    \State $s_t \gets (1 - \gamma) \cdot s_{t-1} + \gamma \cdot \left| \| R_t \| - \| R_{t-1} \| \right|$
\Else \Comment{Burn-in Phase: Determining the Optimal Learning Rate}
    \For{$i = 0$ to $(g-1)$}
        % \State $\hat{x}_{t} \gets x_{t}{R}_{i,t-1}^T$
        \State ${R}_{i,t} \gets {R}_{i,t-1} - \frac{{\eta}_{G}[i]}{d-1} \left[ \left( x_{t} {R}_{i,t-1}^T \right)^T \left( x_{t} {R}_{i,t-1}^T \right) - \operatorname{diag} \left( \left( x_{t} {R}_{i,t-1}^T \right)^T \left( x_{t} {R}_{i,t-1}^T \right) \right) \right] {R}_{i,t-1}$
