        \State ${R}_{n-1} \gets {R}_{i^{\star},n-1}$ , ${\eta} \gets {\eta_G}[i^{\star}]$
    \EndIf
    \State ${s}_t \gets 0$    
\EndIf  
\EndFor
\end{algorithmic}
