\title{Frequency Differences between Clocks on the Earth and the Moon}
\author{Mingyue Zhang, Jürgen Müller}
\affiliation{Institute of Geodesy (IfE), Leibniz University Hannover, Schneiderberg 50, 30167 Hannover, Germany}
