\subsection{Particle Weights}
\label{ss:weights}

The above is performed for each of the $j\le J$ particles, yielding $\{\eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k}^j\}_{j=1}^J$. Each of these has an associated weight, $w_k^j$, to be computed such that the weighted samples approximate the true joint posterior distribution. From e.g., \cite{doucet2009}, it is known that 
\cm{
w_k^j &\propto n_k!u_k^j\,w_{k-1}^j,\\
u_k^j &= p(\bm y_k\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k}^j,\bm y_{1:k-1})\\
&~~\times \frac{p(\eta_k^j,\bm\zeta_k^j,\bm a_k^j\mid \eta_{1:k-1}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})}{q(\eta_k^j,\bm\zeta_k^j,\bm a_k^j\mid \eta_{1:k-1}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k})},
}{\label{eq:weightincdefinition}}
where the $n_k!$ comes from the proportionality, for later convenience. Now define
\cm{
P_k^j &:= p(\bm y_k\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k}^j,\bm y_{1:k-1}),\\
\check P_k^j &:= p(\eta_k^j,\bm\zeta_k^j,\bm a_k^j\mid \eta_{1:k-1}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1}),\\
Q'{}_{\!\!k}^j &:= q(\eta_k^j,\bm\zeta_k^j,\bm a_k^j\mid \eta_{1:k-1}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k}).
}{\label{eq:weightinccomponents}}
Because the sampling scheme is unique -- there is only one way to obtain any given sample, $\{\eta_k,\bm\zeta_k,\bm a_k\}$ -- $Q'{}_{\!\!k}^j$ can be recorded during the sampling process. Specifically, if
\cm{
\!\!\!\!\check Q'{}_{\!\!k}^j &= q(\eta_k^j, \bm a_k^j \mid \eta_{1:k-1}^j, \bm\zeta_{1:k}^j, \bm a_{1:k-1}^j, \bm y_{1:k})\\
&= \prod_{\theta=1}^{\Theta_k} q_A(A_{k\theta}^j \mid \{\mathcal G_{k\theta'}, A_{k\theta'}^j\}_{\theta'=1}^{\theta-1}, \mathcal G_{k\theta},\dots)\\
&~~~~~~~~\times q_{\check A}(\check A_{k\theta}^j\mid \mathcal G_{k\theta}, \bm\zeta_{1:k}^j, \eta_{1:k-1}^j, \bm a_{1:k-1}^j, \bm y_{1:k-1}),
}{\label{eq:qdecomp1}}
is computed when sampling $\{\check A_{k\theta}^j,A_{k\theta}^j\}_{\theta=1}^{\Theta_k}$, then the final proposal probability is
\cm{
Q'{}_{\!\!k}^j &= \check Q'{}_{\!\!k}^j \cdot q(\bm\zeta_k^j \mid \eta_{1:k-1}^j, \bm\zeta_{1:k-1}^j, \bm a_{1:k-1}^j, \bm y_{1:k})\\
&= \check Q'{}_{\!\!k}^j \cdot \prod_{i=1}^{N_{k-1}^j} (1-\psi)^{\check\zeta_{ki}^j(1-\zeta_{ki}^j)}\,\psi^{\zeta_{ki}^j}.
}{\label{eq:qdecomp2}} 
What remains is to compute the likelihood and prior terms, $P_k^j$ and $\check P_k^j$, respectively. Starting with the former, we have
\cm{
P_k^j &= p(\bm y_{k0}^j)\prod_{i=1}^{N_k^j} p(\bm y_{ki}^j\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k}^j,\bm y_{1:k-1},\{\bm y_{k\iota}^j\}_{\iota=1}^{i-1}).
}{\label{eq:weightlikelihood0}}
Each factor in the product regarding pre-existing objects can be expressed as a weighted sum of marginal likelihoods, weighted by $\bm\pi_k^j$. Namely, for $i\in\{1,\dots,N_{k-1}^j\mid \zeta_{ki}^j=1\}$, we have
\cm{
p&(\bm y_{ki}^j\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k}^j,\bm y_{1:k-1},\{\bm y_{k\iota}^j\}_{\iota=1}^{i-1})\\
&= \sum_{c=1}^{N_c} \mathcal N\Big(\bm y_{ki}^j~\big|~(\check{\bm m}_{kic}^j)_1\bm 1_{n_{ki}^j},\\
&~~~~~~~~~~~~~~~~~~~(\check V_{kic}^j)_{1,1}\bm 1_{n_{ki}^j\times n_{ki}^j}+{s'}_{\!\!k}^{j2} I_{n_{ki}^j}\Big)\,\check\pi_{kic}^j.
}{\label{eq:weightlikelihood0.1}}
For the corresponding factors for $i\in\{N_{k-1}^j+1,\dots,N_k^j\}$ one can use the approximation in \eqref{eq:approxliknewtrack} to obtain
\cm{
p(\bm y_{ki}^j&\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k}^j,\bm y_{1:k-1},\{\bm y_{k\iota}^j\}_{\iota=1}^{i-1})\\
&\approx \rho\sqrt{\frac{2\pi{s'}_{\!\!k}^{j2}}{n_{ki}^j}} \mathcal N\left(\bm y_{ki}^j~\big|~\bar y_{ki}^j\bm 1_{n_{ki}^j},{s'}_{\!\!k}^{j2}I_{n_{ki}^j}\right).
}{\label{eq:weightlikelihood0.2}}
