The joint likelihoods can be efficiently computed using \eqref{eq:simplifylikelihood1} and \eqref{eq:simplifylikelihood2}, from Appendix \ref{subapp:uses}. 

Finally, consider
\cm{
n_k!\,\check P_k^j &= n_k!\,p(\bm a_k^j\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})\\
&~~~\times p(\bm\zeta_k^j\mid \eta_{1:k}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})\\
&~~~\times p(\eta_k^j\mid \eta_{1:k-1}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1}).
}{\label{eq:weightprior1}}
Combinatorially, the association mass function evaluated at $\bm a_k^j$ can be computed as the product of the probabilities of having $n_k$ data in total, and these specific (ordered) track associations, marginalised over the Poisson means, $\bm\mu_k^j := (\mu_0,\dots,\mu_{N_k^j})^T$. That is,
\cm{
\!n_k!&p(\bm a_k^j\mid \eta_{1:k}^j,\bm\zeta_{1:k}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})\\
&= n_k!\!\int \text{Poisson}(n_k\mid\check\mu_k^j)\\
&~~~~~~~~\times\prod_{i=0}^{N_k^j} \left(\frac{\mu_i}{\check\mu_k^j}\right)^{n_{ki}^j} \!\!\!\! \text{Gamma}(\mu_i \mid \alpha_{k-1,i}^j, \beta_{k-1,i}^j) \ d\bm\mu_k^j\\
% &= n_k!\!\int \frac{e^{-\check\mu_k^j}}{n_k!}(\check\mu_k^j)^{n_k}\\
% &~~~~~~~~\times\prod_{i=0}^{N_k^j} \left(\frac{\mu_i}{\check\mu_k^j}\right)^{n_{ki}^j}\!\!\!\!\text{Gamma}(\mu_i\mid\alpha_{k-1,i}^j,\beta_{k-1,i}^j)\ d\bm\mu_k^j\\
% &= \!\!\!\!\prod_{\substack{i=0\\i:\zeta_{ki}=1}}^{N_k^j} \frac{{\beta_{k-1,i}^j}^{\alpha_{k-1,i}^j}}{\Gamma(\alpha_{k-1,i}^j)}\\
% &~~~~~~~~\times\int_0^\infty e^{-\mu_i} \mu_i^{n_{ki}^j}\mu_i^{\alpha_{k-1,i}^j-1}e^{-\beta_{k-1,i}^j\mu_i}\ d\mu_i\\
&= \!\!\!\!\prod_{\substack{i=0\\i:\zeta_{ki}=1}}^{N_k^j} \frac{\Gamma(\alpha_{k-1,i}^j+n_{ki}^j)}{\Gamma(\alpha_{k-1,i}^j)}\frac{{\beta_{k-1,i}^j}^{\alpha_{k-1,i}^j}}{(\beta_{k-1,i}^j+1)^{\alpha_{k-1,i}^j+n_{ki}^j}},
}{\label{eq:condassocprob}}
with the sum of the means of active tracks $\check\mu_k^j:=\mu_0 + \sum_{i=1}^{N_k^j}\mu_i\zeta_{ki}^j$, and where we say that $\zeta_{k0}=1$, for notational brevity. It is easily shown that
\cm{
p(\bm\zeta_k^j&\mid \eta_{1:k}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})\\
% &= \prod_{i=1}^{N_{k-1}^j} \text{Bernoulli}(\zeta_{ki}^j\mid \zeta_{k-1,i}^j\psi)\\
&= \prod_{i=1}^{N_{k-1}^j} (1-\psi)^{\zeta_{k-1,i}^j(1-\zeta_{ki}^j)} \, \psi^{\zeta_{ki}^j},
}{\label{eq:weightprior1.1}}
as well as
\cm{
p(\eta_k^j&\mid \eta_{1:k-1}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})\\
% &= \int \text{Poisson}(\eta_k^j\mid \gamma)\,\text{Gamma}(\gamma \mid \varepsilon_{k-1}^j,\xi_{k-1}^j)\ d\gamma\\
&= \frac{\Gamma(\varepsilon_{k-1}^j+\eta_k^j)}{\Gamma(\varepsilon_{k-1}^j)\eta_k^j!}\frac{{\xi_{k-1}^j}^{\varepsilon_{k-1}^j}}{(\xi_{k-1}^j+1)^{\varepsilon_{k-1}^j+\eta_k^j}},
}{\label{eq:weightprior1.2}}
which completes the computation of $n!\check P_k^j$. For convenience, the product term in \eqref{eq:qdecomp2} and the result in \eqref{eq:weightprior1.1} can be combined to
\cm{
\frac1{Q'{}_{\!\!k}^j}&p(\bm\zeta_k^j\mid \eta_{1:k}^j,\bm\zeta_{1:k-1}^j,\bm a_{1:k-1}^j,\bm y_{1:k-1})\\
&~~~~~~~~= \frac1{\check Q'{}_{\!\!k}^j}\prod_{i=1}^{N_{k-1}^j} \frac{(1-\psi)^{\zeta_{k-1,i}^j(1-\zeta_{ki}^j)} \, \psi^{\zeta_{ki}^j}}{(1-\psi)^{\check\zeta_{ki}^j(1-\zeta_{ki}^j)} \, \psi^{\zeta_{ki}^j}}\\
&~~~~~~~~= \frac1{\check Q'{}_{\!\!k}^j}\prod_{i=1}^{N_{k-1}^j} (1-\psi)^{(\zeta_{k-1,i}^j-\check\zeta_{ki}^j)(1-\zeta_{ki}^j)}.
}{\label{eq:weightpriorsimplification}}
