\section{Gaussian Ratios}
\label{app:gaussianratios}

With constant $x$ and $\bar y = \frac1n\sum_{l=1}^ny_l$, the following product of Gaussian ratios is
\cm{
\prod_{l=1}^n\frac{\mathcal N(y_l\mid x,\sigma^2)}{\mathcal N(y_l\mid \bar y,\sigma^2)}
% &= \exp\left\{-\frac1{2\sigma^2}\sum_{l=1}^n\left((y_l-x)^2 - (y_l-\bar y)^2\right)\right\}\\
% &= \exp\left\{-\frac1{2\sigma^2}\sum_{l=1}^n\left(-2xy_l+2\bar yy_l+x^2-\bar y^2\right)\right\}\\
= \exp\left\{-\frac n{2\sigma^2}(\bar y-x)^2\right\}.
}{\label{eq:gaussianratioproduct}}
Multiple such expressions can be combined and simplified, such as in \eqref{eq:finalassoc1.5}. If we have $n_x+n_y=n_z$ as sample sizes, and $n_x\bar x + n_y\bar y = n_z \bar z$ as sample sums, then
\cm{
n_y(\bar z-\bar y)^2 + n_x(\bar z-\bar x)^2
% &= \frac{n_x^2n_y}{n_z^2}(\bar x -\bar y)^2 +\frac{n_xn_y^2}{n_z^2}(\bar y - \bar x)^2\\
% &= \frac{n_xn_y}{n_z}(\bar x-\bar y)^2\\
= \frac{n_xn_y}{n_x+n_y}(\bar x-\bar y)^2.
}{\label{eq:simplifydoubleGratioresult}}

\section{Offset-Diagonal Matrices}
\label{app:offsetdiag}

\subsection{Derivations}
\label{subapp:derivations}

Consider matrices $M,N\in\mathbb R^{\alpha\times\alpha}$ of the form
\cm{
M = AI_\alpha + B\bm 1_{\alpha\times\alpha},\! && N = \frac1AI_\alpha - \frac B{\alpha AB + A^2}\bm 1_{\alpha\times\alpha},
}{\label{eq:twoparameterinverse1}}
% \cm{
% M &= AI_\alpha + B\bm 1_{\alpha\times\alpha}\\
% N &= \frac1AI_\alpha - \frac B{\alpha AB + A^2}\bm 1_{\alpha\times\alpha},
% }{\label{eq:twoparameterinverse1}}
for some $A\ne0$ and $B\ne -\frac A\alpha$.
Using $\delta_{ij}$ as the Kronecker Delta, $N = M^{-1}$ is shown by computing $MN$ element-wise.
\cm{
(MN)_{ij} 
% &= \sum_{k=1}^\alpha M_{ik}N_{kj}\\
&= \sum_{k=1}^\alpha (A\delta_{ik}+B)\left(\frac1A\delta_{kj}-\frac B{\alpha AB + A^2}\right)\\
% &= \sum_{k=1}^\alpha \delta_{ik}\delta_{kj} - \frac B{A+\alpha B}\delta_{ik} + \frac BA\delta_{kj} - \frac{B^2}{\alpha AB + A^2}\\
% &= \delta_{ij} - \frac B{A+\alpha B} + \frac BA - \frac{\alpha B^2}{\alpha AB + A^2}\\
% &= \delta_{ij} - \frac{AB - B(A + \alpha B) + \alpha B^2}{\alpha AB + A^2}\\
&= \delta_{ij}~~~~\blacksquare
}{\label{eq:twoparameterinverse2}}

The determinant of $M_\alpha := M$ is also computable as
\cm{
\det M_\alpha = A^{\alpha-1}(A+\alpha B),
}{\label{eq:twoparameterdet}}
proven by induction. The cases for $\alpha=1,2$ are trivially computed. The determinant $\det M_{\alpha}$ can be expanded as
\cm{
(A+B)\det M_{\alpha-1} + B\sum_{i=1}^{\alpha-1} (-1)^i \det(M_{\alpha-1} - A\bm e_{i\alpha}\bm e_{i\alpha}^T).
}{\label{eq:twoparameterdetproof1}}
By permuting the `all-B' row $i$ to the top (which is $i-1$ row permutations), one has
\cm{
(-1)^{i-1}\!\det(M_{\alpha-1} \!-\! A\bm e_{i\alpha}\bm e_{i\alpha}^T)\! &=\! \det(M_{\alpha-1} \!-\! A\bm e_{i\alpha}\bm e_{i\alpha}^T)\\
&=\! (\det M_{\alpha-1} \!-\! A\det M_{\alpha-2}).
}{\label{eq:allB}}
Hence, $\det M_{\alpha}$ in \eqref{eq:twoparameterdetproof1} becomes the recurrence relation
\cm{
(A-(\alpha-2)B)\det M_{\alpha-1} + (\alpha-1)AB\det M_{\alpha-2}.
}{\label{eq:twoparameterdetproof2}}
Assuming \eqref{eq:twoparameterdet} for all $\alpha'<\alpha$, substitution into \eqref{eq:twoparameterdetproof2} gives the result
% \cm{
% \det M_\alpha &= (A-(\alpha-2)B)\cdot A^{\alpha-2}(A+(\alpha-1)B)\\
% &~~~~+ (\alpha-1)AB\cdot A^{\alpha-3}(A+(\alpha-2)B)\\
% &= A^{\alpha-2}(A^2 + AB - (\alpha-1)(\alpha-2)B^2\\
% &~~~~+ (\alpha-1)AB + (\alpha-1)(\alpha-2)B^2)\\
% &= A^{\alpha-1}(A+\alpha B).
% }{\label{eq:twoparameterdetproof2}}
% Thus, by induction, \eqref{eq:twoparameterdet} holds
$\forall\,M_\alpha\in\mathbb R^{\alpha\times\alpha}$ with $\alpha\ge 1~\blacksquare$.

\subsection{Simplifications Using Offset-Diagonal Matrices}
\label{subapp:uses}

These allow for simplification of typical Gaussian expressions and manipulations frequently seen in this work. Specifically, a typical linear update step may be required if we have
\cm{
\bm y\mid \bm x&\sim \mathcal N((\bm e_{1d}^T\bm x)\bm 1_n,\Sigma I_n),\\
\bm x &\sim\mathcal N(\check{\bm m},\check V),
}{\label{eq:typicalkalmanupdate1}}
where $d=\dim \bm x, n=\dim \bm y$, and $\bm 1_\alpha$ and $I_\alpha$ mean as they did in the main body of work, above. In such a case, the standard Kalman update equations (e.g., \cite{sarkka2013}) yield
\cm{
&~~~~~~~~~~~~~~~~~~~~~~~~~\bm x\mid\bm y \sim \mathcal N(\bm m,V),\\
&\bm m \!=\! \check{\bm m} \!+\! \check V\bm e_{1d}\bm 1_n^T\!\!\left(\Sigma I_n + (\bm e_{1d}^T\check V\bm e_{1d})\bm 1_{n\times n}\right)^{-1}\!\!(\bm y - \bm 1_n\bm e_{1d}^T\check{\bm m}),\\
&V = \check V - \check V\bm e_{1d}\bm 1_n^T\left(\Sigma I_n + (\bm e_{1d}^T\check V\bm e_{1d})\bm 1_{n\times n}\right)^{-1} \bm 1_n\bm e_{1d}^T\check V.
}{\label{eq:typicalkalmanupdate2}}
Acknowledging that $\check V\bm e_{1d} = \check V_{:,1}$ is the first column of $\check V$, and similar results, \eqref{eq:twoparameterinverse1} ultimately implies
\cm{
\check V\bm e_{1d}\bm 1_n^T\left(\Sigma I_n + (\bm e_{1d}^T\check V\bm e_{1d})\bm 1_{n\times n}\right)^{-1}
% &= \check V_{:,1}\bm 1_n^T\left(\frac1\Sigma I_n - \frac{\check V_{1,1}}{n\Sigma\check V_{1,1}+\Sigma^2}\bm 1_{n\times n}\right)\\
% &= \frac1\Sigma \check V_{:,1}\bm 1_n^T - \frac1\Sigma \frac{n\check V_{1,1}}{n\check V_{1,1}+\Sigma}\check V_{:,1}\bm 1_n^T\\
% &= \frac1\Sigma \check V_{:,1}\bm 1_n^T - \frac1\Sigma\left(1 - \frac{\Sigma}{n\check V_{1,1}+\Sigma}\right)\check V_{:,1}\bm 1_n^T\\
= \frac1{n\check V_{1,1}+\Sigma}\check V_{:,1}\bm 1_n^T.
}{\label{eq:typicalkalmanupdate3}}
Then,
\cm{
\bm m = \check{\bm m} + \frac{n(\bar y-\check m_1)}{n\check V_{1,1}+\Sigma}\check V_{:,1},
&& V = \check V - \frac n{n\check V_{1,1}+\Sigma}\check V_{:,1}\check V_{1,:}.
}{\label{eq:typicalkalmanupdate4}}
% \cm{
% \bm m &= \check{\bm m} + \frac1{n\check V_{1,1}+\Sigma}\check V_{:,1}\bm 1_n^T(\bm y - \bm 1_n\check m_1)\\
% &= \check{\bm m} + \frac{n(\bar y-\check m_1)}{n\check V_{1,1}+\Sigma}\check V_{:,1},\\
% V &= \check V - \frac1{n\check V_{1,1}+\Sigma}\check V_{:,1}\bm 1_n^T\bm 1_n\check V_{1,:}\\
% &= \check V - \frac n{n\check V_{1,1}+\Sigma}\check V_{:,1}\check V_{1,:}.
% }{\label{eq:typicalkalmanupdate4}}
These update formulae are significantly more efficient than the general ones in \eqref{eq:typicalkalmanupdate2}, scaling in time as $\mathcal O(n)$ rather than $\mathcal O(n^2)$. If  \eqref{eq:typicalkalmanupdate3} is computed directly %(i.e., not the inverse individually) 
the latter is in fact $\mathcal O(n^3)$.% and the only operation of order $n$ is finding $\bar y$.

Likewise, the computation of the marginal likelihood of the above scenario can be simplified. The marginal likelihood is
\cm{
&\mathcal N(\bm y\mid \check m_1\bm 1_n,\check V_{1,1}\bm 1_{n\times n} + \Sigma I_n)\\
&= (2\pi)^{-\frac{n}2}\left(\det \left(\check V_{1,1}\bm 1_{n\times n} + \Sigma I_n\right)\right)^{-\frac12}\\
&~~\times\exp\left\{\!-\frac12 (\bm y \!-\! \check m_1\bm 1_n)^T\!\!\left(\check V_{1,1}\bm 1_{n\times n} \!+\! \Sigma I_n\right)^{-1}\!\!(\bm y \!-\! \check m_1\bm 1_n)\!\right\}.
}{\label{eq:simplifylikelihood1}}
 With $\overline{(y-\bar y)^2} = \frac 1n \sum_{i=1}^n (y_i-\bar y)^2$, the determinant can be directly computed from \eqref{eq:twoparameterdet} and the matrix inverse of \eqref{eq:twoparameterinverse1} can be used to simplify the (negative) exponent of \eqref{eq:simplifylikelihood1} to
\cm{
&\frac12 (\bm y - \check m_1\bm 1_n)^T\!\!\left[\Sigma^{-1}I_n - \frac{\check V_{1,1}}{\Sigma^2 +n\check V_{1,1}\Sigma}\bm 1_{n\times n}\right]\!\!(\bm y - \check m_1\bm 1_n)\\
% &~~= \frac1{2\Sigma}\sum_{i=1}^n(y_i-\check m_1)^2 + \frac{\check V_{1,1}}{2\Sigma^2+2n\check V_{1,1}\Sigma}\left[\sum_{i=1}^n(y_i-\check m_1)\right]^2\\
% &~~= \frac{n}{2\Sigma}\left(\overline{(y-\bar y)^2}+(\bar y-\check m_1)^2-\frac{n\check V_{1,1}}{\Sigma+n\check V_{1,1}}(\bar y-\check m_1)^2\right)\\
&~~= \frac n2 \left[\frac1{\Sigma}\overline{(y-\bar y)^2} + \frac1{\Sigma+n\check V_{1,1}}(\bar y - \check m_1)^2\right].
}{\label{eq:simplifylikelihood2}}

