\begin{abstract}
We utilise the two principles of decoupling introduced in \cite{LiYang2024} to prove the following conditional result: assuming uniform decoupling for graphs of polynomials in all dimensions with identically zero Gaussian curvature, we can prove decoupling for all smooth hypersurfaces in all dimensions. Moreover, we are able to prove (unconditional) decoupling for all smooth hypersurfaces in $\R^4$ and graphs of homogeneous polynomials in $\R^5$.
\end{abstract}


\maketitle



\section{Introduction}
Fourier decoupling inequalities, first introduced by Wolff in \cite{Wolff2000}, are well established for hypersurfaces with non-zero principal curvatures; see \cite{BD2015, BD2017} and also the textbook \cite{Demeter2020}. As with many other problems in harmonic analysis, the absence of curvature assumptions makes the analysis significantly more subtle.

Building on previous efforts \cite{BDK2019, LiYang, LiYang2023, LiYang2024, LiYang2025, Kemp1, Kemp2, Kemp2024} to develop decoupling inequalities for degenerate hypersurfaces, one of the main results in this paper (see Corollary \ref{cor:conj_holds}) is to reduce the decoupling problem for all smooth hypersurfaces in $\R^{n+1}$ to proving uniform decoupling inequalities for graphs of polynomials $\phi : \R^n \to \R$ with identically zero Gaussian curvature, i.e., $\det D^2\phi \equiv 0$.

The classification of such degenerate polynomials is a challenging algebraic problem in general. However, in dimension $n=3$, a complete classification is available thanks to \cite{SingularHessian2004}. According to their result, any such function $\phi$ either depends on at most two variables or takes a special form that we refer to as \textit{near-affine}. See Lemma \ref{lem:zero_Hessian_paper} below for a precise statement. We then establish decoupling inequalities for near-affine hypersurfaces by using the techniques developed in \cite{LiYang2024}. This leads to an unconditional decoupling result for smooth hypersurfaces in $\R^4$ (see Theorem \ref{thm:almost_affine}), where our method is extended to all dimensions.

Furthermore, applying a similar argument to \cite[Section 12]{LiYang2025}, we are able to prove a uniform decoupling result for homogeneous polynomials of 4 variables (see Corollary \ref{cor:H(4)}).





\subsection{Formulation of decoupling}
We first formulate the decoupling inequalities concerned with this paper. We also recommend that the reader refer to \cite{LiYang2024} for more general formulations of decoupling.

\begin{defn}\label{defn:decoupling}
    Given a compact subset $S\sub \R^n$ and a finite collection $\mathcal R$ of boundedly overlapping parallelograms\footnote{See Section \ref{sec:notation} for the precise definitions.} $R\sub \R^n$. For Lebesgue exponents $p,q\in [2,\infty]$, we define the $\ell^q(L^p)$-decoupling constant $\mathrm{Dec}(S,\mathcal R,p,q)$ to be the smallest constant $\mathrm{Dec}$ such that
    \begin{equation}\label{eqn:defn_decoupling}
        \norm{\sum_{R}f_R}_{L^p(\R^n)} \leq \mathrm{Dec}\,\, (\#\mathcal R)^{\frac{1}{2}-\frac{1}{q}}\norm{\norm{f_R}_{L^p(\R^n)}}_{\ell^q(R\in \mathcal R)}
    \end{equation}
    for all smooth test function $f_R$ Fourier supported on $R\cap S$.

    Given a subset $S\sub \R^n$, we say $S$ can be $\ell^q(L^p)$-decoupled into the parallelograms $R\in \mathcal R$ at the cost of $K$, if $S\sub \cup \mathcal R$ and $\mathrm{Dec}(S,\mathcal R,p,q)\le K$.
\end{defn}


Since we often deal with decoupling for graphs of functions, we introduce the following notation.
\begin{defn}\label{defn:graphical_decoupling}
    Let $\Omega\sub \R^k$ be an open set, $\phi:\Omega\to \R$ be $C^2$. We say that a parallelogram $\Omega_0\sub \Omega$ can be $\phi$-$\ell^q(L^p)$ decoupled into parallelograms $\omega$ at scale $\delta$ (at cost $C$), if $N_\delta^\phi(\Omega_0)$ can be $\ell^q(L^p)$ decoupled into parallelograms equivalent to $N_\delta^\phi(\omega)$ (at cost $C$). %When the exponents $p,q$ are clear from the context, we simply say that $\Omega_0$ can be $\phi$-decoupled into parallelograms $\omega$ at scale $\delta$.
\end{defn}

We now state the following variant of the celebrated decoupling theorem of Bourgain and Demeter \cite{BD2015,BD2017}, which serves as the most fundamental ingredient in this article. See also \cite[Proposition 5.21]{LiYang2024}.
\begin{thm}[Bourgain-Demeter]\label{thm:Bourgain_Demeter}
Let $K\ge 1$ and $\phi(x):[-1,1]^{n-1}\to \R$ be a $C^{3}$ function with $\inf |\det D^2 \phi|\ge K^{-1}$. For every $0<\delta<1$, denote by $\mathcal T_\delta$ a tiling of $[-1,1]^{n-1}$ by cubes $T$ of side length $\delta^{1/2}$.

Then for $2\le p\le \frac{2(n+1)}{n-1}$, $[-1,1]^{n-1}$ can be $\phi$-$\ell^p(L^p)$ decoupled into $\mathcal T_\delta$ at the cost of $C_\eps K^{C_n\eps}\delta^{-\eps}$ for every $\eps>0$, in the sense of Definition \ref{defn:decoupling}, where the constant $C_n$ depends only on $n$, and $C_\eps$ depends only on $\eps,p,\norm{\phi}_{C^3}$. Moreover, this can be upgraded to a $\ell^2(L^p)$ decoupling if $D^2\phi$ is positive (or negative) semidefininte.
\end{thm}

\subsection{Decoupling for polynomials}
In this subsection, we introduce the main decoupling constants that will be studied in this paper.

Fix $n,d\ge 1$. We denote by $\mathcal P_{n,d}$ the collection of all $n$-variate polynomials $\phi$ of degree at most $d$, such that $\max_{[-1,1]^n}|\phi|\le 1$. Equivalently, the coefficients of $\phi$ are $\lesssim_{n,d} 1$.

For a parallelogram $R\sub \R^n$, its smallest dimension is referred to as {\it width}. See Section \ref{sec:notation} for the precise definitions.

\begin{defn}\label{defn:graphical_polynomial_decoupling}
    Let $n,d\ge 1$. We say that uniform decoupling holds for $\mathcal P_{n,d}$, or $U(n)$ holds, if for every $\phi\in \mathcal P_{n,d}$, $\delta\ll_{n,d} 1$ and $\eps\in (0,1]$, there exists a covering $\mathcal R_\delta=\mathcal R_\delta(\phi,\eps)$ of $[-1,1]^{n}$ by 
    parallelograms $R_\delta\sub [-2,2]^n$, such that the following holds:
    \begin{enumerate}
        \item \label{item:U_01} Each $R\in\mathcal R_\delta$ has width at least $\delta$, and $\mathcal R_\delta$ has bounded overlap. In particular, $\#\mathcal R_\delta\lesssim \delta^{-n}$.
        \item Every $R_\delta\in \mathcal R_\delta$ in $(\phi,\delta)$-flat.
        \item For every $2\le p\le \frac{2(n+2)}{n}$, $[-1,1]^{n}$ can be $\phi$-$\ell^p(L^p)$ decoupled into $\mathcal R_\delta$ at scale $\delta$ at cost $\lesssim \delta^{-\eps}$ as in Definition \ref{defn:graphical_decoupling}.
    \end{enumerate}    
    All implicit constants and the overlap function in this definition are allowed to depend on $n,d,\eps,p$,  but not on $\delta$ or the coefficients of $\phi$.
\end{defn}

\begin{defn}\label{defn:graphical_polynomial_decoupling_zero}
    Let $n,d\ge 1$. We say that (uniform) degenerate decoupling holds for $\mathcal P_{n,d}$, or $Z(n)$ holds, if the same statement of Definition \ref{defn:graphical_polynomial_decoupling} holds, except that we additionally have $\det D^2 \phi\equiv 0$.
\end{defn}



\begin{defn}\label{defn:sublevel_set_decoupling}
    Let $n,d\ge 1$. We say that (uniform) sublevel set decoupling holds for $\mathcal P_{n,d}$, or $S(n)$ holds, if for every $\phi\in \mathcal P_{n,d}$, $\delta\ll_{n,d} 1$ and $\eps\in (0,1]$, there exists a covering $\mathcal S_\delta$ of the sublevel set $\{x\in [-1,1]^n:|\phi(x)|<\delta\}$ by parallelograms $S_\delta\sub [-2,2]^n$, such that the following holds:
    \begin{enumerate}
        \item Each $S_\delta\in\mathcal S_\delta$ width at least $\delta$, and $\mathcal S_\delta$ has bounded overlap. In particular, $\#\mathcal S_\delta\lesssim \delta^{-n}$.
        \item $|\phi(x)|\lesssim \delta$ for every $x\in S_\delta\in \mathcal S_\delta$.
        \item For every $2\le p\le \frac{2(n+1)}{n-1}$, the sublevel set $\{x\in [-1,1]^n:|\phi(x)|\le\delta\}$ can be $\ell^p(L^p)$ decoupled into $\mathcal S_\delta$ at cost $\lesssim \delta^{-\eps}$ as in Definition \ref{defn:decoupling}.
    \end{enumerate}
    All implicit constants in this definition are allowed to depend on $n,d,\eps,p$, but not on $\delta$ or the coefficients of $\phi$.
\end{defn}
From the definitions, we see that $U(1)$ holds by \cite{Yang2} (where we can even show that $R_\delta$ has length at least $\delta^{1/2}$), and $U(2)$ holds by \cite[Theorem 5.22]{LiYang2024}. Hence $Z(1)$ and $Z(2)$ hold. Also, $S(1)$ follows from the fundamental theorem of algebra (together with a simple trick called $\delta$-thickening, see the proof of Proposition \ref{prop:delta_thickening} below), and $S(2)$ follows from \cite[Theorem 5.23]{LiYang2024}. The general case remains a conjecture.
\begin{conj}\label{conj:decoupling}
    The statements $U(n)$, $Z(n)$ and $S(n)$ hold for all $n\ge 1$.
\end{conj}
By the Taylor expansion in \cite[Section 2]{LiYang2023}, we have the following result.
\begin{prop}
    If $U(n)$ holds, then decoupling holds for any smooth functions $\phi$ of $n$ variables. More precisely, the same statement of Definition \ref{defn:graphical_polynomial_decoupling} holds for $\phi$, except that the implicit constants are allowed to depend on $\eps,p$ and the $C^{[1/\eps]}$ norm of $\phi$.
\end{prop}

\subsection{Main results}
We now proceed to state the main decoupling theorems in this paper. We start with two trivial observations.
\begin{lem}\label{lem:monotonicity}
    For $n\ge 1$, $U(n+1)\implies U(n)$, $Z(n+1)\implies Z(n)$ and $S(n+1)\implies S(n)$.
\end{lem}

\begin{lem}\label{lem:trivial_implications}
For $n\ge 1$, $S(n+1)\implies U(n)\implies Z(n)$.
\end{lem}
Note that $S(n+1)\implies U(n)$ follows from taking $\Phi(x,y)=y-\phi(x)$ for a given $\phi\in \mathcal P_{n,d}$.
%\begin{proof}
    %The first implication follows from taking $\Phi(x,y)=y-\phi(x)$ for a given $\phi\in \mathcal P_{n,d}$. The second implication is trivial.
%\end{proof}

Now we come to the nontrivial relations between these decoupling constants.
\begin{thm}\label{thm:main_U_imply_S}
    For $n\ge 1$, $U(n)$ implies $S(n+1)$.
\end{thm}
Indeed, in \cite{LiYang2023}, $S(2)$ (but without the width lower bound) is proved based on an iterative method using $U(1)$. This turns out to be true in all dimensions. 

Another main result proved in \cite{LiYang2023} is $U(2)$, which is proved by applying $Z(2)$ and establishing $S(2)$ (all without the width lower bound). Another main theorem of this paper is to prove that it is true in all dimensions.
\begin{thm}\label{thm:main_SZ_imply_U}
    For $n\ge 1$, $S(n)$ and $Z(n)$ together imply $U(n)$.
\end{thm}
