Combining Theorems \ref{thm:main_U_imply_S} and \ref{thm:main_SZ_imply_U}, we have the following corollary.
\begin{cor}\label{cor:conj_holds}
    For $n\ge 2$, $U(n-1)$ and $Z(n)$ together imply $U(n)$. As a result, if $Z(n)$ holds for all $n\ge 1$, then Conjecture \ref{conj:decoupling} holds.
\end{cor}


This means that in general, studying Conjecture \ref{conj:decoupling} is equivalent to studying decoupling for all polynomials $\phi\in \mathcal P_{n,d}$ satisfying $\det D^2\phi\equiv 0$. A natural approach is to classify all these polynomials, but it turns out to be rather difficult in higher dimensions, since it is connected to the Jacobi conjecture in algebraic geometry \cite{SingularHessian2004}. Nevertheless, in this paper, using the partial results established in \cite{SingularHessian2004}, we establish the following theorem.
\begin{thm}\label{thm:trivariate_decoupling}
The statement $Z(3)$ holds. In fact, the range of $p$ can be enlarged to $2\le p\le 4$.
\end{thm}
As a corollary, we obtain a uniform decoupling result for all trivariate polynomials, and a sublevel set decoupling for all $4$-variate polynomials.
\begin{cor}\label{cor:trivariate_decoupling}
    The statements $U(3)$ and $S(4)$ hold.
\end{cor}
The proof of $Z(3)$ uses the following key fact from \cite{SingularHessian2004}:
\begin{lem}\label{lem:zero_Hessian_paper}
    If $\phi(x_1,x_2,x_3)$ is a trivariate polynomial without affine terms that satisfies $\det D^2\phi\equiv 0$, then either of the following statements is correct:
    \begin{enumerate}
        \item There exists an affine bijection $\Xi$ on $\R^3$ such that $\phi\circ \Xi$ depends on $x_1,x_2$ only.
        \item There exists an affine bijection $\Xi$ on $\R^3$ such that $\phi\circ \Xi$ is of the form $A_1(x_1)+A_2(x_1)x_2+A_3(x_1)x_3$, where $A_1,A_2,A_3$ are univariate polynomials.
    \end{enumerate}
\end{lem}
The complete classification of polynomials $\phi\in \mathcal P_{n,d}$ with $\det D^2\phi\equiv 0$ is open for $n\ge 4$ (see \cite{SingularHessian2004,SingularHessian2018}). As a result, $Z(4)$ is open to us.


See Figure \ref{fig:implications}. By the main results of this paper, every statement to the left of (and including) $S(4)$ is known. Compared with \cite{LiYang2023}, the new results are $S(3),Z(3),U(3),S(4)$.


\subsection{Decoupling for homogeneous polynomials}
We can get better results if we restrict ourselves to the family of homogeneous polynomials.
\begin{defn}
    Let $n,d\ge 1$. We say that (uniform) homogeneous decoupling holds for $\mathcal P_{n,d}$, or $H(n)$ holds, if the same statement of Definition \ref{defn:graphical_polynomial_decoupling} holds, except that we additionally assume $\phi$ is homogeneous.
\end{defn}
Morally, we will show that $U(n)$ implies $H(n+1)$, namely, uniform decoupling for $n$-variate polynomials implies uniform decoupling for homogeneous $(n+1)$-variate polynomials. However, due to technical reasons, we can only prove a slightly weaker version. We first state an analogous assumption to $Z(n)$.
\begin{defn}\label{defn:IZ(n)}
    Fix $\eta:[-1,1]\to \R$ be $C^2$ and such that $\eta''\ne 0$. We say that $IZ(n)$ holds, if for every $\phi\in \mathcal P_{n,d}$ with $\det D^2 \phi\equiv 0$, $\delta\ll_{n,d} 1$ and $\eps\in (0,1]$, there exists a covering $\mathcal R_\delta$ of $[-1,1]^{n}$ by 
    parallelograms $R_\delta\sub [-2,2]^n$, such that the following holds:
    \begin{enumerate}
        \item Each $R\in\mathcal R_\delta$ has width at least $\delta$, and $\mathcal R_\delta$ has bounded overlap. In particular, $\#\mathcal R_\delta\lesssim \delta^{-n}$.
        \item Every $R_\delta\in \mathcal R_\delta$ in $(\phi,\delta)$-flat.
        \item Denote $\psi(x,y)=\eta(x)+\phi(y)$. For every $2\le p\le \frac{2(n+2)}{n}$, $[-1,1]^{n+1}$ can be $\psi$-$\ell^p(L^p)$ decoupled into 
        \begin{equation*}
            \{I\times R:I\in \mathcal I_\delta,R\in \mathcal R_\delta\}
        \end{equation*}
        at scale $\delta$ at cost $\lesssim \delta^{-\eps}$ as in Definition \ref{defn:graphical_decoupling}, where $\mathcal I_\delta$ denotes the tiling of $[-1,1]$ by intervals of length $\delta^{1/2}$.
    \end{enumerate}    
    All implicit constants and the overlap function in this definition are allowed to depend on $n,d,\eps,p,\norm{\eta}_{C^2},\inf |\eta''| $, but not on $\delta$ or the coefficients of $\phi$. 
\end{defn}
In general, proving $IZ(n)$ would require us to apply analogous properties to Lemma \ref{lem:zero_Hessian_paper}. In particular, we are able to prove the following proposition.
\begin{prop}\label{prop:IZ(3)}
    The statement $IZ(3)$ holds.
\end{prop}
The main theorem in this paper concerning decouping for homogeneous polynomials is as follows.
\begin{thm}\label{thm:decoupling_homo}
    For $n\ge 1$, $U(n)$ and $IZ(n)$ together imply $H(n+1)$. 
\end{thm}
We will outline the proof of both Proposition \ref{prop:IZ(3)} and Theorem \ref{thm:decoupling_homo} in Section \ref{sec:homo_highdim}, using a similar argument to \cite[Section 12]{LiYang2025}. Indeed, in \cite{LiYang2025}, we proved $H(3)$ based on the two principles introduced in \cite{LiYang2023}, a general sublevel set decoupling which requires $U(1)$, and a uniform bivariate decoupling for ``pseudo-polynomials" which requires $U(2)$. Also, $IZ(2)$ follows from \cite[Proposition 13.1]{LiYang2025}.


\begin{cor}\label{cor:H(4)}
    The statement $H(4)$ holds.
\end{cor}
\begin{proof}
    It follows from Proposition \ref{prop:IZ(3)}, Corollary \ref{cor:trivariate_decoupling} and Theorem \ref{thm:decoupling_homo}.
\end{proof}


\subsection{Outline of the paper} 
In Section \ref{sec:sub_parallelogram} we deal with a technical issue of decoupling a sub-parallelogram. In Section \ref{sec:degeneracy_locating}  we invoke a special case of the degeneracy locating principle established in \cite{LiYang2024}. In Section \ref{sec:S_imply_U} we prove Theorem \ref{thm:main_SZ_imply_U}. In Section \ref{sec:almost_affine}, we prove Theorem \ref{thm:trivariate_decoupling}. In Section \ref{sec:U_imply_S}, we prove Theorem \ref{thm:main_U_imply_S}. In Section \ref{sec:homo_highdim}, we prove Proposition \ref{prop:IZ(3)} and Theorem \ref{thm:decoupling_homo}.





\subsection{Notation}\label{sec:notation}

We introduce some notation that will be used in this paper. 

\begin{enumerate}
    \item \label{item:big_O} We use the standard notation $a=O_M(b)$, or $|a|\lesssim_M b$ to mean that there is a constant $C$ depending on some parameter $M$, such that $|a|\leq Cb$. When the dependence on the parameter $M$ is unimportant, we may simply write $a=O(b)$ or $|a|\lesssim b$. Similarly, we define $\gtrsim$ and $\sim$.

    %\noindent {\bf In particular, for the rest of this paper, unless otherwise specified, we often omit the dependence of constants on the dimension $n$, the polynomial degree $d$ and the decoupling exponent $p$.}

\item Given a subset $M\sub \R^n$, we define the $\delta$-neighbourhood $N_\delta(M)\sub \R^n$ to be
    \begin{equation*}
N_\delta(M) := \{ x + c: x \in M, c\in \R^n,|c|<\delta\}.
\end{equation*}

    \item Given a continuous function $\phi:\Omega\sub \R^n\to \R$, we define the $\delta$-vertical neighbourhood $N^\phi_\delta(\Omega)\sub \R^{n+1}$ by    
    \begin{equation*}
N_\delta^\phi(\Omega): =\{ (x , \phi(x) + c): x \in \Omega, c \in [-\delta,\delta]\}.
\end{equation*}




\item We denote by $\mathcal P_{n,d}$ the collection of all $n$-variate real polynomials $\phi$ of degree at most $d$, such that $\max_{[-1,1]^n}|\phi(x)|\le 1$.





\end{enumerate}




\subsubsection{Notation on parallelograms}\label{sec:equivalence_objects}
Decoupling inequalities are formulated using parallelograms in $\R^n$. To deal with technicalities, it is crucial that we make clear some fundamental geometric concepts.

\begin{enumerate}
    \item A parallelogram $R\sub \R^n$ is defined to be a set of the form
    \begin{equation*}
        \{x+b\in \R^n:|x\cdot u_i|\le l_i\},
    \end{equation*}
    where $\{u_i:1\le i\le n\}$ is a basis of $\R^n$ consisting of unit vectors, $b\in \R^n$ and $l_i\ge 0$. If $\{u_i:1\le i\le n\}$ is in addition orthogonal, we say that $R$ is a rectangle. Unless otherwise specified, we always assume a parallelogram in $\R^n$ has positive $n$-volume, namely, $l_i>0$ for all $1\le i\le n$. We say that two parallelograms are disjoint if their interiors are disjoint. The {\it width} of a parallelogram is defined by its shortest dimension, namely, $\min_i l_i$.

    \item Let $R\sub \R^n$ be a parallelogram. We denote by $\lambda_R$ an affine bijection from $[-1,1]^n$ to $R$. (There is more than one choice of $\lambda_R$, but in our paper, any such a choice will work identically, since in decoupling inequalities, the orientations of such affine bijections do not make any difference.) We say that an affine bijection $\lambda$ on $\R^n$ is {\it bounded} by $C$ if $\lambda x=Ax+b$ where all entries of $A,b$ are bounded by $C$. 

    \item Unless otherwise specified, for a parallelogram $S\sub \R^n$ and $C>0$, we denote by $CS$ the concentric dilation of $S$ by a factor of $C$. Given $t\in \R^n$, we denote $S+t=\{s+t:s\in S\}$. Note that in this notation, we have $C(S+t)=CS+t$.

\item Given a subset $S\sub \R^n$, a parallelogram $R\sub \R^n$ and $C\ge 1$, we say that $S,R$ are $C$-equivalent if $C^{-1}R\sub S\sub CR$.  If the constant $C$ is unimportant, we simply say that $S$ is equivalent to $R$, or that $S$ is an {\it almost parallelogram}.

    \item For $0<\delta<1$, by a {\it tiling} of a parallelogram $R\sub \R^n$ by cubes of side length $\delta$, we mean a covering $\mathcal T$ of $R$ by translated copies $T$ of a cube of side length $\delta$, such that different $T$ and $T'$ from $\mathcal T$ have disjoint interiors, and that $T\sub 2R$.  



    \item By the John ellipsoid theorem \cite{John}, every convex body in $\R^n$ is $C_n$-equivalent to a rectangle in $\R^n$, for some dimensional constant $C_n$. For this reason and in view of the enlarged overlap introduced right below, we often do not distinguish rectangles from parallelograms. 



\end{enumerate}




\subsubsection{Enlarged overlap}

\begin{defn}\label{defn:enlarged_overlap}
By an {\it overlap function} we mean an increasing function $B:[1,\infty)\to [1,\infty)$. Given a finite family $\mathcal R$ of parallelograms in $\R^n$ and an overlap function $B$, we say $\mathcal R$ is $B$-overlapping, or $B$ is an overlap function of $\mathcal R$, if for every $\mu\ge 1$ we have
    \begin{equation*}
        \sum_{R\in \mathcal R}1_{\mu R}\le B(\mu).
    \end{equation*}
\end{defn}
Given $\delta>0$ and a family $\mathcal R$ of parallelograms depending on $\delta$ (and other factors such as $\eps>0$). We say that $\mathcal R$ is boundedly overlapping, if its overlap function $B$ does not depend on $\delta$ (but it might depend on $\eps$ and other factors).

