\section{Geodesic stretch} \label{section, GeodesicStretch}
\subsection{Basics on geodesic stretch} \label{subsection, BasicGeodesicStretch}
\hfill\\
Throughout this note, let $M$ be a closed $n$-dimensional oriented manifold admitting a Riemannian metric $g$ of negative sectional curvature. We will denote $\widetilde{M}$ as the universal covering of $M$ and $\Gamma$ the group of covering transformations on $\widetilde{M}$, identified with $\pi_1(M)$.
To simplify notations, we will always denote the lift of a metric $g$ on $\widetilde{M}$ as $g$ as well. 

Fix two Riemannian metrics $g_1$ and $g_2$ on $M$.  For each vector $v$
in the unit tangent bundle $S^{g_1}M$ of $g_1$, let us
 consider the arclength parametrized geodesic $c^{g_1}_v(s)$ on $M$ with respect to the Riemannian metric $g_1$, with initial condition
$\dot{c}^{g_1}_v(0) = v$.  We denote $\widetilde{c}^{g_1}_v(s)$ to be one of the lifts of $c^{g_1}_v(s)$ on the universal cover $(\widetilde{M},g_1)$. Then for each $t\in \R$, we let
 $$a(v,t) := d_{g_2}(\widetilde{c}^{g_1}_v(0),\widetilde{c}^{g_1}_v(t)) $$ be the $g_2$-distance of the endpoints of the
segment $\{\widetilde{c}^{g_1}_v(s),
0 \le s \le t \}$ with respect to $g_1$.

 It is an easy consequence of the triangle 
inequality that
the map $a(v,t)$ is a subadditive cocycle for
the geodesic flow $\phi^{g_1}$ induced by the metric $g_1$, i.e.
for all $v \in S^{g_1}M$ and 
$t_1, t_2 \in \R$,
$$a(v, t_1 + t_2) \le a(v, t_1 ) + a(\phi^{g_1}_{t_1} v, t_2).$$


Let us denote the space of $\phi^{g_1}_t$-invariant measures as $\mathcal{M} (\phi^{g_1})$ and the subset of $\phi^{g_1}_t$-invariant probability measures as $\mathcal{M}^1 (\phi^{g_1})$.   Suppose $m$ is an element in $\mathcal{M}^1 (\phi^{g_1})$. Then the subadditive ergodic 
theorem \cite[Theorem 10.1]{Wa82} implies that the limit
$$
I_m(g_1, g_2, v) := \lim_{t \to \infty} \frac{a(v,t)}{t}
$$
exists for $m$ almost every $v \in S^{g_1}M$ and defines a 
$m$-integrable function on $S^{g_1}M$ invariant under the geodesic
flow $\phi^{g_1}$. Furthermore, we have:
%\begin{eqnarray*}
$$
\int_{S^{g_1}M} I_m (g_1, g_2, v) d m  =  \lim_{t \to \infty} \frac{1}{t} \int_{S^{g_1}M}
a(v,t) dm = \inf_{t > 0} \frac{1}{t} \int_{S^{g_1}M} a(v,t) dm\;.
%\end{eqnarray*}
$$
We refer to \cite{Kn95} for details.
\begin{definition}
Let $g_1, g_2$ be two Riemannian metrics on $M$ and let $m$ be an element in $\mathcal{M}^1 (\phi^{g_1})$. Then 
$$
I_m (g_1, g_2):= \int_{S^{g_1}M} I_{m}(g_1, g_2, v) d m(v)
$$
is called the \emph{geodesic stretch} of $g_1, g_2$ with respect to $m$. 
\end{definition}
Now we want to calculate the geodesic stretch of closed Riemannian manifolds  of negative curvature. We denote $R^-(M)$ to be the set of smooth negatively curved Riemannian metrics on $M$. Since for two different metrics $g_1,g_2$ in $R^-(M)$, the visual boundary $\partial_{g_1} \widetilde M$ is identified with the visual boundary of $\partial_{g_2} \widetilde M$, we denote the boundary simply by $\partial\widetilde M$. Moreover, this identification is H\"older continuous with respect to the visual metrics induced by both $g_1$ and $g_2$, the boundary $\partial\widetilde M$ has a natural H\"older structure (\cite[Chapter III.H.3]{BH99}).

For $\xi \in  \partial \widetilde M$ and $x_0 \in \widetilde M$, the Busemann function $x \mapsto b_\xi^g(x_0, x)$ is defined by
$$
 b_\xi^g(x_0, x) = \lim_{z \to \xi} d_g(x_0, z) - d_g(x,z).
$$
The Busemann functions are $C^2$ convex function. Furthermore, the following relations hold:
\begin{enumerate} \label{busemann cocycle}
    \item  \label{prop1bus} $b_\xi^g(x_0, x) =  b_\xi^g(x_0, x_1)+  b_\xi^g(x_1, x) \quad \quad $ (\text{cocycle property})
\item \label{prop2bus} $b_{\gamma \xi}^g(\gamma x_0, \gamma x )=  b_\xi^g(x_0, x) $ \; \text{for all}  \; $\gamma \in \Gamma$ \quad ($\Gamma $ \text{invariance})
\end{enumerate}
We call the map $\partial\widetilde M \times \widetilde M \times  \widetilde M  \to \R $ with $(\xi, x_0,x_1) \mapsto 
b_\xi^g(x_0, x_1)$ the Busemann cocycle. Besides being $C^2$ in the variables $x_0$ and $x_1$, the map is H\"older 
in $\xi$ with respect to the visual metric (\cite[Section 2.6]{Bou95}).

We define $B^g(x, \xi) : = \grad_{x} b_\xi^g(x_0,x)$.  This is well defined by property (\ref{prop1bus}).
Furthermore, for $v \in S^g \widetilde M $, we set
$v^g_\pm = \widetilde{c}^{g}_v(\pm \infty)  \in \partial \widetilde M$, where $\widetilde{c}^{g}_v(s)$ is the $g$-arclength parameterized geodesic on $\widetilde{M}$, with initial condition
$\dot{\widetilde{c}}^g_v(0) = v$. We write $\pi: T \widetilde M \to \widetilde M$ and $\pi: T  M \to M$ as the canonical projections from the tangent bundle to its base.

The set 
$$
\partial^{(2)} \widetilde M = \partial \widetilde M \times \partial \widetilde M \setminus \diag
$$
corresponds to the set of unparametrized oriented geodesics on $\widetilde M$ for any metric of negative curvature on $M$.  
Given $g \in R^-(M) $ and $p_0$ a fixed reference point in $\widetilde M $, the map $H^g_{p_0}: S^g \widetilde M \to  \partial^{(2)} \widetilde M \times \R$ given by
\begin{equation} \label{Hopfmap}
H^g_{p_0}(v) = (v^g_-, v^g_+,  b_{ v^g_+}^{\scriptscriptstyle g}(p_0, \pi (v)))
\end{equation}
is a H\"older homeomorphism which is called the \emph{Hopf parametrization} of $S^g \widetilde M$ (see also \cite{ST21}).
\begin{lemma}
We have  for all $v \in S^g \widetilde M $ and $t\in \R$,
$$
H^g_{p_0}( \phi_t^gv) =  (v^g_-, v^g_+,  b_{v^g_+}^{\scriptscriptstyle g}(p_0, \pi (v)) +t),
$$
and for $ \gamma \in \Gamma$,
$$
H^g_{p_0}( \gamma_* v) = \gamma_H H^g_{p_0}(v),
$$
where the action of $\Gamma$ on $\partial^{(2)} \widetilde M \times \R$ is defined by
$$
\gamma_H (\xi_-, \xi_+, t) = ( \gamma \xi_-, \ \gamma \xi_+, \ t+ b_{\xi_+}^{g}(\gamma^{-1}p_0,  p_0) ).
$$
\end{lemma}

\begin{lemma}\label{lem,Busem-distance}
Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$.
Then there is a constant $k =k(g_1, g_2)$ such that for all $v \in S^{g_1} \widetilde M$ and $\xi = v^{g_1}_+$,
$$
| d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v)) -b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))| \le k.
$$
\end{lemma}
\begin{proof}
For  $v \in S^{g_1} \widetilde M$, consider $w \in S^{g_2} \widetilde M$ given by  $w = B^{g_2}(\pi(v), \xi)$. Since $(\widetilde M,g_1)$ and $(\widetilde M,g_2)$ are quasi-isometric, by the Morse Lemma (\cite{Mo24}), there exists a constant $R_1=R_1(g_1,g_2)>0$ such that for each $t \ge 0$, we can find some $s(t) \in \R$ and
$$
d_{g_2}( \pi (\phi_t^{g_1} v ),\pi (\phi_{s(t)}^{g_2} w )) \le R_1(g_1, g_2). 
$$
This implies that
$$
|d_{g_2}( \pi (v), \pi (\phi_t^{g_1} v )) -d_{g_2}( \pi (v), \pi (\phi_{s(t)}^{g_2} w ))| 
\le R_1(g_1,g_2),
$$
and
$$
|b^{g_2}_\xi( \pi (v), \pi (\phi_t^{g_1} v )) -b^{g_2}_\xi( \pi (v), \pi (\phi_{s(t)}^{g_2} w ))|
 \le R_1(g_1,g_2),
$$
where the first inequality follows from the triangle inequality and the second from the fact that Busemann functions are $1$-Lipschitz.
Hence
\begin{equation*}
\begin{split}
 & | d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v))  -b_\xi^{g_2}(\pi(v),  \pi (\phi_t^{g_1} v))| \\ 
 = &
   | d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v)) - d_{g_2}( \pi (v), \pi (\phi_{s(t)}^{g_2} w ))
  +  d_{g_2} ( \pi (v), \pi (\phi_{s(t)}^{g_2} w)\\
 &  - b_\xi^{g_2}(\pi(v),  \pi(\phi_{s(t)}^{g_2} w))
  +b_\xi^{g_2}(\pi(v),  \pi(\phi_{s(t)}^{g_2} w)) -b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))| \\
  \le  &
 | d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v)) - d_{g_2}( \pi (v), \pi (\phi_{s(t)}^{g_2} w ))| +|b_\xi^{g_2}(\pi(v),  \pi(\phi_{s(t)}^{g_2} w)) -b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))|\\
  \le & 2 R_1(g_1, g_2) =: k(g_1,g_2).
\end{split}
\end{equation*}
\end{proof}


\begin{corollary} \label{corollary, GeodesicStretchBusemannFunction} 
Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$
and  let $m$ be a measure in $\mathcal{M}^1 (\phi^{g_1})$. Then for $m$-almost  all $v \in  S^{g_1}  M$, any of its lifts $\widetilde{v} \in  S^{g_1} \widetilde M$ satisfies 
$$
\lim_{t \to \infty} \frac{1}{t}d_{g_2} (\pi (\widetilde{v}), \pi(\phi_t^{g_1} \widetilde{v})) = \lim_{t \to \infty} \frac{1}{t}\int_0^t g_2(B^{g_2}(\pi (\phi_s^{g_1}\widetilde{v}), \widetilde{v}^{g_1}_+), \phi_s^{g_1}\widetilde{v})ds.
$$
Furthermore, 
$$
I_m(g_1,g_2) = \int_{S^{g_1}M} g_2(B^{g_2}(\pi (\widetilde{v}), \widetilde{v}^{g_1}_+), \widetilde{v}) dm.
$$
\end{corollary}
\begin{proof}
For $m$-almost  all $v \in  S^{g_1}  M$ and any lift $\widetilde{v} \in  S^{g_1} \widetilde M$ of $v$ the limit $\lim\limits_{t \to \infty} \frac{1}{t}d_{g_2} (\pi (\widetilde{v}), \pi(\phi_t^{g_1} \widetilde{v}))$ exists and is equal to $I_m(g_1, g_2, v)$. If $\xi = \widetilde{v}^{g_1}_+$, we obtain by Lemma \ref{lem,Busem-distance},
\begin{equation*}
\begin{split}
 I_m(g_1, g_2, v) =&\lim_{t \to \infty}  \frac{1}{t}d_{g_2} (\pi (\widetilde{v}), \pi(\phi_t^{g_1} \widetilde{v})) \\
=&\lim_{t \to \infty}  \frac{1}{t} b_\xi^{g_2}(\pi (\widetilde{v}),  \pi(\phi_t^{g_1} \widetilde{v}))\\
=&\lim_{t \to \infty}  \frac{1}{t} \int_0^t g_2(\grad_{\pi (\phi_s^{
 g_1}\widetilde{v})} b_\xi^{g_2}(\pi (\widetilde{v}), \pi (\phi_s^{g_1}\widetilde{v})), \phi_s^{g_1}\widetilde{v})ds\\
=&\lim_{t \to \infty}  \frac{1}{t} \int_0^t g_2(B^{g_2}(\pi (\phi_s^{g_1}\widetilde{v}),   \widetilde{v}^{g_1}_+), \phi_s^{g_1}\widetilde{v})ds.
\end{split}
\end{equation*}
By the Birkhoff ergodic theorem for invariant measures (\cite[Theorem 1.14]{Wa82}), we obtain
\begin{equation*}
\begin{split}
I_m(g_1,g_2) &=    \int_{S^{g_1}M} \lim_{t \to \infty} \frac{1}{t}d_{g_2} (\pi (\widetilde{v}), \pi(\phi_t^{g_1} \widetilde{v})) dm(v)\\
&= \int_{S^{g_1}M}  \lim_{t \to \infty} \frac{1}{t} \int_0^t g_2(B^{g_2}(\pi (\phi_s^{g_1}\widetilde{v}),   \widetilde{v}^{g_1}_+ ), \phi_s^{g_1}\widetilde{v})ds dm(v) \\
&= \int_{S^{g_1}M} g_2(B^{g_2}(\pi (\widetilde{v}), \widetilde{v}^{g_1}_+ ), \widetilde{v}) dm(v).
\end{split}
\end{equation*}
\end{proof}






\subsection{Orbit equivalence of geodesic flows on manifolds of negative curvature}
\hfill\\
In this subsection, we construct an orbit equivalence between geodesic flows with respect to different metrics in $R^-(M)$ which will be useful in the sequel. This construction is also in \cite{ST21}.

\begin{lemma} \label{lem:conj}

Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$.
Consider the map $\Psi_{g_1, g_2}: S^{g_1}\widetilde M  \to  S^{g_2}\widetilde M $ defined by $\Psi_{g_1, g_2}(v)  =w$ where 
$w \in  S^{g_2}\widetilde M $ is the unique vector with $w^{g_2}_+ = v^{g_1}_+$ and  $w^{g_2}_-= v^{g_1}_-$ and 
$b^{g_2}_{v^{g_1}_+}( \pi(v), \pi(w)) =0$. Then $\Psi_{g_1, g_2}$ is a H\"older continuous surjective map with
$$
\phi^{g_2}_{\tau(v,t)}(\Psi_{g_1, g_2}(v)) = \Psi_{g_1, g_2}( \phi_t^{g_1}(v)),
$$
where 
$$
\tau(v,t) = b^{g_2}_{v^{g_1}_+} ( \pi(v), \pi(\phi_t^{g_1}(v)) ) =\int_{0}^t g_2( B^{g_2}(\pi \phi_s^{g_1}v, v^{g_1}_+) , \phi_s^{g_1}v) ds,
$$
 for all $v \in S^{g_1}\widetilde M $. Furthermore, for all $\gamma \in \Gamma$
we have 
$$
\gamma_{\ast}\Psi_{g_1, g_2}(v) =\Psi_{g_1, g_2} (\gamma_{\ast}v),
$$ and 
${\tau(\gamma_{\ast}v,t)} = \tau(v,t)$. Therefore, the map $\Psi_{g_1, g_2}$ decends to an orbit equivalence between the geodesic flows on the quotients $S^{g_1}M$ and $S^{g_2}M$.\\ 
Moreover
$$
\Psi_{g_2, g_1} \circ \Psi_{g_1, g_2}(v) =  \phi_{t(v)}^{g_1}(v)
$$
for all $v  \in S^{g_1}\widetilde M$ where $t(v) = b^{g_1}_{v^{g_1}_+}( \pi(v), \pi( \Psi_{g_1, g_2}(v) )$.
\end{lemma} 
\begin{proof}
 By the cocycle property (\ref{prop1bus}) of the Busemann function and the assumption that $b^{g_2}_{v^{g_1}_+}( \pi(v), \pi(\Psi_{g_1, g_2}(v) )) =0$ , for each $(v,t) \in  S^{g_1}\widetilde M \times \R$, we have 
 \begin{align*}
&b^{g_2}_{v^{g_1}_+}( \pi \phi_t^{g_1}(v), \pi \phi^{g_2}_{\tau(v,t)}\Psi_{g_1, g_2}(v)) = b^{g_2}_{v^{g_1}_+}(  \pi  \phi_t^{g_1}(v),\pi \Psi_{g_1, g_2}(v)) +\tau(v,t)\\
=& b^{g_2}_{v^{g_1}_+}( \pi(  \phi_t^{g_1}(v)), \pi(v)) +  b^{g_2}_{v^{g_1}_+}( \pi(v),   \pi(\Psi_{g_1, g_2}(v))  ) +\tau(v,t) =0.
 \end{align*}
 This implies by the definition of $\Psi_{g_1, g_2}$,
$$
\Psi_{g_1, g_2}( \phi_t^{g_1}(v))  = \phi^{g_2}_{\tau(v,t)}(\Psi_{g_1, g_2}(v)),
$$
for $\tau(v,t) = b^{g_2}_{v^{g_1}_+} ( \pi(v),\pi(\phi_t^{g_1}(v))$. 


The   $\Gamma$-equivariance of the orbit equivalence and the time change follow from the  $\Gamma$-invariance (\ref{prop2bus}) of the Busemann function. Furthermore, for
each $v  \in S^{g_1}\widetilde M$, there exists a number $t(v) \in \R$ such that
$$
\Psi_{g_2, g_1} \circ \Psi_{g_1, g_2}(v) =  \phi_{t(v)}^{g_1}(v).
$$
The definition of the orbit equivalence $\Psi_{g_2, g_1}$ gives
$$
0 = b^{g_1}_{v^{g_1}_+}( \pi(\Psi_{g_1, g_2}(v) ), \pi(\phi_{t(v)}^{g_1}(v)) =   b^{g_1}_{v^{g_1}_+}( \pi(\Psi_{g_1, g_2}(v) ), \pi(v))  - t(v),
$$
which yields the last assertion.
\end{proof}

With abuse of notation, we also denote the quotient orbit equivalence as $\Psi_{g_1,g_2}: S^{g_1}M \to S^{g_2}M$. The next corollary follows immediately from the construction of the orbit equivalence.


\begin{corollary}
Let $g_1, g_2$ be two metrics in $R^-(M)$ and let $m$ be an ergodic measure in $\mathcal{M}^1 (\phi^{g_1})$. Then for $m$-almost every $v \in  S^{g_1} \widetilde M$, 
we have
$$
\lim_{t \to \infty} \frac{\tau(v,t)}{t} = I_m(g_1,g_2) = \int_{S^{g_1}M} g_2(B^{g_2}(\pi (v), v^{g_1}_+) , v )dm.
$$
\end{corollary}

Since the Busemann function is $\Gamma$ invariant, the definition for $\tau(v,t)$ descends to $S^{g_1}M$.
\begin{definition}\label{def:timechange}  
We call the function $\tau=\tau_{g_1,g_2}: S^{g_1}M \times \R  \to \R$ given by
$$
\tau_{g_1,g_2}(v,t) =  b^{g_2}_{\widetilde{v}^{g_1}_+} ( \pi(\widetilde{v}), \pi(\phi_t^{g_1}(\widetilde{v})) )
$$
the \emph{time change} and  $a_{g_1,g_2} : S^{g_1}M  \to \R$  given by
$$
a_{g_1,g_2}(v) = \left.\frac{d}{dt}  \right|_{t = 0} 
  b^{g_2}_{\widetilde{v}^{g_1}_+} ( \pi(\widetilde{v}), \pi(\phi_t^{g_1}(\widetilde{v})) )  = g_2(B^{g_2}(\pi (\widetilde{v}), \widetilde{v}^{g_1}_+) , \widetilde{v} )
$$
the \emph{infinitesimal time change} of $\phi^{g_1}$ to  $\phi^{g_2}$, where $\widetilde{v}$ is a lift of $v$ in $S^{g_1}\widetilde{M}$.
\end{definition}

It is clear that the Busemann function and its derivatives are defined on the universal cover $S^{g_1}\widetilde{M}$. We will often drop the distinction between $v\in S^{g_1}M$ and $\widetilde{v}\in S^{g_1}\widetilde{M}$ and simply write
$
a_{g_1,g_2}(v) = \left.\frac{d}{dt}  \right|_{t = 0} 
  b^{g_2}_{v^{g_1}_+} ( \pi(v), \pi(\phi_t^{g_1}(v)) )  = g_2(B^{g_2}(\pi (v), v^{g_1}_+) , v )
$.

\begin{remark} \label{remark,regularityTimeChange}
We make the the following remarks about time changes and infinitesimal time changes.
\begin{enumerate}
\item
The H\"older structure of the boundary $\partial M$ implies the H\"older continuity of $a_{g_1g_2}$. 

\item 
The time change $\tau_{g_1,g_2}$ is an additive (H\"older) cocycle. It satisfies for $t,s\in \R$
$$
\tau_{g_1,g_2}(v,t+s) = \tau_{g_1,g_2}(v,t) + \tau_{g_1,g_2}(\phi_t^{g_1}v,s)
$$
and 
$$
\tau_{g_1,g_2}(v,t) = \int_0^t a_{g_1,g_2}(\phi_s^{g_1}v) ds.
$$
\end{enumerate}
\end{remark}



We discuss in the next remark the existence of a bijective orbit equivalence.

\begin{remark} 
Note that $\Psi_{g_1, g_2}: S^{g_1}M  \to S^{g_2}M$ maps orbits of the geodesic flow of $g_1$ surjectively onto orbits of the geodesic flow of $g_2$ but is not necessarily
injective.
An injective map can be obtained by modifying the time change and the infinitesimal time change in its Liv\v{s}ic cohomology class (see Gromov \cite{Gr00} and also \cite{Kn02} for details). Since these infinitesimal time changes are Liv\v{s}ic cohomologous, we are free to choose which one to use for our theory.
Throughout this note, we prefer to work with the non-modified 
orbit equivalence and the non-modified infinitesimal time change $a_{g_1,g_2}$.
\end{remark}


Let us denote by $X_g(v) :=\left.\frac{d}{dt} \right |_{t=0} \phi^g_t(v)$ the infinitesimal generator of the geodesic flow
$\phi^g_t : S^gM \to S^gM$. 


\begin{corollary}\label{cor:equiv}

Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. Then the following are equivalent.
\begin{enumerate}
\item
The metrics $g_1$ and $g_2$ have the same marked length spectrum.
\item
The infinitesimal time change is cohomologous to $1$, i.e. there exists a H\"older continuous function $u: S^{g_1}M \to \R$ 
such that for any $t\in\R$
$$
a_{g_1,g_2}(v) -1 = X_{g_1}(u)(v).
$$
\item
The geodesic flows of $g_1$ and $g_2$ are time preserving conjugate. More precisely, 
 there exists a H\"older continuous map $G: S^{g_1}M \to S^{g_2}M$  such that
 $$
 \phi_t^{g_2}(G(v)) =   G (\phi_t^{g_1}(v)),
 $$
and  $G(v)^{g_2}_{\pm} = v^{g_1}_{\pm}$.
 \end{enumerate}
\end{corollary}
\begin{proof}
We prove $(1)\Rightarrow (2) \Rightarrow (3) \Rightarrow (1)$. Assume that $g_1, g_2$ have the same marked length spectrum. Let $\phi^{g_1}_t(v) $ be a periodic orbit with period $l>0$. Then
$$
\phi^{g_2}_{\tau(v,l)}\circ \Psi_{g_1, g_2}(v) = \Psi_{g_1, g_2}\circ\phi^{g_1}_{l}(v),
$$
with $ l= \tau(v,l) = \int_0^l a_{g_1,g_2}( \phi_s^{g_1}(v) ds$. By Liv\v{s}ic theorem \cite[Chapter 19]{KH95}, there exists a H\"older continuous function $u: S^{g_1}M \to \R$ differentiable along the orbits of the geodesic flow $\phi_t^{g_1}$
such that
$$
a_{g_1,g_2}(v) -1 = X_{g_1}(u)(v).
$$
We obtain (2). Therefore
$$
\tau(v,t) = t + u(\phi_t^{g_1}(v)) -u(v).
$$
 Hence 
 $$
 \phi^{g_2}_t \phi^{g_2}_{u(\phi_t^{g_1}(v)) -u(v)}\Psi_{g_1, g_2}(v) =\Psi_{g_1, g_2}(\phi_t^{g_1}(v)),
$$
and $G(v) = \phi^{g_2}_{-u(v)}\Psi_{g_1, g_2}(v) $ defines the required orbit equivalence, which preserves the points at infinity. This yields (3).
Under this assumption the marked length spectrum of $g_1$ and $g_2$ are the same. This finishes our proof. 
\end{proof}




\subsection{Geodesic currents, intersections and geodesic stretches}
\hfill\\
In this section, we reinterpret the geodesic stretch using the framework of \emph{geodesic currents}, introduced by Bonahon (see \cite{Bon91} and \cite{ST21}). In certain context, geodesic currents offer a more 
convenient and flexible tool than invariant measures 
for the purposes of our theory. This is for instance evident in Proposition \ref{prop,triangleInequality} and later Proposition \ref{prop,whyIntegralWellDefined}. Throughout the note, we will alternate between  the perspectives of invariant probability measures and geodesic currents, depending on which is more suitable to the context.


\subsubsection{Geodesic currents} We introduce the \emph{geodesic current} in this subsection and discuss many of its properties. We omit many proofs in this subsection since they are classical in the field. Standard reference for this topic includes \cite{Bon88} and \cite{Bon91}.

Recall $M=\widetilde M/ \Gamma$ is a closed manifold admitting Riemmanian metrics of negative sectional curvature and $R^-(M)$ is the space of all smooth Remiannian metrics of negative curvature on $M$. Recall also
the set 
$$
\partial^{(2)} \widetilde M = \partial \widetilde M \times \partial \widetilde M \setminus \diag
$$
corresponds to the set of unparametrized oriented geodesics on $\widetilde M$ for any metric in $R^-(M)$.  

\begin{definition}
A \emph{geodesic current}\footnote{We consider in this note oriented geodesic currents in contrast to unoriented geodesic currents introduced in \cite{Bon88}.} is a locally finite $\Gamma$-invariant Borel measure $\mu$ on $\partial^{(2)} \widetilde M$.
\end{definition}

Let us denote the space of $\Gamma$-invariant geodesic currents by $\mathcal{C} (\Gamma) $. It is equipped with the weak* topology of convergence of Borel measures, that is,  a sequence $\mu_n \in \mathcal{C} (\Gamma) $
converges to  $\mu \in \mathcal{C} (\Gamma) $ if and only if for all continuous functions $\varphi: \partial^{(2)} \widetilde M  \to \R$
with compact support, we have 
$$ \lim_{n \to \infty} \int \varphi d\mu_n =  \int \varphi d\mu. $$ 

The simplest examples of geodesic currents are dirac currents. For any $\gamma\in \Gamma$, let $\delta_{\gamma}$ denote the dirac measure supported at $(\gamma^-,\gamma^+)\in \partial^{(2)} \widetilde M$, where $\gamma^-$ (resp. $\gamma^+$) is the repelling (resp. attractive) fixed point of $\gamma$ on $\partial \Gamma$. Then associated to the conjugacy class $[\gamma]\in[\Gamma]$ is the \emph{dirac current} in $\mathcal{C} (\Gamma) $ given by
$$\delta_{[\gamma]}=\sum_{\alpha\in[\gamma] }\delta_{\alpha}.$$



Let $ \R_{>0} $ denote the set of all positive real numbers. The following lemma is classical (see for example \cite{Bon91}).
\begin{lemma}\label{prop:proj-current}
 Denote by $\mathcal{PC}(\Gamma) =  \mathcal{C} (\Gamma)/ \R_{>0} $ the projectivized space of currents. Then $\mathcal{PC}(\Gamma)$ is compact.
\end{lemma} 



We then explain the relation between geodesic currents and invariant probability measures. Recall for $g \in R^-(M)$ and $p_0 \in \widetilde M$, we have introduced the Hopf map 
$H^g_{p_0} : S^g \widetilde M \to \partial^{(2)} \widetilde M \times \R$ in Section \ref{subsection, BasicGeodesicStretch}.  Recall also $\mathcal{M}(\phi^g)$ is the space of $\phi^g$-invariant measures on $S^g M$.

\begin{proposition}\label{prop:m-current}  
 For $g \in R^-(M)$, each geodesic current $\mu\in \mathcal{C}(\Gamma)$ defines a  measure $m_{\mu}^g$ which is both $\Gamma$-invariant and $\phi_t^g$-invariant, with local product structure $dm_{\mu}^g= d\mu \times dt$ in the Hopf coordinate $H^g_{p_0}$. This map $\mu\mapsto m^g_{\mu}$ yields a homeomorphism between $\mathcal{C} (\Gamma)$ and $ \mathcal{M}(\phi^g)$ which is linear, in the sense that $k_1\mu_1+k_2\mu_2$ is mapped to $k_1 m_{\mu_1}^g+k_2 m_{\mu_2}^g$ for $k_1,k_2\geq 0$.

Moreover, for a measurable and non-negative function $f: S^g \widetilde M \to \R$, its Lebesgue integral with respect to $m^g_{\mu}$ can be expressed as 
$$
\int_{S^g\widetilde M} \ f dm_{\mu}^g = \int_{\partial^{(2)} \widetilde M}
\int_{\R} f(\phi_t^g (v_{(\xi_-, \xi_+)}))dt \ d\mu (\xi_-, \xi_+).
$$
where $v_{(\xi_-, \xi_+)} = (H^g_{p_0})^{-1} (\xi_-, \xi_+, 0)$.
\end{proposition}




To further consider integration over the quotient unit tangent bundle $S^g M$, we need to take a \emph{fundamental domain} $\mathcal{F}$ for the $\Gamma$ action on $\widetilde M$, that is,  a connected and contractible set of $\widetilde M$ such that each $\Gamma$-orbit $\Gamma\cdot p$ meets the interior of $\mathcal{F}$
at exactly one point. We let
$$ S^g \mathcal{F} := \bigcup_{p \in \mathcal{F} }S^g_p \widetilde {M}
$$
be a fundamental domain for the $\Gamma$ action on $S^g \widetilde {M}$.


\begin{remark}\label{remark:CurrentMeasure}
For each metric $g\in R^-(M)$, the $\Gamma$-invariant measure $m_{\mu}^g$ on $S^g \widetilde M$ induces a  $\phi^g$-invariant measure on $S^g M$ as follows. 
If $f:S^g M \to \R $ is a bounded measurable function and $ \widetilde f:S^g \widetilde {M} \to \R $ is its lift, then with abuse of notation, we let
$$
\int_{S^g M} f \ dm_{\mu}^g := \int_{S^g \widetilde M} \widetilde f  \cdot \chi_{_{S^g \mathcal{F}}}     \ dm_{\mu}^g
$$
where $\chi_{_{S^g \mathcal{F}}}$ is the characteristc function of the set $S^g \mathcal{F}$. The definition is independent of the choice of the fundamental domain $\mathcal{F}$.
\end{remark}


\subsubsection{Geodesic stretches and intersections via geodesic currents} \label{subsection GeodesicStretchIntersection}
We reinterpret the geodesic stretch from the viewpoint of geodesic currents. 

\begin{definition}\label{def:defGeodesicStretch}
The  geodesic stretch is
 \begin{align*}
 &I:  \mathcal{C}(\Gamma) \times R^-(M) \times R^-(M) \to \mathbb{R}_{\geq 0}\\
& I_\mu(g_1,g_2) := I_{\hat m_{\mu}^{g_1}}(g_1, g_2),
\end{align*}
where
$$\hat m_{\mu}^{g_1} :=\frac{m_{\mu}^{g_1}}{m_{\mu}^{g_1}(S^{g_1} M)}\in \mathcal{M}^1(\phi^{g_1})$$ and the geodesic stretch $I_{\hat m_{\mu}^{g_1}}(g_1, g_2)$ defined using geodesic flow invariant probability measure has been introduced in Section \ref{subsection, BasicGeodesicStretch}.
\end{definition}


There is a pairing called the \emph{intersection} that is closely related to the geodesic stretch. 

\begin{definition}\label{def:intersection}
The \emph{intersection} $i: R^-(M) \times \mathcal{C}(\Gamma) \to \mathbb{R}_{\geq 0}$  is given by
$$
i(g, \mu) := m_{\mu}^g(S^gM).
$$
\end{definition}

\begin{remark} \label{remark,intersection}
The intersection $i(g, \cdot)$ is the translation distance function (length function) with respect to $g$ (see \cite{Bon91}) . In particular, when $\mu=\delta_{[\gamma]}$ is the dirac current associated to $[\gamma]\in [\Gamma]$, the intersection $i(g, \delta_{[\gamma]})$ equals the $g$-length of the $g$-closed geodesic in the free homotopy $[\gamma]\in [\Gamma]$. 
\end{remark}

To relate the intersection and the geodesic stretch, we need the following proposition. For its proof, we refer to \cite[Proposition 2.13, Remark 2.14]{ST21}.
\begin{proposition} \label{prop: transformation-formula}
Let $g_1, g_2\in R^-(M)$  and  $\mu \in \mathcal{C} (\Gamma)$.
If $G:S^{g_2}M \to \R$ is a $ m_{\mu}^{g_2}$ integrable function, then $G\circ \Psi_{g_1, g_2} : S^{g_1}M \to \R$ is  $ m_{\mu}^{g_1}$ integrable 
and 
$$
\int_{S^{g_2}M} G \ dm_{\mu}^{g_2} = \int_{S^{g_1}M} G \circ \Psi_{g_1, g_2}  a_{g_1,g_2} dm_{\mu}^{g_1},
$$
where $\Psi_{g_1, g_2}$ is the map introduced in Lemma \ref{lem:conj}.
In particular,
$$
m_{\mu}^{g_2}(S^{g_2}M) = \int_{S^{g_1}M}   a_{g_1,g_2} dm_{\mu}^{g_1}.
$$

\end{proposition}

The following relates the intersection and the geodesic stretch for geodesic currents. 

\begin{corollary}\label{cor:s-current} 
Given  a geodesic current  $\mu\in\mathcal{C}(\Gamma) $ and given $g_1,g_2 \in R^-(M)$ so that $m_{\mu}^{g_1} \in \mathcal{M}(\phi^{g_1})$ has finite mass, then 
$$
I_\mu(g_1,g_2) = \frac{i(g_2, \mu)}{i(g_1, \mu)}.
$$
In particular, for all $\lambda >0$,
$$I_{\lambda\mu}(g_1,g_2) = I_{\mu}(g_1,g_2) $$  and therefore  $I_{\mu}(g_1,g_2)$ descends to be defined on the projective space $\mathcal{PC}(\Gamma)$. We denote the descended map as $I([\mu], g_1,g_2)$.


\end{corollary}

\begin{proof}

From the definition of the geodesic stretch (Definition \ref{def:defGeodesicStretch}) and Proposition \ref{prop: transformation-formula}, for $\mu\in\mathcal{C}(\Gamma) $, we have
    $$
I_\mu(g_1,g_2) = \frac{1}{m_{\mu}^{g_1}(S^{g_1}M)}\int_{S^{g_1}M}    a_{g_1,g_2} dm_{\mu}^{g_1} = \frac{m_{\mu}^{g_2}(S^{g_2}M) }{m_{\mu}^{g_1}(S^{g_1}M)} = \frac{i(g_2, \mu)}{i(g_1, \mu)}.
$$
\end{proof}


  When $M=S$ is a closed surface, the intersection generalizes to the geometric intersection number for curves and extends to be a continuous symmetric function $i:\mathcal{C} (\Gamma) \times  \mathcal{C} (\Gamma) \to \mathbb{R}$, called the \emph{intersection number} (\cite[Proposition 3]{Bon88}, see also \cite{Ot90}). We will present the magic of this concept in a proof in the last section (Proposition \ref{prop, bonahonIntersection}). Unfortunately, in higher dimensions, a similar pairing of geodesic currents like the intersection number is not known.  

 \begin{proposition}
   When $\dim M=2$, there is an embedding of  $R^-(M) $ into $\mathcal{C} (\Gamma)$ via Liouville currents: for each $g \in R^-(M)$, we associate  the Liouville current $\lambda_g$ in $\mathcal{C}(\Gamma) $  defined by demanding that
    $m_{\lambda_g}^g $ is the non-normalized Liouville measure with
   $m_{\lambda_g}^g (S^gM) = 2 \pi \vol(M,g)$. Furthermore,  this embedding identifies the intersection and the intersection number. For each $\mu \in \mathcal{C}(\Gamma)$,
     $$
    i(\lambda_g, \mu) = i(g, \mu) =  m_{\mu}^g(S^gM).
    $$  
 \end{proposition}
   \begin{proof}
    We want to show $ i(\lambda_g, \mu) = i(g, \mu)$. For a fixed $g_0  \in R^-(M) $ and all free homotopy classes $[\gamma]\in [\Gamma]$, by the definition of infinitesimal time change $a_{g_0,g}$, we have
    $$
    i(\lambda_g, \delta_{[\gamma]})= \ell_{g}([\gamma])= \int _{S^{g_0} M} a_{g_0,g} dm^{g_0}_{\delta_{[\gamma]}}, 
$$
Hence for any $\mu \in \mathcal{C}(\Gamma)$, we can find by Sigmund's theorem (\cite[Theorem 1]{Sig72}) a sequence $\delta_{\gamma_n}$ converging weakly to $ \mu$, after scaling by some real multiplies. Using the continuity of the intersection number and  Proposition 
\ref{prop: transformation-formula} again, we obtain
$$
i(\lambda_g, \mu)= \int _{S^{g_0} M} a_{g_0,g} dm^{g_0}_{\mu} =  m_{\mu}^g(S^gM) = i(g, \mu). 
$$
   \end{proof}



We continue to study properties of the geodesic stretch. The following lemma is an immediate consequence of Corollary \ref{cor:s-current}.
\begin{lemma} \label{lemma,cocycleRelationStretch}

 The geodesic stretch $I: \mathcal{PC}(\Gamma) \times R^-(M) \times R^-(M) \to \mathbb{R}_{\geq 0}$ given by
$$
I([\mu], g_1,g_2) =I_{\mu}(g_1,g_2)=  \frac{i(g_2, \mu)}{i(g_1, \mu)}
$$
satisfies for any $\mu\in\mathcal{C}(\Gamma)$ and any $g_1, g_2, g_3\in R^-(M)$,
 $$
I_\mu(g_1, g_3) =I_\mu(g_1, g_2) I_\mu(g_2, g_3).
$$

In particular,
$$
I_\mu(g_1, g_2) = \frac{1}{I_\mu(g_2, g_1)}.
$$   
\end{lemma}


Moreover,


\begin{lemma}[Countinuity of geodesic stretches]\label{lemma, GeodesicStretchContinuous}
The geodesic stretch 
$$I: \mathcal{PC}(\Gamma) \times R^-(M) \times R^-(M) \to \mathbb{R}_{\geq 0}$$
$$
I([\mu], g_1,g_2) =I_{\mu}(g_1,g_2)=  \frac{i(g_2, \mu)}{i(g_1, \mu)}
$$
 is continuous.   
\end{lemma}  
\begin{proof}
According to Corollary \ref {cor:s-current},
we have
$$
I_\mu(g_1,g_2) = \frac{1}{m_{\mu}^{g_1}(S^{g_1}M)}\int_{S^{g_1}M}    a_{g_1,g_2} dm_{\mu}^{g_1} =\int_{S^{g_1}M}    a_{g_1,g_2} d\widehat{m}_{\mu}^{g_1},
$$
where  $a_{g_1,g_2}$ is the infinitesimal time change given by
$$
a_{g_1,g_2}(v) = \left.\frac{d}{dt}  \right|_{t = 0} 
  b^{g_2}_{v^{g_1}_+} ( \pi(v), \pi(\phi_t^{g_1}(v)) )  = g_2(B^{g_2}(\pi (v), v^{g_1}_+) , v )
$$
We first show the continuity for $(g,\mu) \mapsto I_\mu(g_1,g)$.
For this we claim that for any $g_2 \in R^-(M)$ all $\varepsilon >0$ there exists a $C^2$ open neighborhood $U$ of $g_2$ such that
$$
 \|B^{g}(\pi (v), v^{g_1}_+) -B^{g_2}(\pi (v), v^{g_1}_+) \|_{g_2} < \varepsilon
$$
for all $v \in S^{g_1}\widetilde M$. 
If this is not the case, there exists $\varepsilon_0 >0$ and sequences $\{h_n\}_{n\geq0} \subset R^-(M) $ and $\{v_n\}_{n\geq0} \subset S^{g_1} \widetilde M$ where  $h_n$ converges to $g_2$ such that
$$
\|B^{h_n}(\pi (v_n), v^{g_1}_{n_+}) -B^{g_2}(\pi (v_n), v^{g_1}_{n_+}) \|_{g_2} \ge \varepsilon_0.
$$
By compactness of $M = \widetilde M / \Gamma$, we can assume that $v_n$ converges to some $v \in S^{g_1} \widetilde M $. 
Note that $B^{h_n}(\pi (v_n), v^{g_1}_{n_+} ) \in S^{h_n}M$ is the initial vector
of the $h_n$-geodesic $c_n: [0, \infty) \to \widetilde M$ with  $c_n(0) = \pi (v_n)$ and $c_n(\infty) = v^{g_1}_{n_+}$. By choosing a subsequence of $c_n$, we can assume that $c_n$ converges to a $g_2$ geodesic $c$ with $c(0) = \pi (v)$ and $c(\infty) =  v^{g_1}_+$
we have $\dot c(0) = B^{g_2}(\pi (v), v^{g_1}_+)$ and therefore $B^{h_n}(\pi (v_n), v^{g_1}_{n_+})$ converges to $B^{g_2}(\pi (v), v^{g_1}_+) $. Since by a similar argument, $B^{g_2}(\pi (v_n), v^{g_1}_{n_+})$ converges to $B^{g_2}(\pi (v), v^{g_1}_+)$. We obtain a contradiction.
This yields that for all  $\varepsilon >0$ there exists a $C^2$ open neighborhood $U$ of $g_2$ such that
$$
|a_{g_1,g}(v) - a_{g_1,g_2}(v)| < \varepsilon,
$$
for all $g \in U$ and $v \in S^{g_1}M $. Now let $\mu_n \in \mathcal{C}(\Gamma)$
converge weakly to $\mu$ and $h_n \in R^-(M)$ converge in the $C^2$-topology to $g$. We obtain
\begin{align*}
\left|I_{\mu_n}(g_1,h_n) -I_{\mu}(g_1,g_2)\right|& = \left|\int_{S^{g_1}M}   a_{g_1,h_n} d\widehat{m}_{\mu_n}^{g_1} -\int_{S^{g_1}M} a_{g_1,g_2} d\widehat{m}_{\mu}^{g_1}\right|\\
& \le \left|\int_{S^{g_1}M}a_{g_1,h_n} d\widehat{m}_{\mu_n}^{g_1} -\int_{S^{g_1}M}a_{g_1,g_2} d\widehat{m}_{\mu_n}^{g_1} \right|\\
& \quad
 + \left|\int_{S^{g_1}M}a_{g_1,g_2} d\widehat{m}_{\mu_n}^{g_1} - \int_{S^{g_1}M} a_{g_1,g_2} d\widehat{m}_{\mu}^{g_1} \right|.
\end{align*}
Since $a_{g_1,h_n}$ converges uniformly to $a_{g_1,g_2}$ and $\widehat{m}_{\mu_n}^{g_1}$ converges weakly to $\widehat{m}_{\mu}^{g_1}$,
we obtain that $I_{\mu_n}(g_1,h_n)$ converges to  $I_{\mu}(g_1,g_2)$. This implies the continuity of  $(\mu,g) \mapsto I_\mu(g_1,g)$ for all $g_1 \in R^-(M)$.




Since $I_\mu(g_1, g_2) = \frac{1}{I_\mu(g_2, g_1)} $, 
we also obtain the continuity of $(g , \mu) \mapsto I_\mu(g, g_2)$.
Finally for jointly continuity, consider for any $g \in R^-(M)$ the following equality
$$
I_\mu(g_1, g_2) = I_\mu(g_1, g)I_\mu(g, g_2)
$$
This yields the continuity of $ (\mu, g_1, g_2) \mapsto I_\mu(g_1, g_2)$  
and hence the proof of the proposition. 
\end{proof}








\section{Maximal stretch and Aubry-Mather theory}\label{sec:MC}




\subsection{The maximal stretch} \label{subsection, The maximal stretch}
\hfill\\
In this section, we focus on the \emph{maximal stretch}, which is a major object of study in this note. After introducing the maximal stretch in Subsection \ref{subsection, The maximal stretch} and verify some simple properties of this quantity, we turn in Subsection \ref{subsection, MCMather} to measure-theoretic objects associated with the study of the maximal stretch: these are \emph{maximal currents}, \emph{maximally stretched measures}, the \emph{Mather set}; we also discuss the non-measure-theoretic counterpart of the Mather set, namely the \emph{Aubry set}, which is defined using weak supersolutions. Then, in Subsection \ref{subsection, propMCMather}, we investigate further properties of the Mather set. Finally, in Subsection \ref{subsection AubrySetPeierlBarrier}, we discuss a closely related concept, the \emph{Peierl Barrier} and its properties.




\begin{definition}\label{def:maximal stretch}
For $g_1,g_2 \in R^-(M)$, the \emph{maximal stretch} $S:  R^-(M) \times R^-(M) \to \mathbb{R}_{\geq 0}$ is defined as
$$
S(g_1,g_2) = \sup_{\mu \in \mathcal{C}(\Gamma)} I_\mu(g_1,g_2)= \sup_{\mu \in \mathcal{C}(\Gamma)} \int a_{g_1,g_2}(v) d\hat{m}^{g_1}_{\mu}.
$$

\end{definition}

\begin{remark} \label{remark, supremumGeodesicStretch}
   % We make following remarks about the maximal stretch.
   We make following remarks about the maximal stretch.
    \begin{enumerate} 

      \item Since $I_{\mu}(g_1,g_2) =I([\mu], g_1,g_2) $ is defined on the compact space of projective currents $\mathcal{PC}(\Gamma)$ (Corollary \ref{cor:s-current}) and $I_{\mu}(g_1,g_2)$ is continuous (Lemma \ref{lemma, GeodesicStretchContinuous}). The supremum is realized by some currents, 
    $$ S(g_1,g_2) = \sup_{\mu \in \mathcal{C}(\Gamma)} I_\mu(g_1,g_2)=\max_{\mu \in \mathcal{C}(\Gamma)} I_\mu(g_1,g_2). $$

\item Since periodic orbit measures are dense in the space of invariant probability measures \cite[Theorem 1]{Sig72} and real multiple of dirac currents are dense in $\mathcal{C}(\Gamma)$, 

 $$ S(g_1,g_2) = \sup_{[\gamma] \in [\Gamma]} I_{\delta_{[\gamma]}}(g_1,g_2)=\sup_{[\gamma] \in [\Gamma]} \frac{\ell_{g_2}([\gamma])}{\ell_{g_1}([\gamma])} , $$
 where  $\ell_{g}([\gamma])$ is the length of the $g$-closed geodesic $\gamma^{g}$ in the free homotopy $[\gamma]\in [\Gamma]$.
      \end{enumerate}


\end{remark}

We explain our notation of lengths of curves.
\begin{remark}
    The following distinction for lengths of general Lipschitz curves and lengths of geodesics will be adopted throughout the note in the future. 
    \begin{itemize}
        \item 
    Given $g\in R^-(M)$, we denote $L_g(\alpha)$ as the $g$-length of a general Lipschitz curve $\alpha$ on $M$. 
    \item
    We denote $\ell_{g}([\gamma])$ as the $g$-length of the uniquely determined $g$-closed geodesic $\gamma^{g}$ up to parametrization in the free homotopy $[\gamma]\in [\Gamma]$, that is, $\ell_{g}([\gamma])=L_g(\gamma^{g})$.
    \end{itemize}
\end{remark}




We have the following continuity result for maximal stretch.
\begin{proposition} \label{propositionGK, GeodesicStretchContinuous}
    The maximal stretch $S:  R^-(M) \times R^-(M) \to \mathbb{R}_{\geq 0}$ given by,
$$
S(g_1,g_2) = \sup_{[\mu] \in \mathcal{PC}(\Gamma)} I([\mu], g_1,g_2)= \max_{[\mu] \in \mathcal{PC}(\Gamma)} I([\mu], g_1,g_2)
$$
is continuous.
\end{proposition}

\begin{proof}
The proposition follows from Lemma \ref{lemma, GeodesicStretchContinuous} and Lemma
 \ref{simpleLemma} in Appendix \ref{Appendix simpleLemma}.
 \end{proof}


\subsection{Maximally stretched measures and Aubry-Mather theory}\label{subsection, MCMather}
\hfill\\
In this subsection, we introduce maximal currents, the Mather set and the Aubry set arising from the study of maximal stretches. The termonologies and many ideas come from Aubry-Mather theory for Lagrangian systems (see for example \cite{Fat08}). We characterize some dynamical properties of the Mather set and the Aubry set in this and the next subsections.



\subsubsection{Maximal currents}
 We denote the set of \emph{maximal currents} of $g_1$ to $g_2$ as
$$
MC(g_1,g_2) = \{ \mu \in \mathcal{C}(\Gamma) \mid I_\mu(g_1,g_2)  =S(g_1,g_2)\}.
$$





We verify here a simple but interesting feature of maximal currents. It mainly exploits Lemma \ref{lemma,cocycleRelationStretch}.
\begin{proposition} \label{prop,triangleInequality}
For $g_1,g_2 ,g \in R^-(M)$,
we have
$$
S(g_1, g_2) \le S(g_1, g)  S(g, g_2) 
$$
where equality holds if and only if there is a current $\mu_0$ in the set $MC(g_1,g) \cap MC(g,g_2)$. 
In particular, in this case,
$ \mu_0 \in MC(g_1,g_2)$. 

Moreover, if the equality holds, then any current $\mu\in MC(g_1,g_2)$ is also in $MC(g_1,g) \cap MC(g,g_2)$.
\end{proposition}
\begin{proof}
The inequality follows since for all $\mu \in \mathcal{C}(\Gamma)$, we have
$$
I_\mu(g_1, g_2) =I_\mu(g_1, g) I_\mu(g, g_2) \le S(g_1,g) S(g,g_2).
$$
The equality 
$$
S(g_1, g_2) = S(g_1, g)  S(g, g_2) 
$$
is equivalent to
$$
\sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g_1,g) \sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g,g_2) =\sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g_1,g_2).
$$
Suppose $ I_{\mu_0}(g_1,g) = \sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g_1,g)$ and $ I_{\mu_0}(g,g_2) = \sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g,g_2)$.
Then
\begin{eqnarray*}
\sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g_1,g_2) &=& \sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g_1,g) I_\mu(g,g_2) \\
&\le&\sup_{ \mu \in  \mathcal{C}(\Gamma) } I_\mu(g_1,g) \sup_{ \mu \in  \mathcal{C}(\Gamma) }I_\mu(g,g_2)\\
&=& I_{\mu_0}(g_1,g) I_{\mu_0}(g,g_2) \\
&=&I_{\mu_0}(g_1,g_2)\le \sup_{ \mu \in  \mathcal{C}(\Gamma) }I_\mu(g_1,g_2).
\end{eqnarray*}
In particular, $\sup_{ \mu \in  \mathcal{C}(\Gamma) }I_\mu(g_1,g_2) =I_{\mu_0}(g_1,g_2)$.

On the other hand, let us suppose $S(g_1, g_2) = S(g_1, g) S(g, g_2) $ and assume $\sup_{ \mu \in  \mathcal{C}(\Gamma) }I_\mu(g_1,g_2) =I_{\mu_0}(g_1,g_2)$
for some $\mu_0 \in   \mathcal{C}(\Gamma)$. Then
$$
S(g_1,g_2) = I_{\mu_0}(g_1,g_2) =  I_{\mu_0}(g_1,g)   I_{\mu_0}(g,g_2) =S(g_1,g) S(g,g_2) 
$$
which implies the other claim.
\end{proof}


Recall $\partial^{(2)} \widetilde{M}$ denotes the space of unparametrized oriented geodesics of $\widetilde{M}$. Let $$\iota: \partial^{(2)} \widetilde{M}  \to \partial^{(2)} \widetilde{M}$$ be the 
flip map exchanging two factors of $\partial^{(2)} \widetilde{M}$.


\begin{lemma}
    Suppose $\mu_0$ is a maximal current.  Then $\iota^*\mu_0$ is also a maximal current. Therefore we can symmetrize $\mu_0$ to obtain a flip invariant maximal current as $\frac{\mu_0+ \iota^*\mu_0}{2}$.
\end{lemma}  
\begin{proof}
    Since $$S(g_1,g_2)= I_{\mu_0}(g_1,g_2)= \sup_{[\gamma]\in[\Gamma]} I_{\delta_{[\gamma]}} (g_1,g_2).$$
    If $\mu_0$ is a maximal current and if we write $\mu_0=\lim_{n\to \infty} \delta_{[\gamma_n]}$ in weak* topology, then $\iota^*\mu_0$ which is a limit of $\delta_{[\gamma_n^{-1}]}=\iota^* \delta_{[\gamma_n]}$, is also a maximal current. This follows from the observation that
    $\ell_{g_i}([\gamma])=\ell_{g_i}([\gamma^{-1}])$ and hence $I_{\delta_{[\gamma]}} (g_1,g_2)=I_{\delta_{[\gamma^{-1}]}} (g_1,g_2)$.
\end{proof}
For maximal stretched measures introduced next, we can also symmetrize them and obtain reflexive measures (see footnotes in the introduction). However, we do not emphasize this feature in this note and work with unsymmetrized objects.


\subsubsection{Maximally stretched measures and the Mather set}


We describe the measure-theoretic counterpart of maximal currents. Recall $\mathcal{M}^1(\phi^{g_1})$ denotes the space of $\phi^{g_1}$-invariant probability measures and $R^-(M)$ is the set of smooth Riemannian metrics with negative sectional curvature. Recall for $g_1,g_2 \in R^-(M)$, the maximal stretch of $g_1$ to $g_2$ is also
$$
S(g_1,g_2) = \max_{m \in \mathcal{M}^{1}(\phi^{g_1})} I_m(g_1,g_2).
$$



\begin{definition}
Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. The set of \emph{maximally stretched measures} of $g_1$ to $g_2$ is defined by
$$
MS(g_1,g_2) = \{ m \in \mathcal{M}^{1}(\phi^{g_1}) \mid I_m(g_1,g_2)  =S(g_1,g_2)\}.
$$
The \emph{Mather set} of $g_1$ to $g_2$ is defined by
$$
\mathcal{M}(g_1,g_2) :=\overline{ \bigcup_{m\in MS(g_1,g_2)} \supp m}.$$
\end{definition}



Using maximal currents, the Mather set of $g_1$ to $g_2$ can be equivalently written as

$$
\mathcal M(g_1, g_2) = \overline{\bigcup_{\mu \in MC(g_1,g_2)}\supp \hat{m}^{g_1}_{\mu} }.
$$



Mather sets in the Teichm\"uller space always project to geodesic laminations; In contrast, for metrics in $R^-(M)$, the Mather set is in general not related to geodesic laminations (see Example \ref{MatherNotLamination}). Nevertheless, some structural features from the Teichm\"uller space are still preserved in this general setting (Theorem \ref{corollary, LinearConjugacy} and Proposition \ref{thm, EmtpyInterior}). Before turning to an analysis of further properties of the Mather set, we complete the picture of the Aubry-Mather theory in our setting by introducing another closely related object, the \emph{Aubry set}.  

\subsubsection{Supersolutions and the Aubry set} \label{subsection,SupersolutionAubry}

We first consider \emph{(strong) supersolutions}  which in our context were defined in \cite{LT05}. They are analogous to weak KAM subsolutions studied in Fathi's monograph \cite{Fat08}. 

\begin{definition}\label{def,StrongSuper}
    Let $g_1, g_2  \in R^-(M)$. We call a H\"older continuous function $u:  S^{g_1}M \to \R$ a \emph{strong supersolution} for $a_{g_1,g_2}$, if it is smooth along the flow direction of the geodesic flow $\phi^{g_1}$ and
 for all $v\in S^{g_1}M$,
    $$
S(g_1, g_2) -a_{g_1, g_2}(v) + X_{g_1} u(v) \ge 0,
$$
where $X_{g_1}$ is the infinitesimal generator of the geodesic flow $\phi^{g_1}$ and $X_{g_1}u$ is H\"older continuous.

\end{definition}

We also introduce a weaker version of supersolutions as follows. They will be used in later subsections.
\begin{definition}\label{def,weakSuper}
    We say a continuous function $u:S^{g_1}M \to \mathbb{R}$ is a \emph{weak supersolution} for $a_{g_1,g_2}$, if for all $t_1 \le t_2$, we have
    $$
u(\phi_{t_2}^{g_1}v)- u(\phi_{t_1}^{g_1}v) \ge \int_{t_1}^{t_2} a_{g_1, g_2} (\phi_s^{g_1}v )ds - (t_2-t_1) S(g_1, g_2) .
$$
\end{definition} 





\begin{proposition}\label{prop:subsolution}
Let $g_1, g_2  \in R^-(M)$. Then there exists a strong supersolution for $a_{g_1,g_2}$.
\end{proposition}
\begin{proof}
For all $\mu \in \mathcal{C}(\Gamma)$, we know $$\int_{S^{g_1}M} a_{g_1,g_2}(v) d\hat{m}^{g_1}_{\mu} \le S(g_1,g_2) .$$ 

As a consequence, the integral of  $a_{g_1,g_2} -S(g_1,g_2) $ is non-positive along
all periodic orbits of the geodesic flow $\phi^{g_1}$. Then from \cite[Theorem 1]{LT05}, we obtain that there exists a H\"older continuous function $u:  S^{g_1}M \to \R$ smooth along the flow direction of $\phi^{g_1}$ so that for any $v\in S^{g_1}M$,
 $$X_{g_1} u(v) \ge  a_{g_1,g_2}(v)- S(g_1,g_2). $$
 Therefore $u$ is a supersolution for $a_{g_1,g_2}$.
\end{proof}

Motivated by the weak KAM-theory, we define the \emph{Aubry set}.
\begin{definition}
Let $g_1, g_2  \in R^-(M)$ and let $u:  S^{g_1}M \to \R$ be a weak supersolution for $a_{g_1,g_2}$. We define the set
\begin{align*}
\mathcal A_u(g_1, g_2) = \{ v \in S^{g_1}M \mid u(\phi_{t_2}^{g_1}v)  &= \int_{t_1}^{t_2} a_{g_1, g_2} (\phi_s^{g_1}v )ds - (t_2-t_1) S(g_1, g_2) \\
&+u(\phi_{t_1}^{g_1}v),
 \;\text{for all $t_1,t_2\in\R$ with $t_1 \leq t_2$} \}
\end{align*}
as the  \emph{Aubry set} of $u$.\\ 

We define the \emph{Aubry set} as  $$\mathcal{A}(g_1,g_2)= \bigcap_u \mathcal{A}_u(g_1,g_2),$$
where $u$ is any weak supersolution.
\end{definition}



\begin{remark}  \label{remark, AubrySet}
The following statements are clear from the definitions of $\mathcal A_u(g_1, g_2)$ and $\mathcal{A}(g_1,g_2)$.
\begin{enumerate}
\item  $\mathcal A_u(g_1, g_2)$ and $\mathcal{A}(g_1,g_2)$ are compact $\phi^{g_1}_t$-invariant subsets of $S^{g_1}M$. 
\item If we have for $t_1 \leq t_2$
\begin{equation*}
u(\phi_{t_2}^{g_1}(v))= \int_{t_1}^{t_2}  a_{g_1, g_2} (\phi_s^{g_1}(v) )ds - (t_2-t_1) S(g_1, g_2) 
+u(\phi_{t_1}^{g_1}(v)).
\end{equation*}
Then for any subinterval $[s_1,s_2] \subset [t_1,t_2]$, the above equality still holds  by replacing $t_j$ by $s_j$ for $j=1,2$.
\end{enumerate} 
\end{remark}

We would like to relate the Aubry set of a supersolution to the Mather set. For this, it is more convenient to work with strong supersolutions. 
\begin{proposition} \label{prop, AubryMather}
Let $g_1, g_2  \in R^-(M)$ and let $u:  S^{g_1}M \to \R$ be a strong supersolution. Then the Mather set $\mathcal M(g_1, g_2) $ is contained in the Aubry set $\mathcal A_u(g_1, g_2)$ of $u$.
\end{proposition}

\begin{proof}
Consider $v \in \mathcal M(g_1, g_2)$. Then there exists $m_n\in MS(g_1,g_2)$ and a sequence $v_n \in \supp m_n$ so that $v_n$ converges to $v$. By assumption, the function
$f: S^{g_1} M \to \mathbb{R}$ given by
$$f(v):= S(g_1, g_2) -a_{g_1, g_2}(v) + X_{g_1} u(v) $$
is non-negative. Therefore,
$$
\int_{S^{g_1}M} f  d m_n = S(g_1, g_2) -\int_{S^{g_1}M} a_{g_1, g_2} d m_n =0.
$$

Since the integrand is continuous and non-negative, we have that $f$ vanishes identically on the invariant set $\supp m_n$.
In particular, for $t_1\leq t_2$,
$$
u(\phi_{t_2}^{g_1}(v_n)) = \int_{t_1}^{t_2} a_{g_1, g_2} (\phi_s^{g_1}(v_n) )ds - (t_2-t_1) S(g_1, g_2) +u(\phi_{t_1}^{g_1}(v_n)) 
$$
and by continuity, $v$ is also contained in the Aubry set $A_u(g_1, g_2)$ of $u$.
 \end{proof}



The next theorem is the main result of this subsection: we show that one can always find an orbit equivalence between $S^{g_1}M$ and $S^{g_2}M$ so that the time change is maximally linear on the Aubry set of a weak supersolution.

Recall we introduced the time change function $\tau: S^{g_1}M \times \mathbb{R} \to \mathbb{R}$ (Definition \ref{def:timechange}) as
\begin{align*}
    \tau(v,t) =  b^{g_2}_{v^{g_1}_+} ( \pi(v), \pi(\phi_t^{g_1}(v))).
\end{align*}

\begin{theorem}
     \label{corollary, LinearConjugacy}
Let $g_1, g_2  \in R^-(M)$ and let $u:  S^{g_1}M \to \R$ be a weak supersolution.
Let $G: S^{g_1}M \to S^{g_2}M$ be a H\"older orbit equivalence given by 
$$G(v) := \phi^{g_2}_{- u(v)}\Psi_{g_1, g_2}(v).$$ Then 
$$
\phi^{g_2}_{\tau_u(v,t)} G(v) = G(\phi_t^{g_1}(v)),
$$
where $\tau_u(v,t):=\tau(v,t) -u(\phi_t^{g_1}(v))+u(v) \le tS(g_1, g_2)$.
In particular, the geodesic flows $ \phi^{g_1}$ and  $ \phi^{g_2}$ are homothetic on the Aubry set $\mathcal A_u(g_1, g_2) $, in the sense that
$$
 \phi^{g_2}_{ S(g_1,g_2)t} (G(v))  = G( \phi_t^{g_1}(v)),
 $$
for all $v \in \mathcal A_u(g_1, g_2)$. 


Furthermore, for all $g_1$-periodic orbits  $\phi_t^{g_1}(v)$ with $v \in \mathcal A_u(g_1, g_2)$ and with period $\ell_{g_1}(v)$,  the orbit $  \phi^{g_2}_{t} (G(v)) $ is periodic with period $ \ell_{g_2}(G(v))$ that satisfies
 $$ \ell_{g_2}(G(v)) = S(g_1, g_2) \ell_{g_1}(v).$$
\end{theorem}
\begin{proof}
In Lemma \ref{lem:conj}, we constructed a H\"older continuous homeomorphism $\Psi_{g_1,g_2}: S^{g_1}M \to S^{g_2}M $ such that
$$
\phi^{g_2}_{\tau(v,t)}\Psi_{g_1, g_2}(v) = \Psi_{g_1, g_2}( \phi_t^{g_1}(v)),
$$
where 
$$
\tau(v,t) =  b^{g_2}_{v^{g_1}_+} ( \pi(v), \pi(\phi_t^{g_1}(v)) )  =\int_0^t a_{g_1, g_2} (\phi_s^{g_1}(v) )ds,
$$
and  
$$
 a_{g_1, g_2} (v)= g_2( B^{g_2}(\pi (v), v^{g_1}_+) , v).
$$

  This yields
  \begin{align*}
  \phi^{g_2}_{- u(v)}   \phi^{g_2}_{\tau(v,t)} \Psi_{g_1, g_2}(v)
  &= \phi^{g_2}_{-u(v)}\Psi_{g_1, g_2}( \phi_t^{g_1}(v))\\
   &= \phi^{g_2}_{u(\phi_t^{g_1}(v))- u(v)}  \phi^{g_2}_{-u(\phi_t^{g_1}(v))} \Psi_{g_1, g_2}( \phi_t^{g_1}(v))\\
    &=\phi^{g_2}_{u(\phi_t^{g_1}(v))- u(v)} G(( \phi_t^{g_1}(v)).
\end{align*}
And therefore,
$$
\phi^{g_2}_{\tau(v,t)- u( \phi_t^{g_1}(v)) + u(v) }\phi^{g_2}_{- u(v)}\Psi_{g_1, g_2}(v) =      G(( \phi_t^{g_1}(v)).  
$$ 
Recall the definition of the orbit equivalence $G$,
$$
\phi^{g_2}_{\tau(v,t)- u( \phi_t^{g_1}(v)) + u(v) }G(v) =      G(( \phi_t^{g_1}(v)).  
$$  
  In particular, for $v \in \mathcal A_u(g_1, g_2)$, we have
  $$
  \tau(v,t)= u(\phi_t^{g_1}(v))- u(v) + t S(g_1,g_2).
  $$
 This concludes, for all $v \in \mathcal A_u(g_1, g_2)$ and for all $t\in \mathbb{R}$,  
 $$
\phi^{g_2}_{ S(g_1,g_2)t}G(v) = G(( \phi_t^{g_1}(v)). 
$$
\end{proof}




\subsection{More properties of maximally stretched measures, maximal currents and the Mather set} \label{subsection, propMCMather}
\hfill\\
We discuss in this subsection more properties of maximally stretched measures, maximal currents and the Mather set from different aspects.

\subsubsection{Ergodic maximally stretched measures}

This subsection discuss ergodicity theory in our setting from invariant measures perspective. Parallel statements extend to geodesic currents.

A first observation is that  the space of maximally stretched measures or  the space of maximal currents forms a convex set as follows.
\begin{lemma}
   Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. The set of maximally stretched measures is a closed convex subset in $\mathcal{M}^1(\phi^{g_1})$. similarly, the set of maximal currents $MC(g_1,g_2)$ is a closed convex subset in $\mathcal{C}(\Gamma)$.
\end{lemma}
\begin{proof}
    Suppose $m_1,m_2\in MS(g_1,g_2)$ and $m_0=tm_1+(1-t)m_2$ for some $t\in[0,1]$. Then from the properties of maximal currents for $m_1,m_2$, it follows,
    $$\int a_{g_1,g_2}(v) dm_0=S(g_1,g_2).$$
    Therefore $m_0\in MS(g_1,g_2)$ and $MS(g_1,g_2)$ is a convex subset of $\mathcal{M}^1(\phi^{g_1})$. The closedness condition of $MS(g_1,g_2)$ follows from continuity of the geodesic stretch (Lemma \ref{lemma, GeodesicStretchContinuous}).

\end{proof}

We then discuss the existence of ergodic maximally stretched measures, or ergodic maximal currents. A current $\mu$ is said to be \emph{ergodic} if the action of $\Gamma$ on $\partial^{(2)}M$ is ergodic with respect to $\mu$. Given a Riemannian metric $g\in R^{-}(M)$, this is equivalent to the fact that the geodesic flow $\phi^{g_1}$on $S^{g_1}M$ is ergodic with respect to its associated invariant measure $m^{g}_{\mu}$. It is a property independent of chosen metrics (see \cite{Su79}, \cite[Proposition 2.3]{ST21}). Therefore, we can consider the subset of ergodic currents in $\mathcal{C} (\Gamma)$, denoted as $\mathcal{C}_{erg}(\Gamma)$. Similarly, the subset of ergodic invariant probability measures is denoted as $\mathcal{M}^1_{erg}(\phi^{g_1})$.




The following is proved in \cite{GKL22} using Choquet representation theorem.

\begin{lemma} [\cite{GKL22} Lemma 5.5] \label{lemma, ergodicMaximalCurrent}
Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. Then
$$S(g_1,g_2)=\sup_{\mathcal{M}^{1}_{erg}(\phi^{g_1})} I_{m}(g_1,g_2)=\sup_{\mathcal{C}_{erg}(\Gamma)} I_{\mu}(g_1,g_2).$$
Moreover, there exists a maximally stretched measure $m_0\in MS(g_1,g_2)$ that is ergodic. Similarly, there also exists a maximal current $\mu_0$ in $MC(g_1,g_2)$ that is ergodic.
\end{lemma} 
\begin{proof}
    Suppose for $m_0\in\mathcal{M}^{1}(\phi^{g_1})$, we have

      $$S(g_1,g_2)=\int a_{g_1,g_2}(v) dm_0.$$

    By Choquet representation theorem (see, for example, \cite[Section 3]{Ph66}), for the compact convex metric space $\mathcal{M}^{1}(\phi^{g_1})$, there exists a probability measure $\tau_0$ in $\mathcal{M}^{1}(\phi^{g_1})$ which represents $m_0$ and is supported on the set $\mathcal{M}^{1}_{erg}(\phi^{g_1})$ of extreme points of $\mathcal{M}^{1}(\phi^{g_1})$. Therefore 
    \begin{align*}
         S(g_1,g_2)&=  \int_{\mathcal{M}^{1}_{erg}(\phi^{g_1})} I_m(g_1,g_2) d\tau_0(m)\\
           &\leq  \sup_{m \in \mathcal{M}^{1}_{erg}(\phi^{g_1})}I_m(g_1,g_2)\le S(g_1,g_2).
    \end{align*}
    This implies that the equality holds. Moreover, for any ergodic $m$ that is in the support of $\tau_0$, we have $S(g_1,g_2) =I_{m}(g_1,g_2).$

    The proof works similarly for ergodic maximal currents.
\end{proof}




\subsubsection{The Mather set is nowhere dense}

We prove in this subsection that for generic metrics in $R^{-}(M)$, the Mather set is nowhere dense. Precisely, the Mather set is not nowhere dense only when the marked length spectra of $g_1$ and $g_2$ are \emph{proportional},  that is, there exists a constant $C>0$ such that $\ell_{g_2}([\gamma])=C \ell_{g_1}([\gamma])$ for all $[\gamma]\in[\Gamma]$.  

Denote by $h_{top} (\phi^{g})$ the topological entropy of the geodesic flow $\phi^g$ for a Riemannian metric $g \in R^{-}(M)$. We first recall a related theorem from previous works of the second author.

\begin{theorem}[\cite{Kn95} Theorem 1.2, \cite{GKL22} Proposition 5.4]
   Given two Riemannian metrics $g_1, g_2  \in R^{-}(M)$, we have
    \begin{equation*}\label{eqtn Kn95}
        \frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) \ge 1.
    \end{equation*}
    The equality holds precisely when the marked length spectra of $g_1,g_2$ are proportional.
\end{theorem}


Our next key theorem shows that the propotionality of marked length spectra also characterize the topological structure of the Mather set.

\begin{theorem} \label{thm, EmtpyInterior}
   Given $g_1,g_2\in R^-(M)$, the following dichotomy holds:
   \begin{itemize}
       \item If the marked length spectra are not proportional, then the interior of the Mather set $\mathcal{M}(g_1,g_2)$ is empty.
       \item If the marked length spectra are proportional, then the Mather set $\mathcal{M}(g_1,g_2)=S^{g_1}M$.
   \end{itemize}
\end{theorem}

\begin{proof}
    Note that for each $v\in \mathcal{M}(g_1,g_2)$, we have for all $t\in \mathbb{R}$,
    $$\phi^{g_2}_{S(g_1,g_2)t}\circ G(v)=G \circ \phi^{g_1}_{t}(v),$$
    where $G: S^{g_1}M \to S^{g_2}M$ is the orbit equivalence defined in Theorem \ref{corollary, LinearConjugacy}.
        Suppose for the sake of contradiction,
      the  Mather set $\mathcal{M}(g_1,g_2)$  contains an open set $U\subset S^{g_1}M$.  
Since the geodesic flow $\phi^{g_1}$ is topologically transitive, there exists a dense orbit $\phi^{g_1}_t(v_0)$ with $v_0 \in U$. Therefore the continuity of $G$ implies

  $$\phi^{g_2}_{S(g_1,g_2)t}\circ G(v)=G \circ \phi^{g_1}_{t}(v),$$
for any $v\in S^{g_1}M$.

    This implies that for any $[\gamma]\in[\Gamma]$, we have $\ell_{g_2}([\gamma])= S(g_1,g_2) \ell_{g_1}([\gamma])$. Therefore, the marked length spectra are proportional, which leads to a contradiction.

On the other hand, when the marked length spectra are propotional, that is, there exists $C>0$ so that $\ell_{g_2}([\gamma])=C\ell_{g_1}([\gamma])$ for all $[\gamma]\in[\Gamma]$. Then
$ S(g_1,g_2)=\sup\limits_{[\gamma]\in[\Gamma]} \frac{\ell_{g_2}([\gamma])}{\ell_{g_1}([\gamma])}=C$. Therefore, every dirac measure obtained from a periodic orbit is a maximally stretched measure. Because periodic orbts of $\phi^{g_1}$ are dense in $S^{g_1}M$, it follows
 $$\mathcal{M}(g_1,g_2) :=\overline{ \bigcup_{m\in MS(g_1,g_2)} \supp m}= S^{g_1}M.$$
Moreover, in this case, every $\phi^{g_1}$-invariant measure is a maximally stretched measure by Sigmund's Theorem (\cite[Theorem 1]{Sig72}).
\end{proof}



\subsubsection{Minimal subsets of the Mather set} \label{subsubsection,minimalComponents}




Recall in topological dynamical system, a \emph{minimal subset} is a nonempty, closed and invariant subset of a dynamical system such that no proper subset has these three properties. A minimal subset of a dynamical system always exists due to Zorn Lemma. 

Motivated by minimal laminations in Teichmüller theory (see for example \cite[Chaper I.4]{CEG06}), we study  minimal subsets of the Mather set $\mathcal{M}(g_1,g_2)$. We show 
in Proposition \ref{Prop, OneOrUncountable} that a minimal subset in the Mather set $\mathcal{M}(g_1,g_2)$ either contains a single closed orbit or it must contain uncountable many orbits (leaves).



To prove this, we introduce the definition of an \emph{isolated orbit}. We say an orbit $\mathcal{O}=\{\phi_t^{g_1}(v)\}_{t\in\R}$ of a minimal subset $\Lambda$ is \emph{isolated}, if for any $w\in\mathcal{O}$, there exists $\varepsilon>0$ and a metric ball $B_w(\varepsilon)\subset S^{g_1} M$ centered at $w$ of the radius $\varepsilon$  with respect to the Sasaki metric $g_1^s$ such that $B_w(\varepsilon)\cap \Lambda$ is a connected geodesic segment homeomorphic to the unit interval.


\begin{proposition} \label{Prop, OneOrUncountable}
   Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. Suppose that $\Lambda$ is a minimal subset of $\mathcal{M}(g_1,g_2)$. Then 
    \begin{itemize}
        \item either $\Lambda$ is the orbit of a closed $g_1$-geodesic on $ S^{g_1} M$;

        \item or $\Lambda$ contains uncountable many orbits. Moreover, for every point $v\in\Lambda$, we can find a transversal section $\mathcal{P}_v$ to the flow $\phi^{g_1}$ at $v$ so that $\mathcal{P}_v\cap \Lambda$ is a perfect set.
    \end{itemize}
\end{proposition}
  \begin{figure}[!htb]
   \centering    \includegraphics[width=60mm,scale=0.5]{MinimalMatherPerfect.pdf}
    \caption{A figure for Property (A). The orbit $\mathcal{O}$ is a non-isolated leaf and $\mathcal{P}_v$ is a traversal to $\mathcal{O}$. } 
    \label{fig: figure1}
\end{figure}
\begin{proof}
    Suppose $\mathcal{O} \subset \Lambda$ is a nonempty isolated orbit. Take a (countable) cover of $\mathcal{O}$ by metric balls $B_{w_i}(\varepsilon_i)$ so that each $B_{w_i}(\varepsilon_i)\cap \Lambda$ is a connected geodesic segment on $\mathcal{O}$ as defined before the proposition. Then 
    $$\Lambda \backslash \mathcal{O} =\Lambda \backslash (\cup_{i} B_{w_i}(\varepsilon_i) ) $$ is a closed invariant set. If $\Lambda \backslash \mathcal{O} $ is empty, i.e. $\Lambda=\mathcal{O} $,  then the isolated orbit $\mathcal{O}$ can not be bi-infinite. This is because $S^{g_1}M$ is compact. A  bi-infinite orbit of the geodesic flow $\phi^{g_1}$ has an accumulation point on $S^{g_1}M$ which contradicts the isolated orbit condition.  Therefore $\mathcal{O}$ must be the orbit of a closed $g_1$-geodesic. On the other hand, if $\Lambda \neq \mathcal{O} $, then it leads to a contradiction with the fact that $\Lambda$ is minimal.
Next we assume all orbits of $\Lambda$ are not isolated. We take one orbit $\mathcal{O}$. Since $\mathcal{O}$ is not isolated, there exists a point $v$ in $\mathcal{O}$ that satisfies the following property: it is an accumulation point of $\Lambda \cap \mathcal{P}_v$ in $\Lambda$, if $\mathcal{P}_v$ is any transversal section to $\mathcal{O}$ at $v$ in $S^{g_1}M$ (i.e. $T_v S^{g_1}M = T_v \mathcal{P}_v \bigoplus X_{g_1}(v)$, where we recall $X_{g_1}: S^{g_1}M\to TS^{g_1}M $ is the infinitesimal generator of the geodesic flow  $\phi^{g_1}$).  See Fugure \ref{fig: figure1}.



    We call the above property the \emph{Property (A)}. The point $v\in \mathcal{O}$  satisfies the Property (A).  Therefore, there exists $ \{v_n\}\subset \Lambda \cap \mathcal{P}_v $ such that $v_n \to v$.  We then want to show  that Property (A) holds for any point in $\Lambda$ (not only at $v$). We start from showing that it holds for any point on $\mathcal{O}$. Because every point $w$ on $\mathcal{O}$ is a translation of $v$ as $w=\phi_T^{g_1}(v)$. Continuity of the flow $\phi^{g_1}$ implies $d_{g_1^s}(w_n, w)= d_{g_1^s}(\phi_T^{g_1}(v_n),\phi_T^{g_1}(v)) \to 0$ for a fixed real number $T$. This implies that every point $w$ on $\mathcal{O}$ satsifies Property (A): for any transversal $\mathcal{P}_w$  to $w$, we find $w$ is an accumulation point of $\mathcal{P}_w\cap \Lambda$ in $\Lambda$. Since every orbit of $\Lambda$ is not isolated, we obtain any point of $\Lambda$ satisfies the Property (A) in the same manner.


    Now we go back to the point $v$ which is the limit of $v_n$. Taking $\mathcal{P}_v $ small enough, then we can make sure that it is transversal to the orbit of $v_n$ at $v_n$ for $n$ big enough (i.e. $T_{v_n} S^{g_1}M = T_{v_n} \mathcal{P}_v \bigoplus X_{g_1}(v_n)$ ). Therefore since $v_n$ satisfies the Property (A), it is also an accumulation point of $\Lambda \cap \mathcal{P}_v$ in $\Lambda$. As every point of $\Lambda \cap \mathcal{P}_v$ in $\Lambda$ is an accumulation point, the set $\mathcal{P}_v\cap \Lambda$ is a perfect set. Lastly, since the obit $\mathcal{O}$ can only intersects $\mathcal{P}_v$ countable many times, $\Lambda$ must have uncountable many orbits.

\end{proof}
















\subsection{The Aubry set and the Peierls barrier} \label{subsection AubrySetPeierlBarrier}
We discuss in this subsection the \emph{Peierls barrier} and its properties. This concept is also motivated from Aubry-Mather theory and Lagrange dynamics (see for example \cite{Fat08}). In particular, the zero level set of the Peierls barrier plays an important role in this subsection.





\subsubsection{The Peierls barrier} 




\begin{definition} \label{def, PeierlsBarrier}

Given $g_{1}, g_{2} \in R^{-}(M)$, we define the \emph{Peierls barrier} $\mathcal{H}_{g_{1}, g_{2}}: S^{g_{1}} M \times S^{g_{1}} M \rightarrow \mathbb{R} \cup \{-\infty\}$ by
\begin{align*}
\mathcal{H}_{g_{1}, g_{2}}(v_{1}, v_{2}):= 
 \lim _{\varepsilon \rightarrow 0} 
 \lim_{t\to \infty} \sup\bigg\{ &\int_{0}^{t} a_{g_{1}, g_{2}}(\phi_{s}^{g_{1}} v) d s-t \cdot S(g_{1}, g_{2}) \mid   \\
 & d_{g_{1}^{s}}\left(v, v_{1}\right)<\varepsilon, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{2}\right)<\varepsilon \bigg\}.
\end{align*}

\end{definition}


In some sense, this quantity measures ``the infinite optimal way" to maximaize the cost of the function $a_{g_{1}, g_{2}}-S\left(g_{1}, g_{2}\right)$ from $v_{1}$ to $v_{2}$.


\begin{remark}
We make following remarks about the definition of the Peierls barrier.
    \begin{enumerate}
        \item The well-definedness of the Peierls barrier follows from the topological transitivity of the geodesic flow $\phi_{t}^{g_{1}}$. 
        \item The value $-\infty$ can possibly be 
acheived. For example, consider $[\gamma_0]\in[\Gamma]$ so that $\frac{\ell_{g_2}([\gamma_0])}{\ell_{g_1}([\gamma_0])}<S(g_1,g_2)$, and take $v_0\in S^{g_1}M$ tangential to $\gamma_0^{g_1}$, then  
$\mathcal{H}_{g_{1}, g_{2}}(v_{0},v_0)=-\infty$.

    \end{enumerate}
\end{remark}

Recall that the Aubry set is the intersection of all Aubry sets $\mathcal{A}_u(g_1,g_2)$ of weak supersolutions. Our goal in this subsection is to relate the zero level set of the Peierls barrier $\mathcal{H}_0(g_1,g_2):=\{v \in S^{g_1}M | \mathcal{H}_{g_1,g_2}(v,v)=0 \}$ with the Aubry set $\mathcal{A}(g_1,g_2)$. For this, it is more convenient to work with a natural \emph{(continuous) additive cocycle} associated with weak supersolutions.



A weak supersolution $u$ induces a continuous function $c_u:S^{g_1}M \times \mathbb{R}_{\geq 0}  \to \mathbb{R}_{\leq0}$ by letting
$$c_u(v,t):=\int_{0}^{t} a_{g_1, g_2} (\phi_s^{g_1}v )ds - t\cdot S(g_1, g_2)- \big(u(\phi^{g_1}_tv)-u(v)\big).$$
It is easy to check that $c_u$ is nonpositive and verifies the \emph{additive cocycle} condition, that is, for any $v\in S^{g_1}M$ and $t_1,t_2\in \mathbb{R}_{\geq0}$, 
$$c_u(v,t_1+t_2)=c_u(v,t_1)+c_u(\phi^{g_1}_{t_1}v,t_2).$$

\begin{remark}
    We make following remarks for the cocycle $c_u(v,t)$.
    \begin{itemize}
        \item As a consequence of non-positiveness, the cocycle $c_u(v,t)$ is monotone decreasing in $t\geq 0$ with $c_u(v,0)=0$. 
        \item  When $u$ is a strong supersolution, we have $c_u(v,t)= \int_{0}^{t} f\left(\phi_{s}^{g_{1}} v\right) d s$, where $f(v)=a_{g_1,g_2}(v) -S(g_1,g_2)- X_{g_1}u(v)$.
    \end{itemize}
\end{remark}

\begin{lemma}\label{lemma, ManePotentialLessZero}  
 Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. For any $v_{0} \in S^{g_{1}} M$, the Peierls barrier satisfies
$$
\mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right) \leq 0.
$$
\end{lemma}
\begin{proof}
    Let $u: S^{g_{1}} M \rightarrow \mathbb{R}$ be a weak supersolution for $a_{g_1,g_2}$ and $c_u$ be its associated cocycle so that for any $v \in S^{g_{1}} M$,
    \begin{align*}
\int_{0}^{t} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-t\cdot S\left(g_{1}, g_{2}\right) & =c_u(v,t) +u\left(\phi_{t}^{g_{1}} v\right)-u(v). 
\end{align*}


This implies
\begin{align*}
\mathcal{H}_{g_{1}, g_{2}}(v_{0}, v_{0}) &= 
 \lim _{\varepsilon \rightarrow 0} 
 \lim_{t\to \infty} \sup\bigg\{  \int_{0}^{t} a_{g_{1}, g_{2}}(\phi_{s}^{g_{1}} v) d s- t \cdot S(g_{1}, g_{2}) \mid  \\
 & \qquad \qquad  \qquad d_{g_{1}^{s}}\left(v, v_{0}\right)<\varepsilon, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{0}\right)<\varepsilon \bigg\}\\
&=\lim _{\varepsilon \rightarrow 0}\lim_{t\to \infty} \sup  \bigg\{c_u(v,t)+u\left(\phi_{t}^{g_{1}}v \right)-u(v) \mid \\
&\qquad \qquad  \qquad
 d_{g_{1}^{s}}\left(v, v_{0}\right)<\varepsilon, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{0}\right)<\varepsilon \bigg \} .
\end{align*}


Since $u$ is a uniform continuous function and $c_u$ is non-positive, it follows

\begin{align*}
 \mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right) &=
 \lim _{\varepsilon \rightarrow 0} \lim_{t\to \infty} \sup\bigg\{c_u(v,t) \mid  d_{g_{1}^{s}}\left(v, v_{0}\right)<\varepsilon, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{0}\right)<\varepsilon \bigg\}\\ 
 &\leq 0.
\end{align*}

\end{proof}

\begin{lemma}
     Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. The  Peierls barrier zero set

$$
\mathcal{H}_{0}(g_1, g_2):=\left\{v \in S^{g_{1}} M \mid \mathcal{H}_{g_{1}, g_{2}}(v, v)=0\right\}
$$
is a closed subset of $S^{g_{1}} M$.
\end{lemma}
\begin{proof}
    Suppose $v_n$ converges to $v_0$ and $\mathcal{H}_{g_{1}, g_{2}}(v_n, v_n)=0$ for all $n>0$. We want to show $\mathcal{H}_{g_{1}, g_{2}}(v_0, v_0)=0$. It suffices to show for all $\varepsilon_k=\frac{1}{k}$, we have 
    \begin{align*}
    &\mathcal{H}^{\varepsilon_k}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right) \\
 :=&
 \lim_{t\to \infty} \sup\bigg\{c_u(v,t) \mid  d_{g_{1}^{s}}\left(v, v_{0}\right)<\varepsilon_k, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{0}\right)<\varepsilon_k \bigg\} \geq 0 .
\end{align*}
Given a fixed $k\in \mathbb{N}$, take $n$ big enough so that  $d_{g_{1}^{s}}\left(v_n, v_0 \right)<\varepsilon'_k\leq \frac{\varepsilon_k}{2}$. Then
 \begin{align*}
0 =\mathcal{H}_{g_{1}, g_{2}}(v_n, v_n)& \le \mathcal{H}^{\varepsilon'_k}_{g_{1}, g_{2}}\left(v_{n}, v_{n}\right) \\
 =&
 \lim_{t\to \infty} \sup\bigg\{c_u(v,t) \mid  d_{g_{1}^{s}}\left(v, v_{n}\right)<\varepsilon'_k, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{n}\right)<\varepsilon'_k  \bigg\}.
\end{align*}
The choices of $\varepsilon_k$  and $\varepsilon'_k$ together with triangle inequalities for $d_{g_1^s}(\cdot,\cdot)$ implies $$\mathcal{H}^{\varepsilon_k}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right) \geq \mathcal{H}^{\varepsilon'_k}_{g_{1}, g_{2}}\left(v_{n}, v_{n}\right) \geq 0$$ 
and therefore we obtain $\mathcal{H}_{g_{1}, g_{2}}(v_0, v_0)=\lim\limits_{k\to\infty}\mathcal{H}^{\varepsilon_k}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right)\geq0$. By Lemma \ref{lemma, ManePotentialLessZero}, we conclude $\mathcal{H}_{g_{1}, g_{2}}(v_0, v_0)=0$.
\end{proof}



\begin{lemma}
     Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. The Peierls barrier zero set $\mathcal{H}_{0}(g_1, g_2)$
is a $\phi^{g_{1}}$-invariant subset of $S^{g_{1}} M$.
\end{lemma}
\begin{proof}
     We claim if $v_{0}$ satisfies $\mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right)=0$, then for any real number $T$, the vector $\phi_{T}v_{0}$ also satisfies $\mathcal{H}_{g_{1}, g_{2}}\left(\phi_{T}v_{0}, \phi_{T}v_{0}\right)=0$. Equivalently, we want to show, for any $\varepsilon>0$, any $\kappa>0$ and any big positive $\tau_0$, we can find a vector $v$ and $t_{0}\geq \tau_0$ so that


\begin{equation} \label{eqtn, EquationVV_0}
d_{g_{1}^{s}}\left(v, \phi_{T}v_{0}\right)<\varepsilon, \; d_{g_{1}^{s}}\left(\phi_{t_{0}}v, \phi_{T}v_{0}\right)<\varepsilon 
\end{equation}


and


\begin{equation}\label{eqtn, EqtnKappa}
\int_{0}^{t_{0}} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-t_{0} \cdot S\left(g_{1}, g_{2}\right)>-\kappa 
\end{equation}


For a fixed given $T \in \R$, define $ C_0 =  C_0(T) := \max_{v \in S^{g_{1}} M} \| D\phi^{g_{1}}_T(v) \|$ where the norm is taken
with respect to the Sasaki metric $g^s_1$. Then for all $v, w \in S^{g_{1}} M $ we have

$$
d_{g_{1}^{s}}\left(\phi_{T}^{g_{1}}v, \phi_{T}^{g_{1}}w \right) \leq C_{0} d_{g_{1}^{s}}(v, w).
$$

Since $\mathcal{H}_{g_{1}, g_{2}}(v_{0}, v_{0}) =0$, for every $\varepsilon >0$ and $\kappa >0$ and $\tau_0>0$, there exists  $t_0 \geq \tau_0$ and $w \in  S^{g_{1}} M$ such that 
$$
d_{g_{1}^{s}}\left(w, v_0\right)<\frac{\varepsilon}{2 C_0} \;\; \text{and} \; \; d_{g_{1}^{s}}\left(\phi_{t_0}^{g_{1}}w, v_0\right)<\frac{\varepsilon}{2 C_0}
$$
as well as

$$
\int_{0}^{t_{0}} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} w\right) d s-t_{0} \cdot S\left(g_{1}, g_{2}\right)>-\frac{\kappa}{2} .
$$

Hence, for  $v=\phi_{T}^{g_{1}}(w)$ we obtain
$$
d_{g_{1}^{s}}\left(v, \phi_{T}^{g_1}v_{0}\right) = d_{g_{1}^{s}}\left( \phi_{T}^{g_1} w, \phi_{T}^{g_1}v_{0}\right) \le C_0 d_{g_{1}^{s}}\left(w, v_{0}\right) < \varepsilon
$$
and
$$
d_{g_{1}^{s}}\left(\phi_{t_{0}}^{g_1} v, \phi_{T}^{g_1}v_{0}\right) = d_{g_{1}^{s}}\left( \phi_{T}^{g_1} \phi_{t_{0}}^{g_1}w, \phi_{T}^{g_1}v_{0}\right) \le C_0 d_{g_{1}^{s}}\left(\phi_{t_{0}}^{g_1}w, v_{0}\right) < \varepsilon
$$
which yields inequalities \eqref{eqtn, EquationVV_0}. Furthermore
$$
\begin{aligned}
& \int_{0}^{t_{0}} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-t_{0} \cdot S\left(g_{1}, g_{2}\right) \\
= & \int_{-T}^{t_{0}-T} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-t_{0} \cdot S\left(g_{1}, g_{2}\right)+\left(\int_{t_{0}-T}^{t_{0}} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-\int_{-T}^{0} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s\right) \\
= &\int_{0}^{t_{0}} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} w\right) d s-t_{0} \cdot S\left(g_{1}, g_{2}\right)+\left(\int_{t_{0}-T}^{t_{0}} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-\int_{-T}^{0} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s\right) \\
> & -\frac{\kappa}{2}+\int_{-T}^{0}\left(a_{g_{1}, g_{2}}\left(\phi_{t_{0}+s}^{g_{1}} v\right)-a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right)\right) d s .
\end{aligned}
$$
Since 
\begin{align*}
d_{g_{1}^{s}}\left( v, \phi_{t_{0}}^{g_{1}} v\right) &= d_{g_{1}^{s}}\left(\phi_T^{g_{1}} w, \phi_T^{g_{1}}\phi_{t_{0}}^{g_{1}} w\right)\leq C_{0} d_{g_{1}^{s}}\left( w, \phi_{t_{0}}^{g_{1}} w\right) \\
&\leq C_{0}\big(d_{g_{1}^{s}}\left(w, v_{0}\right)+d_{g_{1}^{s}}\left(v_{0}, \phi_{t_{0}}^{g_{1}} w\right)\big) < \varepsilon.
\end{align*}
If $T>0$, choosing $\varepsilon$ sufficiently small,
the continuity of $a_{g_{1}, g_{2}}$ and the Lipschitz  continuity of $\phi_{s}^{g_{1}}$ for $s \in[-T, 0]$
$$
\int_{-T}^{0}\left|a_{g_{1}, g_{2}}\left( \phi_{s}^{g_{1}} \phi_{t_{0}}^{g_{1}} v\right)-a_{g_{1}, g_{2}}\left( \phi_{s}^{g_{1}}v\right)\right| d s<\frac{\kappa}{2} .
$$
 If $T<0$, consider $s\in [0,-T]$. The proof is the same. This yields Inequality \eqref{eqtn, EqtnKappa} and therefore $\mathcal{H}_{g_{1}, g_{2}}\left(\phi_{T}^{g_{1}}\left(v_{0}\right), \phi_{T}^{g_{1}}\left(v_{0}\right)\right)=0$.
\end{proof}


We next show that the Mather set is contained in the Peierls barrier zero set $\mathcal{H}_{0}(g_1, g_2)$. 



 \begin{proposition} \label{prop,ManeAubrySet}

Let $g_{1}, g_{2} \in R^{-}(M)$. The Mather set satisfies

$$
\mathcal{M}(g_1,g_2) \subset \mathcal{H}_{0}(g_1, g_2)
$$
 \end{proposition}
 \begin{proof}
     This proposition can be viewed as a corollary of Proposition \ref{prop, AubryMather}. Take a strong supersolution $u$. In Proposition \ref{prop, AubryMather}, we have showed that if $m \in MS(g_1,g_2)$ and if $f:S^{g_1}M\to \mathbb{R}_{\geq 0}$ is the function given by
     $$f(v):=S(g_1,g_2)-a_{g_1,g_2}+X_{g_1}u(v),$$
     then $f$ vanishes on $\supp m$. From Poincare's Recurrence Theorem, we know that $m$-almost every point is recurrent. Suppose $v_0\in \supp m $ is recurrent. Then there exists $t_n\to \infty$ so that $d_{g_{1}^{s}}\left( v_0, \phi_{t_n}^{g_{1}} v_0\right) \to 0$ when $n\to \infty$ and
\begin{align*}
\int_{0}^{t_n} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v_0\right) d s-t_n\cdot S\left(g_{1}, g_{2}\right) & =u\left(\phi_{t_n}^{g_{1}} v_0\right)-u(v_0). 
\end{align*}
 This implies $\mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right)=0$. 

Suppose $v_0\in\supp m$ is not recurrent. Then since non-recurrent points form a null set, every open neighborhood of $v_0$ must contain recurrent points. Therefore  $\mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right)=0$ by closeness of the subset  $\mathcal{H}_{0}(g_1, g_2)$. This shows0  $\supp  m \subset \mathcal{H}_{0}(g_1, g_2)$ for any $ m \in MS(g_1,g_2)$. 

Finally, since $\mathcal{H}_{0}(g_1, g_2)$ is closed, we conclude
$$
\mathcal M(g_1, g_2) = \overline{\bigcup_{m \in MS(g_1,g_2)}\supp m} \subset \mathcal{H}_{0}(g_1, g_2).
$$
 \end{proof}


In the end, we show that the set $\mathcal{H}_{0}(g_1, g_2)$ is contained in the Aubry set $\mathcal{A}(g_1,g_2)$.

 \begin{proposition} \label{prop,ManeAubrySet}

Let $g_{1}, g_{2} \in R^{-}(M)$ and let $u$ be any weak supersolution for $a_{g_1,g_2}$. Then the Aubry set $\mathcal{A}_u\left(g_{1}, g_{2}\right)$ of $u$ satisfes

$$
\mathcal{H}_{0}(g_1, g_2) \subset \mathcal{A}_u\left(g_{1}, g_{2}\right).
$$
In particular, we have 
$$
\mathcal{H}_{0}(g_1, g_2) \subset \mathcal{A}\left(g_{1}, g_{2}\right).
$$
 \end{proposition}


\begin{proof} 
    We first show that if $v_{0}$ satisfies $\mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right)=0$, then it is in $\mathcal{A}_u\left(g_{1}, g_{2}\right)$. Given a weak supersolution $u$, we find a nonpositive cocycle $c_u$. Let us fix a finite positive constant $\tau_0$ and consider $t\geq \tau_0$. We have
$$
\begin{aligned}
\int_{0}^{t} a_{g_{1}, g_{2}}\left(\phi_{s}^{g_{1}} v\right) d s-t\cdot S\left(g_{1}, g_{2}\right) & =c_u(v,t) +u\left(\phi_{t}^{g_{1}} v\right)-u(v) \\
& \leq c_u(v,\tau_0)+u\left(\phi_{t}^{g_{1}} v\right)-u(v).
\end{aligned}
$$

This implies, by finding positive $t$ and vectors $v$ so that $v \rightarrow v_{1}$ and $\phi_{t}^{g_{1}}(v) \rightarrow$ $v_{2}$, together with the continuity of $u$ and $c_u$,

$$
\mathcal{H}_{g_{1}, g_{2}}\left(v_{1}, v_{2}\right) \leq c_u(v_1,\tau_0)+u\left(v_{2}\right)-u\left(v_{1}\right) .
$$

When $v_{0}=v_{1}=v_{2}$ and $\mathcal{H}_{g_{1}, g_{2}}\left(v_{0}, v_{0}\right)=0$, we obtain $c_u(v_0,\tau_0)=0$. Since $c_u$ in monotone nonincreasing in $t$, we obtain $c_u(v_0,t)=0$ for $t\leq \tau_0$.  Because $\tau_0$ is arbitrarily chosen, we conclude for any $t\geq 0$,
$$c_u(v_0,t)=0,$$ 
and hence
$v_{0} \in \mathcal{A}_{u}\left(g_{1}, g_{2}\right)$.


\end{proof} 


 \begin{remark}
     We do not know if $\mathcal{H}_{0}(g_1, g_2)$ coincides with our definition of the Aubry set.  However, some authors define
  $\mathcal{H}_{0}(g_1, g_2)$ as the Aubry set (see for example \cite{FS04}).
 \end{remark}




\subsubsection{Reverse triangle inequality of the Peierls barrier}
We show that the Peierls barrier satisfies the reverse triangle inequality in this subsection. We denote for a fixed $\varepsilon >0$,

\begin{align*}
\mathcal{H}^{\varepsilon}_{g_{1}, g_{2}}(v_{1}, v_{2}):= 
\lim_{t\to \infty} \sup\bigg\{&\int_{0}^{t} a_{g_{1}, g_{2}}(\phi_{s}^{g_{1}} v) d s-t \cdot S(g_{1}, g_{2}) \mid  \\ 
 & d_{g_{1}^{s}}\left(v, v_{1}\right)<\varepsilon, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{2}\right)<\varepsilon \bigg\},
\end{align*}
and further for a fixed $T>0$, denote
\begin{align*}
\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{1}, v_{2}):= 
\ \sup\ \bigg\{ &\int_{0}^{t} a_{g_{1}, g_{2}}(\phi_{s}^{g_{1}} v) d s-t \cdot S(g_{1}, g_{2}) \mid t\geq T \\ 
  & \quad d_{g_{1}^{s}}\left(v, v_{1}\right)<\varepsilon, d_{g_{1}^{s}}\left(\phi_{t}^{g_{1}}v, v_{2}\right)<\varepsilon \bigg\}.
\end{align*} Note that $\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{1}, v_{2})$ monontone decreases to $\mathcal{H}^{\varepsilon}_{g_{1}, g_{2}}(v_{1}, v_{2})$ when  $T\to \infty$ and $\mathcal{H}^{\varepsilon}_{g_{1}, g_{2}}(v_{1}, v_{2})$ monotone decreases in $ \varepsilon$  as $ \varepsilon \to 0$ and converges to the Peierls barrier $\mathcal{H}_{g_{1}, g_{2}}\left(\cdot, \cdot\right) $.
Moreover, $\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{1}, v_{2})$ is monontone decreasing in $\varepsilon$ with limit $ \lim\limits_{\varepsilon \to 0}\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{1}, v_{2}) $. 

In the sequel, we need the following simple version of the shadowing Lemma. See \cite[Theorem 18.3.14]{KH95} for a general version.

\begin{lemma}[Shadowing Lemma]\label{lem, shadowing}
Let $(M, g)$ be a complete manifold of strictly negative curvature. Then for every 
$\varepsilon>0$, there exists $\delta>0$ such that for all $w_1, w_2\in S^{g}M$ and $t_1,t_2 >0$ with
        $d_{g^s}(\phi^g_{t_1}w_1,w_2) < \delta$,
    there exists some $w\in S^{g}M$ with
    $$
   d_{g^s} (\phi_t^{g}w, \phi_t^{g}w_1)< \varepsilon  \; \text{if} \; \; 0\leq t\leq t_1,
   $$
 and    
    $$
   d_{g^s} (\phi_{t}^{g}w, \phi_{t-t_1}^{g}w_2)< \varepsilon \; \text{if} \; \; t_1\leq t\leq t_1+t_2. 
   $$
\end{lemma}     
\begin{proposition}[Reverse triangle inequality] \label{prop,reverseTriangle}
The Peierls barrier satisfies for all $T>0$ and all
 $v_1,v_2,v_3\in S^{g_1}M$,

$$\mathcal{H}_{g_{1}, g_{2}}\left(v_1, v_3\right)\geq \mathcal{H}_{g_{1}, g_{2}}\left(v_1, v_2\right)+ 
\lim\limits_{\varepsilon \to 0}\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{2}, v_{3}).$$
In particular, it satisfies the reverse triangle inequality, that is,
$$\mathcal{H}_{g_{1}, g_{2}}\left(v_1, v_3\right)\geq \mathcal{H}_{g_{1}, g_{2}}\left(v_1, v_2\right)+ 
 \mathcal{H}_{g_{1}, g_{2}}\left(v_2, v_3\right).$$



\end{proposition} 
\begin{proof}

  For $(M, g_1)$ and  $\varepsilon>0$, choose $\delta >0$ as in the shadowing Lemma \ref{lem, shadowing}.
  Consider the (not necessarily distinct) vectors $v_1,v_2,v_3 \in S^{g_1}M$ and let $T$ be any positive number. By the definition of $\mathcal{H}^{\frac{\delta}{2}}_{g_{1}, g_{2}}$, for any $\kappa>0$ and any $T_1>0$, there exists $w_1$ and $t_1>T_1$ such that 
    \begin{equation} \label{eqtn, v1v2}
        d_{g_1^s}(v_1,w_1) < \frac{\delta}{2}, \quad d_{g_1^s}(v_2,\phi^{g_1}_{t_1}w_1) < \frac{\delta}{2},
     \end{equation}
and
    $$\mathcal{H}^{\frac{\delta}{2}}_{g_{1}, g_{2}}(v_{1}, v_{2})-\kappa \leq b^{g_2}_{(w_1)^{g_1}_{+}} (\pi w_1, \pi \phi^{g_1}_{t_1}w_1)-t_1 S(g_1,g_2).$$
By the definition of  $\mathcal{H}^{\frac{\delta}{2},T}_{g_{1}, g_{2}}$, for any $\kappa >0$,  
there exists $w_2$ and $t_2\geq T$ such that
  \begin{equation}\label{eqtn, v2v3}
  d_{g_1^s}(v_2,w_2) < \frac{\delta}{2}, \quad d_{g_1^s}(v_3,\phi^{g_1}_{t_2}w_2) < \frac{\delta}{2},
  \end{equation}
and 
  $$\mathcal{H}^{\frac{\delta}{2},T}_{g_{1}, g_{2}}(v_{2}, v_{3})-\kappa \leq b^{g_2}_{(w_2)^{g_1}_{+}} (\pi w_2, \pi \phi^{g_1}_{t_2}w_2)-t_2 S(g_1,g_2)$$
  holds.
This in particular implies
$$
d_{g_1^s}(\phi^{g_1}_{t_1}w_1,w_2) \le d_{g_1^s}(\phi^{g_1}_{t_1}w_1,v_2) + d_{g_1^s}(v_2, w_2) < \delta.
$$
The shadowing Lemma yields the existence of
 $w\in S^{g_1}M$ with
   \begin{equation}\label{eqtn, ww_1}
  d_{g_1^s} (\phi_t^{g_1}w, \phi_t^{g_1}w_1)< \varepsilon, \qquad  0\leq t\leq t_1,
     \end{equation}
and    
    \begin{equation}\label{eqtn, ww_2}
  d_{g_1^s} (\phi_{t}^{g_1}w, \phi_{t-t_1}^{g_1}w_2)< \varepsilon, \qquad  t_1\leq t\leq t_1+t_2. 
  \end{equation}

This  together with the inequalities \eqref{eqtn, v2v3} and \eqref{eqtn, ww_1}  implies
     $$ d_{g_1^s}(v_1,w) \le d_{g_1^s}(v_1,w_1 ) + d_{g_1^s}(w_1,w)< \varepsilon+ \frac{\delta}{2} $$
and
$$
d_{g_1^s} (v_3,\phi_{t_1+t_2}^{g_1}w)< d_{g_1^s} (v_3,\phi^{g_1}_{t_2}w_2)+  d_{g_1^s} (\phi^{g_1}_{t_2}w_2, \phi
_{t_1+t_2}^{g_1}w)< \varepsilon+\frac{\delta}{2}.
$$
Furthermore, we can choose $T_1 > 0$ such that
      \begin{align*}
         \mathcal{H}^{\varepsilon+\frac{\delta}{2}}_{g_{1}, g_{2}}(v_{1}, v_{3}) 
         \geq \mathcal{H}^{\varepsilon+\frac{\delta}{2},T_1}_{g_{1}, g_{2}}(v_{1}, v_{3}) -\kappa.
     \end{align*}
     Since  $t_1+t_2\geq T_1+T> T_1$, it follows
     \begin{align*}
\mathcal{H}^{\varepsilon+\frac{\delta}{2}}_{g_{1}, g_{2}}(v_{1}, v_{3})&  
         \geq b^{g_2}_{w^{g_1}_+}(\pi w, \pi \phi^{g_1}_{t_1+t_2}w) -(t_1+t_2) S(g_1,g_2)-\kappa\\
         &\geq  b^{g_2}_{w^{g_1}_+}(\pi w, \pi \phi^{g_1}_{t_1}w) -t_1 S(g_1,g_2) \\
        &  \quad + b^{g_2}_{w^{g_1}_+}(\pi \phi^{g_1}_{t_1}w, \pi \phi^{g_1}_{t_1+t_2}w) -t_2 S(g_1,g_2)-\kappa.
\end{align*}
         By continuity of the Busemann cocycle (see Subsection \ref{busemann cocycle}), for any $\eta>0$, their exists $\varepsilon_\eta >0$ such that 
         $$b^{g_2}_{{w}^{g_1}_+}(\pi w, \pi \phi^{g_1}_{t_1}w) \geq b^{g_2}_{({w_1})^{g_1}_+}(\pi w_1, \pi \phi^{g_1}_{t_1}w_1)-\eta,$$
         and 
          $$b^{g_2}_{w^{g_1}_+}(\pi \phi^{g_1}_{t_1}w, \pi \phi^{g_1}_{t_1+t_2}w) \geq b^{g_2}_{(w_2)^{g_1}_+}(\pi w_2, \pi \phi^{g_1}_{t_2}w_2)-\eta.$$
          provided $ \varepsilon \le \varepsilon_\eta $
          Hence for all  $ \varepsilon \le \varepsilon_\eta $ we have
         \begin{align*}
\mathcal{H}^{\varepsilon+\delta}_{g_{1}, g_{2}}(v_{1}, v_{3})
         &\geq b^{g_2}_{{w_1}^{g_1}_+}(\pi w_1, \pi \phi^{g_1}_{t_1}w_1) -t_1 S(g_1,g_2) \\
         & \quad +b^{g_2}_{({w_2})^{g_1}_+}(\pi w_2, \pi \phi^{g_1}_{t_2}w_2) -t_2 S(g_1,g_2)-\kappa-2\eta \\
         &\geq \mathcal{H}^{\frac{\delta}{2}}_{g_{1}, g_{2}}(v_{1}, v_{2})+\mathcal{H}^{\frac{\delta}{2},T}_{g_{1}, g_{2}}(v_{2}, v_{3}) -3\kappa-2\eta
     \end{align*}

     Taking the limits $\varepsilon \to 0$, $\delta=\delta(\varepsilon)\to 0$  we obtain
$$
\mathcal{H}_{g_{1}, g_{2}}(v_{1}, v_{3}) \ge \mathcal{H}_{g_{1}, g_{2}}(v_{1}, v_{2})+\lim\limits_{\varepsilon \to 0}\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{2}, v_{3}) -3\kappa-2\eta
$$
for all $\kappa, \eta >0$.  This yields the first inequality. The second inequality is a consequence of
$   \mathcal{H}_{g_{1}, g_{2}}(v_{2}, v_{3})  \le \lim\limits_{\varepsilon \to 0}\mathcal{H}^{\varepsilon,T}_{g_{1}, g_{2}}(v_{2}, v_{3}).$
     \end{proof}














\section{Maximal stretch and thermodynamic formalism} \label{section,thermodynamics}
\subsection{The Mather set and measures of maximal entropy } \label{subsection,MMEMatherSet}
\hfill\\
In this section, we use tools from the thermodynamic formalism to study the maximal stretch $S(g_1,g_2)$ and maximally stretched measures. We refer the readers to \cite{Bo08} for a good survey on the subject of thermodynamic formalism which has a close relation with statistic physics.



We will establish a connection between the theory of equilibrium states, measures of maximal entropy, and the study of the Mather set. A starting observation is that the maximal stretch can be expressed via the \emph{pressure function} in thermodynamic formalism. We recall that the \emph{pressure (function)} of the potential $r a_{g_1,g_2}$  is given by the following \emph{variational principle},
 $$\mathbf{P}(r a_{g_1, g_2})=\sup\limits_{m\in \mathcal{M}^1(\phi^{g_1})} \big(h_{m}(\phi^{g_1})  +\int r a_{g_1,g_2} dm ).$$

 The above supremum is realized by a unique $\phi^{g_1}$-invariant probability measure $m_{ra_{g_1,g_2}}$, called the \emph{equilibrium state} of the potential $r a_{g_1,g_2}$.
In statistical mechanics, the scaling constant $r$ is interpreted as the inverse of the temperature $r=\frac{1}{T}$.  When the temperature $T=\frac{1}{r} \to 0$, the potential energy $E(m)=\int a_{g_1,g_2} dm =I_m(g_1,g_2)$
becomes the dominating term in the pressure function. This motivates the following.


\begin{lemma}
    Given $g_1,g_2\in R^-(M)$, the maximal stretch satisfies
    $$S(g_1,g_2)= \lim\limits_{r\to \infty} \frac{\mathbf{P}(r a_{g_1, g_2})}{r}.$$
\end{lemma}
\begin{proof}
    By variational principle, 
    \begin{align*}
        \mathbf{P}(r a_{g_1, g_2})&=\sup\limits_{m\in \mathcal{M}^1(\phi^{g_1})} \big(h_{m}(\phi^{g_1})  +\int r a_{g_1,g_2} dm \big)\\
        &\leq \sup\limits_{m\in \mathcal{M}^1(\phi^{g_1})} h_{m}(\phi^{g_1})  + \sup\limits_{m\in \mathcal{M}^1(\phi^{g_1})} \int r a_{g_1,g_2} dm   \\
         &= h_{top}(\phi^{g_1})+ r S(g_1,g_2).
          \end{align*}
    On the other hand, since $h_m(\phi^{g_1})\geq 0$, it also holds  
    $$\mathbf{P}(r a_{g_1, g_2}) \geq \sup\limits_{m\in \mathcal{M}^1(\phi^{g_1})} \int r a_{g_1,g_2} dm = rS(g_1,g_2).$$
    The result follows from a combination of the two inequalities.     
\end{proof} 



To simplify our notation, we denote the equilibrium states $m_{ra_{g_1,g_2}}$ as $m_r$. Up to subsequences, the measures $m_{ra_{g_1,g_2}}$ converge in weak * topology to some weak limits when $r\to \infty$. These weak limits are called the \emph{zero-temperature limits} of equilibrium states. 

In the following, we show that \emph{zero-temperature limits} are maximally stretched measures.


\begin{lemma}\label{lemma,weaklimitEquilibriumStates}
    Each weak limit $m_+=\lim\limits_{n\to\infty} m_{r_n}$ of the equilibrium states for some subsequence $r_n\to \infty$ is a maximally stretched measure.
\end{lemma}

\begin{proof}
   For all $m \in \mathcal{M}^1(\phi^{g_1})$, we have
\begin{eqnarray*}
h_m(\phi^{g_1}) + r \int a_{g_1, g_2} dm &\le & \mathbf{P}(r a_{g_1, g_2})  \\
&=&  h_{m_{r}} (\phi^{g_1})+r \int a_{g_1, g_2}dm_{r}.
\end{eqnarray*}
This implies
$$
\int a_{g_1, g_2}dm_{r} - \int a_{g_1, g_2} dm  \ge \frac{1}{r}\big(  h_{m} (\phi^{g_1})- h_{m_r}(\phi^{g_1}) \big).
$$
Let $r \to  \infty$. The right hand side goes to zero. We obtain, for each weak limit $m_+ := \lim\limits_{n \to \infty} m_{r_n}$ of some subsequence $\{r_n\}$,
 $$ \int a_{g_1, g_2}dm_+ \ge  \int a_{g_1, g_2} dm.$$
 Therefore
$$ \int a_{g_1, g_2}dm_+ =\sup_{m\in\mathcal{M}^{1}(\phi^{g_1})} \int a_{g_1, g_2}dm=S(g_1,g_2),$$
and $m_+$ is a maximally stretched measure.
\end{proof}








We next show that a zero-temperature limit $m_+$ is a measure of maximal entropy of the geodesic flow $\phi^{g_1}$ when restricted to the Mather set $\M(g_1,g_2)$.

\begin{theorem}[Measures of maximal entropy for $\mathcal{M}(g_1,g_2)$]
\label{prop,limitIsTopEntropy}
   Any zero temperature limit $m_+$ is a measure of maximal entropy of the geodesic flow $\phi^{g_1}$ restricted to the Mather set $\M(g_1,g_2)$, i.e.
$$h_{m_{+}} (\phi^{g_1}) = h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2)),$$
    where $h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))$ is the topological entropy of $\phi^{g_1}$ on the closed invariant subset $\mathcal{M}(g_1,g_2)$ and $h_{m_{+}} (\phi^{g_1})$ denotes the metric entropy of $m_+$. 
\end{theorem}
\begin{proof}
    We first give an argument that any $\phi^{g_1}$-invariant probability measure $m$ with support in $\mathcal{M}(g_1,g_2)$ is maximally stretched. By Birkhoff's ergodic Theorem for invariant measures, we have
   $$\int_{\mathcal{M}(g_1,g_2)} a_{g_1,g_2}dm =\int_{\mathcal{M}(g_1,g_2)} \lim_{T\to\infty} \frac{1}{T}\int_0^T a_{g_1,g_2}(\phi^{g_1}_tx)dtdm(x).$$

   If $x\in \supp(m)\subset \mathcal{M}(g_1,g_2)$ and the above time average exists, then since $\mathcal{M}(g_1,g_2)$ is contained in the Aubry set $ \mathcal{A}(g_1,g_2)$, it follows from the definition of $ \mathcal{A}(g_1,g_2)$ that 
   $$\lim_{T\to\infty} \frac{1}{T}\int_0^T a_{g_1,g_2}(\phi^{g_1}_tx)dt = S(g_1,g_2).$$ 

    Combining the above estimates together yields that any $\phi^{g_1}$-invariant probability measure $m$ with support in $\mathcal{M}(g_1,g_2)$ is maximally stretched. Hence for any such measure and any  $r>0$, by variational principle,
\begin{align*}
    h_{m}(\phi^{g_1}) +r\int a_{g_1,g_2} dm_r &\leq h_{m}(\phi^{g_1})+r\int a_{g_1,g_2} dm\\
    &\leq h_{m}(\phi^{g_1}) +r\int a_{g_1,g_2} dm_r.
    \end{align*}
    Therefore, $ h_{m}(\phi^{g_1}) \leq \inf\limits_{r> 0} h_{m_r}(\phi^{g_1}) $. 

    Again, applying variational principle to the geodesic flow $\phi^{g_1}$ restricted to $\mathcal{M}(g_1,g_2)$ and the potential function $0$ yields
    $$ \max_{m \in MS(g_1,g_2)} h_{m}(\phi^{g_1})
   = h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2)) \leq \inf\limits_{r> 0}h_{m_r}(\phi^{g_1}). $$

    Since the metric entropy $m \to h_m (\phi^{g_1})$ is upper semi-continuous (see, for example, \cite[Theorem 8.2]{Wa82}), we obtain the following.

    $$\limsup_{r \to \infty} h_{m_r}(\phi^{g_1}) \leq h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2)).$$
    This implies for any maximally stretched measure $m_+$ arising as limits of equilibrium states, we have
    $$h_{m_{+}} ( \phi^{g_1})= h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))=\inf\limits_{r>0} h_{m_r}(\phi^{g_1}),$$
    and therefore, each such measure has maximal
 entropy on the Mather set.

\end{proof}



 Lemma \ref{lemma,weaklimitEquilibriumStates} guarantees the existence of maximally stretched measures arising as limits of equilibrium states. Nevertheless, these  maximally stretched measures are in general not equilibrium states because of the following.
\begin{remark}
We make following remarks regarding whether maximally stretched measures can be equilibrium states of some potential functions.
\begin{itemize}
    \item If  $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) > 1$ for $g_1, g_2 \in R^-(M)$,  maximally stretched measures for $g_1,g_2$ cannot be equilibrium states. The reason is that according to Theorem \ref{thm, EmtpyInterior}, the support of a maximally stretched measure does not contain any open set. On the other hand, by Theorem 3.3 of \cite{BR75}, the equilibrium states of the Anosov flows have full support. 
    \item If $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2)=1$, Theorem \ref{thm, EmtpyInterior} implies
$\mathcal{M}(g_1,g_2)=S^{g_1}M$. Since
by Theorem \ref{prop,limitIsTopEntropy}, a maximally stretched measure arising as limits of equilibrium states is a measure of maximal entropy (i.e. the Bowen-Margulis measure for $\phi^{g_1}$) and is the equilibrium state for the potential function $0$.
\end{itemize}
\end{remark}



\subsection{Further discussion of metric entropy}
We continue to characterize the behaviors of metric entropy of equilibrium states $m_r$ of potentials $r a_{g_1,g_2}$ and their zero-temperature limits in this subsection.
We will see in Proposition \ref{prop,EquilibriumStateLimit} that if a maximally stretched measure $m_+$ is a zero-temperature limit, i.e. it arises as a weak limit of equilibrium states $m_{r_n}$, then the metric entropy of $m_{r_n}$ converges to the metric entropy of $m_{+}$ in a monotone manner. 


We start from the following proposition.

\begin{proposition} \label{prop, MonotoneMetricEntropy}
    The function $r\mapsto h_{m_r}(\phi^{g_1})$ is analytic. Moreover, 
    $$ \frac{ \partial h_{m_r}(\phi^{g_1})} {\partial r} =-r  \cdot \textnormal{Var} (P_{m_r}(a_{g_1,g_2}), m_r),$$
    where the \emph{variance} of a mean zero Hölder function $f: S^{g_1}M \to \R$ with respect to $m_r$ is given by
    \begin{equation}
    \mathrm{Var}(f,m_r)= \lim_{T\to\infty} \frac{1}{T} \int_{ S^{g_1}M}  \left( \int_{0}^{T} f(\phi_{s}(v))\mathrm{d}s \right) ^2 \mathrm{d}m_r(v),
    \label{eq:Var}
\end{equation}
and the projection operator $P_{m_r}$ is defined as $P_{m_r}(f)(v):= f(v)- \int f \mathrm{d}m_r$. 
\end{proposition}
\begin{proof}
We recall from Remark \ref{remark,regularityTimeChange} that the infinitesimal time change $a_{g_1,g_2}$ is Hölder. By variational principle,
\begin{equation} \label{eqtn,PressureInVariableT}
 \mathbf{P}(r a_{g_1, g_2}) = h_{m_r}(\phi^{g_1}) + r\int a_{g_1,g_2}\mathrm{d}m_r. 
\end{equation}
We also know from thermodynamic formalism (see \cite[Proposition 4.10]{PP90}),
$$\int a_{g_1,g_2}\mathrm{d}m_r = \frac{d}{dr}  \mathbf{P}(r a_{g_1, g_2}).$$
This yields
\begin{equation} \label{eqtn,entropy}
h_{m_r}(\phi^{g_1}) = \mathbf{P}(r a_{g_1, g_2}) -r \frac{d}{dr}  \mathbf{P}(r a_{g_1, g_2}).
\end{equation}
Since the pressure $\mathbf{P}(ra_{g_1,g_2})$ is analytic in $r$, it follows that  $r\mapsto h_{m_r}(\phi^{g_1})$ is analytic as well. Furthermore, $h_{m_0}(\phi^{g_1}) = h_{top} (\phi^{g_1})$ and therefore $m_0 =  m^{g_1}_{BM}$.

Now taking a derivative on both sides of the Equation  \eqref{eqtn,entropy} yields
 \begin{equation}  \label{eqtn,derivativeOfT}  
\frac{d}{dr} h_{m_r}(\phi^{g_1})=-r  \frac{d^2}{dr^2} \mathbf{P}(r a_{g_1, g_2}) 
 =  -r\cdot \mathrm{Var}(P_{m_r}(a_{g_1,g_2}),m_r),
\end{equation}
where the deduction of second derivative formulas of pressure functions can be found in \cite[Proposition 4.11]{PP90} and \cite[Corollary 2.2, Remark 2.25]{Da23}.

\end{proof}


Let us denote by $m^{g_1}_{BM}$ the Bowen Magulis measure of the geodesic flow $\phi^{g_1}$ on $S^{g_1}M$.
\begin{corollary}\label{cor,dichotomyEntropy}
The following dichotomy holds.
\begin{itemize}
    \item  If  $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) =1$, then the metric entropy satisifes, for $r >0$,
    $$  h_{m_r}(\phi^{g_1}) \equiv h_{top}(\phi^{g_1}),$$ 
    and so $$m_r\equiv m^{g_1}_{BM}.$$
   \item 
   If  $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) >1,$ then $h_{m_r}(\phi^{g_1})$ strictly decreases when $r$ increases. 

\end{itemize}
   \begin{proof}
       From the equation,
       $$ \frac{d}{dr} h_{m_r}(\phi^{g_1}) 
=-r  \cdot \textnormal{Var} (P_{m_r}(a_{g_1,g_2}), m_r),$$ 
 it follows that  $h_{m_r}(\phi^{g_1}) $ is a constant independent of $r$ if and only if the variance is zero. From the properties of the variance (\cite[Proposition 4.12]{PP90}), $\textnormal{Var} (P_{m_r}(a_{g_1,g_2}), m_r)=0$ if and only if $a_{g_1,g_2}$ is cohomologous to the constant $\int a_{g_1,g_2} \mathrm{d}m_r$, or equivalently, the marked length spectra of $g_1$ and $g_2$ are proportional (Corollary \ref{cor:equiv}). This yields the first item by Theorem \ref{thm, EmtpyInterior}. If  $a_{g_1,g_2}$ is not cohomologous to a constant, then $\textnormal{Var} (P_{m_r}(a_{g_1,g_2}), m_r)>0$ and therefore the second item follows.
   \end{proof} 

\end{corollary}



\begin{proposition} \label{prop,EquilibriumStateLimit}
    Suppose a maximally stretched measure $m_+$ is a zero-temperature limit, that is, it arises as a weak limit of equilibrium states $m_{r_n}$ for some sequence $r_n \to \infty$. Then 
    \begin{equation} \label{eqtn,MetricEntropyLimit}
        h_{m_+}(\phi^{g_1})=\lim\limits_{n\to \infty} h_{m_{r_n}}(\phi^{g_1}).
    \end{equation}
    Moreover, $h_{m_{r_n}}(\phi^{g_1})$ converges monotonically to $h_{m_+}(\phi^{g_1})$ as $n\to \infty$.
\end{proposition}
\begin{proof}
    If   $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) =1$,  then by Theorem \ref{thm, EmtpyInterior}, the Mather set $\mathcal{M}(g_1,g_2)=S^{g_1}M$ and by Theorem \ref{prop,limitIsTopEntropy},
   $$h_{m_{+}}(\phi^{g_1})= h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))
   = h_{top}(\phi^{g_1}).$$
  On the other hand, by Corollary \ref{cor,dichotomyEntropy}, we have $ h_{m_r}(\phi^{g_1}) \equiv h_{top}(\phi^{g_1})$. Therefore we obtain Equation \eqref{eqtn,MetricEntropyLimit} for this case.

   If $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) >1$, by Corollary \ref{cor,dichotomyEntropy},  $r \mapsto h_{m_r}(\phi^{g_1}) $ strictly decreases. So by the proof of Theorem \ref{prop,limitIsTopEntropy},
$$h_{m_+}(\phi^{g_1})= \inf\limits_{r>0}h_{m_r}(\phi^{g_1})\leq \lim\limits_{n\to \infty} h_{m_{r_n}}(\phi^{g_1}) \leq h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))),$$
where the last inequality follows from the uppersemicontinuity of $m\to h_m (\phi^{g_1})$. Since $h_{m_{+}} (\phi^{g_1})= h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))$, Equality \eqref{eqtn,MetricEntropyLimit} now follows.
\end{proof}

Now we can relate the topological entropy of $\phi^{g_1}$ on $S^{g_1}M$ and the topological entropy of $\phi^{g_1}$ on $\mathcal{M}(g_1,g_2)$ by a precise formula.

\begin{corollary} \label{cor formulaTwoEntropy}
   We have the following formula relating $ h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))$ and $h_{top}(\phi^{g_1})$.
      \begin{equation*}
        h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))=h_{top}(\phi^{g_1}) - \int_0^\infty r  \textnormal{Var} (P_{m_r}(a_{g_1,g_2}), m_r) dr.
    \end{equation*}
\end{corollary}
\begin{proof}
    This is a combination of Proposition \ref{prop,EquilibriumStateLimit} and  Proposition \ref{prop, MonotoneMetricEntropy} together with Theorem \ref{prop,limitIsTopEntropy}.
\end{proof}

Combining Corollary \ref{cor formulaTwoEntropy} with the proof of Corollary \ref{cor,dichotomyEntropy}, we obtain the following main result of this subsection.

\begin{corollary}\label{cor,RigidityTopEntropy}
 Given $g_1,g_2\in R^-(M)$, the topological entropy on the Mather set $\M(g_1,g_2)$ satisfies
 $$h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))=h_{top}(\phi^{g_1})$$
if and only if the marked length spectra of $g_1$ and $g_2$ proportional, i.e. there exists a constant $C>0$ such that $\ell_{g_2}([\gamma])= C \ell_{g_1}([\gamma])$ for all $[\gamma]\in[\Gamma]$. 
\end{corollary}  


    In the end of this subsection, we come to a question that originally motivated the study in this section. When $\frac{h_{top} (\phi^{g_2})}{h_{top} (\phi^{g_1}) }S(g_1,g_2) >1$, we have that
    $$ h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))<  h_{top}(\phi^{g_1}).$$  A natural question is:  does the topological entropy $h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))$ vanish in this case? This is indeed the true for Teichmüller spaces: when $g_1,g_2$ are hyperbolic metrics on a closed surface representing distinct points in the Teichmüller space, a maximally stretched measure after symmetrization always gives a measured geodesic lamination and measured geodesic laminations have zero metric entropy (see Lemma 2.3.5 of \cite{Na03}). Therefore by Theorem \ref{prop,limitIsTopEntropy}, when $g_1,g_2$ are hyperbolic metrics, a zero-temperature limit satisifies
    $$h_{m_+}(\phi^{g_1})=h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))=0.$$
    However, for general negatively curved metrics $g_1,g_2$, we will see in Example \ref{MatherNotLamination} that the topological entropy $h_{top}(\phi^{g_1}, \mathcal{M}(g_1,g_2))$ can be positive.





















\section{Geodesic stretch and Lipschitz maps} \label{section, StretchLip}

Starting from this section, we turn our attention to Lipschitz maps.
Our final goal of this section is to relate the geodesic stretch of an invariant measure to the average ``stretch" of a Lipschitz map with respect to that measure  (see Section \ref{section, FunctionalGfirst}, Lemma \ref{lem, GeodesicStretchLipStretch} and Theorem \ref{prop,GeodesicToGeodesic}). This connection offers a new perspective of understanding geodesic stretches and maximal stretches. We begin by reviewing some basics of Lipschitz maps in Section \ref{section, PreliminaryLipMaps}.


\subsection{Some preliminaries on Lipschitz maps} \label{section, PreliminaryLipMaps}
\hfill\\
This section is classical. We discuss some properties of Lipschitz maps between Riemannian manifolds.  Recall $M = \widetilde{M}/\Gamma$ is a smooth closed manifold admitting Riemannian metrics of negative sectional curvature, where $\widetilde{M}$ is
the universal covering and $pr: \widetilde{M} \to M $ is the covering map and
$\Gamma$ is the group of covering transformations.
We denote by $C^{0}(M,M)$ the space of all
continuous maps from $M$  to $M$. The space $C^{0}(M,M)$ is a connected infinite dimensional Banach manifold (\cite[Chapter II. 11]{Ab63}).  
 We are interested in the subspace $C_{\id}^{0}(M,M)$ of $C^{0}(M,M)$ consisting of maps homotopic to the identity. 


 \begin{lemma}\label{lem, uniquelift}
     $f \in  C^{0}(M,M)$ is homotopic to the identity map if and only if there exists a unique lift $ \widetilde{f} : \widetilde{M} \to \widetilde{M}$ of $f$ such that $\widetilde{f}  \gamma = \gamma   \widetilde{f}$
for all $\gamma \in \Gamma$.
 \end{lemma}  
 \begin{proof}
     Assume that $f \in  C^{0}(M,M)$ is homotopic to the identity map, i.e. there exists a homotopy  $H(t,x)=H_t(x):[0,1] \times M \to M$ with $H_0 = \id$ and  $H_1= f$.
Let  $\widetilde H:[0,1] \times \widetilde{M} \to \widetilde{M}$ be the unique lift of $H$ such that $\widetilde H_0 = \id$.
This implies  $\widetilde H_t \gamma = \gamma \widetilde H_t $ for all $\gamma \in \Gamma$. Hence, $\widetilde {H_1} = \widetilde{f}$ is a lift of $f$ such that $\widetilde{f} \gamma = \gamma   \widetilde{f}$
for all $\gamma \in \Gamma$. \\
If $\widetilde{f'}$ is another lift of $f$ with $\widetilde{f'} \gamma = \gamma \widetilde{f'}$ for all $\gamma \in \Gamma
$. Then there exists $\gamma_0, \eta_0 \in \Gamma$ such that
 $\widetilde{f'} = \gamma_0 \widetilde{f} \eta_0$. Then 
 $$
 \gamma  \gamma_0 \eta_0\widetilde{f}   =\gamma  \gamma_0 \widetilde{f} \eta_0 = \gamma  \widetilde{f'} = \widetilde{f'}\gamma = \gamma_0 \widetilde{f} \eta_0 \gamma =\gamma_0 \eta_0 \gamma \widetilde{f},  
 $$
 which implies $\gamma  \gamma_0 \eta_0 = \gamma_0 \eta_0\gamma $ for all $\gamma \in \Gamma$, i.e.
 $\gamma_0 \eta_0 $ commutes with all element in $\Gamma$.  Recall $M = \widetilde{M}/\Gamma$ is a smooth closed manifold admitting Riemannian metrics of negative sectional curvature. So any abelian subgroup of $\Gamma$ is infinite cyclic by Preissman theorem (see \cite[Chapter 12.3]{DoC92}). This implies $\gamma_0\eta_0 = e$
 and therefore  $\widetilde{f'} =\gamma_0  \eta_0 \widetilde{f} =\widetilde{f}$. \\
 To prove the converse, we assume that $f \in  C^{0}(M,M)$ has a lift $\widetilde{f}$ such that
$\widetilde{f}\gamma = \gamma  \widetilde{f}$
for all $\gamma \in \Gamma$. We want to show that $f$ is homotopic to the identity. To see this, let us equip $M$ with a negatively curved metric $g$ and consider for each $x \in \widetilde{M} $ the unique constant speed geodesic $ \alpha_x: t \to \widetilde{f_t}(x) $ with $\widetilde{f_0}(x) =x$  and $\widetilde{f_1}(x) = \widetilde{f}(x)$ with respect to $g$. Since $\gamma \widetilde{f}(x) =\widetilde{f}\gamma(x)$ and $\gamma$ is an isometry with respect to $g$, we obtain that $\gamma \alpha_x: t\to \gamma \widetilde{f_t}(x)$ is the unique geodesic connecting $\gamma (x)$ and $\widetilde{f}\gamma(x)$ which is $\alpha_{\gamma x}$. Therefore $\gamma\widetilde{f_t}(x) = \widetilde{f_t}\gamma (x)$. The map $\widetilde{f_t}(x) : [0,1] \times \widetilde{M} \to \widetilde{M}$ is continuous and $\Gamma$-equivariant. It descends to a homotopy $H: [0,1] \times M \to M$ with $H(t,p) = pr \circ \widetilde{f_t}(x)$ where $pr (x) =p$.   
 \end{proof}



 Using the above lemma, we can therefore identify the space  $C_{\id}^{0}(M,M)$ with
$$
\mathcal{C}=\big\{\varphi \in C^{0}(\widetilde{M},\widetilde{M})  \;|  \; \varphi(\gamma x)=\gamma \varphi(x) \;, \forall x\in  \widetilde{M}, \gamma \in\Gamma \big\}.
$$
Moreover, a neagatively curved Riemannian metric $g$ on $\widetilde{M}$ induces a metric $d_{\mathcal{C},g} $ on $\mathcal{C}$ defined by
$$
d_{\mathcal{C},g}(\varphi, \psi) := \max_{x\in\widetilde{M}}
 d_g(\varphi(x), \psi(x)).
$$
 Since $d_g(\varphi(x), \psi(x))= d_g(\varphi(\gamma x), \psi(\gamma x))$ for all $\gamma \in \Gamma$ and $\varphi, \psi \in \mathcal{C}$, the maximum can be attained. The metric $ d_{\mathcal{C},g}$ is  $\Gamma$-invariant in the sense that,
 $$d_ {\mathcal{C},g}(\varphi \circ \gamma, \psi \circ \gamma)=d_ {\mathcal{C},g}(\varphi, \psi)$$ for all $\gamma \in \Gamma$ and $\varphi, \psi \in \mathcal{C}$. 
It induces a metric on $C_{\id}^{0}(M,M)$ and we will still denote it as $d_{\mathcal{C},g}$.

\begin{proposition}
    The metric space 
    $(\mathcal{C},d_{\mathcal{C},g})$ is a geodesic length space.  
\end{proposition} 



\begin{proof}
    Suppose $\varphi_0,\varphi_1 \in \mathcal{C}$. Given $x\in \widetilde{M}$, let $\alpha_{x}: [0,1] \longrightarrow \widetilde{M}$ be the unique geodesic with respect to $g$ connecting $\varphi_0(x)$ and $\varphi_1(x)$, i.e. 
$\alpha_{x}(0)=\varphi_0(x)$ and $\alpha_{x}(1)=\varphi_1(x)$ and with constant speed $\norm{\alpha'_x}_{g}=d_g(\varphi_0(x),\varphi_1(x))$.

 Define for $s\in[0,1]$ the map
$\psi_s: \widetilde{M}\longrightarrow\widetilde{M}$ as 
$\psi_s(x):= \alpha_{x}(s)$.
Then $\psi :[0,1] \times \widetilde{M} \to \widetilde{M} $ with $\psi(s,x) =\psi_s(x)$ is a homotopy with $\psi_0=\varphi_0$ and $\psi_1=\varphi_1$. 
Moreover, since $\varphi_0$, $\varphi_1$ are $\Gamma$-equivariant,
$\psi_s \in \mathcal{C}$. Therefore,
$$\psi_s(\gamma x)= \alpha_{\gamma x}(s) = \gamma \alpha_x(s) = \gamma  \psi_s(x).$$
The distance between $\psi_t$ and $\psi_s$ with respect to $d_{\mathcal{C},g}(\cdot, \cdot)$ is given by
$$d_{\mathcal{C},g}(\psi_t, \psi_s)= \max_{x\in\widetilde{M}} d_{g}( \alpha_x(t), \alpha_x(s)) = 
|s-t|\max_{x\in \widetilde{M}}  \norm{\alpha'_x}_{g}=|s-t| d_{\mathcal{C},g}(\varphi_0,\varphi_1)$$

Therefore $\{\psi_s\}$ is a geodesic connecting $\varphi_0$ and $\varphi_1$.

\end{proof}




Denote by $\mathcal{C}_{\Lip}(g_1,g_2)$ the space of Lipschitz maps in $\mathcal{C}$ with respect to metrics $g_1,g_2$ on $\widetilde{M}$.

\begin{proposition}  \label{prop,convexityLip}
   Let $g_1,g_2$ be the lifts of a pair of negatively curved metrics to $\widetilde M$
   and for $R >0$, denote by $\mathcal{C}_{R}(g_1,g_2)$ the subset of $\mathcal{C}_{\Lip}(g_1,g_2)$ with Lipschitz constants bounded by $R$. If $\mathcal{C}_{R_0}(g_1,g_2)$ is non-empty, it is a convex subset of $(\mathcal{C}_{R}(g_1,g_2),d_{\mathcal{C},g_2})$ for all $R \ge R_0$. In particular, $\mathcal{C}_{\Lip}(g_1,g_2)$ is a convex subset of  $(\mathcal{C},d_{\mathcal{C},g_2})$.
\end{proposition}
\begin{proof}
    Suppose $\varphi_0, \varphi_1 \in \mathcal{C}_{R_0}(g_1,g_2) $. Consider $\psi:[0,1] \times \widetilde{M} \to \widetilde{M}$ the geodesic homotopy with $\psi_0 = \varphi_0$ and $\psi_1 = \varphi_1$. We claim $\psi_s \in \mathcal{C}_{R_0}(g_1,g_2) $.
From the definition of the geodesic homotopy, it follows $\psi_s(x)=\alpha_x(s)$ for all $x\in \widetilde{M}$, where $\alpha_x:[0,1] \longrightarrow \mathbb{R}_{\geq 0} $ is the geodesic connecting $\varphi_0(x)$ and $\varphi_1(x)$. Since
$g_2$ is a metric of negative curvature, the map $s \to d_{g_2}(\alpha_x(s),\alpha_y(s))$ is a convex function. It is strictly convex when the geodesics $\alpha_x$ and $\alpha_y$ have no segment in common \cite[Theorem 2.2.1]{Jo97}. Therefore for any $x , y \in \widetilde{M}$,
\begin{align*}
d_{g_2}(\psi_s(x), \psi_s(y))&=d_{g_2}(\alpha_x(s),\alpha_y(s)) \\
&\leq s d_{g_2}(\alpha_x(0),\alpha_y(0)) + (1-s)d_{g_2}(\alpha_x(1),\alpha_y(1))\\
&=s d_{g_2}(\psi_0(x),\psi_0(y)) +(1-s) d_{g_2}(\psi_1(x),\psi_1(y)) )\\
&\leq (s\text{Lip}(\psi_0) +(1-s) \text{Lip}(\psi_1)) d_{g_1}(x,y)\\
&\leq \max \{\text{Lip}(\varphi_0),\text{Lip}(\varphi_1)\} d_{g_1}(x,y)
\end{align*}
 which implies $\psi_s \in \mathcal{C}_{R_0}(g_1,g_2) $.  
\end{proof}

Now we prove the convexity of the length function under geodesic homotopies.
\begin{proposition} \label{prop,convexityLength}   
 Let $g_1,g_2$ be the lifts of a pair of negatively curved metrics to $\widetilde M$. Let $\psi:[0,1] \times \widetilde{M} \to \widetilde{M}$   geodesic homotopy
in $\mathcal{C}_{R_0}(g_1,g_2)$ with $\psi_0 = \varphi_0$ and $\psi_1 = \varphi_1$.
Then for any Lipschitz curve $\alpha: [0,1] \to \widetilde{M}$ we have 
$$
L_{g_2}(\psi_s(\alpha)) \le (1-s) L_{g_2}(\varphi_0(\alpha)) +sL_{g_2}(\varphi_1(\alpha))
$$
 \end{proposition}
\begin{proof}
Let $0 =t_0 <t_1 < \ldots <t_n =1 $ be any partion of the interval $[0,1]$.
We obtain 
\begin{align*}
    \sum_{i =0}^{n-1}d_{g_2}(\psi_s\circ \alpha(t_i), \psi_s\circ \alpha(t_{i+1})) \le  &
(1-s)\sum_{i =0}^{n-1}d_{g_2}(\varphi_0\circ\alpha(t_i), \varphi_0\circ\alpha(t_{i+1}))\\
&+ s\sum_{i =0}^{n-1}d_{g_2}(\varphi_1\circ\alpha(t_i), \varphi_1\circ\alpha(t_{i+1})).
\end{align*}
Therefore, the proposition follows from the definition of the length of a curve.


\end{proof}





 Denote the space of all Lipschitz maps from $(M,g_1)$ and $(M,g_2)$ that are homotopic to the identity by $\Lip_{\id}(M, g_1, g_2)$. This is a subspace of $C_{\id}^{0}(M,M)$. The \emph{Lipschitz constant} of $f\in \Lip_{\id}(M, g_1, g_2)$ is defined by 
$$\Lip(f, g_1,g_2)= \sup_{x,x' \in M, x\neq x'} \frac{d_{g_2}(f(x),f(x'))}{d_{g_1}(x,x')}.$$  

\begin{remark}
 By Lemma \ref{lem, uniquelift}, the space
        $\Lip_{\id}(M, g_1, g_2)$ is in one to one correspondence with,
$$
\mathcal{C}_{\Lip}(g_1,g_2)=\big\{\psi \in \mathcal{C} \; | \;\psi :(\widetilde{M},g_1) \to (\widetilde{M},g_2) \text{ is a Lipschitz map} \}.
$$
\end{remark}


We define for $R\geq L(g_1,g_2)$, a subset in $ \Lip_{\id}(M, g_1, g_2)$,
$$ \mathcal{A}_R(g_1,g_2):=\{f\in  \Lip_{\id}(M, g_1, g_2) \text{ }|\text{ } \Lip(f, g_1,g_2) \leq R\}.$$


 When the background metrics $g_1,g_2$ are clear in the context, we simply write the above space as $ \mathcal{A}_R$.
\begin{lemma} \label{lemma, HolderCompactEmbedding}
    For any $\alpha<1$, the subset $\mathcal{A}_R$ is compact in $C^{\alpha}(M,M)$ with respect to the $C^{\alpha}$ (weak) topology. In particular, it is a compact subset in  $(C_{\id}^{0}(M,M),d_{\mathcal{C},g})$.
\end{lemma}
\begin{proof}
   Any sequence of maps $\{f_n\}$ in $\mathcal{A}_R$ is an equicontinuous 
   %and uniformly bounded 
   family in $C_{\id}^{0}(M,M)$. By Ascoli-Arzelà Theorem, it has convergent subsequence in $C_{\id}^{0}(M,M)$ with respect to $C^0$ topology. This shows that $\mathcal{A}_R$ is a compact subset of $C_{\id}^{0}(M,M)$. For the more general statement, see \cite[Lemma 6.33]{GT01}. 

\end{proof}








\subsection{Geodesic stretches and weighted Lipschitz constants} \label{section, FunctionalGfirst}
\hfill\\
In this subsection, we want to discuss the relation between geodesic stretches and  the average ``stretch" of Lipschitz maps with respect to a $\phi_t^{g_1}$-invariant measure $m$. 


The space of Lipschitz map from $(M, g_1)$ to $(M, g_2)$ can be identified with the Sobolev space $W^{1,\infty}(M,g_1,g_2)$ 
 (see\cite[Section 4.2.3.]{EG15}). Consider the following \emph{weigthed Lipschitz constant} of a Lipschitz map $f$ with respect to a $\phi_t^{g_1}$-invariant measure $m$  given by a functional
 \begin{align*}
 &G: \Lip_{id}(M,g_1,g_2) \times \mathcal{M}(\phi^{g_1})\to \mathbb{R}_{\geq 0}\\
&G(f,m)=\int_{S^{g_1}M} \norm{Df(v)}_{g_2} dm(v),
 \end{align*}
where $Df$ is the weak derivative of $f\in W^{1,\infty}(M,g_1,g_2)$.
However, since the weak derivative $Df$ is only defined almost everywhere with respect to Liouville measure, it is not immediately obvious that the above integral makes sense. The following proposition interprets the integral for a $\phi^{g_1}_t$-invariant measure with the help of geodesic currents.

Recall that we denote $\pi$ as the canonical projection from $TM$ to $M$ and the canonical projection from $T\widetilde{M}$ to $\widetilde{M}$ depending on context. Recall also from Proposition \ref{prop:m-current}, any geodesic current $\mu$ defines a $\Gamma$-invariant and $\phi^g$-invariant measure $m^g_{\mu}$. Recall also that $R^-(M)$ denotes the space of all smooth Remiannian metrics of negative curvature on $M$.

\begin{proposition}\label{prop,whyIntegralWellDefined}
Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. Let $ f \in \Lip_{\id}(M, g_1, g_2)$ be a Lipschitz map and $ m_{\mu}^{g_1}$ be the $\phi^{g_1}_t$ invariant measure induced by a current $\mu \in \mathcal C (\Gamma)$.
Choose a fundamental domain $\mathcal F \subset \widetilde M$ that satisfies Remark \ref{remark:CurrentMeasure} and for each pair $ (\xi_-, \xi_+ ) \in \partial^{(2)} \widetilde M$, denote by 
$c_{\xi_-, \xi_+}^{g_1} $ the oriented $g_1$-geodesic with $c_{\xi_-, \xi_+}^{g_1}(-\infty) = \xi_- $ and $c_{\xi_-, \xi_+}^{g_1}(\infty) = \xi_+$. Then
$$
\int_{S^{g_1}M } \| Df (v) \|_{g_2} d m_{\mu}^{g_1}(v) = \int_{\partial^{(2)} \widetilde M} L_{g_2} ( f(c_{\xi_-, \xi_+}^{g_1} \cap \mathcal F)) d\mu(\xi_-, \xi_+). 
$$
\end{proposition}
\begin{proof}
For $p_0 \in \widetilde M $ and the Hopf map $H^{g_1}_{p_0}: S^{g_1} \widetilde M \to  \partial^{(2)} \widetilde M \times \R$ given by
$$
H^{g_1}_{p_0}(v) = (v^{g_1}_-, v^{g_1}_+,  b_{ v^{g_1}_+}^{\scriptscriptstyle g_1}(p_0, \pi (v))) 
\quad \text{(see Equation (\ref{Hopfmap}) for details)},
$$
define 
$v_{(\xi_-, \xi_+)} :=  (H^{g_1}_{p_0})^{-1}(\xi_-, \xi_+, 0)$ . According to Remark \ref{remark:CurrentMeasure} and Proposition \ref{prop:m-current}  , we have,
\begin{align*}
&\int_{S^{g_1}M } \| Df (v) \|_{g_2} d m_{\mu}^{g_1}(v) =
\int_{S^{g_1} \widetilde {M}}  \| Df(v) \|_{g_2} \chi_{_{S^{g_1}\mathcal{F}}}(v)     \ dm_{\mu}^{g_1}(v)\\
= &\int_{\partial^{(2)} \widetilde M}
\int_{\R}  \| Df(\phi_t^{g_1} (v_{(\xi_-, \xi_+)}) \|_{g_2}  \chi_{_{S^{g_1}\mathcal{F}}}(\phi_t^g (v_{(\xi_-, \xi_+)}) dt \ d\mu (\xi_-, \xi_+) \\
= &\int_{\partial^{(2)} \widetilde M}
\int_{\R}  \| \frac{d}{dt}f(c^{g_1}_{v_{\scriptscriptstyle (\xi_-, \xi_+)}}(t))  \|_{g_2} \chi_{_{\mathcal{F}}}(c^{g_1}_{v_{(\xi_-, \xi_+)}} (t))dt \ d\mu (\xi_-, \xi_+) ,
\end{align*}
where $c^{g_1}_v$ is the $g_1$-unit speed geodesic with initial velocity $v$ and with abuse of notation, the unique lift of $f$ in the class $\mathcal{C}$ is still denoted as $f$.
This integral is well defined since $t \to f(c^{g_1}_{v_{(\xi_-, \xi_+)}}(t)) $
is Lipschitz and therefore the derivative exists a.e. for $t\in \mathbb{R}$ by Rademacher’s Theorem (see \cite[Theorem 3.2]{EG15}).
Now the proposition follows since
$$
\int_{\R}  \| \frac{d}{dt}f(c^{g_1}_{v_{(\xi_-, \xi_+)}}(t))  \|_{g_2} \chi_{_{\mathcal{F}}}(c^{g_1}_{v_{(\xi_-, \xi_+)}} (t))dt = L_{g_2} ( f(c_{\xi_-, \xi_+}^{g_1} \cap \mathcal F)).
$$

\end{proof}


We can also understand the weighted Lipschitz constant of  $f$ as follows.
\begin{lemma} \label{lem: Reinterpret}
Given $v\in S^{g_1}M$, denote $c^{g_1}_v$ as the $g_1$-unit speed geodesic with $c^{g_1}_v(0)= \pi(v)$ and $\dot{c}^{g_1}_v(0)= v$. If $m\in\mathcal{M}^1(\phi^{g_1})$, then
$$
\int_{S^{g_1}M } \| Df (v) \|_{g_2} d m(v) = \int_{S^{g_1}M } L_{g_2} (f(c^{g_1}_v[0,1]))d m(v).
$$
\end{lemma}
\begin{proof}
Since $m$ is $\phi^{g_1}_t$-invariant, we have
$$
\int_{S^{g_1}M } \| Df (v) \|_{g_2} d m(v) =\int_{S^{g_1}M } \| Df (\phi^{g_1}_sv) \|_{g_2} d m(v), 
$$
for all $s \in \R$. This implies that
\begin{align*}
\int_{S^{g_1}M } \| Df (v) \|_{g_2} d m(v) &= \int_0^1\int_{S^{g_1}M } \| Df (\phi^{g_1}_sv) \|_{g_2} d m(v) ds \\
&=\int_{S^{g_1}M }\int_0^1 \| Df (\phi^{g_1}_sv) \|_{g_2}  ds \; d m(v) \\
&=\int_{S^{g_1}M }\int_0^1 \| \frac{d}{ds} f(c^{g_1}_v(s)) \|_{g_2} \ ds \; d m(v) \\
&=\int_{S^{g_1}M }  L_{g_2} (f(c^{g_1}_v[0,1]) \ d m(v).
\end{align*}
\end{proof}





Let $ f\in \Lip_{\id}(M,g_1,g_2)$. According
 to Lemma \ref{lem, uniquelift}, there exists a unique lift $ \widetilde{f}: \widetilde M \to \widetilde M$  such that $\widetilde{f}\gamma = \gamma  \widetilde{f}$ for all $\gamma \in \Gamma$. Then given a fundamental domain $\mathcal F$, there exists a constant $c_f(g_2)$ such that 
 $d_{g_2}(x, \widetilde f (x)) \le c_f(g_2)$ for all $x \in \mathcal F $
  and by the $\Gamma$- equivariance of $\widetilde{f}$, we obtain 
 $$d_{g_2}(x, \widetilde f (x)) \le c_f(g_2)$$
for all $x \in \widetilde M$.
 In particular,  $\widetilde{f}$ has a continuous extension $\widetilde{f} :\partial \widetilde M \to  \partial \widetilde M $ given by the identity.
 Furthermore, the following extension of Lemma \ref{lem,Busem-distance}
 holds for any fixed Lipschitz map $f\in \Lip_{\id}(M,g_1,g_2)$.
 \begin{lemma}\label{lem,Busem-distance-Lip}
 There exists a constant $k_f(g_1, g_2)$ such that for all $v \in S^{g_1} \widetilde M$ and $\xi = v^{g_1}_+$ we have,
$$
| d_{g_2}(\widetilde{f}\pi (v) , \widetilde{f}\pi(\phi_t^{g_1} v)) -b_\xi^{g_2}(\widetilde{f}\pi(v),  \widetilde{f}\pi(\phi_t^{g_1} v))| \le k_f(g_1, g_2).
$$
\end{lemma}
\begin{proof}
By the discussion before this lemma,
$$
|  d_{g_2}(\widetilde{f}\pi (v) , \widetilde{f}\pi(\phi_t^{g_1} v)) - d_{g_2}(\pi (v) , \pi(\phi_t^{g_1} v)) | \le 2 c_f(g_2),
$$
and by cocycle property (\ref{prop1bus}) of the Busemann function,
\begin{align*}
    &|b_\xi^{g_2}(\widetilde{f}\pi(v),  \widetilde{f}\pi(\phi_t^{g_1} v)) 
- b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))| \\ 
=& |b_\xi^{g_2}(\widetilde{f}\pi(v),   \pi (v)) 
- b_\xi^{g_2}(\widetilde{f} \pi(\phi_t^{g_1} v), \pi(\phi_t^{g_1} v)) |\\
\le &  d_{g_2}(\widetilde{f}\pi (v) , \pi (v)) + d_{g_2}(\widetilde{f}\pi(\phi_t^{g_1} v), \pi(\phi_t^{g_1} v)) \le 2 c_f(g_2).
\end{align*}
Furthermore, Lemma \ref{lem,Busem-distance} implies that there exists a constant $R_1=R_1(g_1,g_2)>0$ so that
$$  
| d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v)) -b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))| \le R_1(g_1, g_2).
$$
Using this inequalities, we obtain
\begin{align*}
&|  d_{g_2}(\widetilde{f}\pi (v) , \widetilde{f}\pi(\phi_t^{g_1} v)) -b_\xi^{g_2}(\widetilde{f}\pi(v),  \widetilde{f}\pi(\phi_t^{g_1} v))| \\
= &| d_{g_2}(\widetilde{f}\pi (v) , \widetilde{f}\pi(\phi_t^{g_1} v)) -
  d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v)) 
+ d_{g_2}(\pi (v) , \pi (\phi_t^{g_1} v)) \\
-&b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))
  \ + b_\xi^{g_2}(\pi(v),  \pi(\phi_t^{g_1} v))-b_\xi^{g_2}((\widetilde{f}\pi(v)),  \widetilde{f}\pi(\phi_t^{g_1} v))| \\
   \le &4 c_f(g_2) +R_1(g_1, g_2) =: k_f(g_1, g_2).
 \end{align*}
\end{proof}


Define a function $l_f: S^{g_1}M \times \mathbb{R} \to \mathbb{R}_{\geq 0}$ by
$$ l_f (v, t): =  d_{g_2}(\widetilde{f}\pi (\widetilde{v}) , \widetilde{f}\pi(\phi_t^{g_1} \widetilde{v})), $$
where $\widetilde{v}$ is a lift of $v$ on $S^{g_1}\widetilde M $. This is well defined because the right hand side is $\Gamma$-invariant.
Consider a $\phi^{g_1}$-invaraint probability measure $m \in \mathcal{M}^1(\phi^{g_1})$. By the subadditive ergodic theorem and the subadditivity of the function $l_f (v, t)$, 
the limit 
$\lim\limits_{t \to \infty} \frac{ 1}{t}l_f (v, t)$
exists for $m$-almost every $v \in S^{g_1} M $. On the other hand, from the proof of Lemma \ref{lem,Busem-distance-Lip}, when the limit exists for $v \in S^{g_1} M $, we obtain,
$$
\lim_{t \to \infty} \frac{1}{t}l_f (v, t) =\lim_{t \to \infty} \frac{1}{t}
 d_{g_2}(\pi (\widetilde{v}) , \pi (\phi_t^{g_1} \widetilde{v}))= I_m(g_1,g_2,v). 
$$
In particular, this limit is independent of a choice of $f$ in $\Lip_{\id}(M,g_1,g_2)$.

We next show that the geodesic stretch with respect to a $\phi^{g_1}$-invariant probability measure is always bounded above by the average `` stretch " of a Lipschitz map with respect to that measure. 


\begin{lemma} \label{lem, GeodesicStretchLipStretch}
   Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$ and let $m\in\mathcal{M}^1(\phi^{g_1})$. Given any Lipschitz map $f\in \Lip_{\id}(M,g_1,g_2)$, the geodesic stretch $I_{m}(g_1, g_2)$ satisfies
    \begin{align*}
I_m(g_1, g_2) \leq \int_{S^{g_1} M}  \| Df(v) \|_{g_2} dm.
\end{align*}
\end{lemma}
\begin{proof}

By Lemma \ref{lem,Busem-distance-Lip}, we obtain for $m$ almost every $v\in S^{g_1} M$,

\begin{align*}
\lim_{t \to \infty} \frac{1}{t} l_f (v, t) & = \lim_{t \to \infty} \frac{1}{t}
b_\xi^{g_2}(\widetilde{f}\pi(\widetilde{v}),  \widetilde{f}\pi(\phi_t^{g_1} \widetilde{v}))\\
&=  \lim_{t \to \infty} \frac{1}{t} \int_0^t \frac{d}{ds} b_\xi^{g_2}(\widetilde{f}\pi(\widetilde{v}),  \widetilde{f}\pi(\phi_s^{g_1} \widetilde{v}))  ds\\
&=  \lim_{t \to \infty} \frac{1}{t} \int_0^t g_2( B^{g_2}(\widetilde{f}\pi(\phi_s^{g_1} \widetilde{v})), \widetilde{v}^{g_1}_+), D\widetilde{f}
(\phi_s^{g_1} \widetilde{v} )) ds,
\end{align*}
where $\widetilde{v}$ denotes a lift of $v$ on $S^{g_1}\widetilde M $ and $\xi=\widetilde{v}^{g_1}_{+}$. Since the functions  $g_2( B^{g_2}(\widetilde f\pi( \widetilde{v}), \widetilde{v}^{g_1}_+), D\widetilde{f}(\widetilde{v}))$ and $ \| D\widetilde{f}(\widetilde{v}) \|$ are  $\Gamma$-invariant, we obtain from the Birkhoff ergodic theorem for invariant measures ((\cite[Theorem 1.14]{Wa82})) and the definition of the geodesic stretch, 
\begin{align*}
I_{m}(g_1, g_2) &= \int_{S^{g_1} M}\lim_{t \to \infty} \frac{1}{t}l_f (v, t) dm(v)\\
 &= \int_{S^{g_1} M}g_2( B^{g_2}(\widetilde f\pi( \widetilde{v}), \widetilde{v}^{g_1}_+), D\widetilde f(\widetilde{v})) dm(v)\\
 & \le \int_{S^{g_1} M}  \| Df(v) \|_{g_2} dm(v).
\end{align*}
Furthermore, 
$$
I_{m}(g_1, g_2) = \int_{S^{g_1} M}  \| Df(v) \|_{g_2} dm(v)
$$
if and only if for $m$ almost every $v\in S^{g_1} M$ we have
$$
 D\widetilde{f}(\widetilde{v}) = \| Df(v) \|_{g_2}  B^{g_2}( \widetilde f \pi(\widetilde{v}), \widetilde{v}^{g_1}_+).
$$

\end{proof}



The above Lemma holds for any Lipschitz map homotopic to identity. This motivates us to define
\begin{definition}
Given $g_1,g_2\in R^-(M)$ and given $m\in \mathcal{M}^1(\phi^{g_1})$, we define the \emph{$m$-weighted least Lipschitz constant} $L_{m}(g_1,g_2)$ as   
 $$L_m(g_1,g_2):=\inf\limits_{f\in \Lip_{\id}(M, g_1, g_2)}\int_{S^{g_1}M} \norm{Df(v)}_{g_2} dm.$$
\end{definition}

 similarly, for a geodesic current $\mu\in \mathcal{C}(\Gamma)$, we define the  \emph{$\mu$-weighted least Lipschitz constant} as $L_{\mu}(g_1,g_2):= L_{\hat{m}^{g_1}_{\mu}}(g_1,g_2)$, which is the weighted least Lipschitz constant of its assocaited invariant probability measure $\hat{m}^{g_1}_{\mu}$.

\begin{comment}


$$ L_{\mu}(g_1,g_2)=\inf\limits_{f\in \Lip_{\id}(M, g_1, g_2)} \| Df(v) \|_{g_2} d\hat{m}^{g_1}_{\mu}.$$

Similarly 
\end{comment}

 As a simple application of  Lemma \ref{lem, GeodesicStretchLipStretch}, we obtain

\begin{corollary} \label{cor, MinGeqGeodesicStretch}
Let $g_1, g_2$ be two Riemannian metrics in $R^-(M)$. Given $m\in \mathcal{M}^1(\phi^{g_1})$, we have
$$ I_{m}(g_1,g_2) \leq  L_{m}(g_1,g_2).$$
\end{corollary} 



Now we discuss in the following theorem when the equality holds in Lemma \ref{lem, GeodesicStretchLipStretch}. We state this theorem in the language of geodesic currents.


\begin{theorem} \label{prop,GeodesicToGeodesic}
Given $g_1, g_2 \in R^{-}(M)$ and $\mu \in \mathcal{C}(\Gamma)$ a geodesic current and $f \in \Lip_{\id}(M,g_1,g_2)$ such that

$$
I_{\mu}(g_1, g_2) = \int_{S^{g_1} M}  \| Df(v) \|_{g_2} d\hat{m}^{g_1}_{\mu}(v).
$$ 
Then for  all $(\xi_-, \xi_+) \in \partial^{(2)} \widetilde M$ contained in 
$\supp \mu$,
we have that its lift $\widetilde f \in \mathcal{C}$ maps $g_1$-geodesics to corresponding $g_2$-geodesics up to parametrization, i.e.
$$
\widetilde f(c_{(\xi_-, \xi_+)}^{g_1}) = c_{(\xi_-, \xi_+)}^{g_2},
$$
where $c_{(\xi_-, \xi_+)}^{g_1}$ denotes the $g_1$-geodesic with backward endpoint $\xi_-$ and forward endpoint $\xi_+$. In particular, if $\mu$ has full support on $ \partial^{(2)} \widetilde M$, then $\widetilde f$ maps every $g_1$-geodesic to the corresponding $g_2$-geodesic up to parametrization.

\end{theorem}



\begin{proof}
The geodesic stretch satisfies from the deduction of Lemma \ref{lem, GeodesicStretchLipStretch},
\begin{align*}
I_{\mu}(g_1, g_2)& =\int_{S^{g_1} M} \int_{0}^{1} 
g_2( B^{g_2}(\widetilde f\pi( \phi^{g_1}_s \widetilde v), \widetilde v^{g_1}_+), D \widetilde f(\phi^{g_1}_s \widetilde v)) ds  d\hat{m}^{g_1}_{\mu}(v) \\
&= \int_{S^{g_1} M} \int_{0}^{1} \frac{d}{ds} b^{g_2}_{v_+}(x_0, \widetilde f( c^{g_1}_{\widetilde v} (s))) ds \ d\hat{m}^{g_1}_{\mu}(v)\\
&= \int_{S^{g_1} M} b^{g_2}_{v_+}(\widetilde f( c^{g_1}_{\widetilde v}(0) ), \widetilde f( c^{g_1}_{\widetilde v}(1) )) d\hat{m}^{g_1}_{\mu}(v),
\end{align*}
where $x_0$ is a base point on $\widetilde M$ and $\widetilde v$ is a lift of $v$. $c^{g_1}_{\widetilde v}(t)$ is the unit speed $g_1$-geodesic on $\widetilde M$ starting from $\widetilde v$. To simplify notation, we write $v_+$ to mean $ \widetilde v^{g_1}_+$. 

On the other hand, the average ``stretch" of the Lipshitz map $f$ is 
$$
\int_{S^{g_1} M}  \| Df(v) \|_{g_2} d\hat{m}^{g_1}_{\mu}(v) =
 \int_{S^{g_1} M} L_{g_2} ( \widetilde f(  c^{g_1}_{\widetilde v}([0, 1]))) d\hat{m}^{g_1}_{\mu}(v),
$$
Since the Busemann function is 1-Lipschitz, we have

\begin{equation}\label{eqtn,bLd}
b^{g_2}_{v_+} (\widetilde f( c^{g_1}_{\widetilde v}(0) ), \widetilde f( c^{g_1}_{\widetilde v}(1) ) )\le d_{g_2}(\widetilde f( c^{g_1}_{\widetilde v}(0) ),\widetilde f(c^{g_1}_{\widetilde v} (1) ))
\le  L_{g_2} ( \widetilde f(   c^{g_1}_{\widetilde v}([0,  1]))).
\end{equation}


Therefore
$$
I_{\mu}(g_1, g_2) =\int_{S^{g_1} M}  \| Df(v) \|_{g_2} d\hat{m}^{g_1}_{\mu}(v)
$$

implies
\begin{equation}\label{eqtn,b=Lfullmeasure}
b^{g_2}_{v+} (\widetilde f( c^{g_1}_{\widetilde v} (0) ), \widetilde f( c^{g_1}_{\widetilde v}(1)) ) = L_{g_2} ( \widetilde f(  c^{g_1}_{\widetilde v}([0, 1]))),
\end{equation}
for $\hat{m}^{g_1}_{\mu}$ almost every $v \in S^{g_1} M$. Here we use the fact that the above functions on $\widetilde M$ are $\Gamma$-invariant.


We want to show that the Equation \eqref{eqtn,b=Lfullmeasure} in fact holds for every $v\in \supp \hat{m}^{g_1}_{\mu}$. It is clear that the Busemann function $b^{g_2}_{v_+} (\widetilde f( c^{g_1}_{\widetilde v}(0) ), \widetilde f( c^{g_1}_{\widetilde v}(1) )$ is continuous in $\widetilde v$. However we need to be careful that $L_{g_2} ( \widetilde f(  c^{g_1}_{\widetilde v}([0, 1]))$ is only lower-semicontinuous in $\widetilde v$: if $\widetilde v_n \to \widetilde v_0$, then the curves $\widetilde f\circ   c^{g_1}_{\widetilde v_n}$ approximates $\widetilde f\circ \widetilde c^{g_1}_{v_0}$ uniformly in the $C^0$ topology. Then the lengths of these curves satisfy (see for example, \cite[Chapter I.1, Proposition 1.20 (7)]{BH99}),
\begin{equation}  \label{equation liminfLength}
 L_{g_2} (\widetilde f\circ   c^{g_1}_{\widetilde v_0}([0,1]))\leq \liminf\limits_{n\to\infty} L_{g_2} (\widetilde f\circ   c^{g_1}_{\widetilde v_n}([0,1]) ).
\end{equation}
Now suppose $v_0\in \supp \hat{m}^{g_1}_{\mu}$. For a lift $\widetilde v_0$ of $v_0$, let us consider an open ball $B_{\frac{1}{n}}(\widetilde v_0)$ of radius $\frac{1}{n}$ with respect to the Sasaki metric centered at $\widetilde v_0$. It has positive measure with respect to (the lift of) $\hat{m}^{g_1}_{\mu}$. We can therefore find $\widetilde v_n \in B_{\frac{1}{n}}(\widetilde  v_0)$ that satisfies Equation \eqref{eqtn,b=Lfullmeasure} and that $\widetilde  v_n\to \widetilde  v_0$.
Therefore, by inequality \eqref{eqtn,bLd} and \eqref{equation liminfLength}, we have,
\begin{align*}
\liminf_{n\to\infty}L_{g_2} ( \widetilde f(  c_{\widetilde v_n}^{g_1}([0, 1])))&\geq L_{g_2} ( \widetilde f(   c^{g_1}_{\widetilde v_0}([0, 1])))
\geq  b^{g_2}_{v_{0+}} (\widetilde f(  c^{g_1}_{\widetilde v_0} (0) ), \widetilde f(  c^{g_1}_{\widetilde v_0}(1) ))\\ 
&=\lim\limits_{n\to\infty} b^{g_2}_{v_{n+}} (\widetilde f(  c^{g_1}_{\widetilde v_n} (0) ), \widetilde f(  c^{g_1}_{\widetilde v_n}(1) )).
\end{align*}

By assumption, Equation \eqref{eqtn,b=Lfullmeasure} holds for all $\widetilde  v_n$. The above inequalities imply 

\begin{equation*}
L_{g_2} ( \widetilde f(   c^{g_1}_{\widetilde v_0}([0, 1])))
=  b^{g_2}_{v_{0+}} (\widetilde f(  c^{g_1}_{\widetilde v_0} (0) ), \widetilde f(  c^{g_1}_{\widetilde v_0}(1) )).
\end{equation*}

Hence  Equation \eqref{eqtn,b=Lfullmeasure} in fact holds for (lifts of) every $v\in \supp \hat{m}^{g_1}_{\mu}$.

To conclude the statement, we notice since  $\supp \hat{m}^{g_1}_{\mu}$ is
$\phi^{g_1}_t$-invariant, for all $t \in \R$,
\begin{align} \label{equation Length-distance}
L_{g_2} (\widetilde f( c^{g_1}_{\widetilde v}([t, t+1])))&= L_{g_2} (\widetilde f( c_{\phi^{g_1}_t \widetilde v}^{g_1}([0, 1]))) \\
&=  d_{g_2}(\widetilde f( c^{g_1}_{\phi^{g_1}_t \widetilde v}(0) ),\widetilde f(c^{g_1}_{\phi^{g_1}_t \widetilde v} (1) )) \nonumber \\
&= d_{g_2}(\widetilde f( c^{g_1}_{\widetilde v}(t) ),\widetilde f( c^{g_1}_{\widetilde v}(t+1) )) \nonumber.
\end{align}



This implies that for all $t \in \R$, the curve $ [0, 1] \to \widetilde M$ given by
$$s \mapsto  \widetilde f( c^{g_1}_{\widetilde v}(t+s))$$ agrees up to parametrization with the  $g_2$-geodesic $ c^{g_2}$ connecting 
 $\widetilde f ( c^{g_1}_{\widetilde v}(t))$ to  $\widetilde f( c^{g_1}_{\widetilde v}(t+1))$. Hence we conclude,
for all $v \in  \supp \hat{m}^{g_1}_{\mu}$ and $(v_-, v_+) \in \partial^{(2)} \widetilde M $, we have that
$$
\widetilde f( c_{(v_-, v_+)}^{g_1}) =  c_{(v_-, v_+)}^{g_2}
$$
where $ c^{g_j}_{(v_-, v_+)}$ is the unparametrized geodesic with $c^{g_j}_{(v_-, v_+)}(-\infty) =v_-$
and  $ c^{g_j}_{(v_-, v_+)}(+\infty) =v_+$, for $j=1,2$.

\end{proof}


Combining all we have discussed leads to the key statement in this subsection.

\begin{corollary} \label{cor,MainThm3}
 Suppose $g_1,g_2 \in R^-(M)$. For any maximally stretched measure, we have
\begin{align*} 
S(g_1, g_2) \leq L_m(g_1,g_2).
\end{align*}
Furthermore, if for some maximally stretched measure $m_0$, there exists  $f_0 \in \Lip_{\id}(M, g_1, g_2)$  such that $$S(g_1,g_2) =\int_{S^{g_1}M} \norm{Df_0(v)}_{g_2} dm_0(v)=L_{m_0}(g_1,g_2) ,$$
then  $f_0$ maps any $g_1$-geodesic in the support of $m_0$ to a corresponding $g_2$-geodesic (up to parametrization).
\end{corollary}
\subsection{Some further properties of the functional $G$} 
We discuss in this subsection lower-semicontinuity annd convexity of the functional $G$ given by 
 \begin{align*}
 &G: \Lip_{id}(M,g_1,g_2) \times \mathcal{M}(\phi^{g_1})\to \mathbb{R}_{\geq 0}\\
&G(f,m)=\int_{S^{g_1}M} \norm{Df(v)}_{g_2} dm(v).
 \end{align*}

We have the following lemma for lower-semicontinuity.
\begin{lemma} 
\label{lem,correctCompactness}
Let $f_0 \in \Lip_{\id}(M,g_1,g_2)$ and  $m_0 \in\mathcal{M}^{1}(\phi^{g_1})$, for any $\varepsilon>0$ there exists a neighborhood $U_1$ of $f_0$  in  $(\Lip_{\id}(M,g_1,g_2), d_{\mathcal{C}, g_2})$ and a neighborhood $U_2$ of $m_0$ in  $\mathcal{M}^{1}(\phi^{g_1})$ such that
    $$
     G(f_0,m_0)  \leq   G(f,m) + \varepsilon
     $$
     for all $f \in U_1$ and $m \in U_2$, where $U_1=U_1(f_0,m_0,\varepsilon)$ and $U_2=U_2(f_0,m_0,\varepsilon)$ both depend on $f_0$, $m_0$ and $\varepsilon$.

\end{lemma} 
 \begin{proof}
Consider for each $\ell \in \N$ the partition $0 \le t_0^\ell < \ldots  <t_{2^\ell}^\ell =1 $ of $[0, 1]$ with 
$t_i^\ell = \frac{i}{2^\ell}$.
Using the triangle inequality we obtain that for each $v \in S^{g_1}M$ and all $f \in \Lip_{\id}(M,g_1,g_2)$ the sequence
$$
\ell \mapsto \sum_{i=0}^{2^\ell-1} d_{g_2}(f\circ c^{g_1}_v(t_i^\ell), f\circ c^{g_1}_v(t_{i+1}^\ell))
$$
is monotonically increasing and from the definition of the length functional we obtain
$$
L_{g_2} ( f(c^{g_1}_v[0,1])) = \lim_{\ell \to \infty} \sum_{i=0}^{2^\ell-1} d_{g_2}(f\circ c^{g_1}_v(t_i^\ell), f\circ c^{g_1}_v(t_{i+1}^\ell)).
$$
Then Lebesgue's dominated convergence theorem yields
\begin{align*}
 G(f,m) &=\int_{S^{g_1}M} L_{g_2} ( f(c_{v}^{g_1}[0,1])) dm \\
 &= \lim_{\ell \to \infty} \int_{S^{g_1}M}
  \sum_{i=0}^{2^\ell-1} d_{g_2}(f\circ c^{g_1}_v(t_i^\ell), f\circ c^{g_1}_v(t_{i+1}^\ell)) dm.
 \end{align*}

Let $\varepsilon >0$. For a fixed $f_0\in \Lip_{\id}(M,g_1,g_2)$ and a fixed $m_0\in\mathcal{M}^{1}(\phi^{g_1})$, there exists $\ell=\ell(f_0,m_0,\varepsilon) \in \N$
 such that
 \begin{equation} \label{eqtn, partition}
  G(f_0,m_0)  \leq \int_{S^{g_1}M}
  \sum_{i=0}^{2^\ell-1} d_{g_2}(f_0 \circ c^{g_1}_v(t_i^\ell), f_0 \circ c^{g_1}_v(t_{i+1}^\ell)) dm_0 + \frac{\varepsilon}{4}.
\end{equation}

Choose a neighborhood $U_1=U_1(f_0,m_0,\varepsilon)$ of $f_0$  such that for all $f \in U_1$,
 $$d_{\mathcal{C},g_2}(f ,f_0)\leq \frac{\varepsilon}{ 2^{\ell+2}}.$$
Hence for all $v \in S^{g_1}M$ and $t \in [0,1]$, we have
$$ d_{g_2} (f\circ c^{g_1}_v(t),f_0 \circ c^{g_1}_v(t))\leq d_{\mathcal{C},g_2}(f,f_0)\leq \frac{\varepsilon}{ 2^{\ell+2}}.$$
and 
 by triangle inequality, 
 we obtain
 \begin{align*} 
 &|d_{g_2}(f_0 \circ c^{g_1}_v(t_i^\ell), f_0 \circ c^{g_1}_v (t_{i+1}^\ell))- d_{g_2}(f\circ c^{g_1}_v(t_{i}^{\ell}), f   \circ c^{g_1}_v(t_{i+1}^{\ell}))| \\
\leq &  d_{g_2}(f_0 \circ c^{g_1}_v(t_{i}^{\ell}), f \circ c^{g_1}_v (t_{i}^{\ell})) +  d_{g_2}(f_0 \circ c^{g_1}_v(t_{i+1}^{\ell}), f \circ c^{g_1}_v (t_{i+1}^{\ell})) \\
 \leq & \frac{\varepsilon}{  2^{\ell+1}}
  \end{align*} 
Therefore 
\begin{equation}\label{eqtn, DistSum}
 \sum_{i=0}^{2^\ell-1} d_{g_2}(f_0\circ c^{g_1}_v(t_i^\ell), f_0 \circ c^{g_1}_v(t_{i+1}^\ell)) \le  \sum_{i=0}^{2^\ell-1} d_{g_2}(f\circ c^{g_1}_v(t_i^\ell), f \circ c^{g_1}_v(t_{i+1}^\ell))  + \frac{\varepsilon}{2}  
\end{equation}


Since $v\to \sum_{i=0}^{2^\ell-1} d_{g_2}(f_0\circ c^{g_1}_v(t_i^\ell), f_0\circ c^{g_1}_v(t_{i+1}^\ell))$ is a continuous function, by  weak* topology, we can choose a neighborhood $U_2=U_2(f_0,m_0,\varepsilon)$ of $m_0$, so that for $m \in U_2$,


\begin{align} \label{eqtn, TwoMeasures}
    \bigg| \int_{S^{g_1}M} &
  \sum_{i=0}^{2^\ell-1} d_{g_2}(f_0\circ c^{g_1}_v(t_i^\ell), f_0\circ c^{g_1}_v(t_{i+1}^\ell)) dm \\
  &- \int_{S^{g_1}M}
  \sum_{i=0}^{2^\ell-1} d_{g_2}(f_0\circ c^{g_1}_v(t_i^\ell), f_0\circ c^{g_1}_v(t_{i+1}^\ell)) dm_0\bigg| \leq \frac{\varepsilon}{4}.
  \end{align} 

Combining Equation \ref{eqtn, partition}, \ref{eqtn, DistSum} and \ref{eqtn, TwoMeasures} with an application of Lebesgue's dominated convergence theorem leads to,
  $$ G(f_0,m_0) \leq \int_{S^{g_1}M}
  \sum_{i=0}^{2^\ell-1} d_{g_2}(f \circ c^{g_1}_v(t_i^\ell), f\circ c^{g_1}_v(t_{i+1}^\ell)) dm +\varepsilon \leq G(f, m)+\varepsilon.$$

\end{proof}

\begin{proposition}\label{prop,PropertiesG3}
    The map $G: \Lip_{id}(M,g_1,g_2) \times \mathcal{M}^{1}(\phi^{g_1}) \longrightarrow \mathbb{R}_{\geq 0}$ with $(f,m) \mapsto G(f, m) $ is lower semi-continuous.
\end{proposition}
\begin{proof}
    This follows from Lemma \ref{lem,correctCompactness}.
\end{proof}
For a fixed $m_0\in \mathcal{M}^{1}(\phi^{g_1})$, let us denote  $L_{m_0}: \Lip_{id}(M,g_1,g_2)  \longrightarrow \mathbb{R}_{\geq 0}$ as $L_{m_0}(f):=G(f,m_0)$. Then



 \begin{proposition} \label{prop,PropertiesG}
     For each $m_0 \in\mathcal{M}^{1}(\phi^{g_1})$, the map $ f\to L_{m_0}(f)$ is convex. 
     %The map $ f\to G(f,\mu_0 )$ is also lower semi-continuous, i.e. if $\{f_n\}\subset \mathcal{A}_R$ and $f_n$ converges to $f_0$ in $(\mathcal{C},d_{\mathcal{C}, g_2})$. Then 
    %$$ G(f_0,\mu_0)\leq \liminf\limits_{n\to\infty}G(f_{n},\mu_0).$$
