 \section{Best Lipschitz maps} \label{section,BLM}


 In this section, we discuss extremal Lipschitz maps and their relation to maximal stretches in some settings of negatively curved manifolds. We will have an emphysis on the study of stretch loci which was originally introduced in \cite{GK17} for hyperbolic spaces.
\subsection{Best Lipschitz maps and the maximal stretch }
\hfill\\
We always assume that the Riemannian metrics $g_1$ and $g_2$ are of negative sectional curvatures. The Lipschitz constant of a Lipschitz map $f$ with respect to $g_1$ and $g_2$ is 


$$\Lip(f, g_1,g_2)= \sup_{\substack{x,x' \in M \mathstrut \\ x\neq x'}} \frac{d_{g_2}(f(x),f(x'))}{d_{g_1}(x,x')}.$$  

Recall that $ \Lip_{\id}(M, g_1, g_2)$ is the set of Lipschitz maps from $(M,g_1)$ to $(M, g_2)$ that are homotopic to the identity. We would like to study extremal Lipschitz maps in this set.
\begin{definition}
We define the \emph{least Lipschitz constant} from $g_1$ to $g_2$ as
$$
L(g_1,g_2) := \inf \{ \Lip(f, g_1,g_2) \mid f\in \Lip_{\id}(M,g_1,g_2) \}.
$$
A Lipschitz map in $ \Lip_{\id}(M,g_1,g_2)$ that realizes the least Lipschitz constant $L(g_1,g_2)$ is called a \emph{best Lipschitz map}.
\end{definition}


\begin{remark}
    The existence of best Lipschitz maps follows from the compactness of $M$ and Arzelà-Ascoli Theorem.
\end{remark}


We also recall for $g_1,g_2 \in R^-(M)$,
the maximal stretch of $g_1$ to $g_2$ is defined by
$$
S(g_1,g_2) = \max_{\mu \in \mathcal{C}(\Gamma)} I_\mu(g_1,g_2)= \max_{\mu \in \mathcal{C}(\Gamma)} \int a_{g_1,g_2}(v) d\hat{m}^{g_1}_{\mu}.
$$

The following relation between $L(g_1,g_2)$ and $S(g_1,g_2)$ is obvious.
\begin{proposition}[\cite{Th98}] \label{prop,LgeqS}
Given $g_1,g_2\in R^-(M)$, the following inequality always holds:
$$
S(g_1, g_2) \le L(g_1,g_2).
$$
\end{proposition}
\begin{proof}
Let $ f: (M, g_1)  \to (M, g_2)$ be a best Lipschitz map. Let $\gamma=\gamma^{g_1}$ be any closed geodesic in $(M, g_1)$. Since $f$ is homotopic to the identity, we have
$ [f \circ \gamma ] =[\gamma]$ and 
$$
 \int\limits_0^{ \ell_{g_1}([\gamma])} a_{g_1,g_2} (\dot \gamma(t)) dt=  \ell_{g_2}([\gamma]) \le   L_{g_2}(f \circ \gamma) \le  \ell_{g_1}([\gamma]) \cdot L(g_1,g_2),
 $$
 where $L_{g_2}(f \circ \gamma)$ is the $g_2$-length of the Lipschitz curve $f\circ \gamma$.


 By Remark \ref{remark, supremumGeodesicStretch},
 $$
 S(g_1, g_2) = \sup_{[\gamma]\in [\Gamma]} \frac{1}{  \ell_{g_1}([\gamma])} \int\limits_0^{\ell_{g_1}([\gamma])} a_{g_1,g_2} (\dot \gamma(t)) dt  \le L(g_1,g_2)
 $$ 
 which yields the claim.
\end{proof}

It is an interesting but not easy question to address when the equality holds. A well known theorem of \cite{Th98} states that in the Teichm\"uller space, the maximal stretch alway equals to the least Lipschitz constant. We will have further discussion and provide some partial pictures of this question in negatively curved metrics setting in later subsections. In Section \ref{subsection,NotLamination}, we provide a large class of negatively curved metrics with $S(g_1,g_2)=L(g_1,g_2)$. In Appendix \ref{ExampleS<L}, we will also discuss an example of $g_1,g_2\in R^-(M)$ with $L(g_1,g_2)> S(g_1,g_2)$.




  \subsection{Best Lipschitz maps and the stretch locus}
\hfill\\
In \cite{GK17}, Gu\'{e}ritaud and Kassel introduce the stretch locus for best Lipschitz maps in the setting of hyperbolic spaces $\mathbb{H}^n$ for $n\geq 2$. We consider the same object in variable negatively curved manifolds in this subsection. In the sequel, we will discuss relations of stretch loci with other geometric objects.

\begin{definition} \label{defn, stretchLocus}
   Suppose $g_1,g_2 \in R^-(M)$. For $f\in \Lip_{\id}(M,g_1, g_2)$, we define the \emph{stretch locus} of $f$ from $g_1$ to $g_2$ as,
    $$E_f(g_1, g_2):= \{x\in M| \Lip(f, g_1,g_2)=\Lip_x(f, g_1,g_2) \},$$
    where $\Lip_x(f, g_1,g_2)$ is the \emph{local Lipschitz constant} at $x$ defined by 
    $$\Lip_x(f, g_1,g_2)= \inf_{r>0} \Lip(f|_{\overline{B}^{g_1}_x(r)}, g_1,g_2)$$
    and $\Lip(f|_{\overline{B}^{g_1}_x(r)}, g_1,g_2)$ denotes the Lipschitz constant of $f$ restricted to the closed ball $\overline{B}^{g_1}_x(r)$ of radius $r$ centered at $x\in M$ with respect to the metric $g_1$.
\end{definition}


   We list some useful properties of local Lipschitz constants and the stretch locus of $f\in \Lip_{\id}(M,g_1, g_2)$.  We refer to \cite[Lemma 2.9]{GK17} for details and proofs.

   Recall that  $\mathcal{C}$ is the space of $\Gamma$-equivariant continuous maps from $\widetilde{M}$ to $\widetilde{M}$.
\begin{remark} \label{remark, LocalLip}
 The following statements hold. 
    \begin{enumerate}
        \item The local Lipschitz constant $ x\to \Lip_x(f, g_1,g_2) $ is upper semicontinuous.
        \item  Consider the unique lift $\widetilde{f}\in \mathcal{C}$ of $f\in \Lip_{\id}(M,g_1, g_2)$ on the universal cover $\widetilde M$. Then for any convex subset $X$ of $(\widetilde M,g_1)$,
        $$\Lip(\widetilde{f}|_{X}, g_1,g_2)=\sup_{x\in X} \Lip_x(\widetilde{f}, g_1,g_2),$$
        where $\widetilde{f}|_{X}$ is the restriction of $\widetilde{f}$ to $X$.
        \item As a consequence of item (2), the local Lipschitz constant of $f$ satisfies
        $$\Lip(f, g_1,g_2)=\sup_{x\in M} \Lip_x(f, g_1,g_2),$$
        and so by item (1),
         $$\Lip(f, g_1,g_2)=\max_{x\in M} \Lip_x(f, g_1,g_2),$$
        \item As a consequence of item (1) and (3), the stretch locus $E_f(g_1, g_2)$ of $f\in \Lip_{\id}(M,g_1, g_2)$ is nonempty and closed.
\end{enumerate}
\end{remark}



Moreover, one defines the stretch locus between two metrics.

\begin{definition}
   Suppose $g_1,g_2 \in R^-(M)$. The stretch locus of $g_1$ to $g_2$ is given by
    \begin{align*}
    E(g_1,g_2):= \bigcap_{\substack{f\in \Lip_{\id}(M,g_1,g_2) \\ \Lip(f,g_1,g_2)=L(g_1,g_2)}} E_f(g_1, g_2).
   \end{align*}

    Furthermore, a Lipschitz map $f_0\in \Lip_{\id}(M,g_1,g_2)$ is called an \emph{optimal Lipschitz map} from $g_1$ to $g_2$ if its stretch locus $E_{f_0}(g_1, g_2)$ satisfies 
    $$E_{f_0}(g_1, g_2)=E(g_1,g_2).$$
\end{definition}

\begin{remark} \label{remark, StretchClosed}
    It follows from item (4) of Remark \ref{remark, LocalLip} that the stretch locus $E(g_1,g_2)$ is closed.
\end{remark}

In fact, an optimal Lipschitz map from $g_1$ to $g_2$ always exists when $g_1,g_2 \in R^-(M)$. The following proof is based on Lemma 4.13 of \cite{GK17} about existence of optimal Lipschitz maps in hyperbolic $n$ spaces $\mathbb{H}^n$. The crucial method used here is the barycenter method for probability measures. A good introduction of barycenter theory can be found in Section 4 of \cite{KT03}. 

\begin{proposition}
    Suppose $g_1,g_2 \in R^-(M)$. Then there exists an optimal Lipschitz map $f_0$ from $g_1$ to $g_2$. In particular, the stretch locus $E(g_1,g_2)$ is a nonempty subset of $M$.
\end{proposition} 
\begin{proof}
    Since $E(g_1,g_2)$ is closed, let us consider the open subset $M\setminus E(g_1,g_2)$.  For any $x\in M\setminus E(g_1,g_2)$, by the definition of the stretch locus $E(g_1,g_2)$, there exists a best Lipschitz map $f_x$ and some constant $\varepsilon_x>0$ such that 
    $$\Lip_x(f_x, g_1,g_2) < L(g_1,g_2)-\varepsilon_x<L(g_1,g_2). $$

  Since the local Lipschitz constant is upper semicontinuous (Remark \ref{remark, LocalLip}), there exists a small neighborhood $U_x$  so that for any $x'\in U_x$,
 $$\Lip_{x'}(f_x, g_1,g_2) < \Lip_{x}(f_x, g_1,g_2)+\frac{\varepsilon_x}{2}< L(g_1,g_2)-\frac{\varepsilon_x}{2}.$$

We take a small geodesic ball $B^{g_1}_r(x)$ inside $U_x$ that is convex with respect to $g_1$(see for example, \cite[Chapter 3, Proposition 4.2]{DoC92}). By abuse of notation, we denote $U_x$ to be $B^{g_1}_r(x)$ . The family $\{U_x\}_{x\in M}$ forms a covering of $M \setminus E(g_1,g_2)$. Since $M\setminus E(g_1,g_2)$ as an open subset of $M$ is $\sigma$-compact, it is a union of countable many compact subsets. Therefore, there exist countable many open convex subsets $U_i=U_{x_i}$ (corresponding to best Lipschitz maps $f_{x_i}$) that covers $M\setminus E(g_1,g_2)$. 

Since the Lipschitz maps $f_{x_i}$ are homotopic to the identity Lemma \ref{lem, uniquelift} implies that they have unique Lifts with $\widetilde f_{x_i}  \gamma = \gamma\widetilde f_{x_i} $ for all $\gamma \in \Gamma$.
Fix $z_0 \in \widetilde M$. For any $x$ in $\mathcal{F}$, we define  the probability measure on $(\widetilde M,g_2)$ as 
$$p_x:= \sum_{k=1}^{\infty} \alpha_k \delta_{\widetilde f_{\scaleto{x_k}{4pt}}(x)},$$
where $\{ \alpha_k \}_{k\in\mathbb{N}}$ is a sequence of positive real numbers satisfying the following conditions:
\begin{itemize}
    \item $\sum\limits_{k\in\mathbb{N}} \alpha_k =1 $.
    \item $\{ \alpha_k \}_{k\in\mathbb{N}}$ decays fast enough so that
$$\int_{\widetilde M} d_{g_2}^2(y,\widetilde f_{x_1}( z_0)) dp_{z_0}(y)= \sum_{k=1}^{\infty} \alpha_k d^2_{g_2}(\widetilde f_{x_k}(z_0) ,\widetilde f_{x_1}(z_0)) < \infty.$$
\end{itemize}
Using the inequality $(a+b+c)^2\leq 3(a^2+b^2+c^2)$ and the fact that the maps $\widetilde f_{x_k}$ are $L:=L(g_1,g_2)$-Lipschitz we obtain
\begin{align*}
\int_{\widetilde M} & d_{g_2}^2(y,\widetilde f_{x_1}(x)) dp_{x}(y) = \sum_{k=1}^{\infty} \alpha_k d^2_{g_2}(\widetilde f_{x_k}(x) ,\widetilde f_{x_1}(x)) \leq 3\sum_{k=1}^{\infty} \alpha_k \big(d^2_{g_2}(\widetilde f_{x_k}(x) ,\widetilde f_{x_k}(z_0))\\
&+3\sum_{k=1}^{\infty} \alpha_k d^2_{g_2}(\widetilde f_{x_k}(z_0) ,\widetilde f_{x_1}(z_0))+3\sum_{k=1}^{\infty} \alpha_k d^2_{g_2}(\widetilde f_{x_1}(z_0) ,\widetilde f_{x_1}(x))\big) \\
&\le 6 L^2 d_{g_2}^2(x,z_0) + +3\sum_{k=1}^{\infty} \alpha_k d^2_{g_2}(\widetilde f_{x_k}(z_0) ,\widetilde f_{x_1}(z_0)) < \infty.
\end{align*}
Therefore, for all $z, x \in \widetilde M$ we have
\begin{align*}
\int_{\widetilde M} d_{g_2}^2(z,y) dp_x(y) &\le 2 \int_{\widetilde M} d_{g_2}^2(z, \widetilde f_{x_1}( z_0))) dp_x(y) + 2 \int_{\widetilde M} d_{g_2}^2( \widetilde f_{x_1}( z_0)),y) dp_x(y)\\
&\le d_{g_2}^2(z, \widetilde f_{x_1}( z_0))) +2 \int_{\widetilde M} d_{g_2}^2( \widetilde f_{x_1}( z_0)),y) dp_x(y) < \infty\\
\end{align*}
Hence
$
F_x: \widetilde{M} \rightarrow \mathbb{R}
$
with 
$$F_x(z) =\int_{\widetilde M} d_{g_2}^2(z,y) dp_x(y)$$ defines a strictly convex function which has a unique minimum
$b(p_x)$  called the $d^2$-barycenter map of the probability measure $p_x$ (see e.g. Proposition 4.3 of \cite{KT03} for further details).


Since the Lipschitz maps $\widetilde f_{\scaleto{x_k}{4pt}}$ are $\Gamma$-equivariant, one obtains $\gamma_* p_x=p_{\gamma x}$ for any $\gamma\in\Gamma$.  Since the barycenter $b$ is $\Gamma$-equivariant  as well (\cite[Lemma5.1]{KT03}) we obtain for any $\gamma \in \Gamma$
$$\gamma\widetilde f_0(x) =\gamma(b(p_x))=b(\gamma_* p_x)= b(p_{\gamma x})=\widetilde f_0(\gamma x).$$
Therefore, Lemma \ref{lem, uniquelift} implies that $\widetilde f_0 $ descends to a map $f_0 :M \to M$
homotopic to the identity.
Now we show that $\widetilde f_0 :\widetilde M \to \R$
with 
$$\widetilde f_0(x):= b(p_x)$$ 
defines an optimal map. 
For that we note that non-positive curvature yields the barycenter contracting property (see \cite[Theorem 6.3]{KT03}),  i.e. for any pair $x, x'$ on $\widetilde M$ we have,
$$d_{g_2}(\widetilde f_0(x),\widetilde f_0(x')) \leq \sum_{k=1}^{\infty} \alpha_k d_{g_2}(\widetilde f_{\scaleto{x_k}{4pt}}(x), \widetilde f_{\scaleto{x_k}{4pt}}(x')) \le L d_{g_1}(x, x')$$
Hence $\widetilde f_0$ is the lift of the best Lipschitz map $f_0$. In particular, the above estimate holds for any lift $ \widetilde U_i$ of the convex ball $U_i \subset M\setminus E(g_1,g_2)$  and therefore implies that for any $ z \in \widetilde U_i$ by Remark \ref{remark, LocalLip},
\begin{align*}
\Lip_z(\widetilde f_0,g_1,g_2)& \leq \sup_{x'\neq x \in \widetilde U_i} \frac{d_{g_2}(\widetilde f_0 (x), \widetilde f_0 (x'))}{d_{g_1}(x,x')}   \\
&\leq \sup_{x'\neq x \in \widetilde U_i}  \sum_{k=1}^{\infty}  \alpha_k \frac{d_{g_2}(\widetilde f_{\scaleto{x_k}{4pt}}(x), \widetilde f_{\scaleto{x_k}{4pt}}(x'))}{d_{g_1}(x,x')}\\
&\leq \sum_{k\neq i}  \alpha_k L(g_1,g_2) + \alpha_i \Lip(f_{x_i}|_{\widetilde{U_i}}, g_1,g_2)\\
&< L(g_1,g_2)- \alpha_i \frac{\varepsilon_{x_i}}{2} < L(g_1,g_2).
\end{align*}
 Hence the stretch locus $E_{f_0}(g_1, g_2)$ of $f_0$ does not intersect $M \setminus E(g_1, g_2) $ which implies $E_{f_0}(g_1, g_2) \subset E(g_1, g_2) $ and $E(g_1, g_2)$. By
 the definition of $E(g_1, g_2) $ we have  $E(g_1, g_2) \subset E_{f_0}(g_1, g_2)$
we conclude $E(g_1,g_2) = E_{f_0}(g_1, g_2)$. In particular
Remark item (4) of Remark \ref{remark, LocalLip} yields that $E(g_1,g_2)$
is closed and nonempty.

\end{proof}




\subsection{The Mather set and the stretch locus}
\hfill\\
When the least Lipschitz constant equals to the maximal stretch, we have the following characterization of the relation between the Mather set and the stretch locus. Recall that $\pi: S^{g_1}  M  \to  M$ is the projection map. 
\begin{proposition} \label{proposition,MatherStretchLocus}

   Suppose for $g_1,g_2\in R^{-} (M)$, we have  $$S(g_1,g_2)= L(g_1,g_2).$$

    Then the projection of the Mather set $\mathcal{M}(g_1,g_2)$ on $M$ is contained in the stretch locus from $g_1$ to $g_2$, that is
     $$\pi(\mathcal{M}(g_1,g_2)) \subset E(g_1,g_2).$$
\end{proposition}
\begin{proof}
Suppose $S(g_1,g_2)= L(g_1,g_2)$. By Lemma \ref{lem, GeodesicStretchLipStretch}, for a maximal current $\mu_0 \in \mathcal{C}^{g_1} (\Gamma)$ and any $f\in \Lip_{\id}(M, g_1, g_2)$,
$$S(g_1,g_2)= I_{\mu_0}(g_1,g_2) \leq  \int_{S^{g_1} M}  \| Df(v) \|_{g_2} d\hat{m}^{g_1}_{\mu_0}.$$
On the other hand, there exists $f_0\in \Lip_{\id}(M, g_1, g_2)$ so that $ L(g_1,g_2) = \Lip(f_0,g_1,g_2)$. Therefore,  
$\norm{Df_0(v)}_{g_2} \le \Lip_{\pi v} (f_0,g_1,g_2) \le L(g_1,g_2)$ for all $v \in S^{g_1} M$ for which $Df_0(v)$ exists. Hence,
$$ S(g_1,g_2)=L(g_1,g_2) = \Lip(f_0,g_1,g_2)\geq \int_{S^{g_1}M} \norm{Df_0(v)}_{g_2} d\hat{m}^{g_1}_{\mu_{0}}.$$
Therefore,
    \begin{equation} \label{equation, maximallyStretchedGeodesics}
        S(g_1,g_2)=\int_{S^{g_1}M} \norm{Df_0(v)}_{g_2} d\hat{m}^{g_1}_{\mu_{0}}= \Lip(f_0,g_1,g_2) .
    \end{equation}
 Furthermore, 
for all  $(\xi,\eta)$ in the support of ${\mu_{0}}$, Theorem \ref{prop,GeodesicToGeodesic} implies that the lift $\widetilde f_0 \in \mathcal{C}$ of $f_0$ takes the $g_1$-geodesic $c_{\xi, \eta}^{g_1}$ to the corresponding $g_2$-geodesic $c_{\xi, \eta}^{g_2}$. Moreover, for $\hat{m}^{g_1}_{\mu_{0}}$ almost every $v$, $\norm{Df_0(v)}_{g_2}= \Lip (f_0,g_1,g_2) = L(g_1,g_2)$. Then Equation \eqref{equation Length-distance} implies, that every geodesic in the support of $\hat{m}^{g_1}_{\mu_{0}} $ of speed one is mapped to a geodesic of speed $L(g_1, g_2) = S(g_1,g_2)$. Therefore, 
$$\pi (\supp \hat{m}^{g_1}_{\mu_{0}}) \subset E_{f_0}.$$
Since this holds for any Lipschitz map that realizes $L(g_1,g_2)$, we obtain,
$$\pi (\supp \hat{m}^{g_1}_{\mu_{0}}) \subset E(g_1,g_2).$$
Since this also holds for any maximal current $\mu_0$ in $\mathcal{C}^{g_1} (\Gamma)$ and since $E(g_1,g_2)$ is a closed subset, 
%(recall Corollary \ref{Corollary, StretchlocusClosed}), 
we obtain $ \pi(\mathcal{M}(g_1,g_2)) \subset E(g_1,g_2)$.
\end{proof}



 \subsection{The stretch locus and geodesic laminations} 
 \label{subsection,NotLamination}
 \hfill\\
This subsection discusses more examples in $R^-(M)$ where the equality $S(g_1,g_2)= L(g_1,g_2)$ holds. It is based on the work of \cite{GK17} which
investigates the relation between stretch loci and \emph{geodesic laminations} in hyperbolic n-space $\mathbb{H}^n$. \emph{(One-dimensional) geodesic laminations} on hyperbolic surfaces were introduced by Thurston and play a central role in Thurston's study of Teichum\"uller spaces and hyperbolic 3-manifolds. We give here its definition for $n$-dimensional closed manifold $M$ with $n\geq 2$.   
\begin{definition}
    A \emph{(one dimensional)\footnote{In a compact manifold $M$ of dimension $n\geq 3$, it seems that higher diemnsional geodesic laminations, namely laminations whose leaves are totally geodesic and of dimension not less than 2, are more rigid and less interesting. For example, in \cite{Zeg91}, it is proved that all leaves of a codimension one lamination of $M$ are compact.} geodesic lamination} $\mathcal{L}$ of $(M,g)$ is a nonempty closed subset of $M$ that consists of a disjoint union of simple complete (closed or biinfinite) geodesics with respect to $g$.
\end{definition}




The result in \cite{GK17} provides a sufficient condition for the stretch locus $E(g_1,g_2)$ to be a geodesic lamination in the setting of constant negative curvature metrics, regardless of the dimension of the manifold $M$. The key idea in their proof (\cite[Lemma 5.2]{GK17}) is to show, for an optimal Lipschitz map $f_0: (M,g_1)\to (M,g_2)$, every point of the stretch locus $E_{f_0}(g_1,g_2)=E(g_1,g_2)$ lies on a complete simple geodesic that remains entirely in $E_{f_0}(g_1,g_2)$ and does not intersect other parts of the stretch locus. To establish this, they perform a local analysis around a point $x$ in the strech locus $E_{f_0}(g_1,g_2)$. By considering a small ball $B_x$ centered at $x$, they restrict $f_0$ to the boundary $\partial B_x$, and apply the Kirszbraum-Valentine theorem(\cite[Section 3.1]{GK17}) to obtain a Lipschitz extension $\overline{f_0}: \overline{B_x} \to M$ that minimizes the Lipschitz constant. Optimality then ensures $\overline{f_0}$ still has Lipschitz constant equal to $L(g_1,g_2)$. Next, by a clever argument based on triangle comparision (i.e. Toponogov's theorem), they show that there exist only two diametrically opposite points on $\partial B_x$ so that the geodesic segment connecting them is maximally stretched by $\overline{f_0}$, with stretch factor equal to the Lipschitz constant $L(g_1,g_2)$. By iterating this process and extending this geodesic segment, they construct a complete simple geodesic through $x$ that lies entirely in the stretch locus.


Their argument does not rely on hyperbolic geometry involving high symmetry, in contrast to the original work of Thurston \cite{Th98}. Their proofs are based on classical tools in geometry of negatively curved manifolds, specifically the Kirszbraum-Valentine theorem and the Toponogov's theorem. Consequently, it is not hard to convince oneself that their argument can carry over to variable negative curvature under certain curvature assumptions, as will be described in the following theorem.

For a smooth Riemannian metric $g$ on $M$, we denote
$$K^-_g(p) := \min\limits_{\substack{\Pi \subset T_{p} M}} K_{g}(\Pi), \qquad  K^+_g(p) := \max\limits_{ \Pi \subset T_{p} M} K_{g}(\Pi),$$
and
$$K^-_g := \min\limits_{p\in M} K^-_{g}(p), \qquad  K^+_g := \max\limits_{p\in M} K^+_{g}(p),$$
where $\Pi$ are $2$-dimensional planes in $T_{p}M$ and $K_{g}(\Pi)$ are sectional curvatures for $\Pi$ with respect to $g$.




\begin{theorem}[see \cite{GK17} Theorem 5.1, Lemma 5.2] \label{GK, geodesicLamination}
Suppose $g_1,g_2 \in R^-(M)$ satisfies 
   \begin{equation}\label{eqtn,LaminationConditions}
        0 < \frac{K^-_{g_1}}{K^+_{g_2}}<L(g_1,g_2)^2, 
        \end{equation}  
    Then 
    $$S(g_1,g_2) = L(g_1,g_2).$$
    Moreover, $E(g_1,g_2)$ is a geodesic lamination and each leaf of $E(g_1,g_2)$ is maximally stretched by an optimal Lipschitz map $f_0$, in the sense that the lift $\widetilde{f_0}\in\mathcal{C}$ of $f_0$ multiplies all distances of lifts of leaves of $E(g_1,g_2)$ on $(\widetilde{M},g_1)$ by $L(g_1,g_2)$. 
\end{theorem}


\begin{proof}
    Consider $g'_1=\lambda g_1$ for some positive constant $\lambda$. The following conditions are sufficient to apply Theorem 5.1 and then Lemma 4.6 of \cite{GK17} to obtain the desired results in the above statement for Riemannian metrics $g'_1$ and $g_2$:
    $$L(g'_1, g_2) > 1,$$
    $$0> K^-_{g_1} \geq  K^+_{g_2}.$$

    These are equivalent to 
    $$L(g_1, g_2) > \lambda^{\frac{1}{2}} \geq \bigg(\frac{K^-_{g_1}}{K^+_{g_2}}\bigg)^{\frac{1}{2}} >0. $$
    This yields the conditions in the statement.
\end{proof}
Their theorem can be stated in a stronger form as follows.
\begin{corollary}[\cite{GK17}, Theorem 5.1, Lemma 5.2]  \label{Cor, geodesicLamination}
Suppose $g_1,g_2 \in R^-(M)$ and $f_0$ is an optimal Lipschitz map from $(M,g_1)$ to $(M,g_2) $. Suppose for all points $p\in M$,

    $$0> K^-_{g_1}(p)> K^+_{g_2}(f_0(p)) \cdot L(g_1,g_2)^2. $$
    Then 
    $$S(g_1,g_2) = L(g_1,g_2).$$
    Moreover, $E(g_1,g_2)$ is a geodesic lamination that is maximally stretched by some optimal Lipschitz map as described in Theorem \ref{GK, geodesicLamination}.
\end{corollary}

Theorem \ref{GK, geodesicLamination} permits some deformation in $R^-(M)$ because of the following proposition. For this porposition, we can equip $R^-(M)$ with the $C^{\infty}$ topology (in fact, any $C^k$ topology for $k\geq 2$ suffices). 

\begin{proposition} \label{prop,LaminationConditions}
    The set given by
 \begin{align*}
       \mathcal{R}:=\bigg\{ (g_1,g_2)\in R^-(M) \times R^-(M) \text{ }|\text{ } 0 < \frac{K^-_{g_1}}{K^+_{g_2}}<L(g_1,g_2)^2 \bigg\}
 \end{align*}
        is open in $R^-(M) \times R^-(M)$. Therefore, there exists an open set $U$ in $R^-(M) \times R^-(M)$ such that for $(g_1,g_2)\in U$, the stretch locus $E(g_1,g_2)$ is a geodesic lamination that is maximally stretched by some optimal Lipschitz map as described in Theorem \ref{GK, geodesicLamination} and $S(g_1,g_2)=L(g_1,g_2)$.  
\end{proposition} 
\begin{proof}
    Suppose $(g_1,g_2)\in \mathcal{R}$. We want to show if $(g_1',g_2')$ is sufficiently close to $(g_1,g_2)$ in $R^-(M) \times R^-(M)$, then $(g_1',g_2')$ is also in $\mathcal{R}$. The fact that $(g_1,g_2)\in \mathcal{R}$ implies we can find small $\varepsilon>0$ so that, 

   $$L(g_1,g_2)^2- \frac{K^-_{g_1}}{K^+_{g_2}} > \varepsilon>0  . $$ 


     Sectional curvatures are second variation of metric tensors. For $i=1,2$, when a smooth Riemannian metric  $g_i'$ in $R^-(M)$ is in a sufficiently small open neighborhood of $g_i$ (with respect to the topology from $C^k$-norms for $k\geq 2$), we have
     $$\bigg|\frac{K^-_{g_1}}{K^+_{g_2}}  - \frac{K^-_{g'_1}}{K^+_{g'_2}} \bigg|\leq \frac{\varepsilon}{2}.$$
    By Theorem \ref{GK, geodesicLamination}, we know $S(g_1,g_2)=L(g_1,g_2)$ for $(g_1,g_2)\in \mathcal{R}$. And by Proposition \ref{propositionGK, GeodesicStretchContinuous}, the maximal stretch $S(\cdot,\cdot)$ is continuous. So after adjusting $g_i'$ to be even closer to $g_i$, we can make sure
    $$\bigg|S(g'_1,g'_2)^2-S(g_1,g_2)^2\bigg| \leq \frac{\varepsilon}{2}.$$
    Therefore, we obtain by Proposition \ref{prop,LgeqS}
\begin{align*}
L(g'_1,g'_2)^2&\geq S(g'_1,g'_2)^2 \geq S(g_1,g_2)^2- \frac{\varepsilon}{2}\\
&=L(g_1,g_2)^2-\frac{\varepsilon}{2}\\
&> \frac{K^-_{g_1}}{K^+_{g_2}}+ \frac{\varepsilon}{2} \geq \frac{K^-_{g'_1}}{K^+_{g'_2}}.
\end{align*}

So $(g'_1,g'_2)$ also satisfies  inequality \eqref{eqtn,LaminationConditions} and $(g'_1,g'_2)\in \mathcal{R}$. As a consequence, $E(g'_1,g'_2)$ is a geodesic lamination and $L(g'_1,g'_2)=S(g'_1,g'_2)$. We obtain the desired result.
\end{proof}

 When the dimension of $M$ is $n=2$, the above discussion provides abundant examples of stretch loci being geodesic laminations.



\begin{remark} [Laminations may survive in $R^-(S)$] \label{remark,LaminationSurvive} 
    Let $M=S$ be a closed surface of genus $\mathcal{G}\geq 2$. Take $g_1$ and $g_2$ to be hyperbolic metrics representing different points $[g_1]$ and $[g_2]$ in the Teichm\"uller space $\mathcal{T}(S)$. From \cite{Th98}, we know  
    $$S(g_1,g_2)^2=L(g_1,g_2)^2 >1 = \frac{K^-_{g_1}}{K^+_{g_2}}.$$
    Lift the set  
    \begin{align*}
    \mathcal{T}^{(2)}(S)&:=\mathcal{T}(S) \times \mathcal{T}(S)\setminus \diag 
    \end{align*}
    to a subset of $R^-(S)\times R^-(S)$ and denote it as  $\widetilde{ \mathcal{T}^{(2)}(S)}$. The proposition \ref{prop,LaminationConditions} then implies that there exists a nonempty open neighborhood $U$ of $\widetilde{ \mathcal{T}^{(2)}(S)}$ in $R^-(S)\times R^-(S)$ so that for $(g_1,g_2) \in U$, the stretch locus $E(g_1,g_2)$ is still a geodesic lamination and $L(g_1,g_2)=S(g_1,g_2)$. 
\end{remark}







\subsection{Example of a stretch locus which is not a geodesic lamination}
\hfill\\
Let $M=S$ be a closed surface of genus $\mathcal{G} \geq 2$. In this subsection, we provide an example of metrics $g_1,g_2 \in R^-(S)$ for which the stretch locus $E(g_1,g_2)$ is not a geodesic lamination. 

 In the Teichm\"uller space $\mathcal{T}(S)$, the equality $L(g_1,g_2)=S(g_1,g_2)$ always holds and the geodesic flow $\phi^{g_1}$ on the Mather set $\mathcal{M}(g_1,g_2)$ always has zero topological entropy. In contrast, as a further observation from this example, we show that the topological entropy of the geodesic flow $\phi^{g_1}$ on the Mather set for general $g_1,g_2\in R^-(S)$ can be positive.

\begin{example}[positive entropy example] 
\label{MatherNotLamination} Suppose $M=S$ is a genus $\mathcal{G} =2$ closed surface and $g_1$ is a hyperbolic metric on $M$. Let $M_1\subset (M,g_1)$ be a subsurface bounded by a separating simple closed geodesic $\gamma^{g_1}_0$ (see Figure \ref{fig: figure2}).  Let $a>1$ be a constant. Consider a metric $g_2=\varphi g_1$ which is conformal to $g_1$, where $\varphi: M \to (0,\infty)$ is a smooth function that satisfies the following conditions:
\begin{enumerate}
    \item $\varphi(x)=a \hspace{4cm} \text{  for } x\in M_1$.
     \item 
     $0< \varphi(x)< a \hspace{3.25cm} \text{ for } x\in M \backslash M_1$.
     \item 
     $K_{g_2}(x)= \frac{1}{\varphi(x)}(-1-\Delta_{g_1} \log \varphi )<0 \hspace{0.6cm} \text{ for } x\in M$,
\end{enumerate}
  where $\Delta_{g_1} f = \textnormal{div} \circ \grad f$ is the negative Laplacian Beltrami operator with respect to $g_1$.
Then the stretch locus $E(g_1,g_2)$ (and the projection of the Mather set $\pi (\mathcal{M}(g_1,g_2))$) are not geodesic laminations. Moreover,
\begin{itemize}
    \item the topological entropy of $\phi^{g_1}$ on the Mather set $\mathcal{M}(g_1,g_2)$ satisfies
$$h_{top}(\phi^{g_1},\mathcal{M}(g_1,g_2))>0.$$ 
    \item  The Hausdorff dimension of $\mathcal{M}(g_1,g_2)$ is
    $$
     Hd(\mathcal{M}(g_1,g_2))  =2h_{top}(\phi^{g_1},\mathcal{M}(g_1,g_2))+1>1.$$
\end{itemize} 
 \end{example}



\begin{figure}[!htb]
   \centering    \includegraphics[width=\textwidth]{drawing-1.pdf}
    \caption{$(M,g_1)$ is a closed hyperbolic surface of genus 2. The yellow part $M_1$ is a submanifold of $(M,g_1)$ bounded by a seperating simple closed $g_1$-geodesic $\gamma^{g_1}_0$. The generators of the fundamental group $\pi_1(M_1)$ is represented by two simple closed $g_1$-geodesics $\gamma^{g_1}_1$ and $\gamma^{g_1}_2$ in the figure.} 
    \label{fig: figure2}
\end{figure}

\begin{proof}


Suppose $\gamma:[0,1]\to M_1$ is a closed geodesic with respect to $g_1$. Then it is also a closed geodesic with respect to $g_2$ and 
$$\ell_{g_2}([\gamma])=\int_0^1 g_2(\dot{\gamma}(t),\dot{\gamma}(t))^{\frac{1}{2}}dt= \sqrt{a}\int_0^1 g_1(\dot{\gamma}(t),\dot{\gamma}(t))^{\frac{1}{2}}dt=\sqrt{a}\ell_{g_1}([\gamma]). $$

On the other hand, if $\gamma:[0,1]\to M$ is a closed geodesic with respect to $g_1$ not entirely lying in $M_1$, then we know
\begin{align*} 
\ell_{g_2}([\gamma])&\leq L_{g_2}(\gamma)=\int_0^1 \varphi^{\frac{1}{2}}(\gamma(t))g_1(\dot{\gamma}(t),\dot{\gamma}(t))^{\frac{1}{2}}dt\\
&<\sqrt{a}\int_0^1 g_1(\dot{\gamma}(t),\dot{\gamma}(t))^{\frac{1}{2}}dt=\sqrt{a}L_{g_1}(\gamma)= \sqrt{a}\ell_{g_1}([\gamma]). 
\end{align*}

Together, we obtain 
$$S(g_1,g_2)=\sup_{[\gamma]\in[\Gamma]} \frac{\ell_{g_2}([\gamma])}{\ell_{g_1}([\gamma])}=\sqrt{a}.$$

We also know that the identity map satisfies
$$\text{Lip}(\id, g_1, g_2)=\max_{v\in S^{g_1}M}\frac{||v||_{g_2}}{||v||_{g_1}}=\max_{v\in S^{g_1}M} \varphi(\pi(v) )=\sqrt{a}.$$
As a consequence,  $E_{\id}(g_1,g_2)= M_1$ and also
$$S(g_1,g_2)=\text{Lip}(\id,g_1,g_2)= L(g_1,g_2)$$ and the identity map is a best Lipschitz map.  Moreover, from Proposition \ref{proposition,MatherStretchLocus}, we conclude
$$\pi(\mathcal{M}(g_1,g_2)) \subset E(g_1,g_2)\subset E_{\id}(g_1,g_2)= M_1.$$

From previous arguments, we know that $\pi(\mathcal{M}(g_1,g_2))$ contains all closed $g_1$-geodesics on $M_1$. We conclude that the sets $\pi(\mathcal{M}(g_1,g_2))$ and $E(g_1,g_2)$ are not geodesic laminations. \footnote{This example does not satisfy the condition in Theorem \ref{GK, geodesicLamination} since

$$\frac{K^-_{g_1}}{K^+_{g_2}}\geq \max_{x\in M} \frac{-\varphi(x)}{-1- \Delta_{g_1} \log \varphi } \geq a= L(g_1,g_2)^2. $$} 


To obtain a better understanding of the Mather set $\mathcal{M}(g_1,g_2)$, let us further denote $\Gamma_1$ as the subgroup in $\mathrm{PSL}(2,\mathbb{R})$ freely generated by two elements represented by simple closed geodesics $\gamma^{g_1}_1$ and $\gamma^{g_1}_2$ on $M_1$ (See Figure \ref{fig: figure2}).  Consider the complete convex cocompact hyperbolic surface $\mathbb{H}^2/\Gamma_1$ given by a one-holed torus glued with an expanding funnel of infinite volume (see for example, \cite[page 500]{Eb72II}). This noncompact surface contains $M_1$ as its convex core. Since the Mather set $\mathcal{M}(g_1,g_2) \subset S^{g_1}M_1,$ it follows easily from the definition of the Mather set that $\mathcal{M}(g_1,g_2) \subset \Omega$, where $\Omega$ is the nonwandering set of the geodesic flow on the unit tangent bundle of $\mathbb{H}^2/\Gamma_1$ which is also contained in $S^{g_1}M$. A simple hyperbolic geometry computation shows that if a geodesic leaves $M_1$ in forward time direction in $\mathbb{H}^2/\Gamma_1$, then it will never go back to $M_1$.  On the other hand, because the Mather set $\mathcal{M}(g_1,g_2)$ contains all periodic vectors on $S^{g_1}M$ and because periodic vectors of $S^{g_1}(\mathbb{H}^2/\Gamma_1)$ are dense in $\Omega $ (
\cite[Theorem 3.10]{Eb72II}). We conclude from closedness condition of $\mathcal{M}(g_1,g_2)$ that $\Omega \subset \mathcal{M}(g_1,g_2)$. Therefore 
$\mathcal{M}(g_1,g_2)=\Omega$
and the topological entropy $h_{top}(\phi^{g_1},\mathcal{M}(g_1,g_2))$ is equal to the topological entropy of the geodesic flow on $\mathbb{H}^2/\Gamma_1$ which is strictly positive. It also equals to the critical exponent $\delta(\Gamma_1)$ of $\Gamma_1$(\cite{Su79}).

Since from Corollary 3.8 of \cite{Eb72II}, the nonwandering set $\Omega$ is identified as 
$$\Omega \simeq \Lambda^{(2)}(\Gamma_1)\times \mathbb{R},$$
where $\Lambda(\Gamma_1)$ denotes the limit set of $\Gamma_1$ and $$\Lambda^{(2)}(\Gamma_1)=\Lambda(\Gamma_1) \times \Lambda(\Gamma_1)\setminus \diag.$$ From Patterson Sullivan theory, the Hausdorff dimension of $\Lambda(\Gamma_1)$ equals to the critical exponent $\delta(\Gamma_1)$ of $\Gamma_1$. As a consequence of the above identification, the Hausdorff dimension of $\mathcal{M}(g_1,g_2)=\Omega$ is 
$$Hd(\mathcal{M}(g_1,g_2))=2\delta(\Gamma_1)+1.$$
\end{proof}


We thank Islam Mitul for discussing properties of convex cocompact manifolds with us. We also thank Sami Douba for pointing out to us the following fact.
\begin{remark}
     Compared  with Corollary \ref{cor,RigidityTopEntropy} and Theorem \ref{thm, EmtpyInterior}, the above example shows that even when the marked length spectra of $g_1$ and $g_2$ are not proportional, the topological entropy of the Mather set $h_{top}(\phi^{g_1},\mathcal{M}(g_1,g_2))$ can be arbitrarily close to $h_{top}(\phi^{g_1})=1$ and the Hausdorff dimension of \newline $ Hd(\mathcal{M}(g_1,g_2))$ can be arbitrarily close to the Hausdorff dimension of the full unit tangent bundle by taking hyperbolic metrics $g_1$ so that the lengths of the separating simple closed $g_1$-geodesics $\gamma_0^{g_1}$ go to zero (i.e. pinching the hyperbolic surface to a cusped case).
\end{remark} 



We notice that the conditions in Theorem  \ref{GK, geodesicLamination} and arguments in Lemma 5.2 of \cite{GK17} based on triangle comparison theorems are not necessary conditions for $E(g_1,g_2)$ to be a maximally stretched geodesic lamination. We have further discussion of related phenomena in Appendix \ref{appendix, C}. 

 \section{Maximal stretches, Lipschitz maps and volume}\label{section,StretchLipVol}

 All results in this section about length spectra, Lipschitz maps and volume are not new. We do not claim any novelty in them. Since these results from previous works of different authors were not presented from the perspective of maximal stretches and least Lipschitz constants,  we include this section to give a nice picture of how these objects, maximal stretches, least Lipschitz constants and volumes, are related to each other. Important related work include but not restricted to \cite{BCG94}, \cite{Kn95}, \cite{CD04} and \cite{GL19}.
\subsection{Lipschitz maps and volumes}
\hfill\\
We discuss relation between least Lipschitz constants and volumes of Riemannian manifolds.
\begin{proposition} 
    Suppose $\dim M=n \geq 2$ and suppose $g_1, g_2\in R^-(M)$. Then 
    $$\frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)} \leq L(g_1,g_2)^n.$$
   Moreover, equality holds if and only if $g_1$ is isometric to $g_2$ up to a multiplicative constant.
\end{proposition}
\begin{proof}

 Suppose $L=L(g_1,g_2)$.  Consider a scaling of the metric $g_2$ given by $g_2'= \frac{1}{L^2}g_2$. Then $\textnormal{vol}(M,g'_2)= \frac{1}{L^n}\textnormal{vol}(M,g_2)$ and $L(g_1,g'_2)=1$. A best Lipschitz map $f \in \Lip_{\id}(M,g_1,g_2)$ is a $1$-Lipschitz map between $(M,g_1)$ and $(M,g_2')$. To prove the statement, it is equivalent to show
 $$\textnormal{vol}(M,g_2')\leq\textnormal{vol}(M,g_1),$$
 with equality if and only if $g_2'$ is isometric to $g_1$. Since $f$ is homotopic to identity, it is of degree one. The result then follows from \cite[Appendix C,  Proposition C.1, Lemme C.2]{BCG94}.


\end{proof}

  \subsection{Maximal stretch and volume}
\hfill\\
We observe the following relation between maximal stretches (minimal stretches) and volumes when $M$ is a closed surface. The proof can be derived from \cite[Thoerem 1.1]{CD04} and \cite[Theorem 5.1]{BCLS18}.

 We will denote $s(g_1,g_2):=\min\limits_{\mu\in \mathcal{C}(\Gamma)} I_{\mu}(g_1,g_2)$ as the \emph{minimal stretch}. 
\begin{proposition} \label{prop, bonahonIntersection}
    Suppose $\dim M=2$ and suppose $g_1, g_2\in R^-(M)$. Then 
    $$s(g_1,g_2)^2 \leq \frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)} \leq S(g_1,g_2)^2.$$
   Moreover, either equality holds if and only if $g_1$ is isometric to $g_2$  up to a multiplicative constant.

\end{proposition}
\begin{proof}
Recall from Subsection \ref{subsection GeodesicStretchIntersection}, we mentioned that Bonahon's intersection number $i:  \mathcal{C} (\Gamma) \times  \mathcal{C} (\Gamma) \to \mathbb{R}$ is continuous and symmetric , where  $\mathcal{C} (\Gamma)$ is the space of $\Gamma$-invariant geodesic currents. We denote by $\lambda_g$ the associated Liouville current for a metric $g$. Since $s(g_1,g_2)$ is the minimal stretch, it follows from Remark \ref{remark,intersection}, for any $[\gamma] \in [\Gamma]$ and the associated dirac current $\delta_{[\gamma]}$ and any constant $c>0$
 \begin{equation} \label{equation, geqMinimalStretch}
     i(c\delta_{[\gamma]}, \lambda_{g_2})=c\ell_{g_2}([\gamma])\geq s(g_1,g_2) c \ell_{g_1}([\gamma])= s(g_1,g_2) i(c\delta_{[\gamma]}, \lambda_{g_1}).
      \end{equation}
 Since the intersection number is continuous, taking properly scaled sequences of dirac currents $\delta_{[\gamma_n]}$ approximating $\lambda_{g_2}$ (resp. $\lambda_{g_1}$) in Equation \eqref{equation, geqMinimalStretch} yields,
 \begin{equation} \label{equation, geqMinimalStretchb}
 i( \lambda_{g_2}, \lambda_{g_2})\geq  s(g_1,g_2) i( \lambda_{g_2}, \lambda_{g_1}) \; \;
  \end{equation} 
  and 
   \begin{equation} \label{equation, geqMaxStretchb}
 \; \; i( \lambda_{g_1}, \lambda_{g_2})\geq  s(g_1,g_2) i( \lambda_{g_1}, \lambda_{g_1}).
 \end{equation} 
Since the intersection number is symmetric, we know $i( \lambda_{g_1}, \lambda_{g_2})= i( \lambda_{g_2}, \lambda_{g_1})$. 
Together, we obtain
$$i( \lambda_{g_2}, \lambda_{g_2})\geq  s(g_1,g_2)^2 i( \lambda_{g_1}, \lambda_{g_1}).$$
The intersection number of Liouville currents satisfies from Definition \ref{def:intersection},

$$i( \lambda_g, \lambda_g) = m_{\lambda_g}^g(S^gM)=2\pi \cdot \textnormal{vol}(M,g).
$$ 

We obtain

$$s(g_1,g_2)^2 \leq \frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)}.
$$
Using the inequality $\ell_{g_2}([\gamma])\leq S(g_1,g_2) \ell_{g_1}([\gamma])$
together with the arguments above yields the other inequality in the proposition.

Now assume that $$s(g_1,g_2)^2 = \frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)}.$$

This implies $i( \lambda_{g_2}, \lambda_{g_2})= s(g_1,g_2)^2 i( \lambda_{g_1}, \lambda_{g_1})$ and by Equations
\eqref{equation, geqMinimalStretchb} and \eqref{equation, geqMaxStretchb}, we obtain for $j \in \{1,2\}$
  $$
 i( \lambda_{g_j}, \lambda_{g_2})=  s(g_1,g_2) i( \lambda_{g_j}, \lambda_{g_1}).
 $$


From the transformation formula in Proposition \ref{prop: transformation-formula}, we obtain 
$$
i( \lambda_{g_2}, \lambda_{g_1})=  m_{\lambda_{g_1}}^{g_2}(S^{g_2}M) = \int_{S^{g_1}M}   a_{g_1,g_2} dm_{\lambda_{g_1}}^{g_1} =s(g_1,g_2) i( \lambda_{g_1},\lambda_{g_1})
$$
Therefore, 
\begin{equation} \label{equation, IntegralMinimalStretch}
\int_{S^{g_1}M}  ( a_{g_1,g_2}-s(g_1,g_2)) dm_{\lambda_{g_1}}^{g_1} = 0.
\end{equation}
On the other hand, for any $\delta_{\gamma}$, we have
$$\int_{S^{g_1}M}  ( a_{g_1,g_2}-s(g_1,g_2)) dm_{\delta_{[\gamma]}}^{g_1}= \ell_2([\gamma])-s(g_1,g_2)\ell_2([\gamma]) \geq 0.$$
Therefore, \cite[Theorem 1]{LT05}implies  the existence of a H\"older continuous function $u:  S^{g_1}M \to \R$ differentiable along flow lines of the geodesic flow of $g_1$ such that
 $ a_{g_1,g_2}- s(g_1,g_2) \ge X_{g_1} u $.  Combining with Equation \eqref{equation, IntegralMinimalStretch}, we obtain that $ a_{g_1,g_2}- s(g_1,g_2)$ is cohomologous to zero. Therefore $\ell_2([\gamma])= s(g_1,g_2) \ell_2([\gamma])$ for all $[\gamma]$. By the marked length rigidity theorem for surfaces (\cite{Cr90}, \cite{Ot90}), one concludes that $g_2$ is isometric to $g_1$ up to a multiplicative constant.\\
An analogous reasoning yields the other equality in the above proposition. 
\end{proof}
There is a version of the above proposition above for arbitrary dimensions provided the metrics are conformally equivalent. More precisely,
\begin{proposition}
Suppose  $\dim M=n \geq 2$ and  $g_1, g_2\in R^-(M)$ are conformally equivalent. Then
 \begin{equation}\label{eqtn,VolStretch}
     s(g_1,g_2)^n \leq \frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)} \leq S(g_1,g_2)^n.
     \end{equation}
Moreover, either equality holds if and only if $g_1$ is isometric to $g_2$ up to a multiplicative constant.
\end{proposition}
\begin{proof}
Assume that $g_1, g_2\in R^-(M)$ are conformally equivalent, i.e. there exists a smooth positive function $\varphi: M \to \R$ such that $g_2= \varphi g_1$. Let $\lambda_{g_1}$ be the Liouville current of $g_1$ and let $\hat m_{\lambda_{g_1}}^{g_1} $ be the corresponding probability measure. We follow the arguments in the proof of Theorem 4.1 in \cite{Kn95} using Jensen's inequality.

\begin{eqnarray*}
s(g_1,g_2)^2 \le I_{\lambda_{g_1}} (g_1, g_2)^2  &\le\int_{S^{g_1}M} g_2(v, v) d\hat m_{\lambda_{g_1}}^{g_1}  =\frac{1}{\vol( M,g_1)} \int_{M} \varphi d\vol_{g_1} \\
 & \le\left(\frac{\int_{M} \varphi^{\frac{n}{2}} d\vol_{g_1}}
{\vol( M, g_1)}\right)^{\frac{2}{n}} 
 =  \left(\frac{\vol(M,g_2)}{\vol(M,g_1)}\right)^{\frac{2}{n}}.
\end{eqnarray*}
This yields the first inequality. To obtain the second inequality in the proposition, we take the Liouville current $ \lambda_{g_2}$ of $g_2$.
Since
$$
S(g_1,g_2) \ge I_{\lambda_{g_2}}(g_1,g_2) = \frac{1}{I_{\lambda_{g_2}}(g_2,g_1)}
$$
and
$$
I_{\lambda_{g_2}}(g_2,g_1) \le \left(\frac{\vol(M,g_1)}{\vol(M,g_2)}\right)^{\frac{1}{n}}.
$$
we obtain 
$$
S(g_1,g_2)^n \ge \frac{\vol(M,g_2)}{\vol(M,g_1)}
$$
If an equality holds in one of the two estimates in Equation \eqref{eqtn,VolStretch} of the proposition,  Jensen's inequality 
must be an equality as well and therefore the conformal factor $\varphi$ is constant.
\end{proof}
Based on the work of Guillarmou and Lefeuvre \cite{GL19},
the estimates in Equation \eqref{eqtn,VolStretch} hold for an arbitrary pair of negatively curved metrics which are sufficiently close in a suitable $C^N$ norm in $R^-(M)$.
More precisely:

\begin{proposition}
Let $g_1$ be a Riemannian metric in $R^-(M)$
let and $N > \frac{n}{2} +2$.
Then there exists an $\varepsilon >0$ such that for all $g_2 \in R^-(M)$
with $\| g_2 -g_1 \|_{C^N} <\varepsilon $  we have 
 \begin{equation*}\label{eqtn,VolStretch-nonconformal}
     s(g_1,g_2)^n \leq \frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)} \leq S(g_1,g_2)^n.
     \end{equation*}
     Furthermore, either equality holds if and only if $g_1$  and $g_2$ are isometric up to a multiplicative constant.
\end{proposition}  
 \begin{proof}

      The proof is a consequence of Theorem 2 of \cite{GL19} which says: there exists an $\varepsilon_1 >0$ such that for all metrics $g_2 \in R^-(M)$ with $\| g_2 -g_1 \|_{C^N} <\varepsilon_1$, the inequalities $\ell_{g_1}([\gamma]) \le \ell_{g_2}([\gamma])$ for all $[\gamma] \in [\Gamma]$ 
    implies $\vol(M,g_1) \le \vol(M,g_2) $. Furthermore, $\vol(M,g_1) =\vol(M,g_2) $ holds if and only if $g_1$ and $g_2$ are isometric. \\
Now choose $\varepsilon >0 $ such that for $g_2 \in R^-(M)$
satisfying $\| g_2 -g_1 \|_{C^N} <\varepsilon$, we have $\| r g_2 -g_1 \|_{C^N} <\varepsilon_1$ for both $r= r_S = S(g_1,g_2)^{-2} $ and  $r=r_s=s(g_1,g_2)^{-2} $. 
Then we obtain by Theorem 2 of \cite{GL19} , for $g^S_2 = r_S g_2$,
$$
   \ell_{g^S_2}([\gamma])= \frac{1}{ S(g_1,g_2)} \ell_{g_2}([\gamma])\leq \ell_{g_1}([\gamma]).
   $$ 
This implies $\vol(M,g^S_2)\leq \vol(M,g_1)$ which is equivalent to
$\frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)} \leq S(g_1,g_2)^n$. 

Moreover, $\frac{\textnormal{vol}(M,g_2)}{\textnormal{vol}(M,g_1)} = S(g_1,g_2)^n$ implies  $\vol(M,g^S_2) = \vol(M,g_1)$ and therefore  $g^S_2$ is isometric to $g_1$. The other part follows from similar arguments.
 \end{proof}





\appendix



\section{An example of $S(g_1,g_2)< L(g_1,g_2)$} \label{ExampleS<L}
\hfill\\
In this appendix, we discuss an example of $g_1,g_2\in R^-(M)$ with $S(g_1,g_2)< L(g_1,g_2)$ based on the work of \cite{GR24} adapted to our setting.

We start with some preparation lemmas. Recall the $g-$length of a general Lipschitz curve $\alpha$ is denoted by $L_{g}(\alpha)$. 
\begin{lemma} \label{lemma,LengthUniformConverge}
Let $g$ be a Riemannian metric in $R^-(M)$ and let $\gamma: \R \to M$  be a geodesic on $M$ that is 1-periodic, i.e. $\gamma(t) = \gamma(t+1)$ for all $t \in \R$. We denote the restriction of $\gamma$ to the interval $[0,1]$ as $\gamma_1:[0,1]\to M$ and denote $L_g(\gamma):=L_g(\gamma_1)$, the $g$-length of the closed geodesic $\gamma_1$. Consider the space of closed Lipschitz curves on $(M,g)$,
$$\mathcal{L}_c= \{\alpha: [0,1] \to (M,g) \mid \alpha \text{ is Lipschitz and } \alpha(0)=\alpha(1)  \}.$$ Define for some $c> L_g(\gamma)$ the subset 
  $$  \Lip_c([\gamma_1]) :=   \{\alpha \in [\gamma_1] \mid  \alpha\in \mathcal{L}_c, \;  \; \Lip(\alpha) \le c \}
  $$  
  and consider the length functional $L_g$ restricting to $\Lip_c([\gamma_1])$.
  Then for all $\varepsilon > 0$, there exists $\delta >0$ such that for all $\alpha \in \Lip_c([\gamma_1])$
  with 
  $$
  L_g(\alpha) \le  L_g(\gamma) + \delta,
  $$
there exists  $t_0 \in [0,1)$ and a monotone continuous and surjective map $\tau: [0,1] \to [t_0, t_0 +1]$ 
  such that
  $$
  d_g( \alpha(t), \gamma (\tau(t)) \le \varepsilon
  $$
 for all $t \in [0,1]$.  
\end{lemma}
\begin{proof}
Suppose the lemma does not hold.  Then
there exists $ \varepsilon >0$ and a sequence of closed curves $\alpha_{n}:[0,1]\to M$  in $\Lip_c([\gamma_1])$ such that
$$
 L_g(\alpha_n) \le  L_g(\gamma) + \frac{1}{n} \; \text{and} \; d_g( \alpha_n(t), \gamma (\tau(t))) \ge \varepsilon
$$
for some $t \in [0,1]$ and  all monotone continuous and surjective maps $\tau: [0,1] \to [t_0, t_0 +1]$, where $t_0 \in [0,1)$.

By Arzelà-Ascoli Theorem, there exists a subsequence $\alpha_{n_j}:[0,1]\to (M,g)$ that uniformly converges to a closed Lipschitz curve $\alpha$.  Hence
    $$
    \lim\limits_{j\to \infty} \max_{t\in[0,1]} d_g(\alpha_{n_j}(t),\alpha(t))=0.
    $$
    Therefore $\alpha\in [\gamma_1]$. Recall that the length $L_g(\cdot)$ is a lower semi-continuous function of continuous curves (\cite[Chapter I.1, Proposition 1.20 (7)]{BH99}),
    $$L_g(\gamma)\geq \liminf_{j\to \infty} L_g(\alpha_{n_j})\geq L_g(\alpha).$$
Since $\gamma_1$ is up to parametrization the unique shortest closed curve in the homotopy class $[\gamma_1]$, it holds that $L_g(\gamma)=L_g(\alpha)$. Therefore,
there exists for some $t_0 \in [0,1) $ a monotone continuous and surjective map $\tau: [0,1] \to [t_0, t_0 +1]$ such that $ \alpha (t) = \gamma (\tau(t))$.
But then
$$
0= \lim\limits_{j\to \infty} \max_{t\in[0,1]} d_g(\alpha_{n_j}(t),\alpha(t))= \lim\limits_{j\to \infty} \max_{t\in[0,1]} d_g(\alpha_{n_j}(t),\gamma (\tau(t)))
$$
yields a contradiction.
\end{proof}
\begin{lemma} \label{lemma,self-intersection-surfaces}
Let $g$ be a Riemannian metric in $R^-(M)$ and let $\gamma: \R \to M$  be a geodesic that is 1-periodic on $M$ with $\gamma(t) = \gamma(t+1)$ for all $t \in \R$ and has one self-intersection at $p = \gamma(0) = \gamma(s_0)$ for some $s_0 \in (0, 1)$. 
Denote by $\theta_p \in (0 , \frac{\pi}{2}]$ the angle of self-intersection of $\gamma $ at $p$ and therefore $a_p =\cos(\theta_p) \in [0, 1) $. For $\varepsilon >0$ smaller than $1/2$ of the injectivity radius $R_M$ of $M$, let 
$ \alpha: \R \to M$ be a closed continuous curve with $ \alpha(t) = \alpha(t+1)$
freely homotopic to $\gamma$ and let $\tau:\R \to \R$ be a surjective momotone and continuous map with  $\tau(t+1) = \tau(t) +1$  such that 
$d_g( \alpha(t) , \gamma(\tau(t))) < \varepsilon$. Then $\alpha$ has a self-intersection at $q = \alpha (t_0) =  \alpha (t_1)$ such that $0 < t_1 -t_0 <1$ and
\begin{equation} \label{inequality,self-intersection-surfaces}
d_g(p, q) < \varepsilon (\sqrt{\frac{2}{1-a_p}} +1)
\end{equation}
Furthermore, the loops $\gamma: [0, s_0] \to M$ and  $\alpha: [t_0, t_1] \to M$ are free homotopic.
Moreover, if $q' = \alpha (t_0') =  \alpha (t_1')$ is any  self-intersection such that the loop 
$\alpha:[t_0', t_1'] \to M$ is free homotopic to  $\gamma: [0, s_0] \to M$ then the inequality \ref{inequality,self-intersection-surfaces} holds for $q'$.
\end{lemma}
\begin{proof}
Since   $\varepsilon $ is smaller than $1/2$ of the injectivity radius $R_M$, there are lifts  $\widetilde \gamma , \widetilde \alpha : \R \to \widetilde M$ of curves $\gamma: \R  \to M$ and $\alpha: \R  \to M$ respectively such
that  $d_g( \widetilde\alpha(t), \widetilde \gamma(\tau(t)) < \varepsilon$. Since $\widetilde \gamma $ is a geodesic and the projection of $\widetilde p = \widetilde \gamma (0) $  is given by the self-intersection $p$,  there exists $\eta \in \Gamma$, the group of covering transformations of $\widetilde{M}$, such that
$\eta \widetilde \gamma \cap \widetilde \gamma = \eta\widetilde p = \widetilde \gamma(s_0)$. Let $U_\varepsilon (\widetilde \gamma)$ and  $U_\varepsilon ( \eta \widetilde \gamma)$ be the $\varepsilon$-tubular neigborhoods of $\widetilde \gamma$ and  $\eta \widetilde \gamma$. Then $\widetilde\alpha(t) \in U_\varepsilon (\widetilde \gamma)$
and $\eta \widetilde\alpha(t) \in U_\varepsilon (\eta \widetilde \gamma)$ for all $t \in \R$. Therefore the curves
 $\widetilde\alpha$ and  $\eta \widetilde \alpha$ intersects in the set $U_\varepsilon (\widetilde \gamma) \cap U_\varepsilon ( \eta \widetilde \gamma)$ and there exists $ t_0 < t_1$ with $t_1-t_0 <1$ and $\eta \widetilde \alpha(t_0) =\widetilde \alpha(t_1) \in U_\varepsilon (\widetilde \gamma) \cap U_\varepsilon ( \eta \widetilde \gamma)$. Since $\eta \widetilde \gamma (0) = \widetilde \gamma(s_0)$, we obtain that the loops $\gamma_{[0,s_0]}$
 and $\alpha_{[t_0, t_1]}$ are free homotopic.  For any $ x \in  U_\varepsilon (\widetilde \gamma) \cap U_\varepsilon ( \eta \widetilde \gamma)$, denote by $x_1$ (resp.  $x_2$) the orthogonal projections of $x$ onto the geodesics $\widetilde \gamma$ (resp.  $\eta \widetilde \gamma$).    Then
 $$
  d_g(x_1, x_2) \le d_g(x_1, x) + d_g(x, x_2) \le 2 \varepsilon
 $$ 
 Consider the triangle given by $x_1, x_2$ and  $x_0 = \widetilde \gamma (s_0) $ and define $a_i = d_g(x_i, x_0)$ for 
 $i \in \{1,2 \}$.  Since the intersection angle of $\eta \widetilde \gamma$ and 
$\widetilde \gamma$ is $\theta_p$, and since the curvature of the surface is non-positive,
we obtain by triangle comparison and the laws of cosine (see for example, \cite[Lecture I.B]{BGS85})
\begin{align*}
4 \varepsilon^2 &\ge d_g(x_1, x_2)^2 \ge a_1^2 + a_2^2 - 2 \cos{\theta_p}a_1 a_2 \\
&= (a_1-a_2)^2 + 2 a_1 a_2 - 2 a_p a_1a_2\\
&= (a_1-a_2)^2 + 2 a_1 a_2(1-a_p) \\
&\ge  2 a_1 a_2(1-a_p).
\end{align*}
Assume without loss of generality that $a_1 \le a_2$. Then
$$
4 \varepsilon^2 \ge 2 a_1^2 ((1-a_p)
$$
and therefore
$$
a_1 \le \varepsilon \frac{\sqrt{2} }{\sqrt{1-a_p}}.
$$
This implies for all $ x \in  U_\varepsilon (\widetilde \gamma) \cap U_\varepsilon ( \eta \widetilde \gamma)$,
$$
d_g(x, x_0) \le d_g(x,x_1)+d_g(x_0,x_1) \le a_1 + \varepsilon \le \varepsilon (\sqrt{\frac{2}{1-a_p}} +1).
$$
Let 
 $x=\widetilde \alpha(t_1) \in  U_\varepsilon (\widetilde \gamma) \cap U_\varepsilon ( \eta \widetilde \gamma)$ and let $q$ be the projection of $x$. Since the projection of $x_0$ is $p$
and since $d_g(p,q)\leq d_g(x,x_0)$, we obtain Inequality  \eqref{inequality,self-intersection-surfaces}. 
If the loop 
$\alpha:[t_0', t_1'] \to M$ is free homotopic to  $\gamma: [0, s_0] \to M$, then  $\eta \widetilde \alpha(t_0') = \widetilde \alpha(t_1')$. 
Therefore $\eta \widetilde\alpha(t_0') = \widetilde\alpha(t_1')  \in U_\varepsilon (\widetilde \gamma) \cap U_\varepsilon ( \eta \widetilde \gamma)$. Hence, the same argument gives that Inequality (\ref{inequality,self-intersection-surfaces}) holds for the projection point $q'$ of  $\widetilde \alpha(t_1')$.
\end{proof}




We are now able to discuss an example of $S(g_1,g_2)< L(g_1,g_2)$.  We first summarize some results from \cite{GR24}. Given sufficiently small $0<\varepsilon_1< \varepsilon_2$, Gogolev and Reber in \cite{GR24} constructed by perturbation method a pair of Riemannian metrics $g_1,g_2\in R^-(M)$ on a closed surface $M=S$ of genus $\mathcal{G}\geq 2$ with the following properties:
\begin{enumerate}
    \item There exists a closed $g_2$-geodesic $\gamma=\gamma^{g_2}$ with exactly one self-intersection $p = \gamma (0) =\gamma(s_0)$  such that  $\gamma=\gamma^{g_1}$ is also a $g_1$-geodesic up to parametrization.
    \item The two loops $\gamma_1,\gamma_2$ of $\gamma$ separated by $p$ have the following properties,
    $$L_{g_1}(\gamma_1)= L_{g_2} (\gamma_1)- \varepsilon_1, $$
    and 
    $$L_{g_1}(\gamma_2)= L_{g_2} (\gamma_2)+ \varepsilon_2. $$
    \item There exists some $\varepsilon>0$ so that for any $\alpha \in [\Gamma]=[\pi_1 S]$, we have 
    $$\frac{\ell_{g_2} (\alpha)}{\ell_{g_1} (\alpha)}\leq \frac{1}{1+\varepsilon}.$$
     In particular, $S(g_1,g_2) \leq \frac{1}{1+\varepsilon}< 1$.
\end{enumerate}

In the paper \cite{GR24}, the authors focus on the non-existence of shrinking diffeomorphism for such a pair of metrics. For us, since we care about Lipschitz maps homotopic to identity, we provide an argument here of non-existence of Lipschitz maps $f\in \Lip_{\id}(M,g_1,g_2)$ with $\Lip(f,g_1,g_2) < 1$.
\begin{proposition}
    Assume that the positive numbers $\varepsilon_1,\varepsilon_2$ and $\varepsilon_2-\varepsilon_1$ are small enough. Then for metrics $g_1,g_2$ introduced above, there does not exist a Lipschitz map $f\in  \Lip_{\id}(M,g_1,g_2)$ so that $\Lip(f,g_1,g_2) < 1$.  As a consequence, $L(g_1,g_2)\geq 1$.
\end{proposition}

\begin{proof}
    We prove the proposition by contradiction. Suppose there exists $f_0\in  \Lip_{\id}(M,g_1,g_2)$ so that $\Lip(f_0,g_1,g_2) < 1$. Since $f_0\circ \gamma$ is a closed curve homotopic to $\gamma$, we have
  \begin{align*}
      L_{g_2} (\gamma)&\leq L_{g_2}(f_0\circ \gamma)\\
       &\leq \Lip(f_0,g_1,g_2) L_{g_1}(\gamma)\\
      &=\Lip(f_0,g_1,g_2) (L_{g_2}(\gamma)+ \varepsilon_2-\varepsilon_1) < L_{g_2}(\gamma)+ \varepsilon_2-\varepsilon_1.
      \end{align*}
      Therefore we obtain $0\leq L_{g_2}(f_0\circ \gamma) - L_{g_2}(\gamma) < \varepsilon_2 -\varepsilon_1$.
For any $\epsilon >0 $,   Lemma \ref{lemma,LengthUniformConverge} implies the existence
of $ t_0 \in [0,1) $ together with a monotone continuous and surjective map $\tau: [0,1] \to [t_0, t_0 +1]$ 
  such that
  $$
  d_g( f_0 \circ \gamma(t), \gamma (\tau(t))) \le \varepsilon
  $$
 for all $t \in [0,1]$ when $\delta= \varepsilon_2 -\varepsilon_1 $ is sufficiently small.
Since $p =\gamma(0) = \gamma(s_0)$ is the unique self-intersection
 of $\gamma$, $f_0(p) = f_0(\gamma(0)) = f_0(\gamma(s_0))$ is a self-intersection of $f_0\circ \gamma$.
 Since $f_0$ is homotopic to the identity, the loops $\gamma_{[0,s_0]}$ and $f_0 \circ \gamma_{[0,s_0]}$  are free homotopic. Extend $\tau:[0,1]\to [t_0,t_0+1]$ to $\tau:\mathbb{R} \to \mathbb{R}$ by letting $\tau(t+1)=\tau(t)+1$.
Using Lemma \ref{lemma,self-intersection-surfaces}, we obtain $d_{g_2}(p,f_0(p))< \frac{\varepsilon_1}{2}$ provided 
      $\varepsilon (\sqrt{\frac{2}{1-a_p}} +1) \le \frac{\varepsilon_1}{2}$, where $a_p >0$ is the cosine of the angle of self-intersection of $\gamma$.
 Now let $\beta$ be the minimal geodesic connecting $p$ to $f_0(p)$ and $\eta_1=f_0\circ \gamma_1$. Then since we assume $\Lip(f_0,g_1,g_2)  <1$, we obtain
      $$L_{g_2}(\beta \eta_1 \beta^{-1}) \leq \varepsilon_1 + L_{g_2}(f_0 \circ \gamma_1) < \varepsilon_1 + L_{g_1}(\gamma_1)= L_{g_2}(\gamma_1).$$
      Therefore 
      $$L_{g_2}(\gamma_2 \beta\eta_1\beta^{-1})< L_{g_2}(\gamma_1)+ L_{g_2}(\gamma_2) = L_{g_2}(\gamma).$$
      Since the closed curve $\gamma_2  \beta\eta_1\beta^{-1}$ is homotopic to $\gamma$, the estimate above leads to a contradiction of the fact that $\gamma=\gamma^{g_2}$ is the shortest closed curve in its homotopy. Therefore, we conclude that there does not exist a Lipschitz map $f\in  \Lip_{\id}(M,g_1,g_2)$ so that $\Lip(f,g_1,g_2) < 1$.
\end{proof}


\begin{corollary}
     Assume that the positive numbers $\varepsilon_1,\varepsilon_2$ and $\varepsilon_2-\varepsilon_1$ are small enough. Then for metrics $g_1,g_2$ introduced as before, we have
     $$S(g_1,g_2) < L(g_1,g_2).$$
\end{corollary}


\section{Examples for which the stretch locus is a simple closed geodesic}
\label{appendix, C}
\hfill\\
Below, we provide examples of compact surfaces which do not satisfy the condition of Theorem  \ref{GK, geodesicLamination} but where the stretch locus $E(g_1,g_2)$ is a lamination given by a simple closed geodesic.
It is an interesting question to understand what is a necessary and sufficient condition for the stretch locus $E(g_1,g_2)$ to be a geodesic lamination.




Our example is given by perturbing metrics based on a simple closed geodesic. To give the construction, we first state a lemma. 
\begin{lemma} \label{lemma, fermiCoordinates}
    Let $M=S$ be a closed connected oriented surface of genus $\mathcal{G}\geq 2$. Let $g_0\in R^-(S)$ and let $\gamma$ be a simple closed $g_0$-geodesic on $S$. There exists a small tubular neighborhood $U$ of $\gamma$ and a closed set $V\subseteq U$ containing $\gamma$ such that for $0<s<1$, we can find a smooth bump function $\kappa_s: S\to \mathbb{R}$ satisfying,
\begin{enumerate}
    \item $\kappa_s|_{\gamma}\equiv (1-s)^2$.
     \item $\kappa_s|_{V}<1$.
    \item $\kappa_s|_{U^c}\equiv 1$.
    \item $g_s= \kappa_s g_0$ defines a new metric and the closed curve $\gamma$ is a $g_s$-geodesic up to reparametrization.
\end{enumerate}
\end{lemma}
\begin{proof}
    Let $t\mapsto \gamma(t)$ be the $g_0$ arc-length parametrization of $\gamma$. Consider the Fermi coordinate for $g_0$ based at $\gamma$. A point $p$ has Fermi coordinate 
 $(\rho,t)$ if $p$ is of distance $\rho$  to  $\gamma$ (i.e. to the orthogonal projection point on $\gamma$, say $p'$), and $p'=\gamma(t)$. The metric tensor then is 
    $$g_0|_p=d\rho^2+ f(\rho,t)^2 dt^2.$$
    Since $\gamma$ is a $g_0$-geodesic, we have $f(0,t)\equiv 1$ and $\partial_{\rho}f(\rho,t)\big|_{\rho=0}\equiv 0$.

    Let $\varepsilon$ be small so that the boundary of $\varepsilon$-tubular neighborhood $U$ of $\gamma$ are also simple closed curves. Let $0<s<1$ and $m_s(\rho)$ be a smooth function in $\overline{U}$ given by 
     \begin{equation*}
     m_s(\rho)=
\begin{cases}
    1-s,  \hspace{1cm}  \text{when } \rho=0, \\
     1-s \cdot\exp({1-\frac{1}{1-(\frac{\rho}{\varepsilon})^2}}) , \hspace{1cm}   \text{when } 0<|\rho| <\varepsilon, \\
   1,  \hspace{1cm}  \text{when } |\rho| = \varepsilon. 
  \end{cases}
\end{equation*}

For a fixed $s$, the function $m_s(\rho)$ is smooth and monotone in the interval $[0, \varepsilon]$ (resp. the interval $[-\varepsilon,0]$).   Let $\kappa_s: S\to \mathbb{R}$ be given by $\kappa_s\equiv 1$ in the complement of $U$ and $\kappa_s(\rho,t)=m_s(\rho)^2 \leq 1$ in $\overline{U}$. Consider $g_s= \kappa_s g_0$ . The metric tensor for $g_s$ in the same Fermi coordinate is $$g_s|_p= m_s(\rho)^2 d\rho^2+ (m_s(\rho)f(\rho,t))^2 dt^2.$$
The requirement that $\gamma$ is still a reparametrized geodesic for $g_s$ is 
$$\nabla^{g_s}_{\partial_t} \dot{\gamma}(t)\big|_{\rho=0}=h_s(t) \partial_t,$$
for some function $h_s(t)$. One checks from Christoffel symbol computation that this requirement is fulfilled when $\partial_{\rho}m_s(\rho)|_{\rho=0}=0$. This is satisfied with the above chosen $m_s(\rho)$. In this case $h_s(t)\equiv0$ and $t'=(1-s)t$ is the arc-length parameter for $g_s$. Moreover, letting the closed set $V\subset U$ be the closure of $\frac{\varepsilon}{2}$-tubular neighborhood concludes all statements needed. 

\end{proof}

We are now able to discuss the main example in this appendix.

\begin{example}
     Let $M=S$ be a closed connected oriented surface of genus $\mathcal{G}\geq 2$. Consider any hyperbolic metric $g_2$ on $S$ of constant curvature $-1$. Suppose $\gamma_0$ is a simple closed $g_2$-geodesic on $S$. Let $s>0$ be small and let $g_1$ be a small perturbation of $g_2$ described as in Lemma \ref{lemma, fermiCoordinates}.  Then $g_1\in R^-(S)$ and 
    $$S(g_1,g_2)= L(g_1,g_2) =\frac{1}{1-s}>1,$$
    and  $E(g_1,g_2)=E_{\id}(g_1,g_2)=\{\gamma_0\}$ is a geodesic lamination. However, we have for any $p\in\gamma_0$, the sectional curvatures satisfy
        \begin{equation} \label{eqtn, CurvatureInequality}
       K_{g_1}(p) < K_{g_2}(p) L(g_1,g_2)^2.
         \end{equation} 
\end{example}
\begin{proof}
Since $g_s$ in Lemma \ref{lemma, fermiCoordinates} varies smoothly with respect to $s$, so is its sectional curvature $K_{g_s}$. Because $g_2=g_0$ is a hyperbolic metric. For $s$ small enough, we can ensure that $g_1=g_s$ is negatively curved.

By Corollary \ref{corollary, GeodesicStretchBusemannFunction}, we know 
$$
I_m(g_1,g_2) = \int_{S^{g_1}M} g_2(B^{g_2}(\pi (v), v^{g_1}_+), v) dm.
$$    

Since 
$$g_2(B^{g_2}(\pi (v), v^{g_1}_+), v) = \norm{v}_{g_2} \cos \theta_v, $$

where $v\in S^{g_1}M$ and $\theta_v$ is the angle formed from the vector $B^{g_2}(\pi (v), v^{g_1}_+)$ to $v$ counterclockwisely.  Since $g_1=k_s g_2$,
$$\norm{v}_{g_2}= \frac{1}{\sqrt{k_s(\pi(v))}} \cdot \norm{v}_{g_1} \leq \frac{1}{1-s}, $$
and $$ \cos \theta_v \leq 1.$$

Both equalites are realised if and only if  $v$ is tangent to $\gamma_0$ which is a geodesic for both $g_1$ and $g_2$. Therefore, 
$$S(g_1,g_2)=I_{\delta_{\gamma_0}}(g_1,g_2)=\frac{1}{1-s},$$
and 
$\mathcal{M}(g_1,g_2)=\{v\in S^{g_1}M \text{ }| \text{ } v  \text{ is tangent to } \gamma_0\}$.
On the other hand  (see, for example \cite[Proposition 5.2, (ii), (iv)]{DU22} ),
$$L(g_1,g_2) \leq \Lip (\id,g_1,g_2)= \max_{v\in S^{g_1}M} \frac{\norm{v}_{g_2}}{\norm{v}_{g_1}}=\frac{1}{1-s}.$$
Again, the equality is realised when  $v$ is tangent to $\gamma_0$. We obtain $L(g_1,g_2)=S(g_1,g_2)$ and by  Proposition \ref{proposition,MatherStretchLocus},
$$E(g_1,g_2) \subset E_{\id}= \{\gamma_0 \}= \pi(\mathcal{M}(g_1,g_2))\subset E(g_1,g_2),$$
which yields $E(g_1,g_2)=\{\gamma_0 \}$ is a geodesic lamination. Moreover, the identity map is an optimal Lipschitz map and it maximally stretches $\gamma_0$ by $ L(g_1,g_2)$.  

 Next we want to verify Inequality \eqref{eqtn, CurvatureInequality}. We notice that the sectional curvature for metric of the form 
$g=A(u,v)^2du^2+B(u,v)^2 dv^2$
is
$$K_g(p)=\frac{-1}{AB} ({\partial_u}(A^{-1} \partial_{u}{B})+{\partial_v}(B^{-1} \partial_{v}{A})).$$
As discussed in Lemma \ref{lemma, fermiCoordinates}, we can take the Fermi coordinate based at $\gamma_0$ for $g_2$. The curvature for the metric
$g_2|_p=d\rho^2+ f(\rho,t)^2 dt^2$
is,
$$K_{g_2}(p)=\frac{- \partial^2_{\rho}f(\rho,t)}{f(\rho,t)}=-1.$$
In fact, we have $f(\rho,t)=\cosh \rho$.

Consider $p=\gamma_0(t)$ with Fermi coordinate $(0,t)$. Using the conditions  $\partial_{\rho}m_s(\rho)|_{\rho=0}=0$ together with $f(0,t)\equiv 1$ and $\partial_{\rho}f(\rho,t)\big|_{\rho=0}\equiv 0$, we obtain that the sectional curvature for metric $g_1=m_s(\rho)^2 d\rho^2+ m_s(\rho)^2f(\rho,t)^2 dt^2$ at $p=(0,t)$ is 
$$K_{g_1}(p)=\frac{- 1}{ m_s(0)^2} [\partial^2_{\rho}f(0,t) + \partial^2_{\rho} m_s(0)  m_s(0)^{-1} ].$$

Recall in Lemma \ref{lemma, fermiCoordinates}, the function $m_s(\rho) = 1-s \cdot\exp({1-\frac{1}{1-(\frac{\rho}{\varepsilon})^2}})  $ when  $ 0<|\rho| < \varepsilon $ and so $\partial^2_{\rho} m_s(0)>0$ . Also $0<m_s(0)=1-s<1$. Therefore,
$$\frac{K_{g_1}(p)}{K_{g_2}(p)}=\frac{\partial^2_{\rho}f(0,t) + \partial^2_{\rho} m_s(0) (1-s)^{-1} }{(1-s)^2 \partial^2_{\rho}f(0,t)}> \frac{1}{(1-s)^2}=L(g_1,g_2)>1.$$

Since $f_0=\id$ is an optimal Lipschitz map, this is also an example of $E(g_1,g_2)$ being a maximally stretched geodesic lamination while conditions of Corollary \ref{Cor, geodesicLamination} do not hold.
\end{proof}

\section{A simple analytic lemma}\label{Appendix simpleLemma}
Since we can't find a reference for the following lemma, we include a proof of it here.

\begin{lemma}\label{simpleLemma}
    Let $K$ be a compact topological space and $V$ an arbitrary metric space.
    Given a continuous function $F:K \times V \to \R$, then the function
    $G:V \to \R$ given by 
    $$
    G(p)= \max_{x \in K}F(x,p)
    $$
    is continuous as well.
\end{lemma}
\begin{proof}
Let $p_n$ be a sequence in $V$ converging to $p$.
We show first that
\begin{equation} \label{eqtn,LimitMax}
\lim_{n \to \infty} \max_{x \in K}|F(x,p_n) -F(x,p)| = 0.
\end{equation}
If not, there exists $\varepsilon >0 $ and a subsequence $p_{n_k}$ and a sequence $x_k \in K$
such that
$$
|F(x_k,p_{n_k}) -F(x_k,p)| \geq \varepsilon.
$$
By choosing a subsequence, we can assume that $x_k$ converges to $x_0 \in K$.
Then $(x_k,p_{n_k})$ converges to $(x_0, p)$. This leads to a contradiction with continuity of $F$.

Now assume
$$
\max_{x \in K}F(x,p) = G(p) = F(x_p,p)
$$
for some $x_p \in K$. Choose a sequence $x_n \in K$ converging to $x_p$.
Then $G(p_n) \ge F(x_n, p_n)$. Continuity of $F$ implies
$$
\varliminf_{n \to \infty}G(p_n) \ge \lim_{n \to \infty} F(x_n, p_n) =F(x_p, p) = G(p).
$$
On the other hand, if we let $y_n \in K$ be a sequence such that $F(y_n,p_n) =G(p_n)$. Using what we have shown in Equation \eqref{eqtn,LimitMax}, we obtain
$$
\lim_{n \to \infty}(F(y_n,p_n) -F(y_n,p)) =0.
$$
This yields
$$
\varlimsup_{n \to \infty}G(p_n)=\varlimsup_{n \to \infty} F(y_n,p_n) =\varlimsup_{n \to \infty} F(y_n,p) \le G(p).
$$
Hence, we obtain the continuity of G.
\end{proof} 






