\section{Some properties of the univariate Jacobi polynomials and the rank one Jacobi algebra \label{app:A}}
%
We define a family of polynomials, denoted by $J_n^{(a,b)}(x)$, on the interval $[0,1]$, via the transformation $$J_n^{(a,b)}(x) = P_n^{(a,b)}(1-2x),$$ where $P_n^{(a,b)}(x)$ denotes the usual Jacobi polynomial of degree $n$, orthogonal on $[-1,1]$; see \cite{koekoek2010hypergeometric} for standard definitions and properties.
In the following, we summarize some basic properties of the polynomials $J_n^{(a,b)}(x)$.

\medskip
\noindent \textit{Explicit expression}
\begin{align*}
  &  J_n^{(a,b)}(x) = \dfrac{(a+1)_n}{n!}\hg{2}{1}\argu{-n,n+a+b+1}{a+1}{x}.
\end{align*}
\noindent \textit{Orthogonality}
\begin{align}
&   \int_{0}^1x^{a} (1-x)^{b} J_n^{(a,b)}(x) J_{m}^{(a,b)}(x)dx
     = \frac{\Gamma(n+a+1)\Gamma(n+b+1)}{(2n +a+b+1)\,n!\, \Gamma(n+a+b+1) } \delta_{nm}, \quad a,b>-1.
\end{align}

\medskip

\noindent\textit{Differential equation}
\begin{align}\label{unide}
  &H^{(a,b)}[J_{n}^{(a,b)}(x)]=-n\,(n+a+b+1)J_{n}^{(a,b)}(x),
\end{align}
where
\begin{align}
H^{(a,b)} = x(1-x)\partial_x^2 + (a+1 - (a+b+2)x)\partial_x.
\end{align}

\medskip

\noindent \textit{Recurrence relation}
\begin{align}
(1-2x) &J_n^{(a,b)}(x)
=
\frac{2(n+1)(n+a+b+1)}{(2n+a+b+1)(2n+a+b+2)}J_{n+1}^{(a,b)}(x) \nonumber  \\
&-\frac{(a-b)(a+b)}{(2n+a+b)(2n+a+b+2)}J_{n}^{(a,b)}(x)+\frac{2(n+a)(n+b)}{(2n+a+b)(2n+a+b+1)} J_{n-1}^{(a,b)}(x).
\label{RR:univariate}
\end{align}%

\medskip
\noindent \textit{Shift relation}
\begin{align}
&   \partial_x J_n^{(a,b)}(x) = -(n+a+b+1) J_{n-1}^{(a+1,b+1)}(x), \label{uniJacobi:shift1}\\
&    \left(x(1-x) \partial_x  + a-(a+b)x\right)J_n^{(a,b)}(x) = (n+1) J_{n+1}^{(a-1,b-1)}(x).
    \label{uniJacobi:shift2}
\end{align}

\medskip
\noindent \textit{Rank one Jacobi algebra} 

\noindent Take
\begin{equation}
   \ K_1=H^{(a,b)}, \qquad K_2=x,
\end{equation}
where $H^{(a,b)}$ is given by \eqref{unide} and $K_2$ is the operator multiplication by $x$. Define a third operator $K_3=[K_1,K_2]$. It is readily seen that
\begin{equation}
  K_3=2x (1-x)\partial_x +(a+1-(a+b+2)x).
\end{equation}
By direct computation one then verifies that $K_1$ and $K_2$ verify the commutation relations given in \eqref{rank1} that define the Jacobi algebra of rank one with $\alpha =a$ and $\beta =b$. We may here remark that this algebra is isomorphic to the rank one Hahn algebra (see for example \cite{frappat2019higgs}).



\medskip

\noindent \textit{Structure relation}
%
\begin{align}
    K_3 &J_n^{(a,b)}(x) = \dfrac{(n+1)(n+a+b+1)}{2n+a+b+1} J_{n+1}^{(a,b)}(x) -\dfrac{(n+a)(n+b)}{2n+a+b+1} J_{n-1}^{(a,b)}(x).
\end{align}


\noindent \textit{Contiguity relations of the one variable Jacobi polynomials}

\noindent We record the following contiguity relations \cite{bateman1953higher} obtained from Christoffel and Geronimus transformations \cite{chihara2011introduction} :
\begin{align}
    x J_n^{(a,b)}(x) &=\dfrac{n+a}{2n+a+b+1} J_n^{(a-1,b)}(x)-\dfrac{n+1}{2n+a+b+1} J_{n+1}^{(a-1,b)}(x),  \label{uniJacobi:CTa} \\
    J_n^{(a,b)}(x) &=\dfrac{n+a+b+1}{2n+a+b+1}J_n^{(a+1,b)}(x)-\dfrac{n+b}{2n+a+b+1}J_{n-1}^{(a+1,b)}(x), \label{uniJacobi:GTa}\\
    (1-x) J_n^{(a,b)}(x) &=\dfrac{n+1}{2n+a+b+1} J_{n+1}^{(a,b-1)}(x)+\dfrac{n+b}{2n+a+b+1} J_n^{(a,b-1)}(x),   \label{uniJacobi:CTb} \\
    J_n^{(a,b)}(x) &=\dfrac{n+a+b+1}{2n+a+b+1}J_n^{(a,b+1)}(x)+\dfrac{n+a}{2n+a+b+1}J_{n-1}^{(a,b+1)}(x). \label{uniJacobi:GTb}
\end{align}

\section{Differential properties of the two variable Jacobi polynomials \label{app:B}}
We introduce six first-order differential operators $s_1, s_2, s_3, s_1^*, s_2^*, s_3^*$ defined by
\begin{align} \label{diffop}
  &s_1=(x+y-1)\partial_y + cI, \quad
  s_2=x\partial_x + aI, \quad   
  s_3=-y\left(\partial_x-\partial_y \right)+ bI, \nonumber\\
  &s_1^*= -y \partial_y -b I, \quad
  s_2^*=(1-x-y)\partial_x-cI, \quad
  s_3^*=x(\partial_y - \partial_x) -a I,   
\end{align}
where each pair $(s_i, s_i^{*})$ for $i=1,2,3$, is related via a transformation involving parameter-dependent functions: 
\begin{align}
g_1^{(b,c)}= y^b (1-x-y)^{-c},\quad   g_2^{(a,c)}=x^{-a}(1-x-y)^c, \quad   g_3^{(a,b)}=x^a y^{-b},
\end{align}
as
\begin{align}
s_1^*=g_1^{(1-b,1-c)}\circ s_1 \circ g_1^{(b,c)}, \quad
s_2^*=g_2^{(1-a,1-c)}\circ s_2 \circ g_2^{(a,c)}, \quad
s_3^*=g_3^{(1-a,1-b)}\circ s_3 \circ g_3^{(a,b)}.    
\end{align}
The operators $L_1^{(b,c)}, L_2^{(a,c)}, L_3^{(a,b)} $ and $L$ can be expressed in terms of these six operators as follows:
\begin{align}
L_1^{(b,c)}&=(s_1^* - 1)s_1 +c(b+1)=(s_1+1) s_1^* + b(c+1), \\
L_2^{(a,c)}&=(s_2^* - 1)s_2 +a(c+1)=(s_2+1) s_2^* + c(a+1), \\
L_3^{(a,b)}&=(s_3^* - 1)s_3 +b(a+1)=(s_3+1) s_3^* + a(b+1), \label{Lzs}\\
    L&=s_1^* s_1+s_2^* s_2+s_3^* s_3 -s_1-s_2-s_3 +a+b+c+ab+ac+bc\nonumber\\
     &=s_1 s_1^*+s_2 s_2^*+s_3 s_3^* +s_1^*+s_2^*+s_3^*+a+b+c+ab+ac+bc. \label{L:s1s2s3}
\end{align}
Moreover, the actions of $s_1, s_2, s_3, s_1^*, s_2^*, s_3^*$ on the two-variable Jacobi polynomials can be readily computed and are given by:
\begin{align}
& s_1[J_{n,k}^{(a,b,c)}]=(c+k)J_{n,k}^{(a,b+1,c-1)},\label{acts2}\\
& s_1^*[J_{n,k}^{(a,b,c)}]=-(b+k)J_{n,k}^{(a,b-1,c+1)},\label{acts2*}\\
& s_2[J_{n,k}^{(a,b,c)}]=\dfrac{(n-k+1)(b+k)}{b+c+2k+1}J_{n,k-1}^{(a-1,b,c+1)}
  + \dfrac{(a+n-k)(b+c+k+1)}{b+c+2k+1}J_{n,k}^{(a-1,b,c+1)},\label{acts1}\\
& s_2^*[J_{n,k}^{(a,b,c)}]=-\dfrac{(k+1)(a+b+c+n+k+2)}{b+c+2k+1}J_{n,k+1}^{(a+1,b,c-1)}
  - \dfrac{(c+k)(b+c+k+n+1)}{b+c+2k+1}J_{n,k}^{(a+1,b,c-1)},\label{acts1*}\\
& s_3[J_{n,k}^{(a,b,c)}]= - \dfrac{(k+1)(a+b+c+n+k+2)}{b+c+2k+1}J_{n,k+1}^{(a+1,b-1,c)}
  + \dfrac{(b+k)(b+c+k+n+1)}{b+c+2k+1}J_{n,k}^{(a+1,b-1,c)},\label{acts3}\\
& s_3^*[J_{n,k}^{(a,b,c)}]=\dfrac{(n-k+1)(c+k)}{b+c+2k+1}J_{n,k-1}^{(a-1,b+1,c)}
  - \dfrac{(a+n-k)(b+c+k+1)}{b+c+2k+1}J_{n,k}^{(a-1,b+1,c)} \label{acts3*}.
\end{align}
%
The above relations can be proved using the contiguity relations \eqref{uniJacobi:CTa}–\eqref{uniJacobi:GTb} of the one variable Jacobi polynomials, together with additional identities: 
\begin{align}
    (x-1)\partial_x J_n^{(a,b)}(x) &= (n+a+b+1) \left(J_n^{(a+1,b)}(x)  - J_n^{(a,b)}(x)\right), \label{uniJacobi:(x-1)_diff}\\
    x \partial_x J_n^{(a,b)}(x) &= (n+a+b+1) \left(J_n^{(a,b+1)}(x)-J_n^{(a,b)}(x)\right). \label{uniJacobi:x_diff}
\end{align}
We briefly outline the proof of the third relation, namely \eqref{acts1}, as a representative case:
%
\begin{align}
   s_2[J_{n,k}^{(a,b,c)}]=&(x \partial_x +a I)\left(J_{n-k}^{(a,b+c+2k+1)}\bigl( x\bigr) \cdot (1-x)^k\right) \cdot J_k^{(b,c)}\left(\frac{y}{1-x}\right)    \nonumber \\
   &+J_{n-k}^{(a,b+c+2k+1)}\bigl( x\bigr) \cdot (1-x)^k \cdot x \partial_x \left(J_k^{(b,c)}\left(\frac{y}{1-x}\right) \right) \nonumber \\
   =& B_1^{(1)}(x)\, J_k^{(b,c)}\left(\frac{y}{1-x}\right)+B_2^{(1)}(x)\, J_k^{(b,c+1)}\left(\frac{y}{1-x}\right)\nonumber\\
   =& B_1^{(2)}(x)\, J_{k-1}^{(b,c+1)}\left(\frac{y}{1-x}\right)+B_2^{(2)}(x)\, J_k^{(b,c+1)}\left(\frac{y}{1-x}\right)
\end{align}
where we first rewrite the expression using \eqref{uniJacobi:x_diff}, and then express the coefficients of $J_k^{(b,c)}$ and $J_k^{(b,c+1)}$ as $B_1^{(1)}$ and $B_2^{(1)}$, respectively, to obtain the third line. The fourth line is obtained by reorganizing the terms using the contiguity relation \eqref{uniJacobi:GTb}, and expressing the coefficients of $J_{k-1}^{(b,c+1)}$ and $J_k^{(b,c+1)}$ as $B_1^{(2)}$ and $B_2^{(2)}$, respectively.
Furthermore, using the relations 
%
\begin{align}
     n J_n^{(a,b-1)}(x) &= (n+a+b+1)(1-x) J_{n-1}^{(a+1,b+1)}(x) - (n(1-x)+b) J_{n-1}^{(a+1,b)}(x),\\
    (n+a+1)J_n^{(a,b+1)}(x) &= (n+a+b+2)J_n^{(a+1,b+1)}(x) - (n+b+1) J_n^{(a+1,b)}(x), 
\end{align}
for $B_1^{(2)}$ and $B_2^{(2)}$, which follow directly from the four contiguity relations \eqref{uniJacobi:CTa}–\eqref{uniJacobi:GTb}, we finally obtain the right-hand side of \eqref{acts1}.


