\section{Conventions and background} 
\label{sect:prelim}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Representations of the symmetric groups and Schur functors}

We work over the rational numbers, $\rat$. The category of finite-dimensional $\rat$-vector spaces is denoted by $\fmodq$;  all undecorated tensor products $\otimes$ are understood to be taken over $\rat$. For $n \in \nat$, the symmetric group on $n$ letters is denoted $\sym_n$.
The category of $\rat \sym_n$-modules (or $\sym_n$-modules) is semi-simple. The simple $\sym_n$-modules are indexed by the partitions $\lambda$ of $n$, with $S_\lambda$ denoting the associated simple module. The indexing convention is chosen so that $S_{(n)}$ is the trivial representation $\triv_n$ and $S_{(1^n)}$ the sign representation $\sgn_n$. For groups $H \subset G$, the notation $\downarrow^G_H$ denotes restriction from $G$-modules to $H$-modules and $\uparrow_H^G$ denotes induction.

The Schur functor construction establishes the correspondence between $\sym_n$-modules and functors from $\fmodq$ to $\rat$-vector spaces. For $M$ a $\sym_n$-module, the associated Schur functor is 
\[
V \mapsto V^{\otimes n}\otimes_{\sym_n} M,
\]
for $V \in \fmodq$, where $\sym_n$ acts by place permutations on $V^{\otimes n}$. Writing $T^n$ for the $n$th tensor product functor $V \mapsto V^{\otimes n}$ equipped with the place permutation action of $\sym_n$ (on the right), the Schur functor can be written as 
\[
T^n \otimes_{\sym_n} M.
\]
This is a polynomial functor that is homogeneous of degree $n$. (See \cite[Appendix I.A]{MR3443860} for polynomial functors in characteristic zero.) The Schur functor construction establishes an equivalence of categories between $ \sym_n$-modules and homogeneous polynomial functors of degree $n$; given such a polynomial functor $F$, the associated $\sym_n$-representation is given by 
the natural transformations
\[
\mathrm{Nat} ( T^n, F),
\]
where the $\sym_n$-action is given by the action on $T^n$. This can also be interpreted as a {\em cross-effect} functor, corresponding to passage to multilinear terms.

\begin{nota}
\label{nota:schur_functor}
For a partition $\lambda \vdash n$, the associated Schur functor is denoted $\schur_{\lambda}$, so that 
$\schur_\lambda (V) = V^{\otimes n}\otimes _{\sym_n} S_\lambda$.  
\end{nota}

\begin{exam}
For $\lambda = (n)$, the Schur functor $\schur_{(n)}$ identifies as the $n$th symmetric power functor $V \mapsto S^n (V) = (V^{\otimes n}) / \sym_n$. Over $\rat$, this is isomorphic to the $n$th divided power functor $V \mapsto \Gamma^n (V)= (V^{\otimes n})^{\sym_n}$.  In particular, there is a canonical surjection $V^{\otimes n} \twoheadrightarrow S^n (V)$ and a canonical inclusion $\Gamma^n (V) \hookrightarrow V^{\otimes n}$. 
 For $\lambda = (1^n)$, the Schur functor $\schur_{(1^n)}$ identifies as the $n$th exterior power functor $V \mapsto \Lambda^n (V)$. 

The $\nat$-graded functors $S^*$, $\Gamma^*$ and $\Lambda^*$ are all exponential functors (paying attention to signs in the case of $\Lambda^*$). In particular, for $a, b \in \nat$ and  $n = a+b$, there are natural  coproducts 
$\Lambda^n  \rightarrow \Lambda ^a  \otimes \Lambda^b $ and $\Gamma^n  \rightarrow \Gamma ^a  \otimes \Gamma^b$, and 
  natural products
$\Lambda ^a  \otimes \Lambda^b  \rightarrow \Lambda^n $ and 
$S^a  \otimes S^b  \rightarrow S^n$. 
\end{exam}

We record the following basic fact which plays the r\^ole of Schur's lemma:

\begin{prop}
\label{prop:nat_schur}
For partitions $\lambda \vdash m$, $\mu \vdash n$,  
\begin{enumerate}
\item 
$\schur_\lambda$ is a simple functor from $\fmodq$ to $\rat$-vector spaces; 
\item 
$\mathrm{Nat} (\schur_\lambda, \schur_\mu ) \cong
\left\{ 
\begin{array}{ll}
 \rat & \lambda = \mu \\
 0 & \mbox{otherwise.}
\end{array}
\right.
$
\end{enumerate}
\end{prop}

For a partition $\lambda$, $l(\lambda)$ denotes its length, i.e., the number of non-zero terms in the partition. One has the following standard result on the connectivity of the simple Schur functors:

\begin{lem}
\label{lem:conn_schur}
For a partition $\lambda$,  $\schur_\lambda (V)$ is zero if and only if $\dim V < l(\lambda)$.
\end{lem}

We will also be working with functors from $\fmodq$ to $\rat$-vector spaces that are equipped with a $\sym_r$-action (for some fixed $r \in \nat$) and $\sym_r$-equivariant natural transformations. A basic example of such a functor is given by forming the tensor product of a homogeneous polynomial functor $F$ of degree $n \in \nat$ with a $\sym_r$-module $M$. This will be denoted by 
$
F\boxtimes M$.




We also work with  analytic functors (in the sense of \cite[Chapitre 4]{MR927763}). By definition, these are direct sums of homogeneous polynomial functors (not necessarily of the same degree). 




\begin{nota}
\label{nota:components_analytic}
For $V \mapsto F(V)$ an analytic functor on $\fmodq$ and $n \in \nat$, write $F^{[n]}$ for the homogeneous component of degree $n$, so that one has the natural isomorphism
\[
 F(V) \cong \bigoplus_{n \in \nat} F^{[n]} (V).
\]
Thus, written without the variable $V$, $F \cong \bigoplus_{n \in \nat} F^{[n]}$. (We will also write $F(V)^{[n]}$ for $ F^{[n]} (V)$.) 
\end{nota}

\begin{exam}
\label{exam:lie_small_degree}
Consider the free Lie algebra functor $V \mapsto \lie (V)$, for $V \in \fmodq$. The underlying functor to $\rat$-vector spaces is analytic and one has the natural splitting
\[
\lie (V) \cong \bigoplus_{n \in \nat} \lie^{[n]} (V).
\]
Here $ \lie^{[n]} (V)$ identifies as  the subspace of $\lie (V)$  generated (as a vector space) by iterated brackets of length exactly $n$. 
In particular, $\lie^{[0]} (V) =0$, $\lie^{[1]}(V) = V$, $\lie ^{[2]} (V) \cong \Lambda^2 (V)$ and $\lie^{[3]} (V) \cong \schur_{(2,1)}(V)$. 
\end{exam}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{A form of the  de Rham differential}
\label{subsect:dR}

For later use, we introduce  $\diff$, a form of the de Rham differential written using the divided power functors. For $a, b \in \nat$, with $b>0$, $\diff$ is the natural transformation 
\begin{eqnarray}
\label{eqn:diff}
\diff \colon
\Lambda^a \otimes \Gamma^b 
\rightarrow 
\Lambda^{a+1} \otimes \Gamma^{b-1} 
\end{eqnarray}
that is given by the composite 
\[
\Lambda^a \otimes \Gamma^b  
\rightarrow 
\Lambda^a  \otimes \Gamma^1 \otimes \Gamma^{b-1}  
\cong 
\Lambda^a  \otimes \Lambda^1 \otimes \Gamma^{b-1}  
\rightarrow 
\Lambda^{a+1} \otimes \Gamma^{b-1} 
\]
in which the first map is the coproduct of $\Gamma^*$ (which corresponds to the natural inclusion $(V^{\otimes b})^{\sym_b} \subset V \otimes (V^{\otimes b-1})^{\sym_{b-1}}$) and the second is the product of $\Lambda^*$. 


One has the following characterization of $\diff$:

\begin{lem}
\label{lem:diff_characterization}
For $a<b \in \nat$, $\diff$ is the unique map which fits into the commutative diagram of natural transformations
\begin{eqnarray}
\label{eqn:characterize_diff}
\xymatrix{
\Lambda^a \otimes \Gamma^b 
\ar[r]^\diff
\ar@{^(->}[d]
&
\Lambda^{a+1}  \otimes \Gamma^{b-1} 
\ar@{^(->}[d]
\\
\Lambda^a  \otimes T^{b}
\ar[r]
&
\Lambda^{a+1} \otimes T^{ b-1},
}
\end{eqnarray}  
where the bottom map is induced by the product $\mu : \Lambda^a  \otimes \Lambda^1 \rightarrow \Lambda^{a+1} $  and the vertical maps correspond are induced by the canonical inclusion $\Gamma^* \subset T^*$.
\end{lem}

As usual, one can identify the kernel and cokernel of $\diff$ using the Pieri rule:

\begin{lem}
\label{lem:ker_coker_diff}
For positive integers $a,b$, the kernel and cokernel of $\diff$ identify respectively as 
\begin{eqnarray*}
\ker (\diff) &\cong & \schur_{(b+1,1^{a-1})}
\\
\mathrm{coker} (\diff) &\cong & \schur_{(b-1,1^{a+1})},
\end{eqnarray*} 
where, if $b=1$, the cokernel is understood to be zero.
\end{lem}




\begin{exam}
\label{exam:schur_embedding}
For $r \geq 2$,  $\schur_{(r, 1^2)}$ identifies as the kernel of 
$
\diff \colon  
\Lambda^3  \otimes \Gamma^{r-1} 
\rightarrow 
\Lambda^{4}  \otimes \Gamma^{r-2}.  
$
\end{exam}

%\input{adj}
\section{The adjoint action and a reduction}
\label{sect:adj}

The main purpose of this section is to reduce the calculation of 
 $H_1 (\lie (V); \lie(V)^{\otimes r})^{[r+2]}$ (for $r\geq 2$)  to that of the kernel of the morphism $\dbar_r$ introduced in Notation \ref{nota:dbar}; this is achieved in Proposition \ref{prop:H_1_by_dbar}.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The adjoint action}

Consider $\lie (V)$, the free Lie algebra on $V\in \ob \fmodq$. Then $\lie (V)$ can be considered as a left $\lie (V)$-module for the adjoint action, and this structure is natural with respect to $V$. Hence, for each $r \in \nat$, $\lie (V)^{\otimes r}$ is a left $\lie (V)$-module (using the tensor product of $\lie (V)$-modules). For $r=0$ this gives the trivial module $\rat$ and, for  $r=1$,  the  adjoint representation. The symmetric group $\sym_r$ acts by place permutations of the tensor factors of $\lie (V)^{\otimes r}$, respecting the $\lie (V)$-module structure. All this structure is natural with respect to $V$. 

It follows that one can consider the Lie algebra homology:
$ 
H_* (\lie(V); \lie (V) ^{\otimes r}) 
$ 
and this takes values in $\sym_r$-modules,  naturally with respect to $V$. This is given as the homology of the complex (placed in homological degrees $1$ and $0$)
\[
V \otimes \lie (V) ^{\otimes r} 
\stackrel{\adbar_r}{\longrightarrow} 
\lie (V)^{\otimes r}
\]
given by restricting the adjoint action 
 $\mathrm{ad}_r : \lie (V) \otimes \lie (V) ^{\otimes r} 
\rightarrow 
\lie (V)^{\otimes r}$  to $V \subset \lie(V)$ on the first tensor factor. Thus one has 
\[
H_* (\lie (V); \lie(V)^{\otimes r}) \cong 
\left\{ 
\begin{array}{ll}
\coker (\adbar_r) & r=0 \\
\ker (\adbar _r) & r=1 \\
0 & \mbox{otherwise}.
\end{array}
\right.
\]

Since $\adbar_r$ is a natural transformation between  analytic functors (with respect to $V$), both $\ker (\adbar_r)$ and $\coker (\adbar_r)$ are analytic functors. 


\begin{exam}
In the case $r=0$, the complex reduces to $
V \stackrel{0}{\rightarrow} \rat,  
$ 
giving the homology $H_* (\lie(V); \rat)$ with trivial coefficients. 

The case $r=1$ is more interesting; $\adbar_1$ fits into an exact complex:
\[
0
\rightarrow 
\cyclie (V) 
\rightarrow 
V \otimes \lie (V)
\stackrel{\adbar_1}{\rightarrow} 
\lie (V) 
\rightarrow 
V 
\rightarrow 
0.
\]
Here, $\cyclie(V)$ is the Schur functor that is associated to the cyclic Lie operad. (Cf. \cite{MR1943338}, where a stronger result is established, working over $\mathbb{Z}$).

To explain this exact sequence, recall that, if $\liemod(n)$ denotes the $n$th Lie representation (corresponding to the functor $V \mapsto \lie(V)^{[n]}$ by the Schur correspondence) and $\mathrm{CycLie}(n)$ the analogous module corresponding to $V \mapsto \cyclie(V)^{[n]}$, then these are related by 
\[
\liemod(n) = \mathrm{CycLie}(n+1)\downarrow^{\sym_{n+1}}_{\sym_n}
\]
(this identification explains our conventions for indexing cyclic operads). The collection of morphisms $\mathrm{CycLie}(n+1) \rightarrow \liemod(n)\uparrow^{\sym_{n+1}}_{\sym_n}$ obtained by adjunction induce the natural transformation $\cyclie (V) \rightarrow V \otimes \lie (V)$  above and it is straightforward to check that one obtains a sequence as given.
 Exactness can be checked at the level of  representations of the symmetric groups by using restriction, exploiting the fact that $\liemod(n+1) \downarrow ^{\sym_{n+1}}_{\sym_n} \cong \rat \sym_n$.
\end{exam}


Here we are interested in $H_1 (\lie (V); \lie(V)^{\otimes r})^{[n]}$ for small $n$, considered as a functor of $V \in \ob \fmodq$ equipped with a $\sym_r$-action. Using the notation introduced in Section \ref{sect:prelim}, one has the basic result:

\begin{prop}
\label{prop:small_n}
For $r, n \in \nat$, there is a $\sym_r$-equivariant natural isomorphism:
\[
H_1 (\lie (V); \lie(V)^{\otimes r})^{[n]} = \left\{ 
\begin{array}{ll}
0 & n \leq r \\
\Gamma^{r+1} (V) \boxtimes \triv_r & n = r+1.
\end{array}
\right.
\]
\end{prop}

\begin{proof}
The case $n \leq r$ is clear, since $(V \otimes \lie(V) ^{\otimes r})^{[n]}$ is zero for $n \leq r$. 
 The case $n=r+1$ is shown as follows. The case $r=0$ is immediate.  For $r\geq 1$, one uses the
 the fact that (for $r \geq 1$) $\adbar_r^{[r+1]}$ identifies as an explicit map
\begin{eqnarray}
\label{eqn:adbar_1}
V \otimes V^{\otimes r} \rightarrow \bigoplus_{i=0}^{r-1} V^{\otimes i} \otimes \Lambda^2 (V) \otimes  V^{\otimes r-1-i}.
\end{eqnarray}
The canonical inclusion $\Gamma^{r+1}(V) \hookrightarrow V \otimes V^{\otimes r}$ clearly maps to the kernel of this; moreover, the image is invariant under the action of $\sym_r$, by definition of the divided power functor. Hence, to prove the result, it suffices to show that, neglecting the $\sym_r$-action, the kernel is $\Gamma^{r+1}(V) $.

For $r=1$, the map (\ref{eqn:adbar_1}) gives the natural short exact sequence
\[
0
\rightarrow \Gamma^2 (V) \rightarrow V^{\otimes 2} \stackrel{\adbar_1}{\rightarrow}
\Lambda^2 (V) 
\rightarrow 
0,
\]
identifying the kernel as required. The cases $r>1$ then follow by an inductive argument (cf. the proof of Lemma \ref{lem:intersect_lambda}).
\end{proof}

The  case $n=r+2$ stated below is the main result of this paper (Theorem \ref{THM} of the Introduction). 

\begin{thm}
\label{thm:main}
For $r \in \nat$, there is a $\sym_r$-equivariant natural isomorphism:
\[
H_1 (\lie (V); \lie(V)^{\otimes r})^{[r+2]}
\cong 
\left\{ 
\begin{array}{ll}
0 & r=0\\
\Lambda^3 (V) \boxtimes \sgn_1 & r=1 \\
\Lambda^{r+2} (V) \boxtimes \sgn_r \   \oplus \  \schur_{(r, 1^2)} (V) \boxtimes \triv_r
& r>1.
\end{array}
\right.
\]
\end{thm}


\begin{exam}
\label{exam:r=1}
The case $r=1$ of Theorem \ref{thm:main} is elementary. The requisite complex is 
\[
V \otimes \Lambda^2 (V) \stackrel{\adbar_1^{[3]}}{\twoheadrightarrow} \schur_{(2,1)}(V),
\]
using the identifications $\lie(V)^{[2]} = \Lambda^2 (V)$ and $\lie(V)^{[3]} = \schur_{(2,1)}(V)$; the map is surjective since $\lie (V)$ is generated as a Lie algebra by $V$.
 By the Pieri rule, $V \otimes \Lambda^2 (V) \cong \Lambda^3(V) \oplus  \schur_{(2,1)}(V)$, giving the identification of the kernel.
\end{exam}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Reduction of the problem}
\label{subsect:reduce}

To calculate $H_1 (\lie (V); \lie(V)^{\otimes r})^{[r+2]}$, we need to calculate the kernel of 
\[ 
\adbar_r ^{[r+2]} \ : \ 
\Big( V \otimes \lie (V)^{\otimes r} \Big)^{[r+2]} 
\rightarrow 
\Big (\lie(V)^{\otimes r} \Big) ^{[r+2]}.
\]


This can be described explicitly by using the identifications in Example \ref{exam:lie_small_degree}.

\begin{lem}
For $r \geq 1$, there are natural $\sym_r$-equivariant isomorphisms
\begin{eqnarray*}
\Big( V \otimes \lie (V)^{\otimes r} \Big)^{[r+2]} 
&\cong & 
V \otimes (\Lambda^2 (V) \otimes V^{\otimes r-1} ) \uparrow_{\sym_{r-1}}^{\sym_r}
\\
\Big (\lie(V)^{\otimes r} \Big) ^{[r+2]}
&\cong& 
 (\schur_{(2,1)} (V) \otimes V^{\otimes r-1} ) \uparrow_{\sym_{r-1}}^{\sym_r}
\ \quad \oplus \ \quad (\Lambda^2 (V) \otimes \Lambda^2 (V) \otimes V^{\otimes r-2}) \uparrow_{\sym_2 \times \sym_{r-2}}^{\sym_r},
 \end{eqnarray*}
 for the obvious actions of the symmetric groups by place permutations (if $r =1$, the final term is understood to be zero).
\end{lem}



The  adjoint action $\adbar_1$ gives the canonical projections
\begin{eqnarray*}
(V\otimes \lie (V))^{[2]} \cong V \otimes V &\twoheadrightarrow &\lie (V)^{[2]} = \Lambda^2 (V) \\ 
(V \otimes \lie (V))^{[3]} \cong V \otimes \Lambda^2 (V) &\twoheadrightarrow &\lie (V)^{[3]} = \schur_{(2,1)} (V), 
\end{eqnarray*} 
with kernels $\Gamma^2 (V)$ and $\Lambda^3 (V)$ respectively. These extend to define the components $\delta'_r$ and $\delta''_r$ of $\adbar_r^{[r+2]}$:
\begin{eqnarray*}
\delta'_r &:&  V \otimes (\Lambda^2  (V) \otimes V^{\otimes r-1})\uparrow _{\sym_{r-1} }^{\sym_r} 
\rightarrow 
(\schur_{(2,1)}  (V) \otimes V^{\otimes r-1})\uparrow _{\sym_{r-1} }^{\sym_r} 
\\
\delta''_r &:& V \otimes (\Lambda^2  (V) \otimes V^{\otimes r-1})\uparrow _{\sym_{r-1} }^{\sym_r} 
\rightarrow (\Lambda^2  (V) \otimes \Lambda^2 (V) \otimes  V^{\otimes r-2})\uparrow _{\sym_2 \times \sym_{r-2} }^{\sym_r}.
\end{eqnarray*}
Using the $\sym_r$-equivariance, these maps can be described by specifying one of their components, as follows.

The morphism underlying $\delta'_r$ identifies  as 
\[
\bigoplus_{i=1}^{r} 
V \otimes (V^{\otimes i-1} \otimes \Lambda^2  (V) \otimes V^{\otimes r-i})
\rightarrow 
\bigoplus_{j=1}^{r} 
(V^{\otimes j-1} \otimes \schur_{(2,1)}  (V) \otimes V^{\otimes r-j}).
\]
The component with $i=j=1$ is given by 
$$V \otimes \Lambda^2  (V) \otimes V^{\otimes r-1}
\rightarrow 
\schur_{(2,1)}  (V) \otimes V^{\otimes r-1}$$ 
obtained by applying $\adbar_1$ to the first two tensor factors of the domain. 

Likewise, the morphism underlying  $\delta''_r$ identifies as 
\[
\bigoplus_{i=1}^{r} 
V \otimes (V^{\otimes i-1} \otimes \Lambda^2  (V) \otimes V^{\otimes r-i})
\rightarrow 
\bigoplus_{1 \leq j < k \leq r} 
(V^{\otimes j-1} \otimes \Lambda^2 (V) \otimes V^{\otimes k-j-1} \otimes \Lambda^2 (V) \otimes V^{\otimes r-k}).
\]
The component with $i=j=1$ and $k=2$ is 
 $$
 V \otimes (\Lambda^2  (V) \otimes V^{\otimes r-1})
\rightarrow
\Lambda^2  (V) \otimes \Lambda^2 (V) \otimes  V^{\otimes r-2}
 $$ 
 obtained by applying $\adbar_1$ to the first and third tensor factors of the domain.


\begin{lem}
\label{lem:ker_delta'}
The kernel of $\delta'_r$ is  $\sym_r$-equivariantly naturally isomorphic to
$
(\Lambda^3  (V) \otimes V^{\otimes r-1})\uparrow _{\sym_{r-1} }^{\sym_r}, 
$
which is considered as a $\sym_r$-submodule of $V \otimes (\Lambda^2 (V) \otimes V^{\otimes r-1})\uparrow _{\sym_{r-1} }^{\sym_r}$ via the inclusion induced up from the $\sym_{r-1}$-equivariant map  
\[
\Lambda^3  (V) \otimes V^{\otimes r-1} \hookrightarrow V \otimes \Lambda^2 V \otimes V^{\otimes r-1}
\] 
given by applying the inclusion $\Lambda^3 (V) 
\rightarrow 
V \otimes \Lambda^2 (V) $ to the first factor.
\end{lem}

\begin{proof}
This generalizes the case $r=1$ given in Example \ref{exam:r=1}. 
\end{proof}

\begin{nota}
\label{nota:dbar}
Write $\dbar_r$ for the restriction of $\delta''_r$ to the kernel of $\delta'_r$:
\[
\dbar_r \ : \ 
(\Lambda^3   \otimes T^{ r-1})\uparrow _{\sym_{r-1} }^{\sym_r}
 \rightarrow 
(\Lambda^2   \otimes \Lambda^2  \otimes  T^{ r-2})\uparrow _{\sym_2 \times \sym_{r-2} }^{\sym_r}.
\] 
\end{nota}

The underlying functors of the domain and codomain of $\dbar_r$ identify as follows:


\begin{lem}
\label{lem:domain_codomain_dbar}
There are isomorphisms of functors 
\begin{eqnarray*}
(\Lambda^3  \otimes T^{r-1})\uparrow _{\sym_{r-1} }^{\sym_r}
&\cong &
\bigoplus_{i=1}^r 
T^{i-1} \otimes \Lambda^3 \otimes T^{r-i}
\\
(\Lambda^2   \otimes \Lambda^2 \otimes  T ^{ r-2})\uparrow _{\sym_2 \times \sym_{r-2} }^{\sym_r}
& \cong &
\bigoplus 
_{1 \leq i< j \leq r} 
T^{i-1} \otimes \Lambda^2 \otimes T^{j-i-1} \otimes \Lambda^2 \otimes T^{r-j}.
\end{eqnarray*}
Thus, $\dbar_r$ identifies as a natural transformation
\[
\bigoplus_{i=1}^r 
T^{i-1} \otimes \Lambda^3 \otimes T^{r-i}
\rightarrow 
\bigoplus 
_{1 \leq i< j \leq r} 
T^{i-1} \otimes \Lambda^2 \otimes T^{j-i-1} \otimes \Lambda^2 \otimes T^{r-j}.
\]
\end{lem}



Putting the above together provides the following reduction to the study of $\ker \dbar_r$.

\begin{prop}
\label{prop:H_1_by_dbar}
For $r \geq 2$, $H_1 (\lie (V); \lie(V)^{\otimes r})^{[r+2]}$ is isomorphic to $\ker \dbar_r$.
\end{prop}




