 \section{The case $r=3$}
 \label{sect:case_r3}


A key step in proving Theorem \ref{THM} is the case $r=3$:


\begin{thm}
\label{thm:case_r=3}
There is a $\sym_3$-equivariant natural isomorphism 
\[
\ker \dbar_3
\cong 
\Lambda^{5} \boxtimes \sgn_3\   \oplus \  \schur_{(3, 1^2)} \boxtimes \triv_3.
\]
\end{thm}

The proof uses Proposition \ref{prop:X_i_ker_dbar} for the case $r=3$. The relevant morphisms (see Notation \ref{nota:alpha_ij}) fit into  the (non-commutative) diagram:
\[
\xymatrix{
& 
\Lambda^1 \otimes \Lambda^1 \otimes \Lambda^3 
\ar[ldd]_{\alpha_{1;3}^{-1}} 
\\
\\
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1 
\ar[rr]
_{\alpha_{1;2}}
&&
\Lambda^1 \otimes \Lambda^3 \otimes \Lambda^1. 
\ar[uul]_{\alpha_{2;3}} 
}
\]  


The cocycle condition arising from Proposition \ref{prop:X_i_ker_dbar} can be restated as 


\begin{prop}
\label{prop:cocycle_r=3}
The kernel of $\dbar_3$ is isomorphic to the equalizer of 
\[
\xymatrix{
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1 
\ar@<.5ex>[rr]^\id 
\ar@<-.5ex>[rr]_{- (\alpha_{1;3}^{-1} \circ \alpha_{2;3} \circ \alpha_{1;2})}
&
\quad 
&
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1. 
}
\]
\end{prop}





The composite $\alpha_{1;3}^{-1} \circ \alpha_{2;3} \circ \alpha_{1;2}$ is an automorphism of $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1 $.  
This will be analysed using:


\begin{nota}
\label{nota:beta}
Denote by $\beta$ the automorphism of $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1$ given by the composite
\[
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1
\stackrel{\tau \circ \alpha \otimes \id}{\longrightarrow}
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1
\stackrel{\id \otimes \tau} {\longrightarrow }
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1.
\]
\end{nota}

\begin{rem}
\label{rem:beta}
The morphism $\beta$ also identifies as the composite of $\alpha \otimes \id : \Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1 \rightarrow \Lambda^1 \otimes \Lambda^3 \otimes \Lambda^1$ with the cyclic place permutation $\Lambda^1 \otimes \Lambda^3 \otimes \Lambda^1 \stackrel{\mathrm{cyclic}}{\rightarrow } \Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1 $ (this corresponds to $\Lambda^1 \otimes F\rightarrow F \otimes \Lambda^1$, where $F:=\Lambda^3 \otimes \Lambda^1$.)
\end{rem}



\begin{lem}
\label{lem:alpha_comp_versus beta}
The composite $\alpha_{1;3}^{-1}\circ \alpha_{2;3} \circ \alpha_{1;2}$ is equal to the automorphism
 $\beta^{\circ 3}$ of $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1$.
\end{lem}

\begin{proof}
This is a direct verification, based on the construction of the morphisms $\alpha_{1;3}$,   $\alpha_{2;3}$,  $\alpha_{1;2}$ from $\alpha$. Namely, using Remark \ref{rem:beta},
one reduces to checking that the cyclic permutation in the definition of $\beta$ always ensures that the $\alpha$ is applied to the correct choice of factors, in the correct order. 
\end{proof}

Using Lemma \ref{lem:alpha_comp_versus beta}, Proposition \ref{prop:cocycle_r=3} can be restated as:


\begin{prop}
\label{prop:restate_cocycle_r=3}
The kernel of $\dbar_3$ is equal to  the equalizer of $\id$ and $(- \beta)^{\circ 3}$.
\end{prop} 

 We thus need to understand the automorphism $- \beta$ of $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1$. This  identifies explicitly using Corollary \ref{cor:new_tau_alpha}:

\begin{lem}
\label{lem:-beta}
The automorphism $- \beta$ of $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1$ evaluated on $V$ is given for $x,y,z,s,t\in V$ by 
 $$- \beta  (x \wedge y \wedge z \otimes s \otimes t ) = 
\frac{1}{2} \big( x \wedge y \wedge z  \otimes t \otimes s + x \wedge y \wedge s \otimes t \otimes z - x \wedge z \wedge s \otimes t \otimes   y + y \wedge z \wedge s \otimes t  \otimes x \big).$$ 
\end{lem}

To analyse the automorphism $- \beta$ by exploiting the representation theory, one can use the natural decomposition of $\Lambda^3  \otimes \Lambda^1  \otimes \Lambda^1$ that is given by Pieri's rule:
\begin{eqnarray}
\label{eqn:pieri_311}
\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1
\cong 
\Lambda^5 \oplus \schur_{(3,1^2)}  \oplus \schur_{(2^2,1)} \oplus \schur_{(2,1^3)}^{\oplus 2}.
\end{eqnarray}



By Schur's lemma, we have the following analogue of Lemma \ref{lem:schur_Lambda3_otimes_Lambda1}:

\begin{lem}
\label{lem:endo_auto}
There is an isomorphism of algebras
\begin{eqnarray*}
\mathrm{End}(\Lambda^3 \otimes \Lambda^1\otimes \Lambda^1)
&\cong & 
\mathrm{End}(\Lambda^5) 
\prod 
\mathrm{End}(\schur_{(3,1^2)} ) 
\prod
\mathrm{End}(\schur _{(2^2,1)}) 
\prod 
\mathrm{End}(\schur_{(2,1^3)}^{\oplus 2}) \\
&
\cong 
&
\rat_{(1^5)} \prod \rat_{(3,1^2)}  \prod \rat_{(2^2,1)} \prod M_2 (\rat).
\end{eqnarray*}
\end{lem}

\begin{rem}
The fact that the decomposition (\ref{eqn:pieri_311}) is not multiplicity-free is the source of complexity in the proof of Theorem \ref{thm:case_r=3}. In particular,  
the isomorphism $\mathrm{End}(\schur_{(2,1^3)}^{\oplus 2}) \cong M_2 (\rat)$ is not canonical.
\end{rem}


We analyse the isomorphism (\ref{eqn:pieri_311}) in two different ways, adapted  to considering the action of $\tau \circ \alpha \otimes \id$ and of $\id \otimes \tau$, the two isomorphisms appearing in the construction of $\beta$ in Notation \ref{nota:beta}.

For the first, starting from the decomposition $\Lambda^3 \otimes \Lambda^1 \cong \Lambda^4 \oplus \schur _{(2,1^2)}$, one uses the identifications given by the Pieri rule
\begin{eqnarray*}
\Lambda^4 \otimes \Lambda^1 & \cong & \Lambda^5 \oplus \schur_{(2, 1^3)} \\
\schur_{(2,1^2)} \otimes \Lambda^1 & \cong & \schur_{(3, 1^2)} \oplus \schur_{(2^2,1)} \oplus \schur _{(2,1^3)}.
\end{eqnarray*}
Then, by Corollary \ref{prop:new_tau_alpha}, one has the following, in which $(1,-1)$ denotes the diagonal matrix in $M_2 (\rat)$ with respect to the chosen decomposition:

\begin{lem}
\label{lem:tau_alpha_otimes_id}
There exists an isomorphism as in (\ref{eqn:pieri_311}) with respect to which $\tau\circ \alpha \otimes \id \in \mathrm{End}(\Lambda^3 \otimes \Lambda^1\otimes \Lambda^1)$ acts via the isomorphism of Lemma \ref{lem:endo_auto} by $(1, -1, -1, (1, -1))$.
\end{lem}

To study the action of $\id \otimes \tau$, one uses the $\sym_2$-equivariant decomposition $\Lambda^1 \otimes \Lambda^1 \cong \schur_{(2)} \boxtimes \triv_2  \oplus \Lambda^2 \boxtimes \sgn_2$ (for the place permutation action on the left hand side) together with the isomorphisms given by the Pieri rule:
\begin{eqnarray*}
\Lambda^3 \otimes \schur_{(2)} & \cong & \schur_{(3,1^2)} \oplus \schur _{(2,1^3)} \\
\Lambda^3 \otimes \Lambda^2 & \cong & \schur_{(2^2,1)} \oplus \schur _{(2,1^3)} \oplus \Lambda^5.
\end{eqnarray*}

Then, analogously to Lemma \ref{lem:tau_alpha_otimes_id}, one has: 

\begin{lem}
\label{lem:id_otimes_tau}
There exists an isomorphism as in (\ref{eqn:pieri_311}) with respect to which $\id \otimes \tau \in \mathrm{End}(\Lambda^3 \otimes \Lambda^1\otimes \Lambda^1)$ acts via the isomorphism of Lemma \ref{lem:endo_auto} by $(-1, 1, -1, (1, -1))$.
\end{lem}

Since there are unique composition factors of $\Lambda^5$,  $\schur_{(3,1^2)}$, and  $\schur_{(2^2,1)}$ in $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1$, Lemmas \ref{lem:tau_alpha_otimes_id} and \ref{lem:id_otimes_tau} imply:


\begin{lem}
\label{lem:-beta_mult_one}
The automorphism $- \beta$ restricts to 
\begin{enumerate}
\item 
$\id$ on the summand $\Lambda^5 \oplus \schur_{(3,1^2)}$; 
\item 
$- \id$ on the summand $\schur_{(2^2,1)}$.
\end{enumerate}
\end{lem}

To prove Theorem \ref{thm:case_r=3}, it remains to show that $(-\beta)^{\circ 3}$ has no non-zero fixed points for the factor $\schur_{(2,1^3)}^{\oplus 2}$; this restriction can be considered as an element of $\mathrm{End}(\schur_{(2,1^3)}^{\oplus 2})\cong  M_2 (\rat)$ via Lemma \ref{lem:endo_auto}. It is sufficient to calculate the eigenvalues of this action.


Now, the decompositions corresponding to the two composition factors $\schur_{(2,1^3)}$ in $\Lambda^3 \otimes \Lambda^1 \otimes \Lambda^1$ 
 that are used in Lemmas \ref{lem:tau_alpha_otimes_id} and \ref{lem:id_otimes_tau} do not coincide (that they must be different is a consequence of the calculations below), so one cannot directly read off the action of $- \beta$ on the corresponding isotypical component. One can, however, deduce the determinant:

\begin{lem}
\label{lem:determinant}
The automorphism $- \beta$ restricted to $\schur_{(2,1^3)} ^{\oplus 2}$, considered as an element of $M_2 (\rat)$ via Lemma \ref{lem:endo_auto},   
 has determinant $1$.
\end{lem}

\begin{proof}
Using Lemmas \ref{lem:tau_alpha_otimes_id} and \ref{lem:id_otimes_tau}, one sees that the determinant of $\beta$ is $1$, using that the diagonal matrix $\mathrm{diag} (1, -1)$ has determinant $-1$. Thus $- \beta$ also has determinant $1$, since $- \id = \mathrm{diag} (-1,-1)$ has determinant one. 
\end{proof}

To determine the eigenvalues, it thus suffices to  calculate the trace.  For this, it is convenient to pass to the associated representations of $\sym_5$ and their underlying vector spaces, using the Schur correspondence that is given by the Schur functor construction, with inverse given by cross effects.


The Schur functor $\Lambda^3 \otimes \Lambda^1\otimes \Lambda^1$ corresponds to the $\sym_5$-representation 
\begin{eqnarray}
\label{eqn:sym_5}
(\sgn_3 \boxtimes \triv_1  \boxtimes \triv_1) \uparrow_{\sym_3 \times \sym_1 \times \sym_1}^{\sym_5}
\cong
\sgn_5 
\oplus 
S_{(3,1^2)} \oplus S_{(2^2,1)} \oplus S_{(2,1^3)}^{\oplus 2}, 
\end{eqnarray}
This module has dimension $20$; the dimensions of $\sgn_5$, $S_{(3,1^2)}$,  $S_{(2^2,1)}$, and  $S_{(2,1^3)}$ are respectively $1$, $6$, $5$, and $4$.
 The automorphism $-\beta$ induces an automorphism of the $\sym_5$-module given by (\ref{eqn:sym_5}), and hence of its underlying $\rat$-vector space, $\rat^{\oplus 20}$. 

\begin{lem}
\label{lem:m}
The element of   $M_{20}(\rat)$ associated to $-\beta$ has trace $0$.
\end{lem}

\begin{proof}
The vector space underlying (\ref{eqn:sym_5}) has basis given by  the elements $(i \wedge j \wedge k) \otimes s \otimes t$, where $i, j, k, s,t$ are pairwise distinct elements of $\{1, \ldots ,5 \}$ with $i<j<k$. (This basis can be ordered lexicographically.)

By inspection using Lemma \ref{lem:-beta} and its analogue for the $\sym_5$-representations (given by considering cross-effects), the associated matrix is zero on the diagonal, hence the trace is zero.
\end{proof}

From this, one deduces the following counterpart of Lemma \ref{lem:determinant}

\begin{lem}
\label{lem:trace}
The automorphism $- \beta$ restricted to $\schur_{(2,1^3)} ^{\oplus 2}$, considered as an element of $M_2 (\rat)$ via Lemma \ref{lem:endo_auto},   
 has trace $-\frac{1}{2}$.
\end{lem}

\begin{proof}
We first calculate the trace of the restriction of $-\beta$ (considered as an element of $M_{20}(\rat)$ as in Lemma \ref{lem:m}) to the direct summand $S_{(2,1^3)} ^{\oplus 2}$ (which has underlying vector space of dimension $8$). Using the decomposition (\ref{eqn:sym_5}) and Schur's lemma, $-\beta$ has block diagonal form. Moreover, by Lemma \ref{lem:-beta_mult_one}, it acts as $\id$ on $\sgn_5 \oplus S_{(3,1^2)}$ (which has dimension $7$) and by $-\id$ on $S_{(2^2,1)}$ (which has dimension $5$). Using the block diagonal form and Lemma \ref{lem:m}, it follows that the restriction of $- \beta$ to $S_{(2,1^3)} ^{\oplus 2}$ (an element of $M_8 (\rat)$) has trace $-2$. 

By Schur's Lemma, this element of $M_8 (\rat)$ is obtained from $\mathrm{End}_{\sym_5} (S_{(2,1^3)} ^{\oplus 2}) \cong M_2 (\rat)$ by the morphism of algebras $M_2 (\rat) \rightarrow M_8 (\rat)$ induced by the functor $- \otimes \rat^{\oplus 4}$ on vector spaces. (The trace is independent of choices made.) The result follows.
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm:case_r=3}]
By Proposition \ref{prop:restate_cocycle_r=3},  $\ker \dbar_3$ is  the equalizer of $\id$ and $(-\beta)^{\circ 3}$. The behaviour of this on the single-multiplicity composition factors is given by Lemma \ref{lem:-beta_mult_one}. To conclude, we need to show that $\id - (-\beta)^{\circ 3}$ is injective restricted to $\schur_{(2,1^3)} ^{\oplus 2}$. 

Using the trace and determinant, from Lemmas \ref{lem:determinant} and \ref{lem:trace}, one deduces that the automorphism $- \beta$ restricted to $\schur_{(2,1^3)} ^{\oplus 2}$, considered as an element of $M_2 (\rat)$ via Lemma \ref{lem:endo_auto},  has eigenvalues (in $\mathbb{C}$) 
$ 
\frac{1}{4}(-1  \pm \sqrt{15} i).
$ 
This implies that $1$ is not an eigenvalue of $(-\beta)^{\circ 3}$, whence the result.
\end{proof}


