\mel{\chi_b}{G_0}{\vec{r}_0}\!
\mel{\vec{r}_0}{G_0}{\chi_a}\!
\mel{\chi_b}{G_0}{\chi_a}^*}=K_{b\vec{r}_0}W(\vec{r}_0)\,K_{\vec{r}_0 a},
\end{equation}
where $K_{\vec{r}_0 a}=K_{a\vec{r}_0 }$ is defined as 
\begin{equation}
K_{\vec{r}_0 a}=\int d\vec{r}_1 \Gamma(\vec{r}_0,\vec{r}_1)
\left|\!\mel{\vec{r}_1}{\overline{G}_0}{\chi_a}\right|^2,
\end{equation}
and $W(\vec{r}_0) = \int d\vec{r}_1d\vec{r}_2 W(\vec{r}_0, \vec{r}_2, \vec{r}_1)$. The integrated kernel  is independent of the position $\vec{r}_0$ of the perturbation, since
\begin{equation}
W(\vec{r}_0)=\bra{\vec{r}_0}\bar{G}_0\bar{G}_0^\dagger\bar{G}_0\ket{\vec{r}_0}
=\int\frac{d\vec{q}}{(2\pi)^d}\bar{G}_0(q)^2\bar{G}_0(q)^*.
\end{equation}
Using $\bar{G}_0(q)= (k^2-q^2-ik/\ell)^{-1}$, explicit calculation in the limit $k\ell \gg1$ gives
\begin{equation}
W(\vec{r}_0)\simeq \frac{i}{8}\frac{\ell^2}{k^2}\left( \frac{k}{\pi} \right)^{{\cal D}-2}.
\end{equation}
We conclude that the left hand-side of Eq.~(\ref{EqGreenIdentity}) can be expressed as
\begin{equation}
\overline{
\mel{\chi_b}{G_0}{\vec{r}_0}\!\!
\mel{\vec{r}_0}{G_0}{\chi_a}\!\!
\mel{\chi_b}{G_0}{\chi_a}^*}=\!\frac{i}{8}\,\frac{\ell^2}{k^2}\!\left( \frac{k}{\pi} \right)^{{\cal D}-2}\!\!\!\!\!\!\!K_{b\vec{r}_0}\,K_{\vec{r}_0 a}.
\label{EqMean3Gv2}
\end{equation}

The right-hand-side of Eq.~(\ref{EqGreenIdentity}) can also be expressed in terms of the product $K_{b\vec{r}_0} K_{\vec{r}_0 a}$. Indeed, in the diffusive limit, we have
\begin{align}
&\overline{\left|\mel{\vec{r}_0}{G_0}{\chi_a}\right|^2}
=\!\!\int \!\!d\vec{r}_1 d\vec{r}_2 \!
\left|\!\mel{\vec{r}_0}{\bar{G}_0}{\vec{r}_2}\right|^2
\Gamma(\vec{r}_2,\vec{r}_1)\!
\left|\!\mel{\vec{r}_1}{\bar{G}_0}{\chi_a}\right|^2 \nonumber\\
&\simeq\left[\int d\vec{r}_2
\left|\!\mel{\vec{r}_0}{\bar{G}_0}{\vec{r}_2}\right|^2
\right]\,\int d\vec{r}_1
\Gamma(\vec{r}_0,\vec{r}_1)
\left|\!\mel{\vec{r}_1}{\bar{G}_0}{\chi_a}\right|^2 \nonumber\\
&=\frac{\ell}{4k} \left(\frac{k}{\pi} \right)^{{\cal D}-2}K_{\vec{r_0}a}.
\end{align}
This result implies that Eq.~(\ref{EqMean3Gv2}) can be written as
\begin{align}
&\overline{
\mel{\chi_b}{G_0}{\vec{r}_0}\!
\mel{\vec{r}_0}{G_0}{\chi_a}\!
\mel{\chi_b}{G_0}{\chi_a}^*
}
\nonumber
\\
&=2i\left(\frac{\pi}{k}\right)^{{\cal D}-2}\,
\overline{\left|\mel{\chi_b}{G_0}{\vec{r}_0}\right|^2}\,\,
\overline{\left|\mel{\vec{r}_0}{G_0}{\chi_a}\right|^2},
\end{align}
and the identity Eq.~(\ref{EqGreenIdentity}) then follows naturally. 


