\section{Diffusion approximation for sensitivity in remission geometry:
analytical result\label{sec:diffusion_in_remission_geometry}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\noindent 
\noindent In the remission geometry considered in Sec.~\ref{sec:numerical_simulation_scalar}, a closed-form expression for optical sensitivity Eq.~(\ref{EqDiffusiveSensitivity}) can be obtained in 2D and 3D. To that end, we begin with the normalized sensitivity Eq.~(\ref{EqInt_sensitivity}) in terms of the random-input intensities 
\begin{equation}
\overline{{\cal s}}_\text{diff}(\vec{r_0}) = 
-\displaystyle\frac{1}{N_1 N_2}
\left(\frac{\pi}{k^2}\right)^{\mathcal{D}-2}
\overline{I}^{\text{RI}}_{\text{in}}(\vec{r_0})\,
\overline{I}^{\text{RI}}_{\text{out}}(\vec{r_0}).
\label{EqDiffusiveSensitivity2D}
\end{equation}
Here, input and output intensities can be found by solving 2D/3D diffusion equation in semi-infinite geometry $z>0$. At $z=0$, we apply open boundary condition with an extrapolation length $z_e$, see Ref.~\cite{Akkermans_Montambaux_2007}. We also assume that the widths of input and output, located at $y=0,d$, see e.g. Fig.~\ref{fig:panel_random}a, are much smaller than their separation $W_1,W_2\ll d$. 
Normalization adopted in Sec.~\ref{sec:sensitivity_diffusion_approximation}, assumes $N_1$ units of dimensionless flux is used to excite the system. 
The source of diffusive waves is $\nabla\cdot\vec{J}_\text{ball}$, where $\vec{J}_\text{ball}=c/(2n_\text{eff}k)\times e^{-z/\ell} \delta(y)$ is the ballistic (unscattered) flux. 
The normalization factor $[c/2kn_\text{eff}]$ is obtained from the microscopic wave equation~\cite{2022_HoChun_MESTI}.

In 2D, we find 
\begin{equation}
\overline{I}^{\text{RI,2D}}_{\text{in}}(\vec{r_0})=
\displaystyle\frac{c}{2kn_\text{eff}}\,
\displaystyle\frac{N_1}{\pi D}\,
\displaystyle\frac{\ell\,z_0}{(z_0+z_e)^2+y_0^2}.
\label{EqIinRI}
\end{equation}

% Substituting this, and the analogous expression for $\overline{I}^{\text{RI}}_{\text{out}}(\vec{r_0})$, into Eq.~(\ref{EqDiffusiveSensitivity2D}) we obtain
% \begin{equation}
% \overline{{\cal s}}_\text{diff}(y_0,z_0)= 
% -\left(\displaystyle\frac{\ell}{\pi D}\right)^2\,
% \displaystyle\frac{z_0^2}{\left((z_0+z_e)^2+y_0^2\right)\left((z_0+z_e)^2+(y_0-d)^2\right)}.
% \label{EqBornDiff2}
% \end{equation}
% This is the analytical expression to compute the diffusive sensitivity. This is a product of two Green functions from input and output, respectively,and thus a product of two fundamental solutions of the diffusion equation. 
% To compare the analytical solution with the numerical results quantitatively, we need make it dimensionless, by adopting the same normalization used in the numerical simulations~Ref.~\cite{2022_HoChun_MESTI}. 
% This is can be accomplished by computing the proper source for the diffusion equation from the attenuation of the incident ballistic wave $\nabla\cdot\vec{J}_\text{ball}$.
% The latter is given by $\vec{J}_\text{ball}=c/(2n_\text{eff}k)\times e^{-z/\ell} \delta(y)$. 
% Here we assumed $\delta(y)$ source along the $y$-axis, similar to Eq.~(\ref{EqIinRI}).
% Comparing this source to the source of diffusive waves $(1/\ell)\times e^{-z/\ell}$ used to obtain Eq.~(\ref{EqIinRI}), we find sought normalization factor of $[c/2kn_\text{eff}]^2$ in Eq.~(\ref{EqBornDiff2}) reducing it to the dimensionless form

\noindent Substituting Eq.~(\ref{EqIinRI}) into Eq.~(\ref{EqDiffusiveSensitivity2D}) we obtain the final result for the normalized sensitivity map
\begin{widetext}
\begin{equation}
\overline{{\cal s}}^\text{2D}_\text{diff}(y_0,z_0)= 
-\displaystyle\frac{1}{\pi^2k^2}
\displaystyle\frac{z_0^2}{\left[(z_0+z_e)^2+y_0^2\right]\left[(z_0+z_e)^2+(y_0-d)^2\right]}.
\label{EqBornDiff3}
\end{equation}
\end{widetext}
This is the desired analytical expression used to study dependence on the detector separation in Fig.~\ref{fig:panel_random} from Sec.~\ref{sec:remission_enhancement}. 
Interestingly, we find that Eq.~(\ref{EqBornDiff3}) is essentially independent on the transport mean free path. Indeed, at distances exceeding the extrapolation length $z_e\sim\ell$, the dependence on $\ell$ is insignificant. In fact, along the crescent banana trajectory, the sensitivity remains nearly constant
\begin{equation}
\overline{{\cal s}}^\text{2D}_\text{diff}\simeq
-\displaystyle\frac{1}{\pi^2}\times\frac{1}{k^2 d^2}.
\label{sdiff_dimensionless}
\end{equation}
It depends only on the vacuum wavenumber $k=2\pi/\lambda_0$ and source-detector separation $d$. 
For $\lambda_0=1.55\mu$m and $d=128\mu$m we get $\overline{{\cal s}}_\text{diff}(d/2,d/2)\simeq 3.8\times 10^{-7}$, which agrees with the microscopical numerical calculations reported in Fig.~\ref{fig:panel_random}.

The 3D result can be obtained analogously by using the the appropriate expression for Green's function. For $\overline{I}^{\text{RI}}_{\text{in}}(\vec{r_0})$ we get
\begin{equation}
\overline{I}^{\text{RI,3D}}_{\text{in}}(\vec{r_0})=
\displaystyle\frac{c}{2kn_\text{eff}}\,
\displaystyle\frac{N_1}{2\pi D}\,
\displaystyle\frac{\ell\,z_0}{[x_0^2+y_0^2+(z_0+z_e)^2]^{3/2}}.
\label{EqIinRI3D}
\end{equation}
where the normalization factor $c/2kn_\text{eff}$ remains the same as in 2D. Subsequently, we get the final dimensionless expression for 3D sensitivity map as
\begin{widetext}
\begin{equation}
\overline{{\cal s}}_\text{diff}^\text{3D}(\vec{r_0})= 
-\displaystyle\frac{9}{16\pi k^4}
\displaystyle\frac{z_0^2}{\left[x_0^2+y_0^2+(z_0+z_e)^2\right]^{3/2}\left[x_0^2+(y_0-d)^2+(z_0+z_e)^2\right]^{3/2}}.
\label{EqBornDiff3D}
\end{equation}
\end{widetext}

\noindent Similar to Eq.~(\ref{EqBornDiff3}), Eq.~(\ref{EqBornDiff3D}) does not significantly depend on the transport mean free path. Parameterizing the position along the banana trajectory of radius $d/2$ with a polar angle $\theta$, we get a simplified expression
\begin{equation}
\overline{{\cal s}}_\text{diff}^\text{3D}\simeq
-\displaystyle\frac{9}{8\pi}\times\frac{1}{k^4 d^4}\times\frac{1}{\cos\theta},
\label{sdiff_dimensionless_3D}
\end{equation}
which now, in 3D, depends on $k$, $d$ and $\theta$. Unlike the 2D expression, Eq.~(\ref{sdiff_dimensionless}), the sensitivity is no longer constant along the banana. The divergence at $\theta\sim\pm\pi/2$ is prevented by the surface-corrections at the level 
\begin{equation}
\overline{{\cal s}}_\text{diff}^\text{3D}\propto
-\displaystyle\frac{1}{k^4 d^3\ell}.
\label{sdiff_dimensionless_3D_BC}
\end{equation}

