\subsection*{Conventions}
\begin{enumerate}
    \item From this point onwards, the word ``category'' means ``$\infty$-category''.
    \item We denote by $\Spc$ the category of anima/spaces/$\infty$-groupoids/weak homotopy types.
    \item For a small category $\cC$, we denote by $\psh(\cC) := \Fun(\cC^\op,\Spc)$ the category of presheaves on $\cC$ and let $\yo \colon \cC \to \psh(\cC)$ be the Yoneda embedding.
    \item We use the notions of \emph{Waldhausen categories} and \emph{exact categories} as defined in \cite{barwick:heart}.
     In particular, we refer to the distinguished morphisms in a Waldhausen category $\cC$ as \emph{ingressive} morphisms, and denote this subcategory by $\cC_\ing$.
     If $\cC$ is exact, we refer to the cofibres of ingressive morphisms as \emph{egressive} morphisms, and denote the subcategory of these by $\cC_\egr$.
\end{enumerate}

