\section{Energy consumption:\ a comparison of multiplication and memory operations}\label{sec:energyConsumption}
\textbf{Notation Disclaimer*}
The notation used in this appendix is defined within the local context of this section and may differ from or be independent of the notation used in the main text.
Readers should interpret symbols and definitions as specific to this appendix to avoid any confusion.


In order to calculate the energy savings netted by the use of our binary stochastic forward-forward (BSFF) algorithm, here we make explicit how memory and multiplication operations scale with network parameters for each of BSFF, CwC-FF \cite{papachristodoulou2024convolutional}, and backprop.
For simplicity, we consider the same architecture in all cases.
This architecture consists of $L$ layers, with each layer containing the following sublayers:
\begin{itemize}
    \item{convolution}
    \item{activation}
    \item{max pooling}
    \item{batch normalization}
\end{itemize}
We assume a simple Von-Neumann computational model, comprising memory units and compute units, as shown abstractly in Figure~\ref{fig:compute-arch}. Although Forward–Forward–based algorithms can benefit from more advanced architectures that exploit multi–level memory hierarchies—since gradient computations are local to each layer—they still conform to the model below.

Specifically, we assume that inputs and weights are fetched from main memory, and that each sublayer has sufficient local memory to store its outputs and weights either for a single sample (one datum per batch and one layer at a time) or for one channel across the entire batch. In general, intermediate tensors can have  dimensions $\bigl(\text{Channels}\,\times\,\text{Height}\,\times\,\text{Width}\bigr)$ or 
$\bigl(\text{Batch Size}\,\times\,\text{Height}\,\times\,\text{Width}\bigr)$ (as $C \sim N$).
This assumption is reasonable, since even a mid‑sized network requires only on the order of 2–3 MB of local memory.

To compute gradients for weight updates, we process each sample independently—reading one sample from memory, computing its gradient, and then averaging over the batch. This approach is broadly applicable, with one caveat for BatchNorm: computing the BatchNorm gradients requires the batch mean and variance, as well as the per‑sample BatchNorm output. However, this does not significantly increase memory traffic, because the batch statistics are computed during the forward pass and can be reused in the backward pass.
\subsection{\textbf{Backpropagation: Number of multiplications and memory accesses}}
\subsubsection{Forward Pass(layer $\ell$)}
\begin{align}
    z^{(\ell)} &= w \ast u^{(\ell-1)} \label{eq:conv} \\
    a^{(\ell)} &= \mathrm{ReLU}(z^{(\ell)}) \label{eq:relu} \\
    \Tilde{u}^{(\ell)} &= \mathrm{max\_pool}\left(a^{(\ell)}\right), \label{eq:Maxpool} \\
    u^{(\ell)} &= \mathrm{BN}\left(\Tilde{u}^{(\ell)}\right). \label{eq:bn}
\end{align}

\begin{algorithm}[H]
\caption{ForwardPassOneLayer}
\label{alg:forward-pass-layer}
\begin{algorithmic}[1]
\item[\algorithmicrequire] Layer index $\ell$, batch size $N$
\item[\algorithmicensure] Batch-normalized outputs $u$ for layer $\ell$

\COMMENT{First Pass: Accumulate Mean \& Variance Stats}
\STATE sum $\gets 0$, \quad sumSq $\gets 0$
\STATE \label{alg:weight-read} \textbf{readFromMainMemory}$(W^{(\ell)})$
\FOR{$n \gets 1$ to $N$}
\IF{$\ell = 1$}
  \STATE \label{alg:input-read-layer1}\textbf{readFromMainMemory}$(\textit{input}_n)$
    \STATE \label{alg:conv-1}$z_n^{(\ell)} \gets \mathrm{Conv}(W^{(\ell)}, \textit{input}_n)$
\ELSE
  \STATE \label{alg:input-read-rest-layer}\textbf{readFromMainMemory}$(u_n^{(\ell-1)})$
    \STATE \label{alg:conv-n}$z_n^{(\ell)} \gets \mathrm{Conv}(W^{(\ell)}, u_n^{(\ell-1)})$
\ENDIF
  \STATE \label{alg:relu-store}$a_n^{(\ell)} \gets \mathrm{ReLU}(z_n^{(\ell)})$, \textbf{writeToMainMemory}$(a_n^{(\ell)})$
  \STATE \label{alg:Maxpool-store}$\Tilde{u}_n^{(\ell)} \gets \mathrm{Maxpool}(a_n^{(\ell)}), \textbf{writeToMainMemory}(\Tilde{u}_n^{(\ell)})$
  \STATE \label{alg:sum}sum $\gets \text{sum} + \text{elementwiseSum}(\Tilde{u}_n^{(\ell)})$
  \STATE \label{alg:sumsq}sumSq $\gets \text{sumSq} + \text{elementwiseSumOfSquares}(\Tilde{u}_n^{(\ell)})$
\ENDFOR
\STATE \label{alg:mean-var-calc}$\mu \gets \frac{\text{sum}}{\textit{totalElements}}$
\STATE \label{alg:mean-var-store}$\sigma^2 \gets \frac{\text{sumSq}}{\textit{totalElements}} - (\textit{mean})^2$
\STATE \label{alg:store-mean-var}\textbf{writeToMainMemory}$(\mu)$, \textbf{writeToMainMemory}$(\sigma^2)$

\COMMENT{Apply BatchNorm using computed stats}
\FOR{$n \gets 1$ to $N$}
  \STATE \label{alg:Maxpool-read}\textbf{readFromMainMemory}$(\Tilde{u}_n^{(\ell)})$
  \STATE \label{alg:BatchNorm-store}$u \gets \mathrm{BatchNorm}(\Tilde{u}_n^{(\ell)}, \mu, \sigma^2)$, \textbf{writeToMainMemory}$(u_n)$
\ENDFOR
\STATE \textbf{return} $u$
\end{algorithmic}
\end{algorithm}

