\subsubsection{Backward Pass}
To compute the weight gradient \( \frac{\partial L}{\partial W^{(\ell)}} \) for any layer \( \ell \), the following steps are followed. The gradient of the Maxpool operation involves only an indexing operation through the maximum element in each patch. Therefore, for simplicity, we combine the BatchNorm Jacobian and \( \frac{\partial u^{(\ell)}}{\partial \tilde{u}^{(\ell)}} \) with the Maxpool Jacobian \( \frac{\partial \tilde{u}^{(\ell)}}{\partial a^{(\ell)}} \), and directly express \( \frac{\partial u^{(\ell)}}{\partial a^{(\ell)}} \), as this does not affect our analysis of the number of multiplications and memory accesses.

\begin{enumerate}
\item \textbf{Initialize for the last layer:} 
  \begin{equation*}
  \begin{split}
    \Delta^{(L)}[c,h,w]
    &= \frac{\partial L}{\partial u^{(L)}[c,h,w]}\,
  \end{split}
\end{equation*}
for each channel \(c\) and spatial location \((h,w)\).

\item \textbf{Backward pass for layers $\ell = L$ down to $1$:}
  \begin{enumerate}
    \item \textbf{Compute the gradient w.r.t.\ pre-activation $z^{(\ell)}$:}
\begin{equation*}
  \begin{split}
  \frac{\partial L}{\partial z^{(\ell)}[c,h,w]}
  &=\; \Delta^{(\ell)}[c,h,w] 
       \;\cdot\;
       \Bigl[ 
         \underbrace{\frac{\partial u^{(\ell)}[c,h,w]}
                          {\partial \tilde{u}^{(\ell)}[c,h,w]}}_{\text{BN derivative}}\\
        & \;\cdot\;
         \underbrace{\frac{\partial a^{(\ell)}[c,h,w]}
                          {\partial z^{(\ell)}[c,h,w]}}_{\text{ReLU or BSN derivative}}
       \Bigr]
  \end{split}       
\end{equation*}
Here, $\Delta^{(\ell)}[\,c,\,h,\,w\,]$ is the upstream gradient from the “goodness” function or from higher layers.

    \item \textbf{Compute the weight gradient:}
\begin{equation*}
  \begin{split}
      \frac{\partial L}{\partial W^{(\ell)}[\,c,\;c',\;k_1,\;k_2\,]} 
      \;=\;
      \sum_{h=1}^{H^{(\ell)}} 
      \;\sum_{w=1}^{W^{(\ell)}}
      \;
      \frac{\partial L}{\partial z^{(\ell)}[\,c,\,h,\,w\,]}\\
      \;\cdot\;
      u^{(\ell-1)}\bigl[c',\,\text{fold}(h,k_1),\,\text{fold}(w,k_2)\bigr]
  \end{split}       
\end{equation*}
where $(k_1,k_2)$ index the kernel offsets (size $K\times K$), and \(\text{fold}(\cdot)\) indicates the spatial mapping back to the correct location in $u^{(\ell-1)}$ (depending on stride and padding). 
In practice, you sum over \textit{all} spatial locations $(h,w)$ of $z^{(\ell)}$ that overlap with the kernel position $(k_1,k_2)$ on channel $c'$ of $u^{(\ell-1)}$.

    \item \textbf{Compute the upstream gradient for layer $\ell-1$:}
\begin{equation*}
  \begin{split}
      \Delta^{(\ell-1)}[\,c',\,h',\,w'\,]
      =
      \sum_{c=1}^{C^{(\ell)}}
      \;\sum_{k_1=1}^{K}\;\sum_{k_2=1}^{K}
      \;
      \frac{\partial L}{\partial z^{(\ell)}[\,c,\;h,\;w\,]}\\
      \;\cdot\;
      W^{(\ell)}[\,c,\;c',\;k_1,\;k_2\,].
  \end{split}       
\end{equation*}
Only those elements of $W^{(\ell)}$ that map $(h',w')$ in $u^{(\ell-1)}$ to $(h,w)$ in $z^{(\ell)}$ will be nonzero in this summation (i.e., $C^{(\ell-1)} \times K^2$ effective connections per output channel, if stride=1).
  \end{enumerate}
\end{enumerate}
