%  \end{minipage}
\begin{algorithm}[]
  \caption{Backpropagation for an Arbitrary Layer}
  \label{alg:backprop-arbitrary-layer}
  \begin{algorithmic}[1]
    \ENSURE \label{alg:backprop-BP:ensure} 
      Gradients: $\frac{\partial L}{\partial W}, \frac{\partial L}{\partial u^{(\ell-1)}}$.

    \FOR{$c^{(\ell)}=1$ \textbf{to} $C^{(\ell)}$} \label{alg:backprop-BP:for_outer}

      \STATE \textbf{readFromMainMemory}$\bigl(\Tilde{u}^{(\ell)}[\,c^{(\ell)}]\bigr)$ \label{alg:backprop-BP:read_tilde_u}
      \STATE \textbf{readFromMainMemory}$\bigl(\frac{\partial L}{\partial u^{(\ell)}}\bigr)$ \label{alg:backprop-BP:read_dL_du}
     \STATE $temp \gets \frac{\partial L}{\partial u^{(\ell)}}$
      \STATE $\displaystyle \mu_{grad} \gets \frac{\sum \, temp}{NHW}$ \label{alg:backprop-BP:mu_grad_compute}

      \STATE $\displaystyle \bar{\Tilde{u}} \gets \Tilde{u}[\,c^{(\ell)}] \;-\; \mu\bigl[c^{(\ell)}\bigr]$  
      \label{alg:backprop-BP:compute_u_tilde_bar} 
      \COMMENT{// shape [N, H, W]}

      \STATE 
      $\displaystyle 
          \Sigma_{term} 
          \gets 
          \frac{\mathrm{mean}\Bigl(\frac{\partial L}{\partial u^{(\ell)}[\,c^{(\ell)}]} *\bar{\Tilde{u}}\Bigr)}
               {\sigma^2\bigl[c^{(\ell)}\bigr]}
      $ \label{alg:backprop-BP:sigma_term_compute}
      \COMMENT{// $NHW$ multiplications}

      \STATE 
      $\displaystyle 
          \frac{\partial L}{\partial a^{(\ell)}}[\,c^{(\ell)}] 
          \gets 
          \frac{\gamma[c^{(\ell)}]}{\sqrt{\sigma^2\bigl[c^{(\ell)}\bigr]}} 
          \;\cdot\; 
          \Bigl( 
            temp \;-\; \mu_{grad} 
            \;-\; \bar{\Tilde{u}} * \Sigma_{term} 
          \Bigr)
      $ \label{alg:backprop-BP:dL_da_compute}
      \COMMENT{// $NHW$ multiplications}      
      \STATE \textbf{readFromMainMemory}$\bigl(a^{(\ell)}[\,c^{(\ell)}]\bigr)$ \label{alg:backprop-BP:read_a}
      \STATE 
      $\displaystyle 
          \frac{\partial L}{\partial z}[\,c^{(\ell)}] 
          \gets 
          \frac{\partial L}{\partial a^{(\ell)}}[\,c^{(\ell)}] 
          * 
          \mathbb{I}\Bigl( a^{(\ell)}[\,c^{(\ell)}] > 0 \Bigr)
      $ \label{alg:backprop-BP:compute_dL_dz}
      \COMMENT{// 0 multiplications}

      \STATE \COMMENT{// Gradient with respect to Convolution Weights and input $u^{(\ell-1)}$} \label{alg:backprop-BP:grad_conv_input_comment}

      \FOR{$c^{(\ell-1)}=1$ \textbf{to} $C^{(\ell-1)}$} \label{alg:backprop-BP:for_inner}

        \STATE \textbf{readFromMainMemory}$\bigl(u^{(\ell-1)}[c^{(\ell-1)}]\bigr)$ \label{alg:backprop-BP:read_u_prev}
        \STATE \textbf{readFromMainMemory}$\bigl(W[c^{(\ell)},c^{(\ell-1)}]\bigr)$ \label{alg:backprop-BP:read_weight}

        \STATE           
          $\frac{\partial L}{\partial W}[c^{(\ell)},c^{(\ell-1)}] \gets Conv\Bigl(u^{(\ell-1)}[c^{(\ell-1)}], \frac{\partial L}{\partial z}[\,c^{(\ell)}]\Bigr)
          $ \label{alg:backprop-BP:compute_dL_dW}
        \COMMENT{// $NK^2HW$ multiplications}        
\STATE         $W[c^{(\ell)},c^{(\ell-1)}]  \gets W[c^{(\ell)},c^{(\ell-1)}] - \eta \frac{\partial L}{\partial W}[c^{(\ell)},c^{(\ell-1)}] $ \label{alg:backprop-BP:update_weight}
        \STATE \textbf{writeToMainMemory}$\bigl(W[c^{(\ell)},c^{(\ell-1)}]\bigr)$ \label{alg:backprop-BP:write_weight}
        \STATE 
          $\frac{\partial L}{\partial u^{(\ell-1)}}[c^{(\ell-1)}] \gets TransposedConv\Bigl(u^{(\ell-1)}[c^{(\ell-1)}],W[c^{(\ell)},c^{(\ell-1)}]\Bigr)$ \label{alg:backprop-BP:compute_dL_du_prev}
        \COMMENT{// $NK^2HW$ multiplications}

      \ENDFOR \label{alg:backprop-BP:end_for_inner}

    \ENDFOR \label{alg:backprop-BP:end_for_outer}

    \RETURN $\frac{\partial L}{\partial W}$, $\frac{\partial L}{\partial u^{(\ell-1)}}$ \label{alg:backprop-BP:return}

  \end{algorithmic}
\end{algorithm}
\subsection{\textbf{Forward Forward Algorithm (Real): Number of Multiplications and Memory Accesses}}
\subsubsection{Forward Pass (layer $\ell$)}
\begin{align}
    z^{(\ell)}[c] 
    &= 
    \sum_{c'} 
    W^{(\ell)}[\,c,\;c'\,] 
    \;\ast\;
    u^{(\ell-1)}[\,c'\,]
    && 
    \text{(convolution)}
    \label{eq:FF_conv}
    \\[6pt]
    a^{(\ell)}[c] 
    &= 
    \mathrm{ReLU}\!\Bigl(z^{(\ell)}[c]\Bigr)
    && 
    \text{(activation)}
    \label{eq:FF_relu}
    \\[6pt]
    \tilde{u}^{(\ell)}[c] 
    &= 
    \mathrm{max\_pool}\!\Bigl(a^{(\ell)}[c]\Bigr)
    && 
    \text{(max pooling)}
    \label{eq:FF_Maxpool}
    \\[6pt]
    u^{(\ell)}[c] 
    &= 
    \mathrm{BN}\!\Bigl(\tilde{u}^{(\ell)}[c]\Bigr)
    && 
    \text{(batch normalization)}
    \label{eq:FF_BatchNorm}
\end{align}

% ------------------------------------------------------------------------
% Single-pass algorithm that immediately updates weights
% ------------------------------------------------------------------------
\begin{algorithm}[]
  \caption{ForwardForwardOneLayer (Real Valued Activations)}
  \label{alg:forward-forward-layer}
  \begin{algorithmic}[1]

  \item[\algorithmicrequire] 
    Layer index $\ell$, batch size $N$
    \quad
    \label{alg:forward-forward-layer:requires}

  \item[\algorithmicensure] 
    Updated weights $W^{(\ell)}$ and batch-normalized outputs $u^{(\ell)}$
    \quad
    \label{alg:forward-forward-layer:ensures}

  % ---------------- FIRST PASS ----------------
  \COMMENT{First Pass: Accumulate Mean \& Variance for BN}
  \label{alg:forward-forward-layer:accumulate-mean-variance}

  \STATE sum $\gets 0$, \quad sumSq $\gets 0$
  \label{alg:forward-forward-layer:init-sums}

  \STATE \textbf{readFromMainMemory}$(W^{(\ell)})$
  \label{alg:forward-forward-layer:read-weights}

  \FOR{$n \gets 1$ to $N$}
  \label{alg:forward-forward-layer:loop-n}

    \IF{$\ell = 1$}
    \label{alg:forward-forward-layer:if-first-layer}

        \STATE \textbf{readFromMainMemory}$(\textit{input}_n)$
        \label{alg:forward-forward-layer:read-input}

        \STATE $z_n^{(\ell)} \gets \mathrm{Conv}\bigl(W^{(\ell)},\,\textit{input}_n\bigr)$
        \label{alg:forward-forward-layer:conv-first-layer}
        \COMMENT{Real conv if first layer, $C[\ell-1]C[\ell]HWK^2$ multiplications}

    \ELSE
    \label{alg:forward-forward-layer:else-higher-layer}

        \STATE \textbf{readFromMainMemory}$\bigl(u_n^{(\ell-1)}\bigr)$
        \label{alg:forward-forward-layer:read-prev-activ}

        \STATE $z_n^{(\ell)} \gets  \mathrm{Conv}\bigl(W^{(\ell)}, u_n^{(\ell-1)}\bigr)$
        \label{alg:forward-forward-layer:conv-binary}
        \COMMENT{Real conv, $K^2HWC[\ell-1]C[\ell]$ multiplications}

    \ENDIF

    \STATE $a_n^{(\ell)} \gets \mathrm{BSN}\bigl(z_n^{(\ell)}\bigr)$
    \quad \textbf{writeToMainMemory} $\bigl(\Delta_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer:bsn-forward}
    \COMMENT{Storing relu gradient instead of $a^{(\ell)}$}

    \STATE $\tilde{u}_n^{(\ell)} \gets \mathrm{Maxpool}\bigl(a_n^{(\ell)}\bigr)$
    \quad \textbf{writeToMainMemory}$\bigl(\tilde{u}_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer:maxpool}

    \STATE sum   $\gets$ sum + \text{elementwiseSum}$\bigl(\tilde{u}_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer:update-sum}

    \STATE sumSq $\gets$ sumSq + \text{elementwiseSumOfSquares}$\bigl(\tilde{u}_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer:update-sumsq}

  \ENDFOR

  \STATE $\mu^{(\ell)} \gets \dfrac{\text{sum}}{\textit{totalElements}}$
  \label{alg:forward-forward-layer:compute-mean}

  \STATE $\bigl(\sigma^{(\ell)}\bigr)^2 
         \gets \dfrac{\text{sumSq}}{\textit{totalElements}}
         \;-\;\bigl(\mu^{(\ell)}\bigr)^2$
  \label{alg:forward-forward-layer:compute-variance}

\STATE \COMMENT{BN and Weight Updates} \label{alg:forward-forward-layer:local-grad-update}
\FOR{$n \gets 1$ to $N$} \label{alg:forward-forward-layer:ff-second-loop}
  \STATE \textbf{readFromMainMemory}$(\Tilde{u}_n^{(\ell)})$ \label{alg:forward-forward-layer:ff-read-pool}
  \STATE $u_n^{(\ell)} \gets \mathrm{BatchNorm}(\Tilde{u}_n^{(\ell)}, \mu, \sigma^2)$ \label{alg:forward-forward-layer:ff-BatchNorm}
  \STATE \textbf{writeToMainMemory}$(u_n^{(\ell)})$ \label{alg:forward-forward-layer:ff-store-bn}
\ENDFOR

  \IF{$\ell = 1$}
  \label{alg:forward-forward-layer:if-compute-grad-first}

    \STATE 
    $\dfrac{\partial L^{(\ell)}}{\partial W^{(\ell)}} 
            \gets \textbf{ComputeGradient}\bigl(\tilde{u}^{(\ell)},{u}^{(\ell)},\Delta^{(\ell)},\,\textit{input}\bigr)$  
    \label{alg:forward-forward-layer:compute-gradient-first}

  \ELSE
  \label{alg:forward-forward-layer:else-compute-grad-higher}

    \STATE 
    $\dfrac{\partial L^{(\ell)}}{\partial W^{(\ell)}} 
            \gets \textbf{ComputeGradient}\bigl(\tilde{u}^{(\ell)},{u}^{(\ell)},\Delta^{(\ell)},\,u^{(\ell-1)}\bigr)$  
    \label{alg:forward-forward-layer:compute-gradient-higher}

  \ENDIF

  \STATE 
  $W^{(\ell)} \gets W^{(\ell)} 
    \;-\; \eta \cdot
          \dfrac{\partial L^{(\ell)}}{\partial W^{(\ell)}}$
  \label{alg:forward-forward-layer:update-weights}

  \STATE $\textbf{writeToMainMemory}\bigl(W^{(\ell)}\bigr)$
  \label{alg:forward-forward-layer:write-weights}

  \end{algorithmic}
\end{algorithm}
