\begin{itemize}

\item \textbf{Total Number of Multiplications (per layer)}
\begin{align*}
= & \; N \, C^{(\ell-1)}C^{(\ell)}K^2H^{(\ell-1)}W^{(\ell-1)} 
    \quad (\text{Algo \ref{alg:forward-forward-layer}}, \text{Lines~\ref{alg:forward-forward-layer:conv-first-layer} or \ref{alg:forward-forward-layer:conv-binary}}) 
\end{align*}
%\end{minipage}
\hfill
%\begin{minipage}[t]{0.48\textwidth}
\item \textbf{Number of Memory Accesses (per layer)}
\begin{align*}
= & \; C^{(\ell-1)}C^{(\ell)}K^2 
    \quad (\text{Algo \ref{alg:forward-forward-layer}},\text{Line~\ref{alg:forward-forward-layer:read-weights}}) \\
+ & \; N \, C^{(\ell-1)}H^{(\ell-1)}W^{(\ell-1)} 
    \quad (\text{Algo \ref{alg:forward-forward-layer}},\text{Line~\ref{alg:forward-forward-layer:read-input} or \ref{alg:forward-forward-layer:read-prev-activ}}) \\
+ & \; 2N \, C^{(\ell)}H^{(\ell)}W^{(\ell)} 
    \quad (\text{Algo \ref{alg:forward-forward-layer}},\text{Lines~\ref{alg:forward-forward-layer:bsn-forward} and \ref{alg:forward-forward-layer:maxpool}}) \\
+ & \; N \, C^{(\ell)}H^{(\ell)}W^{(\ell)} 
    \quad (\text{Algo \ref{alg:forward-forward-layer}},\text{Line~\ref{alg:forward-forward-layer:ff-read-pool}}) \\
+ & \; N \, C^{(\ell)}H^{(\ell)}W^{(\ell)} 
    \quad (\text{Algo \ref{alg:forward-forward-layer}},\text{Line~\ref{alg:forward-forward-layer:ff-store-bn}}) \\
+ & \; C^{(\ell)}C^{(\ell-1)}K^2 
    \quad (\text{Algo \ref{alg:forward-forward-layer}},\text{Line~\ref{alg:forward-forward-layer:write-weights}})
\end{align*}
%\end{minipage}
\end{itemize}

\subsubsection{\textbf{Weight Update at layer $\ell$:  $\frac{\partial L^{(\ell)}}{\partial w^{(\ell})}$}}

Here the loss is defined by grouping channels $c$ into subsets $S_j$.
\begin{align}
% --- Delta z definition (chain rule) ---
\frac{\partial L}{\partial 
  z^{(\ell)}}[n,c,h,w]
&=\;
\sum_{j=1}^{\mathrm{N_{class}}}
\;\frac{\partial L}{\partial G_j}
\;\frac{\partial G_j}{\partial u^{(\ell)}[c,n,h,w]} \notag \\ 
&\cdot\frac{\partial u^{(\ell)}[n,c,h,w]}{\partial a^{(\ell)}[n,c,h,w]}
\cdot\;\frac{\partial a^{(\ell)}[n,c,h,w]}{\partial z^{(\ell)}[n,c,h,w]},
\label{eq:DeltaZ_FF}
\\[6pt]
% --- Weight gradient expression ---
\frac{\partial L}{\partial 
  w^{(\ell)}[\,c,\,c',\,k_1,\,k_2]
}
&=\;
\sum_{n=1}^{N}
\;\sum_{h=1}^{H}
\;\sum_{w=1}^{W}
\;\frac{\partial L}{\partial 
  z^{(\ell)}}[n,c,h,w] * \\
&\Bigl[u^{(\ell-1)}\bigl(n,c',h^{\ast},\,w^{\ast}\bigr)\Bigr] \notag
% \label{eq:dLdW_FF}
\end{align}

\begin{algorithm}[]
  \caption{ComputeGradient Subroutine for Real Valued FF Network}
  \label{alg:compute-gradient-FF}
  \begin{algorithmic}[1]

  \item[\algorithmicrequire] 
    Batchnorm Input $\Tilde{u}^{(\ell)}$, Batchnorm Output $u^{(\ell)}$, ReLU gradient $\Delta^{(\ell)}$, Previous layer batchnorm output ${u}^{(\ell-1)}$.
    \label{alg:compute-gradient-FF:requires}

  \item[\algorithmicensure] 
    $\displaystyle \frac{\partial L^{(\ell)}}{\partial W^{(\ell)}}$
    \label{alg:compute-gradient-FF:ensures}

  \STATE $\displaystyle \frac{\partial L^{(\ell)}}{\partial W^{(\ell)}} \gets 0$
  \label{alg:compute-gradient-FF:init-partial-LW}

  \FOR{$c^{(\ell)} \gets 1$ to $C^{(\ell)}$}
  \label{alg:compute-gradient-FF:loop-c-l}
    \STATE \textbf{readFromMainMemory}$\bigl({u}^{(\ell)}[c^{(\ell)}]\bigr)$
    \label{alg:compute-gradient-FF:read-tilde-u-n}  
    \STATE $\text{group index}:j \gets \frac{c^{(\ell)}}{N_{classes}}$
        \STATE  
        $\frac{\partial G_j}{\partial u^{(\ell)}[c^{(\ell)}]} 
        \gets 
        \frac{2}{|N_j|} 
        \Bigl({u}^{(\ell)}[c^{(\ell)}] \Bigr)$
      \label{alg:compute-gradient-FF:dG-du}
      \COMMENT{// shape $[N,H,W]$}

      \STATE  
        $\displaystyle 
        \frac{\partial L^{(\ell)}}{\partial u^{(\ell)}[c^{(\ell)}]} 
        \gets  
        \frac{\partial G_j}{\partial u[c^{(\ell)}]} 
        \;\ast\; 
        \frac{\partial L^{(\ell)}}{\partial G_{j}}
        $
      \label{alg:compute-gradient-FF:dL-du}
      \COMMENT{// $N \times H \times W$ multiplications}

    \STATE $\displaystyle temp \gets \frac{\partial L^{(\ell)}}{\partial u^{(\ell)}[\,c^{(\ell)}]}$
    \label{alg:compute-gradient-FF:temp-def}
    \COMMENT{// shape [N, H, W]}

    \STATE $\displaystyle \mu_{grad} \gets \frac{\sum temp}{NHW}$
    \label{alg:compute-gradient-FF:mu-grad}

    \STATE $\displaystyle \bar{\Tilde{u}} \gets \Tilde{u}[\,c^{(\ell)}] \;-\; \mu\bigl[c^{(\ell)}\bigr]$
    \label{alg:compute-gradient-FF:a-bar}
    \COMMENT{// shape [N, H, W]}

    \STATE 
      $\displaystyle 
      \Sigma_{term} 
      \gets 
      \frac{\mathrm{mean}\Bigl(\frac{\partial L^{(\ell)}}{\partial u^{(\ell)}[\,c^{(\ell)}]} *\bar{\Tilde{u}}\Bigr)}
           {\sigma^2\bigl[c^{(\ell)}\bigr]}
      $
    \label{alg:compute-gradient-FF:Sigma-term}
    \STATE 
      $\displaystyle 
      \frac{\partial L^{(\ell)}}{\partial a^{(\ell)}}[\,c^{(\ell)}] 
      \gets 
      \frac{\gamma[c^{(\ell)}\bigr]}{\sqrt{\sigma^2\bigl[c^{(\ell)}\bigr]}} 
      \;\cdot\; 
      \Bigl( 
        temp \;-\; \mu_{grad} 
        \;-\; \bar{\Tilde{u}} * \Sigma_{term} 
      \Bigr)
      $
    \label{alg:compute-gradient-FF:dL-da-update}
    \STATE \textbf{readFromMainMemory}$\bigl(\Delta^{(\ell)}[\,c^{(\ell)}]\bigr)$
    \label{alg:compute-gradient-FF:read-Delta-l}

    \STATE 
      $\displaystyle 
      \frac{\partial L^{(\ell)}}{\partial z}[\,c^{(\ell)}] 
      \gets 
      \frac{\partial L^{(\ell)}}{\partial a^{(\ell)}}[\,c^{(\ell)}] 
      \;\cdot\; 
      \Delta^{(\ell)}[\,c^{(\ell)}]
      $
    \label{alg:compute-gradient-FF:dL-dz}
    \COMMENT{// 0 multiplications}


    \FOR{$c^{(\ell-1)} \gets 1$ to $C^{(\ell-1)}$}
    \label{alg:compute-gradient-FF:loop-c-l-1}

        \STATE \textbf{readFromMainMemory}$\bigl(u^{(\ell-1)}[\,c^{(\ell-1)}]\bigr)$
        \label{alg:compute-gradient-FF:read-tilde-u-l-1}

        \STATE           
          $\frac{\partial L^{\ell}}{\partial W}[c^{(\ell)},c^{(\ell-1)}] \gets Conv\Bigl(u^{(\ell-1)}[c^{(\ell-1)}],\frac{\partial L^{\ell}}{\partial z}[\,c^{(\ell)}]\Bigr)
          $ \label{alg:compute-gradient-FF:compute-dL_dW}

    \ENDFOR
    \label{alg:compute-gradient-FF:end-loop-c-l-1}

  \ENDFOR
  \label{alg:compute-gradient-FF:end-loop-c-l}

  \STATE 
    \textbf{return} 
    $\displaystyle \frac{\partial L^{(\ell)}}{\partial W^{(\ell)}}$
  \label{alg:compute-gradient-FF:return-partial-LW}

  \end{algorithmic}
\end{algorithm}

\begin{itemize}
%\begin{minipage}[t]{0.48\textwidth}
\item \textbf{Total number of Multiplications (per layer)}
\begin{align*}
= &  
     \underbrace{NC^{(\ell)}H^{(\ell)}W^{(\ell)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:dL-du}}} \\
  & \quad + \; \underbrace{NC^{(\ell)}H^{(\ell)}W^{(\ell)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:Sigma-term}}}
    + \underbrace{NC^{(\ell)}H^{(\ell)}W^{(\ell)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:dL-da-update}}}
 \\
& + \; \underbrace{NC^{(\ell)}C^{(\ell-1)}K^2H^{(\ell)}W^{(\ell)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:compute-dL_dW}}}
\end{align*}
%\end{minipage}
\hfill
%\begin{minipage}[t]{0.48\textwidth}
\item \textbf{Total Number of Memory Accesses (per layer)}
\begin{align*}
=\, &  \underbrace{NC^{(\ell)}H^{(\ell)}W^{(\ell)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:read-tilde-u-n}}} \\
&+   \underbrace{NC^{(\ell)}H^{(\ell)}W^{(\ell)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:read-Delta-l}}}
+  \underbrace{NC^{(\ell)}C^{(\ell-1)}H^{(\ell-1)}W^{(\ell-1)}}_{\text{Algo \ref{alg:compute-gradient-FF}},\text{Line~\ref{alg:compute-gradient-FF:read-tilde-u-l-1}}}
\end{align*}
