\subsection{\textbf{Forward Forward Algorithm (BSN): Number of Multiplications and Memory Accesses}}

\subsubsection{Forward Pass (layer $\ell$)}

% ------------------------------------------------------------------------
% Equations for the forward pass (substitute ReLU for your activation)
% ------------------------------------------------------------------------

\begin{align}
z^{(\ell)}[c] \;&=\; w^{(\ell)}[c,\cdot] \;\ast\; u^{(\ell-1)}[\cdot]
\label{eq:FF_conv_BSN_new}\\[6pt]
p^{(\ell)}[c,i] \;&=\; \sigma\!\Bigl(z^{(\ell)}[c,i]\Bigr)
\label{eq:FF_sigmoid_BSN_new}\\[6pt]
a^{(\ell)}[c,i] \;&\sim\; \mathrm{Bernoulli}\Bigl(p^{(\ell)}[c,i]\Bigr)
\quad\forall\,c,\,i
\label{eq:FF_activation_BSN_new}\\[6pt]
\tilde{u}^{(\ell)}[c] \;&=\; \mathrm{max\_pool}\bigl(a^{(\ell)}[c]\bigr)
\label{eq:FF_Maxpool_BSN_new}\\[6pt]
u^{(\ell)}[c] \;&=\; \mathrm{BN}\Bigl(\tilde{u}^{(\ell)}[c]\Bigr)
\label{eq:FF_BatchNorm_BSN_new}
\end{align}

Because the BSN activation outputs are in the set $\{0,1\}$
\[
u^{(\ell)}[c] \;\in\; \Bigl\{
   \tfrac{-\,\mu[c]}{\sqrt{\sigma^2[c]}}, \;
   \tfrac{1 - \mu[c]}{\sqrt{\sigma^2[c]}}
\Bigr\},
\]
each channel \(c\) of \(u^{(\ell)}\) can be written using two constants \(\alpha^{(\ell)}[c]\) and \(\delta^{(\ell)}[c]\), namely:

\[
u^{(\ell)}[c] 
\;=\; 
\alpha^{(\ell)}[c]\,\tilde{u}^{(\ell)}[c] 
\;+\;
\delta^{(\ell)}[c],
\]
where
\[
\alpha^{(\ell)}[c] 
\;=\; 
\frac{1}{\sqrt{\bigl(\sigma^{(\ell)}[c]\bigr)^2}}
\quad\text{and}\quad
\delta^{(\ell)}[c]
\;=\; 
\frac{-\,\mu^{(\ell)}[c]}{\sqrt{\bigl(\sigma^{(\ell)}[c]\bigr)^2}}.
\]

Rewriting the pre-activation \(z^{(\ell)}[c]\) to highlight these terms:

\begin{equation}
\begin{split}    
z^{(\ell)}[c] 
&=
\sum_{c^{(\ell-1)}=1}^{C^{(\ell-1)}} 
\Bigl(
  w^{(\ell)}[c,\,c^{(\ell-1)}] \,\alpha^{(\ell-1)}[c^{(\ell-1)}]\\
  &\ast
  u^{(\ell-1)}[c^{(\ell-1)}]
  \;+\;
  w^{(\ell)}[c,\,c^{(\ell-1)}] \,\delta^{(\ell-1)}[c^{(\ell-1)}]
\Bigr).
\label{eqn:preactivation_rewrite_new}
\end{split}
\end{equation}

This equation shows in practice we do not need to calculate BatchNorm; we can just calculate these constants and store them in local memory.
Whenever we need the BatchNorm output, we simply multiply with the Maxpool output first, which is a binary tensor.
Per channel, this amounts to $2K^2$ multiplications, where $K \times K$ is the kernel size.\\

\subsubsection*{\textbf{M-\emph{tiled} units}} \label{ss:M-tiled-units}
If we use \(M\) \emph{tiled} units instead of binary units, then the batch‑normalized outputs take values
\begin{align*}
u^{(\ell)}[c] &\;\in\;\Bigl\{\tfrac{i - \mu[c]}{\sqrt{\sigma^2[c]}}
  \;\Big|\; i = 0,1,\dots,M\Bigr\},
\end{align*}
where \(i\) is an integer representable in \(\log_2 M\) bits.  Therefore,
\begin{align*}
w[c]\,\frac{i - \mu[c]}{\sqrt{\sigma^2[c]}}
  &= i\,\frac{w[c]}{\sqrt{\sigma^2[c]}}
    \;-\;\mu[c]\,\frac{w[c]}{\sqrt{\sigma^2[c]}}.
\end{align*}
Naïvely, this adds \(M K^2\) extra multiplications per input–output channel kernel of size \(K\times K\), but since energy and area scale roughly with the square of operand bit‑width, a multiply between the 32‑bit constant \(\tfrac{w[c]}{\sqrt{\sigma^2[c]}}\) and the \(\log_2 M\)-bit integer \(i\) uses far fewer gates and switching activity than a full \(32\times32\)-bit multiply—making the \(M K^2\) extra operations negligible compared to the usual \(2K^2\) full‑width multiplies per channel for smaller values of $M$.


