% Single-pass algorithm that immediately updates weights
% ------------------------------------------------------------------------

\begin{algorithm}[]
  \caption{ForwardForwardOneLayer (BSN)}
  \label{alg:forward-forward-layer-BSN}
  \begin{algorithmic}[1]

  \item[\algorithmicrequire] 
    Layer index $\ell$, batch size $N$
    \quad
    \label{alg:forward-forward-layer-BSN:requires}

  \item[\algorithmicensure] 
    Updated weights $W^{(\ell)}$ and batch-normalized outputs $u^{(\ell)}$
    \quad
    \label{alg:forward-forward-layer-BSN:ensures}

  % ---------------- FIRST PASS ----------------
  \COMMENT{First Pass: Accumulate Mean \& Variance for BN}
  \label{alg:forward-forward-layer-BSN:accumulate-mean-variance}

  \STATE sum $\gets 0$, \quad sumSq $\gets 0$
  \label{alg:forward-forward-layer-BSN:init-sums}

  \STATE \textbf{readFromMainMemory}$(W^{(\ell)})$
  \label{alg:forward-forward-layer-BSN:read-weights}

  \FOR{$n \gets 1$ to $N$}
  \label{alg:forward-forward-layer-BSN:loop-n}

    \IF{$\ell = 1$}
    \label{alg:forward-forward-layer-BSN:if-first-layer}

        \STATE \textbf{readFromMainMemory}$(\textit{input}_n)$
        \label{alg:forward-forward-layer-BSN:read-input}

        \STATE $z_n^{(\ell)} \gets \mathrm{Conv}\bigl(W^{(\ell)},\,\textit{input}_n\bigr)$
        \label{alg:forward-forward-layer-BSN:conv-first-layer}
        \COMMENT{Real conv if first layer, $C[\ell-1]C[\ell]HWK^2$ multiplications}

    \ELSE
    \label{alg:forward-forward-layer-BSN:else-higher-layer}

        \STATE \textbf{readFromMainMemory}$\bigl(u_n^{(\ell-1)}\bigr)$
        \label{alg:forward-forward-layer-BSN:read-prev-activ}

        \STATE $z_n^{(\ell)} \gets \sum_{\,c^{(\ell-1)}\,}
          \Bigl(
              \alpha^{(\ell)}\bigl[c^{(\ell-1)}\bigr] \cdot w^{(\ell)}\bigl[c^{(\ell-1)}\bigr]\,                      
              *\, u_n^{(\ell-1)}\bigl[c^{(\ell-1)}\bigr]
              \;+\;
              w^{(\ell)}\bigl[c^{(\ell-1)}\bigr]\,
              \delta^{(\ell)}\bigl[c^{(\ell-1)}\bigr]
          \Bigr)$
        \label{alg:forward-forward-layer-BSN:conv-binary}
        \COMMENT{Binary conv (since $u^{(\ell-1)}\in\{0,1\}$), $2K^2C[\ell-1]C[\ell]$ multiplications}

    \ENDIF

    \STATE $a_n^{(\ell)} \gets \mathrm{BSN}\bigl(z_n^{(\ell)}\bigr)$
    \quad \textbf{writeToMainMemory} $\bigl(\Delta_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer-BSN:bsn-forward}
    \COMMENT{Storing BSFF gradient instead of $a^{(\ell)}$}

    \STATE $\tilde{u}_n^{(\ell)} \gets \mathrm{Maxpool}\bigl(a_n^{(\ell)}\bigr)$
    \quad \textbf{writeToMainMemory}$\bigl(\tilde{u}_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer-BSN:maxpool}

    \STATE sum   $\gets$ sum + \text{elementwiseSum}$\bigl(\tilde{u}_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer-BSN:update-sum}

    \STATE sumSq $\gets$ sumSq + \text{elementwiseSumOfSquares}$\bigl(\tilde{u}_n^{(\ell)}\bigr)$
    \label{alg:forward-forward-layer-BSN:update-sumsq}

  \ENDFOR

  \STATE $\mu^{(\ell)} \gets \dfrac{\text{sum}}{\textit{totalElements}}$
  \label{alg:forward-forward-layer-BSN:compute-mean}

  \STATE $\bigl(\sigma^{(\ell)}\bigr)^2 
         \gets \dfrac{\text{sumSq}}{\textit{totalElements}}
         \;-\;\bigl(\mu^{(\ell)}\bigr)^2$
  \label{alg:forward-forward-layer-BSN:compute-variance}

  \STATE \COMMENT{No need to calculate explicit BN}
  \label{alg:forward-forward-layer-BSN:no-explicit-bn}

  \STATE \COMMENT{Local Gradient Computation \& Weight Update}
  \label{alg:forward-forward-layer-BSN:local-grad-update}

  \IF{$\ell = 1$}
  \label{alg:forward-forward-layer-BSN:if-compute-grad-first}

    \STATE 
    $\dfrac{\partial L^{(\ell)}}{\partial W^{(\ell)}} 
            \gets \textbf{ComputeGradient}\bigl(\tilde{u}^{(\ell)},\,\Delta^{(\ell)},\,\textit{input}\bigr)$  
    \label{alg:forward-forward-layer-BSN:compute-gradient-first}

  \ELSE
  \label{alg:forward-forward-layer-BSN:else-compute-grad-higher}

    \STATE 
    $\dfrac{\partial L^{(\ell)}}{\partial W^{(\ell)}} 
            \gets \textbf{ComputeGradient}\bigl(\tilde{u}^{(\ell)},\,\Delta^{(\ell)},\,u^{(\ell-1)}\bigr)$  
    \label{alg:forward-forward-layer-BSN:compute-gradient-higher}

  \ENDIF

  \STATE 
  $W^{(\ell)} \gets W^{(\ell)} 
    \;-\; \eta \cdot
          \dfrac{\partial L^{(\ell)}}{\partial W^{(\ell)}}$
  \label{alg:forward-forward-layer-BSN:update-weights}

  \STATE $\textbf{writeToMainMemory}\bigl(W^{(\ell)}\bigr)$
  \label{alg:forward-forward-layer-BSN:write-weights}

  \end{algorithmic}
\end{algorithm}




