 \item \textbf{Total Number of Multiplications}
\vspace{-0.5em}
\begin{align*}
\text{MulCount} 
=\;& 
\underbrace{
  \begin{cases}
    N\, C^{(\ell-1)}C^{(\ell)}K^2H^{(\ell-1)}W^{(\ell-1)} 
      & \text{if } \ell=1 \\
    N\, \cdot 2\,C^{(\ell-1)}C^{(\ell)}K^2      
      & \text{if } \ell>1
  \end{cases}
}_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}},\text{Conv operation at} \\ \text{Line~\ref{alg:forward-forward-layer-BSN:conv-first-layer} (}\ell=1\text{) or}\\ \text{Line~\ref{alg:forward-forward-layer-BSN:conv-binary} (}\ell>1\text{)}}} \\[8pt]
& + \; \underbrace{
  \text{[Gradient Computations at Line~\ref{alg:forward-forward-layer-BSN:compute-gradient-first} or \ref{alg:forward-forward-layer-BSN:compute-gradient-higher}]}
}_{\text{Counted separately}}
\end{align*}
  \item \textbf{Total number of memory accesses}
  \vspace{-0.5em}
  \begin{align*}
  \text{MemAccess}
  =\;& 
  \underbrace{
    \sum_{\ell=2} (N C^{(\ell-1)}H^{(\ell-1)}W^{(\ell-1)})/32
  }_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}},\text{read }u^{(\ell-1)}\text{ at line \ref{alg:forward-forward-layer-BSN:read-prev-activ}}\\(\ell>1\text{ case})}}\\
  &+\underbrace{
     (N C^{(\ell-1)}H^{(\ell-1)}W^{(\ell-1)})
  }_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}},\text{read }u^{(\ell-1)}\text{ at line \ref{alg:forward-forward-layer-BSN:read-input}}\\(\ell=1\text{ case})}}\\&+ \underbrace{
    \sum_{\ell}C^{(\ell-1)}C^{(\ell)}K^2
  }_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}}, \text{read }W^{(\ell)}\text{ at line \ref{alg:forward-forward-layer-BSN:read-weights}}\\(\text{weights per layer})}}
  \\
  &+ \underbrace{
   \sum_{\ell} (N C^{(\ell)}H^{(\ell)}W^{(\ell)})
  }_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}}, \text{store }\Delta^{(\ell)}\text{ at line \ref{alg:forward-forward-layer-BSN:bsn-forward}}}}\\
  &+ \underbrace{
   \sum_{\ell} ( N C^{(\ell)}H^{(\ell)}W^{(\ell)})/32
  }_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}}, \text{store Maxpool output}\text{ at line \ref{alg:forward-forward-layer-BSN:maxpool}})}}\\
  &+ \underbrace{
    \sum_{\ell} C^{(\ell-1)}C^{(\ell)}K^2
  }_{\substack{\text{Algo \ref{alg:forward-forward-layer-BSN}}, \text{write updated }W^{(\ell)}\text{ at line \ref{alg:forward-forward-layer-BSN:write-weights}}}}
  \end{align*}
 \end{itemize}



\begin{algorithm}[]
  \caption{ComputeGradient Subroutine for BSN Network}
  \label{alg:compute-gradient-BSN}
  \begin{algorithmic}[1]

  \item[\algorithmicrequire] 
    Batchnorm Input $\Tilde{u}^{(\ell)}$, BSFF gradient $\Delta^{(\ell)}$, Previous layer batchnorm input $\Tilde{u}^{(\ell-1)}$.
    \label{alg:compute-gradient-BSN:requires}

  \item[\algorithmicensure] 
    $\displaystyle \frac{\partial L^{(\ell)}}{\partial W^{(\ell)}}$
    \label{alg:compute-gradient-BSN:ensures}

  \STATE $\displaystyle \frac{\partial L^{(\ell)}}{\partial W^{(\ell)}} \gets 0$
  \label{alg:compute-gradient-BSN:init-partial-LW}


  \FOR{$c^{(\ell)} \gets 1$ to $C^{(\ell)}$}
  \label{alg:compute-gradient-BSN:loop-c-l}

    \STATE \textbf{readFromMainMemory}$\bigl(\Tilde{u}^{(\ell)}\bigr)$
    \label{alg:compute-gradient-BSN:read-tilde-u-n}

    \STATE $\text{group index}:j \gets \frac{c^{(\ell)}}{N_{classes}}$

      \STATE  
        $\displaystyle 
        \frac{\partial G_j}{\partial u^{(\ell)}[c^{(\ell)}]} 
        \gets 
        \frac{2}{|N_j|} 
        \Bigl(\alpha^{(\ell)}\,\Tilde{u}^{(\ell)}[c^{(\ell)}] 
              + 
              \delta^{(\ell)}\Bigr)$
      \label{alg:compute-gradient-BSN:dG-da}

      \STATE  
        $\displaystyle 
        \frac{\partial L^{(\ell)}}{\partial u^{(\ell)}[c^{(\ell)}]} 
        \gets  
        \frac{\partial G_j}{\partial u[c^{(\ell)}]} 
        \;\ast\; 
        \frac{\partial L^{(\ell)}}{\partial G_{j}}
        $
      \label{alg:compute-gradient-BSN:dL-da}
      \COMMENT{// $\sim 0$ multiplications as $\tilde{u} \in \{0,1\}$ and $\alpha$ can be taken outside per channel}

    \STATE $\displaystyle temp \gets \frac{\partial L^{(\ell)}}{\partial u^{(\ell)}[\,c^{(\ell)}]}$
    \label{alg:compute-gradient-BSN:temp-def}
    \COMMENT{// shape [N, H, W]}

    \STATE $\displaystyle \mu_{grad} \gets \frac{\sum temp}{NHW}$
    \label{alg:compute-gradient-BSN:mu-grad}

    \STATE $\displaystyle \bar{\Tilde{u}} \gets \Tilde{u}[\,c^{(\ell)}] \;-\; \mu\bigl[c^{(\ell)}\bigr]$
    \label{alg:compute-gradient-BSN:a-bar}
    \COMMENT{// shape [N, H, W]}

    \STATE 
      $\displaystyle 
      \Sigma_{term} 
      \gets 
      \frac{\mathrm{mean}\Bigl(\frac{\partial L^{(\ell)}}{\partial u^{(\ell)}[\,c^{(\ell)}]} * \bar{\Tilde{u}}\Bigr)}
           {\sigma^2\bigl[c^{(\ell)}\bigr]}
      $
    \label{alg:compute-gradient-BSN:Sigma-term}
    \COMMENT{// $\sim 0$  multiplications}

    \STATE 
      $\displaystyle 
      \frac{\partial L^{(\ell)}}{\partial a^{(\ell)}}[\,c^{(\ell)}] 
      \gets 
      \frac{\gamma[c^{(\ell)}\bigr]}{\sqrt{\sigma^2\bigl[c^{(\ell)}\bigr]}} 
      \;\cdot\; 
      \Bigl( 
        temp \;-\; \mu_{grad} 
        \;-\; \bar{\Tilde{u}} * \Sigma_{term} 
      \Bigr)
      $
    \label{alg:compute-gradient-BSN:dL-da-update}
    \COMMENT{// $\sim 0$  multiplications}

    \STATE \textbf{readFromMainMemory}$\bigl(\Delta^{(\ell)}[\,c^{(\ell)}]\bigr)$
    \label{alg:compute-gradient-BSN:read-Delta-l}

    \STATE 
      $\displaystyle 
      \frac{\partial L^{(\ell)}}{\partial z}[\,c^{(\ell)}] 
      \gets 
      \frac{\partial L^{(\ell)}}{\partial a^{(\ell)}}[\,c^{(\ell)}] 
      \;\cdot\; 
      \Delta^{(\ell)}[\,c^{(\ell)}]
      $
    \label{alg:compute-gradient-BSN:dL-dz}
    \COMMENT{// NHW multiplications}


    \FOR{$c^{(\ell-1)} \gets 1$ to $C^{(\ell-1)}$}
    \label{alg:compute-gradient-BSN:loop-c-l-1}

      \IF{$\ell = 1$}
      \label{alg:compute-gradient-BSN:if-first-layer}

        \STATE \textbf{readFromMainMemory}$\bigl(\textit{input}[\,c^{(\ell-1)}]\bigr)$
        \label{alg:compute-gradient-BSN:read-input-c-l-1}
        \STATE           
          $\frac{\partial L^{\ell}}{\partial W}[c^{(\ell)},c^{(\ell-1)}]\gets Conv\Bigl({input}[c^{(\ell-1)}],\frac{\partial L^{\ell}}{\partial z}[\,c^{(\ell)}]\Bigr)
          $ \label{alg:compute-gradient-BSN:compute-dL_dW_1}
      \ELSE
      \label{alg:compute-gradient-BSN:else-higher-layer}

        \STATE \textbf{readFromMainMemory}$\bigl(\Tilde{u}^{(\ell-1)}[\,c^{(\ell-1)}]\bigr)$
        \label{alg:compute-gradient-BSN:read-tilde-u-l-1}
        \STATE           
          $\frac{\partial L^{\ell}}{\partial W}[c^{(\ell)},c^{(\ell-1)}] \gets Conv\Bigl(\alpha\bigl[c^{(\ell-1)}\bigr] \tilde{u}^{\ell-1}[c^{\ell-1}+\delta\bigl[c^{(\ell-1)}\bigr] ],\frac{\partial L^{\ell}}{\partial z}[\,c^{(\ell)}]\Bigr)
          $ \label{alg:compute-gradient-BSN:compute-dL_dW}        

      \ENDIF


    \ENDFOR
    \label{alg:compute-gradient-BSN:end-loop-c-l-1}

  \ENDFOR
  \label{alg:compute-gradient-BSN:end-loop-c-l}

  \STATE 
    \textbf{return} 
    $\displaystyle \frac{\partial L^{(\ell)}}{\partial W^{(\ell)}}$
  \label{alg:compute-gradient-BSN:return-partial-LW}

  \end{algorithmic}
\end{algorithm}





