Let $I=P_{F_1}\cap\dots\cap P_{F_m}$ be the minimal primary decomposition of a squarefree monomial ideal $I\subset S$. We say that $I$ is \textit{normally torsionfree} if $\Ass(I^k)\subseteq\Ass(I)$ for all $k\ge1$. The $k$th \textit{symbolic power} of $I$ is the monomial ideal defined as
\[
I^{(k)}\ = P_{F_1}^k\cap\dots\cap P_{F_m}^k.
\]

We have $I^k\subseteq I^{(k)}$ for all $k\ge1$. By \cite[Theorem 1.4.6]{JT}, the equality $I^{(k)}=I^k$ holds for all $k\ge1$ if and only if $I$ is normally torsionfree.\smallskip

The goal of this last section is to prove the following characterization.

\begin{Theorem}\label{Thm:Bt(u)SP}
	Let $I=B_{\bf t}(u)$. The following statements are equivalent.
	\begin{enumerate}
		\item[\textup{(a)}] $I$ is normally torsionfree.
		\item[\textup{(b)}] $I^{(k)}=I^k$, for all integers $k\ge1$.
		\item[\textup{(c)}] $j_{i}\le \sum_{s=1}^i t_s$ for all $i=1,\dots,d-1$.
	\end{enumerate}
\end{Theorem}

The proof of this theorem requires some preparation. Let $I\subset S$ be a monomial ideal and let ${\bf a}=(a_1,\dots,a_n)\in\ZZ_{\ge0}^n$. The ${\bf a}$\textit{-restriction} of $I$ is defined as the monomial ideal $I^{\le{\bf a}}\subset S$ with minimal generating set 
\[
G(I^{\le{\bf a}})=\{x_1^{b_1}\cdots x_n^{b_n}\in G(I):\ b_i\le a_i\ \textup{for all}\ i\}.
\]

We recall the following result proved in \cite[Theorem 3.7]{SNQ}. Let ${\bf e}_i\in\ZZ_{\ge0}^n$ be the vector with $i$th component equal to 1 and with the other components equal to zero, and set ${\bf 1}={\bf e}_1+\dots+{\bf e}_n=(1,\dots,1)\in\ZZ_{\ge0}^n$.
\begin{Theorem}\label{Thm:useful}
	Let $I\subset S$ be a squarefree monomial ideal. Suppose there exists a squarefree monomial $v\in S$ such that $v\in P\setminus P^2$ for all $P\in\Ass(I)$, and  $P_{[n]\setminus\{i\}}\notin\Ass((I^{\le{\bf 1}-{\bf e}_i})^k)$ for all $k\ge1$ and all $i\in\supp(v)$. Then $I^{(k)}=I^k$ for all $k\ge1$.
\end{Theorem}

The following lemma will be needed later.
\begin{Lemma}\label{Lem:FM}
	Let $J\subset S$ be a monomial ideal, let $u\in S$ be a monomial and set $I=uJ$. Then, $I^{(k)}=I^k$ for all $k\ge1$, if and only if, $J^{(k)}=J^k$ for all $k\ge1$
\end{Lemma}
\begin{proof}
	It is shown in \cite[Proposition 6.3]{FM} that $I^{(k)}=u^kJ^{(k)}$ for all $k\ge1$. The assertion now follows at once.
\end{proof}

Let $I\subset S$ be a graded ideal and let $\mathcal{R}(I)=\bigoplus_{k\ge0}I^kt^k$ be its Rees algebra. The \textit{analytic spread} of $I$, denoted by $\ell(I)$, is defined as the Krull dimension of the ring $\mathcal{R}(I)/\m\mathcal{R}(I)=\bigoplus_{k\ge0}(I^k/\m I^k)t^k$, where $\m=(x_1,\dots,x_n)$.
\begin{Proposition}\label{Prop:useful}
	Let $I\subset S$ be a graded ideal such that $\mathcal{R}(I)$ is Cohen-Macaulay. Suppose that $\ell(I)<n$. Then $\m=(x_1,\dots,x_n)\notin\Ass(I^k)$ for all $k\gg0$.
\end{Proposition}
\begin{proof}
	By \cite[Proposition 10.3.2]{JT}, $\lim_{k\rightarrow\infty}\depth\,S/I^k=n-\ell(I)$. Our assumption implies that $\depth\,S/I^k>0$ for all $k\gg0$. Hence $\m\notin\Ass(I^k)$ for all $k\gg0$.
\end{proof}
\begin{Corollary}\label{Cor:useful}
	Let $I=B_{\bf t}(u)\subset S$ be a squarefree principal vector-spread Borel ideal. If $\ell(I)<n$ then $\m\notin\Ass(I^k)$ for all $k\ge1$.
\end{Corollary}
\begin{proof}
	By \cite[Proposition 1]{CF2024}, $I$ is vertex splittable. By \cite[Theorem 3.1(a)-(b)]{M2023} it follows that $\mathcal{R}(I)$ is Cohen-Macaulay and $\Ass(I)\subseteq\Ass(I^2)\subseteq\Ass(I^3)\subseteq\cdots$. Proposition \ref{Prop:useful} and our assumption imply that $\m\notin\Ass(I^k)$ for all $k\gg0$. The previous ascending chain of inclusions yields that $\m\notin\Ass(I^k)$ for all $k\ge1$.
\end{proof}

Let $I\subset S$ be a monomial ideal with $G(I)=\{u_1,\dots,u_m\}$. The \textit{linear relation graph} $\Gamma$ of $I$ is defined as the graph with the edge set 
\[
E(\Gamma)\ =\ \{\{i,j\}: \text{there exist $u_k,u_\ell\in G(I)$ such that $x_iu_k=x_ju_\ell$}\},
\]
and with the vertex set $V(\Gamma)=\bigcup_{\{i,j\}\in E(\Gamma)}\{i,j\}$.

If $I\subset S$ is a monomial ideal generated in degree $d$ having linear relations (e.g. $I$ has linear resolution) then \cite[Lemma 5.2]{DHQ} guarantees that
\begin{equation}\label{eq:ell}
	\ell(I)=r-s+1
\end{equation}
where $r$ is the number of vertices and $s$ is the number of connected components of the linear relation graph of $I$.

Let $I=B_{\bf t}(u)$ as in the Setup \ref{setup}, and define the sets
\[B_r\ =\ \big[\sum_{s=1}^{r-1}t_s+1,\,j_r\big], \quad r=1,\dots,d.\]

Notice that $v=x_{i_1}\cdots x_{i_d} \in G(I)$ if and and only if $i_r\in B_r$, for all $r=1, \ldots, d$, and $i_r - i_{r-1}\ge t_r$ for all $r=2,\dots,d$.

