\begin{Proposition}\label{Prop:Gamma}
	Let $I=B_{\bf t}(u)$ and %set 
	$B_i=[\sum_{s=1}^{i-1}t_s+1,j_i]$ for $i=1,\dots,d$. Let $\Gamma$ be the linear relation graph of $I$. The following statements hold.
	\begin{enumerate}
		\item[\textup{(a)}] We have $|B_i|\ge2$ if and only if $B_i\subseteq V(\Gamma)$. 
		%If $|B_i|\ge2$, then the induced subgraph of $\Gamma$ on $B_i$ is a complete graph.
		\item[\textup{(b)}] Suppose that $j_i\le\sum_{s=1}^it_s$ for all $i=1,\dots,d-1$. Then $B_p\cap B_q=\emptyset$ for all $1\le p<q\le d$ and $\m\notin\Ass(I^k)$ for all $k\ge1$.
	\end{enumerate}
\end{Proposition}
\begin{proof}
	(a) Suppose that $B_i\subseteq V(\Gamma)$ and assume for a contradiction that $|B_i|=1$, for some $i$. Then $j_i=(\sum_{s=1}^{i-1}t_s)+1$. It follows that each generator of $B_{\bf t}(u)$ is a multiple of $x_{j_i}$ and this implies that $B_i=\{j_i\}\not\subseteq V(\Gamma)$, a contradiction.

	Conversely, suppose that $|B_i|\ge2$. We claim  that if $|B_i|\ge2$, then the induced subgraph of $\Gamma$ on $B_i$ is a complete graph. This implies that $B_i\subseteq V(\Gamma)$. 

	Let $h_1,h_2\in B_i$ with $h_1<h_2\le j_i$. If $i=1$, then $x_{h_1}(u/x_{j_1}),x_{h_2}(u/x_{j_1})\in G(I)$ since $I$ is ${\bf t}$-spread. Hence $\{h_1,h_2\}\in E(\Gamma)$. If $i=d$, then $vx_{h_1},vx_{h_2}\in G(I)$ where $v=x_1x_{1+t_1}\cdots x_{1+t_1+\dots+t_{d-2}}$. Hence $\{h_1,h_2\}\in E(\Gamma)$. Finally, let $1<i<d$. Then $\sum_{s=1}^{i-1}t_s+1\le h_1<h_2\le j_i$. We have $wx_{h_1},wx_{h_2}\in G(I)$ where $w=x_{j_d}(v/x_{1+t_1+\dots+t_{i-1}})$. Hence $\{h_1,h_2\}\in E(\Gamma)$ as desired.\smallskip

	(b) Suppose for a contradiction that $B_p\cap B_q\ne\emptyset$ for some $1\le p<q\le d$. Then $j_p\ge\sum_{s=1}^{q-1}t_s+1>\sum_{s=1}^{p}t_s$. Since by assumption we have $j_p\le\sum_{s=1}^pt_s$, we reach the desired contradiction.

	Next, we claim that $\Gamma$ does not contain any edge with one endpoint in $B_p$ and the other endpoint in $B_q$ for some $1\le p<q\le d$. If $|B_p|=1$ or $|B_q|=1$, then (a) implies the assertion. Now, let $|B_p|\ge2$ and $|B_q|\ge2$. Recall that $B_p\cap B_q=\emptyset$ for all $1\le p<q\le d$. Take $h_1\in B_p$ and $h_2\in B_q$ for some $1\le p,q\le d$ with $p\ne q$. Then for any $v\in G(I)$ with $x_{h_1}$ dividing $v$, we have $x_{h_2}(v/x_{h_1})\notin G(I)$.  Indeed, $v$ is not ${\bf t}$-spread because the support of this monomial contains two distinct elements from $B_q$. This yields the assertion.

	Now, if $I=(x_1x_{1+t_1}\cdots x_{1+t_1+\dots+t_{d-1}})$ is a principal ideal, there is nothing to prove. Suppose that $I$ is not principal. By Corollary \ref{Cor:useful} it is enough to show that $\ell(I)<n$. By \cite[Corollary 5.3(c)]{F1}, $I$ has linear resolution. Hence, formula \eqref{eq:ell} holds. So it is enough to prove that the linear relation graph $\Gamma$ of $I$ has more than one connected component. Since $I$ is not principal, we have $j_i>(\sum_{s=1}^{i-1}t_s)+1$ for some $i$. Hence $|B_i|\ge2$ for some $i$. By part (a) and the previous claim, it follows that $\Gamma$ is the disjoint union of the complete graphs on the vertex sets $B_i$ for which $|B_i|\ge2$. Hence $\Gamma$ has only one connected component if and only if $|B_d|\geq 2$ and $|B_i|=1$, for all $i=1, \ldots, d-1$. In this case, $\ell(I)=|B_d|<n$. Otherwise, $\Gamma$ has at least two connected components and we have again $\ell(I)<n$, as desired.
\end{proof}

Let $I\subset S$ be a monomial ideal and $P\subset S$ be a monomial prime ideal. The \textit{monomial localization} of $I$ with respect to $P$ is the monomial ideal of the polynomial ring $R=K[x_j:\,x_j\in P]$ defined as $I(P)=\varphi(I)$ where $\varphi:S\rightarrow R$ is the $R$-algebra homomorphism defined by setting $\varphi(x_j)=1$ for all $x_j\notin P$.\medskip

We are now ready to prove Theorem \ref{Thm:Bt(u)SP}.
\begin{proof}
	The equivalence between (a) and (b) follows from \cite[Theorem 1.4.6]{JT}.\smallskip

	(b) $\Rightarrow$ (c) Let $I=B_{\bf t}(u)$ and assume that $I^{(k)}=I^k$ for all $k\ge1$. If $d=2$ then the statement follows from \cite[Theorem 5.13]{NQKR}. Hence, we assume that $d\ge3$.

	Suppose by contradiction that (c) does not hold. Then, there is at least one index $1\le \ell\le d-1$ such that $j_\ell>\sum_{s=1}^\ell t_s$. Let $\ell$ be the smallest such integer. Let $v=x_{h_1}\cdots x_{h_d}\in G(I)$. Notice that for any $r=1,\dots,\ell-1$ we have
	\begin{equation}\label{eq:hr}
		h_r\in B_r\ \subseteq\ \big[\sum_{s=1}^{r-1}t_s+1,\,\sum_{s=1}^rt_s\big],
	\end{equation}
	and for $r=\ell,\dots,d$ we have $h_r\ge(\sum_{s=1}^{\ell-1}t_s)+1$.

	Let $Q=P_{[(\sum_{s=1}^{\ell-1}t_s)+1,n]}$ and $R=K[x_j:x_j\in Q]$. The inclusion \eqref{eq:hr} implies that $I(Q)=B_{\bf s}(v)\cap R$ where ${\bf s}=(t_{\ell},\dots,t_{d-1})$ and $v=u/(x_{j_1}\cdots x_{j_{\ell-1}})$. Hence $I(Q)$ is a ${\bf s}$-spread monomial ideal in the polynomial ring $R$ with $\min(v)=j_\ell\ge 1+\sum_{s=1}^{\ell}t_s$. Moreover, $I(Q)^{(k)}=I(Q)^k$ for all $k\ge1$. Therefore, this reduction shows that we may assume from the very beginning that $\ell=1$ and that $\min(u)=j_1\ge t_1+1$.

	To finish the proof, we will show that $I^{(2)}\ne I^2$, reaching the desired contradiction. To this end, we claim that
	\[
	w=(x_1\cdots x_{t_1}x_{t_1+1})(x_{j_2}\cdots x_{j_d})\in I^{(2)}\setminus I^2.
	\] 

	Firstly, let us show that $w\in I^{(2)}$. Since $I^{(2)}=\bigcap_{P\in\Ass(I)}P^2$, we must prove that $w\in P^2$ for all $P\in\Ass(I)$.

	Let $P\in\Ass(I)$. By Theorem \ref{thm:PrimDecom}, either $P=P_{[n]\setminus\supp_{{\bf t}}(v)}$ for some $v\in G(I)$ or $P=P_{[n]\setminus G}$ for some $G\in\mathcal{G}$, where $\mathcal{G}$ is defined in the statement of Theorem \ref{thm:PrimDecom}.

	Suppose $P=P_{[n]\setminus\supp_{{\bf t}}(v)}$. If $\min(v)\ge3$ then $x_1x_2\in P^2$ and so $w\in P^2$. If $\min(v)=2$, then $[2,t_1+1]\subseteq\supp_{\bf t}(v)$. Hence $x_1\in P$ but $x_{1+t_1}\notin P$. Since $x_{1+t_1}x_{j_2}\cdots x_{j_d}\in I\subset P$, $x_{1+t_1}\notin P$ and $P$ is a prime ideal, it follows that $x_{j_s}\in P$ for some $s=2,\dots,d$. Hence $x_1x_{j_s}\in P^2$ and so $w\in P^2$. Finally, if $\min(v)=1$, then $[1,t_1]\subseteq\supp_{\bf t}(v)$. Hence $x_{1+t_1}\in P$ but $x_{1}\notin P$. Since $x_{1}x_{j_2}\cdots x_{j_d}\in I\subset P$ it follows that $x_{j_s}\in P$ for some $s=2,\dots,d$. Hence $x_{1+t_1}x_{j_s}\in P^2$ and so $w\in P^2$.

	Suppose now $P=P_{[n]\setminus G}$ with $G\in\mathcal{G}$. Then $G=\supp_{\bf t}(x_{\ell_1}\cdots x_{\ell_{s-1}}x_{j_s})\cup[j_s+1,n]$ where $x_{\ell_1}x_{\ell_2}\cdots x_{\ell_{s-1}}x_{j_s}\in G(B_{\bf t}(x_{j_1}x_{j_2}\cdots x_{j_{s-1}}x_{j_s}))$, for some $s=1,\dots,d$. If $s=1$, then $x_1x_2\in P^2$ and so $w\in P^2$ too. Suppose $s>1$. Then $x_{j_s}\in P$. Moreover, applying the same reasoning as before on the integer $\ell_1$, it follows that $x_1x_2\in P^2$ or $x_1\in P$ or $x_{t_1+1}\in P$. In each possible case, we have $w\in P^2$, as desired.

	Hence $w\in I^{(2)}$. Suppose for a contradiction that $w\in I^2$. Then, there would exist squarefree monomials $v_1,v_2\in G(I)$, $g\in S$ such that
	\begin{equation}\label{eq:w}
		w\ = \ (x_1\cdots x_{t_1}x_{t_1+1})(x_{j_2}\cdots x_{j_d})\ =\ v_1v_2g.
	\end{equation}

	Write $v_1=x_{p_1}\cdots x_{p_d}$. Then $p_1\in[1,t_1+1]\cup\{j_2,\dots,j_d\}$. We claim that $p_1\in[1,t_1]$. Suppose, otherwise, that $p_1\in\{j_2,\dots,j_d\}$. Since $p_d>\dots>p_2>p_1$ it would follow from \eqref{eq:w} that $v_1$ divides $x_{j_2}\cdots x_{j_d}$. This is impossible because $v_1$ has degree $d$. Hence $p_1\in[1,t_1+1]$. Since $p_2\ge p_1+t_1$ it follows that $p_2\in\{j_2,\dots,j_d\}$. Therefore $x_{p_2}\cdots x_{p_d}=x_{j_2}\cdots x_{j_d}$. By equation \eqref{eq:w}, it then follows that
	\[
	x_1\cdots x_{p_1-1}x_{p_1+1}\cdots x_{t_1+1}\ =\ v_2g\in I.
	\]
	This is impossible, because $v_2$ is a ${\bf t}$-spread monomial of degree $d\ge3$.\smallskip

	(c) $\Rightarrow$ (a) By assumption we have $j_i\le\sum_{s=1}^i t_s$ for all $i=1,\dots,d-1$.
	Notice that $j_i\ge \sum_{r=1}^{i-1}t_r+1$ for all $r=1,\dots,d$. We may assume that $j_i> \sum_{r=1}^{i-1}t_r+1$ for all $i=1,\dots,d$. Indeed suppose that this is not the case and let $r$ be the biggest integer with this property. Then $B_{\bf t}(u)=(x_{j_1}\cdots x_{j_r})B_{{\bf s}}(v)$ where ${\bf s}=(t_{r+1},\dots,t_{d-1})$ and $v=u/(x_{j_1}\cdots x_{j_r})$, and where $B_{{\bf s}}(v)$ is a ${\bf s}$-spread ideal in the polynomial ring $K[x_{j_r+t_r},\dots,x_n]$ with fewer variables. Then, by Lemma \ref{Lem:FM}, $B_{\bf t}(u)$ is normally torsionfree if and only if $B_{\bf s}(v)$ is such.

	Hence we can assume that $j_i> \sum_{r=1}^{i-1}t_r+1$ for all $i=1,\dots,d$. To prove (a) we apply Theorem \ref{Thm:useful}. 

	Let $I=B_{\bf t}(u)$ and let $u=x_{j_1}\cdots x_{j_d}$ be the vector-spread Borel generator of $I$. Firstly, let us verify that $u\in P\setminus P^2$ for all $P\in\Ass(I)$. Since $I\subset P$ for all $P\in\Ass(I)$, we only need to verify that $u\notin P^2$ for all $P\in\Ass(I)$. This is equivalent to show that $|G(P)\cap\{x_{j_1},\dots,x_{j_d}\}|\le1$ for all $P\in\Ass(I)$.

	Let $P\in\Ass(I)$. By Theorem \ref{thm:PrimDecom}, either $P=P_{[n]\setminus\supp_{\bf t}(v)}$ for some $v\in G(I)$, or else $P=P_{[n]\setminus G}$ for some $G\in\mathcal{G}$. We distinguish the two cases.

	Suppose $P=P_{[n]\setminus\supp_{\bf t}(v)}$. We claim that $G(P)\cap\{x_{j_1},\dots,x_{j_d}\}= \{x_{j_d}\}=
	\{x_n\}$ (Setup \ref{setup}) which implies the desired assertion. From the definition of ${\bf t}$-spread support it follows immediately that $x_{j_d}\notin\supp_{\bf t}(v)$ and so $x_{j_d}=x_n\in G(P)$. Now we show that $x_{j_s}\notin G(P)$ for $s=1,\dots,d-1$. Equivalently, we show that $j_s\in\supp_{\bf t}(v)$ for $s=1,\dots,d-1$. Let $v=x_{i_1}\cdots x_{i_d}$. Then $i_s\in B_s=[\sum_{r=1}^{s-1}t_{r}+1,j_s]$, for all $s=1,\dots,d-1$. It follows that
	\[
	i_s+t_s-1\ge \sum_{r=1}^{s-1}t_{r} +1+t_s-1=\sum_{r=1}^st_r\ge j_s\ge i_s.
	\]
	Hence $j_s\in[i_s,i_s+t_s-1]\subseteq\supp_{\bf t}(v)$, as desired.

	Suppose $P=P_{[n]\setminus G}$ with $G\in\mathcal{G}$. Then $G=\supp_{\bf t}(x_{\ell_1}\cdots x_{\ell_{s-1}}x_{j_s})\cup[j_s+1,n]$ for some $x_{\ell_1}x_{\ell_2}\cdots x_{\ell_{s-1}}x_{j_s}\in G(B_{\bf t}(x_{j_1}x_{j_2}\cdots x_{j_{s-1}}x_{j_s}))$ and some $s=1,\dots,d$. We claim that $G(P)\cap\{x_{j_1},\dots,x_{j_d}\}=\{x_{j_s}\}$. Notice that $[n]\setminus G=[j_s]\setminus\supp_{\bf t}(x_{\ell_1}\cdots x_{\ell_{s-1}}x_{j_s})$. Then, the same argument as before shows that $G(P)\cap\{x_{j_1},\dots,x_{j_d}\}=\{x_{j_s}\}$.

	Now to apply Theorem \ref{Thm:useful} it remains to prove that $P_{[n]\setminus\{j_i\}}\notin\Ass((I^{\le{\bf 1}-{\bf e}_{j_i}})^k)$ for all $k\ge1$ and all $i=1,\dots,d$.

	Let $1\le i\le d$ and $B_i=[\sum_{s=1}^{i-1}t_s+1,j_i]$, for $i=1,\dots,d$. Our assumption and Proposition \ref{Prop:Gamma} imply that $|B_i|\ge2$ for all $i$ and that the $B_i$'s are pairwise disjoint. If $j_{i}-j_{i-1}>t_i$ then it is clear that $I^{\le{\bf 1}-{\bf e}_{j_i}}=B_{\bf t}(x_{j_i-1}(u/x_{j_i}))$. If otherwise $j_{i}-j_{i-1}=t_i$, then we define the integer
	\[
	\ell\ =\ \max\{m:\ j_p-j_{p-1}=t_{p-1}\ \textup{for all}\ p=m,\dots,i\},
	\]
	and we set
	\[
	v\ =\ \begin{cases}
		\,(\displaystyle\prod_{r=1}^{\ell-2}x_{j_r})(\prod_{r=\ell-1}^{i}x_{j_r-1})(\prod_{r=i+1}^{d}x_{j_r})&\text{if}\ j_i-j_{i-1}=t_{i-1},\\[5pt]
		\,\,x_{j_i-1}(u/x_{j_i})&\text{otherwise}.
	\end{cases}
	\]

	We claim that $I^{\le{\bf1}-{\bf e}_{j_i}}=B_{\bf t}(v)$. If $v=x_{j_i-1}(u/x_{j_i})$ this is clear. Now, assume we are in the first case and write $v=x_{h_1}\cdots x_{h_d}$. Notice that $h_r\ge(\sum_{s=1}^{r-1}t_s)+1$ for all $r=1,\dots,d$, because $j_r> \sum_{s=1}^{r-1}t_s+1$ for all $r=1,\dots,d$. Moreover, the definition of $\ell$ implies immediately that $v$ is ${\bf t}$-spread.

	Let $w=x_{q_1}\cdots x_{q_d}\in G(B_{\bf t}(v))$. Then $w$ is ${\bf t}$-spread, $\sum_{s=1}^{r-1}t_s +1\le q_r\le h_r\le j_r$ for all $r\in [1,\ell-2]\cup[i+1,d]$, and $\sum_{s=1}^{r-1}t_s+1\le q_r\le h_r\le j_r-1$, for all $r\in [\ell -1, i]$. In particular, $\sum_{s=1}^{i-1}t_s+1\le q_i\le h_i\le j_i-1$. This implies that $x_{j_i}$ does not divide $w$ and so $w\in G(I^{\le{\bf1}-{\bf e}_{j_i}})$.

	%for all $r\ne i$, and $\sum_{s=1}^{i-1}t_s+1\le q_i\le h_i\le j_i-1$. This implies that $x_{j_i}$ does not divide $w$ and so $w\in G(I^{\le{\bf1}-{\bf e}_{j_i}})$.

	Conversely, take $w=x_{q_1}\cdots x_{q_d}\in G(I^{\le{\bf1}-{\bf e}_{j_i}})$. Then $w$ is ${\bf t}$-spread with $q_r\in B_r$ for all $r$ and $j_i\notin\supp(w)$. We claim that $q_r\le h_r$ for all $r=1,\dots,d$. For $r\in[1,\ell-2]\cup[i+1,d]$ this is clear. For $r=i$ we have $q_i\in B_i$ and $q_i\ne j_i$. Hence $q_i\le j_i-1=h_i$. Now suppose for a contradiction that $q_{i-1}$ is not less or equal to $j_{i-1}-1=h_{i-1}$. Then, since $q_{i-1}\in B_{i-1}$ we have $q_{i-1}=j_{i-1}$. Since $w$ is ${\bf t}$-spread we have $q_{i}-q_{i-1}-t_{i-1}\ge0$. However, since $q_i\le j_i-1$ and $q_{i-1}=j_{i-1}$ we then have 
	\[
	q_{i}-q_{i-1}-t_{i-1}=j_i-1-j_{i-1}-t_{i-1}=-1
	\]
	by the meaning of $\ell$, and this is absurd. Hence $q_{i-1}\le h_{i-1}$. Proceeding in a similar way we obtain that $q_r\le h_r=j_r-1$ for all $r=\ell-1,\dots,i$. Hence $I^{\le{\bf1}-{\bf e}_{j_i}}\subseteq B_{\bf t}(v)$.

	Therefore $I^{\le{\bf 1}-{\bf e}_{j_i}}=B_{\bf t}(v)$. Since $h_r\le j_r\le\sum_{s=1}^rt_s$ for all $r$,  it follows from Proposition \ref{Prop:Gamma}(b) that $P_{[n]\setminus\{j_i\}}\notin\Ass(B_{\bf t}(v)^k)$ for all $k\ge1$, as we wanted to show. Finally, Theorem \ref{Thm:useful} implies that $I^{(k)}=I^k$ for all $k\ge1$.
\end{proof}

