\section{METHODOLOGY FOR FORMULATING AND SOLVING OPTIMIZATION PROBLEMS WITH MANIFOLDS}\label{sec:III}

In the following, we illustrate the \gls{mo} methodology by detailing the steps involved in addressing a real-world problem in power systems. Specifically, we will optimize the voltage phase angles in a distributed grid using a \gls{mo} technique. This approach serves as an example, but the methodology can be applied to any problem involving non-convex constraints that can be represented as a manifold.

Power systems are designed to balance dynamically the generation and demand while maintaining stability; thus, optimizing voltage angles to enhance power flow efficiency is crucial, particularly in networks with high renewable energy penetration. The phase angles of bus voltages and the setpoints of distributed energy resources constitute high-dimensional and nonlinear spaces. \gls{mo} provides a structured framework for efficiently dealing with these complex and non-convex optimization problems.

\subsection*{STEP 1: PROBLEM FORMULATION}

\begin{itemize}

\item[\dm]\textbf{Define the Objective}: Clearly define the optimization problem in terms of an \gls{of}. This could involve optimizing key operational metrics such as power loss minimization, voltage stability margin, or economic dispatch efficiency. The \gls{of} is represented by $f(\boldsymbol{\theta},\boldsymbol{v})$, where $\boldsymbol{v}$ and $\boldsymbol{\theta}$ denote the complex bus voltages and phase angles, respectively, in a system with $N$ buses, with $[\boldsymbol{v}]_n = V_n e^{j\theta_n}$.

    \vspace{2mm}

    \item[\dm]\textbf{Constraints}: Identify the constraints of the problem, such as inferior and superior bounds on the injected power, represented as $\mathcal{P}_n^{\min} \leq P_n \leq \mathcal{P}_n^{\max}$ $\forall n \in \mathcal{N}_{\text{PV}}$, voltage magnitude bounds $V_n^{\min} \leq |V_n| \leq V_n^{\max}$ $\forall n \in \mathcal{N}_{\text{PV}}$, and power balance equations $\mathbf{S} = \mathbf{diag(V)YV^*}$, with $\mathbf{V}$ being the complex voltage and $\mathbf{Y}$ the adimittance matrix. For voltage-controlled buses, the following must hold:
    \begin{small}
    \begin{align}
    |V_n e^{j\theta_n}| = V_n^{\text{ref}} \quad \forall n \in \mathcal{N}_{\text{PV}},
    \end{align}
    \end{small}
    \noindent where $\mathcal{N}_{\text{PV}}$ denotes the set of PV buses and $V_n^{\text{ref}}$ is the specified voltage magnitude.
\end{itemize}

\subsection*{STEP 2: IDENTIFY THE MANIFOLD STRUCTURE}

\begin{itemize}
\item[\dm]\textbf{Manifold Description}: Establish the geometric structure of the constraint. For instance, voltage phasors in power systems lie on \gls{ccm}, which can be treated as a manifold\footnote{Common manifolds in power systems include the Euclidean manifold (for traditional power flow and OPF), the Grassmann manifold (for low-rank subspace methods in PMU data), and the SPD manifold (for covariance-based uncertainty analysis). For a complete list of manifolds, see Table \ref{tab:manifolds}.} and described as
    %
    \begin{small}
    \begin{align}
        \mathcal{S}^1 = \{V_n e^{j\theta_n} \in \mathbb{C} \mid \theta_n \in [0, 2\pi), V_n = V_n^{\text{ref}}\}, \quad \forall n \in \mathcal{N}_{\text{PV}},
    \end{align}
    \end{small}
    \noindent where $\mathcal{N}_{\text{PV}}$ is the set of voltage-controlled (PV) buses in the system.
\end{itemize}


\subsection*{STEP 3: REFORMULATE THE OPTIMIZATION PROBLEM}

\begin{itemize}
    \item[\dm]\textbf{Manifold Representation}: Reformulate the original non-convex constraint problem in terms of manifold constraints. For example, if the optimization involves fixed-voltage-magnitude constraints, e.g., PV bus voltage angles $\theta_n \in [0, 2\pi)$, it should be represented in terms of the complex phasor form $V_ne^{j\theta_n}$. In power system optimization, the problem becomes:
    %
    \begin{small}
    \begin{align}
        \max_{\boldsymbol{\theta} \in \mathcal{M}} f(\boldsymbol{\theta},\boldsymbol{V}),
    \end{align}
    \end{small}
    \noindent where $\boldsymbol{\theta}$ is the vector of voltage phase angles at PV buses, $\boldsymbol{V}$ represents the complex bus voltages, and $\mathcal{M}$ denotes the power flow manifold incorporating both voltage magnitude constraints and network physics.

    \vspace{2mm}

    \item[\dm]\textbf{Alternative Parameterization}: Use appropriate parameterizations to represent elements on the manifold in a computationally friendly way.
\end{itemize}

\subsection*{STEP 4: DEVELOP AN OPTIMIZATION ALGORITHM}

\begin{itemize}
    \item[\dm]\textbf{Initialization}: Start with an initial feasible point on the manifold. This might involve random initialization or a heuristic-based initialization.
    %
    \begin{small}
    \begin{align}
        \boldsymbol{\theta}^{(0)} = [\theta_1^{(0)}, \theta_2^{(0)}, \ldots, \theta_N^{(0)}]^T.
    \end{align}
    \end{small}

    \vspace{2mm}

    \item[\dm]\textbf{Gradient Descent}: Use some {\it manifold-based optimization technique} (see subsection \ref{subsec:gradient} of section \ref{sec:V}) to iteratively update the phase shifts and move towards the local optimum. The steps should ensure the updated points lie on the manifold.
    %
    \begin{small}
    \begin{align}
        \boldsymbol{\theta}^{(k+1)} = \boldsymbol{\theta}^{(k)} + \alpha \nabla_{\mathcal{M}} f(\boldsymbol{\theta}^{(k)}),
    \end{align}
    \end{small}
    \noindent where $\alpha$ is the step size and $\nabla_{\mathcal{M}} f(\boldsymbol{\theta}^{(k)})$ is the Riemannian gradient at the $k$-th iteration.

    \vspace{2mm}

    \item[\dm]{\bf Returning to the Manifold}: After updating the phase shifts, the updated point should be on the manifold surfaces, therefore, the retraction operator should be applied. Specifically, for the \gls{ccm} manifold, the retraction operator is given as
    %
    \begin{small}
    \begin{align}
        \operatorname{Retr}_{\mathcal{S}^1}(\boldsymbol{\theta}^{(k+1)}) = \frac{\left[\boldsymbol{\theta}^{(k+1)}\right]_n}{\left|\left[\boldsymbol{\theta}^{(k+1)}\right]_n \right|}, \quad \forall n={1,2,\dots,N}. \label{eq:Retraction_CCM}
    \end{align}
    \end{small}
\end{itemize}

\subsection*{STEP 5: ITERATIVE OPTIMIZATION}

\begin{itemize}
    \item[\dm]\textbf{Iterative Process}: Iterate the optimization process until convergence. The stopping criterion could be based on the change in the \gls{of} value or the gradient norm at the $k$-th iteration till a small positive threshold $\epsilon$.
\end{itemize}
%
\begin{small}
\begin{align}
    \|\nabla_M f(\boldsymbol{\theta}^{(k)})\| < \epsilon.
\end{align}
\end{small}

\subsection*{STEP 6: VALIDATION AND PERFORMANCE EVALUATION}

\vspace{2mm}

\begin{itemize}
    \item[\dm]\textbf{Validation}: Validate the optimized voltage profiles by evaluating the system's power flow solutions. Compare the performance with conventional optimization methods (e.g., interior-point or Newton-Raphson) to demonstrate the efficiency and effectiveness of the \gls{mo}-based approach through metrics like:
    \begin{itemize}
        \item[\dm] Power loss reduction: $\Delta P_{\text{loss}} = P_{\text{loss}}^{\text{conv}} - P_{\text{loss}}^{\text{MO}}$
        \item[\dm] Voltage stability margin improvement: $\Delta VSM = VSM^{\text{MO}} - VSM^{\text{conv}}$
        \item[\dm] Computational time savings: $t_{\text{savings}} = t_{\text{conv}} - t_{\text{MO}}$
    \end{itemize}
\end{itemize}


\section{GRADIENT DESCENT-BASED ALGORITHMS} \label{sec:IV}
%\colr{Adaptar/Re-escrever}
In the following, we exhibit a list of gradient descent-based methods, which can be generalized to the Riemannian space and utilized in \gls{mo} strategy. 







\subsection{GRADIENT DESCENT-BASED ALGORITHMS} \label{subsec:gradient}

Manifold-based optimization techniques, such as  \gls{rn}, \gls{rcg}, \gls{rtr} and \gls{rgd} are powerful for optimizing functions constrained to manifolds. These methods are specifically designed to account for the non-Euclidean geometry of the optimization space. By leveraging the inherent geometric properties of these manifolds, such techniques enable efficient and effective optimization pathways. This is particularly beneficial in solving complex optimization problems found in power systems, where gradients can be computed directly on the manifold, allowing algorithms to navigate the curvature of the space effectively. This tailored approach helps ensure efficient convergence to locally optimal solutions within these constrained environments.

\vspace{2mm}

\noindent{\em \gls{rgd}}: The \gls{rgd} is an optimization technique that extends the classical gradient descent method to Riemannian manifolds. The optimization process is constrained to a curved space rather than a flat Euclidean space. The key idea is to iteratively move towards the local optimum while ensuring that each update remains on the manifold. The \gls{rgd} Algorithm steps are as follows:

\begin{enumerate}
    \item[\dm]\textbf{Initialization:} Start with an initial feasible point on the manifold.

    \item[\dm]\textbf{Gradient Computation:} Compute the Riemannian gradient, which is the projection of the Euclidean gradient onto the tangent space of the manifold.

    \item[\dm]\textbf{Update Rule:} Move in the direction of the Riemannian gradient by a step size, ensuring the updated point lies on the manifold. This often involves a retraction operation that maps the point back onto the manifold.

    \item[\dm]\textbf{Iteration:} Repeat the gradient computation and update steps until convergence.
\end{enumerate}

\begin{algorithm}
\label{alg:rgd}
\small
\caption{\gls{rgd} Algorithm}
\begin{algorithmic}[1]

\State \textbf{Input:} Initial point $\mathbf{x}_0$ on manifold $\mathcal{M}$, step size $\alpha$, max iterations $K$

\State \textbf{Output:} Optimized point $\mathbf{x}^*$ on the manifold
\algorithmiccomment{\it Input and output specifications}

\State $k \gets 0$ \algorithmiccomment{ Initialization of the iteration counter}

\While{$k < K$ and not converged} 
    \State Compute Riemannian gradient $\operatorname{grad} f(\mathbf{x}_k)$ \algorithmiccomment{\it Project Euclidean gradient onto tangent space}

    \State Update: $\mathbf{x}_{k+1} \gets \mathcal{R}_{\mathbf{x}_k}(-\alpha \operatorname{grad} f(\mathbf{x}_k))$ 
    \algorithmiccomment{\it Utilize retraction operator to map point back to manifold} 

    \State $k \gets k + 1$
\EndWhile

\State \textbf{return} $\mathbf{x}_k$ \algorithmiccomment{\it  Return of the final optimized point}

\end{algorithmic}
\end{algorithm}

\vspace{2mm}

\noindent{\em \gls{rn}:} \gls{rn} method is an extension of the classical Newton method to Riemannian manifolds. It uses second-order information (Hessian) to achieve faster convergence when compared to the gradient descent method.

\vspace{2mm}

\noindent{\em \gls{rcg}:} \gls{rcg} is an adaptation of the conjugate gradient method to Riemannian manifolds. It combines the efficiency of the conjugated gradient method with the geometric constraints of manifolds.

\vspace{2mm}

\noindent{\em \gls{rtr}:} \gls{rtr} methods extend trust-region methods to the Riemannian manifolds. These methods iteratively solve a local approximation of the optimization problem within a “trust region” around the current point.


 Utilizing \gls{mcs} or other simulation techniques is useful to evaluate the algorithm's performance under different scenarios. Based on simulation results, we can also refine the algorithm for better performance by adjusting parameters and re-evaluating. Refinement based on simulations is a critical step in the optimization process, especially when dealing with complex systems like those involving manifolds. In this context, the refinement process based on simulations might involve specific steps such as:

\begin{itemize}
    \item[\dm] \textit{Gradient and Hessian Adjustments:} Fine-tuning the computation of Riemannian gradients and Hessians to ensure they accurately capture the manifold's geometry.
    \item[\dm] \textit{Retraction Operations:} Modifying the retraction operations to better map updated points back onto the manifold.
    \item[\dm] \textit{Step Size Adaptation:} Adjusting the step size dynamically based on the manifold's curvature to ensure efficient convergence.
    \item[\dm] \textit{Constraint Handling:} Refining how additional constraints are incorporated into the optimization problem, possibly by adjusting the indicator functions or penalty terms.
\end{itemize}

The goal is to iteratively improve the algorithm or model based on empirical evidence from simulations, leading to better performance in the target application. How refinement is typically done based on simulations is summarized in Algorithm \ref{alg:refinement}. 

Some open-source libraries support manifold structures, such as  \href{https://www.manopt.org/}{\texttt{Manopt tools}}, which implements a bunch of manifold collections available on \texttt{Manopt} (Matlab) or \texttt{Pymanopt} (Python), which can be useful for obtaining solutions of many diverse problems \cite{manopt2014}, 
\cite{Boumal_book_2023}.

\begin{algorithm}
\caption{Refinement Based on Simulations}
\label{alg:refinement}
\small
\begin{algorithmic}[1]
%
    \State \textbf{Initial Simulation:} 
    \State \quad Run initial simulations to evaluate the performance of the current algorithm or system configuration.
    \State \quad Collect performance metrics such as \gls{se}, \gls{ee}, error rates, throughput, etc.

    \State \textbf{Performance Analysis:}
    \State \quad Examine the simulation results to identify strengths and weaknesses.
    \State \quad Determine which aspects are underperforming or causing issues.

    \State \textbf{Parameter Adjustment:}
    \State \quad Modify parameters of the algorithm or system based on the analysis.
    \State \quad Make necessary changes to the algorithm itself if required.

    \State \textbf{Re-simulation:}
    \State \quad Perform new simulations with the adjusted parameters or modified algorithm.
    \State \quad Compare the new simulation results with the previous ones.

    \State \textbf{Iteration:}
    \State \quad Repeat the process of analysis, adjustment, and re-simulation multiple times.
    \State \quad Continue iterating until performance metrics converge to satisfactory levels.

    \State \textbf{Validation:}
    \State \quad Use cross-validation techniques to ensure generalization to different scenarios.
    \State \quad Test the refined system under various conditions for robustness.

    \State \textbf{Final Tuning:}
    \State \quad Perform fine-tuning of parameters to achieve the best possible performance.
    \State \quad Use advanced optimization techniques if necessary.
\end{algorithmic}
\end{algorithm}





