\subsection{Main result}
Before stating the main result we compile a list of assumptions that it relies on.

\begin{assumption}[Turing instability]\label{ASSUMP:Turing_instability}
 Consider the linear operator $\mathcal{L}_p$ in \eqref{EQ:linear_operator}. We assume that
 \begin{align}
     p(x) = p_*(x) + \varepsilon^2 r \, , \quad r \in \mathbb{R} \, ,
 \end{align}
 for $0 < \varepsilon \ll 1$ and some periodic function $p_*(x) = \mathcal{O}(1)$
 is chosen such that the band structure \eqref{EQ:bands_periodic_coefficient} is given by $(\ell, \lambda_n(\ell))$ with $\lambda_n(\ell) = \lambda_n(\ell;k_0, p_*, \varepsilon, r)$ and the following holds true for the Floquet-Bloch solutions from \eqref{EQ:Floquet-Bloch_solutions}.
 \begin{itemize}
     \item[(a)] {\bf (ONB)} The sequence of functions $\{\psi_n(\ell,\cdot)\}_{n\in\mathbb{N}}$ forms an orthonormal basis of $L^2\left(\left[0, \frac{2\pi}{k_f}\right]\right)$ for every $ -k_f/2 \leq \ell < k_f/2$.
     \item[(b)] {\bf (Ordering of band structure)} We have $\lambda_{n}(\ell) \geq \lambda_{n+1}(\ell), n \in \mathbb{N}, \lambda_{n}(\ell) \rightarrow -\infty, n \rightarrow \infty$ for every $ -k_f/2 \leq \ell < k_f/2 $.
     \item[(c)] {\bf (Regularity properties of spectral data)} The $\psi_n, \lambda_n$ are at least three times differentiable w.r.t. $\ell$, with $\partial_\ell^k \psi_n(\ell,x)\in L^2([0, 2\pi/k_f])$ for $0\leq k\leq 3$ and satisfy $\lambda_n(-\ell) = \lambda_n(\ell)$, $\psi_n(-\ell, x) = \overline{\psi_n(\ell,x)}$ for every $ -k_f/2 \leq \ell < k_f/2 $.
     \item[(d)] {\bf (Bifurcation w.r.t. $\bm{r}$)} The function $p_*$ is such that $ \mathrm{sign}(r) = \mathrm{sign}(\max_{-k_f/2 \leq \ell < k_f/2}(\lambda_{1}(\ell)))$ and, in particular, for $r = 0$ we have that there exists a unique $\ell_0$ with $0 = \lambda_1(\ell_0) = \max_{0 \leq \ell < k_f/2}\lambda_{1}(\ell)$.
     \item[(e)] {\bf (Parabolic band structure at onset)} At bifurcation onset, $r = 0$, we have that
\begin{equation}
    \lambda_1(\ell_0) = 0, \quad \partial_\ell \lambda_1(\ell_0)=0, \quad \partial_\ell^2 \lambda_1(\ell_0)<0.
\end{equation}
    for $l_0 \in [0, k_f/2)$ and $\lambda_1(\ell)$ is of parabola type around $\ell_0$, i.e., $\lambda_1(\ell) \leq -C(\ell-\ell_0)^2$ for some $C>0$ and for $\ell\in B_\varepsilon (\ell_0)$, with $B_\varepsilon(\ell_0)$ an $\varepsilon$-neighborhood of $\ell_0$.
    \item[(f)] {\bf (Spectral gap)} At bifurcation onset, $r = 0$, there is a spectral gap between the first two spectral curves, $\min_\ell \lambda_1(\ell)>\max_\ell \lambda_2(\ell)$.
    \item[(g)] {\bf (Non-resonance conditions)} We have that $\lambda_1(3\ell_0)\neq 0$, $\lambda_1(3\ell_0)= \mathcal{O}(1)$ and $\lambda_2(\ell_0)=\mathcal{O}(1), \lambda_2(3\ell_0)=\mathcal{O}(1)$ with respect to $\varepsilon$.
      \end{itemize}
\end{assumption}

We now have all ingredients to state the main theorem.

\begin{theorem}\label{thm:SH_approx}\emph{\textbf{(Approximation Theorem - Ginzburg-Landau for the non-resonant case)}}
    Consider the Swift-Hohenberg equation \eqref{EQ:SH_periodic_coefficients} with periodic functions $p, \rho$ as in \eqref{EQ:periodic_ceofficients} such that Assumption~\ref{ASSUMP:Turing_instability} holds and $\rho$ is continuous. Let $T_0\in\mathbb{R}$, $T_0>0$ and $T_0=\mathcal{O}(1)$ and let $Y$ be a suitably chosen function space. Then there exists an $\varepsilon_0>0$ and a $C>0$ such that for all $\varepsilon\in(0,\varepsilon_0)$ there are solutions $u$ of the Swift-Hohenberg equation \eqref{EQ:SH_periodic_coefficients} with
    \begin{equation}\label{eq:thm_error_est}
        \sup_{t\in [0,~T_0/\varepsilon^2]} \|u(\cdot,t)-u_{\rm Ans}(\cdot, t)\|_{Y} \leq C\varepsilon^2,
    \end{equation}
    where $u_{\rm Ans} = u_{\rm GL} + \mathcal{O}(\varepsilon^2)$ is to leading order given by
    \begin{equation}\label{eq:u_GL}
        u_{\rm GL}(x,t) = \varepsilon A_1(X,T)\psi_1(\ell_0,x) e^{i\ell_0x}+\varepsilon \overline{A_1(X,T)} \overline{\psi_1(\ell_0,x)} e^{-i\ell_0x},
    \end{equation}
    with $X:=\varepsilon x, ~T:=\varepsilon^2 t$, and where $A_1$ solves the Ginzburg-Landau equation
    \begin{equation}\label{eq:GL_forced_SH}
        \begin{split}
    \partial_T A_1 = & ~r A_1 + \frac{1}{2} \partial_\ell^2 \lambda_1 (\ell_0) \partial_X^2 A_1  - 3 \left(\int_0^{2\pi/k_f} |\psi_1(\ell_0,x)|^4 \rho(x) ~dx \right)~ |A_1|^2 A_1 \, ,
    \end{split}
    \end{equation}
    for non-resonant wavenumbers $k_f$. 
\end{theorem}

When $\ell_0=3\ell_0 \pmod{k_f}$, Assumption~\ref{ASSUMP:Turing_instability}(g) can not be satisfied. In these cases, either $\ell_0=0$ or $\ell_0=\frac{k_f}{2}$, leading to resonances.

\begin{definition}\label{def:resonances}\emph{\textbf{(Resonances)}}
If the spectrum admits a spectral gap at onset between $\lambda_1(\ell)$ and $\lambda_2(\ell)$, the combination of parameters such that $\ell_0 = \frac{k_f}{2}$ is called \emph{resonant}. Combinations of parameters that yield to $\ell_0\neq 3\ell_0\pmod{k_f}$ are referred to as \emph{non-resonant}. 
\end{definition}

The proof of Theorem \ref{thm:SH_approx} yields the following corollaries for values of $k_f$ such that $\ell_0=3\ell_0\pmod{k_f}$. Here, we need an adaptation of Assumption~\ref{ASSUMP:Turing_instability}(g):

\newcommand{\mainTheoremNumber}{\arabic{section}.\arabic{assumption}}
\setcounter{assumption}{\value{assumption}-1}
\begin{assumption}
    \begin{itemize}
        \item [(g')] We have $\lambda_2(\ell_0)=\mathcal{O}(1)$ with respect to $\varepsilon$.
    \end{itemize}
\end{assumption}


\begin{corollary}[\textbf{Allen-Cahn approximation for the $\ell_0=0$ case}]\label{cor:SH_approx_l00}
    Consider parameter regimes such that $\ell_0=0$ and the same assumptions as Theorem \ref{thm:SH_approx} hold, with Assumption~\ref{ASSUMP:Turing_instability}(g) replaced by Assumption~\ref{ASSUMP:Turing_instability}(g'). Let $T_0\in\mathbb{R}$, $T_0>0$ and $T_0=\mathcal{O}(1)$ and let $Y$ be a suitably chosen function space. Then there exists an $\varepsilon_0>0$ and a $C>0$ such that for all $\varepsilon\in(0,\varepsilon_0)$ there are solutions $u$ of the Swift-Hohenberg equation \eqref{EQ:SH_periodic_coefficients} such that \eqref{eq:thm_error_est} holds, where $u_{\rm Ans} = u_{\rm AC} + \mathcal{O}(\varepsilon^2)$ is to leading order given by
    \begin{equation}\label{eq:u_AC}
        u_{\rm AC}(x,t) = \varepsilon A_1(X,T)\psi_1(0,x)\,,
    \end{equation}
    with $X:=\varepsilon x, ~T:=\varepsilon^2 t$, $A_1$, $\psi_1(0,\cdot) \in \mathbb{R}$ and where $A_1$ solves the Allen-Cahn equation
    \begin{equation}\label{eq:AC_forced_SH}
         \begin{split}
     \partial_T {A}_{1} = & ~ rA_1 +  \frac12 \partial_{\ell}^2\lambda_1(0) \partial_X^2A_1 -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(0,x)^4\rho(x)~ dx\right) A_1^3\,.
     \end{split}
    \end{equation}
\end{corollary}


\begin{corollary}[\textbf{Non-phase invariant GL approximation for a resonant case}]\label{cor:SH_approx_res}
    Consider $k_f$ resonant and let the same conditions as Theorem \ref{thm:SH_approx} hold true, with Assumption~\ref{ASSUMP:Turing_instability}(g) replaced by Assumption~\ref{ASSUMP:Turing_instability}(g'). Let $T_0\in\mathbb{R}$, $T_0>0$ and $T_0=\mathcal{O}(1)$ and let $Y$ be a suitably chosen function space.
    Then there exists an $\varepsilon_0>0$ and a $C>0$ such that for all $\varepsilon\in(0,\varepsilon_0)$ there are solutions $u$ of the Swift-Hohenberg equation \eqref{EQ:SH_periodic_coefficients} such that \eqref{eq:thm_error_est} and \eqref{eq:u_GL} hold, where $A_1$ solves the non-phase invariant Ginzburg-Landau equation
    \begin{equation}\label{eq:GL_forced_SH_res}
         \begin{split}
     \partial_T {A}_{1} = & ~ rA_1 +  \frac12 \partial_{\ell}^2\lambda_1(\ell_0) \partial_X^2A_1 - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0,x)|^4\rho(x)~dx\right) |A_1|^2 A_1  \\ 
     &\quad -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(\ell_0,x)^3 \overline{\psi_1( \ell_0,x)}\rho(x)~ dx\right) A_1^3\,.
     \end{split}
    \end{equation}
\end{corollary}

Solutions $u$ of the Swift-Hohenberg \eqref{EQ:SH_periodic_coefficients} can be represented as $u(x,t) = u_{\rm Ans}(x,t) + \check{S}(x,t)$ where $\check{S}$ represents the error between the real solution and the approximation $u_{\rm Ans}(x,t)$. The PDE for the error $\check{S}$ is given by
\begin{equation}\label{eq:res_def}
\begin{split}
    \partial_t \check{S} = \mathcal{L}_p \check{S} -\check{S}^3 -3 \check{S}^2 u_{\rm Ans} - 3\check{S} u_{\rm Ans}^2-\text{Res}(u_{\rm Ans}) \, , \quad \text{Res}(u_{\rm Ans}) = -\partial_t u_{\rm Ans} + \mathcal{L}_pu_{\rm Ans} -u_{\rm Ans}^3 \, .
\end{split}
\end{equation}
The approximation $u_{\rm Ans}$ is constructed as a small amplitude solution that features $\varepsilon$ both in front of the amplitude and in the space and time scaling. A common technique is to make the residual small by matching the ansatz. However, to establish the validity of the approximation, it is important to control the entire error $\check{S}$.  Special situations are known in which the amplitude equation, although correctly derived, fails to make a correct prediction \cite{phd_thesis_failure_ampl, Failure_Nwave_Schneider_Haas, Failure_mod_eq_Schneider_Rijk_Haas, failure_slow_dyn_Schneider_BSZ}. This underscores the importance of validating the derived amplitude equation. The novelty of this paper lies in justifying the Ginzburg-Landau equation for a dissipative system with spatially varying coefficients that are not restricted in magnitude. 


\begin{remark}[\bf Periodic solutions of GL]
The complex Ginzburg-Landau equation with constant coefficients,
\begin{equation}
    \partial_T A= \alpha_1 A + \alpha_2\partial_X^2A+\alpha_3|A|^2A\,,
\end{equation}
$\alpha_1, \alpha_2, \alpha_3\in \mathbb{C}$, admits stationary solutions that are spatially periodic of the form 
\begin{equation}
    A_{\rm per}(X,T) = Be^{i\kappa X}\,, \quad  |B|^2 = \frac{\kappa^2\alpha_2-\alpha_1}{\alpha_3}\, . 
\end{equation}
Upon taking $\alpha_1, ~\alpha_2$ and $\alpha_3$ to agree with \eqref{eq:GL_forced_SH} , these periodic solutions $A_{\rm per}$ lead to solutions of \eqref{EQ:SH_periodic_coefficients} featuring a band of possible wavenumbers close to $\ell_0$, given by 
\begin{equation}
    u_{\rm GL}(x,t) =  \varepsilon B\psi_1(\ell_0,x)e^{i(\ell_0+\varepsilon\kappa )x} +{\rm c.c.}.
\end{equation}
Solutions $A_{\rm per}$ are stable for a range of wavenumbers $\kappa$ (see e.g. \cite{Eckhaus1965, Cross_Hohenberg_1993, Schneider_Diffusive_stab, eckmann1997geometric, haragus2011local}). This family of periodic solutions of the Ginzburg-Landau equation explains the occurrence of an entire branch of stable periodic orbits for the Swift-Hohenberg equation. In more complicated systems, computing these solutions and determining their stability enables us, in particular, to compute the tip of the Busse balloon explicitly (see \cite{GKGS_SDHR}).
\end{remark}


\begin{remark}[\bf Global results]
For the classic constant-coefficient case the (above local) approximation result (based on \cite{SH_GL_val_cubic}) is complemented by an attractivity results and a global approximation result (see \cite{Bollerman1995},\cite{Eckhaus1993GLAttractor} , \cite{Schneider1994Global}, \cite{Schneider1995Analyticity}, \cite{Schneider2001}). We expect similar results to hold true for \eqref{EQ:SH_periodic_coefficients}, but leave this for future work. 
\end{remark}



\begin{remark}[$\bm{p(x) = p_*(x) + \varepsilon^2 \widetilde{p}(x)}$]\label{rem:p_tilde}
For $p(x) = p_*(x) + \varepsilon^2 \widetilde{p}(x)$ we expect a similar result with the modification that the GL equation will feature a term containing the change of the dispersion relation at $\ell = \ell_0$ in the direction $\widetilde{p}$. Extensions of the result of this form are left for future work.
\end{remark}


\begin{remark}[\bf $\bm{k_f}$ small]\label{rem:kf_small}
    From an ecological perspective, forcing with small wavenumbers, i.e. $k_f = o(1)$ with respect to $k_0$, are particularly interesting, as the wavenumber of mountains is much smaller than that of the observed wavenumber of vegetation patterns. From a mathematical point of view, forcing with small wavenumbers is of interest as for small forcing, the system admits space-intermittent solutions \cite{Doelman_Schielen}. Numerical experiments show that with large forcing, these space-intermittent solutions persist. Although often treated as a separate case, numerical study shows that for $k_f$ small and $\gamma$ large enough, the spectrum can satisfy Assumption~\ref{ASSUMP:Turing_instability} and hence the same results hold as for $k_f=\mathcal{O}(1)$. However, the numerical algorithm is more computationally expensive, hence numerical validation of Assumption~\ref{ASSUMP:Turing_instability} is less straightforward. Since the first two curves strongly overlap with small forcing, one has to carefully check Assumption~\ref{ASSUMP:Turing_instability}(f). 
\end{remark}

\subsection{Numerical Results}\label{sec:num_res}
In this section we present numerical approximations for a setting in which Assumption~\ref{ASSUMP:Turing_instability} appears to hold in the case $p(x) = p_*(x) + \varepsilon^2 r = \mu_* + \gamma_* \cos(k_f x)+ \varepsilon^2 r$. For parameter values right after onset, a perturbation to the zero state $u_*=0$ leads to a new pattern solution. These patterns are approximated for $k_f$ non-resonant as in Theorem \ref{thm:SH_approx}. If $A_1$ is real, a stationary solution of (\ref{eq:GL_forced_SH}) is the constant solution
