\subsection{Notation}
We follow the notation and definitions in \cite{SchneiderUecker}.

\subsubsection{Bloch transform}
The Bloch transform is an adaption of the Fourier transform in the spatially homogeneous case to the spatially periodic case \cite{Simon_Reed}. It is defined using the Fourier transform and, similarly as to the Fourier transform, multiple definitions can be used. We use the symmetric Fourier transform
\begin{equation}
    \hat{u}(k)=(\mathcal{F}u)(k) =\frac{1}{\sqrt{2\pi}} \int_{-\infty}^\infty u(x)e^{-ikx} ~dx,
\end{equation}
with inverse Fourier transform
\begin{equation}
    u(x)=(\mathcal{F}^{-1}\hat{u})(k)=\frac{1}{\sqrt{2\pi}} \int_{-\infty}^\infty \hat{u}(k) e^{ikx}~dk.
\end{equation}
The following definition for the Bloch transform for $2\pi/k_f$-periodic functions can be derived
\begin{equation}\label{eq:Bloch_T}
    \widetilde{u}(\ell,x)=(\mathcal{B}u)(\ell, x) = \sum_{j\in\mathbb{Z}} \hat{u}\left(k_f j+\ell\right) e^{ik_f jx},
\end{equation}
with inverse Bloch transform
\begin{equation}\label{eq:Bloch_inv_T}
    u(x) = (\mathcal{B}^{-1}\widetilde{u})(x) = \frac{1}{\sqrt{2\pi}} \int_{-\frac{k_f}{2}}^\frac{k_f}{2}\widetilde{u}(\ell,x) e^{i\ell x} ~d\ell.
\end{equation}
This Bloch transform satisfies the following properties
\begin{equation}
\begin{split}
    \widetilde{u}\left(\ell,x+\frac{2\pi}{k_f}\right) &= \widetilde{u}(\ell,x),\\
    \widetilde{u}\left(\ell+k_f,x\right) &= \widetilde{u}(\ell, x)e^{-ik_f x}.
    \end{split}
\end{equation}
The multiplication to convolution property becomes 
\begin{equation}\label{eq:Bloch_conv_def}
    \widetilde{fg}(\ell,x) = \int_{-k_f/2}^{k_f/2} \widetilde{f}(p) \widetilde{g}(\ell - p) ~dp = (\widetilde{f} \star \widetilde{g})(\ell,x).    
\end{equation}

\subsubsection{Function space}\label{subsec:function_spaces}

Following the reasoning in \cite{SchneiderUecker}, we want to allow solutions of the Ginzburg-Landau equation that do not decay for $|x|\rightarrow \infty$ and want to be able to use the Fourier transform and the Bloch transform. Hence we consider the Sobolev space $H_{ul}^\vartheta$, which is constructed in the following way.

\medskip

We take a positive weight function $q: \mathbb{R}\rightarrow (0,\infty)$ that is continuous, bounded and satisfies $\int_\mathbb{R} q(x) ~dx <\infty$. Furthermore, we impose $q\in C^2(\mathbb{R}, \mathbb{R})$ and $|q'(x)|$, $|q''(x)|\leq q(x)$ for all $x$. Introduce
\begin{equation}
    \widetilde{L_{ul}^2} = \left\{ u\in L_{loc}^2(\mathbb{R})~:~\|u\|_{L_{ul}^2} <\infty\right\}, \quad \text{ where } \quad \|u\|_{L_{ul}^2}^2 = \sup_{y\in\mathbb{R}} \int_\mathbb{R} q(y+x) u(x)^2~dx.
\end{equation}
The $L_{ul}^2$ norm is equivalent to the norm $\|\cdot\|_*$ defined as 
\begin{equation}
    \|u\|_* = \sup_{y\in\mathbb{R}} \left( \int_{y-1/2}^{y+1/2} |u(x)|^2 ~dx \right)^{1/2}.
\end{equation}
Introduce the translation operator $T_y~:~\widetilde{L_{ul}^2} \rightarrow \widetilde{L_{ul}^2}$, $(T_y u)(\cdot) \mapsto u(\cdot + y)$. The space of uniformly local $L^2$ functions is given by
\begin{equation}
    L_{ul}^2 = \left\{ u\in\widetilde{L_{ul}^2}~:~ \|T_y u - u\|_{L_{ul}^2} \rightarrow 0 \text{ as } y\rightarrow 0\right\}.  
\end{equation}
For $\vartheta\in\mathbb{N}$ we define the uniformly local Sobolev space $H_{ul}^\vartheta$ as
\begin{equation}
    H_{ul}^\vartheta = \left\{ u\in L_{ul}^2 ~:~ D^m u \in L_{ul}^2 \text{ for all } |m|<\vartheta \right\}.
\end{equation}


