After substituting \eqref{eq:ansatz_bloch_diag} into \eqref{eq:res_bloch_diag}, we get
\begin{align*}
&\widetilde{\mathbf{Res}}_1\{\widetilde{\mathcal{A}}_{\mathrm{ansatz}} \} = \left[- \partial_t \widetilde{\mathcal{A}}_{\mathrm{ansatz}} + \widetilde{\mathbf{L}}(\ell)\widetilde{\mathcal{A}}_{\mathrm{ansatz}} + \widetilde{\mathbf{N}}\left(\widetilde{\mathcal{A}}_{\mathrm{ansatz}}\right) \right]_1\\[.2cm]
& = \varepsilon^2 \left[ -\partial_T \widetilde{A}_{1,+} + \left( r +  \frac12 \partial_{\ell}^2\lambda_1(\ell_0) L_{+}^2\right)\widetilde{A}_{1,+} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0, x)|^4 \rho(x)~ dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \right]\\[.2cm]
& + \varepsilon^2 \left[ -\partial_T \widetilde{A}_{1,-} + \left( r +  \frac12 \partial_{\ell}^2\lambda_1(-\ell_0) L_{-}^2\right)\widetilde{A}_{1,-} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(-\ell_0,x)|^4 \rho(x)~ dx \right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \right]\\[.2cm]
& + \varepsilon^2 \underbrace{\left[ -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(\ell_0,x)^3 \overline{\psi_1(3\ell_0,x)} \rho(x)~dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \right]}_{=:\widetilde{B}_{1,3}}\\[.2cm]
& + \varepsilon^2 \underbrace{\left[ -\left(\int_{0}^{\frac{2 \pi}{k_f}} \psi_1(-\ell_0,x)^3 \overline{\psi_1(-3\ell_0,x)} \rho(x)~dx\right) \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \right]}_{=:\widetilde{B}_{1,-3}} + \varepsilon^2 \lambda_1(\ell)\widetilde{B}_1 \, 
\end{align*}
for $n=1$, while for $n > 1$ we get
\begin{align*}
&\widetilde{\mathbf{Res}}_n\{\widetilde{\mathcal{A}}_{\mathrm{ansatz}} \} = \left[- \partial_t \widetilde{\mathcal{A}}_{\mathrm{ansatz}} + \widetilde{\mathbf{L}}(\ell)\widetilde{\mathcal{A}}_{\mathrm{ansatz}} + \widetilde{\mathbf{N}}\left(\widetilde{\mathcal{A}}_{\mathrm{ansatz}}\right) \right]_n\\[.2cm]
& = \varepsilon^2 \underbrace{\left[ -3\left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0,x)|^2 \psi_1(\ell_0,x) \overline{\psi_n(\ell_0,x)} \rho(x)~dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \right]}_{=:\widetilde{B}_{n,1}}\\[.2cm]
& + \varepsilon^2 \underbrace{\left[ -3\left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(-\ell_0,x)|^2 \psi_1(-\ell_0,x) \overline{\psi_n(-\ell_0,x)} \rho(x)~dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \right]}_{=:\widetilde{B}_{n,-1}}\\[.2cm]
& + \varepsilon^2 \underbrace{\left[ -\left(\int_{0}^{\frac{2 \pi}{k_f}} \psi_1(\ell_0, x)^3 \overline{\psi_n(3\ell_0,x)}\rho(x)~ dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \right]}_{=:\widetilde{B}_{n,3}}\\[.2cm]
& + \varepsilon^2 \underbrace{\left[ -\left(\int_{0}^{\frac{2 \pi}{k_f}} \psi_1(-\ell_0,x)^3\overline{\psi_n(-3\ell_0,x)}\rho(x)~ dx\right) \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \right]}_{=:\widetilde{B}_{n,-3}} + \varepsilon^2 \lambda_n(\ell)\widetilde{B}_n \, .
\end{align*}
where we used the notation
\begin{align}\label{eq:epsilon_convonlution}
    \left( \widetilde{A}_{1,+} \star_\varepsilon \widetilde{A}_{1,+} \star_\varepsilon \widetilde{A}_{1,-} \right)(\kappa) 
= \int_{-k_f/(2\varepsilon)}^{k_f/(2\varepsilon)} \int_{-k_f/(2\varepsilon)}^{k_f/(2\varepsilon)} 
\widetilde{A}_{1,+}(\kappa - \kappa_1) \widetilde{A}_{1,+}(\kappa_1 - \kappa_2) \widetilde{A}_{1,-}(\kappa_2) 
\, d\kappa_2 \, d\kappa_1 \,,
\end{align}
which allows to read off that one gains a $\varepsilon^2$ factor in front of the nonlinear terms when changing from $\ell$ to $L_{\pm}$. This justifies the initial structure of the ``core ansatz" \eqref{eq:ansatz_bloch_diag} in retrospect. Following \cite{justification_nonlin_schr} we choose $\widetilde{A}_{1,+} = \chi_{\varepsilon, + \ell_0} \hat{A}$ and $\widetilde{A}_{1,-} = \chi_{\varepsilon, - \ell_0}\hat{\overline{A}}$ with
\begin{align}\label{eq:cut-off}
\chi_{\varepsilon, k}(\ell)
 =
 \left\{
 \begin{array}{rcl}
      1 &,& \varepsilon^{-1}(\ell-k) \in (-\pi/k_f, \pi/k_f] \, ,  \\
      0 &,& \varepsilon^{-1}(\ell-k) \notin (-\pi/k_f, \pi/k_f] \, ,  
 \end{array}
 \right.
\end{align}
and $\widetilde{A}_{1,\pm}$ continued periodically.



\subsubsection{Ginzburg-Landau equation for the non-resonant case}\label{sec:non-resonant_GL}

Assume that $k_f$ is non-resonant, then $\ell_0\neq 3\ell_0\pmod{k_f}$. Demanding that $\widetilde{A}_{1,+}$ solves the Bloch transformed Ginzburg-Landau equation
\begin{align}\label{eq:GL_Bloch}
    \partial_T \widetilde{A}_{1,+} = \left( r +  \frac12 \partial_{\ell}^2\lambda_1(\ell_0) L_{+}^2\right)\widetilde{A}_{1,+} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0,x)|^4\rho(x)~ dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \,
\end{align}
and that $\widetilde{A}_{1,-}$ solves solves the Bloch transformed Ginzburg-Landau equation
\begin{align}\label{eq:GL_Bloch_cc}
    \partial_T \widetilde{A}_{1,-} = \left( r + \frac12 \partial_{\ell}^2\lambda_1(-\ell_0) L_{-}^2\right)\widetilde{A}_{1,-} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(-\ell_0,x)|^4 \rho(x)~dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-}
\end{align}
cancels several terms in the residual. However, in order to formally achieve that the residual is of order $\mathcal{O}(\varepsilon^3)$ we further improve the ansatz to
\begin{align}\label{eq:B_n_equations}
\widetilde{B}_1 &= \frac{1}{\lambda_1(3\ell_0)}\widetilde{B}_{1,3} + \frac{1}{\lambda_1(-3\ell_0)}\widetilde{B}_{1,-3}\,, \\[.2cm]
\widetilde{B}_n &= \frac{1}{\lambda_n(\ell_0)}\widetilde{B}_{n,1} + \frac{1}{\lambda_n(-\ell_0)}\widetilde{B}_{n,-1} + \frac{1}{\lambda_n(3\ell_0)}\widetilde{B}_{n,3} + \frac{1}{\lambda_n(-3\ell_0)}\widetilde{B}_{n,-3}\,, \qquad n > 1 \, .
\end{align}
From \eqref{eq:GL_Bloch} we formally find by letting $\varepsilon\rightarrow 0$ the Fourier transformed Ginzburg-Landau equation
\begin{equation}
    \partial_T \hat{A}_{1,+} = \left( r + \frac12 \partial_{\ell}^2\lambda_1(\ell_0) L_{+}^2\right)\hat{A}_{1,+} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0,x)|^4\rho(x)~ dx\right) \hat{A}_{1,+} \star_{\varepsilon} \hat{A}_{1,+} \star_{\varepsilon} \hat{A}_{1,-} \, ,
\end{equation}
since $\int_{-k_f/(2\varepsilon)}^{k_f/(2\varepsilon)}\rightarrow \int_\mathbb{R}$. Applying the inverse Fourier transform results in the Ginzburg-Landau equation in $x$-space, equation \eqref{eq:GL_forced_SH}. Combining \eqref{eq:Bloch_expansion}, \eqref{eq:ansatz_bloch_diag}, \eqref{eq:Bloch_expansion_ansatz} and transforming this ansatz back to $x$-space yields
\begin{equation}\label{eq:ansatz_xspace}
\begin{split}
    u_{\rm Ans}(x,t) =&~ u_{\rm GL}(x,t)+ \big( \varepsilon^2 \partial_X A_1 (X,T)\partial_\ell \psi_1(\ell_0,x)e^{i\ell_0x} +\rm c.c. \big)+ \, \mathcal{O}(\varepsilon^3),
\end{split}
\end{equation}
with $u_{\rm GL}$ given in \eqref{eq:u_GL} (conf. \cite{martina_detection}).


\subsubsection{Allen-Cahn derivation}
With some small adaptations, Sections \ref{SEC:derivation} and \ref{sec:justification} can be used to prove Corollary \ref{cor:SH_approx_l00}. In case that $k_f$ and $\mu_*,\gamma_*$ are such that $\ell_0=0$, we adjust the ansatz \eqref{eq:ansatz_bloch_diag} to 
\begin{align}
   \widetilde{\mathcal{A}}_{\mathrm{ansatz}} = 
   \left( 
   \begin{array}{c}
        \widetilde{a}_1  \\
        \left(\varepsilon^2 \widetilde{B}_n\right)_{n > 1}
   \end{array}
   \right)
   \, ,
\end{align}
with
\begin{equation}
    \widetilde{a}_1(\ell,t) = \widetilde{A}_{1}\left(\frac{\ell}{\varepsilon}, \varepsilon^2t\right) \psi_1(\ell,x)
\end{equation}
and demand that $\widetilde{A}_1$ solves the Bloch transformed Allen-Cahn equation
\begin{align}\label{eq:AC_Bloch}
\begin{split}
    \partial_T \widetilde{A}_{1} = &~\left( r +  \frac12 \partial_{\ell}^2\lambda_1(0) L^2\right)\widetilde{A}_{1}
    -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(0,x)^4 \rho(x)~dx \right) \widetilde{A}_{1} \star_{\varepsilon} \widetilde{A}_{1} \star_{\varepsilon} \widetilde{A}_{1}\,.    
\end{split}
\end{align}
In order to formally achieve that the residual is of order $\mathcal{O}(\varepsilon^3)$ we further improve as before
\begin{equation}\label{eq:Bloch_expansion_ansatz_improved_AC}
\widetilde{B}_n = \frac{1}{\lambda_n(0)}\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(0,x)^3 \psi_n(0,x) \rho(x)dx\right) (\widetilde{A}_{1} \star_{\varepsilon} \widetilde{A}_{1} \star_{\varepsilon} \widetilde{A}_{1}) \,, \qquad n > 1 \, ,
\end{equation}
which is well-defined by Assumption~\ref{ASSUMP:Turing_instability}(g'). From \eqref{eq:AC_Bloch} we formally find the Fourier transformed Allen-Cahn equation
\begin{equation}
\begin{split}
    \partial_T \hat{A}_{1} = &~ \left( r + \frac12 \partial_{\ell}^2\lambda_1(0) L^2\right)\hat{A}_{1} -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(0,x)^4 \rho(x)dx\right) (\hat{A}_{1} \star_{\varepsilon} \hat{A}_{1} \star_{\varepsilon} \hat{A}_{1})\, .
\end{split}
\end{equation}
This results in the Allen-Cahn equation in $x$-space, equation (\ref{eq:AC_forced_SH}).


\subsubsection{Non-phase invariant Ginzburg-Landau derivation}
With some small adaptations, Sections \ref{SEC:derivation} and \ref{sec:justification} can be used to prove Corollary \ref{cor:SH_approx_res}. Here, as $k_f$ is resonant, we have $\ell_0= 3\ell_0\pmod{k_f}$. We use ansatz \eqref{eq:ansatz_bloch_diag} and demand that $\widetilde{A}_{1,+}$ solves the Bloch transformed non-phase invariant Ginzburg-Landau equation
\begin{align}\label{eq:GL_Bloch_res}
\begin{split}
    \partial_T \widetilde{A}_{1,+} = &~\left( r +  \frac12 \partial_{\ell}^2\lambda_1(\ell_0) L_{+}^2\right)\widetilde{A}_{1,+} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0,x)|^4 \rho(x)~dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \\ & 
    -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(\ell_0,x)^3 \overline{\psi_1(\ell_0,x)} \rho(x) dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,+}\, ,    
\end{split}
\end{align}
and that $\widetilde{A}_{1,-}$ solves a similar equation,
\begin{align}\label{eq:GL_Bloch_res_cc}
\begin{split}
        \partial_T \widetilde{A}_{1,-} = &~\left( r + \frac12 \partial_{\ell}^2\lambda_1(-\ell_0) L_{+}^2\right)\widetilde{A}_{1,-} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(-\ell_0,x)|^4 \rho(x)~dx\right) \widetilde{A}_{1,+} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \\
        & -\left(\int_{0}^{\frac{2 \pi}{k_f}} \psi_1(-\ell_0,x)^3 \overline{\psi_1(-\ell_0,x)} \rho(x)~dx\right) \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-} \star_{\varepsilon} \widetilde{A}_{1,-}\, .
\end{split}
\end{align}
In order to formally achieve that the residual is of order $\mathcal{O}(\varepsilon^3)$ we further improve the ansatz as before. Again, Assumption~\ref{ASSUMP:Turing_instability}(g') allows to derive equations for $\widetilde{B}_{n}$ such that the residual is formally of order $\mathcal{O}(\varepsilon^3)$. From \eqref{eq:GL_Bloch_res} we formally find the Fourier transformed non-phase invariant Ginzburg-Landau equation
\begin{equation}
\begin{split}
    \partial_T \hat{A}_{1,+} = &~ \left( r + \frac12 \partial_{\ell}^2\lambda_1(\ell_0) L_{+}^2\right)\hat{A}_{1,+} - 3 \left(\int_{0}^{\frac{2 \pi}{k_f}} |\psi_1(\ell_0,x)|^4 \rho(x)~dx\right) \hat{A}_{1,+} \star_{\varepsilon} \hat{A}_{1,+} \star_{\varepsilon} \hat{A}_{1,-}\\ & -\left(\int_{0}^{\frac{2 \pi}{k_f}}\psi_1(\ell_0,x)^3 \overline{\psi_1(\ell_0,x)} \rho(x)~dx\right) \hat{A}_{1,+} \star_{\varepsilon} \hat{A}_{1,+} \star_{\varepsilon} \hat{A}_{1,+}\, ,
\end{split}
\end{equation}
which in turn results in the non-phase invariant Ginzburg-Landau equation in $x$-space, equation \eqref{eq:GL_forced_SH_res}.

