\subsection*{Notation and Conventions} We follow the standard convention of using `tt’ as an abbreviation for either
`tensor-triangulated’ or `tensor-triangular’, depending on the context. Throughout this work, we assume familiarity with the basics of tt-geometry and freely use notation and terminology from \cite{Bal05} and \cite{Bal10}. Furthermore, we use the term `geometric functor' to refer specifically to a coproduct-preserving tt-functor between rigidly-compactly generated tt-categories.

Let us now highlight some of the most frequently used notation in this text:

\begin{enumerate}
\item We write $\Spc(-)$ for the Balmer spectrum functor, which is defined on essentially small tt-categories and tt-functors.
\item For a graded-commutative ring $R$, we denote its homogeneous spectrum by $\Spec^h(R)$.
\item Calligraphic symbols such as $\mathcal{P}, \mathcal{Q}, \ldots$ are used to denote prime ideals in arbitrary tt-categories.
\item Fraktur symbols such as $\pp, \qq, \ldots$ denote homogeneous prime ideals in a graded ring $R$, while $\aa, \bb, \ldots$ are reserved for \textit{cohomological primes}, i.e., prime ideals in the Balmer spectrum $\Spc(\mathbf{D}_b(\mathrm{mod}(G,R)))$.
\item For a prime ideal $\pp \in \Spec(R)$, we write $k(\pp)$ to denote the residue field of $R$ at $\pp$.
\item The notation $\iota_\pp^\ast$ is used for the functor induced by base change along the residue field $R \to k(\pp)$.
\end{enumerate}

In our treatment of complexes, we adopt homological grading. We also follow standard group-theoretic conventions: for groups $K, H, G$, we write $H^g$ to mean $g^{-1}Hg$, ${}^gH$ to mean $gHg^{-1}$, and $K \leq_G H$ to denote $G$-subconjugation, i.e., $K^g \leq H$ for some $g \in G$.



\section{Preliminaries}



Throughout this text we will work exclusively with finite groups. 

\begin{recollection}
Let $G$ be a group and $R$ be a commutative Noetherian ring.  A permutation $RG$--module $M$ is a $RG$--module isomorphic to the $R$--linearization of a $G$--set $X$. In other words, a permutation $RG$--module is a module with a $R$--basis that is also a $G$--set. In fact, any permutation $RG$--module is a coproduct of modules of the form $R(G/H)$ where $H$ is a subgroup of $G$.


We write $\Perm(G,R)$ to denote the  additive category of permutation $RG$--modules and morphisms $RG$--homomorphisms. We let   $\perm(G,R)$  denote the full subcategory of $\Perm(G,R)$ consisting of finitely generated permutation modules.  In particular, note that $\perm(G,R)$ has countably  many isomorphism classes of objects.  In general, the category $\perm(G,R)$ is not idempotent complete, however, if $k$ is a field of positive characteristic $p$ and $G$ is a  $p$-group, then  $\perm(G,k)$ is idempotent complete.      
\end{recollection}



\begin{definition}\label{def:big derived category}
    The \textit{small derived category of permutation $RG$--modules} $\K(G,R)$ is the idempotent completion of bounded homotopy category $\mathbf{K}_b(\perm(G,R))$. In symbols, 
    \[
    \K(G,R)\coloneqq\mathbf{K}_b(\perm(G,R))^\natural
    \]
    The  \textit{big derived category of permutation $RG$--modules} $\T(G,R)$ is defined as the  localizing subcategory of $\mathbf{K}(\Perm(G,R))$ generated by $\K(G,R)$. 
\end{definition}

\begin{recollection}
  The category $\Perm(G,R)$ is a tensor category with the tensor product given by $\otimes_R$ endowed with the diagonal action of $G$. This tensor product descents to $\mathbf{K}(\Perm(G,R))$, and hence equips $\T(G,R)$ with a tensor structure on which the monoidal unit is given by $R$ viewed as a complex concentrated in degree 0. In fact, 
the big derived category of permutation $RG$--modules $\T(G,R)$ is a rigidly-compactly generated tensor triangulated category, and $\K(G,R)$ sits inside $\T(G,R)$ as the rigid-compact part. We refer to \cite[Section 3]{BG21} for further details.  
\end{recollection}

\begin{remark}
    When $G$ is the trivial group, we have that $\T(1,R)=\mathbf{D}(R)$ and $\K(1,R)=\mathbf{D}_\textrm{perf}(R)$.
\end{remark}

\begin{recollection} \label{Db is a localization of KG}
  In \cite[Section 4]{BG22b}, Balmer and Gallauer showed that there is a localization functor  
  \[\bar{\Upsilon}^G\colon\T(G,R)\to \mathbf{K}_\textrm{perm}(\mathrm{Inj}(RG))\] 
  where the right-hand side category is the localizing subcategory of $\mathbf{K}( \mathrm{Inj}(RG))$ generated by Tate resolutions of permutation $RG$--modules. This functor,  on compacts, gives a localization functor 
  \[
  \Upsilon^G\colon\K(G,R)\to \mathbf{D}_\mathrm{perm}(RG)
  \]
  where the right-hand side category denotes the thick subcategory of $\mathbf{D}_b(RG)$ generated by the finitely generated permutation $RG$-modules. In particular, when $R$ is regular, there are equivalences $\mathbf{K}_\textrm{perm}(\mathrm{Inj}(RG))\simeq \mathbf{K}( \mathrm{Inj}(RG))$ and $\mathbf{D}_\mathrm{perm}(RG)\simeq \mathbf{D}_b(RG)$, see Remark \ref{Db is a localization of KG}.
\end{recollection}


\begin{remark}\label{Def of coho primes}
    Since $\Upsilon^G$ is a localization, we obtain that it induces a continuous injection on Balmer spectra 
    \[
    \Spc(\mathbf{D}_\textrm{perm}(G,R))\to \Spc(\K(G,R))
    \]
    and one often refers to the points in $\Spc(\mathbf{D}_\textrm{perm}(G,R))$ as \textit{cohomological primes}. In fact, when $R$ is a field, the above map has open image by \cite[Proposition 3.22]{BG23b}. We will extend this result to more general ground rings later in this text. 
\end{remark}

\begin{remark}\label{functoriality of K}
    Both categories $\K(G,R)$ and $\T(G,R)$ depend functorially on $G$ and $R$. It is contravariant in the group, and covariant in the ground ring. That is, for a group homomorphisms $\alpha\colon G\to G'$ we obtain a geometric tt-functor 
    \[ \alpha^\ast \colon \T(G',R)\to \T(G,R)\] 
    and we follow the usual convention regarding notation and terminology when $\alpha$ is an inclusion, surjection or conjugation. That is, depending on such properties, we may refer to the functor $\alpha^\ast$ as restriction, inflation or conjugation. On the other hand, for a map of commutative rings $f\colon R\to S$,  base change along $f$ gives a coproduct preserving tensor functor $\Mod(RG)\to \Mod(SG)$. This functor sends (finitely generated) permutation modules to (finitely generated) permutation modules. In particular, we obtain a geometric tt-functor
    \[f^\ast \colon \T(G,R)\to \T(G,S).\]
    Finally, for a prime $\pp$ in $R$, we let $\iota_\pp$ denote the residue field $R\to k(\pp)$. And hence, write $\iota_\pp^\ast\colon \T(G,R)\to \T(G,k(\pp))$ to denote the corresponding base change functor.
\end{remark}

We conclude this section by recalling the following result, which corresponds to \cite[Proposition 3.8]{BG23b}. 

\begin{proposition}\label{Spc is a point in ordinary char}
    Let $k$ be a field and $G$ be a group such that $|G|$ is invertible in $k$. Then $\Spc(\K(G,k))$ is a point. 
\end{proposition}

\section{Triangular fixed points map}\label{sec: triangular fixed points}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we let $G$ be a finite $p$-group and $R$ be an arbitrary commutative Noetherian ring. 

We briefly recall the definition of the triangular fixed points map used in \cite{Gom25} to prove the Noetherianity of the Balmer spectrum of $\K(G,R)$. These maps maps will play an analogous role as the map on triangular spectra induced by modular fixed points functor. We will also recollect some basic properties of these maps.

\begin{recollection}\label{def of K tilde}
Let $N$ be a normal subgroup of $G$. Let $\mathcal{F}_N=\{H\leq G\mid N\not\leq H\}$, and consider the full subcategory of $\perm(G,R)$ given by 
\[ \mathrm{proj}\mathcal{F}_N=\mathrm{add}^\natural\langle R(G/H)\mid H\in \mathcal{F}_N\rangle.
\]
By the Mackey formula, we obtain that this subcategory is stable under the tensor product. In particular, one has an additive monoidal quotient \[\mathrm{Quot}^G_N\colon \perm(G,R)\to \perm(G,R)/\mathrm{proj}\mathcal{F}_N.\]
That is, the objects in the right hand side are permutation $RG$--modules, and  we identify maps such that their difference factor through an element in $\mathrm{proj}\mathcal{F}_N$.
Let $\tilde{\K}(G/N,R)$ denote the category $\mathbf{K}_b(\perm(G,R)/\mathrm{proj}\mathcal{F}_N)^\natural$. In particular, we get a tt-functor \[\mathrm{Quot}^G_N\colon \K(G,R)\to \tilde{\K}(G/N,R).\]
This category will play a relevant role in the rest of this section. 
\end{recollection}

\begin{remark}
    Let $N$ be a normal subgroup of $G$. Recall that there is a tt-functor 
    \[\mathrm{Infl}_{G}^{G/N}\colon \K(G/N)\to \K(G,R)\] given by restriction along the group homomorphism $G\to G/N$. This functor is referred as inflation functor. 
\end{remark}

 We are almost ready to define triangular $N$-fixed points. The following result is \cite[Lemma 6.6]{Gom25}.

\begin{lemma}\label{composite is homeo on spectra}
    The composite functor \[\K(G/N)\xrightarrow{\mathrm{Infl}} \K(G,R)\xrightarrow{\mathrm{Quot}} \tilde{\K}(G/N,R)\]
    induces a homeomorphism on Balmer spectra.
\end{lemma}

\begin{remark}
    In the modular case, Balmer and Gallauer  showed that the composite from above is indeed an equivalence (see \cite[Proposition 5.4]{BG23b}), so the previous result follows trivially. In fact, they show that such equivalence holds even at the level of additive categories; that this, the composite 
    \[
    \perm(G/N,R)\xrightarrow[]{\mathrm{Infl}} 
\perm(G,R) \xrightarrow[]{\mathrm{Quot}} \perm(G,R)/\mathrm{proj}\mathcal{F}_N
    \]
    is an equivalence of symmetric monoidal additive categories. 
     It is easy to find examples where the latter composite is not an equivalence for $R=\mathbb{Z}$. However, we do not know whether the composite $\K(G/N)\to \K(G,R)\to  \tilde{\K}(G/N,R)$ is an equivalence. 
\end{remark}

\begin{definition}\label{triangular fixed points}
    Let $N$ be a normal subgroup of $G$. The \textit{triangular $N$-fixed points map} is the spectral map given as the composite \[\psi^{G,N}\colon \mathrm{Spc}(\K(G/N,R)) \xrightarrow{\mathrm{Spc}(\mathrm{Quot}\circ\mathrm{Infl})^{-1}} 
\mathrm{Spc}(\tilde{\K}(G/N,R)) \xrightarrow{\mathrm{Spc}(\mathrm{Quot})} \mathrm{Spc}(\K(G,R)). \]
Note that the left hand side map is precisely the inverse of homeomorphisms from Lemma \ref{composite is homeo on spectra}. 

Now, for an arbitrary subgroup $H\leq G$, we define the \textit{triangular $H$-fixed points map} as the composite    
    \[\psi^{G,H}\colon \mathrm{Spc}(\K(\WGH,R)) \xrightarrow{\psi^{N_G(H),H}} \mathrm{Spc}(\K(N_G(H),R))\xrightarrow{\rho^G_{N_G(H)}}\mathrm{Spc}(\K(G,R))\] where $\rho^G_{N_G(H)}$ denotes the map induced by the restriction functor \[\Res^G_{N_G(H)}\colon\K(G,R)\to \K(N_G(H),R).\]
\end{definition}

\begin{remark}
    Let us stress that the triangular fixed points map agrees with the map on Balmer spectra induced by the modular fixed points functor when restricted to the modular case. For further details, see \cite[Corollary 6.8]{Gom25}.
\end{remark}

The following result shows that triangular fixed points maps extend some of the good behavior of modular fixed points on Balmer spectra. 

\begin{proposition}\label{split injection normal case}
    Let $N$ be a normal subgroup of $G$. Then triangular $N$-fixed points is a continuous split injection. 
\end{proposition}

\begin{proof}
    We claim that the retraction is given by $\mathrm{Spc}(\mathrm{Infl})$. Indeed, this is an easy consequence of the definition of $\psi^{G,N}$. Let us make it explicit with the following diagram:
    \begin{center}
        \begin{tikzcd}[column sep = 5.5em, row sep = 3em]
          \mathrm{Spc}(\K(G/N,R)) \arrow[rr, bend left=20,"\psi^{G,N}"] \arrow[r,"{\mathrm{Spc}(\mathrm{Quot}\circ\mathrm{Infl})^{-1}}"] \arrow[rrd,"\mathrm{Id}"'] &
\mathrm{Spc}(\tilde{\K}(G/N,R)) \arrow[r,"\mathrm{Spc}(\mathrm{Quot})"] & \mathrm{Spc}(\K(G,R)) \arrow[d,"\mathrm{Spc}(\mathrm{Infl})"] \\ 
& & \mathrm{Spc}(\K(G/N,R))
        \end{tikzcd}
    \end{center}
   The result  follows by the functoriality of the Balmer spectrum. 
\end{proof}

\section{Koszul objects and their support}\label{sec: Kosz}

In this section, we will introduce Koszul objects which are analogous to those defined in \cite{BG23b}, and we will describe their support.  These Koszul objects play a crucial role in the set-theoretic description of the Balmer spectrum of $\K(G,R)$. More concretely, for a subgroup $H$ of $G$ we describe a bounded complex of finitely generated permutation $RG$--modules $\widetilde \kos_G(H,R)$ which in particular generates the kernel of the restriction functor $\mathrm{Res}^G_H$ as a tt-ideal. Moreover, this construction is well behaved under base change. 


For odd primes, it turns out that tensor-induction is still good enough to produce such objects. However,  for $p=2$, additional work is required. In this case, we produce Koszul objects  by refining the resolutions constructed in the proof of \cite[Theorem 3.1]{BG22}. Let us begin with some generalities on tensor-induction.


Throughout this section, we let $G$ be a finite group and let $R$ be a commutative Noetherian ring. Let us briefly recall tensor-induction for complexes. 

\begin{recollection}\label{tensor-induction}
Let $H$ be a normal subgroup of $G$ of index $n$.  Let $g_1,\ldots, g_n\in G$ be a set of representatives of the cosets $G/H$. Using  the bijection $\{1,\ldots,n\}\to G/H, \, i\mapsto [g_i]$, we get that the $G$-action on $G/H$, by multiplication on the left, induces a group homomorphism $\sigma \colon G\to S_n$. Now, consider the action of $S_n$ on $H^n$ by permuting the factors, and the associated semi-direct product $S_n\ltimes H^n$.  This allows us to define an injective group homomorphism by
\[ i\colon G\to S_n \ltimes H^n, \, g\mapsto (\sigma g, h_1, \ldots, h_n)\]
where $g\cdot g_j =g_{(\sigma g)(j)} \cdot h_j$, for all $j=1,\ldots, n$. 
Now, for a bounded complex $x$ of $RH$--modules we write  
\[{}^\otimes \Ind_H^G(x)\coloneqq i^\ast (x^{\otimes n})\] where $i^\ast$ denotes the restriction functor along $i$. Here the $S_n$-action on $x^{\otimes n}$ involves signs according to the Koszul rule. See \cite[Recollection 3.5]{BG22} for further details. 
\end{recollection}

\begin{remark}
    In the modular case, Balmer and Gallauer defined the so-called Koszul objects $\kos_G(H)$ in the derived category of permutation modules for any subgroup $H$ of $G$ using tensor-induction. Namely, 
    \[
    \kos_G(H)={}^\otimes\Ind_H^G(0\to R\to R\to 0)
    \]
    However, when $R$ is not a field, some signs appear. In particular, ${}^\otimes\Ind_H^G(0\to R\to R\to 0)$ may no longer be a complex of permutation modules, at least for $p=2$. Let us explain how to circumvent this problem. 
\end{remark}

\subsection*{Case $p=2$.} Let $G$ be a 2-group and let $R$ denote a commutative Noetherian ring.

\begin{remark}
   Recall that a $RG$--module $M$ is a sign-permutation module if it has an $R$--basis $X$, such that $G\cdot X\subseteq X\cup (-X)$. 
\end{remark}

\begin{recollection}\label{sign representation}
    Let $H$ be a subgroup of $G$ of index 2. Let $R_{\mathrm{sgn}}$ denote the one-dimensional sign representation of $G/H$, and write $L$ to denote  $\Infl^{G}_{G/H}( R_{\mathrm{sgn}})$. Note that there is a quasi-isomorphism of $RG$--modules which is obtained by inflation: 
\begin{center}
\begin{tikzcd}
\tilde{L}  \arrow[d, " s_H"']  \coloneqq & & \cdots 0 \arrow[r] & R \arrow[r] \arrow[d]  & R(G/H) \arrow[r] \arrow[d] & 0 \\
L \coloneqq & & \cdots 0 \arrow[r] & 0 \arrow[r] & L \arrow[r] & 0
\end{tikzcd}   
\end{center}
    where $L$ is concentrated in degree 0. Note that for any $K\leq H$, the restricted module $\Res^G_K(L)$ is simply the trivial representation, and $\Res^G_K(R(G/H))$ is simply two copies of the trivial module $R$. Hence $\Res^G_K(s_H)$ becomes a map of complexes of permutation modules. In fact, it becomes a homotopy equivalence. We will record this observation in the following lemma. 
\end{recollection}



\begin{lemma}\label{sH is iso}
    With the same notation as in Recollection \ref{sign representation}, we obtain that the map $\Res^G_K(s_H)$ is an isomorphism in $\K(K,R)$ for any $K\leq H$. 
\end{lemma}
\begin{proof}
    We already observed that the complexes in question are complexes of permutation modules and have trivial $K$--action. Moreover, the terms of both complexes are free as $R$--modules. Hence the cone of $\mathrm{Res}^G_K(s_H)$ is split exact and the result follows. 
\end{proof}

\begin{lemma}\label{lem:Res_vanishing}
    Let $H$ be a subgroup of $G$ of index 2.  Let $x$ be a bounded complex of permutation $RH$--modules. Then the following properties hold. 
    \begin{enumerate}
        \item Let $y$ denote the tensor-induction ${}^\otimes\Ind_H^G(x)$, which is a bounded complex of sign-permutation $RG$--modules but not necessary of permutation $RG$--modules. If $\Res^H_{H'}(x)$ is contractible for $H'\leq H$, then the complex  $\Res^{G}_K(y)$ is a contractible bounded complex, for any $K\leq H'$. 
        \item Assume that $x$ is concentrated in non-negative degrees, and  $x_0=R$ and $x_1=\Ind_K^H(z)$ for some $RK$--module $z$, and some $K\leq H$.   Then ${}^\otimes\Ind_H^G(x)_0=R$ and ${}^\otimes\Ind_H^G(x)_1=\Ind_K^G(z)$. 
    \end{enumerate}
\end{lemma}

\begin{proof}
    The first part follows from the Mackey formula for tensor-induction:
    \begin{eqnarray*}
     \Res^{G}_K({}^\otimes\Ind^{G}_{H}(x)) \simeq & \displaystyle\bigotimes_{h \in H \backslash G/K} {}^\otimes \Ind^H_{H \cap {}^hK} ({}^h \Res^{H}_{H \cap {}^hK} (x)). 
    \end{eqnarray*}
    In particular, one of the factors on the right hand side factors is a restriction of our complex of $RH$--modules $x$ which is already contractible by hypothesis. 

    The second assertion follows from the definition of the tensor-induction. In particular, ${}^\otimes\Ind_H^G(x)_1$ consists of two copies of $\Ind^H_K(z)$ and the action of $G$ will permute those copies. Hence it can be identified with $\Ind_K^G(z)$ as we wanted. 
\end{proof}

\begin{lemma}\label{lem:sgn_modification}
    Let $H$ be a subgroup of $G$ of index 2.  Let $x$ be a non-negative bounded acyclic complex of  sign-permutation $RG$--modules satisfying: 
    \begin{enumerate}
        \item $\Res^G_H(x)$ is a complex of permutation $RG$--modules.  
       \item $x_0$ is the trivial module $R$. 
       \item $x_1$ is of the form $\Ind^G_K(z)$ for some $RK$--module $z$, and $K\leq H$. 
       \item $\Res^G_{H'}(x)$ is contractible for some $H'\leq H$.
    \end{enumerate}
    The we can inductively modify $x$ in finitely many steps to get a non-negative bounded acyclic complex $\tilde{x}$ of  permutation 
$RG$--modules satisfying:
\begin{enumerate}
    \item $\tilde{x}_0$ is the trivial module $R$. 
       \item $\tilde{x}_1$ is of the form $\Ind^G_K(z')$ for some $RK$--module $z'$.
       \item $\Res^G_{H'}(\tilde{x})$ is contractible.
\end{enumerate}
\end{lemma}

\begin{proof}
    This is essentially contained in the proof of Theorem 3.1 of \cite{BG22}. Hence the task is to verify that such modification of the complex satisfies the required properties. Let $L$ be the sign representation and consider the map $s_H$ from Recollection \ref{sign representation}.  The complex $x$ can be modified inductively; say $x^{m+1}$ is such a way that $x^{ m+1}_j$ is  a permutation $RG$--module for any $j \geq m+1$. Additionally $x^{ m+1}_0$ is either $L$ or $R$ and $x^{ m+1}_1$ is a module of the form $\Ind_K^G(z)$ for some $RK$--module $z$. The modification is done using descending induction. Since the complex is bounded, the conditions on $x$ will hold for some $m+1$ large enough. Hence fix $m+1$ satisfying the previous conditions. 
    Define $x^{ m} \coloneqq \mathrm{cone}(s_H \otimes t^m)$ where $t^m$ is a morphism of complex defined as:
\begin{center}
\begin{tikzcd}
x^{m+1'}  \arrow[d, " t^m"']  \coloneqq &  \cdots  x^{m+1}_{m+2} \arrow[r] \arrow[d] & x^{ m+1}_{m+1} \arrow[r] \arrow[d]  & (x^{ m+1}_m)^{+} \arrow[r] \arrow[d] & 0 \arrow[d]  \cdots \\
x^{m+1 ''} \coloneqq & \cdots   0 \arrow[r] & L \otimes (x^{m+1}_m)^{-} \arrow[r] &  x^{ m+1}_{m - 1} \arrow[r] &  x^{ m+1}_{m - 2} \cdots
\end{tikzcd}   
\end{center}
here we are using the decomposition of $RG$--modules
\[ 
x^{ m+1}_m=(x^{ m+1}_m)^{+} \oplus (L \otimes (x^{m+1}_m)^{-})
\]
given in Lemma 3.9 of \cite{BG22}; in particular both $(x^{ m+1}_m)^{+}$ and $(x^{ m+1}_m)^{-}$ are permutation $RG$--modules. We can check that  $x^{m}_j$ is a permutation $RG$--module for any $j \geq m$ and $x^{m}$ has the required properties which completes the induction step. Indeed, since $L\otimes L\simeq R$ and $\Res^G_K(L)\simeq R$, we obtain that  $x^m_m$ is a permutation module, $x^m_0$ is either $R$ or $L$ and $x^m_1$ is still a module of the form $\Ind_{K}^G(z)$ for some $z$ by the projection formula. Finally, we need to verify this induction step preserves the condition $(3)$. But this follows by Lemma \ref{sH is iso} and our assumption about the contractibility of  $x^{m+1}$ when restricted to $H'\leq H$. That is, $\Res^G_H(s_H\otimes t^m)$ is a homotopy equivalence. Thus the result follows. 
\end{proof}

\begin{definition}\label{def sign mod}
The modification in the above lemma will be referred to as \emph{sign-modifications}.
\end{definition}

\begin{construction}\label{kos in char 2}
    Let $H$ be a subgroup of $G$. We will construct a complex $\widetilde{\kos}_G(H,R)$ of permutation $RG$--modules with the following properties: 
    \begin{enumerate}
        \item $\widetilde{\kos}_G(H,R)_0=R$.
        \item $\widetilde{\kos}_G(H,R)_1$ is of the form $\Ind_H^G(x)$ for some $RH$--module $x$. 
        \item $\mathrm{Res}^G_H(\widetilde{\kos}_G(H,R))\simeq 0$ in $\K(H,R)$.
    \end{enumerate}
The construction is inductive on the index of $H$ in $G$. Consider a normal filtration
\[
H_0 = H \trianglelefteq H_1 \trianglelefteq H_2 \trianglelefteq \ldots \trianglelefteq H_l=G
\]
where $H_i/H_{i-1}$ has order $2$, for any $i=1,\ldots,l$. Now, let $y^0$ denote the complex of $kH_0$--modules $(0\to R\xrightarrow[]{1} R\to 0)$. For $i>0$, we define $y^i$ as the sign modification (see Definition \ref{def sign mod}) of the complex 
${}^\otimes\Ind_{H_{i-1}}^{H_i}(y^{i-1})$. We let $\widetilde{\kos}_G(H)\coloneqq y^l$. Since the base of the inductive definition satisfies the desired properties, so does $\widetilde{\kos}_G(H)$ by Lemma \ref{lem:sgn_modification}. In particular, let us stress that $y^1$ does not need any sign modification. 
\end{construction}



\subsection*{General case.} Let $G$ be a $p$-group. We already mentioned that tensor-induction for odd primes is good enough to produce Koszul objects. Let us record this in a uniform fashion. 


\begin{definition}\label{notation for kos}
    Let $H$ be a subgroup of $G$. We write $\widetilde{\kos}_G(H,R)$ to denote either ${}^\otimes\Ind_H^G(0\to R\to R\to 0)$ if $p>2$; or  the complex $\widetilde{\kos}_G(H,R)$ from Construction \ref{kos in char 2} if $p=2$. We will refer to these objects as \textit{Koszul objects}.
\end{definition}

\begin{remark}\label{three conditions satisfied by kos}
    Note that $\widetilde{\kos}_G(H,R)$ is an acyclic complex of permutation $RG$--modules satisfying that $\widetilde{\kos}_G(H,R)_0=R$ and $\widetilde{\kos}_G(H,R)_1$ is module of the form $\Ind_H^G(z)$ for some $RH$--module $z$. Indeed,  for $p>2$, by \cite[Lemma 3.8]{BG22} we know that any sign-permutation module is a permutation module. Moreover, since the complex $0\to R\to R\to 0$ is acyclic, its tensor-induction remains acyclic. Finally, the description of the module in degree 0 and degree follows from the definition of tensor-induction, and it is similar to \cite[Proposition 3.15]{BG23b}. For $p=2$, this follows from construction (see Construction \ref{kos in char 2}).
\end{remark}

We are ready to describe one of the most relevant properties of Koszul objects. In fact, it would be a consequence of the construction and a very general result in \cite[Corollary 3.20]{BG23b}. Let us include the statement here for convenience of the reader. 

\begin{lemma}\label{conditions to generated a given ideal}
    Let $\A$ be a rigid tensor category and $\mathcal{I}$ be a thick tensor ideal of $\mathbf{K}_b(\A)$. Let $x$ be a bounded complex in $\mathcal{I}$ satisfying the following properties. 
    \begin{enumerate}
        \item $x$ is concentrated in non-negative degrees. 
        \item The  thick tensor ideal generated by  $x_0$ contains $\mathcal I$.
        \item $x_1\otimes y\simeq 0$ in $\mathbf{K}_b(\A)$ for any $y\in \mathcal I$.
    \end{enumerate}
    Then $x$ generates $\mathcal{I}$ as a thick tensor ideal. 
\end{lemma}

\begin{corollary}\label{supp of kos}
  Let $H \leq G$. Consider the restriction functor $\Res^G_H\colon \K(G,R)\to \K(H,R)$. Then $\widetilde{\kos}_G(H, R)$ generates $\ker(\Res^G_H)$ as a thick tensor ideal. In symbols,  
  \[
  \ker(\Res^G_H) = \langle \widetilde{\kos}_G(H, R)\rangle.
  \]
  Equivalently, $\mathrm{supp}(\widetilde{\kos}_G(H, R))=\mathrm{supp}(\ker(\Res^G_H))$ in $\Spc(\K(G,R))$. In particular, $\K_{ac}(G, R) = \ker(\Res^G_1) = \langle \widetilde{\kos}_G(1, R) \rangle$.
\end{corollary}


\begin{proof}
This follows from Lemma \ref{conditions to generated a given ideal}. Indeed, the required three properties of $\widetilde{\kos}_G(H, R)$ follow by Remark \ref{three conditions satisfied by kos}.
\end{proof}


\begin{corollary}
    The localization functor $\Upsilon^G\colon \K(G,R)\to \mathbf{D}_{\mathrm{perm}}(RG)$ induces an open inclusion on Balmer spectra. The complement of its image is the support of $\K_{ac}(G,R)$. 
\end{corollary}

Let us conclude this section with an observation on the behavior of the Koszul objects under base change along the reside fields of $H$. We need some preparation. 

\begin{recollection}\label{restriction under base change}
    Let $H$ be a subgroup of $G$, and let $\pp\in \mathrm{Spec}(R)$. Then we have a commutative square 
    \begin{center}
        \begin{tikzcd}
               \K(G,R) \arrow[r,"\iota_\pp^\ast"] \arrow[d,"\mathrm{Res}_{H,R}"'] & \K(G,k(\pp)) \arrow[d,"\mathrm{Res}_{H,k(\pp)}"] \\
               \K(H,R) \arrow[r,"\iota_\pp^\ast"]  & \K(H,k(\pp)).
        \end{tikzcd}
    \end{center}
    In particular, we have that $\iota_\pp^\ast(\mathrm{Ker}(\mathrm{Res}_{H,R}))\subseteq \mathrm{Ker}(\mathrm{Res}_{H,k(\pp)})$. We will drop the base ring from the notation if the context is clear. 
\end{recollection}

\begin{corollary}\label{supp of kos under base ch}
Let $\pp\in \mathrm{Spec}(R)$. Then $\iota_\pp^\ast(\widetilde{\kos}_G(H,R))$ generates the same thick tensor ideal in $\K(G,k(\pp))$ as $\mathrm{kos}_G(H,k(\pp))$.    
\end{corollary}

\begin{proof}
Note that the previous statement is trivial if the characteristic of $k(\pp)$ is not $p$. Then assume otherwise.  We claim that $\iota_\pp^\ast(\widetilde{\kos}_G(H,R))$ generates $\ker(\Res^G_H)$, and hence the result will follow by \cite[Proposition 3.21]{BG23b}. But this follows by another application of Lemma \ref{conditions to generated a given ideal}. Indeed,  $\iota_\pp^\ast(\widetilde{\kos}_G(H,R))\in \ker(\Res^G_H)$ by Recollection \ref{restriction under base change} and satisfies the following conditions: $\iota_\pp^\ast(\widetilde{\kos}_G(H,R))_0=R\otimes_R k(\pp)\cong k(\pp)$ and $\iota_\pp^\ast(\widetilde{\kos}_G(H,R))_1=\Ind_H^G(z)\otimes_R k(\pp)\cong \Ind^G_H(z\otimes_R k(\pp))$ (see Definition \ref{notation for kos} and Remark \ref{three conditions satisfied by kos}). Then  $\iota_\pp^\ast(\widetilde{\kos}_G(H,R))$ generates  $\ker(\Res^G_H)$. 
\end{proof}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{The Balmer spectrum as a set}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we will describe the points of the Balmer spectrum of $\K(G,R)$ for $G$ a $p$-group and $R$ a commutative Noetherian ring. Let us record the following result which is a reformulation of  \cite[Theorem 6.11]{Gom25} and its proof. Let us first set some notation.

\begin{notation}
  For each subgroup $H$ of $G$, consider the composite map
  \[
  \check \psi^{G,H}\colon V_{\WGH,R}\xrightarrow{\Spc(\Upsilon^{\WGH})} \Spc(\K(\WGH,R))\xrightarrow[]{\psi^{G,H}} \Spc(\K(G,R)) 
  \]
  where $V_{\WGH,R}$ is denotes $\Spc(\mathbf{D}_{\mathrm{perm}}(R\WGH))$. Here $\mathbf{D}_{\mathrm{perm}}(R\WGH)$ denotes the thick subcategory of $\mathbf{D}_b(R\WGH)$ generated by permutation $R\WGH$--modules, see Recollection \ref{Db is a localization of KG} if needed.  
\end{notation}

\begin{theorem}\label{cover of spc KG}
    Let $G$ be a $p$-group and $R$ be a commutative Noetherian ring. Then the maps $\check \psi^{G,H}$ determine a continuous surjection 
  \[
  \coprod_{H\leq G}V_{\WGH,R} \xrightarrow[]{\coprod \check \psi^{G,H}} \Spc(\K(G,R)).
  \]
\end{theorem}

\begin{recollection}\label{Spc of Dperm}
    Recall that an $RG$--lattice is an $RG$--module that is projective as $R$--module. Consider the exact structure on the additive category of finitely generated $RG$--lattices induced by the split exact structure on the category of finitely generated projective $R$--modules. See Section \ref{section:invertible objects}. Let $\mathbf{D}_b(G,R)$ denote the bounded  derived category of finitely generated $RG$--lattices associated with this exact structure (see \cite[Section 2.1]{BBIKP} for further details).  This is a tt-category with the monoidal structure induced by $\otimes_R$ with the diagonal action of $G$. By work of Lau \cite{Lau23}, we know that the comparison map  
    \[ \Spc(\mathbf{D}_b(G,R))\to \Spec^h(\End_{\mathbf{D}_b(G,R)}^\ast(R))\]
    is an homeomorphism. Recall that  $\End_{\mathbf{D}_b(G,R)}^\ast(R)$ identifies with the cohomology ring $H^\ast(G,R)$. 

    Now, note that $\mathbf{D}_\mathrm{perm}(RG)\subseteq\mathbf{D}_b(G,R)$. In fact, they agree for $R$ regular. In any case, both categories have the same monoidal unit, and their graded endomorphism ring agree.  By the naturality of the comparison map we get a commutative diagram 
    \begin{center}
        \begin{tikzcd}
             \Spc(\mathbf{D}_b(G,R)) \arrow[r] \arrow[d,"\mathrm{Comp}"']  &  \Spc(\mathbf{D}_\mathrm{perm}(G,R)) \arrow[d,"\mathrm{Comp}"] \\
             \Spec^h(H^\ast(G,R)) \arrow[r,"\cong"] &  \Spec^h(H^\ast(G,R))
        \end{tikzcd}
    \end{center}
    which tells us that the right hand side map is a bijection since the top map is a surjection. Hence it is homeomorphism by \cite[Corollary 2.8]{Lau23} since $\mathbf{D}_\mathrm{perm}(RG)$ is End-finite. This homeomorphisms will be used to translated certain properties of the spectrum of $\mathbf{D}_\mathrm{perm}(RG)$ under base change along residue fields of $R$. 
 \end{recollection}


 For convenience, let us record the following result which appears in the proof of \cite[Theorem 6.11]{Gom25}. 

\begin{proposition}\label{base change and triangular fixed points}
    Let $H$ be a subgroup of $G$, and let $\pp\in \Spec(R)$. Then the following diagram is commutative. 
    \begin{center}
        \begin{tikzcd}
        V_{\WGH,k(\pp)}  \arrow[d,"\Spc(\lambda_\pp^\ast))"'] \arrow[r,"\check \psi^{G,H}_\pp"]  & \Spc(\K(G,k(\pp))) \arrow[d,"\Spc(\iota^\ast_\pp)"] \\ V_{\WGH,R} \arrow[r,"\check \psi^{G,H}"]  & \Spc(\K(G,R))
        \end{tikzcd}
    \end{center}
    where $\lambda_\pp^\ast$ is short for the left derived base change functor $-\otimes^L_Rk(\pp)\colon \mathbf{D}_\mathrm{perm}(R\WGH)\to \mathbf{D}_\mathrm{perm}(k(\pp)\WGH)$. 
\end{proposition}

\begin{remark}\label{cohomological primes from residue fields}
    By  \cite{Lau23}, we know that the functors $\lambda_\pp^\ast$, from  the previous proposition, determine a bijection on Balmer spectra: 
    \[
    \coprod_{\pp\in \mathrm{Spec}(R)} V_{G,k(\pp)} \to V_{G,R}
    \] 
    for any finite group $G$ and any commutative Noetherian ring $R$.
\end{remark}

\begin{definition}
     Let $H$ be a subgroup of $G$, and $\aa$ be a \textit{cohomological prime} in  $V_{\WGH,k(\pp)}=\Spc(\mathbf{D}_\textrm{perm}(k(\pp)\WGH))$ for some $\pp\in \Spec(R)$. Define a prime of $\K(G,R)$ by  
    \[
    \P_{G, R}(H, \aa,\pp) \coloneqq \check \psi^{G,H} (\Spc(\lambda_\pp^\ast) (\aa)) = \Spc(\iota^\ast_\pp) (\check \psi^{G,H}_\pp (\aa))\in \Spc(\K(G,  R)).
    \] 
   Note that the equality comes from the square in Proposition \ref{base change and triangular fixed points}. If the context is clear, we will forget about the subscript and simply write $\P(H,\aa,\pp)$. 
\end{definition}

\begin{remark}\label{all points in K(G) are come from check psi}
    By Theorem \ref{cover of spc KG} combined with Remark \ref{cohomological primes from residue fields}, we get that any point of $\mathrm{Spc}(\K(G,R))$ is of the form $\P(H,\aa,\pp)$ for some $H\leq G$, $\pp\in \Spec(R)$ and $\aa\in V_{\WGH,R}$. 
\end{remark}



\begin{corollary}\label{comparison for check psi to residue fields}
     Let $H$ be a subgroup of $G$, and let $\pp\in \Spec(R)$. Then the following diagram is commutative. 
      \begin{center}
        \begin{equation}\label{check psi under base change and comparison}
           \begin{tikzcd}
        V_{\WGH,k(\pp)} \arrow[rr, bend left=25] \arrow[d,"\Spc(\lambda_\pp^\ast))"'] \arrow[r,"\check \psi^{G,H}"]  & \Spc(\K(G,k(\pp)))  \arrow[d,"\Spc(\iota^\ast_\pp)"] \arrow[r] & \Spec(k(\pp))\arrow[d,"\Spec(\iota_\pp)"] \\ V_{\WGH,R} \arrow[r,"\check \psi^{G,H}"] \arrow[rr, bend right=25]  & \Spc(\K(G,R)) \arrow[r] & \Spec(R)
        \end{tikzcd}
    \end{equation}
    \end{center}
    where all unlabeled arrows correspond to the comparison map from Balmer spectra to the homogeneous spectrum of the endomorphism ring of  the monoidal unit. 
\end{corollary}

\begin{proof}
    The left square is commutative by Proposition  \ref{base change and triangular fixed points}; the right square is commutative from the naturality of the comparison map. For the bottom triangle the strategy is as follows. Unpack the definition of $\check\psi^{G,H}$ and consider the following diagram.  
    \begin{center}
    \begin{tikzcd}
   \Spc(\K(\WGH,R)) \arrow[dr]  & \arrow[l,"\xi"'] \Spc(\tilde{\K}(\WGH,R)) \arrow[r,"\xi'"] \arrow[d] & \Spc(\K(N_G(H),R)) \arrow[ld] \arrow[d,"\rho^G_{N_G(H)}"] \\ V_{\WGH,R} \arrow[u,"\Spc(\Upsilon^{\WGH})"] \arrow[r]   & \Spec(R) & \Spc(\K(G,R)) \arrow[l] 
    \end{tikzcd}
\end{center}
where $\xi$ and $\xi'$ denote $\Spc(\mathrm{Quot}\circ\mathrm{Infl})$ and $\Spc(\mathrm{Quot})$, respectively; and all the unlabeled arrows are the respective comparison map between Balmer and Zariski spectra. Now, the naturality of the comparison map tells us that each of the small triangles is commutative. It follows that the bottom triangle in \ref{check psi under base change and comparison} is commutative. In the same fashion, one verifies the commutativity of the upper triangle in \ref{check psi under base change and comparison}. This completes the result.  
\end{proof}




\begin{corollary}\label{cohomological primes over different fibers}
    Let $\P(H,\aa,\pp)$ and $\P(K,\aa',\pp')$ be points in $\Spc(\K(G,R))$ for some $H,K\leq G$, $\pp,\pp'\in \Spec(R)$ and $\aa\in V_{\WGH,k(\pp)}$ and $\aa'\in V_{\WGK,k(\pp')}$. If $\pp\not=\pp'$. Then $\P(H,\aa,\pp)\not=\P(K,\aa',\pp')$.
\end{corollary}

\begin{proof}
    This follows from Corollary \ref{comparison for check psi to residue fields}. Indeed, using the  comparison map from $\Spc(\K(G,R))$ to $\Spec(R)$,  we obtain that $\mathrm{Comp}(\P(H,\aa,\pp))=\pp$ and similarly  $\mathrm{Comp}(\P(K,\aa',\pp'))=\pp'$.
\end{proof}




Recall the Koszul objects from Definition \ref{notation for kos}. We now explain a relation between these objects and the primes $\P(H,\aa,\pp)$. 


\begin{lemma}\label{lem:koszul_conjugate_subgroups_ker}
     Let $H$ and $H'$ be subgroups of $G$, $\pp\in \Spec(R)$ and  $\aa \in V_{\Weyl{G}{H'},k(\pp)}$. Suppose that the characteristic of $k(\pp)$ is $p$. Then $\widetilde{\kos}_G(H,R)\in \P_{G, R}(H', \aa,\pp) $ if and only if $H' \leq_G H$. 
\end{lemma}


\begin{proof}
Unpacking the definitions, we get that 
\begin{equation}\label{P under iota}
  \iota^\ast_\pp(\P_{G,R}(H', \aa,\pp))\subseteq \check\psi^{G,H'}_\pp(\aa)\eqqcolon \P_{G, k(\pp)}(H', \aa) 
\end{equation}
where the prime $\P_{G, k(\pp)}(H', \aa)$ is precisely  one of those defined in \cite[Definition 7.4]{BG23b}.
If $\widetilde{\kos}_G(H,R)\in \P_{G, R}(H', \aa,\pp)$, then by Equation \ref{P under iota}, we obtain that 
\[
\langle \kos_G (H, k(\pp)) \rangle = \langle \iota_\pp^* (\widetilde{\kos}_{G}(H, R)) \rangle\subseteq \P_{G, k(\pp)}(H',\aa)
\]
where the first equality follows from Corollary \ref{supp of kos under base ch}. Then $H'\leq_G H$ by  \cite[Lemma 7.12]{BG23b}. 

The converse is similar. Indeed,  assume that $H'\leq_G H$.  By definition, 
\[
\P_{G, R}(H', \aa,\pp) = (\iota_\pp^\ast)^{-1}\P_{G,k(\pp)}(H',\aa).
\]
 But by Corollary  \ref{supp of kos under base ch} we have 
 \[
 \iota_\pp^* (\widetilde{\kos}_{G}(H, R))\in \langle \kos_G (H, k(\pp)) \rangle.
 \]
 Another layer of  \cite[Lemma 7.12]{BG23b} gives us that $\kos_G (H, k(\pp))\in \P_{G,k(\pp)}(H',\aa)$ and hence so is $\iota_\pp^* (\widetilde{\kos}_{G}(H, R))$. We conclude that $\widetilde{\kos}_{G}(H, R)\in \P_{G, R}(H',\aa,\pp)$.
\end{proof}


\begin{remark}\label{rem:primes in coprime char}
    Let $\pp\in \Spec(R)$ such that the characteristic of $k(\pp)$ is coprime to $p$. In this case, note that $\P(H,\aa,\pp)=\P(H',\aa,\pp)$ for any subgroup $H\leq G$. Indeed, this follows since the maps $\check\psi^{G,H}$ factor through $\Spc(\K(G,k(\pp)))$, and the latter is a point. This explains the relevance of the characteristic of $k(\pp)$ in the previous result. 
\end{remark}


\begin{corollary}\label{cor:inclusions of P}
Let $H$ and $H'$ be subgroups of $G$, and let $\pp\in \Spec(R)$ such that the characteristic of $k(\pp)$ is $p$.  If $\P_{G, R}(H, \aa,\pp) \subseteq \P_{G, R}(H', \aa',\pp)$ then $H' \leq_G H$. Therefore if $\P_{G, R}(H, \aa,\pp) = \P_{G, R}(H', \aa',\pp)$ then $H$ and $H'$ are $G$--conjugate.
\end{corollary}

\begin{proof}
    This follows from  Lemma \ref{lem:koszul_conjugate_subgroups_ker} since 
    \[\widetilde{\kos}_G(H, R) \in \P_{G, R}(H, \aa,\pp) \subseteq \P_{G, R}(H', \aa',\pp)\]
    holds if and only if $H' \leq_G H$. The second part follows by symmetry of the argument.
\end{proof}


We are almost ready to describe the set $\Spc(\K(G,R))$ in terms of $\Spc(\K(G,k(\pp)))$. We need some preparations first.


\begin{recollection}\label{primes under homeo induced by conjugation}
   Let $G$ be a subgroup of $G'$, and let $g$ be an element in $G'$. Then the conjugation homomorphism $c_g: G \xrightarrow{} G^g, \, h\mapsto h^g$,  induces a tt-equivalence $c_g^*\colon \K(G, R) \xrightarrow{\sim} \K(G^g, R)$ and hence a homeomorphism
\[
(\_)^g \coloneqq \Spc(c_g^*)\colon \Spc(\K(G, R)) \xrightarrow{\sim} \Spc(\K(G, R)); \,  \P \mapsto \P^g.
\]
In particular, if $g \in G$, the functor $c_g^*\colon \K(G, R) \xrightarrow{\sim} \K(G, R)$
 is isomorphic to the identity and therefore $\P^g = \P$ for all   $\P \in \Spc(\K(G, R))$. See Section 4.1 of \cite{BG23b} for more details.
\end{recollection}

\begin{recollection}\label{primes P under restriction}
We want to record the behavior of the primes $\P(H,\aa,\pp)$ under tt-functors induced by group homomorphisms. This follows a similar pattern as \cite[Remark 7.6]{BG23b}. 
    Let $\alpha\colon G \to G'$ be a group homomorphism, and let $H$ be a subgroup of $G$. Let $H' = \alpha(H) \leq G'$. Then $\alpha(N_G(H)) \leq N_{G'}(H')$ and hence induces a morphism $\bar{\alpha}\colon \WGH \to \Weyl{G'}{H'}$. Let $\pp\in \mathrm{Spec}(R)$. We claim that
 \[
 \Spc(\alpha^*)(\P_G(H, \aa,\pp)) = \P_{G'}(H', \Spc(\bar{\alpha}^*) (\aa),\pp)
 \]
     in $\Spc(\K(G', R))$, where $\alpha^*$ is the restriction functor along $\alpha$; similarly the functor  $\bar{\alpha}^*\colon \mathbf{D}_\mathrm{perm}(\WGH, R) \to \mathbf{D}_\mathrm{perm}(\Weyl{G'}{H'}, R)$ is the derived restriction functor induced by $\bar{\alpha}$. Indeed, 
     we only need to verify that the following square is commutative.
     \begin{center}
         \begin{tikzcd}[column sep = 3em]
             V_{\Weyl{G'}{H'},k(\pp)} \arrow[r,"\Spc(\bar \alpha^\ast)"] \arrow[d,"\Spc(\lambda_\pp^\ast)"'] & V_{\Weyl{G'}{H'},k(\pp)}  \arrow[d,"\Spc(\lambda_\pp^\ast)"]  \\        
             V_{\Weyl{G'}{H'},R} \arrow[r,"\Spc(\bar \alpha^\ast)"] \arrow[d,"\check \psi^{G',H'}"'] & V_{\Weyl{G'}{H'},R}  \arrow[d,"\check \psi^{G,H}"]  \\ 
             \Spc(\K(G',R)) \arrow[r,"\Spc(\alpha^\ast)"] & \Spc(\K(G,R))
         \end{tikzcd}
     \end{center}
    Now, recall that the functors $\Upsilon^G$ are well behaved under group homomorphism (see \cite[Remark 4.1]{BG23b}), and the category $\K(-,R)$  functorial along group homomorphisms (see Remark \ref{functoriality of K}). Unpacking the definition of $\check\psi^{G,H}$ we observe that it is enough to check that the following diagram is commutative
    \begin{center}
        \begin{tikzcd}
            \K(N_G(H),R) \arrow[r, "\alpha^*"] \arrow[d,"\mathrm{Quot}"'] & \K(N_{G'}(H'), R) \arrow[d, "\mathrm{Quot}"]\\
            \tilde{\K}(\WGH, R) \arrow[r, "\bar{\alpha}^*"] & \tilde{\K}(\Weyl{G'}{H'}, R)
        \end{tikzcd}
    \end{center}
    which is easy to check. In particular we get the following two particular cases. 
    \begin{enumerate}
        \item Let $H\leq K\leq G$, and $\aa\in V_{\Weyl{K}{H},k(\pp)}$. Then 
        \[ \rho_H(\P_K(H,\aa,\pp))=\P_G(H,\bar\rho_H(\aa),\pp).\]
        \item Let $G\leq G'$, $g\in G'$, and $\aa\in V_{\WGH,k(\pp)}$. Then 
        \[
         \P_G(H,\aa,\pp)^g= \P_{G^g}(H^g,\aa^g,\pp).
        \]
    \end{enumerate}
\end{recollection}

\begin{recollection}\label{image of restriction}
    Let $H\leq G$, and let $(A_H,\mu,\eta)$ be the commutative algebra with $A_H=R(G/H)$, multiplication is given by $\mu(\gamma\otimes \gamma')=\gamma $ if $\gamma=\gamma'$ in $G/H$ or $0$ otherwise,  and  unit $\eta(1)=\sum_{\gamma\in G/H} \gamma$.  This algebra is separable and has finite degree; a section is given by the map $\gamma \mapsto \gamma\otimes \gamma$. Moreover, following \cite{Bal17}, we can identify modules in $\K(G,R)$ over $A_H$ with the category $\K(H,R)$ and via this identification restriction becomes extension of scalars and induction becomes the forgetful functor.  
   Then we can apply \cite[Theorem 3.19]{Bal16} to obtain a coequalizer of topological spaces 
   \[\coprod_{[g]\in H\backslash G/H}\mathrm{Spc}(\K(H\cap{}^gH,R))\rightrightarrows \mathrm{Spc}(\K(H,R)\xrightarrow{\rho^G_H} \mathrm{supp}(A_H)\] 
   where one of the left hand side arrows is induced by restriction and the other is induced by conjugation along $[g]$ followed by restriction. Further details  appear in \cite[Proposition 4.7]{BG23b}.
\end{recollection}



\begin{proposition}\label{psi check is injective}
    Let $H $ be a subgroup of $G$, and $\pp\in \Spec(R)$. If $\P_{G, R}(H, \aa,\pp) = \P_{G, R}(H, \aa',\pp)$, then $\aa = \aa'$. In particular, 
    \[
    \check\psi^{G,H}_\pp\colon V_{\WGH,k(\pp)}\to \Spc (\K(G,R))
    \]
    is injective.
\end{proposition}

\begin{proof}
Note that the statement is trivial if the characteristic of $k(\pp)$ is not $p$ since $V_{\WGH,k(\pp)}$ is a point. Hence assume that $k(\pp)$ has characteristic $p$. In this case, the argument is essentially the same as the one in the proof of \cite[Proposition 4.14]{BG23b}. For completeness, let us include the details. Let $N=N_G(H)$. By the definition of triangular fixed points we have \[\rho^G_N(\P_{N, R}(H, \aa,\pp)) = \rho^G_N(\P_{N, R}(H, \aa',\pp)).\] 
 Now, by Recollection \ref{image of restriction} we obtain that there is $g\in G$ together with a point $\mathcal{Q}$ in $\mathrm{Spc}(\K(N\cap{}^gN,R))$ such that 
 \begin{equation}\label{image of Q}
     \rho^N_{N\cap{}^gN}(\mathcal{Q})= \P_{N, R}(H, \aa,\pp) \mbox{ and }  {}^g(\rho^{{}^gN}_{N\cap{}^gN}(\mathcal{Q}))= \P_{N, R}(H, \aa',\pp)
 \end{equation}
Moreover, $\mathcal{Q}$ is of the form  $\P_{N\cap{}^gN,R}(L, \aa'',\pp)$ for some $L\leq N\cap{}^gN$, and some cohomological prime $\aa''\in V_{N\cap{}^gN /\!\!/ L, k(\pp)}$ (See Remark \ref{all points in K(G) are come from check psi}). Now, using Recollection \ref{primes P under restriction}, we know the behavior of the $\mathcal{Q}$ under the map on Balmer spectra induced by restriction:  
\[
\P_{N, R}(H, \aa,\pp)=\rho^N_{N\cap{}^gN}(\mathcal{Q})=\P_{N,R}(L,\bb,\pp) 
\]
and similarly for the map induced by conjugation 
\[
\P_{N, R}(H, \aa',\pp)= {}^g(\rho^{{}^gN}_{N\cap{}^gN}(\mathcal{Q}))= \P_{N,R}(L^g,\bb',\pp)
\]
for suitable cohomological primes $\bb\in V_{N/\!\!/ L,k(\pp)}$ and $\bb'\in V_{N/\!\!/ L^g,k(\pp)}$. By Corollary \ref{cor:inclusions of P}, we deduce that $L\sim_N H\sim_N L^g$. But $H$ is normal in $N$, and hence $L=H=L^g$. In particular, $g\in N$. Thus $N\cap N^g=N$ and $N^g=N$. This equalities applied to Equation \ref{image of Q} give us that $\P_{N,R}(H,\aa,\pp)=\mathcal{Q}=\mathrm{Q}^g=\P_{N,R}(H,\aa',\pp)$. Since $H\trianglelefteq N$, we can invoke Proposition \ref{split injection normal case} which tell us that 
\[
\psi^{N,H}\colon \mathrm{Spc}(\K(H,R))\to \mathrm{Spc}(\K(N,R))
\]
is a split injection. We conclude that $\aa=\aa'$ as we wanted.  
\end{proof}


\begin{theorem}\label{primes in spc up to conj}
    Every prime ideal of $\K(G, R)$ is of the form $\P_{G, R}(H, \aa,\pp)$ for some subgroup $H$ of $G$, some $\pp\in \Spec(R)$ and some cohomological prime $\aa\in V_{\WGH,k(\pp)}$. Moreover, the following properties hold.
    \begin{enumerate}
        \item If the characteristic of $k(\pp)$ is $p$, then $\P_{G, R}(H, \aa,\pp) = \P_{G, R}(H', \aa',\pp)$  if and only if there exists  $g \in G$ such that $H' = H^g$ and $\aa = \aa^g$. 
        \item If the characteristic of $k(\pp)$ is not $p$, then $\P_{G, R}(H, \aa,\pp) = \P_{G, R}(H', \aa',\pp)$ for any $H\leq G$, and any $\aa\in V_{\WGH,k(\pp)}$. 
        \item $\P_{G, R}(H, \aa,\pp) \not= \P_{G, R}(H', \aa',\pp')$ as soon as $\pp\not= \pp'$.
    \end{enumerate} 
\end{theorem}

\begin{proof}
    The first claim follows from Remark \ref{all points in K(G) are come from check psi}. Part $(1)$ is an immediate consequence of Corollary \ref{cor:inclusions of P}, Proposition \ref{psi check is injective}, and the behavior of primes under restriction along homomorphisms of groups (see Recollection \ref{primes P under restriction}). Part $(2)$ is Remark \ref{rem:primes in coprime char}. Part $(4)$ is Corollary \ref{cohomological primes over different fibers}. 
\end{proof}



We can now combine the previous results to give an alternative set-theoretic description of the Balmer spectrum of $\K(G,R)$.

\begin{proposition}\label{Spc as a set}
   There is a set bijection induced by base change along all residue fields of $R$: 
   \[
   \coprod_{\pp\in\mathrm{Spec}(R)} \mathrm{Spc}(\K(G,k(\pp))) \xrightarrow[]{} \mathrm{Spc}(\K(G,R)).
   \]
 \end{proposition}


\begin{proof}
First of all, consider the following diagram. 
\begin{center}
        \begin{tikzcd}[column sep = 4em]
            \displaystyle\coprod_{\pp\in \Spec(R)} \Spc(\K(G,k(\pp))) \arrow[d, "\mathrm{Comp}"'] \arrow[r, "\Spc(\iota_\pp^\ast)"] & \Spc (\K(G, R)) \arrow[d,"\mathrm{Comp}"]\\
           \displaystyle\coprod_{\pp\in \Spec(R)} \Spec(k(\pp)) \arrow[r,"\sim"] & \mathrm{Spec}(R)
        \end{tikzcd}
    \end{center} 
and note that this diagram is commutative by the naturality of the comparison map. Hence, we only need to prove that  the map $\Spc(\iota_\pp^\ast)$ is injective for each $\pp\in \Spec(R)$. If the characteristic of $k(\pp)$ is coprime to $p$, then this is trivial. Assume otherwise. The result follows from  Theorem \ref{primes in spc up to conj}. Indeed, this theorem tells us that the  map 
\[
\displaystyle\coprod_{H\in \mathrm{Sub}(G)/G} V_{\WGH,k(\pp)} \xrightarrow[]{\coprod\Spc(\iota_\pp^\ast)\circ \check\psi^{G,H}_\pp} \Spc(\K(G,R)) 
\]
is injective. But this map, by definition, factors through $\Spc(\K(G,k(\pp)))$. Then the result follows by \cite[Proposition 7.32]{BG23b} which states that $\coprod \psi^{G,H}_\pp$ is a bijection. 
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Reduction to elementary abelian groups}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Let $G$ be a $p$-group and $R$ a commutative Noetherian ring. In this section, we reduce the computation of the Balmer spectrum of $\K(G,R)$ to the elementary abelian case. In other words, we show that $\Spc(\K(G,R))$ decomposes as a colimit indexed over the category of elementary abelian $p$-sections of $G$, generalizing \cite[Theorem 11.10]{BG23b}. Our strategy is slightly different from the one in \textit{loc. cit.}; in particular, we need some general results about spectral spaces. Let us deal with this first. 



\begin{recollection}\label{reflection funtor}
    Let  $\mathrm{Top}_{\mathrm{Spec}}$ and  $\mathrm{Top}$ denote the categories of spectral spaces and topological spaces, respectively. The \textit{spectral reflection functor} $\mathrm{Top} \to \mathrm{Top}_{\mathrm{Spec}}$ is the left adjoint to the forgetful functor. Write $S_X\colon X\to S(X)$ to denote the unit of this adjunction.  Let us highlight that the spectral reflection of a space is a homeomorphism if and only if the space is spectral and Noetherian. See \cite[Theorem 7.1]{Schwartz17}. 

    On the other hand, recall that the category of sober spaces is a reflective subcategory of $\mathrm{Top}$. The  left adjoint is called \textit{soberification} and it is denoted by $\mathrm{Sob}$. Let $\mathrm{Sob}_X\colon X\to \mathrm{Sob}(X)$ denote the unit of this adjunction. We highlight that $\mathrm{Sob}_X$ is a homeomorphism if and only if it is a bijection if and only if  $X$  is already sober. 
\end{recollection}

\begin{lemma}\label{spectral criteria}
  Let $X$ be a Noetherian topological space. Assume that the following properties hold. 
\begin{enumerate}
    \item There is a continuous bijection $f\colon X\to Y$ with $Y$ a Noetherian spectral space.  
    \item There is a surjection $g\colon Z\to X$ with $Z$ a sober space. 
\end{enumerate}
  Then $X$ is a Noetherian spectral space. 
\end{lemma}

\begin{proof}
   It is enough to prove that $X$ is sober. First, consider the following commutative diagram. 
    \begin{center}
        \begin{tikzcd}
          X \arrow[r,"f"]  \arrow[d,"S_X"'] & Y \arrow[d,"S_Y"] \\ 
            S(X) \arrow[r,"S(f)"] & S(Y)
        \end{tikzcd}
    \end{center} 
    and by our assumption, the right vertical map is a homeomorphism (see Recollection \ref{reflection funtor}). By the commutativity of the square, the left vertical map is injective, hence $X$ is a $T_0$ space (see \cite{Schwartz17}). Similarly, consider the commutative diagram induced by the soberification. 
    \begin{center}
        \begin{tikzcd}
          Z \arrow[r,"g"]  \arrow[d,"\mathrm{Sob}_Z"'] & X \arrow[d,"\mathrm{Sob}_X"] \\ 
            \mathrm{Sob}(Z) \arrow[r,"\mathrm{Sob}(g)"] & \mathrm{Sob}(X)
        \end{tikzcd}
    \end{center}
    Now, the the left vertical map is a homeomorphism since $Z$ is sober; the bottom map is surjective since epimorphisms in topological spaces are simply continuous surjections. It follows that the right vertical map is also surjective. Moreover, we already proved that $X$ is $T_0$, then $\mathrm{Sob}_X\colon X\to \mathrm{Sob}(X)$ is also injective. It follows that $X$ is sober and hence spectral.   
\end{proof}

We will also need the following straightforward result. 

\begin{lemma}\label{criteria for open maps}
    Let $f\colon X\to Y$ be a continuous spectral bijection between Noetherian spectral spaces. Then $f$ is a homeomorphism if and only if $f$ lifts specializations.  
\end{lemma}

\begin{proof}
   Let $Z$ be a closed subset of  $X$. Then $f(Z)$ is constructible in $Y$. By assumption on $f$, we deduce that $f(Z)$ is specialization closed. But constructible and specialization closed subsets are closed. We conclude the result.  
\end{proof}

Those are all the abstract results we need, so let’s get back to the derived category of permutation modules. In order to state the main result of this section, we need to recall the construction of \textit{the category of elementary abelian sections $\mathcal{E}(G)$ of $G$}; see \cite[Construction 11.1]{BG23b}.




\begin{recollection}\label{rec category of p sections}
     Let $\mathcal{E}(G)$ denote the category whose objects are pairs $(H,K)$ such that $K\unlhd H\leq G$, and $H/K$ is elementary abelian; a morphisms in this category from  $(K,H)$ to $(K',H')$ corresponds to an element $g$ of $G$ such that 
     \[
     K'\leq K^g\leq H^g \leq H'
     \]
     and the composition of morphisms is given by the multiplication in $G$. 
\end{recollection}

\begin{construction}
    Let $R$ be a commutative Noetherian ring. For an object $(H,K)$ in $\mathcal{E}(G)$, we will consider the tt-category $\K(H/K,R)$. For a morphism $g$ in $\mathcal{E}(G)$ we define a morphism $\mathrm{Spc}(\K(g))$ on Balmer spectra as the composition 
    \begin{center}
    \begin{tikzcd}
\mathrm{Spc}(\K(H/K,R)) \arrow[r,"\mathrm{Spc}(c_g^\ast)"]  
&    \mathrm{Spc}(\K(H^g/K^g,R)) \arrow[d, phantom, ""{coordinate, name=Z}]
\arrow[d,
rounded corners,"\rho_{K^g/K^g}",
to path={ -- ([xshift=4ex]\tikztostart.east)
 |- (Z) [near start]\tikztonodes
-|([xshift=-4ex]\tikztotarget.west)
-- (\tikztotarget)}]
 &  \\
  & \mathrm{Spc}(\K(H'/K^g,R)) \arrow[r,"\psi^{\bar K}"] & \mathrm{Spc}(\K(H'/K',R)) 
\end{tikzcd}
\end{center}
 \noindent  here $\rho_{K^g/K^g}$ denotes the induced map by the restriction functor, and  $\psi^{\Bar{K}}$ denotes the triangular fixed points map, and  $\Bar{K}=K^g/K'$. We are also using that $(H'/K')/\Bar{K}=H'/K^g$. This defines a functor $\Xi_G$ from $\mathcal{E}(G)^\textrm{op}$ to topological spaces.  

 On the other hand,  for each object $(H,K)$ in $\mathcal{E}(G)$, we obtain a map $\varphi_{(H,K)}$ of topological spaces as the composition \[
 \mathrm{Spc}(\K(H/K,R))\xrightarrow{\psi^{H,K}} \mathrm{Spc}(\K(H,R))\xrightarrow{\rho^G_H} \mathrm{Spc}(\K(G,R)).
 \] 
 In fact, unpacking the definition of triangular fixed points we can verify that the following square is commutative. 
 \begin{center}
    \begin{tikzcd}[column sep = 4em]
        \Spc(\K(H/K,R)) \arrow[r,"\psi^{H,K}"] \arrow[d,"\rho_{H/K}"'] & \Spc(\K(H,R)) \arrow[d,"\rho_H"] \\
        \Spc(\K(\WGK,R)) \arrow[r,"\psi^{G,K}"'] & \Spc(\K(G,R))
     \end{tikzcd}
\end{center}
using that $H\leq N_G(K)$. Moreover, the maps $\varphi_{(H,K)}$ are compatible with the morphisms in $\mathcal{E}(G)$, as we will show later.
\end{construction}

 \begin{remark}
     If $R$ is a field, then the functor $\Xi_G$ agrees with the functor defined in \cite[Construction 11.4]{BG23b}, since the map on spectra induced by modular fixed points agrees with the triangular fixed points map, see Section \ref{sec: triangular fixed points}. 
 \end{remark}

 \begin{remark}
    In contrast with the field case, the maps $\varphi_{(H,K)}$ are not necessarily closed in our generality. A key step in the field case was to show that, for a normal subgroup $N \unlhd G$, the modular $N$-fixed points functor induces a closed immersion on Balmer spectra (see \cite[Proposition 7.18]{BG23b}). This result followed by showing that the image of $\check \psi^{G,N}$ corresponds to the support of the tt-ideal $\bigcap_{\mathcal{F}_H} \Ker(\Res^G_H)$, where $\mathcal{F}_H = \{ K \leq G \mid H \not\leq K\}$. However, this rarely happens in our generality, since $\Ker(\Res^G_H)$ is only supported on $\Spc(\K(G,k(\pp)))$ for $k(\pp)$ of characteristic $p$. Indeed, if the characteristic of $k(\pp)$ is not $p$, then $\mathrm{supp}(\iota^\ast_\pp \Ker(\Res^G_H)) = \varnothing$ since $\K(G,k(\pp))$ is semisimple. Nevertheless, this will still play a relevant role here.
 \end{remark}


\begin{proposition}
     Let $g\colon (H,K)\to (H',K')$ be a morphism in $\mathcal{E}(G)$. Then the following diagram of topological spaces is commutative. 
\begin{center}
    \begin{tikzcd}[column sep = 4em]
        \Spc(\K(H/K,R)) \arrow[r,"\varphi_{(H,K)}"] \arrow[d,"\Spc(\K(g))"'] & \Spc(\K(G,R)) \\
        \Spc(\K(H'/K',R)) \arrow[ru,"\varphi_{(H',K')}"']
     \end{tikzcd}
\end{center}
 In particular, we obtain a continuous map 
 \begin{equation}\label{comparison with colim}
\varphi\colon \underset{(H,K)\in \mathcal{E}(G)^\textrm{op}}{\colim} \mathrm{Spc}(\K(H/K,R))\to \mathrm{Spc}(\K(G,R))     
 \end{equation}
whose component at $(H,K)$ is precisely $\varphi_{(H,K)}$.  
 \end{proposition}

\begin{proof}
Our strategy is to unpack the definition of the maps $\varphi_{(-,-)}$ and $\Spc(\K(-))$ in order to break the above diagram into triangles that would be commutative from the functoriality of the Balmer spectrum. In order to ease notation, let us omit the ground ring $R$ from the notation.  
Recall that the map $\Spc(\K(g))$ is the composite $\psi^{\bar K}\circ \rho^{H/K^g}_{H'/K^g} \circ\Spc(c^\ast_g)$, where $\bar K=K^g/K'$. Let us begin by showing that the following diagram is commutative.  
\begin{center}
\begin{equation}\label{triangle for cg}
    \begin{tikzcd}[column sep = 4em]
        \Spc(\K(H/K)) \arrow[r,"\varphi_{(H,K)}"] \arrow[d,"\Spc(c^\ast_g)"'] & \Spc(\K(G)) \\
        \Spc(\K(H^g/K^g)) \arrow[ru,"\varphi_{(H^g,K^g)}"']
     \end{tikzcd}
\end{equation}
\end{center}
Consider the following  diagram 
\begin{center}
     \begin{tikzcd}[column sep = 3em]
    \K(G) \arrow[r,"\mathrm{Res}"] \arrow[rd,"\mathrm{Res}"']  &  \K(H) \arrow[r,"\mathrm{Qout}"] \arrow[d,"c_g^\ast"] & \tilde{\K}(H/K) \arrow[d,"c_g^\ast"] & \arrow[l,"\mathrm{Qout}\circ\mathrm{Infl}"'] \K(H/K) \arrow[d,"c_g^\ast"]  \\ 
     &  \K(H^g) \arrow[r,"\mathrm{Qout}"']  & \tilde{\K}(H^g/K^g) & \arrow[l,"\mathrm{Qout}\circ\mathrm{Infl}"] \K(H^g/K^g)
     \end{tikzcd}
\end{center}
here  $ \tilde{\K}(H/K)$ is the category $\mathbf{K}_b(\perm(H)/\mathrm{proj}\mathcal{F}_K)^\natural$, see Section \ref{sec: triangular fixed points}. Note that the diagram is commutative. Indeed, the left triangle is commutative since it is induced by restriction. Also, the inflation functor is compatible with restriction along the conjugation by $g$, hence it remains to check that the quotient functor is also compatible with conjugation. But this is clear since for a subgroup $L$ of $H$ such that $L\not \leq K$, we have that $L^g\leq H^g$ and $L\not \leq K^g$.  Now, the commutativity of the Diagram \ref{triangle for cg} follows by applying the functor $\mathrm{Spc}(-)$ and noticing that the top and bottom arrows are precisely the ones given $\varphi_{(H,K)}$ and $\varphi_{(H^g,K^g)}$, respectively. 

In the same fashion, we can verify the following identities:  
\begin{enumerate}
    \item $\varphi_{(H^g,K^g)} = \varphi_{(H',K^g)} \circ \rho^{H/K^g}_{H'/K^g}$. 
    \item $\varphi_{(H',K^g)} =  \varphi_{(H',K')}  \circ \psi^{\bar K}$.
\end{enumerate}
We deduce that $\varphi_{(H',K')}\circ \Spc(\K(g))=\varphi_{(H,K)}$.
The second claim is clear. 
\end{proof}


\begin{theorem}\label{colimit theorem}
    The comparison map \[\varphi\colon \underset{{(H,K)\in \mathcal{E}(G)^\textrm{op}}}{\colim} \mathrm{Spc}(\K(H/K,R))\to \mathrm{Spc}(\K(G,R))  \] from Equation \ref{comparison with colim} is a homeomorphism. 
\end{theorem}

Our strategy is as follows. We will first show that the map $\varphi$ is a continuous bijection. From this, we will deduce that the colimit space is indeed a Noetherian spectral space. The last step consists in showing that  specializations lift along $\varphi$.

\begin{proposition}\label{varphi is injective}
    The map $\varphi$ is a continuous bijection over an arbitrary Noetherian base $R$. 
\end{proposition}


\begin{proof}
     Let $\pp\in \mathrm{Spec}(R)$. Then the comparison map 
 \[\varphi_{k(\pp)}\colon \underset{{(H,K)\in \mathcal{E}(G)^\textrm{op}}}{\colim} \mathrm{Spc}(\K(H/K,k(\pp)))\to \mathrm{Spc}(\K(G,k(\pp)))  \]
 is an homeomorphism. Indeed, if the characteristic of $k(\pp)$ is not $p$, then the left hand side correspond to the connected components of $\mathcal{E}(G)$. But since $G$ is 
a $p$-group, we get that any $(H,K)$ has a zig-zag of maps to $(1,1)$ (just use a maximal normal series of the subgroup $H$). It follows that $\varphi_{k(\pp)}$ is a homeomorphisms in this case since both sides are a point. On the other hand, if the characteristic of $k(\pp)$ is $p$, then it follows from \cite[Theorem 11.10]{BG23b}. Now, let us consider the following commutative diagram obtained from base change along all residue fields of $R$. 
 \begin{center}
    \begin{tikzcd}
       \displaystyle \coprod_{\pp\in\mathrm{Spec}(R)} 
 \underset{(H,K)\in \mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,k(\pp))) \arrow[r,"\coprod\varphi_{k(\pp)}"] \arrow[d] & \displaystyle \coprod_{\pp\in\mathrm{Spec}(R)} \mathrm{Spc}(\K(G,k(\pp))) \arrow[d] \\ 
\displaystyle  \underset{(H,K)\in\mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,R)) \arrow[r,"\varphi"] & \mathrm{Spc}(\K(G,R))
    \end{tikzcd}
\end{center}
    here we are using that coproducts commute with colimits to rewrite the top left corner. Now, note that the top map is a bijection by the previous observation; the  vertical maps are bijections by Proposition \ref{Spc as a set}. It follows that $\varphi$ is also a bijection as we wanted.
\end{proof}

\begin{corollary}\label{colim is noetherian spectral}
    The space $\colim_{(H,K)\in \mathcal{E}(G)^\textrm{op}} \mathrm{Spc}(\K(H/K,R))$ is a Noetherian spectral space. 
\end{corollary}

\begin{proof}
    The Noetherianity is clear since it is a quotient of a Noetherian space. The second claim follows from Lemma \ref{spectral criteria} applied to $\varphi$ and to the quotient from $\coprod_{(H,K)\in \mathcal{E}(G)^\textrm{op}} \mathrm{Spc}(\K(H/K,R))$ to $\colim_{(H,K)\in \mathcal{E}(G)^\textrm{op}} \mathrm{Spc}(\K(H/K,R))$. 
\end{proof}

In order to proceed, we need some terminology. 

\begin{definition}\label{def: modular fiber}
Let $G$ be a $p$-group. The \textit{modular fiber of $\Spc(\K(G,R))$} is the preimage of the point $(p)$ under the composition
\[
\Spc(\K(G,R))\xrightarrow[]{\rho} \Spec(R)\xrightarrow[]{\eta} \Spec(\mathbb Z)
\]
where $\rho$ denotes Balmer’s comparison map between the triangular spectrum and the Zariski spectrum, and $\eta$ denotes the structural map of $R$. We write $\Spc(\K(G,R))_{(p)}$ to denote the modular fiber. The \textit{ordinary fiber of  $\Spc(\K(G,R))$} is the set theoretic complement of the modular fiber. 
\end{definition}

\begin{recollection}\label{rec: modular fiber of colim}
   Consider the canonical map from the proof of Proposition \ref{varphi is injective}
   \[
  \mu\colon \coprod_{\pp\in\mathrm{Spec}(R)} 
 \underset{(H,K)\in \mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,k(\pp))) \to  \underset{(H,K)\in\mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,R))
   \]
   Let $\colim_{(H,K)\in\mathcal{E}(G)^\mathrm{op}} \Spc(\K(H/K,R))_{(p)}$ denote the image of 
   \[
   \coprod_{\pp\in\eta^{-1}(p)} 
 \underset{(H,K)\in \mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,k(\pp))). 
   \]
   under $\mu$. By Proposition \ref{Spc as a set}, we deduce that $\varphi$ induces a bijection
   \[
  \underset{(H,K)\in\mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,R))_{(p)}\to \Spc(\K(G,R))_{(p)} 
   \]
 In fact, we will see that this is actually a homeomorphisms. 
\end{recollection}

\begin{lemma}\label{lemma: rest of varphi is homeo}
 The restriction of the comparison map 
 \[
 \varphi\colon \underset{(H,K)\in\mathcal{E}(G)^\mathrm{op}}{\colim} \Spc(\K(H/K,R))_{(p)} \to \Spc(\K(G,R))_{(p)}
 \]
 is a a homeomorphism. Here we are considering both spaces with the subspace topology. 
\end{lemma}

We need the following result. 

\begin{proposition}\label{psi is closed normal case}
    Let $H$ be a normal subgroup of $G$. Then the restriction of  triangular $H$-fixed points map 
    \[\psi^{G,H}_{(p)}\coloneqq\psi^{G,H}\colon \Spc(\K(G/H,R))_{(p)}\to \Spc(\K(G,R))_{(p)}\]
    is a closed map. Its image agrees with the support of the tt-ideal $\bigcap_{\mathcal{F}_H}\Ker(\Res^G_K))$, where $\mathcal{F}_H=\{K\leq G\mid H\not\leq K\}.$ 
\end{proposition}

\begin{proof}
  Recall that the Koszul object $\widetilde{\kos}_G(H,R)$ generates the tt-ideal $\Ker(\Res^G_H)$, and hence they have the same support (see Corollary \ref{supp of kos}). We will show that the image of $\psi^{G,H}_{(p)}$ is precisely $\bigcap_{\mathcal{F}_H}\mathrm{supp}(\widetilde{\kos}_G(H,R))$ which will complete the result since the latter is closed. 

    Consider the following commutative square induced by base change along the residue fields. 
    \begin{center}
        \begin{tikzcd}[column sep = 3em]
            \displaystyle\coprod_{\pp\in \eta^{-1}(p)} \Spc(\K(G/N,k(\pp))) \arrow[d,"\coprod \Spc \iota_\pp^\ast"'] \arrow[r, "\coprod\psi^{H}_{k(\pp)}"] & \displaystyle\coprod_{\pp\in \eta^{-1}(p)} \Spc (\K(G, k(\pp))) \arrow[d,"\coprod\Spc\iota_\pp^\ast"]\\
            \Spc(\K(G/N,R)_{(p)} \arrow[r,"\psi^{G,H}_{(p)}"] & \Spc(\K(G,R))_{(p)}
        \end{tikzcd}
    \end{center} 
Recall that the vertical maps are bijections by Proposition \ref{Spc as a set} combined with the definition of the modular fiber.
By this observation, we obtain that $\mathrm{Im}(\psi^{G,H}_{(p)})$ coincides with $\mathrm{Im}( \coprod \mathrm{Spc}\iota_\pp^\ast \circ \coprod \psi^{G,H}_\pp)$.  We also recall the behavior of the support of Koszul objects under base change; namely
\begin{equation}\label{base change of kosz}
\langle\iota_\ast\widetilde{\kos}_G(H,R)\rangle = \langle \kos_G(H,k(\pp))\rangle.    
\end{equation}
Moreover, we have  
\begin{align*}
\mathrm{Im}\left(\coprod  \psi^{G,H}_\pp\right) & =  \coprod \bigcap_{K\in \mathcal{F}_H} \mathrm{supp}(\kos_G(K,k(\pp)))    \\
 & = \coprod \bigcap_{K\in \mathcal{F}_H} \mathrm{supp}(\iota_\pp^\ast \widetilde\kos_G(K,R)) \\
 &= \coprod \Spc(\iota_\pp^\ast)^{-1} \bigcap_{K\in \mathcal{F}_H} \mathrm{supp}(\widetilde\kos_G(K,R))
\end{align*}
where the first equality holds by \cite[Proposition 7.18]{BG23b}; the second equality follows by Equation \ref{base change of kosz}; and the last one is simply the behavior of the support with respect to tt-functors together with the injectivity of $\mathrm{Spc}(\iota_\pp^\ast)$. Since $\coprod \mathrm{Spc}(\iota_\pp^\ast)$ is a bijection, we get 
\begin{align*}
    \mathrm{Im}(\psi^{G,H}_{(p)}) &= \coprod \mathrm{Spc}(\iota_\pp^\ast)(\coprod \Spc(\iota_\pp^\ast)^{-1} \bigcap_{K\in \mathcal{F}_H} \mathrm{supp}(\widetilde\kos_G(K,R)))  \\ 
    &= \bigcap_{K\in \mathcal{F}_H} \mathrm{supp}(\widetilde\kos_G(K,R)))
\end{align*}
which completes the proof.
\end{proof}

\begin{corollary}\label{psi is closed}
    Let $H$ be an arbitrary subgroup of $G$. Then the restriction of the triangular $H$-fixed points map 
    \[\psi^{G,H}_{(p)}\coloneqq \psi^{G,H}\colon \Spc\K(G/H,R)_{(p)} \to \Spc(\K(G,R))_{(p)}\]
    is a closed map. 
\end{corollary}


\begin{proof}
    Recall that $\psi^{G,H}$ is defined as the composite $\rho^G_{N}\circ\psi^{N,H}$, where $N$ denotes $N_G(H)$. The map $\rho^G_{N}$ is closed by Recollection \ref{image of restriction}, and $\psi^{N,H}_{(p)}$ is closed by Proposition \ref{psi is closed normal case}. We conclude by noticing that the modular fiber is a closed subset of the spectrum by definition. 
\end{proof}

\begin{corollary}\label{transition maps are closed}
    Let $(H,K)\in \mathcal{E}(G)$. Then the restriction of the transition map 
    \[\varphi_{(H,K),(p)}\coloneqq \varphi_{(H,K)}\colon \K(H/K,R)_{(p)} \to \Spc(\K(G,R)) \] lies in $\Spc(\K(G,R))_{(p)}$. In particular, $\varphi_{(H,K),(p)}$ is a closed map. 
\end{corollary}

\begin{proof}
     Both claims follow from the definition of the map together with  the fact that triangular fixed points map restricted to the modular fiber is closed by Corollary \ref{psi is closed}, and also the map on spectra induced by restriction is closed by Recollection \ref{image of restriction}.
\end{proof}


\begin{proof}[Proof of Lemma \ref{lemma: rest of varphi is homeo}]
  This follows by combining the fact that the modular fiber is a closed subset, Corollary \ref{transition maps are closed}, and Recollection \ref{rec: modular fiber of colim}.
\end{proof}




%--------------------------------------------------------------------------------

\begin{proof}[Proof of Theorem \ref{colimit theorem}]
    In view of  Lemma \ref{criteria for open maps} and Corollary \ref{colim is noetherian spectral}, we are left to prove $\varphi$ is spectral and that specializations lift along $\varphi$.  The first claim follows by noticing that the colimit agrees with the colimit in the category of spectral spaces. For the second claim, fix  $\P\in \colim_{(H,K)\in \mathcal{E}(G)^\textrm{op}} \mathrm{Spc}(\K(H/K,R))$. Let $\pp$ be the image of $\varphi(\P)$ under the comparison map, and $q$ be the characteristic of the residue field $k(\pp)$. We have two cases. First, assume that  $p=q$. In this case, $\varphi(\P)$ is in the modular fiber which is a closed subset. Hence $\overline{\varphi(\P)}$ must be contained in the modular fiber as well. We conclude this case by Lemma \ref{lemma: rest of varphi is homeo}.  



 Now, assume that $p\not=q$. Let $\mathcal{Q}\subseteq \varphi(\P)$, equivalently $\mathcal{Q}\in \overline{\varphi(\P)}$. We already know that the map 
\[
\coprod_{(H,K)\in \mathcal{E}(G)^\textrm{op}} \mathrm{Spc}(\K(H/K,R)) \xrightarrow[]{\varphi'} \Spc(\K(G,R))
\]
is surjective. Here $\varphi'$ is short for $\amalg\varphi_{(H,K)}$. Let $(H',K'),(H,K)\in \mathcal{E}(G)$, together with $\P'\in\Spc(\K(H'/K',R))$ and $\mathcal{Q}'\in \Spc(\K(H/K,R))$ such that $\varphi'(\P')=\varphi(\P)$ and $\varphi'(\mathcal{Q}')=\mathcal{Q}$.  Moreover, note that for any $p$-group $H$, $\Spc(\K(H,R[1/p]))\cong \Spec( R[1/p])$. Indeed, the comparison map in this case is a bijection, hence a homeomorphism since the category $\K(G,R[1/p])$ is End-finite (see \cite[Lemma 2.8]{Lau23}). In particular, we deduce that  $\varphi(\P)$ is in $\Spec(R[1/p])$ via such identification. Since the category $\mathcal{E}(G)$ is connected, and maps in there act trivially on the part of the spectrum corresponding to $\Spec(R[1/p])$, we can find a zig-zag of maps from $(H,K)$ to $(H',K')$ that allows to  identify $\P'$ with an element $\P''$ in $\Spc(\K(H/K,R))$ and such that $\varphi_{(H,K)}(\P'')=\varphi(\P)$.  In other words, we can assume that both $\varphi(\P)$ and $\mathcal{Q}$ are in the image of the map $\varphi_{(H,K)}= \rho^G_H\circ \psi^{H,K}$. 



Recall that the map $\rho^G_H$ is closed, and hence it lifts specializations. In particular, from the specialization
\[
\rho^G_H(\psi^{H,K}(\P'')) \rightsquigarrow
 \mathcal{Q}
\]
we obtain that there is prime $\mathcal{L}\in \Spc(\K(H,R))$ such that $\rho^G_H(\mathcal{L})=\mathcal{Q}$ and 
\[
\psi^{H,K}(\P'') \rightsquigarrow
 \mathcal{L}.
\]
On the other hand, by the coequalizer in Recollection \ref{image of restriction}, we get that there is $g\in G$ and $\mathcal{L}'\in\Spc(\K(H\cap{}^gH,R))$ such that \begin{equation}
     \rho^N_{N\cap{}^gN}(\mathcal{L}')=\psi^{H,K}(\mathcal{Q})  \mbox{ and }  {}^g(\rho^{{}^gN}_{N\cap{}^gN}(\mathcal{L}'))=\mathcal{L}
 \end{equation}
In particular, we deduce that both points $\mathcal{L}$ and $\psi^{H,K}(\mathcal{Q})$ can be identified in the colimit. Hence, we can replace the prime $\mathcal{Q}'$ in such a way that we end up in the following situation. $\varphi'(\mathcal{Q}')=\mathcal{Q}$, and 
\[
\psi^{H,K}(\P'') \rightsquigarrow
 \psi^{H,K}(\mathcal{Q}')
\]
in $\Spc(\K(H,R))$. By Proposition \ref{split injection normal case}, we get  $\P''\rightsquigarrow \mathcal{Q}'$. Now, consider the quotient map 
\[
\mathbf{q}\colon \coprod_{(H,K)\in \mathcal{E}(G)^\textrm{op}} \mathrm{Spc}(\K(H/K,R))\to \underset{{(H,K)\in \mathcal{E}(G)^\textrm{op}}}{\colim} \mathrm{Spc}(\K(H/K,R)).
\] 
In particular, we get that  $\mathbf{q}(\mathcal{Q}')$ is in the closure of $\mathbf{q}(\P'')=\P$ in the colimit.  Moreover, $\varphi(\mathbf{q}(\mathcal{Q}'))=\mathcal{Q}$. This completes the proof. 
\end{proof}



