\section{Tensor invertible objects}
\label{section:invertible objects}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Throughout this section, we let $G$ be a $p$-group. Unfortunately, we will soon need to place some additional assumptions on our ground ring, but for the moment, let us still consider $R$ to be a commutative Noetherian ring.

Our goal in this section is to introduce some tensor-invertible objects in the category $\K(G,R)$ that will allow us to extend the Balmer-Gallauer twisted cohomology ring in greater generality. Invertible objects in this category has been extensively studied in the modular case, we refer to the work of Miller \cite{Mil24} for an account. 

\subsection*{Frobenius structure on lattices.} Recall that the group algebra $kG$ is  a Frobenius algebra when the ground ring $k$ is a field and hence, projective $kG$--modules and  injective $kG$--modules agree. However, the group algebra is not necessarily Frobenius over arbitrary commutative rings, and in general projectives do not have to agree with injectives. We will restrict ourselves to work in the full subcategory $\mathrm{Mod}(G,R)$  of $\mathrm{Mod}(kG)$ on $RG$--lattices, that is, $RG$--modules that are projective as $R$--modules. Once and for all, let us fixed the exact structure on  $\mathrm{Mod}(G,R)$ induced by the split exact structure on $\mathrm{Proj}(R)$. In fact, this exact structure turns $\mathrm{Mod}(G,R)$ into an exact Frobenius category.  We will record the following result for the ease of reference, a proof can be found in \cite[Section 2]{BBIKP}. 

\begin{proposition}\label{Frobenius structure}
The category of $RG$--lattices $\Mod(G,R)$ is an exact subcategory of $\Mod(RG)$ with the exact structure given by the split exact sequences of $R$--modules. In fact, $\Mod(G,R)$ is a Frobenius exact category where the injectives and projectives are given as the additive closure of the injective $RG$--modules and the additive closure of projective $RG$--modules, respectively. 
\end{proposition}


\begin{remark}
Note that permutation modules are indeed lattices. We consider   $\mathrm{Perm}(G,R)$ as a full subcategory of $\mathrm{Mod}(G,R)$.    
\end{remark}

\subsection*{Invertible objects for $C_p$} Let $R$ be a commutative Noetherian ring,  $C_p=\langle \sigma\rangle$ be the cyclic group of prime order $p$ and $RC_p$ be the group algebra. Note that $RC_p = R[\sigma]/(\sigma^p - 1)$. Recall that there is a periodic resolution which computes the cohomology of $C_p$: 
\begin{align}\label{eq:standar resolution}
    \ldots \xrightarrow{\mathbf{N}} RC_p  \xrightarrow{\sigma-1}  RC_p\xrightarrow{\mathbf{N}} RC_p \xrightarrow{\sigma -1} RC_p \xrightarrow{\epsilon} R\to 0
\end{align}

\noindent where $\mathbf{N}$ denotes the \textit{norm map} which is given by multiplying with $1+\sigma+\ldots+ \sigma^{p-1}$, and $\epsilon$ denotes the augmentation map.    





\begin{definition}\label{def: uN}
  Let $u_{p,R}$ denote the complex of $RC_p$--modules: 
  \begin{enumerate}
      \item $0 \to  RC_p \xrightarrow{\epsilon} R \to 0$ if $p=2$; or
      \item $0 \to RC_p \xrightarrow{\sigma-1} RC_p \xrightarrow{\epsilon} R \to 0$, if $p>2$. 
  \end{enumerate}
In both cases the copy of $R$ is considered in degree 0.  Moreover, note that  the complex $u_{p,R}$ is obtained as a brutal truncation of the complex given in \ref{eq:standar resolution}. If the context is clear, we will drop $R$ from the notation and simply write $u_p$. 
\end{definition}


\begin{remark}
Recall that the tensor structure on $\mathrm{Perm}(G,R)$ given by the tensor product with diagonal $G$--action endows $\K(G,R)$ with a symmetric monoidal structure where the monoidal unit is $R$ viewed as a complex concentrated in degree 0. In particular, makes sense to talk about \textit{invertible objects}; explicitly, we say that $x\in \K(G,R)$ is $\otimes$-invertible if there exists $y \in \K(G,R)$ such that $x\otimes y\simeq R$. We will see that  $u_{p,R}$ are examples of invertible objects extending the observation made in \cite{BG23b} when $R$ is a field.     
\end{remark}




\begin{lemma}\label{u_p is invertible}
    The object $u_{p, R}$ is a $\otimes$-invertible object in $\K(G,R)$. Moreover, for $\pp\in \Spec(R)$, the base change functor along the residue field $R\to k(\pp)$ give us an isomorphism
    \[
    \iota_\pp^\ast( u_{p, R} ) \simeq u_{p, k(\pp)}.
    \] 
\end{lemma}

We need some preparations first. 



\begin{proposition}\label{homology of X otimes its dual}
    Let $X$ and $Y$ be a complexes of finitely generated $RG$--modules satisfying the following properties:
    \begin{enumerate}
        \item For any $n$, both $X_n$ and $Y_n$ are free as $R$--modules. 
        \item $X$ has homology in a single degree $i$ and it is free as $R$--module and $Y$ has homology in a single degree $-i$ and it is free as $R$--module.
    \end{enumerate}
    Then $X\otimes Y$ has homology concentrated in degree 0.
\end{proposition}

\begin{proof}
    By $(1)$, we obtain that any term of $X\otimes Y$ is free as $R$--module. Now, by the Künneth formula we have that the homology of $X\otimes Y$ in degree $n$ is given by  
    \[
    0\to \bigoplus_{r+s=n}H_r(X)\otimes H_s(Y)\to H_n(X\otimes Y)\to \bigoplus_{s+r=n-1}\mathrm{Tor}^1(H_r(X),H_s(Y))\to 0.
    \]
    By $(2)$, we deduce that $\mathrm{Tor}^1$ vanishes, and the homology must be concentrated in degree 0 as we wanted. 
\end{proof}





\begin{proof}[Proof of Lemma \ref{u_p is invertible}]
Note that $u_p$ satisfies the hypothesis of Proposition \ref{homology of X otimes its dual}, hence we obtain that the homology of $X= u_p\otimes u_p^\ast$ is concentrated in degree 0. Here $u_p^\ast$ denotes the dual complex of $u_p$. Moreover, since the non-trivial homology group of $u_p$ is $R$, we deduce that $H_0(X)\cong R$. 

We will first deal with $p$ odd. In this case, $X_n$  is non-trivial for $n\in \{-2,\ldots, 2\}$, and it is projective as $RG$--module as long as $n\not=0$. We claim that the differentials $d_2\colon X_2\to X_1$ and $d_{-1}\colon X_{-1}\to X_{-2}$ must be split injective and split surjective, respectively. Indeed, since projective $RG$--modules are the same as injective $RG$--modules with respect to the exact structure of $\mathrm{Mod}(G,R)$, it is enough to verify that $d_2$ and ${d_{-1}}$ are admissible mono and admissible epi, respectively.  But this follows since  $X$ has homology concentrated in degree 0 and it is free as $R$--module.
As a consequence, we can `remove' the extremes of the complex $X$. That is, we can write $X$ as  $X'\oplus Y \oplus Z$ with
\[
Y= 0\to X_2\xrightarrow{\simeq} X_2\to 0, \quad \mbox{and} \quad Z=0\to X_{-2}\xrightarrow{\simeq} X_{-2}\to0
\]
 where the first $X_2$ is in degree 2 and the first $X_{-2}$ is in degree -1, and some complex $X'$ with $X'_n=0$ except in degree -1,0 and 1. Since $Y$ and $Z$ are contractible, we obtain that $X$ is homotopy equivalent to $X'$. Since   $X'_{\pm 1}$ is a summand of $X_{\pm 1}$, both $X'_1$ and $X'_{-1}$ are projective $RG$--modules, so we can apply the same argument to `remove' the extremes. This leads us to a complex $X''$ concentrated in degree 0, and which is homotopy equivalent to $X$. Since the homology of $X$ in degree 0 is given by $R$ and trivial otherwise, we obtain that $X''$ must be $R$ as a complex concentrated in degree 0, as we wanted.  The case $p=2$ is completely analogous, except that we only need to apply the previous argument once. 

The second claim is an immediate consequence of the fact that the resolution given in \ref{eq:standar resolution} can be obtained from $R=\mathbb{Z}$ by base change. 
\end{proof}


\begin{remark}
 A different proof of Lemma \ref{u_p is invertible} is possible by invoking \cite[Corollary 4.8]{Gom25}. In this case,   we obtain  that the tt-functor 
 \[
 \prod \iota_\pp^\ast\colon\K(C_p, R) \to \prod_{\pp \in \mathrm{Spec}(R)} \K(C_p, k(\pp))
 \]
 is conservative. 
     Hence it is enough to show that the objects $\iota_\pp^\ast(u_{p,R})\simeq u_{p, k(\pp)}$ are tensor invertible for each $\pp \in \mathrm{Spec}(R)$.
    If the characteristic of $k(\pp)$ is $p$ then this follows from \cite{BG23b}. Otherwise, note that $u_{p, k(\pp)}$ is isomorphic to $k(\pp)[2]$ or $k(\pp)[1]$, depending on whether $p$ is even or odd. 
\end{remark}


\subsection*{Invertible objects in the general case} We extend the definition of the complexes $u_p$ to a more general context as follows. 



\begin{definition}\label{def:u_N}
Let $G$ be a finite group and   $N$ be a normal subgroup of $G$ of  index $p$.  Then define 
\[
u_{N, R} \coloneqq \mathrm{Infl}_N^G (u_{p,R})
\]
where $\mathrm{Infl}_N^G\colon \K(G/N,R)\to \K(G,R)$ denotes the inflation functor obtained by the homomorphism of groups $G\to G/N$.  
\end{definition}

\begin{remark}
There are a few considerations to keep in mind regarding the previous definition:
\begin{enumerate}
\item The complex $u_{N,R}$ also depends on the choice of a generator of $G/N$ to make the identification with $C_p$. We will make this choice explicit whenever needed. For now, observe that the isomorphism type of $u_{N,R}$ is independent of this choice (see \cite[Remark 12.5]{BG23b}).
\item The inflation functor is indeed a tt-functor; in particular, the objects $u_{N,R}$ are $\otimes$-invertible in $\K(G,R)$.
\item A \textit{concrete} description of the objects $u_{N,R}$ is as follows.   \[u_{N,R}= \left\{
        \begin{array}{ll}

            0\to  R(G/N) \xrightarrow{\epsilon} R \to 0 & \textrm{ if } p=2\\
            0 \to R(G/N)\xrightarrow{\sigma-1} R(G/N) \xrightarrow{\epsilon} R \to 0 & \textrm{ if } p>2.
        \end{array}
    \right. \]
\end{enumerate}
\end{remark}

\begin{remark}
Recall that tensoring any two invertible objects is again invertible. In particular, any tensor power of $u_{N,R}$ is again invertible in $\K(G,R)$. We will give a description of such tensor powers since they will play a crucial role in what follows. In fact, such a description generalizes the field case treated in  \cite[Lemma 12.6]{BG23b}.   
\end{remark}

\begin{notation}
    From now on, we will adopt Balmer-Gallauer's notation and write $2'$ to denote either $1$ for $p=2$, or $2$ for $p>2$.
\end{notation}


\begin{lemma}\label{tensor powers of uN}
Let $G$ be a finite group and  $N$ be a normal subgroup of $G$ of index $p$ and  $q \geq 1$. Then there is a canonical identification in $\K(G, R)$
    \[u_{N, R}^{\otimes q} \simeq (0 \to R(G/N) \xrightarrow{\sigma-1} R(G/N) \xrightarrow{\mathbf{N}} \cdots \xrightarrow{\sigma -1} R(G/N) \xrightarrow{\epsilon} R \to 0)\] 
    where the copy of $R$ in the right-hand side is considered in degree 0, and the left most $R(G/N)$ is in degree $q\cdot 2'$.
\end{lemma}

\begin{proof}
Let $Y$ denote the right hand side complex.  We will only deal with the case $p>2$, the other case  follows in a similar pattern. First, assume that $G=C_p$. By Lemma \ref{u_p is invertible} we know that $u_p$ is invertible, then $u_p^{\otimes q}$ is invertible for any $q\geq1$. In particular, it is well known that if $x\otimes y\simeq 1$ in a closed symmetric monoidal category, then we can identify $y$ with the dual of $x$, that is, $x^\ast\simeq y$, and for an invertible object $x$, there is a canonical isomorphisms from $x$ to its double dual $x^{\ast \ast}$. Fix $q\geq 2$. We will show that the dual $Y^\ast$ of $Y$ is an inverse for $X=u_p^{\otimes q}$, and this will imply the desired result. Note that $Y^\ast$ is given by\footnote{The complex $Y^\ast$ corresponds to the truncation of the standard resolution to compute the cohomology of $C_p$.} 
\[
0\to R \xrightarrow{\eta}  RG \xrightarrow{\sigma-1} RG \xrightarrow{\mathbf{N}} \cdots \xrightarrow{\sigma-1} RG \to 0
\]
with $R$ in degree 0, and $\eta$ the counit of the adjunction restriction-induction. We can use a slightly variation of Proposition \ref{homology of X otimes its dual} to show that $X$ has homology concentrated in degree $2q$, while $Y^\ast$ has homology concentrated in degree $-2q$. In particular, the pair $X$ and $Y$ satisfies the hypothesis of  Proposition \ref{homology of X otimes its dual}, and we deduce that the homology of $X\otimes Y^\ast$ is concentrated in degree 0 and it is given by $R$. By inspection, $(X\otimes Y^\ast)_n$ is a projective a $RG$--module, for any $n\not=0$. Moreover, note that, as in the proof of Proposition  \ref{u_p is invertible}, the differentials $d_{2q}$ and $d_{-2q+1}$ are admissible mono and admissible epi in $\Mod(G,R)$, respectively. Hence,   we can `remove' the extremes of $X\otimes Y^\ast$ without changing the homotopy type. That is, we can write $X\otimes Y^\ast$ as $(X\otimes Y^\ast)'\oplus A \oplus B$ with
\begin{align*}
     A & = 0\to (X\otimes Y^\ast)_{2q}\xrightarrow{\simeq} (X\otimes Y^\ast)_{2q}\to 0, \mbox{ and} \\ 
      B & = 0\to (X\otimes Y^\ast)_{-2q}\xrightarrow{\simeq} (X\otimes Y^\ast)_{-2q}\to0
\end{align*}
where the first $(X\otimes Y^\ast)_{2q}$ is in degree 2q and the first $(X\otimes Y^\ast)_{-2q}$ is in degree $-2q+1$, and some complex $(X\otimes Y^\ast)'$ with $(X\otimes Y^\ast)'_n=0$ except for $n\in \{-2q+1,-2q+2,\ldots, 2q-1\}$. Since $A$ and $B$ are contractible, we have that $(X\otimes Y^\ast)$ is homotopy equivalent to $(X\otimes Y^\ast)'$. Again, by inspection, we have that $(X\otimes Y^\ast)'_n$ is a projective $RG$--module, for any  $n\not=0$. We apply the same argument until we get a complex concentrated in degree $0$ homotopy equivalent to $X\otimes Y^\ast$. Since we know the homology of $X\otimes Y^\ast$, we deduce that it must be homotopy equivalent to $R$ concentrated in degree $0$. This completes the case $G=C_p$. For the general case, we only need to inflate since inflation is a tensor triangulated functor. 
\end{proof}

\section{Twisted integral cohomology}\label{sec: twisted}

In this section, we will define the twisted cohomology ring for any $p$-group and study certain properties that it has under base change along residue fields. Before jumping into the construction, let us place a restriction on our ground ring.

\begin{convention}\label{convention on R}
From now on, we will assume that whenever $p \neq 0$ in $R$, then $\mathrm{ann}_R(p) = 0$. In other words, if $p$ is not trivial in $R$, then we will assume that $p$ is not a zero divisor.
\end{convention}

\begin{remark}
    We decided to place the previous restriction in order to simplify several of the arguments that will appear in the rest of this document, rather than for a conceptual reason.
\end{remark}


\begin{definition}
Let $N$ be a normal subgroup of $G$ of index $p$. We will define the following maps in $\K(G,R)$ which will depend on $p$ and $R$. Recall that the definition of the invertible elements $u_N$ also depend on this, see Definition \ref{def: uN}.  

\begin{enumerate}
    \item[$(C1)$]  If $p=2$, and $p$ is trivial in $R$, define $a_N\colon \mathbb{1}\to u_N$ and $b_N\colon \mathbb{1}\to u_N[-1]$ as follows: 
    \begin{center}
     \begin{tikzcd}
  \mathbb{1} \arrow[d, "a_N"']  = & 0 \arrow[r] \arrow[d] &  R \arrow[d,"1"] \\ 
 u_N = & R(G/N) \arrow[r,"\epsilon"] & R.
    \end{tikzcd} 
    \end{center}
    and 
    \begin{center}
     \begin{tikzcd}
  \mathbb{1} \arrow[d, "b_N"']  = & R \arrow[r] \arrow[d,"\eta"] &  0 \arrow[d] \\ 
 u_N[-1] = & R(G/N) \arrow[r,"\epsilon"] & R 
    \end{tikzcd}    
    \end{center}
 \item[$(C2)$] If $p=2$, and $p$ is non-trivial in $R$, define $a_N\colon \mathbb{1}\to u_N$ and $b_N\colon \mathbb{1}\to u_N^{\otimes 2}[-2]$ as follows: 
 \begin{center}
 \begin{tikzcd}
  \mathbb{1} \arrow[d, "a_N"']  = & 0 \arrow[r] \arrow[d] &  R \arrow[d,"1"] \\ 
 u_N = & R(G/N) \arrow[r,"\epsilon"] & R
    \end{tikzcd} 
    \end{center}
    and 
    \begin{center}
     \begin{tikzcd}
  \mathbb{1} \arrow[d, "b_N"']  = & R \arrow[r] \arrow[d,"\eta"] &  0 \arrow[d] \arrow[r] & 0 \arrow[d] \\ 
 u_N^{\otimes 2}[-2] = & R(G/N) \arrow[r,"\sigma -1"] & R(G/N)\arrow[r,"\epsilon"] & R.
    \end{tikzcd}
    \end{center}

    \item[$(C3)$] If $p>2$, and $p$ is trivial in $R$, define $a_N\colon \mathbb{1}\to u_N$, $b_N\colon \mathbb{1}\to u_N[-2]$ and $c_N\colon \mathbb{1}\to u_N[-1]$ as follows: 
    \begin{center}
    \begin{tikzcd}
  \mathbb{1} \arrow[d, "a_N"']  = & 0 \arrow[r] \arrow[d] & 0 \arrow[r] \arrow[d] &  R \arrow[d,"1"] \\ 
 u_N = & R(G/N)\arrow[r,"\sigma-1"] & R(G/N) \arrow[r,"\epsilon"] & R
    \end{tikzcd} 
    \end{center}
     and 
     \begin{center}
     \begin{tikzcd}
