\begin{remark}
Let $\pp$ be a point in $\mathrm{Spec}(R)$. Recall that  base change along the residue field $R\to k(\pp)$  defines a tt-functor  
\[
\iota^\ast_\pp\colon \K(G,R)\to \K(G,k(\pp)).
\]
Now, consider a normal subgroup $N$ of $G$ of index $p$. As we already observed in Lemma \ref{u_p is invertible}, the tensor invertible object $u_{N,R}$ maps to $u_{N,k(\pp)}$ under the functor $\iota^\ast_\pp$. Let us record the behavior of the maps $a_{N,R}, \, b_{N,R}$ and $c_{N,R}$ under $\iota^\ast_\pp$.
\end{remark}


\begin{lemma}\label{base chage of maps aN, bN, cN}
  Let $N$ be a normal subgroup of $G$ of index $p$. Consider the tt-functor $\iota^\ast_\pp$ obtained by $x\mapsto x\otimes_R k(\pp)$. Then we have the following identifications under this functor.  
  \begin{itemize}
      \item[(i)] $\iota_\pp^\ast(a_{N,R})$ identifies  with $a_{N,k(\pp)}$ in all cases $(C1)$-$(C4)$.
      \item[(ii)] $\iota_\pp^\ast(b_{N,R})$ identifies with $b_{N,k(\pp)}$ in cases $C(1)$, $(C3)$ and $(C4)$, and with $b_{N,k({\pp)}}^{\otimes 2}$ in case $(C2)$. 
      \item[(iii)] $\iota_\pp^\ast(c_{N,R})$ identifies with $c_{N,k(\pp)}$ in case $(C3)$.
  \end{itemize}
\end{lemma}


\begin{proof}
     All cases follow a similar pattern, hence we will only show the identification regarding the map $a_N$, that is, part $(i)$. For readability, let us write $k$ to denote $k(\pp)$. Since $\iota_\pp^\ast$ is a tt-functor, we get that $\mathbb{1}_{\K(G,R)}=R$ goes to $\mathbb{1}_{\K(G,k)}=k$ via the canonical map.  Moreover, we showed in Lemma \ref{u_p is invertible} that $\iota_\pp^\ast(u_{N,R})$ agrees with $u_{N,k}$ via the isomorphism $R(G/N)\otimes_Rk\simeq k(G/R)$ point-wise. In particular, we get a diagram 
     \begin{equation*}
         \begin{tikzcd}
         R \otimes_R k \arrow[d,"a_{N,R}"'] \arrow[r,"\simeq"] & k \arrow[d,"a_{N,k}"]\\
             u_{R,N}\otimes_Rk \arrow[r,"\simeq"]  & u_{N,k}          \end{tikzcd}
     \end{equation*}
     and it is easy to verify that this square is commutative. 
\end{proof}

Since the functor $\iota_\pp^\ast\colon \K(G,R)\to \K(G,k(\pp))$ is symmetric monoidal, we obtain a morphism of $(\mathbb{Z}\times \mathbb{N}^\mathcal{N})$-graded rings 
\[
\Theta_\pp\colon H^{\bullet,\bullet}(G,R)\otimes_R k(\pp)\to H^{\bullet,\bullet}(G,k(\pp)).
\]
Let us record the following property of the morphism $\Theta_\pp$. 


\begin{corollary}\label{coro: injectivity by base change}
    The map $\Theta_\pp$ is power surjective, that is, for any $\alpha$ in $H^{\bullet,\bullet}(G,k(\pp))$, there is natural number $n$, such that $\alpha^{\otimes n}$ is in the image of $\Theta_\pp$. In particular, we get that $\Theta_\pp$ induces an injective map 
    \[
    \mathrm{Spec}^h(H^{\bullet,\bullet}(G,k(\pp)))\to \mathrm{Spec}^h(H^{\bullet,\bullet}(G,R)\otimes_R k(\pp)). 
    \]
\end{corollary}

\begin{proof}
    This is an immediate consequence of Lemma \ref{base chage of maps aN, bN, cN}, since the maps $a_N$, $b_N$, and $c_N$ are generators. In particular, in case $(C3)$, we get that for $b_{N,k(\pp)}$, the required $n$ is precisely $2$. It is probably worth highlighting the following scenario: in case $(C4)$, we might have a morphism $c_{N,k(\pp)}$ (depending on the characteristic of $k(\pp)$), but we have no $c_{N,R}$. This is not a problem since such $c_{N,k(\pp)}$ are nilpotent (see Remark \ref{cN is nilpotent}).
\end{proof}


