\section{Comparing Balmer and homogeneous spectra}\label{sec: comparing}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Recall that $G$ denotes a $p$-group and $R$ denotes a commutative Noetherian ring subject to Convention \ref{convention on R}. In this section, we relate the Balmer spectrum of $\K(G,R)$ and the homogeneous spectrum of $H^{\bullet,\bullet}(G,R)$ via the comparison map. Let us recall the construction of this map and refer to \cite[Theorem 5.3]{Bal10} and \cite[Proposition 13.4]{BG23b} for the proof.

\begin{lemma}\label{lemma:comparison map}
    There is a continuous comparison map
    \begin{align*}
     \mathrm{Comp}_{G,R}\colon \mathrm{Spc}(\K(G,R)) & \to \mathrm{Spec}^h(H^{\bullet,\bullet}(G,R)) \\ 
        \mathcal{P} & \mapsto \langle f\colon \mathbb{1}\to \mathbb{1}(q)[s]\mid \mathrm{cone}(f)\not\in \mathcal{P}\rangle. 
    \end{align*} 
    where the right hand side denotes the ideal generated by the maps $f$. 
\end{lemma}

% \begin{proof}
