%  Now, for an element $f\in H^{\bullet,\bullet}(G,R)$ consider the quasi-compact basic open $D(f)=\{\mathfrak{p}\mid f\not\in \mathfrak{p}\}\subseteq \Spec^h(H^{\bullet,\bullet}(G,R))$. Note that $\mathrm{Comp}_{G,R}^{-1}(D(s))=U(\mathrm{cone}(f))$, hence $\mathrm{Comp}_{G,R}$ is continuous.  
% \end{proof}

Let us record  that this comparison map is compatible with base change along the residue fields of $R$.  In fact, the comparison map is natural with respect to tt-functors and the same proof as \cite[Theorem 5.3]{Bal10} applies in this case. 

\begin{proposition}\label{base change and comparison map}
    Let $\pp$ be a prime of $R$. Then base change along the residue field $R\to k(\pp)$ makes the following diagram commutative. 
\begin{center}
    \begin{tikzcd}[column sep = 5em]
       \mathrm{Spc}(\K(E,k(\pp))) \arrow[r,"\mathrm{Spc}(\iota_\pp^\ast)"] \arrow[d,"\mathrm{Comp}_{G,R}"'] & \mathrm{Spc}(\K(E,R)) \arrow[d,"\mathrm{Comp}_{G,k(\pp)}"] \\ 
 \mathrm{Spec}^h(H^{\bullet,\bullet}(E,k(\pp))) \arrow[r,"\mathrm{Spec}(\iota_\pp^\ast)"] & \mathrm{Spec}^h(H^{\bullet, \bullet }(E,R)).
    \end{tikzcd}
\end{center}
Recall that $\iota_\pp^\ast$ denote the tt-functor induced by $x\mapsto x\otimes_R k(\pp)$.
\end{proposition}



\begin{lemma}\label{comaprison is injective}
    Let $E$ be an elementary abelian $p$-group. Then the comparison map 
    \[
    \mathrm{Comp}_E\colon \mathrm{Spc}(\K(E,R))  \to \mathrm{Spec}^h(H^{\bullet,\bullet}(E,R))
    \]
    is injective. 
\end{lemma}

\begin{proof}
    By Proposition \ref{base change and comparison map}, we obtain  the following commutative square

\begin{center}
    \begin{tikzcd}
       \displaystyle \coprod_{\pp\in\mathrm{Spec}(R)} \mathrm{Spc}(\K(E,k(\pp))) \arrow[r] \arrow[d] & \mathrm{Spc}(\K(E,R)) \arrow[d] \\ 
\displaystyle \coprod_{\pp\in\mathrm{Spec}(R)} \mathrm{Spec}^h(H^{\bullet,\bullet}(E,k(\pp))) \arrow[r] & \mathrm{Spec}^h(H^{\bullet, \bullet }(E,R)).
    \end{tikzcd}
\end{center}


\noindent We claim that the left-vertical map is injective. Indeed, if the characteristic of $k(\pp)$ is $p$, then the corresponding component is injective by  \cite[Proposition 15.1]{BG23b}; if the characteristic of $k(\pp)$ is not $p$, then $\mathrm{Spc}(\K(E,k(\pp))$ is simply a point, and the respective component map is trivially injective. Now, note that bottom map is injective  since the components are inclusions into the fibers induced by the map $\mathrm{Spec}^h(H^{\bullet,\bullet}(E,R))\to \mathrm{Spec}^h(R)$ (see Corollary \ref{coro: injectivity by base change}).  It follows that the top map is injective as well. Moreover, by Proposition \ref{Spc as a set}, the top map is a bijection. We deduce that  the comparison map is injective by the commutativity of the square.    
\end{proof}

\begin{remark}
   One should not expect the previous result to hold for more general $p$-groups, not even when $R$ is a field, as discussed in \cite{BG23b}. The point is that twisted cohomology \textit{only sees} the Frattini subgroup of $G$. For instance, if $G$ is a non-cyclic simple $p$-group, twisted cohomology is not very interesting. 
\end{remark}

