\section{A Dirac scheme structure}\label{sec:dirac}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Let $E$ be an elementary abelian $p$-group. In this section, we define a special cover of the Balmer spectrum $\mathrm{Spc}(\K(E,R))$, along with a sheaf of graded rings, which together exhibit $\mathrm{Spc}(\K(E,R))$ as a Dirac scheme. This generalizes the result of Balmer and Gallauer in the case where the base is a field.  We need some preparations.

\begin{definition}\label{def:open(f)}
  Let $G$ be a $p$-group. Let $f$ be an  homogeneous map in the twisted cohomology ring $H^{\bullet,\bullet}(G,R)$. Following \cite[Notation 13.7]{BG23b}, we let $\mathrm{open}(f)\coloneqq\mathrm{open}(\mathrm{cone}(f))$ denote the open subset of $\mathrm{Spc}(\K(G,R))$ defined as the preimage under $\mathrm{Comp}_G$ of the principal open $Z(f)^c=\{\pp\mid f\not\in \pp\}$. That is, $\mathrm{open}(f)$ is given by $\{\mathcal{P}\mid \mathrm{cone}(f)\in \mathcal{P}\}$. In other words, the subset $\mathrm{open}(f)$ is the open locus of $\mathrm{Spc}(\K(G,R))$ where $f$ is invertible. 
\end{definition}



\begin{proposition}\label{cone of an kills cone of bn}
    Let $N$ be subgroup of $G$ of index $p$. Then 
    \[
    \mathrm{cone}(a_{N,R})\otimes \mathrm{cone}(b_{N,R})
    \]
    is trivial. In particular, 
    \[
    \mathrm{open}(a_{N,R} ) \cup \mathrm{open}( b_{N,R})=\mathrm{Spc}(\K(G,R)).
    \]
\end{proposition}

\begin{proof}
     For a prime $\pp$ in $R$, consider the residue field $R\to k(\pp)$. Note that 
     \[
     \mathrm{cone}(a_{N,R}\otimes_R k(\pp))\cong \mathrm{cone}(a_{N,k(\pp)}) \, \textrm{ and } \, \mathrm{cone}(b_{N,R}\otimes_R k(\pp))\cong \mathrm{cone}(b_{N,k(\pp)}) 
     \]
     Moreover, note that $\mathrm{cone}(a_{N,k(\pp)})\otimes \mathrm{cone}(b_{N,k(\pp)})=0$. Indeed, if the characteristic of $k(\pp)$ is $p$, this follows by \cite[Corollary 13.3]{BG23b}; if the characteristic of $k(\pp)$ is coprime to $p$, this follows by the fact that $b_N$ is a quasi-isomorphism. Hence  the first claim follows by jointly conservativity of the functors from \cite[Corollary 4.8]{Gom25}. For the second claim, note that $\mathrm{open}(a_{N,R} ) \cup \mathrm{open}(b_{N,R})=\mathrm{open}(\mathrm{cone}(a_{N,R})\otimes \mathrm{cone}(b_{N,R}))=\mathrm{open}(0)=\mathrm{Spc}(\K(G,R)).$
\end{proof}

For the rest of this section, we focus on an elementary abelian $p$-group $E$. Recall that $\mathcal{N}(E)$ denotes the set of all subgroups of $E$ of index $p$. 


\begin{definition}\label{def:u(H)}
Let $H$ be a subgroup of $E$. Then we define the open subset $U_E(H)$ of $\mathrm{Spc}(\K(E,R))$ given by  
\[
U_E(H)\coloneqq \left( \displaystyle \bigcap_{N\in\mathcal{N}, \, H\not\leq N} \mathrm{open}(a_{N,R}) \right) \cap \left(\bigcap_{N\in\mathcal{N}, \, H\leq N} \mathrm{open}(b_{N,R})\right).
\]
\end{definition}

\begin{definition}\label{def:LH}
    For $H\leq E$, let $S_H\subset H^{\bullet,\bullet}(G,R)$ be the multiplicative subset generated by the set 
    \[
    \{ a_{N,R}\mid N\in\mathcal{N}(E),\, H\not \leq N\}\cup \{ b_{N,R}\mid N\in\mathcal{N}(E),\, H \leq N\}.
    \]
    The tt-category $\mathcal{L}(H,R)$ is defined as the Verdier quotient $\K(G,R)/I$ where $I$ denotes the tt-ideal generated by the collection $\{\mathrm{cone}(f)\mid f\in S_H\}$.  Let $\mathcal{O}^\bullet_E(H)$ denote the $\mathbb{Z}$--graded ring $ \mathrm{End}^\ast_{\mathcal{L}(H,R)}(\mathbb{1})$. 
\end{definition}

\begin{remark}\label{rmk:spc of L(H)}
 Imitating  Construction 14.12 in \cite{BG23b}, we consider the open subset $U=U_E(H)$ which agrees with $\bigcap_{f\in S_H} \mathrm{open}(f)$. Just as the field case, one verifies  that the complement of $U$ agrees with $Z\coloneqq\bigcup_{f\in S_H} \mathrm{supp}(\mathrm{cone}(f))$. In particular, the tt-ideal $\K(E,R)_Z$ supported on $Z$ is the one generated by $\{\mathrm{cone}(f)\mid f\in S_H\}$. Therefore the tt-category $\K(G,R)_U=(\K(G,R)/\K(G,R)_Z)^\natural$ is the idempotent completion of $\mathcal{L}(H,R)$. It follows that $\mathrm{Spc}(\mathcal{L}(H,R))\cong \mathrm{Spc}(\K(G,R)_U)\cong U$, see \cite{BF11} for a proof of the last homeomorphism. 
\end{remark}

\begin{remark}\label{rem:morphism as fractions in LH}
    Note that the $\mathbb{Z}$--graded ring $\mathcal{O}^\bullet_E(H)$ can be identified with the twist-zero part of the localization of $H^{\bullet,\bullet}(G,R)$ on $S_H$, in symbols: 
\[
\mathcal{O}^\bullet_E(H)=(H^{\bullet,\bullet}(G,R)[S_H^{-1}])_{0\textrm{-twist}}
\]
 see \cite[Definition 14.9]{BG23b}. In particular, we can consider the elements of $\mathcal{O}^\bullet_E(H)$ as fractions $\frac{f}{g}$ with $f\colon \mathbb{1}\to \mathbb{1}(q)[s]$ and $g\colon \mathbb{1}\to \mathbb{1}(q)[s'] \in S_H$, for some $q\in \mathcal{N}(E)$ and $s,s'\in\mathbb{Z}$. On the other hand, the morphisms in $\mathcal{L}(E,R)$ can be described as fractions $\frac{f}{g}$ where $g\colon \mathbb{1}\to \mathbb{1}(q)[s]$ is a map in $S_H$ and $f\colon x\to y\otimes \mathbb{1}(q)[1]$ is any morphism in $\K(E,R)$, see \cite[Construction 14.12]{BG23b} and the references therein. 
\end{remark}


Recall that a tt-category $\T$ is called \textit{End-finite} if the graded endomorphism ring $\mathrm{End}^\ast_\T(\mathbb{1})$ is Noetherian and for each object $x$ in $\T$, the $\mathrm{End}^\ast_\T(\mathbb{1})$--module $\mathrm{End}^\ast(x)$ is finitely generated. 

\begin{proposition}\label{prop:L(H) is end-finite}
    Let $H$ be a subgroup of $E$. Then the tt-category $\mathcal{L}(H,R)$ is End-finite.
\end{proposition}


\begin{proof}
First, recall that $\mathcal{O}^\bullet_{E}(H)$ is a localization of the the twisted cohomology ring $H^{\bullet,\bullet}(E,R)$, and the latter is Noetherian by Corollary \ref{twisted coh is noetherian}. We conclude that the former is Noetherian as well. For the cases $(C1)$, $(C2)$ and $(C3)$ one can argue as in the proof of \cite[Theorem 15.3]{BG23b}, that is, one has that $\mathcal{L}(H,R)$ is generated,  as a thick subcategory, by the monoidal unit, and hence the result follows. 

For case $(C4)$, we do not know if the category  $\mathcal{L}(H,R)$ is generated by the monoidal unit, but it is generated by the permutation modules $R(E/K)$, for  $K\leq E$. Hence, we only need to prove that $\mathrm{End}^\ast_{\mathcal{L}(H,R)}(R(E/K))$ is a finitely generated $\mathcal{O}^\bullet_E(H)$--module, for each $R(E/K)$. Moreover, since $R(E/K)$ is dualizable in $\mathcal{L}(E,R)$, and $R(E/K)\otimes R(E/K)^\ast $ is a sum of permutation modules, it is enough to show that $\mathrm{Hom}^\ast_{\mathcal{L}(H,E)}(R(E/K), \mathbb{1})$ is a finitely generated $\mathcal{O}^\bullet_E(H)$--module. 
Fix $K\leq E$. For each $N\in \mathcal{N}(E)$ consider the morphisms $\Bar{a}_N, \, \Bar{b}_N$ and $\Bar{c}_N$ in $\K(E,R)$ obtained from the morphisms $\mathrm{Res}^E_K (a_N), \, \mathrm{Res}^E_K(b_N)$ and $\mathrm{Res}^E_K(c_N)$ in $\K(K,R)$, respectively, via the adjunction restriction-induction. By Remark \ref{invertibles under restriction}, we have the following identifications 

\[
\mathrm{Res}^E_K(a_N)= \left\{
        \begin{array}{ll}

            0 & \textrm{ if } K\leq N\\
            a_{K\cap N} & \textrm{ if } K\not\leq N
        \end{array}
    \right.
\] 
and 
\[
\mathrm{Res}^E_K(b_N)= \left\{
        \begin{array}{ll}

            \mathrm{id}_\mathbb{1} & \textrm{ if } K\leq N\\
            b_{K\cap N} & \textrm{ if } K\not\leq N.
        \end{array}
        \right.
\]
\noindent We also have an analogous behavior for $c_N$. We claim that any map $R(E/K)\to \mathbb{1}(q)[s]$ in $\K(E,R)$, for $q\in \mathbb{N}^{\mathcal{N}(E)}$ and $s\in \mathbb{Z}$, is generated as an $R$-linear combination of the maps  $\Bar{a}_N, \, \Bar{b}_N$ and $\Bar{c}_N$, for $N\in \mathcal{N}(E)$, and multiplications by homogeneous maps $g$ in $H^{\bullet,\bullet}(E,R)$, where multiplication of $g\colon \mathbb{1}\to \mathbb{1}(q')[s']$ on a morphism $f\colon R(E/K)\to \mathbb{1}(q)[s] $ is given by the composition 
\[
g\cdot f= R(E/K)\cong R \otimes R (E/K)\xrightarrow{g\otimes f} \mathbb{1}(q')[s']\otimes \mathbb{1}(q)[s]\cong \mathbb{1}(q'q)[s+s'].
\]

\noindent First, one verifies that the multiplication of $g\colon \mathbb{1}\to \mathbb{1}(q')[s']$ on  $\Bar{a}_N$ corresponds to the map $\mathrm{Res}^E_K(g) \cdot a_N $ via the adjunction restriction-induction. For instance, use the explicit description of the unit and counit of this adjunction. The analogous result holds for the multiplication of $g$ on $\Bar{b}_N$ and $\Bar{c}_N$. We are ready to prove the claim. Let $\Bar{f}\colon R(E/K)\to \mathbb{1}(q)[s]$ as above, and consider the corresponding map under the adjunction, say 
\[
f\colon \mathbb{1}\to \mathrm{Res}^E_K(\mathbb{1}(q))[s].
\]
By Lemma \ref{aN, bN and CN are generators} we know that $f$ is a $R$--linear combination of the maps $a_{N'},\, b_{N'}$  and $c_{N'}$ for $N'\in \mathcal{N}(K)$. But any $N'\leq K$ of index $p$ has the form $N\cap K$ for some subgroup $N\in \mathcal{N}(E)$, so we can write $f$ as 
\[
\displaystyle \sum_{i,j,k}x_{i,j,j}\mathrm{Res}^E_K (a_{N_i})^{\otimes\alpha_{i,j,k}} \otimes \mathrm{Res}^E_K(b_{N_j})^{\otimes \beta_{i,j,k}}\otimes \mathrm{Res}^E_K (c_{N_k})^{\otimes \delta_{i,j,k}}
\] 
for $x_{i,j,k} \in R$, $N_?\in \mathcal{N}(E)$ and $\alpha_?,\, \beta_?$ and $\delta_?$ natural numbers. Recall that restriction is monoidal, so we can rewrite $f$ in the following fashion 
 \[
 \displaystyle \sum_{i,j,k}x_{i,j,j}\mathrm{Res}^E_K (a_{N_i}^{\otimes\alpha_{i,j,k}} \otimes (b_{N_j}^{\otimes \beta_{i,j,k}}\otimes c_{N_k}^{\otimes \delta_{i,j,k}})\otimes \varphi_{N'}
 \]
  where $\varphi_{N'}$ is one of the distinguished maps $a_{N'}$, $b_{N'}$ or $b_{N'}$ for some $N'\in \mathcal{N}(K)$. By the previous observation, we obtain that $\Bar{f}$ can be written as  
  \[
  \displaystyle \sum_{i,j,k}x_{i,j,j}(a_{N_i}^{\otimes\alpha_{i,j,k}} \otimes b_{N_j}^{\otimes \beta_{i,j,k}}\otimes c_{N_k}^{\otimes \delta_{i,j,k}})\cdot \Bar{\varphi}_{N'}
  \]
  where $\Bar{\varphi}_{N'}$ is the  map in $\K(E,R)$ corresponding to $\varphi_{N'}$ via the adjunction. This completes the claim. 

 On the other hand, a morphism  in $\mathcal{L}(E,R)$ corresponds to a fraction $\frac{f}{g}$ where $g\colon \mathbb{1}\to \mathbb{1}(q)[s]$ is a map in $S_H$ and $f\colon x\to y\otimes \mathbb{1}(q)[1]$ is a in $\K(E,R)$ (see Remark \ref{rem:morphism as fractions in LH}). Moreover, the action of a fraction $\frac{r}{s}$ in $\mathcal{O}_E^\bullet(G)$ on a morphism $\frac{f}{g}$ corresponds to $\frac{r\cdot f}{s\otimes g}$. In particular, the previous claim and the fact that any morphism $g$ in $S_H$ can be described as a finite product of the $a_{N,R}$ with $ N\in\mathcal{N}(E)$ such that $ H\not \leq N\}$ and the maps $ b_{N,R}$ with $ N\in\mathcal{N}(E)$ such that $ H \leq N$, we deduce that 
 $\mathrm{Hom}^\ast_{\mathcal{L}(H,E)}(R(E/K), \mathbb{1})$ is finitely generated as $\mathcal{O}^\bullet_E(H)$--module.
\end{proof}



\begin{remark}\label{rem:comparison of LH and KE}
Let $H$ be a subgroup of $E$.  Consider the comparison map 
\[
\rho_{\mathcal{L}(H,R)}\colon \mathrm{Spc}(\mathcal{L}(H,R))\to \mathrm{Spec}^h(\mathcal{O}^\bullet_H(H))
\]
constructed in  \cite{Bal10} corresponding to the tensor invertible complex $\mathbb{1}[1]$. We obtain  the following 
commutative square.  

\begin{center}
   \begin{tikzcd}
    \mathrm{Spc}(\mathcal{L}(H,R)) \arrow[d,"\rho_{\mathcal{L}(H,R)}"'] \arrow[r] & \mathrm{Spc}(\K(E,R)) \arrow[d,"\mathrm{Comp}_G"] \\
    \Spec^h(\mathcal{O}^\bullet_H(H)) \arrow[r] &  \Spec^h(H^{\bullet,\bullet}(E,R)) 
\end{tikzcd} 
\end{center}
 \noindent where the horizontal maps are induced by the respective localizations. This square is commutative by the definition of the comparison maps. 
\end{remark}


\begin{theorem}\label{thm:comp LH is an homeomorphism}
    Let $H$ be a subgroup of $E$. Then the comparison map 
    \[
    \rho_{\mathcal{L}(H,R)}\colon \mathrm{Spc}(\mathcal{L}(H,R))\to \Spec^h(\mathcal{O}^\bullet_H(H))
    \]
    of Remark \ref{rem:comparison of LH and KE} is a homeomorphism. In particular, $\Spec^h(\mathcal{O}^\bullet_H(H))\cong U_E(H)$.
\end{theorem}


\begin{proof}
   Using the commutative square from Remark \ref{rem:comparison of LH and KE} and the injectivity of the comparison map $\mathrm{Comp}_G$ (see Lemma \ref{comaprison is injective}) we deduce that the comparison map  $\rho_{\mathcal{L}(H,R)}$ is injective as well. Since $\mathrm{End}^\ast_{\mathcal{L}(H,R)}(\mathbb{1})$ is Noetherian, by \cite{Bal10} we obtain that the map $\rho_{\mathcal{L}(H,R)}$ is surjective. By Proposition \ref{prop:L(H) is end-finite}, the category $\mathcal{L}(H,R)$ is End-finite, then \cite[Lemma 2.8]{Lau23} gives us that $\rho_{\mathcal{L}(H,R)}$ is a homeomorphism. 
\end{proof}



\begin{remark}\label{rem:LE under base change}
 Let $\pp$ be a prime in $R$, and consider the residue field $R\to k(\pp)$. Fix a subgroup $H$ of $E$. Let $g$ be a map in the multiplicative subset $S_{H,R}$ of $H^{\bullet,\bullet}(E,R)$ from Definition \ref{def:LH}. Note that the map $k(\pp)\otimes g$, obtained by base change along $R\to k(\pp)$, lies in the multiplicative set $S_{E,k(\pp)}$. We deduce that the functor $\K(E,R)\to \K(E,k(\pp))$ fits into a commutative diagram
\[\begin{tikzcd}
    \K(E,R)\arrow[r] \arrow[d] & \K(E,k(\pp))\arrow[d]\\
    \mathcal{L}(H,R) \arrow[r] & \mathcal{L}(H,k(\pp))
\end{tikzcd}\]
 \noindent where the bottom map is also induced by base change along $R\to k(\pp)$.
\end{remark}

\begin{lemma}\label{lemma:open cover}
    The collection $\{U_E(H)\mid H\leq E\}$ is an open cover of the Balmer spectrum of $\K(E,R)$.
\end{lemma}

\begin{proof}
    For each prime $\pp$ in $R$ consider the commutative diagram induced by base change along the residue field $R\to k(\pp)$ given in Remark \ref{rem:LE under base change}. We obtain a commutative diagram of topological spaces   
\begin{center}
    \begin{tikzcd}
       \displaystyle \coprod_{\pp\in\mathrm{Spec}(R)} 
 \coprod_{H\leq E} \mathrm{Spc}(\mathcal{L}(H,k(\pp))) \arrow[r] \arrow[d] & \displaystyle \coprod_{\pp\in\mathrm{Spec}(R)} \mathrm{Spc}(\K(E,k(\pp))) \arrow[d] \\ 
\displaystyle  \coprod_{H\leq E} \mathrm{Spc}(\mathcal{L}(H,R)) \arrow[r] & \mathrm{Spc}(\K(E,R))
    \end{tikzcd}
\end{center}
where the right-hand vertical map is bijective by Proposition \ref{Spc as a set}, and the top map is surjective by \cite[Proposition 13.11]{BG23b}. We deduce that the bottom is surjective. Moreover, we already know that $\mathrm{Spc}(\mathcal{L}(H,R))\cong U_E(H)$ under the map induced by localization, hence the result follows. 
\end{proof}


Now, let $\mathcal{O}^\bullet_E$ be the sheaf  of graded rings on $\mathrm{Spc}(\K(E,R))$ obtained by sheafifying the presheaf 
\[
U\mapsto \mathrm{End}^\ast_{\K(H,R)(U)}(\mathbb{1})
\]
where $\K(H,R)(U)$ is the localization over a quasi-compact open $U\subset \mathrm{Spc}(\K(E,R))$, i.e.,  $\K(E,R)(U)=(\K(E,R)/\K(E,R)_Z)^\natural$, with $Z=\mathrm{Spc}(\K(E,R))\backslash U$. By Theorem \ref{thm:comp LH is an homeomorphism} and Lemma \ref{lemma:open cover} we have exhibited an affine cover of $\mathrm{Spc}(\K(E,R)$ which gives us the following result. 

\begin{corollary}\label{cor: spc is a dirac scheme}
    Let $E$ be an elementary abelian $p$-group. Then $(\mathrm{Spc}(E,R),\mathcal{O}_E^\bullet)$ is a Dirac scheme in the language of \cite{HP23}.
\end{corollary}



\begin{corollary}\label{cor: comp is open immersion}
    The comparison map 
    \[
    \mathrm{Comp}_E\colon \mathrm{Spc}(\K(E,R))\to \Spec^h(H^{\bullet,\bullet}(E,R))
    \]
    is an open immersion.
\end{corollary}

\begin{proof}
    Note that the comparison map is an open immersion locally. Indeed,  for the open cover $\{U_E(H)\mid H\leq E\}$  of the spectrum, the restriction of the comparison map is a homeomorphism to the  open subset of $\Spec^h(H^{\bullet,\bullet}(E,R)$ given by 
\[
U(H)'=\bigcap_{H\not \leq N}Z(a_n)^c \cap \bigcap_{H\leq N}Z(b_N)^c
\] 
 where $Z(f)^c$ denotes the principal open defined by $f$ in $\Spec^h(H^{\bullet,\bullet}(E,R)$ (see Theorem \ref{thm:comp LH is an homeomorphism}). Since the comparison map is injective by Lemma \ref{comaprison is injective} and a locally open embedding, we obtain that it is an open embedding.
\end{proof}



\section{Examples}\label{sec: examples}

In this section, we use the tools developed in this article to describe the Balmer spectrum of $\K(G,\mathbb Z)$  for $G$ a cyclic $p$-group. We also discuss on other examples that follow a similar pattern.   

\begin{remark}
Let $G$ be a $p$-group. Recall that the \textit{modular fiber of $\Spc(\K(G,R))$} is the preimage of the comparison map $\Spc(\K(G,R))\to \Spec(\mathbb Z)$ at $(p)$. The \textit{ordinary fiber of  $\Spc(\K(G,R))$} is the set theoretic complement of the modular fiber.    
\end{remark}


\begin{proposition}\label{ordinary and modular fiber}
Let $G$ be a $p$-group. Then the ordinary fiber of $\Spc(\K(G,R))$, with the subspace topology, is homeomorphic to  $\Spec(R[1/p])$. In particular, we obtain a set decomposition 
\[
\Spc(\K(G,R))= \left( \coprod_{\pp\in \eta^{-1}(p)} \Spc(\iota_\pp^\ast) \Spc(\K(G,k(\pp))) \right) \amalg \Spec(R[1/p])
\]
where $\eta$ denotes the structural map $\Spec(R)\to \Spec(\mathbb Z)$. 
\end{proposition}

\begin{proof}
Consider the base change functor $f^\ast=-\otimes_R\colon \K(G,R)\to \K(G,R[1/p])$. By \cite[Lemma 2.24]{BG22}, we know that the functor $f^\ast$ is essentially surjective.  In particular, the proof of \cite[Lemma 6.9]{Gom25} tell us that the induced map on Balmer spectra 
\[
\Spc(\K(G,R[1/p])) \to \Spc(\K(G,R)) 
\]
is a topological embedding. Of course, there is no reason for the image of this map to be either closed or open in $\Spc(\K(G,R))$. Moreover, as we already noticed in the proof of Theorem \ref{colimit theorem}, the comparison map \[
\Spc(\K(G,R[1/p])) \to \Spec(R[1/n]) 
\]
is a homeomorphism. Indeed, it is a bijection by Proposition \ref{Spc as a set}; and hence an homeomorphisms since the category is End-finite. Thus the first claim follows. The second claim is immediate since the ordinary and modular fiber of $\Spc(\K(G,R))$ form a set partition. 
\end{proof}

\begin{remark}
Since the  map 
\[\Spc(\K(G,R))\xrightarrow{\mathrm{Comp}} \Spec(R)\xrightarrow{\eta}  \Spec(\mathbb Z)\] is continuous, we obtain that the modular fiber of $\Spc(\K(G,R))$ is a closed subset. Hence, there are no specialization relations from the modular fiber to the ordinary fiber but there might be specialization relations the other way around. In fact, such specialization relations are hard to describe in general. 
\end{remark}

Let us focus now on $\K(G,\mathbb Z)$ for $G$ a cyclic $p$-group.  

\begin{recollection}\label{spc for cp over fields}
Let $k$ denote a field of positive characteristic $p$, and let $G=C_{p^n}$ be the cyclic group of order $p^n$. By \cite[Section 8]{BG23b} we  know that the spectrum of $\K(C_{p^n},k)$ has the form 
%
\begin{equation}\label{eq:Spc Cn}
\Spc(\K(C_{p^n},k))=\qquad
\vcenter{\xymatrix@R=1em@C=.7em{
{\scriptstyle\mm_0\kern-1em}
& {\bullet} \ar@{-}@[Gray] '[rd] '[rr] '[drrr]
&&
{\bullet}
&{\kern-1em\scriptstyle\mm_1}
&&{\scriptstyle\mm_{n-1}\kern-1em}&\bullet&&\bullet&{\kern-1em\scriptstyle\mm_n}
\\
&{\scriptstyle\pp_1\kern-1em}& {\bullet}&&& {\cdots}& \ar@{-}@[Gray] '[ru] '[rr] '[rrru] &&\bullet&{\kern-1em}\scriptstyle\pp_{n}}}
\end{equation} 
consisting of $2n+1$ points and specialization relations pointing upward. In particular,  the closed subsets are   those that contain a $\pp_i$ only if they contain $\mm_{i-1}$ and $\mm_i$.
Hence the $\mm_i$ are closed points and the $\pp_i$ are generic points of the $n$ irreducible V-shaped closed subsets $\{\mm_{i-1},\pp_i,\mm_i\}$. Moreover, the points~$\pp_i$ and~$\mm_i$ can be described as follows. Consider a maximal normal series  of $G$
\[
0=N_n<N_{n-1}<\cdots<N_0=G.
\]
Then the points $\pp_i$ and $\mm_i$ in~$\Spc(\K(G,k))$ are given by 
\[
\mm_i=(\check{\Psi}^{N_i})(0)
\mbox{ and }
\pp_i=(\check{\Psi}^{N_i})(\mathbf{D}_{\mathrm{perf}}(\K(G/N_i,k)))
\]
where $\check{\Psi}^{N}=\Upsilon_{G/N}\circ\Psi^N\colon \K(G,k)\to\K(G/N,k)\to\mathbf{D}_b(\K(kG/N))$ is the functor from \cite[Notation 6.10]{BG22b}.
\end{recollection}

\begin{remark}
By Proposition \ref{ordinary and modular fiber}, we are left to check the possible specialization relations that can occur from the ordinary fiber to the  modular fiber. In fact, using again that the comparison map is continuous combined with the structure of $\Spec(\mathbb Z)$, we observe that  such specialization relations can only happen from the generic point in the ordinary fiber. We deal first with $G=C_p$ and the use Theorem \ref{colimit theorem} to extend the results to an arbitrary cyclic $p$-group.  
\end{remark}

\begin{notation}
Let $G$ be a cyclic $p$-group. Let identify $\Spc(\K(G,\mathbb F_p))$ with its image in $\Spc(\K(G,\mathbb F_p))$ under the map induced by the base change functor $\iota_p^\ast$ without further decorations on the notation. In particular, we simply write $\mm_i$ and $\pp_i$ to denote the image, under $\Spc(\iota_p^\ast)$, of the corresponding points in $\Spc(\K(G,\mathbb F_p))$ described in Recollection \ref{spc for cp over fields}.
\end{notation}

\begin{proposition}
Let $G=C_p$ be the cyclic group with $p$ elements. Then the Balmer spectrum of $\K(G,\mathbb Z)$ is homeomorphic to the space 
\begin{equation}
\kern2em\vcenter{\xymatrix@C=.0em@R=.4em{
{\color{Brown}\overset{(2)}{\bullet}}   \ar@{-}@[Brown][rrrrrrrrrrrdddd]  &&& {\color{Brown}\overset{(3)}{\bullet}}  \ar@{-}@<.1em>@[Brown][rrrrrrrrdddd]
&& \ldots
&& {\color{OliveGreen}\overset{\mm_0}{\bullet}} \ar@{-}@[OliveGreen][rdd] \ar@{~}@[Gray][rrrrdddd]
&& {\color{OliveGreen}\overset{\mm_1}{\bullet}} \ar@{-}@[OliveGreen][ldd] \ar@{~}@[Gray][rrdddd]
&&  \cdots  
&&  {\color{Brown}\overset{(q)}{\bullet}}  \ar@{-}@[Brown][lldddd] \ar@{.}@[Gray][r] 
&& \cdots
\\ \\
&&
&&
&&
&& {\color{OliveGreen}\underset{\pp_0}{\bullet}} 
&
& 
& 
&& 
&& 
&&
&&
&&
\\ \\
&&&&&&&&& && {\color{Brown}\bullet_{(0)}}\kern-1em
&&&&&&&& 
}}\kern-1.11em
\end{equation}
where the green part corresponds to the modular fiber and the brown part to the ordinary fiber. 
\end{proposition}

\begin{proof}
By Proposition \ref{ordinary and modular fiber}, it is enough to verify that $(0)$  specializes to the two closed points $\mm_0$ and $\mm_1$ in the modular fiber. First, recall the localization functor 
\[
\K(G,\mathbb Z) \to \mathbf{D}_{\textrm{perf}}(\mathbb Z G) 
\]  
induces an open immersion on Balmer spectra, and we refer to the image as the cohomological open part of $\Spc(\K(G,\mathbb Z))$. The complement of the cohomological open is precisely $\mm_0$. In fact, the cohomological open is 
\[
\Spc(\mathbf{D}_{\textrm{perf}}(\mathbb Z G))\cong \Spec^h(H^\ast(G,\mathbb Z))\cong \Spec(\mathbb{Z}[t]/(p\cdot t)).
\]
By direct inspection, we observe that $(0)$ specializes to $\mm_1$ in the cohomological open and hence in the whole $\Spc(\K(G,\mathbb Z))$.  It remains to verify that $(0)$ specializes to $\mm_0$. To this end, consider the triangular $G$-fixed points map 
\[
\Spec(\mathbb Z) \xrightarrow{\psi^G} \Spc(\K(G,\mathbb Z)).
\] 
It is not too hard to verify that this map is injective in general. Moreover, note that  $ \psi^G(p)=\mm_0$ and $\psi^G(0)=(0)$. Since injections preserve specializations and $(0)$ specializes to $(p)$ in $\Spec(\mathbb Z)$ we deduce the result. 
\end{proof}

\begin{remark}
We could have used twisted cohomology in the previous argument to describe the topology of $\K(C_p,\mathbb Z)$. Indeed, by Example \ref{Ex: twisted cohomology} we have that the reduced part of the twisted cohomology $H^{\bullet,\bullet}(C_p,\mathbb Z)$ is given by $\mathbb{Z}[a_N,b_N]/(p\cdot a_N,p\cdot b_N)$ where $N$ denotes the trivial subgroup of $C_p$. In this case, the cover of $\Spc(C_p,\mathbb Z)$ given in Lemma \ref{lemma:open cover} has two opens, namely $U(N)$ which is the open locus where $b_N$ is invertible and $U(C_p)$ that corresponds to the open locus where $a_N$ is invertible. Moreover, one can verify that $\mathcal{O}^\bullet(N)\cong \mathbb Z[a_N]/(p\cdot a_N)$ and $\mathcal{O}^\bullet(C_p)\cong \mathbb Z[b_N]/(p\cdot b_N)$. In other words, the opens $U(N)$ and $U(C_p)$ are both homeomorphic to $\Spec^h(H^\ast(C_p,\mathbb Z))$. Moreover, one of them identifies with the ordinary fiber of $\Spc(\K(C_p,\mathbb Z))$ and the points  $\pp_1$ and $\mm_0$ while the other open identifies with the ordinary fiber of $\Spc(\K(C_p,\mathbb Z))$ and the points  $\pp_1$ and $\mm_1$ recovering the description given above.  
\end{remark}

\begin{proposition}
Let $G=C_{p^n}$ be the cyclic group of order $p^n$. Then the Balmer spectrum of $\K(G,\mathbb Z)$ is homeomorphic to the space 
\begin{equation*}
\kern2em\vcenter{\xymatrix@C=.0em@R=.4em{
{\color{Brown}\overset{(2)}{\bullet}}    \ar@{-}@[Brown][rrrrrrrrrrrrrrrrdddd]
&& {\color{Brown}\overset{(3)}{\bullet}}  \ar@{-}@[Brown][rrrrrrrrrrrrrrdddd]
