&& {\color{OliveGreen}\overset{\mm_n}{\bullet}} \ar@{-}@[OliveGreen][ldd] \ar@{~}@[Gray][rrdddd] 
&& {\color{OliveGreen}\cdots}
&& {\color{Brown}\overset{(q)}{\bullet}}  \ar@{-}@[Brown][lldddd]
&& \cdots 
\\ \\ 
&&  
