\title{From Axioms to Algorithms: \\ Mechanized Proofs of the vNM Utility Theorem}
\author{Jingyuan Li\thanks{Email: \texttt{jingyuanli@ln.edu.hk}. Department of Operations and Risk Management, Lingnan University.}}
\date{May 18, 2025}

