\begin{proof}
    Since all proofs are similar, we will only show the third reduction. This equates to proving
    \[  
    \mathbb{E}|S_i - y|_+^{-3} |S_i - z|_+^{-3/2} \le C |i|_+^{-3/4} |y|_+^{-3/2} |y-z|_+^{-3/2}.
    \]
    By the triangle inequality and Holder's inequality, $|y-z|_+^{3/2} \le C(|S_i - y|_+^{3/2} + |S_i - z|_+^{3/2})$. Therefore,
    \begin{align*}
        |y-z|_+^{3/2} \mathbb{E}|S_i - y|_+^{-3} |S_i - z|_+^{-3/2} &\le C\left( \mathbb{E}|S_i - y|_+^{-3/2} |S_i-z|_+^{-3/2} + \mathbb{E} |S_i - y|_+^{-3} \right) \\
        &\le C \left(\mathbb{E}|S_i-y|_+^{-3} \right)^{1/2} \left\{\left(\mathbb{E}|S_i-y|_+^{-3} \right)^{1/2} + \left(\mathbb{E}|S_i-z|_+^{-3} \right)^{1/2} \right\} \\
        &\le C |y|_+^{-3/2} |i|_+^{-3/4}
    \end{align*}
    By Lemma~\ref{lem:rw-moment}.
\end{proof}

