\end{tikzpicture} \right] C^2 |j_m - j_{m-1}|_+^{-3/4} |j_{m-1} - j_{m-2}|_+^{-3/4} \\
&\vdots \\
&\le \mathbb{E} \left[ \begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
        \coordinate[vtx] (u1) at (0, 0);
        \node at (u1) [below] {$S_{i_1}$};
        \coordinate[vtx] (v1) at (0, 1);
        \node at (v1) [above] {$\tilde{S}_{j_1}$};
        \draw[thick] (v1) -- (u1);        
        \coordinate[vtx] (u2) at (1, 0);
        \node at (u2) [below] {$S_{i_2}$};
        \draw[thick, red] (v1) -- (u2);       
        \coordinate[vtx] (u3) at (3, 0);
        \node at (u3) [below] {$S_{i_{m-1}}$};
        \draw[thick, red] (u3) -- (u2) node [below, midway, black] {$\dots$};
        \coordinate[vtx] (u4) at (4, 0);
        \node at (u4) [below] {$S_{i_{m}}$};
        \draw[thick, red] (u3) -- (u4);
\end{tikzpicture} \right] C^{m-1} \prod_{k=2}^m |j_k - j_{k-1}|_+^{-3/4} \\
&\le \mathbb{E} \left[ \begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
        \coordinate[vtx] (u0) at (-1, 0);
        \node at (u0) [below] {$0$};
