        \draw[thick, red] (u3) -- (u4);
        \coordinate[vtx] (u6) at (5.5, 0);
        \node at (u6) [below] {$S_{i_{m}}$};
        \draw[thick, red] (u4) -- (u6) node [below, midway, black] {$\dots$};
\end{tikzpicture} \right] &\le \mathbb{E} \left[ \begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
         \coordinate[vtx] (u0) at (0.5, 0);
        \node at (u0) [below] {$0$};
