        \draw[thick, red] (u3) -- (u4);
\end{tikzpicture} \right] &\le \mathbb{E} \left[ \begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
        \coordinate[vtx] (u0) at (-1, 0);
        \node at (u0) [below] {$0$};
        \coordinate[vtx] (u1) at (0, 0);
        \node at (u1) [below] {$S_{i_1}$};  
        \draw[thick, red] (u1) -- (u0); 
        \coordinate[vtx] (u2) at (1, 0);
        \node at (u2) [below] {$S_{i_2}$};
        \draw[thick, red] (u1) -- (u2);     
        \coordinate[vtx] (u3) at (3, 0);
        \node at (u3) [below] {$S_{i_{m-2}}$};
        \draw[thick, red] (u3) -- (u2) node [below, midway, black] {$\dots$};
        \coordinate[vtx] (u4) at (4, 0);
        \node at (u4) [below] {$S_{i_{m-1}}$};
        \draw[thick, red] (u3) -- (u4);
