\end{align*}
After repeating this process $m$ times and combining with the above, we get
\begin{equation}
    \label{eq:cross-term-1}
    \mathbb{E} \left[ \prod_{k = 1}^{m} |S_{i_k} - \tilde{S}_{j_{k}}|_+^3 \right] \le C^m \prod_{k=1}^m |j_k - j_{k-1}|_+^{-3/4} \prod_{k=1}^m |i_{\sigma(k)} - i_{\sigma(k-1)}|_+^{-3/4}.
\end{equation}
Further, by following methods similar to \cite[Lemma~4.1]{DemboOkada2024}, we have
\begin{align*}
    \sum_{1 \le j_1 \le \dots \le j_m \le n} \prod_{k=1}^m |j_k - j_{k-1}|_+^{-3/4} &\le C n^{m/4} \sum_{1 \le j_1 \le \dots \le j_m \le n} \prod_{k=1}^m \left[ \frac{1}{n} \left| \frac{j_k}{n} - \frac{j_{k-1}}{n} \right|^{-3/4} \right] \\
    &\le Cn^{m/4} \int_{0 \le x_1 \le \dots \le x_m \le 1} |x_k - x_{k-1}|^{-3/4} \mathrm{d} x_1 \dots \mathrm{d} x_m \\
    &\le C^m (m!)^{-1/4} n^{m/4}.
\end{align*}
The last inequality comes from \cite[Lemma]{Kono1977}. Now, summing over all $(m!)^2$ orderings of $j_1, \dots , j_m$ and $i_1, \dots , i_m$ completes the proof.
\begin{align*}
    \sum_{1 \le i_1,\ldots i_m,j_1,\ldots, j_m \le n}\mathbb{E} \left[ \prod_{k = 1}^{m} |S_{i_k} - \tilde{S}_{j_{k}}|_+^3 \right] &\le C^m (m!)^2 \left( \sum_{1 \le j_1 \le \dots \le j_m \le n}\prod_{k=1}^m |j_k - j_{k-1}|_+^{-3/4} \right)^2 \\
    &\le C^m (m!)^{3/2} n^{m/2}.
\end{align*}
\end{proof}

