\begin{proof}
    The proof is similar to Lemma~\ref{lem:cross-term-graph}. Since all proofs are similar, we will only explain the third operation in \eqref{eq:error-term-graph-1}. This equates to showing
    \[
    \mathbb{E} |S_i - y|_+^{-3} |S_i - z|^{-1} |S_i - w|_+^{-1} \le C |i|_+^{-1} |y|_+^{-1} |y-z|_+^{-1} |w|_+^{-1}.
    \]
    First note that $|y-z|_+ \le |S_i -y|_+ + |S_i - z|_+$ by the triangle inequality. Thus,
    \begin{align*}
        |y-z|_+ \mathbb{E} &|S_i - y|_+^{-3} |S_i - z|^{-1} |S_i - w|_+^{-1} \\
        &\le \mathbb{E}|S_i - y|_+^{-2} |S_i - z|^{-1} |S_i - w|_+^{-1} + \mathbb{E}|S_i - y|_+^{-3} |S_i - w|_+^{-1} \\
        &\le \left(\mathbb{E}|S_i-y|_+^{-4} \right)^{1/4}\left(|S_i - w|_+^{-4} \right)^{1/4} \left\{\left(\mathbb{E}|S_i-y|_+^{-4} \right)^{1/4}\left(|S_i - z|_+^{-4} \right)^{1/4} +  \left(\mathbb{E} |S_i - y|_+^{-4} \right)^{1/2} \right\} \\
        &\le C |y|_+^{-1} |w|_+^{-1} |i|_+^{-1}
    \end{align*}
    by Lemma~\ref{lem:rw-moment} and H\"{o}lder's inequality.
\end{proof}

