    \coordinate[vtx] (u2) at (3, 0);
    \node at (u2) [below] {$S_{i_{\phi(3)}}$};
    \coordinate[vtx] (u3) at (4.5, 0);
    \node at (u3) [below] {$S_{i_{\phi(4)}}$};
    \node at (6, 1) {$\dots$};
    \coordinate[vtx] (v4) at (7.5, 2);
    \node at (v4) [above] {$\tilde{S}_{j_{2m-1}}$};
    \coordinate[vtx] (v5) at (9, 2);
    \node at (v5) [above] {$\tilde{S}_{j_{2m}}$};
    \coordinate[vtx] (u4) at (7.5, 0);
    \node at (u4) [below] {$S_{i_{\phi(2m-1)}}$};
    \coordinate[vtx] (u5) at (9, 0);
    \node at (u5) [below] {$S_{i_{\phi(2m)}}$};
    \draw[thick] (u0) -- (v0);
    \draw[thick] (u1) -- (v1);
    \draw[thick] (u2) -- (v2);
    \draw[thick] (u3) -- (v3);
    \draw[thick] (u4) -- (v4);
    \draw[thick] (u5) -- (v5);
\end{tikzpicture}
\]
for arbitrary two-to-one maps $\phi : \{ 1, 2, \dots , 2m \} \to \{ 1, \dots, m \}$. Since we are considering all such maps, we can also assume $i_1 \le \dots \le i_m$ without loss of generality. 

Now, we provide an algorithm that works for all such graphs. Consider the following coloring on the multi-set $\{S_{i_{\phi(1)}}, \dots , S_{i_{\phi(2m)}}\}$. First, color $S_{i_{\phi(2m)}}$ blue and $S_{i_{\phi(2m-1)}}$ red. Now, going from right to left, if $S_{i_{\phi(k)}}$ has not already appeared, give it an arbitrary color. If it has appeared, color it the opposite of what it was colored previously. Since $S_{i_{\phi(2m)}}$ and $S_{i_{\phi(2m-1)}}$ have different colors, \eqref{eq:error-term-graph-1} gives a unique way of reducing this graph. Further, this process gives two paths, one red and one blue, that are joined at $0$. Since each vertex $S_{i_k}$ appears once as red and once as blue, each monochromatic path is a permutation of $\{ S_{i_1} , \dots , S_{i_m} \}$. In summary, we get the following inequality after reduction.
\begin{equation}
\label{eq:error-term-1}
\mathbb{E} \left[ \begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
    \coordinate[vtx] (v1) at (1, 2);
    \node at (v1) [above] {$\tilde{S}_{j_1}$};
    \coordinate[vtx] (v2) at (2, 2);
    \node at (v2) [above] {$\tilde{S}_{j_2}$};
    \coordinate[vtx] (v4) at (4, 2);
    \node at (v4) [above] {$\tilde{S}_{j_{2m}}$};
    \coordinate[openvtx] (u1) at (1, 0);
    \node at (u1) [below] {$S_{i_{\phi(1)}}$};
    \coordinate[openvtx] (u2) at (2, 0);
    \node at (u2) [below] {$S_{i_{\phi(2)}}$};
    \coordinate[openvtx] (u4) at (4, 0);
    \node at (u4) [below] {$S_{i_{\phi(2m)}}$};
    \draw[thick] (v1) -- (u1);
    \draw[thick] (v2) -- (u2);
    \draw[thick] (v4) -- (u4);
    \node at (3, 1) {$\dots$};
\end{tikzpicture}
\right] \le \mathbb{E} \left[
\begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
    \coordinate[vtx] (w) at (0, 1);
    \node at (w) [left] {$0$};
    \coordinate[vtx, red] (v1) at (1, 2);
    \node at (v1) [above] {$S_{i_{\sigma(1)}}$};
    \coordinate[vtx, red] (v2) at (2.5, 2);
    \node at (v2) [above] {$S_{i_{\sigma(2)}}$};
    \coordinate[vtx, red] (v4) at (5, 2);
    \node at (v4) [above] {$S_{i_{\sigma(m)}}$};
    \coordinate[vtx, blue] (u1) at (1, 0);
    \node at (u1) [below] {$S_{i_{\tau(1)}}$};
    \coordinate[vtx, blue] (u2) at (2.5, 0);
    \node at (u2) [below] {$S_{i_{\tau(2)}}$};
    \coordinate[vtx, blue] (u4) at (5, 0);
    \node at (u4) [below] {$S_{i_{\tau(m)}}$};
    \draw[thick, red] (w) -- (v1) -- (v2) -- (v4);
    \draw[thick, blue] (w) -- (u1) -- (u2) -- (u4);
    \node at (3.75, 2.5) {$\dots$};
    \node at (3.75, -0.5) {$\dots$};
\end{tikzpicture}
\right] C^{2m} \prod_{k=1}^{2m} |j_k - j_{k-1}|_+^{-1}.
\end{equation}
Here, $\sigma$ and $\tau$ are permutations of $\{ 1, \dots , m \}$ such that $S_{i_1} , \dots , S_{i_m}$ appear in the same order on both sides.That is, $\{\sigma(i)\}_{i=1}^m$ and $\{ \tau(i)\}_{i=1}^m$ are disjoint subsequences of $\{ \phi(i)\}_{i=1}^{2m}$. Now we can use \eqref{eq:error-term-graph-2} to reduce this graph further. This gives
\[  
\mathbb{E} \left[
\begin{tikzpicture}[scale=0.7, baseline=(current bounding box.center)]
    \coordinate[vtx] (w) at (0, 1);
    \node at (w) [left] {$0$};
    \coordinate[vtx, red] (v1) at (1, 2);
    \node at (v1) [above] {$S_{i_{\sigma(1)}}$};
    \coordinate[vtx, red] (v2) at (2.5, 2);
    \node at (v2) [above] {$S_{i_{\sigma(2)}}$};
    \coordinate[vtx, red] (v4) at (5, 2);
    \node at (v4) [above] {$S_{i_{\sigma(m)}}$};
    \coordinate[vtx, blue] (u1) at (1, 0);
    \node at (u1) [below] {$S_{i_{\tau(1)}}$};
    \coordinate[vtx, blue] (u2) at (2.5, 0);
    \node at (u2) [below] {$S_{i_{\tau(2)}}$};
    \coordinate[vtx, blue] (u4) at (5, 0);
    \node at (u4) [below] {$S_{i_{\tau(m)}}$};
    \draw[thick, red] (w) -- (v1) -- (v2) -- (v4);
    \draw[thick, blue] (w) -- (u1) -- (u2) -- (u4);
    \node at (3.75, 2.5) {$\dots$};
    \node at (3.75, -0.5) {$\dots$};
\end{tikzpicture}
\right] \le C^m \prod_{k=1}^{m} |i_k - i_{k-1}|_+^{-1}.
\]
One key point here is that a vertex never neighbors itself, since they are on opposite sides of $0$. Combined with \eqref{eq:error-term-1} and summing over $i_1 \le \dots \le i_m$, $j_1 \le \dots \le j_{2m}$ and their $m! \times (2m)!$ possible reorderings, we have
\begin{align*}
\mathbb{E} \left[ \sum_{1 \le i_1 , \dots , i_m \le n} \right. & \left. \sum_{1 \le j_1 , \dots , j_{2m} \le n} \prod_{k = 1}^{m} |S_{i_k} - \tilde{S}_{j_{2k-1}}|_+^3 |S_{i_k} - \tilde{S}_{j_{2k}}|_+^3 \right] \\
&\le C^{m} (m!)(2m)! \left( \prod_{k=1}^{2m} \sum_{j_k = j_{k-1}}^n |j_k - j_{k-1}|_+^{-1} \right) \left( \prod_{k=1}^{m} \sum_{i_k = i_{k-1}}^n |i_k - i_{k-1}|_+^{-1} \right) \\
&\le C^m (m!)(2m)! \left( \sum_{j=1}^n |j|_+^{-1} \right)^{3m} \\
&\le C^m (m!)^{3} (\log n)^{3m}.
\end{align*}
\end{proof}

\begin{lemma}
\label{lem:aux-error-moment}
Recall that $[n]^{(l, p)} = [2^{-l} n(p-1), 2^{-l}n p]$ denotes the $p$-th piece of the interval $\{ 0, 1, \dots ,n \}$. For any $l$, let
\begin{equation}
\label{eq:aux-error-def}
\begin{aligned}
X_l := \sum_{p = 1}^{2^{l-1}} \sum_{i =1}^n \sum_{j_1 \in [0,n]^{(l, 2p-1)}} \sum_{j_2 \in [0,n]^{(l, 2p)}} G_D (S_i - \tilde{S}_{j_1}) G_D(\tilde{S}_{j_1} - \tilde{S}_{j_2}) \\
Y_l := \sum_{p = 1}^{2^{l-1}} \sum_{i =1}^n \sum_{j_1 \in [0,n]^{(l, 2p-1)}} \sum_{j_2 \in [0,n]^{(l, 2p)}} G_D (S_i - \tilde{S}_{j_2}) G_D(\tilde{S}_{j_1} - \tilde{S}_{j_2}) \\
Z_l := \sum_{p = 1}^{2^{l-1}}  \sum_{i_1 \in [0,n]^{(l, 2p-1)}} \sum_{i_2 \in [0,n]^{(l, 2p)}}\sum_{j=1}^n G_D (S_{i_1} - \tilde{S}_j) G_D(S_{i_1} - S_{i_2}) \\
W_l := \sum_{p = 1}^{2^{l-1}}  \sum_{i_1 \in [0,n]^{(l, 2p-1)}} \sum_{i_2 \in [0,n]^{(l, 2p)}}\sum_{j=1}^n  G_D (S_{i_2} - \tilde{S}_j) G_D(S_{i_1} - S_{i_2}) \\
\end{aligned}
\end{equation}
Then,
\begin{equation}
\label{eq:aux-error-moment}
\mathbb{E}[X_l^m], \mathbb{E}[Y_l^m], \mathbb{E}[Z_l^m], \mathbb{E}[W_l^m] \le  C^m 2^l e^{2^l / m} (m!)^3 (\log n)^{3m}.
\end{equation}
\end{lemma}

\begin{proof}
