    % & \overset{iterated exp}{=} \frac{1}{P(T\in\mathcal{T}_a | X\in \xg)} \frac{E[P(T\in\mathcal{T}_a | X) P(T=t|X=x)|X\in\xg]}{P(T\in\mathcal{T}_a | X\in \xg)} \\
    % & = \frac{P(T\in\mathcal{T}_a | X\in \xg)}{P(T\in\mathcal{T}_a | X\in \xg)} \frac{E[ P(T=t|X=x)|X\in\xg]}{P(T\in\mathcal{T}_a | X\in \xg)} \\
