    &= \sum_{t\in\ta} E[e_{ta}(X) \mu_{t}(X) |X\in \xg]\\
    % &= \sum_{t\in\ta} E[e_{ta}(X) |X\in \xg] E[\mu_{t}(X) |X\in \xg] + Cov[e_{ta}(X), \mu_{t}(X) |X\in \xg]\\
    &= \sum_{t\in\ta} E[e_{ta}(X) |X\in \xg] \mu_{t}(\xg) + Cov[e_{ta}(X), \mu_{t}(X) |X\in \xg]\\
    &= \sum_{t\in\ta} e_{ta}(\xg) \mu_{t}(\xg) + Cov[e_{ta}(X), \mu_{t}(X) |X\in \xg] + (E[e_{ta}(X) |X\in \xg] - e_{ta}(\xg)) \mu_{t}(\xg)
\end{align*}}

\subsection{Derivation of Adjusted Mean Decomposition with Covariate Adjustment for Aggregate Treatment Only}  \label{app:deriv-acm-xtilde}
Define $\tilde{X}$ as some subset of $X$ such that $\sum_{t\in\ta}\mathbbm{1}(T=t)Y(t) \bigCI \mathbbm{1}(T \in \ta)~|\tilde{X}$, i.e.~``binary unconfoundedness'' applies. Denote $\mu_{t,t}(\tilde{X}) := E[Y(t)|T=t,\tilde{X}]$ as the conditional average potential outcome of the treated. The decomposition for the adjusted component in Equation \eqref{eq:decomp-cm2} then changes to

{\footnotesize \begin{align*}
    E&[E[Y|T\in\mathcal{T}_a,\tilde{X}]|\tilde{X}\in \xg] \\
    % &= E\left[E\left[\sum_{t\in\ta} \mathbbm{1}(T=t)Y(t)|T\in\mathcal{T}_a,\tilde{X}\right] \middle|\tilde{X}\in \xg\right] \\
    % &= \sum_{t\in\ta} E[E[ \mathbbm{1}(T=t)Y(t)|T\in\mathcal{T}_a,\tilde{X}] |\tilde{X}\in \xg] \\
    % &= \sum_{t\in\ta} E[P(T=t | T\in\mathcal{T}_a,\tilde{X}) E[Y(t)|T=t,T\in\mathcal{T}_a,\tilde{X}] |\tilde{X}\in \xg] \\
    % &= \sum_{t\in\ta} E[P(T=t | T\in\mathcal{T}_a,\tilde{X}) E[Y(t)|T=t,\tilde{X}] |\tilde{X}\in \xg] & \\
    &= \sum_{t\in\ta} E[e_{ta}(\tilde{X}) \mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] \\
    % &= \sum_{t\in\ta} E[e_{ta}(\tilde{X}) |\tilde{X}\in \xg] E[\mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] + Cov[e_{ta}(\tilde{X}), \mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg]\\
    &= \sum_{t\in\ta} e_{ta}(\xg) E[\mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] + Cov[e_{ta}(\tilde{X}), \mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] \\
    & \quad  + (E[e_{ta}(\tilde{X}) |\tilde{X}\in \xg] - e_{ta}(\xg)) E[\mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] \\
    &= \sum_{t\in\ta} e_{ta}(\xg) \mu_{t}(\xg) + Cov[e_{ta}(\tilde{X}), \mu_{t}(\tilde{X}) |\tilde{X}\in \xg] + (E[e_{ta}(\tilde{X}) |\tilde{X}\in \xg] - e_{ta}(\xg)) \mu_{t}(\xg) \\
    & \quad + e_{ta}(\xg) (E[\mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] - \mu_{t}(\xg)) \\
    & \quad  + Cov[e_{ta}(\tilde{X}), \mu_{t,t}(\tilde{X}) - \mu_{t}(\tilde{X}) |\tilde{X}\in \xg] \\
    & \quad + (E[e_{ta}(\tilde{X}) |\tilde{X}\in \xg] - e_{ta}(\xg)) (E[\mu_{t,t}(\tilde{X}) |\tilde{X}\in \xg] - \mu_{t}(\xg)).    
\end{align*}}
% where we could replace 
% $$\mu_{t,t}(\tilde{X}) - \mu_{t}(\tilde{X}) = Cov\left(\frac{e_t(X)}{e_t(\tilde{X})},\mu_t(X) | \tilde{X} \right)$$ 

The first line resembles the decomposition in main text with $X$ replaced by $\tilde{X}$. However, three additional terms appear because usually $\mu_{t,t}(\tilde{X}) \neq \mu_{t}(\tilde{X})$, i.e.~there is a form of conditional selection bias on the level of the effective treatment. Thus, these three terms can be interpreted as (i) group targeting based on group selection bias (ii) individualized target based on individual selection bias given group membership, and (iii) interaction between composition adjustment for aggregate treatment balance and group selection bias.


