        H_0:~& e_{ta}(\xg) = e_{ta}(\xgp) \text{ for all } t \in \ta \text{, and } e_{t'a'}(\xg) = e_{t'a'}(\xgp) \text{ for all } t' \in \tap, \label{eq:h0-tah} \\
        H_A:~& e_{ta}(\xg) \neq e_{ta}(\xgp) \text{ for some } t \in \ta \text{, and/or } e_{t'a'}(\xg) \neq e_{t'a'}(\xgp) \text{ for some } t' \in \tap, 
    \end{align}}
    % \item with either \textit{average treatment version irrelevance} (TH2):
    %  {\footnotesize \begin{align}
    %     H_0:~& \mu_t = \mu_{t^\dagger} \text{ for all }t, t^\dagger \in \mathcal{T}_a \text{ and } \mu_t = \mu_{t^\dagger} \text{ for all } t, t^\dagger \in \mathcal{T}_{a'} \label{eq:h0-tvia} \\
    %     H_A:~& \mu_t \neq \mu_{t^\dagger} \text{ for some } t, t^\dagger \in \mathcal{T}_a \text{, and/or } \mu_t \neq \mu_{t^\dagger} \text{ for some } t, t^\dagger \in \mathcal{T}_{a'} \nonumber
    % \end{align}}
    \item and \textit{group treatment version irrelevance}:
     {\footnotesize \begin{align}
        H_0:~& \mu_t(\xg) = \mu_{t^\dagger}(\xg) \text{ for all }t, t^\dagger \in \mathcal{T}_a \text{ and } \mu_t(\xg) = \mu_{t^\dagger}(\xg) \text{ for all } t, t^\dagger \in \mathcal{T}_{a'}, \label{eq:h0-tvia} \\
        H_A:~& \mu_t(\xg) \neq \mu_{t^\dagger}(\xg) \text{ for some } t, t^\dagger \in \mathcal{T}_a \text{, and/or } \mu_t(\xg) \neq \mu_{t^\dagger}(\xg) \text{ for some } t, t^\dagger \in \mathcal{T}_{a'}. 
    \end{align}}
\end{itemize}
% \end{itemize}
One way to test these hypotheses jointly is to consider parameter combination $d_2 + d_3$
{\footnotesize \begin{align*}
d_{2}(a,g) + d_{3}(a,g) & = \sum_{t\in\ta} [e_{ta}(\xg) - e_{ta}] \mu_t + [e_{ta}(\xg) - e_{ta}] [\mu_t(\xg) - \mu_t] \\
 % & = \sum_{t\in\ta} [e_{ta}(\xg) - e_{ta}] \mu_t(\xg) \\
 & = \sum_{t\in\ta} [e_{ta}(\xg) - e_{ta}] [\mu_t(\xg) - \mu_a(\xg)],
\end{align*}}
where $\mu_a(\xg) = \sum_{t\in\ta} e_{ta} \mu_t(\xg)$. This means that rejecting $d_2 + d_3 = 0$ is sufficient to reject both \eqref{eq:h0-tah} and \eqref{eq:h0-tvia} and therefore treatment homogeneity. Similarly $\delta_2 + \delta_3$ and $\Delta_2 + \Delta_3$ can serve as tests of group treatment heterogeneity. Many other parameter (combinations) imply average or individualized treatment homogeneity tests. However, they are usually not of primary interest and therefore not explicitly discussed here.

\subsection{Alternative Centering} \label{sec_centering1}
% $e_a$ to $e_a(\xg \cup \mathcal{X}_{g'})$ and $\mu$ to $\mu(\xg \cup \mathcal{X}_{g'})$ or same with $\bigcup_{g\in\mathcal{G}}\xg$. Analogue to BO. Same implied hypothesis as above. However, scale different. power against other alternatives. [const effect for g1 g2, but not necces medium that is not analyzed e.g. if we have g1,g2,g3]
The decomposition of the synthetic estimand \eqref{eq:decomp-srct} and its resulting differences are centered around unconditional within aggregate propensities $e_{ta}$ and potential outcomes $\mu_t$. These allowed us to decompose and contrast heterogeneity estimands relative to the full population. For instance, $d_0$ would be a synthetic estimand corresponding to constant effects and propensities in the whole population. When assessing heterogeneity between groups $g$ and $g'$, we might instead want to build contrasts relative to a scenario where there is homogeneity across exactly the groups we compare. 
Consider two groups characterized by $\mathcal{X}_g$ and $\mathcal{X}_{g'}$. We could center the decomposition of the stratified RCT in \eqref{eq:decomp-srct} only around the respective averages over these groups, $e_{a}(\xg \cup \xgp)$ and $\mu(\xg \cup \xgp)$, i.e.

 {\footnotesize \begin{align}
     \sum_{t\in\ta} e_{ta}(\xg) \mu_t(\xg) 
     &=\sum_{t\in\ta} \underbrace{e_{ta}(\xg \cup \xgp) \mu_t(\xg \cup \xgp)}_{\text{baseline}} + \underbrace{e_{ta}(\xg \cup \xgp) [\mu_t(\xg) - \mu_t(\xg \cup \xgp)]}_{\text{outcome heterogeneity}} \notag \\  &\quad + \underbrace{[e_{ta}(\xg) - e_{ta}(\xg \cup \xgp)] \mu_t(\xg \cup \xgp)}_{\text{group targeting of average outcomes}} \notag \\ &\quad  + \underbrace{[e_{ta}(\xg) - e_{ta}(\xg \cup \xgp)] [\mu_t(\xg) - \mu_t(\xg \cup \xgp)]}_{\text{group targeting of group outcomes}},
 \end{align}}

where now heterogeneity and targeting are defined relative to the composite group $\xg \cup \mathcal{X}_{g'}$. When these groups form a complete partition, $\xg \cup \mathcal{X}_{g'} = \mathcal{X}$, this collapses back to the original decomposition \eqref{eq:decomp-srct}.
From a definition perspective centering the decompositions around other quantities is also possible. For estimation and inference, however, the centering quantities need to behave qualitatively similar to the conditional means and propensities, see Section \ref{sec_estimation1}. Analogous to the discussion in previous sections, these alternative decompositions will have a different economic interpretation and power against alternatives that match their respective weighting schemes.



\section{Proof of Theorem \ref{thm_asyN1}}
\label{sec_app_inference}
\subsection{Preliminaries and Definitions}
For generic $A$ and $B$, we often make use of the following decomposition {\footnotesize \begin{align*}
  \hat{A}\hat{B} -  AB = (\hat{A} - A)B + A(\hat{B} - B) + (\hat{A} - A)(\hat{B} - B).
\end{align*}}
For random variable $A$ and sample $i=1,\dots,n$, we denote  $E_n[A] = \frac{1}{n}\sum_i^nA_i$ and  $G_n[A] = \frac{1}{\sqrt{n}}\sum_{i}^n(A_i - E[A_i])$.
% {\footnotesize \begin{align*}
%     E_n[A] &= \frac{1}{n}\sum_i^nA_i, \\
%     G_n[A] &= \frac{1}{\sqrt{n}}\sum_{i}^n(A_i - E[A_i]).
% \end{align*}}
% Moreover, let $\1_t = \1(T=t)$ and {\footnotesize \begin{align*}
%     r_{e,n} = \sup_{\hat{e}\in \mathcal{E}_n,x\in \mathcal{X}}\frac{e_t(x)}{\hat{e}_t(x)}
% \end{align*}}
%All sums and suprema that run or are defined for entries in $\mathcal{T}_a$ only, e.g.~$\sup_t e_t(x) = \sup_{t\in\mathcal{T}_a} e_t(x)$ and $\sum_{t\neq s}\mu_t = \sum_{t\in\mathcal{T}_a:t\neq s}\mu_t$. 
We denote the efficient influence function for a average potential outcome $E[Y(t)] = \mu_t$ as {\footnotesize \begin{align*}
    \psi_t(\eta) &= \frac{\mathbbm{1}(T=t)(Y-\mu_t(X))}{e_t(X)} + \mu_t(X) - \mu_t 
    = \frac{\mathbbm{1}_t\varepsilon(t)}{e_t(X)} + \mu_t(X) - \mu_t, 
\end{align*}}
where $\1_t = \1(T=t)$ and $\varepsilon(t) = Y(t)-\mu_t(X)$. We omit the true nuisance function argument $\eta$ whenever irrelevant. Without loss of generality, we limit our attention to sequences where $\sup_{t\in\ta}Je_t \lesssim 1$. The extension to the complete case with lower bounded propensities as in Assumption A.4 is trivial as, by construction, there can only be a finite number of treatments appearing at this rate. We also define the sequence space $
     \ell^2(\mathcal{T}_a) = \{ g : \sum_{t\in\ta}|g(t)|^2 < \infty \} 
$
and inner product relative to counting measure $
    \ip{g_1(x),g_2(x)}_{\ell^2(\mathcal{T}_a)} = \sum_{t\in\ta} g_1(t,x)g_2(t,x)$,
where $g_1,g_2$ are generic functions (possibly indexed by some $x \subseteq \mathcal{X}$).

\subsection{IF-based Estimator and Expansion} \label{sec_proof_ifbasedestimator}
Let $\IF(\theta) = \IF(\theta,W,\eta)$ be the (vector of) centered orthogonalized moments or ``influence curves'' \cite{Kennedy2024SemiparametricReview} for any parameter $\theta$ using data $W = (Y,T,X)$ and nuisance functions $\eta \in \mathcal{H}$. Denote $\hat{\IF}(\theta) = \IF(\theta,W,\hat{\eta})$ where $\hat{\eta} \in \mathcal{H}_n$ are the cross-fitted nuisance parameters. 
For the proof, we first consider the parameter $d_0(a) = {d}_0(a)(e_a,\mu) = \ip{e_a,\mu}_{\ell^2(\ta)}$. The extension to all other decomposition parameters is then given in subsection \ref{app_proof_N_decompALL}.
% We first derive the asymptotic theory for the single parameter ${d}_0(a) = \ip{{e}_a,{\mu}}_{\ell^2(\ta)} = \sum_{t\in\mathcal{T}_a}e_{ta}\mu_t$. The extension to the other decomposition parameters and their joint convergence follows. 
The estimated decomposition parameter is given by $
    \hat{d}_0(a) = \ip{\hat{e}_a,\hat{\mu}}_{\ell^2(\ta)} $
The influence function estimators take the plug-in estimators using the empirical analogue for each component
$E_n[\hat{\IF}(\hat{\mu})] = 0$ and $E_n[\hat{\IF}(\hat{e}_a)] = 0$. 
We obtain the following expansion 

{\footnotesize \begin{align*}
    \hat{d}_0(a) - \ip{{e}_a,{\mu}}_{\ell^2(\ta)}
    &= \ip{\hat{e}_a - e_a,{\mu}}_{\ell^2(\ta)} + \ip{{e}_a,\hat{\mu} - \mu}_{\ell^2(\ta)} + \ip{(\hat{e}_a - e_a),(\hat{\mu} - \mu)}_{\ell^2(\ta)}, 
\end{align*}}
which yields {\footnotesize \begin{align*}
    \sqrt{n}(\hat{d}_0(a) - {d}_0(a))
    &= G_n\left[\hat{\IF}({d}_0(a))\right]\left( 1 + O_p\left(E_n[\mathbbm{1}(T\in\mathcal{T}_a)] - P(T\in\mathcal{T}_a)\right) \right)\\ &\quad + \sqrt{n}\ip{(\hat{e}_a - e_a),(\hat{\mu} - \mu)}_{\ell^2(\ta)}. 
\end{align*}}
The first term on the right hand side can be further expanded as {\footnotesize \begin{align*}
    G_n\left[\hat{\IF}({d}_0(a))\right]
    &= \underbrace{G_n\left[{\IF}({d}_0(a))\right]}_{\text{Leading Term}} + \underbrace{\left(G_n\left[\hat{\IF}({d}_0(a))\right] - G_n\left[{\IF}({d}_0(a))\right]\right)}_{\text{Empirical Process}} \\
    &\quad + \underbrace{\sqrt{n}\left(E\left[\hat{\IF}({d}_0(a))\right] - E\left[{\IF}({d}_0(a))\right] \right)}_{\text{Machine Learning Bias}}. 
\end{align*}}





\subsection{Bounding the Machine Learning Bias} \label{sec_proof_mlbias1}
%We now verify the conditions from \citeA{Chernozhukov2018}, Assumption 3.2(iii) 
We now bound the machine learning bias for the given influence function 
$ {\IF}({d}_0(a)) = \sum_{t\in\mathcal{T}_a}\psi_t(\eta)e_t$.
Whenever it does not cause confusion, we keep the conditioning on the cross-fitted folds implicit in what follows, i.e.~we treat $\hat{\eta}(X)$ as depending on $X$ only through the evaluation at $X$ itself and not through the nuisance model.
Let $r \in [0,1]$. First note that, for any $\hat{\eta} = \eta + r(\tilde{\eta} - \eta)$ we can decompose 

{\footnotesize \begin{align*}
    \psi_t(\hat{\eta}) - \psi_t(\eta)
    &= \frac{\mathbbm{1}_t(Y - \mu_t(X) - r(\tilde{\mu}_t(X) - \mu_t(X))}{e_t(X) + r(\tilde{e}_t(X) - e_t(X))} + \mu_t(X) + r(\tilde{\mu}_t(X) - \mu_t(X)) - \mu_t \\
    &\quad - \frac{\mathbbm{1}_t(Y - \mu_t(X))}{e_t(X)} - \mu_t(X) +  \mu_t \\
    % &= \frac{\mathbbm{1}_t(\varepsilon(t) - r(\tilde{\mu}_t(X) - \mu_t(X))e_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} + \frac{r(\tilde{\mu}_t(X) - \mu_t(X))(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} \\
    % &\quad - \frac{\mathbbm{1}_t \varepsilon(t)(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} \\
    % &= \frac{\mathbbm{1}_t \varepsilon(t) e_t(X) - \mathbbm{1}_t \varepsilon(t)(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} - \frac{\mathbbm{1}_t r(\tilde{\mu}_t(X) - \mu_t(X)e_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} \\
    % & \quad + \frac{r(\tilde{\mu}_t(X) - \mu_t(X))(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} \\
    % &= \mathbbm{1}_t \varepsilon(t) \frac{ e_t(X) - e_t(X) - r(\tilde{e}_t(X) - e_t(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} - \frac{\mathbbm{1}_t r(\tilde{\mu}_t(X) - \mu_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))} \\
    % & \quad + \frac{r(\tilde{\mu}_t(X) - \mu_t(X)) e_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))} \\
    % & \quad + \frac{r(\tilde{\mu}_t(X) - \mu_t(X)) r(\tilde{e}_t(X) - e_t(X))e_t(X)}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} \\
    % &= \mathbbm{1}_t \varepsilon(t) \frac{- r(\tilde{e}_t(X) - e_t(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))e_t(X)} \\
    % & \quad + r \frac{(\tilde{\mu}_t(X) - \mu_t(X)) (e_t(X) - \mathbbm{1}_t)}{e_t(X) + r(\tilde{e}_t(X) - e_t(X))} \\
    % & \quad + r^2\frac{(\tilde{\mu}_t(X) - \mu_t(X)) (\tilde{e}_t(X) - e_t(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))} \\
    &= -\mathbbm{1}_t\varepsilon(t) r\frac{(\tilde{e}_t(X) - e(X))}{(e_t(X) + r(\tilde{e}_t(X) - e(X)))e_t(X)} - r \frac{(\tilde{\mu}_t(X) - \mu_t(X))(\mathbbm{1}_t - e_t(X))}{e_t(X) +  r(\tilde{e}_t(X) - e_t(X))} \\
    &\quad + r^2 \frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{e}_t(X) - e_t(X))}{e(X) +  r(\tilde{e}_t(X) - e_t(X))},
\end{align*}}
for all $t$. Plugging this back into the machine learning bias and taking expectations then yields 

{\footnotesize \begin{align*}
    E[{\IF}({d}_0(a)) - \hat{\IF}({d}_0(a))]
    &= r^2 \sum_{t\in \mathcal{T}_a}E\left[ \frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{e}_t(X) - e_t(X))}{e(X) +  r(\tilde{e}_t(X) - e(X))}e_t\right] \\
    &= r^2 \sum_{t\in \mathcal{T}_a}E\left[ \frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{e}_t(X) - e_t(X))}{1 +  r(\tilde{e}_t(X)/e_t(X) - 1)}\frac{e_t}{e_t(X)}\right],
\end{align*}}

as $E[\varepsilon(t)|T=t,X] = E[\varepsilon(t)|X] = 0$ by Assumption 1 as well as $E[\mathbbm{1}_t - e_t(X)|X] = 0$ by definition. Using Assumption A.4 we then obtain
{\footnotesize \begin{align*}
    \sqrt{n}\sup_{\hat{\eta} \in \mathcal{H}_n}&||E[{\IF}({d}_0(a)) - \hat{\IF}({d}_0(a))]|| \\
    &= \sqrt{n}\sup_{r\in [0,1]}r^2 {\bigg|\bigg|}\sum_{t\in \mathcal{T}_a}E\left[ \frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{e}_t(X) - e_t(X))}{1 +  r(\tilde{e}_t(X)/e_t(X) - 1)}\frac{e_t}{e_t(X)}\right] {\bigg|\bigg|} \\
    &\lesssim \sqrt{n} J \sup_{t,x} \frac{e_t}{e_t(x)} \sup_t E[(\tilde{\mu}_t(X) - \mu_t(X))^2]^{1/2}E[(\tilde{e}_t(X) - e_t(X))^2]^{1/2} \\
    &\lesssim \sqrt{n}Jr_{\mu,n,2}r_{e,n,2}, 
\end{align*}}
which is $o(1)$ by Assumption A.5.

\subsection{Bounding the Empirical Process}
Given a finite number of non-overlapping, independent folds for data $W_1,\dots,W_n$, denote fold data  $I_f$ of length $n_f$ and let $I_f^c$ denote the corresponding hold-out data. To bound the empirical process, we first consider convergence conditional on the hold-out sample. In particular conditional on $I_f^c$, we have that

{\footnotesize \begin{align*}
    \left(G_{n_f}\left[\hat{\IF}({d}_0(a))\right] - G_{n_f}\left[{\IF}({d}_0(a))\right]\right)^2
    &\lesssim_P E\left[\left(\sum_{t\in\mathcal{T}_a}(\psi_t(\hat{\eta}) - \psi_t(\eta))e_t\right)^2\bigg|I_f^c\right] \\
    &= \sum_{t\in\ta}\sum_{s\in\ta}e_te_s E[(\psi_t(\hat{\eta}) - \psi_t(\eta))(\psi_s(\hat{\eta}) - \psi_s(\eta))|I_f^c],
    \end{align*}}
by Chebyshev's inequality and independent data. 
Now let again $r \in [0,1]$ such that $\hat{\eta} = \eta + r(\tilde{\eta} - \eta)$. For the $t=s$ summand, we have that {\footnotesize \begin{align*}
    &E[(\psi_t(\hat{\eta}) - \psi_t(\eta))^2|I_f^c] \\
    &= r^2 E\left[\frac{\mathbbm{1}_t\varepsilon^2(t)(\tilde{e}_t(X) - e_t(X))^2}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))^2e_t(X)^2}\bigg|I_f^c\right] + r^2 E\left[\frac{(\tilde{\mu}_t(X) - \mu_t(X))^2(\mathbbm{1}_t - e_t(X))^2}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))^2}\bigg|I_f^c\right] \\
    &\quad + r^4 E\left[\frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{e}_t(X) - e_t(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))^2}\bigg|I_f^c\right] \\
    &= r^2 E\left[\frac{\sigma^2_t(X)(\tilde{e}_t(X) - e_t(X))^2}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))^2e_t(X)}\bigg|I_f^c\right] + r^2 E\left[\frac{(\tilde{\mu}_t(X) - \mu_t(X))^2e_t(X)(1-e_t(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))^2}\bigg|I_f^c\right] \\
    &\quad + r^4 E\left[\frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{e}_t(X) - e_t(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))^2}\bigg|I_f^c\right] \\
    &\lesssim \sup_{t\in\ta,x}\frac{1}{e_te_t(x)^2}\frac{e_t(x)^2}{\hat{e}_t(x)^2} E[(\tilde{e}_t(X) - e_t(X))^2|I_f^c] + \frac{1}{e_t(x)}\frac{e_t(x)}{\hat{e}_t(x)}E[(\tilde{\mu}(X)- \mu(X))^2|I_f^c] \\
    &\quad + \frac{1}{e_t(x)^2}\frac{e_t(x)}{\hat{e}_t(x)}E[(\tilde{e}_t(X) - e_t(X))^2|I_f^c]^{1/2}E[(\tilde{\mu}_t(X) - \mu_t(X))^2|I_f^c]^{1/2},
\end{align*}}
where the second equality follows from Assumption 1 and the law of iterated expectations. For the cross terms $t \neq s$, note that $\mathbbm{1}_t\mathbbm{1}_s = 0$ and hence 

{\footnotesize \begin{align*}
    E&[(\psi_t(\hat{\eta}) - \psi_t(\eta))(\psi_s(\hat{\eta}) - \psi_s(\eta))|I_f^c] \\
    &= r^2E\left[\frac{(\mathbbm{1}_t - e_t)(\mathbbm{1}_s - e_s)(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{\mu}_s(X) - \mu_s(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))(e_s(X) + r(\tilde{e}_s(X) - e_s(X)))}\bigg|I_f^c\right] \\
    &\quad + r^4E\left[\frac{(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{\mu}_s(X) - \mu_s(X))(\tilde{e}_t(X) - e_t(X))(\tilde{e}_s(X) - e_s(X))}{(e_t(X) + r(\tilde{e}_t(X) - e_t(X)))(e_s(X) + r(\tilde{e}_s(X) - e_s(X)))}\bigg|I_f^c\right] \\
    &\lesssim \sup_{t,s\in \ta, t\neq s,x} \frac{e_t(x)e_s(x)}{\hat{e}_t(x)\hat{e}_s(x)}E[|(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{\mu}_s(X) - \mu_s(X))|~|I_f^c] \\
    &\quad + \frac{1}{\hat{e}_t(x)}E[|(\tilde{\mu}_t(X) - \mu_t(X))(\tilde{\mu}_s(X) - \mu_s(X))(\tilde{e}_t(X) - e_t(X))(\tilde{e}_s(X) - e_s(X))|~|I_f^c].
\end{align*}}
Plugging this back into the original empirical process and looking at the worst nuisance case, we obtain conditional bound rates 

{\footnotesize \begin{align*}
  \sup_{\hat{\eta}\in \mathcal{H}_n} & \sum_{t\in\ta}\sum_{s\in\ta}e_te_s E[(\psi_t(\hat{\eta}) - \psi_t(\eta))(\psi_s(\hat{\eta}) - \psi_s(\eta))|I_f^c] \\
  &\lesssim \sup_{\hat{\eta}\in \mathcal{H}_n}\left(\sup_t Je_t^2 E[(\psi_t(\hat{\eta}) - \psi_t(\eta))^2|I_f^c] + \sup_{t,s\in\ta,s\neq t}J^2E[(\psi_t(\hat{\eta}) - \psi_t(\eta))(\psi_s(\hat{\eta}) - \psi_s(\eta))|I_f^c]\right) \\
  &\lesssim \frac{1}{J}\left( J^3 r_{e,n,2}^2 + J r_{\mu,n,2}^2 + J^2 r_{e,n,2}r_{\mu,n,2}\right) + (r_{\mu,n,2}^2 + J^2r_{\mu,n,2}r_{e,n,2}) \\
  &\lesssim (r_{\mu,n,2} + J r_{e,n,2})^2, 
\end{align*}}

where the second inequality follows from repeated application of the Cauchy-Schwarz inequality as well as Assumption A.4. Lastly, given a finite amount of folds, Lemma 6.1 of \citeA{Chernozhukov2018} yields that conditional convergence implies unconditional and thus, we obtain that 

{\footnotesize \begin{align*}
     G_{n}\left[\hat{\IF}({d}_0(a))\right] - G_{n}\left[{\IF}({d}_0(a))\right] \lesssim_P r_{\mu,n,2} + J r_{e,n,2},
\end{align*}}
which is $o(1)$  by Assumption A.5.


\subsection{Leading Term} \label{sec_proof_leadingterm1}
We now consider the limiting behavior of the leading term and show that it is asymptotically normal. We denote all inner product, sums and corresponding suprema without the treatment aggregation for readability, i.e.~$\ip{A,B} = \ip{A,B}_{\ell^2(\ta)}$, $\sum_tA_t = \sum_{t\in\ta}A_t$, and $\sup_tA_t = \sup_{t\in\ta}A_t$.  For simplicity, we consider the modified parameter $\ip{e,\mu}$ where $e = (e_1,\dots,e_J)'$. The proof for $\ip{e_a,\mu}$ is identical up to a $O(n^{-1/2})$ remainder as $e_{ta} = e_t/P(T \in \ta)$ and $P(T \in \ta)$ is bounded away from zero by Assumption A.3. We first find a rate for $\sigma_n^2 = E[\IF(\ip{e,\mu})^2]$. Simplifying the influence function and taking expectations yields

{\footnotesize {\footnotesize \begin{align*}
    \sigma_n^2 &= \sum_t e_t(1-e_t)\mu_t^2 + 2 \mu_t e_t E[\mathbbm{1}_t\psi_t] + e_t^2 E[\psi_t^2] \\
    &\quad+ \sum_{t,s\neq t}E[(\mathbbm{1}_t-e_t)(\mathbbm{1}_{s}- e_{s})]\mu_t\mu_s + e_tE[\psi_t(\mathbbm{1}_s - e_s)]\mu_s + e_sE[\psi_s(\mathbbm{1}_t - e_t)]\mu_t + e_te_s E[\psi_t \psi_s] \\
