\subsection{Bounding the Remainder}
For the remainder note that, due to the ratio form of the conditional probability we have that {\footnotesize \begin{align*}
    \sqrt{n}\ip{\hat{e}_a - e_a,\hat{\mu} - \mu}_{\ell^2(\ta)}
    &=\sqrt{n}\ip{\hat{e} - e,\hat{\mu} - \mu}_{\ell^2(\ta)} \left(1 + O(E_n[\mathbbm{1}(T \in \mathcal{T}_a)] - P(T \in \mathcal{T}_a) \right) \\
    &= \sum_{t\in \mathcal{T}_a}E_n[\mathbbm{1}_t - e_t]G_n[\psi_t(\hat{\eta})]\left(1 + O_p(n^{-1/2})\right). 
\end{align*}}

By the previous two subsections, we have that $G_n[\psi_t(\hat{\eta})] \lesssim_P 1$. Moreover, by a standard CLT argument, we obtain that the empirical sample frequency estimators are superefficient, i.e.~%{\footnotesize \begin{align*}
    $\sqrt{\frac{n}{e_t(1-e_t)}}E_n[\mathbbm{1}_t - e_t] \overset{d}{\rightarrow} \mathcal{N}(0,1)$
%\end{align*}}
and thus, using Assumption A.4, we obtain 

{\footnotesize \begin{align*}
     \sqrt{n}\ip{\hat{e}_a - e_a,\hat{\mu} - \mu}_{\ell^2(\ta)} &\lesssim_P J\sup_t\sqrt{\frac{n}{e_t}} 
     \lesssim \sqrt{\frac{J}{n}},
\end{align*}}
which is again $o(1)$ by Assumption A.5. 


\subsection{Generalization to All Decomposition Estimands} \label{app_proof_N_decompALL}
Derivations for decomposition estimands $d_{j}(a,g)$ with $j=1,2,3,4,4^{'},5$ are obtained analogously to $d_{0}(a)$ as they rely on influence functions that contain either scaled versions of the ones entering $d_{0}(a)$ with a.s.~bounded scaling factors such as indicators and probabilities or simple averages without or at most root-$n$ consistent nuisances (such as simple sample means) that can be controlled. We provide an explicit example of how to adapt the proof below. To bound the explicit varying denominator weights in the influence functions, however, we need to add Assumption A.3. Consider for instance  component $\ip{e_a(\xg),\mu(\xg)}_{\ell^2(\ta)}$. We have that 

{\footnotesize \begin{align*}
&\IF  \{\ip{e_a(\xg),\mu(\xg)}\}_{\ell^2(\ta)} %= \IF\{\sum_{t\in\ta} e_{ta}(\xg)\mu_t(\xg)\} 
= \sum_{t\in\ta} \IF\{e_{ta}(\xg)\mu_t(\xg)\} \\
&= \frac{\mathbbm{1}(X\in\xg)}{P(X\in\xg)} \bigg\{ \sum_{t\in\ta} \left[ \frac{\mathbbm{1}(T\in\mathcal{T}_a)\mathbbm{1}(T = t)}{P(T\in\mathcal{T}_a|X\in\xg)}  \mu_t(\xg) + e_{ta}(\xg) \left( \frac{\mathbbm{1}(T=t) (Y - \mu_t(X))}{P(T=t|X)} + \mu_t(X)\right) \right] \\
& \quad  - \left(1 + \frac{\mathbbm{1}(T\in\mathcal{T}_a)}{P(T\in\mathcal{T}_a|X\in\xg)} \right) { \sum_{t\in\ta} e_{ta}(\xg)\mu_t(\xg)} \bigg\}. 
\end{align*}}

We can see that this is the same influence function with (i) unconditional nuisances $e_{ta}$ and $\mu_t$ replaced by $e_{ta}(\xg)$ and $\mu_t(\xg)$ respectively as well as (ii) a different weight in front of the components. These weights depend only on indicators and probabilities. We use the efficient influence function estimators for the unknown probabilities, see Appendix \ref{sec_app_implement1}. To adapt the proof, we thus need to modify the remainder as well as the supremum weight outside the $\ta$-dependent sums. Solving for the sample analogue with estimated nuisances then yields the following decomposition 

 {\footnotesize   {\footnotesize \begin{align*}
    \sqrt{n}&(\hat{d}_j(a,g) - {d}_j(a,g)) \\
    &= G_n\left[\hat{\IF}({d}_j(a,g))\right]\left( 1 + O\big(|E_n[\IF(P(\ta))]| + |E_n[\IF(P(\xg))]|  + |E_n[\IF(P(\ta|\xg))]|\big) \right)\\
    &\quad  + \sqrt{n}\ip{(\hat{e}_a(\xg) - e_a(\xg)),(\hat{\mu}(\xg) - \mu(\xg))}_{\ell^2(\ta)} \\
    &= \underbrace{G_n\left[{\IF}({d}_j(a,g))\right]}_{\text{Leading Term}} + \underbrace{\left(G_n\left[\hat{\IF}({d}_j(a,g))\right] - G_n\left[{\IF}({d}_j(a,g))\right]\right)}_{\text{Empirical Process}} \\
    &\quad + \underbrace{\sqrt{n}\left(E\left[\hat{\IF}({d}_j(a,g))\right] - E\left[{\IF}({d}_j(a,g))\right] \right)}_{\text{Machine Learning Bias}} + o_p(1).
\end{align*}}}
 In particular, Assumption A.3 states that $\inf \{P(\xg),P(\ta),P(\ta|\xg)\} > \underline{c}$
 and thus all the influence function based frequency estimators above are root-$n$ consistent, i.e.~$E_n[\IF(\cdot)] = o_p(n^{-1/2})$. The proof for machine learning bias as well as empirical process is identical to the previous step with again $e_{ta}$ and $\mu_t$ replaced by their $\xg$ conditional counterparts. Thus, overall we obtain an asymptotic linearization with $o_p(1)$ remainder as for $d_{0}(a)$. The same applies to the remaining decomposition parameters. 

\subsection{Multivariate CLT} \label{app_proof_multiCLT}
We now stack all the influence functions in a single column vector $\IF(\theta)$ where $\theta \in \mathbb{R}^8$ is the the collection of all decomposition estimands from Appendix \ref{sec_app_implement1}. Any decomposition parameter or contrast can then be obtained via linear combinations of these components, i.e.~we consider the asymptotic distribution of estimates $c_n'\hat{\theta}$, i.e.~$
    [c_n'\Sigma c_n]^{-1/2}c_n'(\hat{\theta} - \theta)$, 
where $c_n \lesssim 1$ are bounded (sequences of) weight vectors in $\mathbbm{R}^{8}$ and $\hat{\theta}$ are obtained from solving all influence functions with respect to their target parameters with estimated, cross-fitted nuisances. The variance is given by $\Sigma = E[\IF(\theta)\IF(\theta)']$. Due to the leading term result regarding variance in Subsection \ref{sec_proof_leadingterm1} and the finite dimension of $\theta$ we have that $||c_n'\Sigma c_n||_2 \lesssim ||c_n||_2^2||\Sigma ||_2 \lesssim 1.$
Now we use an expansion as in Section \ref{sec_proof_ifbasedestimator} which can be bounded using the marginal results from the previous subsections. 

{\footnotesize \begin{align*}
    G_n\left[\hat{\IF}(\theta)\right]
    &= {G_n\left[{\IF}(\theta)\right]}{\left(G_n\left[\hat{\IF}(\theta)\right] - G_n\left[{\IF}(\theta)\right]\right)} 
     + {\sqrt{n}\left(E\left[\hat{\IF}(\theta)\right] - E\left[{\IF}(\theta)\right] \right)} \\
    &= {G_n\left[{\IF}(\theta)\right]} + O\left(\max_{i} \sqrt{8}\bigg|\bigg| \left(G_n\left[\hat{\IF}(\theta_i)\right] - G_n\left[{\IF}(\theta_i)\right]\right)\bigg|\bigg|\right) \\
    &\quad + O\left(\max_i \sqrt{8} \sqrt{n}\bigg|\bigg|\left(E\left[\hat{\IF}(\theta_i)\right] - E\left[{\IF}(\theta_i)\right] \right)\bigg|\bigg| \right) \\
    &= G_n\left[{\IF}(\theta)\right] + o_p(1),
\end{align*}}
by norm equivalence in the finite-dimensional vector space. We now consider the multivariate Lindeberg condition for the leading term. 
We make repeated use of the following bound for generic random vectors $A,B$ 

{\footnotesize \begin{align*}
    E[||A + B||_2^2\mathbbm{1}(||A + B|| > c)] 
    \leq 2 \left(E[||A||_2^2\mathbbm{1}(||A|| > c/2)] + E[||A||_2^2\mathbbm{1}(||B|| > c/2)]\right).
\end{align*}}
Consider now the leading term for the linear combination
{\footnotesize \begin{align*}
{\sqrt{n}}E_n\left[\left(c_n'\Sigma c_n\right)^{-1/2}c_n'\IF(\theta)\right] &= E_n[\omega_n \IF(\theta)],
\end{align*}}
where $\omega_n = n^{-1/2}\left(c_n'\Sigma c_n\right)^{-1/2}c_n'$. Thus, by definition of the variance for the iid sum, we have that $V[E_n[\omega_n \IF(\theta)]] = 1$. We can now evaluate the Lindeberg condition. In particular note that, for any $c > 0$, {\footnotesize \begin{align*}
    E[||\omega_n \IF(\theta)||_2^2\mathbbm{1}(||\omega_n \IF(\theta)|| > c)] 
    &\leq ||\omega_n||_2^2 E[||\IF(\theta)||_2^2\mathbbm{1}( ||\IF(\theta)|| > c/||\omega_n||)] \\
    & \leq ||\omega_n||_2^2 8 \max_j E[\IF(\theta_j)^2\mathbbm{1}(|\IF(\theta_j) > c/(8||\omega_n||)] \\
    & \lesssim \max_j E[\IF(\theta_j)^2\mathbbm{1}(|\IF(\theta_j) > c_{n,j}],
\end{align*}}
where $c_{n,j} \sim \sqrt{n}$ by definition of $\omega_n$ as well as $||c_n'\Sigma c_n || \lesssim ||c_n||_2^2 \max \Sigma_{jj} \lesssim 1$ by Subsection \ref{sec_proof_leadingterm1}. Now recall that $E[\IF(\theta_j)^2\mathbbm{1}(|\IF(\theta_j)| > c_{n,j})] = o(1)$ for all $j=1,\dots,8$. Thus the multivariate Lindeberg condition applies and hence %{\footnotesize \begin{align*}
    $[c_n'\Sigma c_n]^{-1/2}c_n'(\hat{\theta} - \theta) \overset{d}{\rightarrow} \mathcal{N}(0,1).$
%\end{align*}}

\subsection{Variance Estimation} \label{sec_app_variance1}
We now consider estimated variancecross-fitted nuisances. In particular define $ \hat{\Sigma} = E_n[\hat{\IF}(\hat{\theta})\hat{\IF}(\hat{\theta})']$.
% {\footnotesize \begin{align*}
%     \hat{\Sigma} = E_n[\hat{\IF}(\hat{\theta})\hat{\IF}(\hat{\theta})'].
% \end{align*}}
It is sufficient to show that $    ||\hat{\Sigma} - \Sigma||_2 = o_p(1)$ and then apply Slutzky's Theorem.
We adapt \citeA{Chernozhukov2018}, Theorem 3.2 to our setup with extending nuisance parameter space. Steps are identical except for some of the moment bounds. In particular, for their (A.25), we need a rate for $E[||\IF(\theta)||_2^q]$ under growing treatments. We again focus on a worst-case component $d_{0}(a)$ in $\theta$ that then provides a bound for the whole vector norm due to its finite dimension. In particular, let $q = 2+m$, then, for any $q > 2$, 

{\footnotesize \begin{align*}
    E[||\IF(\theta)||_2^q] 
    &\lesssim E[||\ip{\IF(\mu),e}_{\ell^2(\ta)}||_2^q] + E[||\ip{\mu,\IF(e)}_{\ell^2(\ta)}||_2^q].
\end{align*}}  
The two components can be bounded by rate and moment assumptions A.1 and A.4. We consider both the case where $q \in (2,4)$ as well as $q \geq 4$. For the first term, triangle inequality, law of total probability, and Jensen's inequality yields 

{\footnotesize \begin{align*}
E[||\ip{\IF(\mu),e}_{\ell^2(\ta)}||_2^q]
&\leq E[|\sum_{t\in\ta}\mathbbm{1}_t\varepsilon(t)|^q] + E[|\sum_{t\in\ta}e_t(\mu_t(X) - \mu_t)|^q] \\
&\leq \sum_{t\in\ta}E[|\varepsilon(t)|^q|T=t]e_t + J^{q-1}\sum_{t\in\ta}|e_t|^qE[|\mu_t(X) - \mu_t|^q] \\
&\lesssim J \sup_{t,x} E[|\varepsilon(t)|^q|X=x]e_t + J^{q-1}J \sup_{t,x}e_t^qE[|Y(t)|^q|X=x]
\end{align*}}
which is $O(1)$. For the second component note that again by Jensen's inequality
{\footnotesize \begin{align*}
    E[||\ip{\mu,\IF(e)}_{\ell^2(\ta)}||_2^q] &\leq J^{q-1} \sum_{t\in\ta}E[|\mu_t(\mathbbm{1}_t - e_t)|^q] \\
    &\lesssim J^q \sup_{t\in\ta}|\mu_t|^q(1-e_t)^qe_t + e_t^q(1-e_t) \\
    &\lesssim J^{q-1}.
\end{align*}}
We now combine this for $q \in (2,4)$ as well as $q \geq 4$, paralleling (A.25) in \citeA{Chernozhukov2018}. In particular, note that for $q > 4$, the optimal rate of the previous terms is obtained already at $q=4$. Thus, combining results yields modified (A.25) rate 

{\footnotesize \begin{align*}
    E_{n_f}[\IF(\theta)] &\lesssim_P \sqrt{\frac{J^3}{n}} + \left(\frac{J}{n}\right)^{1-2/q}J 
    \lesssim J \left(\frac{J}{n}\right)^{[(1/2)\wedge (1-2/q)]}. 
\end{align*}}
For the other moment bound in (A.27), we have to additionally control the second moment of the moment function nuisance relative to using true nuisances on the realization set. In particular, equivalently to the proof in Subsection \ref{sec_proof_mlbias1} we obtain that 

{\footnotesize \begin{align*}
    \sup_{\eta \in \mathcal{H}_n} E[||\hat{\IF}(\theta) - \IF(\theta)||_2^2|I_k^c]
    \lesssim (r_{\mu,n,2} + J r_{e,n,2})^2, 
\end{align*}}
where the rate again comes from the worst case component from Subsection \ref{sec_proof_mlbias1}. Combining rates together as in  \citeA{Chernozhukov2018}, Equation (A.23), and noting that $q = 2 + m$ with $m > 0$ from Assumption A.1, we obtain that

{\footnotesize \begin{align*}
   ||\hat{\Sigma} - \Sigma||_2 &= O_p\left(n^{-1/2} + J \left(\frac{J}{n}\right)^{\left[\frac{1}{2}\wedge \frac{m}{2+m}\right]} + r_{\mu,n,2} + Jr_{e,n,2} \right) \\
   &= O_p\left(J \left(\frac{J}{n}\right)^{\left[\frac{1}{2}\wedge \frac{m}{2+m}\right]} + r_{\mu,n,2} + Jr_{e,n,2} \right), 
\end{align*}}
which is $o_p(1)$ by Assumption A.5 and the statement in Theorem \ref{thm_asyN1}.


