\subsection{Decompositions}
\subsubsection{Auxiliary Results}\label{sec_app_aux_gen_covariance1}Note that, for any measurable $g_1,g_2:\mathcal{T}\times\mathcal{X}\rightarrow \mathbb{R}$, we have that, for any $t \in \mathcal{T}$, {\footnotesize \begin{align*}
    E&[g_1(t,X)g_2(t,X)|X\in \xg] \\
    &= Cov(g_1(t,X),g_2(t,X)|X\in \xg) + E[g_1(t,X)|X\in\xg]E[g_2(t,X)|X\in\xg] \\
    &= Cov(g_1(t,X),g_2(t,X)|X\in \xg) + g_{1,t}(\xg)g_{2,t}(\xg).
\end{align*}}
\subsubsection{Difference-in-Means}
{\footnotesize \begin{align*}
    E[Y|X\in\xg,T\in\ta] 
    &= E[E[Y|X,T]|X\in\xg,T\in\ta] \\
    &= \int_{\mathcal{X}}\left[\int_{\ta\backslash\{t_r\}}\mu_t(x)\frac{f(t|x)}{P(T\in\ta|X\in\xg)}d\lambda(t) \right]dP(x|X\in\xg) \\ &\quad+ \sum_{t\in\{t_r\}} e_{ta}(\xg) E[\mu_{t}(X)|T=t,X\in \xg].
\end{align*}}
For the first component, Fubini's Theorem together with auxiliary result \ref{sec_app_aux_gen_covariance1} yields

{\footnotesize \begin{align*}
&\int_{\ta\backslash\{t_r\}}\int_{\mathcal{X}}\mu_t(x)\frac{f(t|x)}{P(T\in\ta|X\in\xg)}dP(x|x\in\xg)d\lambda(t) \\
    &=\int_{\ta\backslash\{t_r\}}\left(E[\mu_t(X)|x\in\xg]\frac{E[f(t|X)|X\in\xg]}{P(T\in\ta|X\in\xg)} + \frac{Cov(f(t|X),\mu_t(X)|X\in\xg)}{P(T\in\ta|X\in\xg)}\right)d\lambda(t) \\
    &= \ip{\mu(\xg),f_{a}(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda)} + \frac{\ip{Cov(f(X),\mu(X)|X\in\xg),1}_{L^2(\ta\backslash \{t_r\},\lambda)}}{P(T\in\ta|X\in\xg)},
\end{align*}}
where $f(x) = \{f(t|x):t\in\ta \backslash \{t_r\}\}$ and $f_{a}(\xg) = \{f_{ta}(\xg):t \in \ta\backslash \{t_r\} \} = \{f(t|T\in\ta,X\in\xg): t \in \ta\backslash \{t_r\}\}$. 
The discrete component can be decomposed analogously as  

{\footnotesize \begin{align*}
    \sum_{t\in\{t_r\}}& e_{ta}(\xg) E[\mu_{t}(X)|T=t,X\in \xg] \\
    &= \ip{e_{a}(\xg),\mu(\xg)}_{\ell^2(\{t_r\})} + \frac{\ip{Cov(e_{a}(X),\mu(X)|X\in\xg),1}_{\ell^2(\{t_r\})}}{P(T\in\ta|X\in\xg)}.
\end{align*}}
Combining results yields the first decomposition {\footnotesize \begin{align*}
    E&[Y|X\in\xg,T\in\ta] \\
    &=\ip{\mu(\xg),f_{a}(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda)} + \frac{\ip{Cov(f(x),\mu(x)|x\in\xg),1}_{L^2(\ta\backslash \{t_r\},\lambda)}}{P(T\in\ta|x\in\xg)} \\
    &\quad + \ip{e_{a}(\xg),\mu(\xg)}_{\ell^2(\{t_r\})} + \frac{\ip{Cov(e_{a}(X),\mu(X)|X\in\xg),1}_{\ell^2(\{t_r\})}}{P(T\in\ta|X\in\xg)} \\
    &=\ip{e_{a}(\xg),\mu(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda) \oplus \ell^2(\{t_r\})} + \frac{\ip{Cov(e_{a}(X),\mu(X)|X\in\xg),1}_{L^2(\ta\backslash \{t_r\},\lambda) \oplus \ell^2(\{t_r\})}}{P(T\in\ta|X\in\xg)}.
\end{align*}}  
\subsubsection{Adjusted Difference-in-Means}
Derivations for the adjusted DiM work similarly with modified starting point. For any $t \in \ta \backslash \{t_r\}$ and $x \subseteq X$, let $f_{ta}(x)$ be the conditional density of $T$ given $T \in \ta$ and $X\in x$ evaluated at $t$. Note that, for any $t \in \ta \backslash \{t_r\}$,

{\footnotesize \begin{align*}
    \int_{\mathcal{X}}&\mu_t(x)f_{ta}(x)dP(x|X\in\xg) 
    = E[\mu_t(X)f_{ta}(X)|X\in \xg] \\
    &= Cov(\mu_t(X),f_{ta}(X)|X\in\xg) + E[\mu_t(X)|X\in\xg]E[f_{ta}(X)|X\in\xg] \\
    &= Cov(\mu_t(X),f_{ta}(X)|X\in\xg) + \mu_t(\xg)f_{ta}(\xg) + \left(E[f_{ta}(X)|X\in\xg] - f_{ta}(\xg)\right)\mu_t(\xg).
\end{align*}}
We now can decompose the adjusted DiM. For the discrete part, we use the derivations as in Appendix \ref{app:deriv-both}. The definition of the adjusted DiM with the auxiliary result \ref{sec_app_aux_gen_covariance1} then yields 

{{\footnotesize \begin{align*}
    &E\left[E[Y|T\in\ta,X]|X\in\xg\right] \\
    &= \int_x\int_{\ta\backslash\{t_r\}}\mu_t(x)f_{ta}(x)d\lambda(t)dP(x|X\in\xg) + \sum_{t\in\{t_r\}} E[e_{ta}(X) \mu_{t}(X) |X\in \xg] \\
    &= \ip{f_{a}(\xg),\mu(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda)} + \ip{E[f_{\ta}(X)|X\in\xg] - f_{a}(\xg),\mu(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda)}  \\ &\quad+ \ip{Cov(f_{a}(X),\mu(X)|X\in\xg),1}_{L^2(\ta\backslash \{t_r\},\lambda)} + \ip{e_{a}(\xg),\mu(\xg)}_{\ell^2(\{t_r\})} \\ &\quad+ \ip{E[e_{a}(X)|X\in\xg] - e_{a}(\xg),\mu(\xg)}_{\ell^2(\{t_r\})} + \ip{Cov(e_{a}(X),\mu(X)|X\in\xg),1}_{\ell^2(\{t_r\})} \\
    &= \ip{e_{a}(\xg),\mu(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda) \oplus \ell^2(\{t_r\})} + \ip{E[e_{a}(X)|X\in\xg] - e_{a}(\xg),\mu(\xg)}_{L^2(\ta\backslash \{t_r\},\lambda) \oplus \ell^2(\{t_r\})} \\ &\quad + \ip{Cov(e_{a}(X),\mu(X)|X\in\xg),1}_{L^2(\ta\backslash \{t_r\},\lambda) \oplus \ell^2(\{t_r\})}.
\end{align*}}}

