\section{Supplementary Material for Section \ref{sec_indirect1}} \label{sec_app_powerJ1}

\subsection{Theory}

We consider the asymptotic approximation for large $J$ to various testing procedures. To do so, we first make some simplifying assumptions to provide analytically tractable formulations. This can be extended at the expense of carrying around constant weight vectors and matrices throughout. First note that, when $\mu_0(x) = 0$, the strong group effect homogeneity null hypothesis \eqref{eq_strongeffecthomogeneity} can be written as 

{\footnotesize \begin{align*}
   H_0: \mu_t(\xg) = \mu_t(\xgp) \text{ for all } t \in \ta 
\end{align*}}
We additionally make the assumption that, for all $x \in \mathcal{X}$, $e_t(x) = e_t$ and $V[Y(t)|X=x] = \sigma_t^2$. 
Assuming known nuisances, the influence function estimators of the group mean are given by

{\footnotesize \begin{align*}
    \hat{\mu}_t(\xg) -\mu_t(\xg) 
    &= E_n\left[\psi_t\frac{\mathbbm{1}(X \in \xg)}{P(X \in \xg)}\right]= E_n\left[\left(\frac{\mathbbm{1}_t\varepsilon(t)}{e_t(X)} + \mu_t(X) - \mu_t\right)\frac{\mathbbm{1}(X \in \xg)}{P(X \in \xg)}\right].
\end{align*}}
%In practice $P(X\in\xg)$ is estimated. However, they can be replaced by their root-n consistent counterparts without affecting the approximation. 
The centered mean difference parameter can then be written as
{\footnotesize \begin{align*}
   [\hat{\mu}_t(\xg) - \hat{\mu}_t(\xgp)]  - [\mu_t(\xg)  - \mu_t(\xgp)]
    &= E_n\left[\left(\frac{\mathbbm{1}_t\varepsilon(t)}{e_t(X)} + \mu_t(X) - \mu_t \right)\mathbbm{a}_{g,g'}\right]. 
\end{align*}}
where  {\footnotesize \begin{align*}
    \mathbbm{a}_{g,g'} &= \frac{\mathbbm{1}(X \in \xg)}{P(X \in \xg)} - \frac{\mathbbm{1}(X \in \xgp)}{P(X \in \xgp)}.
\end{align*}}
Now note that we have {\footnotesize \begin{align*}
    \sqrt{e_t n}\left([\hat{\mu}_t(\xg) - \hat{\mu}_t(\xgp)]  - [\mu_t(\xg)  - \mu_t(\xgp)]\right)
    &= G_n\left[\left(\frac{\mathbbm{1}_t\varepsilon(t)}{\sqrt{e_t}} + \sqrt{e_t}(\mu_t(X) - \mu_t)\right)\mathbbm{a}_{g,g'} \right] \\
    &=G_n\left[\mathbbm{1}_t\varepsilon(t)\mathbbm{a}_{g,g'}\right] + O_p(J^{-1/2}),
\end{align*}}
due to Assumptions A.1 and A.3.
Consider now the variance of the leading term {\footnotesize \begin{align*}
    E\left[\frac{\mathbbm{1}_t\varepsilon(t)^2}{\sqrt{e_t}^2}\mathbbm{a}^2_{g,g'}\right] 
    &= \sigma_t^2 E[\mathbbm{a}_{g,g'}^2].
\end{align*}}
For the covariances $s\neq t$, we have that
{\footnotesize \begin{align*}
    n&\sqrt{e_te_s} Cov([\hat{\mu}_t(\xg) - \hat{\mu}_t(\xgp)]  - [\mu_t(\xg)  - \mu_t(\xgp)],[\hat{\mu}_s(\xg) - \hat{\mu}_s(\xgp)]  - [\mu_s(\xg)  - \mu_s(\xgp)]) \\
    &= \frac{n\sqrt{e_te_s}}{n^2}\sum_{i=1}^n Cov(\mathbbm{a}_{g,g'}\psi_t,\mathbbm{a}_{g,g'}\psi_s) \\
    &= \sqrt{e_te_s} E[({\mu}_t(X) -\mu_t)({\mu}_s(X) -\mu_s)\mathbbm{a}_{g,g'}^2],
\end{align*}}
due to independence. We now make the following unit-variance-type assumption for simplification: $
    \sigma_t^2 E[\mathbbm{a}_{g,g'}^2] = 1$ and $
    \sqrt{e_te_s} E[({\mu}_t(X) -\mu_t)({\mu}_s(X) -\mu_s)\mathbbm{a}_{g,g'}^2] = 1/J$.
This is without loss of generality as the $1/J$ covariance rate is in line with Assumption A.4. Hence the joint distribution of the vector in large samples is characterized by 

{\footnotesize \begin{align*}
    \sqrt{\frac{n}{J}}\left([\hat{\mu}(\xg) - \hat{\mu}(\xgp)]  - [\mu(\xg)  - \mu(\xgp)]\right) \overset{d}{\rightarrow} \mathcal{N}(0,S),
\end{align*}}
where $S = I_J(1-1/J) + \iota\iota'/J$ is the variance covariance matrix.
For simplicity, we also make the assumption of an exact normal distribution in what follows. This makes all results only first-order approximations if the vectors are not exactly normal. For each $t$-specific entry we can then decompose the process into a system component whose influence vanishes at rate $1/\sqrt{J}$ and a $t$-specific idiosyncratic component.

{\footnotesize \begin{align*}
    \sqrt{\frac{n}{J}}\left([\hat{\mu}_t(\xg) - \hat{\mu}_t(\xgp)]  - [\mu_t(\xg)  - \mu_t(\xgp)]\right) 
    &= \sqrt{\frac{n}{J}}(\hat{m}_t - m_t) \overset{d}{=} \frac{Z_0}{\sqrt{J}} + Z_t\sqrt{1-1/J},
\end{align*}}
where $Z_0,Z_1,Z_2,\dots,Z_J$ are independent standard normal random variables. We denote the stacked vector shorthand as {\footnotesize \begin{align*}
     \sqrt{\frac{n}{J}}\left([\hat{\mu}(\xg) - \hat{\mu}(\xgp)]  - [\mu(\xg)  - \mu(\xgp)]\right) 
     &=  \sqrt{\frac{n}{J}}\left( \hat{m} - m \right) \overset{d}{=} \frac{Z_0}{\sqrt{J}} + {Z}\sqrt{1-1/J},
\end{align*}}
where $Z = (Z_1,\dots,Z_J)'$. We now consider the following test statistics for (implications of) the strong null 
{\footnotesize \begin{align*}
    \hat{t}_{\ell_2}^2 &= \frac{n}{J}\hat{m}'S^{-1}\hat{m}, \quad
     \hat{t}_{\ell_{\infty}} = \sup_t\left|\sqrt{\frac{n}{J}}\frac{\hat{m}_t}{S_{tt}^{-1/2}}\right|, \quad
     \hat{t}_{\Delta} = \frac{\sqrt{n}\hat{\Delta}_1(g,g')}{\Sigma_{{\Delta}_1}^{1/2}},
\end{align*}}
where the formula for the variance of the decomposition $\Sigma_{{\Delta}_1}$ is the corresponding component of the expected squared influence function of $\Delta_1$ as in Appendix \ref{sec_app_implement1}.  For all test-statistics, we compare them against the critical value of the true distribution under the strong null, i.e.~we perform a test with exact size control under normality.

For the the local power analysis, we consider sequences where the group differences are local to zero, i.e.~they are assumed to be small relative to the total sample size, but potentially large relative to effective treatment specific sample size. In particular we assume that, for all $t \in \ta$,$
    \sqrt{n}m_t \rightarrow \xi_t \in \mathbb{R}$,
or $\sqrt{n}m \rightarrow \xi$ in vector notation. We now derive the local power curves. 
\paragraph{\textbf{Auxiliary Results:}} We first provide some auxiliary results. 
Note that, by the properties of standard normal variables, we have that, jointly 

{\footnotesize \begin{align*}
   \begin{pmatrix}
  \frac{n}{J}(\hat{m} - m)S^{-1}(\hat{m} - m) \\
  \sqrt{\frac{n}{J}}S^{-1/2}(\hat{m} - m)
\end{pmatrix} \overset{d}{=} \begin{pmatrix}
    \sum_t(Z_t^*)^2 \\
    Z^*_1 \\
    \vdots \\
    Z^*_J
\end{pmatrix} = \begin{pmatrix}
    \sum_t(Z_t^*)^2 \\
    Z^*
\end{pmatrix},
\end{align*}}
where $Z^* = (Z_1^*,\dots,Z_J^*)'$ are independent standard normal. Thus, for $J\rightarrow \infty$,

{\footnotesize \begin{align*}
    \begin{pmatrix}
    \frac{(\sum_t(Z_t^*)^2 - J)}{\sqrt{2J}}  \\
    Z^* 
\end{pmatrix} \overset{d}{\rightarrow} \mathcal{N}(0,I_{J+1}),
\end{align*}}
as $E[(Z_t^*)^2Z_s] = 0$ for all $t \neq s$ by the properties of the standard normal distribution. Next, due to the Morrison-Sherman-Woodbury formula and the definition of $S$

{\footnotesize \begin{align*}
    (JS)^{-1} &= \left(I_J(J-1) + \iota\iota'\right)^{-1} = \frac{1}{J-1}\left[I_J - \frac{1}{(2J-1)}\iota\iota'\right].
\end{align*}}
\paragraph{\textbf{Wald Test:}}
We can decompose {\footnotesize \begin{align*}
     \hat{t}_{\ell_2}^2
     &= \frac{n}{J}(\hat{m} - m + m)'S^{-1}(\hat{m} - m + m) \\
     &= \frac{n}{J}(\hat{m} - m)'S^{-1}(\hat{m} - m) + 2\frac{n}{J}m'S^{-1}(\hat{m} - m) + \frac{n}{J}m'S^{-1} m \\
     &= {Z^*}'Z^*  + 2\sqrt{{n}}\mu'(JS)^{-1/2}S^{-1/2}\sqrt{\frac{n}{J}}(\hat{m} - m) + \frac{n}{J}m'm - \frac{n}{J-1}\frac{m'\iota\iota'm}{(2J - 1)}. 
\end{align*}}
Hence, we obtain an upper bound of the power under local alternatives as {\footnotesize \begin{align*}
    P_{\xi}\left( \hat{t}_{\ell_2}^2 > CV_{\chi^2(J),1-\alpha}\right) 
    &\leq P\left(  {Z^*}'Z^*  + 2 \xi' S^{-1/2} Z +  > CV_{\chi^2(J),1-\alpha} - \frac{||\xi||_2^2}{J} \right) \\
    &\leq P\left( \frac{{Z^*}'Z^*  - J}{\sqrt{2J}}  + 2 \xi' \frac{1}{\sqrt{2J}}(JS)^{-1/2} Z^*   > \frac{CV_{\chi^2(J),1-\alpha} - J}{\sqrt{2J}} - \frac{1}{2J}\frac{||\xi||_2^2}{J} \right).
\end{align*}}
Now note that {\footnotesize \begin{align*}
    \xi'(JS)^{-1}\xi \leq ||\xi||_2^2 ||(JS)^{-1}||_2 \leq \frac{||\xi||_2^2}{J}
\end{align*}} This together with joint convergence above, we have that, for large $J$ {\footnotesize \begin{align*}
     P_{\xi}\left( \hat{t}_{\ell_2}^2 > CV_{\chi^2(J),1-\alpha}\right) 
     &\leq P\left( Z^{**}  > \frac{z_{1-\alpha}}{\sqrt{1 + {2||\xi||^2_2}/{J}}} - \frac{1}{\sqrt{2J}}\frac{{||\xi||_2^2}/{J}}{\sqrt{1 + {2||\xi||^2_2}/{J}}} \right) + o(1),
\end{align*}}
where $Z^{**} \sim N(0,1)$. 
\paragraph{\textbf{Supremum Test:}}
Denote as $CV_{Gumbel(a,b),\alpha}$ the $\alpha$-quantile of the $Gumbel(a,b)$ distribution. We first show that, for large $J$, we have that 

{\footnotesize \begin{align}
    \frac{\sup_{t\neq 0}|Z_t + Z_0/\sqrt{J}| - a_J}{b_J} \overset{d}{=} Gumbel(0,1) + o(1), \label{eq_app_gumbel1}
\end{align}}
where %{\footnotesize \begin{align*}
    $a_J = \sqrt{2 \log J} - \frac{\log \log J + \log 4\pi}{2 \sqrt{2 \log J}}$ and
$b_J = \frac{1}{\sqrt{2 \log J}}$.
%\end{align*}}
% Moreover, note that, for large $J$, we also have that {\footnotesize \begin{align}
%     \frac{\sup_t|Z_t + Z_0/\sqrt{J}| - a_J}{b_J} \overset{d}{=} Gumbel(0,1)
% \end{align}}
To do so, we verify Lemma 3.2 of \citeA{Berman1964LimitSequences}. Lemma 3.1 then implies the distributional result. Note that $\{Z_0/\sqrt{J} + Z_j\sqrt{1-1/J}\}_{j>0}$ is a mean zero, unit variance Gaussian sequence with covariance $r_j = E[Z_jZ_0] = 1/J$. Lemma 3.2 of \citeA{Berman1964LimitSequences} then corresponds to showing that

{\footnotesize \begin{align*}
    \sum_{j=1}^J|r_j|(J-j)(1-r_j^2)^{-1/2}J^{-2/(1+|r_j|)}(\log J)^{1/(1+|r_j|)} = o(1).
\end{align*}}
Plugging in $r_j$ and simplifying yields {\footnotesize \begin{align*}
     \sum_{j=1}^J&J^{-1}(J-j)(1-J^{-2})^{-1/2}J^{-2/(1+J^{-1})}(\log J)^{1/(1+J^{-1})} \\
     &= J^{-1}(1-J^{-2})^{-1/2}J^{-2/(1+J^{-1})}(\log J)^{1/(1+J^{-1})}(J^2 - J^2/2) \\
     &\lesssim (\log J)^{1/(1+J^{-1})} J^{-1 - 2/(1+J^{-1}) + 2} 
\end{align*}}
which is $o(1)$ if $J > 1$, which verifies \eqref{eq_app_gumbel1}. 
Next, we derive the local power of the supremum test.
Let $CV_{J,1-\alpha}$ denote the $1-\alpha$ critical value of $\sup_{t \neq 0}|Z_t\sqrt{1-1/J} + Z_0/\sqrt{J}|$. We can bound the local power as follows 

{\footnotesize \begin{align*}
    P_{\xi}\left( \hat{t}_{\ell_\infty} > CV_{J,1-\alpha}\right) 
    &= P_{\xi}\left( \sup_{t \neq 0}\left|\sqrt{\frac{n}{J}}\hat{m}_t\right| > CV_{J,1-\alpha}\right) \\
    &\leq P_{\xi}\left( \sup_{t \neq 0}\left|\sqrt{\frac{n}{J}}(\hat{m}_t - m_t)\right| > CV_{J,1-\alpha} - \frac{\sqrt{n}\sup_t|m_t|}{\sqrt{J}}\right) \\
    &= P_{\xi}\left( \sup_{t \neq 0}\left|Z_t\sqrt{1-1/J} + Z_0/\sqrt{J}\right| > CV_{J,1-\alpha} - \frac{||\sqrt{n}m||_{\infty}}{\sqrt{J}}\right) \\
    &=  P\left( \frac{\sup_{t \neq 0}\left|Z_t\sqrt{1-1/J} + Z_0/\sqrt{J}\right| - a_J}{b_J} >  \frac{CV_{J,1-\alpha} - a_J}{b_J} - \frac{||\xi||_{\infty}}{\sqrt{J}b_J}\right) + o(1) \\
    &= P\left( Gumbel(0,1) >  CV_{Gumbel(0,1),1-\alpha} - \sqrt{\frac{2\log J }{J}}||\xi||_{\infty}\right) + o(1).
\end{align*}}

\paragraph{\textbf{Decomposition Test:}}
Now consider the simple two-sided test for decomposition parameter based on Theorem \ref{thm_asyN1}. Its power given local alternatives is given by 

{\footnotesize \begin{align*}
P_{\xi}&\left(\left|\frac{\sqrt{n}\hat{\Delta}_1}{\Sigma_{{\Delta}_1}^{1/2}}\right| > z_{1-\alpha/2} \right) \\
&= P_{\xi}\left(\sqrt{n}\frac{\hat{\Delta}_1}{\Sigma_{{\Delta}_1}^{1/2}} > z_{1-\alpha/2} \right) + P\left(\sqrt{n}\frac{\hat{\Delta}_1}{\Sigma_{{\Delta}_1}^{1/2}} < z_{\alpha/2} \right) \\
    &= P_{\xi}\left(\sqrt{n}\frac{(\hat{\Delta}_1-\Delta_1)}{\Sigma_{{\Delta}_1}^{1/2}} + \sqrt{n}\frac{\Delta_1}{\Sigma_{{\Delta}_1}^{1/2}} > z_{1-\alpha/2} \right) \\
    &\quad + P_{\xi}\left(\sqrt{n}\frac{(\hat{\Delta}_1-\Delta_1)}{\Sigma_{{\Delta}_1}^{1/2}} + \sqrt{n}\frac{\Delta_1}{\Sigma_{{\Delta}_1}^{1/2}}< z_{\alpha/2} \right) \\
    &= P\left(Z^* + \frac{1}{\Sigma_{{\Delta}_1}^{1/2}}\sum_te_{ta}\xi_t > z_{1-\alpha/2}\right) + P\left(Z^* + \frac{1}{\Sigma_{{\Delta}_1}^{1/2}}\sum_te_{ta}\xi_t  < z_{\alpha/2}\right) + o(1)\\
    &=1- \Phi\left(z_{1-\alpha/2} -\ip{e_a,\xi}_{\ell^2(\ta)} \right) + \Phi\left(z_{\alpha/2} - \ip{e_a,\xi}_{\ell^2(\ta)} \right) + o(1),
\end{align*}}
where the last step follows from the simplifying assumption that all potential outcome mean differences have variance one, see also the variance of the leading term derivation in Section \ref{sec_proof_leadingterm1}.

