    % \item $\theta_{tg3} := Cov(e_t(X),\mu_t(X)|X\in \xg) = E[e_t(X)\mu_t(X)|X\in \xg] - e_{t}(\xg) \mu_t(\xg) = \theta_{a,g,t,7} - \theta_{a,g,t,6}$
    , $\theta_{a,g,t,8} := e_{ta}\mu_t$.  
% {\footnotesize\begin{enumerate}
%     \item $\theta_{a,g,t,1} := e_{ta}(\xg) \mu_t(\xg)$
%     \item $\theta_{a,g,t,2} := E[e_{ta}(X)|X\in\xg]\mu_t(\xg)$
%     \item $\theta_{a,g,t,3} := E[e_{ta}(X)\mu_t(X)|X\in \xg]$
%     \item $\theta_{a,g,t,4} := e_{ta}\mu_t(\xg)$
%     \item $\theta_{a,g,t,5} := e_{ta}(\xg)\mu_t$ 
%     % \item $\theta_{tag6} := Cov(e_{ta}(X),\mu_t(X)|X\in \xg) = E[e_{ta}(X)\mu_t(X)|X\in \xg] - e_{ta}(\xg) \mu_t(\xg) = \theta_{a,g,t,3} - \theta_{a,g,t,1}$ 
%     \item $\theta_{a,g,t,6} := e_{t}(\xg) \mu_t(\xg)$
%     \item $\theta_{a,g,t,7} := E[e_t(X)\mu_t(X)|X\in \xg]$
%     % \item $\theta_{tg3} := Cov(e_t(X),\mu_t(X)|X\in \xg) = E[e_t(X)\mu_t(X)|X\in \xg] - e_{t}(\xg) \mu_t(\xg) = \theta_{a,g,t,7} - \theta_{a,g,t,6}$
%     \item $\theta_{a,g,t,8} := e_{ta}\mu_t$    
% \end{enumerate}}
Their respective influence functions $\Psi_{\theta_{a,g,t,p}}$ for $p\in \{1,...8\}$ are derived using the discretization approach discussed in \citeA{Kennedy2024SemiparametricReview}. %in %Supplementary Appendix \ref{app:if-detail}. 
Now we can write all $d$ parameters as combination of the eight primitives:
     $d_0(a) = \sum_{t\in\ta} \theta_{a,g,t,8}$
    , $d_1(a,g) = \sum_{t\in\ta} \theta_{a,g,t,4} - \theta_{a,g,t,8}$
    , $d_2(a,g) = \sum_{t\in\ta} \theta_{a,g,t,5} - \theta_{a,g,t,8}$
    , $d_3(a,g) = \sum_{t\in\ta} \theta_{a,g,t,1} - \theta_{a,g,t,5} - \theta_{a,g,t,4} + \theta_{a,g,t,8}$
    , $d_4(a,g) = \sum_{t\in\ta} (\theta_{a,g,t,7} - \theta_{a,g,t,6}) / P(T\in\mathcal{T}_a,X\in\xg)$
    , $d_{4'}(a,g) = \sum_{t\in\ta} \theta_{a,g,t,3} - \theta_{a,g,t,3}$
    , $d_{5}(a,g) = \sum_{t\in\ta} \theta_{a,g,t,2} - \theta_{a,g,t,1}$. 
% {\footnotesize\begin{enumerate}
%     \item $d_0(a) = \sum_{t\in\ta} \theta_{a,g,t,8}$
%     \item $d_1(a,g) = \sum_{t\in\ta} \theta_{a,g,t,4} - \theta_{a,g,t,8}$
%     \item $d_2(a,g) = \sum_{t\in\ta} \theta_{a,g,t,5} - \theta_{a,g,t,8}$
%     \item $d_3(a,g) = \sum_{t\in\ta} \theta_{a,g,t,1} - \theta_{a,g,t,5} - \theta_{a,g,t,4} + \theta_{a,g,t,8}$
%     \item $d_4(a,g) = \sum_{t\in\ta} (\theta_{a,g,t,7} - \theta_{a,g,t,6}) / P(T\in\mathcal{T}_a,X\in\xg)$
%     \item $d_{4'}(a,g) = \sum_{t\in\ta} \theta_{a,g,t,3} - \theta_{a,g,t,3}$
%     \item $d_{5}(a,g) = \sum_{t\in\ta} \theta_{a,g,t,2} - \theta_{a,g,t,1}$
% \end{enumerate}}
Their respective influence functions follow by applying the chain rule, e.g. $\Psi_{d_1(a,g)} := \sum_{t\in\ta} \Psi_{\theta_{a,g,t,4}} - \Psi_{\theta_{a,g,t,8}}$. The only parameter that is more involved in this regard is $d_4(a,g)$. Its IF is obtained via chain rule $\Psi_{d_4(a,g)} = \sum_{t\in\ta}  \Psi_{\theta_{a,g,t,7}} / e_{ag} - \Psi_{\theta_{a,g,t,6}}  / e_{ag} - \Psi_{e_{ag}}  (\theta_{a,g,t,7} - \theta_{a,g,t,6}) /  e_{ag}^2$,
where $\Psi_{e_{ag}} = \mathbbm{1}(T\in\mathcal{T}_a,X\in\xg) - e_{ag}$.
Similarly, the influence functions of $\delta$ parameters with $j \in \{0,1,2,3,4,4',5\}$ follow as $\Psi_{\delta_j(a,a',g)} = \Psi_{d_j(a,g)} - \Psi_{d_j(a',g)}$, and for $\Delta$ parameters as $\Psi_{\Delta_j(a,a',g,g')} = \Psi_{\delta_j(a,a',g)} - \Psi_{\delta_j(a,a',g')}$.


