% (2022-11-10) Include remarks on what the update equations will be in the case of no ratchet and in the case with a roll-up guarantee.
% \end{boxk}

\begin{rem}
\label{rem-UpdateEquation}
In the formulation of the optimal control problems below, it is convenient to denote the update equations yielding $X(t_k^+)$ and $G(t_k^+)$ by $h^X(X(t_k^-),G(t_k^-),w(t_k))$ and $h^G(X(t_k^-),G(t_k^-),w(t_k))$, respectively, where
\begin{equation}
    \label{eqn-Update-PostWithdrawalInvestmentAccount}
    h^X(x,\gamma,w) = \max\left\{0, \frakf(x) - \frakg(x,\gamma) - (w - \frakg(x,\gamma))^+\right\},
\end{equation}
and
\begin{equation}
    \label{eqn-Update-PostWithdrawalGuaranteeBase}
    h^G(x,\gamma,w) = 
    \begin{cases}
        \dfrac{1}{\beta} \frakg(x,\gamma) & \text{if $w \leq \frakg(x,\gamma)$},\\
        % \dfrac{1}{\beta} \frakg(x,\gamma) - (w - \frakg(x,\gamma)) & \text{if $w > \frakg(x,\gamma)$}\\
        % & \quad \text{and $\frakf(x) \geq (1+\frac{1}{\beta})\frakg(x,\gamma)$}\\
        \dfrac{1}{\beta} \frakg(x,\gamma) \left(1 - \dfrac{w - \frakg(x,\gamma)}{\frakf(x) - \frakg(x,\gamma)}\right) & \text{if $w > \frakg(x,\gamma)$}. % \\
        % & \quad \text{and $\frakf(x) < (1+\frac{1}{\beta})\frakg(x,\gamma)$}
    \end{cases}
\end{equation}
This notation emphasizes that the updated investment account value and benefit base are functions of the withdrawal amount, the pre-withdrawal investment account value, and the pre-withdrawal benefit base. % The function $h^X$ is given by \eqref{eqn-Update-InvestmentAccount-PostWithdrawal} and the function $h^G$ is given by either \eqref{eqn-Update-BenefitBase-NoExcess} or \eqref{eqn-Update-BenefitBase-Excess}.
\end{rem}

In the following we present the policyholder's total discounted cash flows when withdrawals and the interest gains on the cash fund are taxed.
% proceeds are taxed and the taxation of interest income on the cash fund. % Let $\vm{1}_{CF}$ be an indicator function with value 1 if the contract includes a cash fund and with value 0 otherwise. 
The post-tax value of the net withdrawal is % \[\text{post-tax withdrawal} = (1 - \theta) (w(t_k) - \zeta(w(t_k) - g(t_k))^+),\] 
\[\text{post-tax withdrawal} = (1 - \theta) w(t_k),\] 
where $\theta$ is the policyholder's marginal tax rate. In the taxation scheme assumed in this paper, the interest earnings on the cash fund are taxed, but not the actual balance of the cash fund itself as this is part of the initial investment. We now consider the cash fund injection at time $t_k$. If $w(t_k) < g(t_k)$, then the amount $g(t_k) - w(t_k)$ is deposited into the cash fund, where it will earn interest at a rate $\eta$ over the period $[t_k, t_N]$. The interest earned, expressed as \[(e^{\eta(t_N - t_k)} - 1) (g(t_k) - w(t_k))^+\] is then subject to tax. Therefore, the contribution of the injection at time $t_k$ to the terminal value of the cash fund is \[\underbrace{(1 - \theta) (e^{\eta(t_N - t_k)} - 1) (g(t_k) - w(t_k))^+}_{\text{post-tax interest income on CF}} + (g(t_k) - w(t_k))^+.\] This expression simplifies to $[(1 - \theta) e^{\eta (t_N - t_k)} + \theta] (g(t_k) - w(t_k))^+.$

Therefore, given an admissible withdrawal strategy $\vm{w}\in\calW$ and the corresponding state variable trajectories $\vm{X}:=(X(t_1^-),\dots,X(t_N^-))$ and $\vm{G}:=(G(t_1^-),\dots,G(t_N^-))$ achieved under the control $\vm{w}$, the discounted value at time $t=0$ of all cash flows from the VA contract can be represented as
\begin{align*}
	H_0(\vm{X}, \vm{G}, \vm{w})
	& = \sum_{k=1}^{N-1} e^{-r t_k} (1 - \theta) w(t_k) \\
	& \qquad + e^{-r t_N} \sum_{k=1}^{N-1}  \vm{1}_{CF} \cdot \Big( [(1 - \theta) e^{\eta (t_N - t_k)} + \theta] (g(t_k) - w(t_k))^+ \Big) \\
	& \qquad + e^{-r t_N} (1 - \theta) \max \{X^{PF}(t_N^-), g(t_N)\},
\end{align*}
where $\vm{1}_{CF}$ is an indicator function that is equal to 1 when the VA contract includes a cash fund (and is equal to 0 otherwise). The second summation can be written as follows
\begin{align*}
	& e^{-r t_N}  \sum_{k=1}^{N-1}  \vm{1}_{CF} \cdot \Big( [(1 - \theta) e^{\eta (t_N - t_k)} + \theta] (g(t_k) - w(t_k))^+ \Big) \\
	& \qquad = e^{-r t_N}  \sum_{k=1}^{N-1} \vm{1}_{CF} e^{-r t_k} e^{r t_k} [(1 - \theta) e^{\eta (t_N - t_k)} + \theta] (g(t_k) - w(t_k))^+ \\
	& \qquad = \sum_{k=1}^{N-1} \vm{1}_{CF} e^{-r t_k}  e^{-r (t_N - t_k)} [(1 - \theta) e^{\eta (t_N - t_k)} + \theta] (g(t_k) - w(t_k))^+ \\
	& \qquad = \sum_{k=1}^{N-1} \vm{1}_{CF} e^{-r t_k} \left[(1 - \theta) e^{-(r - \eta) (t_N - t_k)} + \theta e^{-r (t_N - t_k)}\right] (g(t_k) - w(t_k))^+.
\end{align*}
The total discounted cash flows can therefore be written in terms of a ``running cost'' and ``terminal cost'' term (as is usual in optimal control problems) as 
\begin{align}		\label{eqn-TotalDiscountedCF_Tax}
	H_0(\vm{X}, \vm{G}, \vm{w}) = \sum_{k=1}^{N-1} e^{-r t_k} C(t_k, X(t_k^-), G(t_k^-), w(t_k)) + e^{-r t_N} D(X(t_N^-), G(t_N^-)),
\end{align}
where
\begin{align}
    \begin{split}
        \label{eqn-TotalDiscountedCF-Running_Tax}
	& C(t_k, X(t_k^-), G(t_k^-), w(t_k)) \\
	& \qquad := (1 - \theta) w(t_k) + \vm{1}_{CF} \left[(1 - \theta) e^{-(r - \eta) (t_N - t_k)} + \theta e^{-r (t_N - t_k)}\right] (g(t_k) - w(t_k))^+
    \end{split}
\end{align}
and
\begin{equation}
    \label{eqn-TotalDiscountedCF-Terminal_Tax}
    D(X(t_N^-), G(t_N^-)) := (1 - \theta) \max \{X^{PF}(t_N^-), g(t_N)\}.
\end{equation}
% \begin{align}	\label{eqn-TotalDiscountedCF-Running_Tax}
% 	C(t_k, X(t_k^-), G(t_k^-), w(t_k))
% 	& := (1 - \theta) w(t_k)  \\
% 	& \qquad + \vm{1}_{CF} \left[(1 - \theta) e^{-(r - \eta) (t_N - t_k)} + \theta e^{-r (t_N - t_k)}\right] (g(t_k) - w(t_k))^+ \nonumber \\	\label{eqn-TotalDiscountedCF-Terminal_Tax}
% 	D(X(t_N^-), G(t_N^-))
% 	& := (1 - \theta) \max \{X^{PF}(t_N^-), g(t_N)\}.
% \end{align}
From \eqref{eqn-Update-InvestmentAccount-PostFee} and \eqref{eqn-GuaranteedWithdrawalAmount}, we note that the right-hand sides of $C(t_k, X(t_k^-), G(t_k^-), w(t_k))$ and $D(X(t_N^-), G(t_N^-))$ are indeed functions of $X(t_k^-)$ and $G(t_k^-)$.

\begin{rem}
	If $\theta = 0$ (no tax), and $\vm{1}_{CF} = 1$ (policyholder has a cash fund), then we also obtain the discounted cash flows written in terms of a ``running cost'' and ``terminal cost'' term as
	\begin{equation}
		\label{eqn-TotalDiscountedCF}
		H_0(\vm{X},\vm{G},\vm{w}) = \sum_{k=1}^{N-1} e^{-r t_k}  C(t_k, X(t_k^-), G(t_k^-), w(t_k)) + e^{-r t_N} D(X(t_N^-), G(t_N^-)),
	\end{equation}
	where
	\begin{align}
		\label{eqn-TotalDiscountedCF-Running}
		C(t_k, X(t_k^-), G(t_k^-), w(t_k)) & := w(t_k) + e^{-(r-\eta)(t_N-t_k)} (g(t_k)-w(t_k))^+, \\
		\label{eqn-TotalDiscountedCF-Terminal}
		D(X(t_N^-), G(t_N^-)) & := \max\{X^{PF}(t_N^-), g(t_N)\}.
	\end{align}
%	the base case specified by equations \eqref{eqn-TotalDiscountedCF-Running} and \eqref{eqn-TotalDiscountedCF-Terminal}.
\end{rem}

We denote by $J_t(x,\gamma;\vm{w})$ the price of the VA contract at time $t$ given the withdrawal strategy $\vm{w}$, $X(t) = x$, and $G(t) = \gamma$. At $t=0$, the quantity $$J_0(x,\gamma;\vm{w}) := \E^\Q[H_0(\vm{X}, \vm{G}, \vm{w})],$$ yields the contract fair price under the withdrawal strategy $\vm{w}$. The above expectation is dependent on the guarantee fee $\varphi$. Consequently, the value of $\varphi$ such that $P_0 = J_0(P_0,P_0;\vm{w})$ is the fair guarantee fee corresponding to the strategy $\vm{w}$.

If the policyholder adopts a dynamic strategy, we assume that they choose their withdrawal strategy to maximize the present value of cash flows from the contract. That is, the policyholder seeks the optimal withdrawal strategy $\vm{w}^*\in\calW$ such that
\begin{equation}
\label{eqn-PHOptimization-t0}
J_0(x,\gamma;\vm{w}^*) = \sup_{\vm{w}\in\calW} \E^\Q[H_0(\vm{X},\vm{G},\vm{w})] =: V_0(x,\gamma).
\end{equation}
It is understood that the state variable trajectories $\vm{X}$ and $\vm{G}$ appearing in the expectation above are those corresponding to strategy $\vm{w}$ with initial values $X(t_0) = x$ and $G(t_0) = \gamma$.

In particular, we investigate the optimal control problem at each time $t_k^-$ prior to any withdrawals. To this end, the value function $V_{t_k}(x,\gamma)$ is given by
\begin{align}
\begin{split}
\label{eqn-PHOptimization-tk}
V_{t_k}(x,\gamma) 
    & = \sup_{\substack{w(t_j)\in\calW(t_j)\\ j=k,k+1,\dots,N-1}}\E^\Q\Bigg[\sum_{j=k}^{N-1} e^{-r(t_j-t_k)}C(t_j, X(t_j^-), G(t_j^-), w(t_j))\\
    & \qquad \qquad + e^{-r(t_N-t_k)}D(X(t_N^-), G(t_N^-)) \bigg| X(t_k^-) = x, G(t_k^-) = \gamma\Bigg].
\end{split}
\end{align}
This problem may be solved through backward induction via the Bellman equation
\begin{align}
\begin{split}
\label{eqn-PHOptimization-BellmanEquation}
V_{t_k}(x,\gamma) 
    & = \sup_{w(t_k)\in\calW(t_k)}\Bigg\{C(t_k, x,\gamma,w(t_k))\\
    & \qquad \qquad + \E^\Q_{w(t_k)}\left[e^{-r\Delta t} V_{t_{k+1}}(X(t_{k+1}^-), G(t_{k+1}^-)) | X(t_k^-) = x, G(t_k^-) = \gamma\right]\Bigg\},
\end{split}
\end{align}
with terminal condition $$V_{t_N}(x,\gamma) = D(x,\gamma).$$ %\citep[see, for example,][Theorem 2.2]{Bjork-2021}. 
The subscript ``$w(t_k)$'' on the expectation operator emphasizes that the expectation is taken with respect to the transition probability function of the state variables $(X(t),G(t))$ over the interval $[t_k^-, t_{k+1}^-]$ with initial state $(x,\gamma)$ at time $t_k^-$, if the amount $w(t_k)$ is withdrawn at time $t_k$.

The backward induction \eqref{eqn-PHOptimization-BellmanEquation} can be solved in two stages, first at time $t_k^+$ then at time $t_k^-$, following \citet{Gudkov-2019, Shevchenko-2017}, for example. Denoting by $V_{t_k^-}(\cdot)$ and $V_{t_k^+}(\cdot)$ the value of the contract before and after the withdrawal event at time $t_k$, respectively, we first compute the expectation
\begin{equation}
\label{eqn-PHOptimization-Stage1}
V_{t_k^+}(x,\gamma) = \E^\Q\left[e^{-r\Delta t} V_{t_{k+1}^-}(X(t_{k+1}^-), \gamma) | X(t_k^+) = x, G(t_k^+) = \gamma\right].
\end{equation}
Observe that we have $G(t_{k+1}^-) = \gamma$ in the expectation since the benefit base does not change on the interval $[t_k^+, t_{k+1}^-]$; see \eqref{eqn-Update-BenefitBase-Minus}. The value function prior to withdrawal is then solved as
\begin{equation}
\label{eqn-PHOptimization-Stage2}
V_{t_k^-}(x,\gamma) = \sup_{w(t_k)\in\calW(t_k)}\left\{C(t_k,x,\gamma,w(t_k)) + V_{t_k^+}(h^X(x,\gamma,w(t_k)), h^G(x,\gamma,w(t_k)))\right\}.
\end{equation}
The quantity $V_{t_k^+}(h^X(x,\gamma,w(t_k)), h^G(x,\gamma,w(t_k)))$ denotes the post-withdrawal value function if the policyholder makes a withdrawal of $w(t_k)$, resulting in $X(t_k^+) = h^X(x,\gamma,w(t_k))$ and $G(t_k^+) = h^G(x,\gamma,w(t_k))$; see Remark \ref{rem-UpdateEquation}. As in the Bellman equation, the two-stage process given by \eqref{eqn-PHOptimization-Stage1} and \eqref{eqn-PHOptimization-Stage2} are implemented for $k=N-1,N-2,\dots,0$ with terminal condition $V_{t_N^-} = D(X(t_N^-), G(t_N^-))$. 

