\subsection{Applying the Jump Condition via Interpolation}

Second, we consider the jump condition represented by the maximization problem \eqref{eqn-PHOptimization-Stage2} with respect to the withdrawal strategy $w(t_k)$ at time $t_k$. The following algorithm is adapted from \citet{Gudkov-2019} and \citet{Shevchenko-2017} and uses the notation introduced in Remarks \ref{rem-mathfrak-notation} and \ref{rem-UpdateEquation}. Fix $k \in\{N-1,N-2,\dots,1,0\}$ and suppose that $V_{t_k^+}(x,\gamma)$ has been approximated by a numerical solution of \eqref{eqn-PHOptimization-PDE2}. This approximation is available only on the values of $(x,\gamma)$ on the grid $\mathbb{X} \times \mathbb{G}$ corresponding to the domain $(0,\infty)\times\Gamma$. However, for a given $w\in\calW(t_k)$, the values $x' = h^X(x,\gamma,w)$ and $\gamma' = h^G(x,\gamma,w)$ may not be on this grid. Therefore, a two-dimensional interpolation in $(x,y)$ is necessary to approximate the value of $V_{t_k}^+(h^X(x,\gamma,w),h^G(x,\gamma,w))$ from the known values of $V_{t_k}^+(x,\gamma)$.

The interpolation and numerical solution of \eqref{eqn-PHOptimization-Stage2} proceeds as follows for each $(x,\gamma)\in\mathbb{X}\times\mathbb{G}$:
\begin{enumerate}
    \item Construct a grid $\mathbb{W}$ of possible values of $w$ based on $\calW(t_k) = [0, \max\{\frakf(x), \frakg(x,\gamma)\}]$.

    \item Compute the value of $h^X(x,\gamma,w)$ and $h^G(x,\gamma,w)$. If $h^X(x,\gamma,w) = 0$, then we replace it with the smallest value on the grid $\mathbb{X}$.

    \item Approximate $V_{t_k}^+(h^X(x,\gamma,w),h^G(x,\gamma,w))$ by interpolation from $\{V_{t_k}^+(x,\gamma)\}_{(x,\gamma)\in\mathbb{X}\times\mathbb{G}}$, the approximate solution  the PDE \eqref{eqn-PHOptimization-PDE2}.

    \item Choose the value of $w^*\in\mathbb{W}$ such that 
    \begin{equation}
        \label{eqn-OptimalWithdrawal}
        w^*(t_k) = w^*(t_k,x,\gamma) = \argmax_{w\in\mathbb{W}}\left\{C(t_k,x,\gamma,w(t_k)) + V_{t_k^+}(h^X(x,\gamma,w), h^G(x,\gamma,w))\right\}.
    \end{equation}
    Consequently, we have \[V_{t_k}^-(x,\gamma) = C(t_k, x, \gamma, w^*(t_k) + V_{t_k}^+(h^X(x,\gamma,w^*(t_k)), h^G(x,\gamma,w^*(t_k)).\]
\end{enumerate}
The approximation $\{V_{t_k}^-(x,\gamma)\}_{(x,\gamma)\in\mathbb{X}\times\mathbb{G}}$ is then used as the terminal condition to solve PDE \eqref{eqn-PHOptimization-PDE2} for $V_{t_{k-1}}^+(x,\gamma)$.

\subsection{Numerical Solution of the PDE via Method of Lines (MOL)}

We first consider the interval $[t_{N-1}^+,t_N^-]$, the time period before the VA matures. We solve PDE \eqref{eqn-PHOptimization-PDE2}, for a fixed $\gamma\in\Gamma\subseteq[0,+\infty)$, for $\tau\in(0,t_N-t_{N-1})=(0,\Delta t)$ and $x\in[0,+\infty)$, with initial condition
\begin{equation}
\label{eqn-PHOptimization-PDE2-InitialCondition}
U(0,x,\gamma) = D(x,\gamma) = \max\{\frakf(x),\frakg(x,\gamma)\}, \qquad x\in[0,+\infty).
\end{equation}
Boundary conditions in $x$ are discussed below:
\begin{itemize}
    \item \textit{Boundary condition along $x=0$:} Recall that
    \begin{align*}
        V_{t_{N-1}^+}(0,\gamma)
            & = \E_\Q\left[e^{-r(t_N-t_{N-1})} V_{t_N^-}(X(t_N^-), \gamma) | X(t_{N-1}^+) = 0, G(t_{N-1}^+) = \gamma\right]\\
            & = \E_\Q\left[e^{-r(t_N-t_{N-1})} D(X(t_N^-), \gamma) | X(t_{N-1}^+) = 0, G(t_{N-1}^+) = \gamma\right].
    \end{align*}
    From \eqref{eqn-Update-InvestmentAccount-Minus}, if $X(t_{N-1}^+) = 0$, then $X(t_N^-) = 0$ a.s. Therefore, \[V_{t_{N-1}^+}(0,\gamma) = e^{-r(t_N - t_{N-1})} D(0,\gamma) = e^{-r(t_N-t_{N-1})}\beta\gamma,\] and so we have the boundary condition
    \begin{equation}
    \label{eqn-PHOptimization-PDE2-BoundaryConditionx0}
    U(\tau,0,\gamma) = e^{-r\tau}\beta\gamma, \qquad \tau\in(0,\Delta t].
    \end{equation}
    In particular, we have $U(0,0,\gamma) = \beta\gamma$, which is consistent with the initial condition.

    \item \textit{Asymptotic boundary condition as $x\to+\infty$:} We adopt the boundary condition
    \begin{equation}
        \label{eqn-PHOptimization-PDE2-BoundaryConditionxinf}
        \pder[^2 U(\tau,x,\gamma)]{x^2} \to 0 \qquad \text{as $x\to\infty$}, \qquad \tau\in(0,\Delta t].
    \end{equation}
    This is justified by a formal differentiation of the Black-Scholes-type PDE and the application of Fichera theory for boundary conditions \citep[see, for example,][Example 1.17, with $\alpha=2$, $q=0$]{Meyer-2015}. This means that for very high values of the underlying investment account value, the value of the contract to the policyholder increases linearly with respect to the value of the investment account.
\end{itemize}

Let $\{\tau_0,\tau_1,\dots,\tau_{N_\tau}\}$ be a partition of $[0,\Delta t]$, where $\tau_0 = 0$, $\tau_{N_\tau} = \Delta t$, and $\Delta\tau = \tau_{n}-\tau_{n-1}$ for all $n=1,2,\dots,N_\tau$. Furthermore, let $U_n(x;\gamma) = U(\tau_n,x,\gamma)$ be the solution of \eqref{eqn-PHOptimization-PDE2} at $\tau = \tau_n$, parameterized by $\gamma$. We employ the three-level backward difference approximation for $\partial U/\partial \tau$,
\begin{equation}
    \label{eqn-MOL-FD-Time}
    \pder[U(\tau_n,x,\gamma)]{\tau} \approx 
    \begin{cases}
        \dfrac{U_n(x;\gamma) - U_{n-1}(x;\gamma)}{\Delta \tau}, & \text{for $n=1,2$}\\
        \dfrac{3}{2}\dfrac{U_n(x;\gamma) - U_{n-1}(x;\gamma)}{\Delta \tau} - \dfrac{1}{2}\dfrac{U_{n-1}(x;\gamma) - U_{n-2}(x;\gamma)}{\Delta \tau}, & \text{for $n=3,4,\dots,N_\tau$}.
    \end{cases}
\end{equation}
This approximation is unconditionally stable \citep[Appendix 2.2]{Meyer-2015}. The time discretization yields the approximation
\begin{equation}
    \label{eqn-MOL-PDEApproximation}
    a(x) U_{n}''(x;\gamma) + b(x) U_n'(x;\gamma) - c_n(x) U_n(x;\gamma) = F_n(x;\gamma)
\end{equation}
of PDE \eqref{eqn-PHOptimization-PDE2} at $\tau = \tau_n$, where
\begin{align*}
    a(x) & = \max\left\{\frac{1}{2}(\varrho \sigma x)^2, 10^{-6}\right\}\\
    b(x) & = rx\\
    c_n(x) & =  \begin{cases}
                r + \dfrac{1}{\Delta \tau}, & \text{if $n=1,2$}\\
                r + \dfrac{3}{2\Delta \tau}, & \text{if $n=3,4,\dots,N_\tau$}
                \end{cases}\\
    F_n(x;\gamma) & =  \begin{cases}
                -\dfrac{1}{\Delta\tau} U_{n-1}(x;\gamma), & \text{if $n=1,2$}\\
                -\dfrac{4U_{n-1}(x;\gamma) - U_{n-2}(x;\gamma)}{2\Delta\tau}, & \text{if $n=3,4,\dots,N_\tau$}.
                \end{cases}
\end{align*}
The replacement of $\frac{1}{2}(\varrho \sigma x)^2$ by $\max\left\{\frac{1}{2}(\varrho \sigma x)^2, 10^{-6}\right\}$ as the coefficient of $U_n''(x;\gamma)$ is done to avoid degeneracy at $x=0$. Alternatively, the lower bound for $x$ can be set to a very small number, for example, $x_0 = 10^{-6}$. The second-order differential equation can then be solved, for example, via the Riccati transform approach \citep[see, for example,][]{Meyer-2015}.


\section{Numerical Illustrations}
\label{sec-NumericalIllustrations}

We conduct several numerical experiments to illustrate the valuation of the hybrid VA product and the effect of taxes and certain product features, such as the presence of a cash fund, the cash fund appreciation rate, and the type of benefit base update scheme presented in Section \ref{sec-MathematicalFormulation}. In the base case, we assume that the model parameters, initial premium, the guaranteed withdrawal rate are as stated in Table \ref{tab-Parameters}. Specifically, we consider a 10-year product where withdrawals occur once a year at the policy anniversary. For each one-year period, the numerical estimate of the contract value is calculated over an 80-point grid in both the $x$- and $\gamma$-direction and a 50-point grid in the $\tau$-direction.\footnote{All computations were implemented in \texttt{R} on a MacBook Air running on the Apple M1 chip with 8 cores and 16GB RAM. Based on preliminary convergence experiments on the computation of the VA value at the fair guarantee fee as a function of the spatial grid size, we found that an 80-by-80 grid is sufficiently fine to allow a detailed examination of the optimal withdrawal behavior without being too prohibitive in terms of the required computational time.
% Due to hardware constraints, a modest grid size in the spatial and temporal dimensions were used. Through preliminary numerical experiments, the chosen grid sizes provide a reasonable degree of numerical accuracy in balance with the computational effort required to implement all subsequent calculations.
} 
