\noindent
With the required assumptions in hand, we now state our main consistency result. 
\begin{theorem} \label{Fnormcr}
(Frobenius norm convergence rates for SMGM estimator) Under Assumptions 1-5,
there exists a local minimizer $(\hat{\Omegabf}, \hat{\Gammabf})$ of (\ref{g}) such that
$$
\frac{\left\|\hat{\Omegabf}-\Omegabf_0\right\|_{\mathrm{F}}^2}{p}=O_{P_0}\left\{\left(1+\frac{s_1}{p}\right) \log p /(n q)\right\}
$$
and
$$
\frac{\left\|\hat{\Gammabf}-\Gammabf_0\right\|_{\mathrm{F}}^2}{q}=O_{P_0}\left\{\left(1+\frac{s_2}{q}\right) \log q /(n p)\right\} .
$$
\end{theorem}
\begin{proof}
We start by establishing required notation for the proof. 
\begin{eqnarray*}
&&\Deltabf_1=\Omegabf-\Omegabf_0,\Deltabf_2=\Gammabf-\Gammabf_0\\
&&
\tilde{\Deltabf}_{1}=\Omegabf_{0}^{-1 / 2} \Deltabf_{1} \Omegabf_{0}^{-1 / 2}, \tilde{\Deltabf}_{2}=\Gammabf_{0}^{-1 / 2} \Deltabf_{2} \Gammabf_{0}^{-1 / 2}\\
&&\zeta_1=\max(s_1,p),\zeta_2=\max(s_2,q)\\
&& \alpha_{1}=\left\{\zeta_{1} \log p /(n q)\right\}^{1 / 2}, \beta_{1}=\{p \log p /(n q)\}^{1 / 2} \\
&& \alpha_{2}=\left\{\zeta_{2} \log q /(n p)\right\}^{1 / 2}, \beta_{2}=\{q \log q /(n p)\}^{1 / 2}
\end{eqnarray*}
\noindent
For any positive integer $m$, let $\mathcal{D}_{m}$ denote the space of $m \times m$ diagonal matrices with positive diagonal entries, and let $\mathcal{R}_m$ denote the space of $m \times m$ matrices with all diagonal entries equal to zero. For a given positive constant $C$ (the choice of $C$ will be determined later in the proof), define the spaces $\mathcal{A}_p$ and $\mathcal{B}_p$ as 
{\small
\begin{eqnarray*}
\mathcal{A}_p &:=& \left\{\mathbf{M}: \; \mathbf{M}=\alpha_{1} \Rbf_{p}+\beta_{1} \Dbf_{p}, \; 
\Dbf_p \in \mathcal{D}_p, \; \Rbf_p \in \mathcal{R}_p \mbox{ and } \|\Dbf_p\|_F = \|\Rbf_p\|_F = C \right\}, \\
\mathcal{B}_q &:=& \left\{\mathbf{M}: \; \mathbf{M}=\alpha_{2} \Rbf_{q}+\beta_{2} \Dbf_{q}, \; 
\Dbf_q \in \mathcal{D}_q, \; \Rbf_q \in \mathcal{R}_q \mbox{ and } \|\Dbf_q\|_F = \|\Rbf_q\|_F = C \right\}. 
\end{eqnarray*}}

\noindent
We also establish some error bounds between relevant `sample' covariance matrices and their `population' counterparts. These bounds will be useful for the subsequent analysis. Let $\Xibf=\Yibf \Gammabf_{0}^{1 / 2}$ for $1 \leqslant i \leqslant n$. It follows that ${\bf X}_1, {\bf X}_2, \cdots, {\bf X}_n$ are i.i.d. from a matrix-variate normal distribution with mean matrix ${\bf 0}$, row covariance matrix $\Sigmabf_0$, and column covariance matrix ${\bf I}_q$. Hence, the matrix 
$$
\Qbf_{1}=(n q)^{-1} \sum_{i=1}^{n} \Xibf \Xibf^{\top} 
$$

\noindent
can be viewed as a sample covariance matrix obtained from $nq$ i.i.d. observations from $p$-variate normal distribution with mean vector $\underline{0}$ and covariance matrix $\Sigmabf_0$. Using \cite[Lemma A.3]{bickel2008regularized}, there exists a constant $K_{1}$ such that
\begin{equation} \label{Q1}
P_{0}\left\{\max _{1 \leqslant i, j \leqslant p}\left|\left(Q_{1}\right)_{i j}-\left(\Sigma_{0}\right)_{i j}\right| \leqslant K_{1} \sqrt{\frac{\log p}{n q}}\right\}\rightarrow 1. 
\end{equation}
Let $\Zibf=\Omegabf_{0}^{1 / 2}\Yibf$ for $1 \leqslant i \leqslant n$. It follows that ${\bf Z}_1, {\bf Z}_2, \cdots, {\bf Z}_n$ are i.i.d. from a matrix-variate normal distribution with mean matrix ${\bf 0}$, row covariance matrix ${\bf I}_q$, and column covariance matrix $\Psibf_0$. Hence, the matrix 
$$
\Qbf_{2}=(n p)^{-1} \sum_{i=1}^{n} \Zibf^{\top} \Zibf
$$

\noindent
can be viewed as a sample covariance matrix obtained from $np$ i.i.d. observations from $q$-variate normal distribution with mean vector $\underline{0}$ and covariance matrix $\Psibf_0$. Using \cite[Lemma A.3]{bickel2008regularized}, there exists a constant $K_{2}$ such that
\begin{equation}\label{Q2}
P_{0}\left\{\max _{1 \leqslant i, j \leqslant q}\left|\left(Q_{2}\right)_{i j}-\left(\Psi_{0}\right)_{i j}\right| \leqslant K_{2} \sqrt{\frac{\log q}{n p}}\right\}\rightarrow 1.\\
\end{equation}

\noindent
Finally, let 
$$
{\bf S} = \frac{1}{n} \sum_{i=1}^{n} \operatorname{vec}\left(\Yibf^{\top}\right) \operatorname{vec}\left(\Yibf^{\top}\right)^{\top} 
$$

\noindent
denote the $pq$-dimensional sample covariance matrix based on $n$ i.i.d. observations from a $pq$-variate normal distribution with mean vector $\underline{0}$ and covariance matrix $\Sigmabf_{0} \otimes \Psibf_{0}$. Again, by \cite[Lemma A.3]{bickel2008regularized}, there exists a constant $K_{3}$ such that 
\begin{equation} \label{Sk}
P_{0} \left\{\max _{1 \leqslant r, s \leqslant pq}\left|\left(S\right)_{rs}-\left(\Sigma_{0}\otimes\Psi_{0}\right)_{rs}\right| \leqslant K_{3} \sqrt{\frac{\log pq}{n }}\right\}  \rightarrow 1.
\end{equation}

\noindent
Let $K = \max(K_1, K_2, K_3)$ and define the sequences of events $\{C_{1,n}\}_{n \geqslant 1},\\\{C_{2,n}\}_{n \geqslant 1},
\{C_{3,n}\}_{n \geqslant 1}$ as 
\begin{eqnarray*}
 C_{1,n}&:=& \left\{\max _{1 \leqslant i, j \leqslant p}\left|\left(Q_{1}\right)_{i j}-\left(\Sigma_{0}\right)_{i j}\right| \leqslant K \sqrt{\frac{\log p}{n q}} \right\},\\
  C_{2,n}&:=&\left\{\max _{1 \leqslant i, j \leqslant q}\left|\left(Q_{2}\right)_{i j}-\left(\Psi_{0}\right)_{i j}\right| \leqslant K \sqrt{\frac{\log q}{n p}}\right\},\\
   C_{3,n}&:=&\left\{\max _{1 \leqslant r, s \leqslant pq}\left|\left(S\right)_{rs}-\left(\Sigma_{0}\otimes\Psi_{0}\right)_{rs}\right| \leqslant K \sqrt{\frac{\log pq}{n }}\right\},
\end{eqnarray*}
and let $C_n := C_{1,n}\cap C_{2,n} \cap C_{3,n}$. It follows from (\ref{Q1}), (\ref{Q2}) and (\ref{Sk}) that 
\begin{eqnarray}
\label{PCn}
   P_0 (C_n) \rightarrow 1 \mbox{ as } n \rightarrow \infty. 
\end{eqnarray}


\noindent
Our goal is to show that 
\begin{equation} \label{identity}
P_0 \left( \inf _{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q}\left\{g\left(\Omegabf_{0}+\Deltabf_{1}, \Gammabf_{0}+\Deltabf_{2}\right)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)\right\}>0  \right) \rightarrow 1 
\end{equation}

\noindent
as $n \rightarrow \infty$. Along with the definitions of $\mathcal{A}_p$ and $\mathcal{B}_q$, this would imply the existence of a local minimizer of $g$, say $(\hat{\Omegabf}, \hat{\Gammabf})$ that satisfies 
$$
\frac{\left\|\Omegabf_0^{-1/2} (\hat{\Omegabf}-\Omegabf_0)  \Omegabf_0^{-1/2} \right\|_{\mathrm{F}}^2}{p} = O_{P_0}\left\{\left(1+\frac{s_1}{p}\right) \log p /(n q)\right\}
$$
and
$$
\frac{\left\|\Gammabf_0^{-1/2} (\hat{\Gammabf}-\Gammabf_0) \Gammabf_0^{-1/2} \right\|_{\mathrm{F}}^2}{q} = O_{P_0}\left\{\left(1+\frac{s_2}{q}\right) \log q /(n p)\right\} .
$$

\noindent
Since $\|{\Abf^{1/2}} \Deltabf {\Abf^{1/2}}\|_F \leqslant \nu_{m}\left(\Abf\right) \|\Deltabf\|_F$ 
for any $m$-dimensional symmetric positive definite matrix ${\bf A}$ and any symmetric matrix $\Deltabf$, it follows by Assumption 2 that 
\begin{eqnarray}
\notag
\frac{\left\|\hat{\Omegabf}-\Omegabf_0\right\|_{\mathrm{F}}^2}{p}&\leqslant& \frac{1}{p\tau_{1}}\left\|\Omegabf_0^{-1/2} (\hat{\Omegabf}-\Omegabf_0)  \Omegabf_0^{-1/2} \right\|_{\mathrm{F}}^2 =O_{P_0}\left\{\left(1+\frac{\zeta_1}{p}\right) \log p /(n q)\right\}\\
\label{coveq1}
&=&O_{P_0}\left\{\left(1+\frac{s_1}{p}\right) \log p /(n q)\right\}
\end{eqnarray}
and
\begin{eqnarray}
\notag
\frac{\left\|\hat{\Gammabf}-\Gammabf_0\right\|_{\mathrm{F}}^2}{q}&\leqslant& \frac{1}{q\tau_{1}} \left\|\Gammabf_0^{-1/2} (\hat{\Gammabf}-\Gammabf_0) \Gammabf_0^{-1/2} \right\|_{\mathrm{F}}^2 = O_{P_0}\left\{\left(1+\frac{\zeta_2}{q}\right) \log q /(n p)\right\}\\
\label{coveq2}
&=& O_{P_0}\left\{\left(1+\frac{s_2}{q}\right) \log q /(n p)\right\}, 
\end{eqnarray}

\noindent
as required. Note equalities (\ref{coveq1}) and (\ref{coveq2}) follow from the fact that $\zeta_1=\max(s_1,p)$ and $\zeta_2=\max(s_2,q)$.  Hence, the focus in the subsequent analysis is to establish 
(\ref{identity}).


We first decompose $g(\Omegabf, \Gammabf)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)$, and take a \textbf{different} path than in \cite{leng2012sparse} to bound the decomposed terms. Note by Taylor's expansion that 
$$
\begin{aligned}
\log |\Omegabf|-\log \left|\Omegabf_{0}\right|= & \operatorname{tr}\left(\Sigmabf_{0} \Deltabf_{1}\right)-\operatorname{vec}\left(\Deltabf_{1}\right)^{\top}  \\
& \times\left\{\int_{0}^{1} \left(\Omegabf_{w}^{-1}\otimes \Omegabf_{w}^{-1}\right)(1-w) d w\right\} \operatorname{vec}\left(\Deltabf_{1}\right)
\end{aligned}
$$
where $\Omegabf_{w}=\Omegabf_{0}+w \Deltabf_{1}$ and $
 \Omegabf_{w}^{-1} \otimes \Omegabf_{w}^{-1}=\left(\Omegabf_{0}+w \Deltabf_{1}\right)^{-1} \otimes\left(\Omegabf_{0}+w \Deltabf_{1}\right)^{-1} $. A similar expansion can be obtained for 
 $\log |\Gammabf| - \log |\Gammabf_0|$ with $\Gammabf_{w}=\Gammabf_{0}+w \Deltabf_{2}$ and $
 \Gammabf_{w}^{-1} \otimes \Gammabf_{w}^{-1}=\left(\Gammabf_{0}+w \Deltabf_{2}\right)^{-1} \otimes\left(\Gammabf_{0}+w \Deltabf_{2}\right)^{-1} $. Using these expansions along with the definition of $g$ in (\ref{gobj}), we obtain the decomposition 
$$
g(\Omegabf, \Gammabf)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)=T_{1}+T_{2}+T_{3}+T_{4}+T_{5}+T_{6}+T_{7},
$$

\noindent
where 


\begin{eqnarray*}
T_{1}&= & \frac{1}{n p q}\left\{\sum_{i=1}^{n} \operatorname{tr}\left(\mathbf{Y}_{i} \Gammabf_{0} \mathbf{Y}_{i}^{\mathrm{T}} \Deltabf_{1}\right)\right\}-\frac{\operatorname{tr}\left(\Sigmabf_{0} \Deltabf_{1}\right)}{p}, \\
T_{2}&= & \frac{1}{n p q}\left\{\sum_{i=1}^{n} \operatorname{tr}\left(\mathbf{Y}_{i}^{\mathrm{T}} \Omegabf_{0} \mathbf{Y}_{i} \Deltabf_{2}\right)\right\}-\frac{\operatorname{tr}\left(\Psibf_{0} \Deltabf_{2}\right)}{q}, \\
T_{3}&= & \frac{1}{n p q} \sum_{i=1}^{n} \operatorname{tr}\left(\mathbf{Y}_{i} \Deltabf_{2} \mathbf{Y}_{i}^{\mathrm{T}} \Deltabf_{1}\right), \\
T_{4}&= & p^{-1} \operatorname{vec}^{\mathrm{T}}\left(\Deltabf_{1}\right)\left\{\int_{0}^{1} \left(\Omegabf_{w}^{-1}\otimes \Omegabf_{w}^{-1}\right)(1-w) d w\right\} \operatorname{vec}\left(\Deltabf_{1}\right), \\
T_{5}&= & q^{-1} \operatorname{vec}^{\mathrm{T}}\left(\Deltabf_{2}\right)\left\{\int_{0}^{1} \left(\Gammabf_{w}^{-1}\otimes \Gammabf_{w}^{-1}\right)(1-w) d w\right\} \operatorname{vec}\left(\Deltabf_{2}\right), \\
T_{6}&=&\sum_{(i, j) \in S_{1}^{c}} \left\{\lambda_{1}\left|\Omega_{ij}\right|-\lambda_{1}\left|\left(\Omega_{0}\right)_{i j}\right|\right\}+\sum_{(i, j) \in S_{2}^{c}} \left\{\lambda_{2}\left|\Gamma_{ij}\right|-\lambda_{2}\left|\left(\Gamma_{0}\right)_{i j}\right|\right\}\\
&=&\sum_{(i, j) \in S_{1}^{c}} \lambda_{1}\left|\left(\Delta_{1}\right)_{i j}\right| +\sum_{(i, j) \in S_{2}^{c}} \lambda_{2}\left|\left(\Delta_{2}\right)_{i j}\right| 
, \text { and } \\
T_{7}&=&\sum_{(i, j) \in S_{1}, i \neq j} \left\{\lambda_{1}\left|\Omega_{ij}\right|-\lambda_{1}\left|\left(\Omega_{0}\right)_{i j}\right|\right\}+\sum_{(i, j) \in S_{2},i \neq j} \left\{\lambda_{2}\left|\Gamma_{ij}\right|-\lambda_{2}\left|\left(\Gamma_{0}\right)_{i j}\right|\right\}. 
\end{eqnarray*}

\noindent
The main steps of the remaining proof are as follows. We first find positive lower bounds for both $T_{4}$ and $ T_{5}$. Note also that $T_{6}$ is non-negative. Next, we carefully derive upper bounds for the remaining terms, $T_1, T_2, T_3, T_7$, and show that the infimum of $T_{4} + T_{5} + T_{6} - |T_{1}| - |T_2| - |T_{3}| - |T_{7}|$ on the set $\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q$ is strictly positive with high probability. 


%The main steps of the remaining proof are as follows. We first find positive lower bounds for both $T_{4}$ and $ T_{5}$. Note also that $T_{6}$ is non-negative. Next, we prove that given $\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q$, $T_{4} + T_{5} + T_{6}$ is a strict upper bound for the sum of absolute values of the remaining terms, i.e., $ |T_{1}| + |T_2| + |T_{3}| + |T_{7}|$. Thus, as $n \rightarrow \infty$, we have $\inf_{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q}\left\{g(\Omegabf, \Gammabf)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)\right\}>0$, as shown in (\ref{gdiffpositive}). This indicates (\ref{identity}) is satisfied as required. 

To find a lower bound for $T_4$, we need to find a lower bound (as a positive definite matrix in the Loewner order) for the term  $\Omegabf_{w}^{-1}\otimes \Omegabf_{w}^{-1}$ in the integrand. Note that 
{\small
\begin{eqnarray}
\Omegabf_{w}^{-1} \otimes \Omegabf_{w}^{-1}
&=&\left(\Omegabf_{0}+w \Deltabf_{1}\right)^{-1} \otimes\left(\Omegabf_{0}+w \Deltabf_{1}\right)^{-1} \nonumber\\
&=&(\Omegabf_{0}^{-1 / 2}\left(\Ibf+w \tilde{\Deltabf}_{1}\right)^{-1} \Omegabf_{0}^{-1 / 2}) \otimes (\Omegabf_{0}^{-1 / 2}\left(\Ibf+w \tilde{\Deltabf}_{1}\right)^{-1} \Omegabf_{0}^{-1 / 2}) \label{T4eq1}
\end{eqnarray}
}
\noindent
and 
{\small
\begin{equation} \label{T4eq2}
\nu_{\text{max}}\left(\Ibf+w \tilde{\Deltabf}_{1}\right)\leqslant \max_{\|\underline{x}\|_2=1} \underline{x}^{\top} \left(\Ibf+w \tilde{\Deltabf}_{1}\right) \underline{x}\leqslant \max_{\|\underline{x}\|_2=1}  (1+\underline{x}^{\top}\left(w \tilde{\Deltabf}_{1}\right) \underline{x})\leqslant 1+\left\|w \tilde{\Deltabf}_{1}\right\|_{F}. 
\end{equation}}
Since by Assumption 1 we have $\left\|\tilde{\Deltabf}_{1}\right\|_{F} \leqslant \sqrt{\alpha_{1}^{2} C^{2}+\beta_{1}^{2} C^{2}} \longrightarrow 0$,  for an arbitrarily fixed positive constant $\kappa$, $\left\|\tilde{\Deltabf}_{1}\right\|_{F} \leqslant \kappa$ and $\left\|\tilde{\Deltabf}_{2}\right\|_{F} \leqslant \kappa$ for large enough $n$. Then, by (\ref{T4eq1}) and (\ref{T4eq2}), for an arbitrary $\kappa > 0$,  $\Omegabf_{w}^{-1} \otimes \Omegabf_{w}^{-1} \succcurlyeq (1+\kappa)^{-2} \Omegabf_{0}^{-1} \otimes \Omegabf_{0}^{-1}$ in the Loewner ordering for large enough $n$. It follows that 
\begin{eqnarray}
 T_{4} &\geqslant& \frac{1}{p} \operatorname{vec}\left(\Deltabf_{1}\right)^{T}\left[\int_{0}^{1}\frac{1}{\left(1+\kappa\right)^{2}}\left(\Omegabf_{0}^{-1} \otimes \Omegabf_{0}^{-1}\right)(1-w) d w\right] \operatorname{vec}\left(\Deltabf_{1}\right) \nonumber\\
 &\geqslant& \frac{1}{p} \operatorname{vec}\left(\Deltabf_{1}\right)^{\top} \frac{1}{2\left(1+\kappa\right)^{2}}\left(\Omegabf_{0}^{-1} \otimes \Omegabf_{0}^{-1}\right) \operatorname{vec}\left(\Deltabf_{1}\right) \nonumber\\
  &=&\frac{1}{p} \operatorname{vec}\left(\Deltabf_{1}\right)^{\top} \frac{1}{2\left(1+\kappa\right)^{2}}\operatorname{vec}\left(\Omegabf_{0}^{-1}\Deltabf_{1}\Omegabf_{0}^{-1}\right) \nonumber\\
    &=&\frac{1}{2p\left(1+\kappa\right)^{2}}\operatorname{tr}\left(\Omegabf_{0}^{-1}\Deltabf_{1}\Omegabf_{0}^{-1}\Deltabf_{1}\right) \nonumber\\
&=&\frac{\left\|\tilde{\Deltabf}_{1}\right\|_{F}^{2}}{2 p\left(1+\kappa\right)^{2}} \nonumber\\
&=&\frac{1}{2 p\left(1+\kappa\right)^{2}}\left(C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}\right) \label{Term4lower}
\end{eqnarray}

\noindent
for large enough $n$. Similarly, we get a lower bound for $T_{5}$, namely 
\begin{equation} \label{Term5lower}
T_{5} \geqslant \frac{1}{2 q\left(1+\kappa\right)^{2}}\left(C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2}\right). 
\end{equation}

\noindent
for large enough $n$. {\em The choice of the constant $\kappa$ will be made in the final stages of the proof.}

Now that we have provided positive lower bounds for $T_{4}$ and $T_{5}$, we proceed to bound $|T_{1}|\& |T_{2}|$, $|T_{7}|$ and $|T_{3}|$ individually so that their sum is bounded by $T_{4}+T_{5}+T_{6}$. We begin by analyzing $|T_{1}|$ and $|T_{2}|$. Recall that $\Xibf=\Yibf \Gammabf_{0}^{1 / 2}$, then the first term in $T_{1}$ is
$$
(n p q)^{-1} \sum_{i=1}^{n} \operatorname{tr}\left(\Yibf \Gammabf_{0} \Yibf^{\top} \Deltabf_{1}\right)=(n p q)^{-1} \sum_{i=1}^{n} \operatorname{tr}\left(\Xibf \Xibf^{\top} \Deltabf_{1}\right)=p^{-1} \operatorname{tr}\left(\Qbf_{1} \Deltabf_{1}\right).
$$
 Thus,
\begin{eqnarray*}
 T_{1}&=&p^{-1} \operatorname{tr}\left\{\left(\Qbf_{1}-\Sigmabf_{0}\right) \Deltabf_{1}\right\}=p^{-1}\left\{\sum_{(i, j) \in S_{1}}+\sum_{(i, j) \in S_{1}^{c}}\right\}\left(Q_{1}-\Sigma_{0}\right)_{i j}\left(\Delta_{1}\right)_{i j}\\
 &=:&T_{11}+T_{12}. 
\end{eqnarray*}
In other words, $T_{1}$ is decomposed into two components,  $T_{11}$ and $T_{12}$, by separating $\operatorname{tr}\left\{\left(\Qbf_{1}-\Sigmabf_{0}\right) \Deltabf_{1}\right\}$ into sums over entry indices in $S_1$ and $S_1^c$ respectively. Similarly, $T_{2}$ can be decomposed into two components,  $T_{21}$ and $T_{22}$,  by separating $\operatorname{tr}\left\{\left(\Qbf_{2}-\Psibf_{0}\right) \Deltabf_{2}\right\}$ into sums over the entry indices in $S_2$ and $S_2^c$ respectively, 
\begin{eqnarray*}
T_{2}&=&  q^{-1} \operatorname{tr}\left\{\left(\Qbf_{2}-\Psibf_{0}\right) \Deltabf_{2}\right\}=q^{-1}\left\{\sum_{(i, j) \in S_{2}}+\sum_{(i, j) \in S_{2}^{c}}\right\}\left(Q_{2}-\Psi_{0}\right)_{i j}\left(\Delta_{2}\right)_{i j}\\
&=:&T_{21}+T_{22}. 
\end{eqnarray*}
We first consider to bound the terms $|T_{11}|$ and $|T_{21}|$ by appropriate portions of $T_{4}$ and $T_{5}$ respectively. In order to achieve this, we first show that $\left\|\Deltabf_{1}\right\|_{F}$ can be upper bounded by a constant multiple of $\left\|\tilde{\Deltabf}_{1}\right\|_{F}$. In particular, by properties of trace operator and the positive definite matrix $\Omegabf_{0}$, we have

\begin{eqnarray}
\notag
\left\|\Deltabf_{1}\right\|_{F}&=&\sqrt{\operatorname{tr}\left(\Deltabf_{1} \Deltabf_{1}\right)}\\
\notag
&=&\left\{\operatorname{tr}\left(\Omegabf_{0}^{1 / 2} \tilde{\Deltabf}_{1} \Omegabf_{0} \tilde{\Deltabf}_{1} \Omegabf_{0}^{1 / 2}\right)\right\}^{1 / 2} \\
\notag
& \leqslant& \left\{\nu_{p}\left(\Omegabf_{0}\right)\operatorname{tr}\left(\Omegabf_{0}^{1 / 2} \tilde{\Deltabf}_{1} \tilde{\Deltabf}_{1} \Omegabf_{0}^{1 / 2}\right)\right\}^{1 / 2}\\
\notag
&\leqslant&\left\{\nu_{p}^{2}\left(\Omegabf_{0}\right)\operatorname{tr}\left( \tilde{\Deltabf}_{1}\tilde{\Deltabf}_{1} \right)\right\}^{1 / 2} \\
\label{transdelta}
& \leqslant& \frac{1}{\tau_{1}}\left\|\tilde{\Deltabf}_{1}\right\|_{F},
\end{eqnarray}
where inequality (\ref{transdelta}) follows from Assumption 2.
Similarly, $\left\|\Deltabf_{2}\right\|_{F}$ can be upper bounded by a constant multiple of $\left\|\tilde{\Deltabf}_{2}\right\|_{F}$, namely 
\begin{eqnarray}
\label{transdelta2}
   \left\|\Deltabf_{2}\right\|_{F} \leqslant \frac{1}{\tau_{1}}\left\|\tilde{\Deltabf}_{2}\right\|_{F}.
\end{eqnarray}
By equations (\ref{Q1}),(\ref{Term4lower}),(\ref{transdelta}) and the Cauchy–Schwarz  inequality, we get for large enough $n$
\begin{eqnarray}
\notag
 \left|T_{11}\right| &\leqslant& p^{-1}\left(s_{1}+p\right)^{1 / 2}\left\|\Deltabf_{1}\right\|_{F} \max _{i, j}\left|\left(Q_{1}-\Sigma_{0}\right)_{i j}\right| \\
 \notag
& \leqslant& \frac{K}{p} \sqrt{\frac{\left(s_{1}+p\right) \log p}{n q}}\left\|\Deltabf_{1}\right\|_{F}\\
\notag
&\leqslant& \frac{K}{p \tau_{1}} \sqrt{\alpha_{1}^{2}+\beta_{1}^{2}} \sqrt{C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}} \\
\label{absT11}
& \leqslant& \frac{2 K\left(1+\kappa\right)^{2}}{\tau_{1} C} T_{4}.
\end{eqnarray}
Similarly,  by equations (\ref{Q2}),(\ref{Term5lower}),(\ref{transdelta2}) and the Cauchy–Schwarz  inequality, we get for large enough $n$, $|T_{21}|$ can be upper bounded by a constant multiple of $T_{5}$, namely
\begin{equation}
\label{absT21} \quad\left|T_{21}\right| \leqslant \frac{2 K\left(1+\kappa\right)^{2}}{\tau_{1} C} T_{5}.
\end{equation}
Next we bound $|T_{12}|$ and $|T_{22}|$ by an appropriate portion of $T_{6}$. Note that 
\begin{eqnarray*}
T_{6}=\sum_{(i, j) \in S_{1}^{c}} \lambda_{1}\left|\left(\Delta_{1}\right)_{i j}\right| +\sum_{(i, j) \in S_{2}^{c}} \lambda_{2}\left|\left(\Delta_{2}\right)_{i j}\right|=:T_{61}+T_{62}, 
\end{eqnarray*}
where $T_{61}:=\sum_{(i, j) \in S_{1}^{c}} \lambda_{1}\left|\left(\Delta_{1}\right)_{i j}\right|$ and $T_{62}:=\sum_{(i, j) \in S_{2}^{c}} \lambda_{2}\left|\left(\Delta_{2}\right)_{i j}\right|$. By inequality (\ref{Q1}), we have 

\begin{eqnarray*}
\left|T_{12}\right|&=&\left|\frac{1}{p} \sum_{(i, j) \in S_{1}^{c}}\left(Q_{1}-\Sigma_{0}\right)_{i j}\left(\Delta_{1}\right)_{i j}\right|\\
 &\leqslant& \frac{1}{p} \sum_{(i, j) \in S_{1}^{c}} K\sqrt{\frac{\log p}{n q}} \mid \left(\Delta_{1}\right)_{i j} \mid
\end{eqnarray*}
on $C_n$. Note by Assumption 4, we have $\left(\lambda_{1}-\frac{K}{p} \sqrt{\frac{\log p}{n q}}\right) \geqslant \frac{\lambda_{1}}{2}$ for large enough $n$. Thus,
\begin{equation}
\label{absT12}
    T_{61}-\left|T_{12}\right| \geqslant \sum_{(i, j) \in S_{1}^{c}}\left(\lambda_{1}-\frac{K}{p} \sqrt{\frac{\log p}{n q}}\right)\left|\left(\Delta_{1}\right)_{i j}\right| \geqslant \frac{\lambda_{1}}{2} \sum_{\left(i, j) \in S_{1}^{c}\right.}\left|\left(\Delta_{1}\right)_{i j}\right| = \frac{T_{61}}{2}
\end{equation}
for large enough $n$. We can similarly obtain

\begin{equation}
\label{absT22}
T_{62}-\left|T_{22}\right| \geqslant \frac{T_{62}}{2},
\end{equation}
for large enough $n$.
\noindent
Next, we proceed to bound $|T_{7}|$ with an appropriate portion of $T_{4}+T_{5}$. As with the term $T_{6}$, we divide $T_{7}$ into two parts as follows: 
\begin{eqnarray*}
    T_{7}&=&\sum_{(i, j) \in S_{1}, i \neq j} \left\{\lambda_{1}\left|\Omega_{ij}\right|-\lambda_{1}\left|\left(\Omega_{0}\right)_{i j}\right|\right\}+\sum_{(i, j) \in S_{2},i \neq j} \left\{\lambda_{2}\left|\Gamma_{ij}\right|-\lambda_{2}\left|\left(\Gamma_{0}\right)_{i j}\right|\right\}\\
    &=:&T_{71}+T_{72},
\end{eqnarray*}
where $T_{71}:=\sum_{(i, j) \in S_{1}, i \neq j} \left\{\lambda_{1}\left|\Omega_{ij}\right|-\lambda_{1}\left|\left(\Omega_{0}\right)_{i j}\right|\right\}$\\ and $T_{72}:=\sum_{(i, j) \in S_{2},i \neq j} \left\{\lambda_{2}\left|\Gamma_{ij}\right|-\lambda_{2}\left|\left(\Gamma_{0}\right)_{i j}\right|\right\}$. \\
Now note that for large enough $n$,
\begin{eqnarray}
\notag
\left|T_{71}\right| & \leqslant& \sum_{(i \neq j) \in S_{1}} \lambda_{1}\left|\Omega_{ij}-(\Omega_{0})_{i j}\right|=\lambda_{1} \sum_{(i \neq j) \in S_{1}} \mid(\Delta_{1})_{i j} \mid \\
\label{T71eq1}
& \leqslant& \lambda_{1} \sqrt{s_{1}} \sqrt{\sum_{(i, j) \in S_{1}}\left(\Delta_{1}\right)_{i j}^{2}}=\lambda_{1} \sqrt{s_{1}}\left\|\Deltabf_{1}\right\|_{F} \\
\label{T71eq2}
& \leqslant& \frac{\lambda_{1}}{\tau_{1}} \sqrt{s_{1}} \sqrt{C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}} \\
\label{T71eq3}
& \leqslant& B \frac{\sqrt{s_{1}}}{\tau_{1}p}\sqrt{1+\frac{p}{s_{1}+1}} \sqrt{\frac{\log p}{n q}} \sqrt{C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}} \\
\notag
& \leqslant&  \frac{B}{\tau_{1}p}\sqrt{s_{1}+p} \sqrt{\frac{\log p}{n q}} \sqrt{C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}}\\
\label{absT71}
&\leqslant&\frac{2B(1+\kappa)^{2}}{\tau_{1}C}T_{4},
\end{eqnarray}
where inequality (\ref{T71eq1}) follows from the Cauchy-Schwarz inequality, inequality (\ref{T71eq2}) follows from (\ref{transdelta}), inequality (\ref{T71eq3}) follows from Assumption 3 (since that assumption implies the existence a constant $B$ such that $\lambda_{1} \leqslant \frac{B}{p}\sqrt{1+\frac{p}{s_{1}+1}} \sqrt{\frac{\log p}{n q}}$ for large enough $n$), and the last inequality follows from the lower bound for the term $T_{4}$ in (\ref{Term4lower}).

Similarly, by the Cauchy-Schwarz inequality, inequality (\ref{transdelta2}),  Assumption 3 and the lower bound for the term $T_5$ in (\ref{Term5lower}), we obtain 
\begin{equation}
\label{absT72}
 \left|T_{72}\right| \leqslant \frac{2B(1+\kappa)^{2}}{\tau_{1}C}T_{5}
\end{equation}
for large enough $n$.


Hence, we have bounds for $|T_1|$, $|T_2|$ and $|T_7|$ in terms of relevant portions of the terms $T_4$, $T_5$ and $T_6$. Lastly, we try to bound $T_{3}$ by the remaining portions of these three positive terms. By utilizing the properties of the trace and vectorization operators, along with the mixed-product property of the Kronecker product, we decompose $T_{3}$ into two components for separate bounding: 
\begin{eqnarray}
T_{3}&=&\frac{1}{n p q} \sum_{i=1}^{n} \operatorname{tr}\left(\Yibf \Deltabf_{2} \Yibf^{\top} \Deltabf_{1}\right) \nonumber\\
& =&\frac{1}{n p q} \sum_{i=1}^{n} \operatorname{vec}\left(\Yibf^{\top}\right)^{\top} \operatorname{vec}\left(\Deltabf_{2} \Yibf^{\top} \Deltabf_{1}\right)  \nonumber\\
& =&\frac{1}{n p q} \sum_{i=1}^{n} \operatorname{vec}\left(\Yibf^{\top}\right)^{\top}\left(\Deltabf_{1} \otimes \Deltabf_{2}\right) \operatorname{vec}\left(\Yibf^{\top}\right) \nonumber\\
& =&\frac{1}{n p q} \sum_{i=1}^{n} \operatorname{tr}\left(\operatorname{vec}\left(\Yibf^{\top}\right)^{\top}\left(\Deltabf_{1} \otimes \Deltabf_{2}\right) \operatorname{vec}\left(\Yibf^{\top}\right)\right) \nonumber\\
& =&\frac{1}{n p q} \sum_{i=1}^{n} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right) \operatorname{vec}\left(\Yibf^{\top}\right) \operatorname{vec}\left(\Yibf^{\top}\right)^{\top}\right) \nonumber\\
& =&\frac{1}{p q} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\frac{1}{n} \sum_{i=1}^{n} \operatorname{vec}\left(\Yibf^{\top}\right) \operatorname{vec}\left(\Yibf^{\top}\right)^{\top}\right)\right) \nonumber\\
& =&\frac{1}{p q} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\Sbf-\Sigmabf_{0} \otimes \Psibf_{0}\right)\right)+\frac{1}{p q} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\Sigmabf_{0} \otimes \Psibf_{0}\right)\right) \nonumber\\
& =:&T_{31}+T_{32}, \label{t3:decomposition}
\end{eqnarray}
where {\small$T_{31}:=\frac{1}{p q} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\Sbf-\Sigmabf_{0} \otimes \Psibf_{0}\right)\right)$} and {\small$T_{32}:=\frac{1}{p q} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\Sigmabf_{0} \otimes \Psibf_{0}\right)\right)$}.
Note that 
\begin{eqnarray}
\notag
|\operatorname{tr}\left(\Deltabf_{1} \Sigmabf_{0}\right)|&=&|\operatorname{tr}\left(\Sigmabf_{0}^{1/2}\Deltabf_{1} \Sigmabf_{0}^{1/2}\right)|=|\operatorname{tr}(\tilde{\Deltabf}_1)| \\
\label{T31tr}
&\leqslant& \sqrt{p}\sqrt{\sum_{r=1}^p (\tilde{\Delta}_1)_{rr}^2}
=\sqrt{p} \beta_{1} C=C p \sqrt{\frac{\log p}{n q}}. 
\end{eqnarray}
Similarly, we have $\left|\operatorname{tr}\left(\Deltabf_{2} \Psibf_{0}\right)\right| \leqslant \sqrt{q} \beta_{2} C=C q \sqrt{\frac{\log q}{n p}}$. Combined with (\ref{Term4lower}), (\ref{Term5lower}) and the mixed-product property of the Kronecker product, for large enough $n$, we can bound $\left|T_{32}\right|$ as follows,
\begin{eqnarray}
\notag
\left|T_{32}\right| &=&\left|\frac{1}{pq} \operatorname{tr}\left(\Deltabf_{1} \Sigmabf_{0}\right) \operatorname{tr}\left(\Deltabf_{2} \Psibf_{0}\right)\right|\\
\notag
&\leqslant& C^{2} \sqrt{\frac{\log p}{n q}} \sqrt{\frac{\log q}{n p}} \leqslant C^{2}\left(\frac{1}{2} \frac{\log p}{n q}+\frac{1}{2} \frac{\log q}{n p}\right)\\
&=&C^{2}\left(\frac{\beta_{1}^{2}}{2 p}+\frac{\beta_{2}^{2}}{2 q}\right) 
\leqslant \frac{C^{2}}{2}\left(\frac{\alpha_{1}^{2}+\beta_{1}^{2}}{2 p}+\frac{\alpha_{2}^{2}+\beta_{2}^{2}}{2 q}\right)\\
\label{absT32}
& \leqslant &\frac{\left(1+\kappa\right)^{2}}{2}\left(T_{4}+T_{5}\right),
\end{eqnarray}
which indicates $|T_{32}|$ can also be upper bounded by some appropriate portion of $T_{4}+T_{5}$.

Before we analyze the last remaining term, $|T_{31}|$, we collect our bounds so far from (\ref{absT11}), (\ref{absT21}), (\ref{absT12}), (\ref{absT22}), (\ref{absT71}), (\ref{absT72}), (\ref{absT32}) to get the following inequality on the event $C_n$ for large enough $n$: 
\begin{eqnarray}
\label{woT31}
|T_{1}|+|T_{2}|+|T_{7}|+|T_{32}|
\leqslant \left(\frac{2 K}{\tau_{1} C}+\frac{2B}{\tau_{1} C}+\frac{1}{2}\right) (1+\kappa)^{2}(T_{4}+ T_{5})+ \frac{1}{2}T_{6}
\end{eqnarray}
Note that the constants $\kappa$ and $C$ are arbitrary. Hence, the coefficient $(\frac{2 K}{\tau_{1} C}+\frac{2B}{\tau_{1} C}+\frac{1}{2})(1+\kappa)^{2}$ for $T_4$ and $T_5$ can be adjusted to approach $1/2$ by selecting large enough $C$ and small enough $\kappa$. 

To analyze $|T_{31}|$, we first rewrite $T_{31}$ in an alternative form. In particular, note that 
{\footnotesize
\begin{eqnarray*}
T_{31}&=&\frac{1}{p q} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\Sbf-\Sigmabf_{0} \otimes \Psibf_{0}\right)\right)\\
& =&\frac{1}{p q} \sum_{j_{1},  j_{4}=1}^{p} \sum_{j_{2}, j_{3}=1}^{q}\left(\Delta_{2}\right)_{j_{2} j_{3}}\left(\Delta_{1}\right)_{j_{1} j_{4}}\left(\frac{1}{n} \sum_{i=1}^{n}\left(Y_{i}\right)_{j_{1} j_{2}}\left(Y_{i}\right)_{j_{4} j_{3}}-\left(\Sigma_{0}\right)_{j_{1} j_{4}}\left(\Psi_{0}\right)_{j_{2} j_{3}} \right). 
\end{eqnarray*}}
Here, $E_{P_0}\left[\left(Y_{i}\right)_{j_{1} j_{2}}\left(Y_{i}\right)_{j_{4} j_{3}}\right]=\left(\Sigma_{0}\right)_{j_{1} j_{4}}\left(\Psi_{0}\right)_{j_{2} j_{3}}$. 
By (\ref{Sk}), on $C_n$, we have
{\scriptsize
\begin{eqnarray} \label{T31U}
\left|T_{31}\right| 
&\leqslant& \frac{K}{p q} \sqrt{\frac{\log p q}{n}}\left(\sum_{j_{1}, j_{4}=1}^{p}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2}, j_{3}=1}^{q}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right) \nonumber\\
&=&A_{n}\left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_{j_{1}j_{4}}\right|\right)\left(\sum_{j_{2}=j_{3}}\left|\left(\Delta_{2}\right)_{j_{2}j_{3}}\right|\right) \nonumber\\
&+&A_{n}\left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} \neq j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)+A_{n}\left(\sum_{j_{1}\neq j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} = j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)
\nonumber\\
&+&A_{n}\left(\sum_{j_{1}\neq j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} \neq j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right) \nonumber\\
&=:& U_1+U_2+U_3,
\end{eqnarray}
}
where we set $A_{n}:=\frac{K}{p q} \sqrt{\frac{\log p q}{n}}$ for simplicity of notation, and 
{\scriptsize
\begin{eqnarray*}
U_1&:=&A_{n}\left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_{j_{1}j_{4}}\right|\right)\left(\sum_{j_{2}=j_{3}}\left|\left(\Delta_{2}\right)_{j_{2}j_{3}}\right|\right)\\
U_2&:=&A_{n}\left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} \neq j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)+A_{n}\left(\sum_{j_{1}\neq j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} = j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)\\
U_3&:=&A_{n}\left(\sum_{j_{1}\neq j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} \neq j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right).    
\end{eqnarray*}}
 We deal with these three parts separately. First, note that for large enough $n$
\begin{eqnarray}
\notag
U_1&=&A_{n}\left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_{j_{1}j_{4}}\right|\right)\left(\sum_{j_{2}=j_{3}}\left|\left(\Delta_{2}\right)_{j_{2}j_{3}}\right|\right)\\
\label{U1eq1}
& \leqslant& \frac{K}{p q} \sqrt{\frac{\log p q}{n}} \cdot \sqrt{p}\left\|\Delta_{1}\right\|_{F} \sqrt{q}\left\|\Delta_{2}\right\|_{F} \\
\label{U1eq2}
&\leqslant&\frac{K}{\tau_{1}^{2} p q} \sqrt{\frac{\log p q}{n}} \sqrt{p} \sqrt{C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}} \sqrt{q} \sqrt{C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2}} \\
\label{U1eq3}
& \leqslant& \frac{K}{\tau_{1}^{2} p q} \sqrt{\frac{\log p q}{n}}\left[\frac{q}{2}\left(C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}\right)+\frac{p}{2}\left(C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2}\right)\right] \\
\label{U1eq4}
& \leqslant&\frac{K(1+\kappa)^{2}}{\tau_{1}^{2}} \sqrt{\frac{\log p q}{n}}\left(T_{4}+T_{5}\right)
\end{eqnarray}
where inequality (\ref{U1eq1}) follows from the Cauchy-Schwarz inequality, inequality (\ref{U1eq2}) follows from (\ref{transdelta}) and (\ref{transdelta2}), inequality (\ref{U1eq3}) follows from the AM-GM inequality, and inequality (\ref{U1eq4}) follows from the lower bounds for the term $T_{4}$ and $T_{5}$ in (\ref{Term4lower}) and (\ref{Term5lower}).

Next, we proceed to bound $U_2$. In particular, note that the first term in $U_2$ satisfies 
\begin{eqnarray}
\notag
&&A_{n}\left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} \neq j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)\\
\notag
&=&A_{n} \left(\sum_{j_{1}=j_{4}}\left|\left(\Delta_{1}\right)_ {j_{1} j_{4}}\right|\right)\left(\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}}\left|\left(\Delta_{2}\right)_{j_{2}  j_{3}}\right|+\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}^c}\left|\left(\Delta_{2}\right)_{j_{2}  j_{3}}\right|\right) \\
\label{U21eq1}
& \leqslant& A_{n} \sqrt{p}\left\|\Deltabf_{1}\right\|_{F} \sqrt{s_{2}}\left\|\Deltabf_{2}\right\|_{F}+A_{n} \sqrt{p}\left\|\Deltabf_{1}\right\|_{F} \sum_{\left(j_{2} \neq j_{3}\right) \in S^{c}}\left|\Gamma_{j_{2} j_{3}}\right|,
\end{eqnarray}
where (\ref{U21eq1}) follows from the Cauchy-Schwarz inequality. The first term in (\ref{U21eq1}) can now be bounded as 
\begin{eqnarray}
\notag
&&A_{n} \sqrt{p}\left\|\Deltabf_{1}\right\|_{F} \sqrt{s_{2}}\left\|\Deltabf_{2}\right\|_{F}\\
\label{U21eq2}
& \leqslant& \frac{K}{\tau_{1}^{2} p q} \sqrt{\frac{\log p q}{n}} \sqrt{p} \sqrt{C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}} \sqrt{s_{2}} \sqrt{C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2}} \\
\label{U21eq3}
& \leqslant& \frac{K}{\tau_{1}^{2} } \sqrt{\frac{\log p q}{n}} \sqrt{\frac{s_{2}}{q}}\left[\frac{1}{2p}\left(C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}\right)+\frac{1}{2q}\left(C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2}\right)\right] \\
\label{U21eq4}
& \leqslant& \frac{K(1+\kappa)^{2}}{\tau_{1}^{2}} \sqrt{\frac{\log p q}{n}} \sqrt{\frac{s_{2}}{q}} \left(T_{4}+T_{5}\right) 
\end{eqnarray}
where inequality (\ref{U21eq2}) follows from (\ref{transdelta}) and (\ref{transdelta2}), inequality (\ref{U21eq3}) follows from the AM-GM inequality, and (\ref{U21eq4}) follows from the lower bounds for the term $T_{4}$ and $T_{5}$ in (\ref{Term4lower}) and (\ref{Term5lower}). Subsequently, for the second term in (\ref{U21eq1}), the inequality in (\ref{transdelta}) implies that 
{\small
\begin{equation} \label{U21eq6}
A_{n} \sqrt{p}\left\|\Deltabf_{1}\right\|_{F}\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}^{c}}\left|\Gamma_{j_{2} j_{3}}\right| 
\leqslant \frac{K C}{\tau_{1} p q} \sqrt{\frac{\log p q}{n}} \sqrt{p} \sqrt{\frac{\left(p+\zeta_{1}\right) \log p}{n q}}\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}^{c}}\left|\Gamma_{j_{2} j_{3}}\right|. 
\end{equation}}
Following a similar line of reasoning, the second term of $U_2$ can be bounded as 

{\footnotesize
\begin{eqnarray}
\notag
&&A_{n}\left(\sum_{j_{1}\neq j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} =j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)\\
\notag
&\leqslant&\frac{K(1+\kappa)^{2}}{\tau_{1}^{2}} \sqrt{\frac{\log p q}{n}} \sqrt{\frac{s_{1}}{p}} \left(T_{4}+T_{5}\right) +\frac{K C}{\tau_{1} p q} \sqrt{\frac{\log p q}{n}}\sqrt{q}  \sqrt{\frac{\left(q+\zeta_{2}\right) \log q}{np }}\sum_{\left(j_{1} \neq j_{4}\right) \in S_{1}^{c}}\left|\Omega_{j_{1} j_{4}}\right|. \\
\label{U2eq1}
\end{eqnarray}}
Finally, note that 
{\footnotesize
\begin{eqnarray}
\notag
U_3&=&A_{n}\left(\sum_{j_{1}\neq j_{4}}\left|\left(\Delta_{1}\right)_{j_{1} j_{4}}\right|\right)\left(\sum_{j_{2} \neq j_{3}}\left|\left(\Delta_{2}\right)_{j_{2} j_{3}}\right|\right)\\
\notag
&=&A_{n} \left(\sum_{j_{1} \neq j_{4} }\left|\left(\Delta_{1}\right)_{j_{1}  j_{4}}\right|\right)\left(\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}}\left|\left(\Delta_{2}\right)_{j_{2}  j_{3}}\right|+\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}^c}\left|\left(\Delta_{2}\right)_{j_{2}  j_{3}}\right|\right) \\
\label{U3eq1}
&\leqslant & A_{n}\left(p\left\|\Deltabf_{1}\right\|_{F} \sqrt{s_{2}}\left\|\Deltabf_{2}\right\|_{F}+p\left\|\Deltabf_{1}\right\|_{F} \sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}^{c}}\left|\Gamma_{j_{2} j_{3}}\right|\right) \\
\notag
& \leqslant& \frac{K(1+\kappa)^{2}}{\tau_{1}^{2}} \sqrt{\frac{\log p q}{n}} \sqrt{\frac{s_{2}p}{q}} \left(T_{4}+T_{5}\right)+\frac{K C}{\tau_{1}  q} \sqrt{\frac{\log p q}{n}} \sqrt{\frac{\left(p+\zeta_{1}\right) \log p}{n q}}\sum_{\left(j_{2} \neq j_{3}\right) \in S_{2}^{c}}\left|\Gamma_{j_{2} j_{3}}\right|\\
\label{U3eq2}
\end{eqnarray}}
where (\ref{U3eq1}) follows from the Cauchy-Schwarz inequality, and (\ref{U3eq2}) follows from (\ref{U21eq4}) and (\ref{U21eq6}) by multiplying $\sqrt{p}$ on both sides of those inequalities. Similarly, by decomposing the first factor of $U_{3}$ instead of the second factor and multiplying $\sqrt{q}$ on both sides of inequality (\ref{U2eq1}), we obtain
{\footnotesize
\begin{equation}
\label{U3eq3}
U_{3}\leqslant\frac{K(1+\kappa)^{2}}{\tau_{1}^{2}} \sqrt{\frac{\log p q}{n}} \sqrt{\frac{s_{1}q}{p}} \left(T_{4}+T_{5}\right) +\frac{K C}{\tau_{1} p } \sqrt{\frac{\log p q}{n}}  \sqrt{\frac{\left(q+\zeta_{2}\right) \log q}{np }}\sum_{\left(j_{1} \neq j_{4}\right) \in S_{1}^{c}}\left|\Omega_{j_{1} j_{4}}\right|. 
\end{equation}}


By combining all the bounds above for $U_1$, $U_2$ and $U_3$ along with Assumption 5 (using bound (\ref{U3eq3}) for $U_3$ if $ \frac{r_n\log p q}{n} \longrightarrow 0$ and using bound (\ref{U3eq2}) for $U_3$ if $ \frac{r_n'\log p q}{n} \longrightarrow 0$), it follows that there exists a sequence of constants 
$\{c_{2,n}\}_{n \geqslant 1}$ with $c_{2,n} \rightarrow 0$ as $n \rightarrow \infty$,
such that 
\begin{equation} \label{T31bound}
|T_{31}|\leqslant U_1+U_2+U_3 \leqslant c_{2,n} (T_4 + T_5 + T_6) \end{equation}

\noindent
on the event $C_n$ for large enough $n$. Combining this with the bound in (\ref{woT31}), we obtain
{\footnotesize
\begin{eqnarray*}
&&\inf _{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q}\left\{g(\Omegabf, \Gammabf)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)\right\}\\
&=&\inf _{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q}\left\{T_{1}+T_{2}+T_{3}+T_{4}+T_{5}+T_{6}+T_{7}\right\}\\
&\geqslant& \inf _{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q}\left\{\left(1-c_{2,n}-\left(\frac{2 K}{\tau_{1} C}+\frac{2B}{\tau_{1} C}+\frac{1}{2}\right) (1+\kappa)^{2}\right)(T_{4}+ T_{5})+ (\frac{1}{2}-c_{2,n})T_{6} \right\}
\end{eqnarray*}}
on event $C_n$ for large enough $n$.
\noindent
Now choose the constant $C = \frac{16 K}{\tau_{1}}+\frac{16B}{\tau_{1}}$ and the constant $\kappa = 0.01$. Since $c_{2,n} \longrightarrow 0$, it follows that $c_{2,n} \leqslant \frac{1}{4}$ eventually. Hence 
\begin{eqnarray}
\notag
&&\inf_{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q}\left\{g(\Omegabf, \Gammabf)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)\right\}\\
\notag
&\geqslant& \inf _{\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q} \left\{ 0.112 (T_4 + T_5) \right\}\\
\notag
&\geqslant& 0.112 \left( \frac{1}{2 p\left(1+\kappa\right)^{2}}\left(C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}\right)+\frac{1}{2 q\left(1+\kappa\right)^{2}}\left(C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2}\right)\right)\\
\label{gdiffpositive}
&>& 0
\end{eqnarray}
on $C_n$ for large enough $n$.
\noindent
Since $P_0 (C_n) \rightarrow 1 \mbox{ as } n \rightarrow \infty$, we have thereby proved (\ref{identity}), and have established the required 
result. 
\end{proof}



\section{Errors in previous consistency proofs}\label{Error}

\noindent
In this section, we carefully examine the errors in the previous 
consistency arguments for the Sparse SMGM estimator, and also highlight the relevant features/innovations in our argument from Section \ref{high:dim:consistency}. 


\subsection{The proof of \texorpdfstring{\cite[Theorem 1]{leng2012sparse}}{Theorem 1 in Leng (2012)}}


\noindent
We start by explaining the mistakes and lapses in the consistency proof of the SMGM estimator in \cite[Theorem 1]{leng2012sparse}. As in Section \ref{high:dim:consistency}, the authors in \cite{leng2012sparse} also pursue the high level strategy of showing that with high probability the infimum of the objective function $g$ over an appropriate set is strictly larger than $g(\Omegabf_0, \Gammabf_0)$. There is however, a key and consequential difference. While the argument in Section \ref{high:dim:consistency} considers infimum over the set $\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q$, the proof in \cite{leng2012sparse} considers infimum over the set $\Deltabf_{1} \in \mathcal{A}_p', \Deltabf_{2} \in \mathcal{B}_q'$, where 
{\small
\begin{eqnarray*}
\mathcal{A}_p' &:=& \left\{\mathbf{M}: \; \mathbf{M}=\alpha_{1}' \Rbf_{p}+\beta_{1} \Dbf_{p}, \; 
\Dbf_p \in \mathcal{D}_p, \; \Rbf_p \in \mathcal{R}_p \mbox{ and } \|\Dbf_p\|_F = \|\Rbf_p\|_F = C \right\}, \\
\mathcal{B}_q' &:=& \left\{\mathbf{M}: \; \mathbf{M}=\alpha_{2}' \Rbf_{q}+\beta_{2} \Dbf_{q}, \; 
\Dbf_q \in \mathcal{D}_q, \; \Rbf_q \in \mathcal{R}_q \mbox{ and } \|\Dbf_q\|_F = \|\Rbf_q\|_F = C \right\}. 
\end{eqnarray*}
and
\begin{eqnarray*}
\alpha_{1}'=\left\{s_{1} \log p /(n q)\right\}^{1 / 2},\alpha_{2}'=\left\{s_{2} \log q /(n p)\right\}^{1 / 2}.
\end{eqnarray*}}
As in the proof of Theorem \ref{Fnormcr}, the difference $g\left(\Omegabf_{0}+\Deltabf_{1}, \Gammabf_{0}+\Deltabf_{2}\right)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)$ is expressed as the sum $T_1 + T_2 + \cdots + T_7$, and the strategy is to use the non-negative terms $T_4, T_5$ and $T_6$ to control/bound the other terms. The errors in the proof of \cite[Theorem 1]{leng2012sparse} arise chiefly in the analysis/bounding of the term $T_3$. Similar to (\ref{t3:decomposition}), the term $T_3$ is broken up as a sum of two parts $T_{31}$ and $T_{32}$ in the proof of \cite[Theorem 1]{leng2012sparse}, and these terms are bounded using separate arguments. We examine both these arguments below. 

\subsubsection{Bound for \texorpdfstring{$T_{32}$}{T32}} \label{T32}

\noindent
The authors in \cite{leng2012sparse} employ 
the following strategy to bound the term $|T_{32}|$. First, the following lower bounds are established for $T_4$ and $T_5$. 
\begin{eqnarray}
\label{an}
&&T_{4} \geqslant(2 p)^{-1}\left\{\tau_{1}^{-1}+a_n\right\}^{-2}\left(C^{2} {\alpha_1'}^{2}+C^{2} \beta_{1}^{2}\right)\\
\label{bn}
&&T_{5} \geqslant(2 q)^{-1}\left\{\tau_{1}^{-1}+b_n\right\}^{-2}\left(C^{2} {\alpha_2'}^{2}+C^{2} \beta_{2}^{2}\right),
\end{eqnarray}
where $a_n$ and $b_n$ are constants which converge to $0$ as $n \rightarrow \infty$. Then, an upper bound for $T_{32}$ in terms of $T_4$ and $T_5$ is derived by noting that for $\Deltabf_{1} \in \mathcal{A}_p'$ and $\Deltabf_{2} \in \mathcal{B}_q'$, 
\begin{eqnarray}
\notag
   |T_{32}| &\leqslant &1/\sqrt{pq}\tau_1^{-2} (C^{2} {\alpha_1'}^{2}+C^{2} \beta_{1}^{2})(C^{2} {\alpha_2'}^{2}+C^{2} \beta_{2}^{2}) \\
   \notag
   &\leqslant & (2p)^{-1}\tau_1^{-2} (C^{2} {\alpha_1'}^{2}+C^{2} \beta_{1}^{2})+(2q)^{-1}\tau_1^{-2}(C^{2} {\alpha_2'}^{2}+C^{2} \beta_{2}^{2}) \\
%    \label{tau_1^2}
%    &\leqslant & (2p)^{-1}\tau_1^{2} (C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2})+(2q)^{-1}\tau_1^{2}(C^{2} \alpha_{2}^{2}+C^{2} \beta_{2}^{2})\\
    \label{tau_1^2}
    &\leqslant& T_4 + T_5
\end{eqnarray}
with probability converging to 1 as $n \rightarrow \infty$.
\noindent
This line of attack has the following problems. 
\begin{itemize}
    \item The inequality (\ref{tau_1^2}) is erroneous for two reasons. First, the constants $a_n$ and $b_n$ are in the lower bounds (\ref{an}) and (\ref{bn}) for $T_4, T_5$ are ignored. While these constants vanish in the limit, they cannot be ignored in the above bounds which need to hold {\it for every large enough $n$}. Second, the $\tau_1$ related terms in the lower bounds (\ref{an}) and (\ref{bn}) are close to $\tau_1^2$, whereas the relevant $\tau_1$ related terms in the  upper bound for $|T_{32}|$ are $\tau_1^{-2}$. By definition, $\tau_1 \leqslant \tau_1^{-1}$, where a strict inequality $\tau_1 < \tau_1^{-1}$ holds unless $\Sigmabf_0 = {\bf I}_p$ and $\Psibf_0 = {\bf I}_q$. Hence, even if $a_n$ and $b_n$ are ignored, the last inequality in (\ref{tau_1^2}) holds in the opposite direction. 
    \item Even if (\ref{tau_1^2}) was accurate, the entirety of the terms $T_4$ and $T_5$ have now been used to control $T_{32}$, leaving no portions of these terms to control other terms like $T_{31}$, $T_1$, $T_2$ and $T_7$. 
    \item A strict inequality is needed in (\ref{tau_1^2}) instead of a less than or equal to condition. 
\end{itemize}

\noindent
%?%
We now discuss the key elements of our argument (Section \ref{high:dim:consistency}) that enable us to avoid the errors delineated above. A salient innovation in our proof is the use of the neighborhood $\tilde{\Deltabf}_{1} \in \mathcal{A}_p, \tilde{\Deltabf}_{2} \in \mathcal{B}_q$ instead of $\Deltabf_{1} \in \mathcal{A}_p', \Deltabf_{2} \in \mathcal{B}_q'$ to search for the local minimizer (recall that $\tilde{\Deltabf}_{1}=\Omegabf_{0}^{-1 / 2} \Deltabf_{1} \Omegabf_{0}^{-1 / 2}, \tilde{\Deltabf}_{2}=\Gammabf_{0}^{-1 / 2} \Deltabf_{2} \Gammabf_{0}^{-1 / 2}$). This approach provides a much tighter inequality for upper bounding $|T_{32}|$ using a significantly smaller portion of $T_{4}$ \& $T_{5}$, and thereby helps prevent the relevant errors.

In particular, note that $T_{32}=\frac{1}{pq} \operatorname{tr}\left(\Deltabf_{1} \Sigmabf_{0}\right) \operatorname{tr}\left(\Deltabf_{2} \Psibf_{0}\right)$. If as in \cite{leng2012sparse}, one uses the constraint $\Deltabf_{1} \in \mathcal{A}_p'$, the 
tightest upper bound for $\operatorname{tr}\left(\Deltabf_{1} \Sigmabf_{0}\right)$ is obtained by  $$|\operatorname{tr}\left(\Deltabf_{1}\Sigmabf_{0}\right)|\leqslant \tau_1^{-1}p^{1/2}\|\Deltabf_1\|_F\leqslant 
 \tau_1^{-1}p^{1/2}(C^2{\alpha_1'}^{2}+C^2\beta_1^2)^{1/2}.$$
 The introduction of the constant $\tau_1^{-1}$ is unavoidable in the upper bound as $\Deltabf_1$ and $\Sigmabf_0$ need to be controlled separately in this setup. On the other hand, by working with the constraint $\tilde{\Deltabf}_1 \in \mathcal{A}_p$, we are able to show $$|\operatorname{tr}\left(\Deltabf_{1}\Sigmabf_{0}\right)|=|\operatorname{tr}(\tilde{\Deltabf}_1)|=p^{1/2}C \beta_1,$$ 
 which is an exact equality and avoids introducing the factor $\tau_1^{-1}$ in the bound. A similar analysis holds for the bounds for the term $\operatorname{tr}\left(\Deltabf_{2} \Psibf_{0}\right)$. 
 At the same time, authors in \cite{leng2012sparse}, under the constraint 
 $\Deltabf_1 \in \mathcal{A}_p$, obtain a lower bound for $T_4$ as 
 \begin{eqnarray}
 \notag
 T_{4} & \geqslant& p^{-1}\left\|\operatorname{vec}\left(\boldsymbol{\Delta}_{1}\right)\right\|_{2}^{2} \int_{0}^{1}(1-w) \min _{0<w<1} \nu_{1}\left(\boldsymbol{\Omega}_{w}^{-1} \otimes \boldsymbol{\Omega}_{w}^{-1}\right) d w \\ 
 \notag
 & \geqslant& (2 p)^{-1}\left\|\operatorname{vec}\left(\boldsymbol{\Delta}_{1}\right)\right\|_{2}^{2} \min _{0<w<1} \nu_{p}^{-2}\left(\boldsymbol{\Omega}_{w} \right)\\
 \notag
 & \geqslant& (2 p)^{-1}\left\|\operatorname{vec}\left(\boldsymbol{\Delta}_{1}\right)\right\|_{2}^{2} (\|\Omegabf_0\|+\|\Deltabf_1\|)^{-2}\\
 \label{T42terms}
&\geqslant&(2 p)^{-1}\left(C^{2} {\alpha_1'}^{2}+C^{2} \beta_{1}^{2}\right)\left\{\tau_{1}^{-1}+a_n\right\}^{-2}.  
 \end{eqnarray}
 Here, for a symmetric matrix $\Abf$, we use $\|\Abf\|$ to denote the spectral norm of $\Abf$, and $a_n$ is $o(1)$. Again, the introduction of the term $\tau_1^{-1}$ is unavoidable since the terms 
$\left\|\operatorname{vec}\left(\boldsymbol{\Delta}_{1}\right)\right\|_{2}^{2}$ and $ (\|\Omegabf_0\|+\|\Deltabf_1\|)^{-2}$ need to be controlled separately in this setup. On the other hand, in our setup, with $\tilde{\Deltabf}_{1}\in \mathcal{A}_p$, first, as in (\ref{T4eq1}), one can express 
 \begin{equation}
\Omegabf_{w}^{-1} \otimes \Omegabf_{w}^{-1}
=(\Omegabf_{0}^{-1 / 2}\left(\Ibf+w \tilde{\Deltabf}_{1}\right)^{-1} \Omegabf_{0}^{-1 / 2}) \otimes (\Omegabf_{0}^{-1 / 2}\left(\Ibf+w \tilde{\Deltabf}_{1}\right)^{-1} \Omegabf_{0}^{-1 / 2}). 
 \end{equation}

\noindent
This allows us to use the constraint on $\tilde{\Deltabf}_1$ to show that for an arbitrary $\kappa > 0$, $\Omegabf_{w}^{-1} \otimes \Omegabf_{w}^{-1} \succcurlyeq (1+\kappa)^{-2} \Omegabf_{0}^{-1} \otimes \Omegabf_{0}^{-1}$ in the Loewner ordering for large enough $n$.
Now, using 
\begin{equation}
 \operatorname{vec}\left(\Deltabf_{1}\right)^{\top} \left(\Omegabf_{0}^{-1} \otimes \Omegabf_{0}^{-1}\right) \operatorname{vec}\left(\Deltabf_{1}\right)=\left\|\tilde{\Deltabf}_{1}\right\|_{F}^{2}=C^2\alpha_{1}^2+C^2\beta_1^2   
\end{equation}
we are able to establish the  lower bound 
\begin{equation}
 T_4 \geqslant \frac{\left\|\tilde{\Deltabf}_{1}\right\|_{F}^{2}}{2 p\left(1+\kappa\right)^{2}}=\frac{1}{2 p\left(1+\kappa\right)^{2}}\left(C^{2} \alpha_{1}^{2}+C^{2} \beta_{1}^{2}\right) 
\end{equation}
for large enough $n$, which avoids introducing terms related to $\tau_1$. A similar comparative 
analysis holds for $T_5$ lower bound. Leveraging these lower and upper bounds, we establish a tighter inequality in (\ref{absT32}) for large enough $n$, namely,
$$
|T_{32}|\leqslant \frac{\left(1+\kappa\right)^{2}}{2}\left(T_{4}+T_{5}\right).
$$
This leaves enough portion of $T_{4}+T_{5}$ to be used for bounding the remaining terms. 

\subsubsection{Bound for \texorpdfstring{$T_{31}$}{T31}} \label{T31}


\noindent
The authors in \cite{leng2012sparse} express $T_{31}$ as 
$$
T_{31} = (pq)^{-1}\operatorname{tr}\left(\Sigmabf_{0} \Deltabf_{1}\right) \operatorname{tr}\left(\Psibf_{0} \Deltabf_{2}\right)u_n. 
$$

\noindent
Note that 
$$
u_n = \frac{1}{\operatorname{tr}\left(\Sigmabf_{0} \Deltabf_{1}\right) \operatorname{tr}\left(\Psibf_{0} \Deltabf_{2}\right)} \operatorname{tr}\left(\left(\Deltabf_{1} \otimes \Deltabf_{2}\right)\left(\Sbf-\Sigmabf_{0} \otimes \Psibf_{0}\right)\right)
$$

\noindent
depends on $\Deltabf_1$ and $\Deltabf_2$. Here $\Sbf=\left(\frac{1}{n} \sum_{i=1}^{n} \operatorname{vec}\left(\Yibf^{\top}\right) \operatorname{vec}\left(\Yibf^{\top}\right)^{\top}\right)$. The authors in \cite{leng2012sparse} observe correctly that {\it for each fixed} $\Deltabf_{1} \in \mathcal{A}_p'$ and $\Deltabf_{2} \in \mathcal{B}_q'$, the law of large numbers implies that 
\begin{equation} \label{Leng:Tang:T31:conclusion}
u_n = u_n (\Deltabf_1, \Deltabf_2) \stackrel{P_0}{\rightarrow} 0. 
\end{equation}

\noindent
However, no further analysis of the term $T_{31}$ is provided. This is a critical mistake in the proof. Even if we ignore that the entirety of $T_4+T_4$ has been used to bound $|T_{32}|$, what needs to be shown is that 
{\small
\begin{eqnarray} \label{Leng:Tang:T31:need}
& & \inf_{\Deltabf_{1} \in \mathcal{A}_p', \Deltabf_{2} \in \mathcal{B}_q'} 
\{{c}_{1,n} (T_4 + T_5) - |T_{31}|\} \nonumber\\
&=& \inf_{\Deltabf_{1} \in \mathcal{A}_p', \Deltabf_{2} \in \mathcal{B}_q'} 
\{c_{1,n} (T_4 + T_5) - |(pq)^{-1}\operatorname{tr}\left(\Sigmabf_{0} \Deltabf_{1}\right) \operatorname{tr}\left(\Psibf_{0} \Deltabf_{2}\right)u_n|\} > 0 
\end{eqnarray}
}
\noindent
with $P_0$-probability converging to $1$, where $c_{1,n}$ is an appropriate sequence of constants. This can only be achieved through a {\it uniform high-probability bound} on $u_n (\Deltabf_1, \Deltabf_2)$ over the set $\Deltabf_{1} \in \mathcal{A}_p'$ and $\Deltabf_{2} \in \mathcal{B}_q'$ is needed. 

The regularity assumptions in \cite{leng2012sparse} 
(essentially equivalent to Assumptions 1-4 in this paper) are not sufficient to provide such a uniform bound, and additional assumptions are needed. Assumption 5 along with the detailed analysis in our proof (leading to the uniform bounds in equation (\ref{woT31}) and (\ref{T31bound}))  are needed to establish the required result.

\subsection{The proof of \texorpdfstring{\cite[Theorem 3]{Yin:Li:2012}}{The proof of Theorem 3}} 

\noindent
Yin and Li \cite{Yin:Li:2012} also establish high-dimensional consistency of the SMGM-lasso estimator in Theorem 3 of that paper. Similar to the proof of \cite[Theorem 1]{leng2012sparse}, their argument aims to show that the infimum of $g$ over a relevant set is strictly larger than $g(\Omegabf_0, \Gammabf_0)$ with high probability. To achieve this, again 
the difference $g\left(\Omegabf_{0}+\Deltabf_{1}, \Gammabf_{0}+\Deltabf_{2}\right)-g\left(\Omegabf_{0}, \Gammabf_{0}\right)$ is broken up as the sum of various terms, and the goal is to leverage the positive terms to bound the others. A close examination of the proof again reveals issues with the bounding of the terms $T_{32}$ and $T_{31}$ (refered to as $K_{5}$ and $K_{6}$ respectively in \cite{Yin:Li:2012}). 

\subsubsection{Bound for \texorpdfstring{$T_{32}$}{T32}} 

\noindent
For the terms $T_4$ and $T_5$ (refered to as $K_{1}$ and $K_{2}$ respectively in \cite{Yin:Li:2012}), the following lower bounds are produced: 
\begin{equation}\label{YinT4}
T_4 \geqslant \frac{q}{2}\text{tr}(\Sigmabf_0 \Deltabf_1^{\top} \Sigmabf_0 \Deltabf_1)(1+\tilde{a}_n)
\end{equation}
\noindent
and 
\begin{equation}\label{YinT5}
T_5 \geqslant \frac{p}{2}\text{tr}(\Psibf_0 \Deltabf_2^{\top} \Psibf_0 \Deltabf_2)(1+\tilde{b}_n)
\end{equation}
where $\tilde{a}_n$ and $\tilde{b}_n$ are $o(1)$. On the other hand, the upper bound obtained for $T_{32}$ is given by 
\begin{equation}\label{YinT32}
 |T_{32}| \leqslant \frac{q}{2}\text{tr}(\Sigmabf_0 \Deltabf_1^{\top} \Sigmabf_0 \Deltabf_1)+\frac{p}{2}\text{tr}(\Psibf_0 \Deltabf_2^{\top} \Psibf_0 \Deltabf_2).
\end{equation}
Combining with (\ref{YinT4}) and (\ref{YinT5}) they conclude that $|T_{32}|$ is dominated by $T_{4}+T_{5}$ with a large probability.


This succession of arguments has the following problems:
\begin{itemize}
\item There is no guarantee that the $\tilde{a}_n$ and $\tilde{b}_n$ are positive and it is possible that the upper bound for $|T_{32}|$ is smaller than the lower bound of $T_{4}+T_{5}$. While these constants vanish in the limit, they cannot be ignored in the above bounds which need to hold {\it for every large enough $n$}. 

\item Even if $\tilde{a}_n$ and $\tilde{b}_n$ were positive, almost all of $T_4+T_5$ would be used in constraining $|T_{32}|$, leaving only $\frac{q}{2}\text{tr}(\Sigmabf_0 \Deltabf_1^{\top} \Sigmabf_0 \Deltabf_1)\tilde{a}_n+\frac{p}{2}\text{tr}(\Psibf_0 \Deltabf_2^{\top} \Psibf_0 \Deltabf_2)\tilde{b}_n \leqslant
\tilde{a}_n T_4+\tilde{b}_n T_5$ to constrain/bound the remaining terms. Following the lines of logic in \cite{Yin:Li:2012}, aside from bounding $|T_{32}|$, non-vanishing factors of $ (T_4+T_5)$ are required to bound the other terms - in particular $|T_1+T_2+T_{31}| < \tilde{c}_{1,n}(T_4+T_5+T_6)$ and $|T_7| < \tilde{c}_{2,n}(T_4+T_5)$, where $\tilde{c}_{1,n}$ and $\tilde{c}_{2,n}$ are $O(1)$. However, $\tilde{a}_n,\tilde{b}_n$ are both $o(1)$, and are inadequate for the desired upper bounds for the terms $|T_1+T_2+T_{31}|$ and $|T_7|$. 
\end{itemize}

\noindent
We refer the reader to Section \ref{T32} for a detailed description of how we we avoid these issues in our proof using sets based on the quantities $\tilde{\Deltabf}_1$ and $\tilde{\Deltabf}_2$. 

\subsubsection{Bound for \texorpdfstring{$T_{31}$}{T31}} 

The argument in the proof of \cite[Theorem 3]{Yin:Li:2012} to upper bound 
$T_{31}$ avoids the error in the proof of \cite[Theorem 1]{leng2012sparse}, and provides a uniform high-probability bound for the term $u_n (\Deltabf_1, \Deltabf_2)$ (see Section \ref{T31}) over a relevant set. However, the analysis is not tight enough, using much stronger assumptions and leading to slower/looser convergence rates than necessary. 

We first look at the assumptions in \cite{Yin:Li:2012} concerning the joint behavior of $n, p, q, s_1, s_2$. The authors in \cite{Yin:Li:2012} require that for some $k,l>1$, 
 $$q\left(p+s_{1}\right) (\log pq)^k /n= O(1), \; \; \; p\left(q+s_{2}\right) (\log pq)^l /n =O(1),$$

 \noindent
 which in particular implies (assuming $p \rightarrow \infty$ or $q \rightarrow \infty$) that 
 \begin{equation} \label{yin:li:comparison}
 q\left(p+s_{1}\right) \log pq /n\longrightarrow 0, \; \; \; p\left(q+s_{2}\right) \log pq /n \longrightarrow 0. 
 \end{equation}

\noindent
On the contrary, in Assumption 1 of this paper, we require
 $$\left(p+s_{1}\right) \log p /(n q) \longrightarrow 0, \; \; \; \left(q+s_{2}\right) \log q /(n p) \longrightarrow 0, 
 $$
 while in Assumption 5 (not including terms with $\lambda_1$ and $\lambda_2$), we require 
 $$\max \left(1, \frac{s_{2}}{q}, \frac{s_{1} q}{p}\right) \log (pq)/n 
\longrightarrow 0 \text{ or } \max \left(1, \frac{s_{1}}{p}, \frac{s_{2} p}{q}\right) \log(pq)/n \longrightarrow 0.$$
It can be easily seen that the constraint in (\ref{yin:li:comparison}) is stronger than both the constraints above. Note the assumptions involving $\lambda_1$ and $\lambda_2$ in this paper and for \cite[Theorem 3]{Yin:Li:2012} lead to different acceptable ranges for these two quantities, and are therefore not comparable. 

Finally, the Frobenius norm convergence rates established in \cite[Theorem 3]{Yin:Li:2012} are 
$$
\left\|\hat{\Omegabf}-\Omegabf_0\right\|_{\mathrm{F}}^2=O_{P_0}\left\{q(p+s_1)(\log p+\log q) /n \right\}
$$
and
$$
\left\|\hat{\Gammabf}-\Gammabf_0\right\|_{\mathrm{F}}^2=O_{P_0}\left\{p(q+s_2)(\log p+\log q) /n \right\}. 
$$

\noindent
These rates are significantly slower than the convergence rates 
$$
\left\|\hat{\Omegabf}-\Omegabf_0\right\|_{\mathrm{F}}^2=O_{P_0}\left\{\left(p+s_1\right) \log p /(n q)\right\}
$$
and
$$
\left\|\hat{\Gammabf}-\Gammabf_0\right\|_{\mathrm{F}}^2=O_{P_0}\left\{\left(q+s_2\right) \log q /(n p)\right\} .
$$

\noindent
established in Theorem \ref{Fnormcr}. 



\section{High-dimensional convergence rates for heuristic estimator} 
\label{convergence:rate:heuristic:estimator}
As discussed in the introduction, in the current matrix-variate context, low-dimensional structures may not always be necessary for achieving consistency in high-dimensional settings. We rigorously establish this by studying the asymptotic properties of the heuristic estimators of $\Sigmabf$ and $\Psibf$ developed in \cite{SVV:2008}. The authors in \cite{SVV:2008} consider the special case when $\Psibf_{jj} = 1$ for every $1 \leqslant j \leqslant q$. In this case, each vector in the collection of $nq$ columns gathered from all the data matrices has a $p$-variate normal distribution with mean ${\underline 0}$ and covariance matrix $\Sigmabf$. While these $nq$ vectors are not all independent, \cite{SVV:2008} argue that their sample covariance matrix, given by 
\begin{equation} \label{hest}
\hat{\Sigmabf}_H := \frac{1}{nq} \sum_{i=1}^n \Yibf \Yibf^{\top}, 
\end{equation}
should be a reasonable heuristic estimator for $\Sigmabf$. To support this, they demonstrate that $\hat{\Sigmabf}_H$ is an unbiased and consistent estimator of 
$\Sigmabf$ in the classical asymptotic setting where $n \rightarrow \infty$ and $p, q$ stay fixed. The estimator $\hat{\Sigmabf}_H$ is then used to construct a similar sample covariance estimator for $\Psibf$, which is shown by \cite{SVV:2008} to be consistent for $\Psibf$. We consider a similar but slightly different heuristic estimator of $\Psibf$, given by 
\begin{equation} \label{psiest}
\hat{\Psibf}_H := \frac{1}{n \mbox{tr}(\hat{\Sigmabf}_H)} \sum_{i=1}^n 
\Yibf^{\top} \Yibf. 
\end{equation}

\noindent
We will show that under an appropriate identifiability constraint, $\hat{\Sigmabf}_H$ and $\hat{\Psibf}_H$ serve as effective estimators for $\Sigmabf$ and $\Psibf$ {\it even when the constraint $\Psibf_{jj} = 1$ for every $1 \leqslant j \leqslant q$ is removed}. We now establish their spectral norm consistency rates in a high-dimensional asymptotic regime where $p$ and/or $q$ are allowed to grow with $n$. 

We first specify the true data generating model. Under this model, for each $n$, the random matrices ${\bf Y}_{1}, {\bf Y}_{2}, \cdots, {\bf Y}_{n}$ are independent and identically distributed with a matrix normal distribution, which has mean $\mathbf{0}$, row covariance matrix $\mathbf{\Sigmabf}_0$ and column covariance matrix $\mathbf{\Psibf}_0$.
Let $\Omegabf_{0}=\Sigmabf_{0}^{-1}$ and $\Gammabf_{0}=\Psibf_{0}^{-1}$ respectively denote the row and column precision matrices. Following \cite{Theobald:Wuttke:2006}, we use the identifiability constraint $\operatorname{tr}(\Psibf_0) = q$. Note that, as in Section \ref{high:dim:consistency}, since $p$ and $q$ are allowed to change with the sample size $n$, the data matrices and the covariance/precision matrices all depend on $n$. However, we suppress their dependence on $n$ for simplicity of notation.

In order to establish our asymptotic results, we need the following mild regularity assumptions. The 
statement of each assumption below is followed by a interpretation/discussion of that assumption.

\noindent
\textit{Assumption} H1. There exists constant $\tau_{1}>0$ such that for all $n \geqslant 1$,


\begin{eqnarray*}
0<\tau_{1}<\nu_{1}\left(\Sigmabf_{0}\right) &\leqslant& \nu_{p}\left(\Sigmabf_{0}\right)<1 / \tau_{1}<\infty, \\
0<\tau_{1}<\nu_{1}\left(\Psibf_{0}\right) &\leqslant& \nu_{q}\left(\Psibf_{0}\right)<1 / \tau_{1}<\infty,
\end{eqnarray*}


\noindent where $\nu_{1}(\Abf) \leqslant \nu_{2}(\Abf) \leqslant \cdots \leqslant \nu_{m}(\Abf)$ are the eigenvalues of an $m$-dim symmetric $\Abf$.
 This standard assumption is identical to Assumption 2 in Section \ref{high:dim:consistency}, and requires the eigenvalues of the row and column covariance matrices $\Sigmabf_{0}$ and $\Psibf_{0}$ to be uniformly (in $n$) bounded away from 0 and $\infty$. 

\medskip

\noindent
\textit{Assumption} H2. $ \frac{\max (p,\log n)}{q}=o(n)$ and $ \frac{\max (q,\log n)}{p}=o(n)$. 
\noindent
This assumption controls the joint behavior/growth of $n, p, q$. The analogous assumption in Section \ref{high:dim:consistency} is Assumption 1. Assumption 1 is stronger than Assumption H2, which is seemingly counter-intuitive. One would think that imposing a low-dimensional sparse structure on $\Omegabf_0$ and $\Gammabf_0$ would lead to weaker requirements/assumptions for establishing consistency in Section \ref{high:dim:consistency}. However, we would like to point out that Assumption H2 will be used to obtain a {\it spectral norm} convergence rate for the heuristic estimator, whereas Assumption 1 in Section \ref{high:dim:consistency} is used to obtain a Frobenius norm convergence rate for the SMGM estimator. If one wants to establish Frobenius norm convergence rates for the heuristic estimator, the required Assumption H2 would need to be strengthened to 
$$
\frac{\max (p^2,\log n)}{q}=o(n) \mbox{ and } \frac{\max (q^2,\log n)}{p}=o(n), 
$$

\noindent
a stronger assumption than Assumption 1, as expected. 

We now state and prove our high-dimensional consistency result for the heuristic estimator $(\hat{\Sigmabf}_H, \hat{\Psibf}_H)$. Recall that for a symmetric matrix $\Abf$, we use $\|\Abf\|$ to denote the spectral norm of $\Abf$.
\begin{theorem} \label{HEmain}(Spectral norm convergence rates for heuristic estimators) Under Assumptions H1-H2, as $n\rightarrow\infty$, for arbitrarily chosen constant $\tilde{C}_{0}$, heuristic covariance estimators $\hat{\Sigmabf}_H$ and $\hat{\Psibf}_{H}$ proposed in (\ref{hest}) and (\ref{psiest}) 
satisfy 
\begin{eqnarray*}
\|\hat{\Sigmabf}_H-\Sigmabf_0\| &=& O_{P_0} \left( \sqrt{\frac{\max (p,\log n)}{nq}} \right) \mbox{ and }\\
\|\hat{\Psibf}_{H}-\Psibf_{0}\| &=& O_{P_0} \left( 
\sqrt{\max\left(\frac{\max(p,\log n)}{nq},\frac{\max(q,\log n)}{np}\right)} \right). 
\end{eqnarray*}

\noindent
The corresponding precision matrix estimators $\hat{\Omegabf}_H = \hat{\Sigmabf}_H^{-1}$ and $\hat{\Gammabf}_H = \hat{\Psibf}_H^{-1}$ also satisfy 
 \begin{eqnarray*}
\|\hat{\Omegabf}_H-\Omegabf_0\| &=& O_{P_0} \left( \sqrt{\frac{\max (p,\log n)}{nq}} \right) \mbox{ and } \\
\|\hat{\Gammabf}_{H}-\Gammabf_{0}\| &=& O_{P_0} \left( 
\sqrt{\max\left(\frac{\max(p,\log n)}{nq},\frac{\max(q,\log n)}{np}\right)} \right). 
\end{eqnarray*}
\end{theorem}
The proof of Theorem \ref{HEmain} is provided in 
the Appendix. 

