&=&P_{0}\left(\frac{1}{p}\left|\operatorname{tr}(\hat{\Sigmabf}_{H}-\Sigmabf_{0})\right|>\frac{t_{3} \tau_{1}^{4}}{4}\right) + P_0 (\tilde{C}_n^c)\\
\label{Psihat1eq1}
&\leqslant& P_{0}\left(\left\|\hat{\Sigmabf}_{H}-\Sigmabf_{0}\right\|>\frac{t_{3} \tau_1^{4}}{4}\right) + P_0 (\tilde{C}_n^c)\\
\notag
&\leqslant&  2\exp \left(-\frac{\tilde{C}_{0}^2 c \tau_{1}^{4}}{4} \max (p, \log n)+\log 21 \cdot p\right) + P_0 (\tilde{C}_n^c) \\
\label{Psihat1}
%\notag
%& & \rightarrow 0 \mbox{ as } n \rightarrow \infty 
\end{eqnarray}}

\noindent
for any $\tilde{C}_{0}>\frac{2}{\tau_1^2}\sqrt{\frac{\log 21}{c}}$ and $t_{3}\geqslant \frac{4\tilde{C}_{0}}{\tau_1^4} \sqrt{\frac{\max(p,\log n)}{nq}}$ , where the inequality (\ref{Psihat1eq1}) follows from the properties of eigenvalues, and the inequality (\ref{Psihat1}) follows from (\ref{sigmacovrate}). Also, the first term in (\ref{Psi0}) satisfies
{\small
\begin{eqnarray}
\notag
P_{0}\left(T_{H}\left\|\tilde{\Psibf}_{H}-\tilde{\Psibf}_{0}\right\|>\frac{t_{3}}{2}\right) &\leqslant&
P_{0}\left(\left\|\tilde{\Psibf}_{H}-\tilde{\Psibf}_{0}\right\|>\frac{t_{3} \tau_{1}}{4}\right) + P_0 (\tilde{C}_n^c)\\
\notag
&\leqslant&  2\exp \left(-\frac{\tilde{C}_{0}^2 c \tau_{1}^{4}}{4} \max (q, \log n)+\log 21 \cdot q\right) + P_0 (\tilde{C}_n^c)\\
\label{Psihat2}
\end{eqnarray}}
for any $\tilde{C}_{0}>\frac{2}{\tau_1^2}\sqrt{\frac{\log 21}{c}}$ and any $t_{3}\geqslant \frac{4\tilde{C}_{0}}{\tau_1} \sqrt{\frac{\max(q,\log n)}{np}}$  , where the inequality (\ref{Psihat2}) follows from (\ref{tildepsicovrate}). Combining equations (\ref{Psi0}), (\ref{Psihat1}) and (\ref{Psihat2}), for any $\tilde{C}_{0}>\frac{2}{\tau_1^2}\sqrt{\frac{\log 21}{c}}$, we get 
\begin{eqnarray}
 \notag
&&P_{0}\left(||\hat{\Psibf}_{H}-\Psibf_{0}||>\frac{4\tilde{C}_{0}}{\tau_1^4} \sqrt{\max\left(\frac{\max(p,\log n)}{nq},\frac{\max(q,\log n)}{np}\right)}\right)\\
\notag
&\leqslant& 2\exp \left(-\frac{\tilde{C}_{0}^2 c \tau_{1}^{4}}{4} \max (p, \log n)+\log 21 \cdot p\right)\\
\label{Psiteq}
& & +2\exp \left(-\frac{\tilde{C}_{0}^2 c \tau_{1}^{4}}{4} \max (q, \log n)+\log 21 \cdot q\right)+ 2 P_0 (\tilde{C}_n^c)
 \end{eqnarray}

\noindent
By the construction of $\tilde{C}_n$ and Assumption H2, it follows that all the three terms on the right side of the above inequality converge to zero as $n \rightarrow \infty$. Thus, the required spectral norm convergence rate for $\hat{\Psibf}_H$ has been established. 

Note that 
\begin{eqnarray*}
\|\hat{\Omegabf}_H-\Omegabf_0\| 
&=& \|\hat{\Sigmabf}_H^{-1}-\Sigmabf_0^{-1}\|\\
&=& \|\hat{\Sigmabf}_H^{-1} (\hat{\Sigmabf}_H-\Sigmabf_0) 
\Sigmabf_0^{-1}\|\\
&\leqslant& \|\hat{\Sigmabf}_H^{-1}\| \|(\hat{\Sigmabf}_H-\Sigmabf_0)\|
\|\Sigmabf_0^{-1}\|\\
&\leqslant& \frac{\|\hat{\Sigmabf}_H^{-1}\|}{\tau_1} \|(\hat{\Sigmabf}_H-\Sigmabf_0)\|. 
\end{eqnarray*}

\noindent
The last inequality follows by Assumption H1. By (\ref{sigmacovrate}) and Assumption H1, it follows that $\|\hat{\Sigmabf}_H^{-1}\| \leqslant 2/\tau_1$ on an event with $P_0$-probability converging to $1$ as $n \rightarrow \infty$. The required spectral norm convergence rate for $\hat{\Omegabf}_H$ now follows from (\ref{sigmacovrate}). Finally, the required convergence rate for $\hat{\Gammabf}_H$ follows by leveraging (\ref{Psiteq}) and then using similar arguments as above. 

%In conclusion, from (\ref{sigmacovrate}) and (\ref{Psiteq}) we can see $\hat{\Sigmabf}_{H}$ and $\hat{\Psibf}_{H}$ are consistent in spectral norm and obtain asymptotic high-dimensional spectral norm convergence rates for both these heuristic estimators.
